// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import {
    StreamArtistRecoveredSimpleHydration as RecoveredSimple
} from "./StreamArtistRecoveredSimpleHydration.sol";
import {
    StreamArtistRecoveredHydrationCodec as RecoveredCodec
} from "./StreamArtistRecoveredHydrationCodec.sol";
import {
    StreamArtistRecoveredHydrationTypes as RecoveredRH
} from "../../interfaces/stream/artist/StreamArtistRecoveredHydrationTypes.sol";
import "./StreamArtistMultipleDelegationCollectionHydration.sol";
import "./StreamArtistMultipleCollectionHydration.sol";

import "./StreamArtistOwner.sol";
import "./StreamArtistCollaboratorHashes.sol";
import "./StreamArtistCurrentAuthorityFacts.sol";
import {
    StreamArtistOnboardingTypes as T
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";

/// @notice Sole owner of acceptance records and acceptance-domain events.
contract StreamArtistAcceptanceLifecycle is StreamArtistOwner {
    struct CollaboratorEventContext {
        bytes32 artistId;
        uint8 authorityClass;
        uint256 nonce;
        bytes32 record;
    }

    mapping(bytes32 => bytes32) public acceptanceRecord;
    mapping(bytes32 => uint64) public acceptedAt;
    mapping(bytes32 => bytes32) private _collaboratorRecords;
    event CollaboratorAccepted(
        uint16 schemaVersion,
        uint256 indexed collectionId,
        address indexed collaborator,
        bytes32 indexed collaboratorArtistId,
        uint64 bindingGeneration,
        bytes32 role,
        bytes32 shareLabelId,
        uint8 authorityClass,
        uint256 nonce,
        uint64 signedAt,
        bytes32 acceptanceRecordHash,
        bytes32 bindingHash
    );
    event ArtistBindingAccepted(
        uint16 schemaVersion,
        uint256 indexed collectionId,
        bytes32 indexed artistId,
        address indexed signer,
        uint64 bindingGeneration,
        bytes32 bindingHash,
        uint8 authorityClass,
        uint256 nonce,
        uint64 signedAt,
        bytes32 acceptanceRecordHash
    );
    constructor(
        address registry_,
        address coordinator_,
        address archive_,
        address core_,
        address manager_
    )
        StreamArtistOwner(
            registry_,
            coordinator_,
            archive_,
            keccak256("domain:acceptance_lifecycle"),
            core_,
            manager_
        )
    { }

    function recordAcceptance(
        T.ActionContext calldata c,
        uint256 collectionId,
        T.Binding calldata b,
        address signer,
        uint256 nonce
    ) external returns (bytes32 record) {
        _check(c, 2);
        if (signer != b.artistAddress) revert T.InvalidRecord();
        return _recordAcceptance(c, collectionId, b, signer, nonce, 1);
    }

    function recordAcceptanceWithAuthority(
        T.ActionContext calldata c,
        uint256 collectionId,
        T.Binding calldata b,
        R.AuthorityFact calldata authority,
        address signer,
        uint256 nonce
    ) external returns (bytes32) {
        _check(c, 2);
        StreamArtistCurrentAuthorityFacts.requirePrincipal(b.artistId, signer, authority, false);
        return _recordAcceptance(c, collectionId, b, signer, nonce, authority.authorityClass);
    }

    function _recordAcceptance(
        T.ActionContext calldata c,
        uint256 collectionId,
        T.Binding calldata b,
        address signer,
        uint256 nonce,
        uint8 authorityClass
    ) private returns (bytes32 record) {
        if (b.accepted || b.bindingHash == bytes32(0)) {
            revert T.InvalidRecord();
        }
        record = StreamArtistHashes.acceptanceRecordForAuthority(
            _environment(), collectionId, b, signer, authorityClass, nonce, _now()
        );
        bytes32 key = _consume(
            keccak256("acceptance_lifecycle.replay.record_uniqueness"),
            keccak256(abi.encode(collectionId, b.generation, uint8(1), signer)),
            record
        );
        acceptanceRecord[b.bindingHash] = record;
        acceptedAt[b.bindingHash] = _now();
        _commit(
            c,
            keccak256(abi.encode(collectionId, b, signer, nonce)),
            keccak256(abi.encode(b.bindingHash, record)),
            keccak256(abi.encode(key, record)),
            record
        );
        _native(c.operationId, record, b.artistId, collectionId);
        emit ArtistBindingAccepted(
            1,
            collectionId,
            b.artistId,
            signer,
            b.generation,
            b.bindingHash,
            authorityClass,
            nonce,
            _now(),
            record
        );
    }

    function collaboratorAcceptanceRecord(
        bytes32 bindingHash,
        address account,
        bytes32 role,
        bytes32 shareLabelId
    ) external view returns (bytes32) {
        return _collaboratorRecords[
            StreamArtistCollaboratorHashes.rowKey(bindingHash, account, role, shareLabelId)
        ];
    }

    function recordCollaboratorAcceptance(
        T.ActionContext calldata c,
        C.BindingAcceptance calldata p,
        bytes32 artistId,
        uint256 nonce
    ) external returns (bytes32 record) {
        return _recordCollaboratorAcceptance(c, p, artistId, nonce, 1);
    }

    function recordCollaboratorAcceptanceWithAuthority(
        T.ActionContext calldata c,
        C.BindingAcceptance calldata p,
        bytes32 artistId,
        uint256 nonce,
        R.AuthorityFact calldata authority
    ) external returns (bytes32) {
        _check(c, 7);
        StreamArtistCurrentAuthorityFacts.requirePrincipal(artistId, p.account, authority, false);
        return _recordCollaboratorAcceptance(c, p, artistId, nonce, authority.authorityClass);
    }

    function _recordCollaboratorAcceptance(
        T.ActionContext calldata c,
        C.BindingAcceptance calldata p,
        bytes32 artistId,
        uint256 nonce,
        uint8 authorityClass
    ) private returns (bytes32 record) {
        _check(c, 7);
        if (
            p.collectionId == 0 || p.generation == 0 || p.bindingHash == bytes32(0)
                || p.account == address(0) || artistId == bytes32(0)
        ) revert T.InvalidRecord();
        record = StreamArtistCollaboratorHashes.acceptanceRecordForAuthority(
            _environment(), p, authorityClass, nonce, _now()
        );
        bytes32 row =
            StreamArtistCollaboratorHashes.rowKey(p.bindingHash, p.account, p.role, p.shareLabelId);
        bytes32 key = _consume(
            keccak256("acceptance_lifecycle.replay.record_uniqueness"),
            keccak256(
                abi.encode(
                    p.collectionId, p.generation, uint8(2), p.account, p.role, p.shareLabelId
                )
            ),
            record
        );
        _collaboratorRecords[row] = record;
        _commit(
            c,
            keccak256(abi.encode(p, artistId, nonce)),
            keccak256(abi.encode(row, artistId, record)),
            keccak256(abi.encode(key, record)),
            record
        );
        _native(c.operationId, record, artistId, p.collectionId);
        _emitCollaboratorAcceptance(
            p, CollaboratorEventContext(artistId, authorityClass, nonce, record)
        );
    }

    function _emitCollaboratorAcceptance(
        C.BindingAcceptance calldata p,
        CollaboratorEventContext memory eventContext
    ) private {
        emit CollaboratorAccepted(
            1,
            p.collectionId,
            p.account,
            eventContext.artistId,
            p.generation,
            p.role,
            p.shareLabelId,
            eventContext.authorityClass,
            eventContext.nonce,
            _now(),
            eventContext.record,
            p.bindingHash
        );
    }

    function authorityHydrationState(AH.Query calldata q)
        external
        view
        override
        returns (bytes memory)
    {
        if (acceptanceRecord[q.bindingHash] == 0 || acceptedAt[q.bindingHash] == 0) {
            revert T.InvalidRecord();
        }
        return abi.encode(AH.Acceptance(acceptanceRecord[q.bindingHash], acceptedAt[q.bindingHash]));
    }

    function _recoveredHydrationFeatures() internal pure override returns (uint256) {
        return RecoveredRH.BINDING_GRAPH_FEATURES;
    }

    function recoveredAuthorityHydrationState(
        AH.Query calldata q,
        RecoveredRH.OwnerProvenance calldata local
    ) external view override returns (bytes memory) {
        return RecoveredSimple.exportAcceptance(acceptanceRecord, acceptedAt, q, local);
    }

    function _hydrateAuthority(AH.Query calldata q, AH.OwnerData calldata p) internal override {
        if (RecoveredCodec.isState(p.typedState, 3)) {
            if (_revision != 0 || p.nonces.length != 0) revert T.InvalidRecord();
            RecoveredSimple.importAcceptance(acceptanceRecord, acceptedAt, q, p.typedState);
            return;
        }
        if (StreamArtistDelegationHydrationCodec.tagged(p.typedState, MD.ACCEPTANCE)) {
            if (p.nonces.length != 0) revert T.InvalidRecord();
            StreamArtistMultipleDelegationCollectionHydration.acceptances(
                acceptanceRecord, acceptedAt, p.typedState
            );
            return;
        }
        if (StreamArtistMultipleHydrationCodec.isState(p.typedState)) {
            if (p.nonces.length != 0) revert T.InvalidRecord();
            StreamArtistMultipleCollectionHydration.acceptances(
                acceptanceRecord, acceptedAt, p.typedState
            );
            return;
        }
        AH.Acceptance memory a = abi.decode(p.typedState, (AH.Acceptance));
        if (acceptanceRecord[q.bindingHash] != 0 || p.nonces.length != 0) revert T.InvalidRecord();
        acceptanceRecord[q.bindingHash] = a.record;
        acceptedAt[q.bindingHash] = a.acceptedAt;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "./StreamArtistDelegationIdentityHydration.sol";
import "./StreamArtistMultipleIdentityHydration.sol";
import "./StreamArtistHistoryState.sol";
import "./StreamArtistHydrationGuards.sol";
import "./StreamArtistMultipleDelegationIdentityHydration.sol";
import "../../interfaces/stream/artist/IStreamArtistDelegationAuthorityHydration.sol";
import {
    IStreamArtistAuthorityHydrationOwner
} from "../../interfaces/stream/artist/IStreamArtistAuthorityHydration.sol";
import {
    IStreamArtistEntropyFindingHydrationOwner
} from "../../interfaces/stream/artist/IStreamArtistEntropyFindingHydration.sol";

/// @notice Fixed transport for original Identity hydration exports and additive imports.
library StreamArtistAdditiveIdentityHydration {
    function exportEncoded(
        StreamArtistIdentityState.State storage identity,
        StreamArtistDelegationState.State storage grants,
        StreamArtistIdentityRevisionState.State storage revisions,
        StreamArtistEstateState.State storage estate,
        StreamArtistDormancyState.State storage dormancy,
        StreamArtistUnavailabilityState.State storage findings,
        bytes calldata encoded
    ) public view returns (bytes memory) {
        if (
            bytes4(encoded[:4])
                == IStreamArtistAuthorityHydrationOwner.authorityHydrationState.selector
        ) {
            return StreamArtistIdentityHydration.exportEncoded(
                identity, estate, dormancy, findings, encoded[4:]
            );
        }
        if (
            bytes4(encoded[:4])
                == IStreamArtistEntropyFindingHydrationOwner.authorityEntropyFindingHydrationState
                .selector
        ) {
            return StreamArtistIdentityHydration.exportFindingEncoded(
                identity, estate, dormancy, findings, encoded[4:]
            );
        }
        if (
            bytes4(encoded[:4])
                == IStreamArtistDelegationHydrationOwner.authorityDelegationHydrationState.selector
        ) {
            return StreamArtistDelegationIdentityHydration.exportEncoded(
                identity, grants, revisions, estate, dormancy, findings, encoded[4:]
            );
        }
        if (
            bytes4(encoded[:4])
                != IStreamArtistMultipleHydrationIdentity.authorityLivingIdentityHydrationState
                .selector
        ) revert T.UnsupportedProfile();
        return StreamArtistMultipleIdentityHydration.exportEncoded(
            identity, estate, dormancy, findings, encoded[4:]
        );
    }

    function importEncoded(
        StreamArtistIdentityState.State storage identity,
        StreamArtistDelegationState.State storage grants,
        StreamArtistIdentityRevisionState.State storage revisions,
        StreamArtistEstateState.State storage estate,
        StreamArtistDormancyState.State storage dormancy,
        StreamArtistUnavailabilityState.State storage findings,
        bytes calldata encoded
    ) public {
        (, AH.Query memory q, AH.OwnerData memory data,) =
            abi.decode(encoded, (T.ActionContext, AH.Query, AH.OwnerData, bytes32));
        if (StreamArtistDelegationHydrationCodec.tagged(data.typedState, MD.IDENTITY)) {
            StreamArtistMultipleDelegationIdentityHydration.importEncoded(
                identity, grants, revisions, estate, dormancy, findings, encoded
            );
            return;
        }
        if (StreamArtistDelegationHydrationCodec.tagged(data.typedState, DH.IDENTITY)) {
            StreamArtistDelegationIdentityHydration.importEncoded(
                identity, grants, revisions, estate, dormancy, findings, encoded
            );
            StreamArtistHistoryState.activate(
                q.artistId, q.collectionId, StreamArtistHydrationGuards.commitment()
            );
            return;
        }
        if (StreamArtistMultipleHydrationCodec.isState(data.typedState)) {
            StreamArtistMultipleIdentityHydration.importEncoded(
                identity, estate, dormancy, findings, encoded
            );
            return;
        }
        StreamArtistIdentityHydration.importEncoded(identity, estate, dormancy, findings, encoded);
        StreamArtistHistoryState.activate(
            q.artistId, q.collectionId, StreamArtistHydrationGuards.commitment()
        );
    }
}

