pragma solidity ^0.8.19;
import "./StreamArtistAuthorityCheckpoint.sol";
import "./StreamArtistIdentityState.sol";
import "./StreamArtistCollaboratorHashes.sol";

/// @notice Linked registration mechanics over Identity-owned original state and appended account replay index.
/// @dev Identity retains typed caller/snapshot guards and makes one semantic commit for all mutations.
library StreamArtistCollaboratorIdentityState {
    using StreamArtistNonceAvailability for StreamArtistNonceAvailability.Index;

    struct State {
        mapping(address => StreamArtistNonceAvailability.Index) available;
    }

    function nonceState(
        State storage accounts,
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistIdentityState.OwnerContext memory o,
        address account,
        uint256 nonce
    ) public view returns (bool, uint256) {
        (, uint256 hint) = accounts.available[account].firstUnused();
        return (
            replay[_key(
                        o,
                        keccak256("identity_authority.replay.collaborator_account_nonce"),
                        keccak256(abi.encode(account, nonce))
                    )].status != 0,
            hint
        );
    }

    function register(
        StreamArtistIdentityState.State storage identity,
        State storage accounts,
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistIdentityState.OwnerContext memory o,
        T.ActionContext memory c,
        C.IdentityProposal memory p,
        T.Authorization memory a,
        T.SignerApproval memory proof,
        bytes memory document,
        string memory displayName
    ) public returns (StreamArtistIdentityState.Mutation memory m) {
        bytes32 digest = StreamArtistCollaboratorHashes.identityDigest(
                o.environment, p.account, p.identityRecordHash, a
            );
        if (proof.signer != p.account || proof.digest != digest) revert T.InvalidSignature();
        (bool available, uint256 hint) = accounts.available[p.account].firstUnused();
        if (!available || (proof.direct && a.nonce != hint)) revert T.InvalidRecord();
        bytes32 nonceKey = _key(
            o,
            keccak256("identity_authority.replay.collaborator_account_nonce"),
            keccak256(abi.encode(p.account, a.nonce))
        );
        bytes32 digestKey = _key(
            o,
            keccak256("identity_authority.replay.collaborator_account_digest"),
            keccak256(abi.encode(p.account, digest))
        );
        if (replay[nonceKey].status != 0) revert T.Replay(nonceKey);
        if (replay[digestKey].status != 0) revert T.Replay(digestKey);
        replay[nonceKey] = T.ReplayCell(digest, o.revision + 1, 1, 2);
        StreamArtistAuthorityCheckpoint.noteReplay(nonceKey, replay[nonceKey]);
        replay[digestKey] = T.ReplayCell(digest, o.revision + 1, 1, 2);
        StreamArtistAuthorityCheckpoint.noteReplay(digestKey, replay[digestKey]);
        bytes32 accountDelta = accounts.available[p.account].consumeTagged(
            a.nonce, 3, bytes32(uint256(uint160(p.account)))
        );
        StreamArtistIdentityState.Mutation memory registration = StreamArtistIdentityState.register(
            identity,
            replay,
            o,
            p.account,
            p.identityRecordHash,
            p.identityRecordURI,
            document,
            displayName
        );
        bytes32 id = registration.record;
        // A direct registration uses the persistent account hint; this fresh identity
        // still consumes that exact nonce and then derives its own independent hint.
        if (proof.direct) identity.identities[id].nonceHint = hint;
        StreamArtistIdentityState.Mutation memory authorization = StreamArtistIdentityState.authorize(
            identity, replay, o, c, id, a, proof, digest, id, p.account
        );
        bytes32 uniqueKey = _key(o, keccak256("identity_authority.replay.identity_uniqueness"), id);
        if (replay[uniqueKey].status != 0) revert T.Replay(uniqueKey);
        replay[uniqueKey] = T.ReplayCell(id, o.revision + 1, 1, 2);
        StreamArtistAuthorityCheckpoint.noteReplay(uniqueKey, replay[uniqueKey]);
        m = StreamArtistIdentityState.Mutation(
            id,
            keccak256(abi.encode(registration.action, authorization.action, p)),
            keccak256(abi.encode(registration.state, authorization.state, accountDelta)),
            keccak256(
                abi.encode(
                    registration.replay,
                    authorization.replay,
                    nonceKey,
                    digestKey,
                    digest,
                    accountDelta,
                    uniqueKey,
                    id
                )
            )
        );
    }

    function _key(StreamArtistIdentityState.OwnerContext memory o, bytes32 surface, bytes32 scope)
        private
        view
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_OWNER_REPLAY_KEY_V2"),
                o.environment.chainId,
                o.environment.registry,
                o.coordinator,
                o.archive,
                address(this),
                o.domain,
                surface,
                scope
            )
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import {
    StreamArtistRecoveredSimpleHydration as RecoveredSimple
} from "./StreamArtistRecoveredSimpleHydration.sol";
import {
    StreamArtistRecoveredHydrationCodec as RecoveredCodec
} from "./StreamArtistRecoveredHydrationCodec.sol";
import {
    StreamArtistRecoveredHydrationTypes as RecoveredRH
} from "../../interfaces/stream/artist/StreamArtistRecoveredHydrationTypes.sol";

import "./StreamArtistOwner.sol";
import "./StreamArtistCollaboratorHashes.sol";

/// @notice Sole owner of collaborator identity proposals and acceptance-ratified account/identity joins.
/// @dev Full immutable binding terms live in Binding; acceptance records live in Acceptance.
contract StreamArtistCollaboratorLifecycle is StreamArtistOwner {
    mapping(bytes32 => C.IdentityProposalState) private _identityProposals;
    mapping(bytes32 => C.Join) private _joins;
    mapping(bytes32 => uint32) private _acceptedCounts;
    mapping(bytes32 => mapping(address => bool)) private _identityLinks;
    event CollaboratorIdentityProposed(
        uint16 schemaVersion,
        address indexed account,
        bytes32 identityRecordHash,
        string identityRecordURI,
        address proposer,
        bytes32 reasonHash,
        string reasonURI
    );
    constructor(
        address registry_,
        address coordinator_,
        address archive_,
        address core_,
        address manager_
    )
        StreamArtistOwner(
            registry_,
            coordinator_,
            archive_,
            keccak256("domain:collaborator_lifecycle"),
            core_,
            manager_
        )
    { }

    /// @notice Empty-profile bootstrap compatibility sentinel, not the live collection inventory.
    /// @dev Use the facade's generation-scoped collaboratorCount/collaboratorAt reads for actual rows.
    function collaboratorSetHash() external pure returns (bytes32) {
        return StreamArtistHashes.emptyCollaborators();
    }

    /// @notice Empty-profile bootstrap compatibility sentinel; actual rows are generation-scoped.
    function collaboratorCount() external pure returns (uint256) {
        return 0;
    }

    function identityProposal(address account, bytes32 identityRecordHash)
        external
        view
        returns (C.IdentityProposalState memory)
    {
        return _identityProposals[keccak256(abi.encode(account, identityRecordHash))];
    }

    function proposeIdentity(T.ActionContext calldata c, C.IdentityProposal calldata p)
        external
        returns (bytes32 hash)
    {
        _check(c, 5);
        if (
            p.account == address(0) || p.identityRecordHash == bytes32(0)
                || p.reasonHash == bytes32(0)
        ) {
            revert T.InvalidRecord();
        }
        if (bytes(p.identityRecordURI).length > 2048) {
            revert T.BoundExceeded(bytes(p.identityRecordURI).length, 2048);
        }
        if (bytes(p.reasonURI).length > 2048) {
            revert T.BoundExceeded(bytes(p.reasonURI).length, 2048);
        }
        bytes32 scope = keccak256(abi.encode(p.account, p.identityRecordHash));
        hash = StreamArtistCollaboratorHashes.proposalHash(_environment(), p, c.actor);
        bytes32 replay = _consume(
            keccak256("collaborator_lifecycle.replay.collaborator_proposal_key"), scope, hash
        );
        _identityProposals[scope] = C.IdentityProposalState(p, c.actor, hash, bytes32(0));
        _commit(
            c,
            keccak256(abi.encode(p)),
            keccak256(abi.encode(scope, _identityProposals[scope])),
            keccak256(abi.encode(replay, hash)),
            bytes32(0)
        );
        emit CollaboratorIdentityProposed(
            1,
            p.account,
            p.identityRecordHash,
            p.identityRecordURI,
            c.actor,
            p.reasonHash,
            p.reasonURI
        );
    }

    function completeIdentity(
        T.ActionContext calldata c,
        address account,
        bytes32 identityRecordHash,
        bytes32 artistId
    ) external {
        _check(c, 6);
        bytes32 scope = keccak256(abi.encode(account, identityRecordHash));
        C.IdentityProposalState storage item = _identityProposals[scope];
        if (
            item.proposalHash == bytes32(0) || item.acceptedArtistId != bytes32(0)
                || artistId == bytes32(0)
        ) revert T.InvalidRecord();
        item.acceptedArtistId = artistId;
        _commit(
            c,
            keccak256(abi.encode(account, identityRecordHash, artistId)),
            keccak256(abi.encode(scope, item)),
            bytes32(0),
            bytes32(0)
        );
    }

    function recordRowAcceptance(
        T.ActionContext calldata c,
        C.BindingAcceptance calldata p,
        bytes32 artistId,
        bytes32 record
    ) external returns (uint32 count) {
        _check(c, 7);
        bytes32 key =
            StreamArtistCollaboratorHashes.rowKey(p.bindingHash, p.account, p.role, p.shareLabelId);
        if (
            p.bindingHash == bytes32(0) || artistId == bytes32(0) || record == bytes32(0)
                || _joins[key].artistId != bytes32(0)
        ) revert T.InvalidRecord();
        count = _acceptedCounts[p.bindingHash] + 1;
        if (count > 32) revert T.BoundExceeded(count, 32);
        _joins[key] = C.Join(artistId, record);
        _acceptedCounts[p.bindingHash] = count;
        _identityLinks[artistId][p.account] = true;
        _commit(
            c,
            keccak256(abi.encode(p, artistId, record)),
            keccak256(abi.encode(key, _joins[key], count, artistId, p.account, true)),
            bytes32(0),
            bytes32(0)
        );
    }

    function acceptedRow(bytes32 bindingHash, address account, bytes32 role, bytes32 shareLabelId)
        external
        view
        returns (C.Join memory)
    {
        return
            _joins[StreamArtistCollaboratorHashes.rowKey(bindingHash, account, role, shareLabelId)];
    }

    function acceptedCount(bytes32 bindingHash) external view returns (uint32) {
        return _acceptedCounts[bindingHash];
    }

    function identityLinked(bytes32 artistId, address account) external view returns (bool) {
        return _identityLinks[artistId][account];
    }

    function _recoveredHydrationFeatures() internal pure override returns (uint256) {
        return RecoveredRH.BINDING_GRAPH_FEATURES;
    }

    function recoveredAuthorityHydrationState(
        AH.Query calldata q,
        RecoveredRH.OwnerProvenance calldata local
    ) external view override returns (bytes memory) {
        return RecoveredSimple.exportCollaborator(q, local);
    }

    function _hydrateAuthority(AH.Query calldata q, AH.OwnerData calldata p) internal override {
        if (RecoveredCodec.isState(p.typedState, 1)) {
            // All collaborator writes advance this counter even when they create no native row.
            if (_revision != 0 || p.nonces.length != 0) revert T.InvalidRecord();
            RecoveredSimple.importCollaborator(q, p.typedState);
            return;
        }
        super._hydrateAuthority(q, p);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "../../interfaces/stream/artist/IStreamArtistCurrentCollaboratorOwner.sol";
import "./StreamArtistAuthorityPolicy.sol";
import "./StreamArtistBindingOperations.sol";
import "./StreamArtistCollaboratorHashes.sol";
import "../../interfaces/stream/artist/IStreamArtistCollaboratorRecordsOwner.sol";
import "../../interfaces/stream/artist/IStreamArtistCollaboratorBindingOwner.sol";
import "../../interfaces/stream/artist/IStreamArtistCollaboratorIdentityOwner.sol";
import "../../interfaces/stream/artist/IStreamArtistCollaboratorAcceptanceOwner.sol";
import "../../interfaces/stream/artist/IStreamArtistCollaboratorAttributionOwner.sol";
import "../../interfaces/stream/governance/IStreamRoleRegistry.sol";

/// @notice Typed collaborator recipes behind the Coordinator's fixed ingress authentication and lock.
library StreamArtistCollaboratorOperations {
    function proposeIdentity(
        D.CoordinatorContext memory x,
        address actor,
        C.IdentityProposal memory p
    ) public returns (bytes32 proposalHash) {
        bytes32 role = keccak256("ROLE_ARTIST_REGISTRY_ADMIN");
        if (!IStreamRoleRegistry(x.suite.roleRegistry).hasRole(role, actor)) {
            revert T.Unauthorized(actor);
        }
        (bytes32 roleHash, uint64 revision) =
            IStreamRoleRegistry(x.suite.roleRegistry).roleMutationState(role);
        T.Snapshot[7] memory before_ = _snapshots(x, 5);
        if (IStreamArtistIdentityOwner(x.suite.owners[2]).activeIdentity(p.account) != bytes32(0)) {
            revert T.AddressAlreadyRegistered(p.account);
        }
        proposalHash = IStreamArtistCollaboratorRecordsOwner(x.suite.owners[1])
            .proposeIdentity(T.ActionContext(5, actor, before_[1]), p);
        _archive(x, 5, actor, proposalHash, before_, abi.encode(p, roleHash, revision));
    }

    function acceptIdentity(
        D.CoordinatorContext memory x,
        address actor,
        address account,
        bytes32 documentHash,
        T.Authorization memory a,
        bytes memory document,
        string memory displayName
    ) public returns (bytes32 artistId) {
        T.Snapshot[7] memory before_ = _snapshots(x, 6);
        C.IdentityProposalState memory proposal = IStreamArtistCollaboratorRecordsOwner(
                x.suite.owners[1]
            ).identityProposal(account, documentHash);
        if (
            proposal.proposalHash == bytes32(0) || proposal.acceptedArtistId != bytes32(0)
                || proposal.proposal.account != account
                || proposal.proposal.identityRecordHash != documentHash
        ) revert T.InvalidRecord();
        IStreamArtistIdentityOwner identity = IStreamArtistIdentityOwner(x.suite.owners[2]);
        if (identity.activeIdentity(account) != bytes32(0)) {
            revert T.AddressAlreadyRegistered(account);
        }
        uint256 allocationNonce = identity.nextRegistrationNonce();
        T.SignerApproval memory proof = _verify(
            x,
            actor,
            account,
            StreamArtistCollaboratorHashes.identityDigest(
                _environment(x), account, documentHash, a
            ),
            a.signature
        );
        artistId = IStreamArtistCollaboratorIdentityOwner(x.suite.owners[2])
            .registerCollaboratorIdentity(
                T.ActionContext(6, actor, before_[2]),
                proposal.proposal,
                a,
                proof,
                document,
                displayName
            );
        if (
            artistId
                != StreamArtistHashes.identity(
                    _environment(x), account, documentHash, allocationNonce
                )
        ) revert T.InvalidRecord();
        IStreamArtistCollaboratorRecordsOwner(x.suite.owners[1])
            .completeIdentity(
                T.ActionContext(6, actor, before_[1]), account, documentHash, artistId
            );
        _archive(
            x,
            6,
            actor,
            artistId,
            before_,
            abi.encode(proposal, a, proof, document, displayName, allocationNonce)
        );
    }

    function acceptRow(
        D.CoordinatorContext memory x,
        address actor,
        C.BindingAcceptance memory p,
        T.Authorization memory a
    ) public returns (bytes32 record) {
        T.Snapshot[7] memory before_ = _snapshots(x, 7);
        T.Binding memory b = IStreamArtistBindingOwner(x.suite.owners[0]).binding(p.collectionId);
        (uint8 state, uint64 generation) =
            IStreamArtistAttributionOwner(x.suite.owners[4]).attributionState(p.collectionId);
        if (
            b.accepted || state != 1 || generation != b.generation || p.generation != b.generation
                || p.bindingHash != b.bindingHash || b.bindingHash == bytes32(0)
                || !IStreamCoreCollectionView(x.suite.core).collectionExists(p.collectionId)
        ) revert T.InvalidAttribution(p.collectionId);
        IStreamArtistCollaboratorBindingOwner bindingOwner =
            IStreamArtistCollaboratorBindingOwner(x.suite.owners[0]);
        C.BindingTerms memory terms = bindingOwner.bindingTerms(p.collectionId, p.generation);
        bool found;
        for (uint256 i; i < terms.count; ++i) {
            T.CollaboratorRecord memory row =
                bindingOwner.collaboratorTerm(p.collectionId, p.generation, i);
            if (
                row.account == p.account && row.role == p.role && row.shareLabelId == p.shareLabelId
            ) {
                found = true;
                break;
            }
        }
        if (!found) revert T.InvalidRecord();
        IStreamArtistCollaboratorRecordsOwner collaborators =
            IStreamArtistCollaboratorRecordsOwner(x.suite.owners[1]);
        if (
            collaborators.acceptedRow(p.bindingHash, p.account, p.role, p.shareLabelId).artistId
                != bytes32(0)
        ) revert T.InvalidRecord();
        uint32 priorCount = collaborators.acceptedCount(p.bindingHash);
        bytes32 primaryRecord =
            IStreamArtistAcceptanceOwner(x.suite.owners[3]).acceptanceRecord(p.bindingHash);
        IStreamArtistIdentityOwner identity = IStreamArtistIdentityOwner(x.suite.owners[2]);
        bytes32 artistId = identity.activeIdentity(p.account);
        (address signer, uint8 auth, uint8 status,) = identity.authorityState(artistId);
        if (
            artistId == bytes32(0) || signer != p.account
                || !StreamArtistAuthorityPolicy.ordinary(auth, status, false)
        ) {
            revert T.InvalidIdentity(artistId);
        }
        T.SignerApproval memory proof = _verify(
            x,
            actor,
            p.account,
            StreamArtistCollaboratorHashes.acceptanceDigest(_environment(x), p, a),
            a.signature
        );
        record = IStreamArtistCollaboratorIdentityOwner(x.suite.owners[2])
            .consumeCollaboratorAcceptance(
                T.ActionContext(7, actor, before_[2]), p, artistId, a, proof
            );
        bytes32 actual = IStreamArtistCurrentCollaboratorAcceptanceOwner(x.suite.owners[3])
            .recordCollaboratorAcceptanceWithAuthority(
                T.ActionContext(7, actor, before_[3]),
                p,
                artistId,
                a.nonce,
                R.AuthorityFact(artistId, signer, auth, status)
            );
        if (record != actual) revert T.InvalidRecord();
        uint32 count = collaborators.recordRowAcceptance(
            T.ActionContext(7, actor, before_[1]), p, artistId, record
        );
        if (count != priorCount + 1 || count > terms.count) revert T.InvalidRecord();
        bool complete = count == terms.count && primaryRecord != bytes32(0);
        if (complete) {
            bindingOwner.completeCollaboratorBinding(
                T.ActionContext(7, actor, before_[0]), p.collectionId, p.bindingHash, record
            );
            IStreamArtistCurrentCollaboratorAttributionOwner(x.suite.owners[4])
                .completeCollaboratorBindingWithAuthority(
                    T.ActionContext(7, actor, before_[4]),
                    p.collectionId,
                    b,
                    record,
                    p.account,
                    R.AuthorityFact(artistId, signer, auth, status)
                );
        }
        _archive(
            x,
            7,
            actor,
            record,
            before_,
            abi.encode(b, p, artistId, a, proof, terms, priorCount, count, primaryRecord, complete)
        );
    }

    function _verify(
        D.CoordinatorContext memory x,
        address actor,
        address signer,
        bytes32 digest,
        bytes memory signature
    ) private view returns (T.SignerApproval memory) {
        if (actor == address(0) || signer == address(0)) {
            revert T.InvalidSignature();
        }
        bool direct = actor == signer && signature.length == 0;
        if (!direct) {
            (uint256 cap,, uint8 failure, uint64 revision) = IStreamGasParameterHost(
                    x.suite.registry
                ).gasParameterInfo(keccak256("6529STREAM_GGP_ARTIST_ERC1271_VERIFY_GAS"));
            if (
                revision == 0 || failure != 2
                    || !StreamArtistRegistryValidatorBase(x.suite.validator)
                        .validateSignerProof(signer, digest, signature, cap)
            ) revert T.InvalidSignature();
        }
        return T.SignerApproval(signer, digest, direct);
    }

    function _environment(D.CoordinatorContext memory x)
        private
        view
        returns (StreamArtistHashes.Environment memory)
    {
        return StreamArtistHashes.Environment(
            block.chainid, x.suite.registry, x.suite.core, x.suite.mintManager
        );
    }

    function _snapshots(D.CoordinatorContext memory x, uint16 op)
        private
        view
        returns (T.Snapshot[7] memory result)
    {
        uint256 mask = op == 7 ? 0x1f : 0x06;
        for (uint256 i; i < 7; ++i) {
            if ((mask & (1 << i)) != 0) {
                result[i] = IStreamArtistOwner(x.suite.owners[i]).ownerStateSnapshotV2();
            }
        }
    }

    function _archive(
        D.CoordinatorContext memory x,
        uint16 op,
        address actor,
        bytes32 reference_,
        T.Snapshot[7] memory before_,
        bytes memory payload
    ) private {
        bytes32 id = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_ONBOARDING_OPERATION_EVIDENCE_V1"),
                block.chainid,
                x.suite.registry,
                address(this),
                op,
                actor,
                reference_
            )
        );
        bytes memory evidence = abi.encode(
            uint16(1),
            x.configurationHash,
            op,
            actor,
            reference_,
            before_,
            _snapshots(x, op),
            payload
        );
        (bytes32 hash,, bool appended) =
            IStreamArtistArchiveV2(x.suite.archive).appendArtistEvidenceV2(id, 1, evidence);
        if (!appended || hash != keccak256(evidence)) revert T.InvalidRecord();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import {
    StreamArtistRecoveredCollectionHydration
} from "./StreamArtistRecoveredCollectionHydration.sol";
import { StreamArtistRecoveredHydrationCodec } from "./StreamArtistRecoveredHydrationCodec.sol";
import {
    StreamArtistRecoveredContentConsentHydration as RecoveredContent
} from "./StreamArtistRecoveredContentConsentHydration.sol";
import {
    StreamArtistRecoveredEconomicsHydration
} from "./StreamArtistRecoveredEconomicsHydration.sol";
import {
    StreamArtistRecoveredDelegatedConsentHydration
} from "./StreamArtistRecoveredDelegatedConsentHydration.sol";
import "./StreamArtistMultipleRecordsConsentImport.sol";
import "./StreamArtistMultipleDelegationCollectionHydration.sol";
import "./StreamArtistMultipleCollectionHydration.sol";
import "./StreamArtistDelegationCollectionHydration.sol";

import "./StreamArtistContentHydration.sol";
import "./StreamArtistEconomicsHydration.sol";
import { StreamArtistPayloadStore } from "./StreamArtistPayloadStore.sol";

import "./StreamArtistEconomicsHashes.sol";
import "./StreamArtistConsentState.sol";
import {
    IStreamArtistEconomicsEvidence
} from "../../interfaces/stream/artist/IStreamArtistEconomicsEvidence.sol";
import "./StreamArtistCurrentAuthorityFacts.sol";
import "./StreamArtistContentHashes.sol";
import "../../interfaces/stream/artist/IStreamArtistContentOwner.sol";

import "./StreamArtistConsentStorage.sol";
import "./StreamArtistConsentWriterExtension.sol";
import "./StreamArtistSanctionState.sol";
import "./StreamArtistConsentReadEncoding.sol";
import "../../interfaces/stream/artist/IStreamArtistSanctionConfirmation.sol";
import {
    StreamArtistOnboardingTypes as T
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";

/// @notice Sole owner of the onboarding policy/economics/content-ratification records.
/// @dev State remains in this owner; the constructor-fixed writer executes its explicit callbacks.
contract StreamArtistConsentFinalityLifecycle is
    StreamArtistConsentStorage,
    IStreamArtistEconomicsEvidence,
    IStreamArtistSanctionOwner,
    IStreamArtistRecoveryApprovalOwner
{
    // Retain the published host error ABI after callback implementation extraction.
    error BoundExceeded(uint256 actual, uint256 maximum);
    error InvalidRecord();
    error Replay(bytes32 replayKey);
    address public immutable consentWriterExtension;

    function recordPreimageBytes(bytes32 hash) external view returns (bytes memory) {
        return StreamArtistPayloadStore.recordBytes(hash);
    }

    function storedPayloadCount() external view returns (uint256) {
        return StreamArtistPayloadStore.count();
    }

    function storedPayloadAt(uint256 index) external view returns (address, bytes32, bytes32) {
        return StreamArtistPayloadStore.at(index);
    }

    function recordRecoveryApproval(
        T.ActionContext calldata c,
        T.Binding calldata b,
        Recovery.ApprovalRecord calldata r,
        R.AuthorityFact calldata authority,
        Approval.Admission calldata admission
    ) external returns (bytes32) {
        _forwardConsentWriter();
    }

    function recoveryApprovalRecord(bytes32 recordHash)
        external
        view
        returns (Recovery.ApprovalRecord memory, Approval.Admission memory)
    {
        _returnSanction(
            StreamArtistRecoveryApprovalState.recordEncodedRead(_recoveryApprovals, recordHash)
        );
    }

    function recoveryApprovalForAssociation(
        bytes32 artistId,
        uint64 generation,
        bytes32 bindingHash,
        Recovery.ApprovalTerms calldata p
    ) external view returns (bytes32) {
        return _recoveryApprovals.associationRecords[
            StreamArtistRecoveryApprovalState.associationKey(artistId, generation, bindingHash, p)
        ];
    }

    function consumeSanctionFinalization(
        T.ActionContext calldata c,
        T.Binding calldata b,
        Confirmation.Transition calldata p
    ) external returns (bytes32) {
        _forwardConsentWriter();
    }

    function recordSanction(
        T.ActionContext calldata c,
        T.Binding calldata b,
        S.Record calldata r,
        R.AuthorityFact calldata authority,
        address finalityRegistry,
        bytes calldata ceremony,
        bytes calldata signature
    ) external returns (bytes32) {
        _forwardConsentWriter();
    }

    /// @notice Direct immutable record lookup; current binding/scope admission remains the reader's duty.
    function staticSanctionRecord(bytes32 associationKey)
        external
        view
        returns (bytes32, S.Record memory)
    {
        bytes32 hash = _sanctions.latest[associationKey];
        return (hash, _sanctions.records[hash]);
    }

    function sanctionRecord(bytes32 recordHash) external view returns (S.Record memory) {
        _returnSanction(StreamArtistSanctionState.recordEncodedRead(_sanctions, recordHash));
    }

    function sanctionArchiveBytes(bytes32 recordHash) external view returns (bytes memory) {
        _returnSanction(StreamArtistSanctionState.archiveEncodedRead(_sanctions, recordHash));
    }

    function sanctionArchiveFacts(bytes32 recordHash)
        external
        view
        returns (IStreamArtistSanctionArchiveFacts.Facts memory)
    {
        _returnSanction(StreamArtistSanctionState.factsEncodedRead(_sanctions, recordHash));
    }

    function _returnSanction(bytes memory result) private pure {
        assembly ("memory-safe") { return(add(result, 32), mload(result)) }
    }

    function sanctionForAssociation(
        bytes32 artistId,
        uint64 generation,
        bytes32 bindingHash,
        uint8 scopeType,
        uint256 collectionId,
        uint256 tokenId,
        bytes32 scopeId
    ) external view returns (bytes32) {
        S.Terms memory p = S.Terms(scopeType, collectionId, tokenId, scopeId, 0, 0);
        return _sanctions.latest[
            StreamArtistSanctionState.associationKey(artistId, generation, bindingHash, p)
        ];
    }

    function recordSaleConsent(
        T.ActionContext calldata c,
        T.Binding calldata b,
