    function authorityReadinessHydrationState(
        AH.Query calldata q,
        T.EconomicsConsent[] calldata economics
    ) external view returns (bytes memory) {
        bytes memory inner =
            StreamArtistEconomicsHydration.exportState(
                _policies,
                _economics,
                _associatedEconomicsRecords,
                _economicsAssociations,
                _recordDelegation,
                q,
                economics
            );
        return StreamArtistContentHydration.exportState(
            _ratifications, _ratificationRecords, _contentConsents, _latestContentConsent, q, inner
        );
    }

    function _recoveredHydrationFeatures() internal pure override returns (uint256) {
        return StreamArtistRecoveredHydrationTypes.BINDING_GRAPH_FEATURES;
    }

    function recoveredAuthorityHydrationState(
        AH.Query calldata q,
        StreamArtistRecoveredHydrationTypes.OwnerProvenance calldata provenance
    ) external view override returns (bytes memory) {
        return StreamArtistRecoveredCollectionHydration.exportPolicies(
            _policies, _recordDelegation, q, provenance
        );
    }

    function _hydrateAuthority(AH.Query calldata q, AH.OwnerData calldata p) internal override {
        if (StreamArtistRecoveredHydrationCodec.isState(p.typedState, 6)) {
            if (_revision != 0 || p.nonces.length != 0) revert T.InvalidRecord();
            if (RecoveredContent.selected(p.typedState)) {
                RecoveredContent.Bundle memory imported = RecoveredContent.importState(
                    _policies,
                    _economics,
                    _associatedEconomicsRecords,
                    _economicsAssociations,
                    _recordDelegation,
                    _saleRecords,
                    _latestSaleConsents,
                    q,
                    p.typedState
                );
                RecoveredContent.importContent(
                    _contentConsents,
                    _latestContentConsent,
                    _royaltyFreezes,
                    _contentFreezes,
                    _latestContentFreeze,
                    _recordDelegation,
                    imported
                );
                return;
            }
            if (StreamArtistRecoveredDelegatedConsentHydration.selected(p.typedState)) {
                StreamArtistRecoveredDelegatedConsentHydration.importState(
                    _policies,
                    _economics,
                    _associatedEconomicsRecords,
                    _economicsAssociations,
                    _recordDelegation,
                    _saleRecords,
                    _latestSaleConsents,
                    q,
                    p.typedState
                );
                return;
            }
            StreamArtistRecoveredEconomicsHydration.importEither(
                _policies,
                _economics,
                _associatedEconomicsRecords,
                _economicsAssociations,
                _recordDelegation,
                q,
                p.typedState
            );
            return;
        }
        if (StreamArtistDelegationHydrationCodec.tagged(p.typedState, MR.CONSENT)) {
            if (p.nonces.length != 0) revert T.InvalidRecord();
            bytes memory delegation = StreamArtistMultipleRecordsConsentImport.economics(
                _policies,
                _economics,
                _associatedEconomicsRecords,
                _economicsAssociations,
                p.typedState
            );
            StreamArtistMultipleRecordsConsentImport.content(
                _ratifications,
                _ratificationRecords,
                _contentConsents,
                _latestContentConsent,
                p.typedState
            );
            StreamArtistMultipleDelegationCollectionHydration.consents(
                _policies, _recordDelegation, _saleRecords, _latestSaleConsents, delegation
            );
            return;
        }
        if (StreamArtistDelegationHydrationCodec.tagged(p.typedState, MD.CONSENT)) {
            if (p.nonces.length != 0) revert T.InvalidRecord();
            StreamArtistMultipleDelegationCollectionHydration.consents(
                _policies, _recordDelegation, _saleRecords, _latestSaleConsents, p.typedState
            );
            return;
        }
        if (StreamArtistDelegationHydrationCodec.tagged(p.typedState, DH.CONSENT)) {
            if (p.nonces.length != 0) revert T.InvalidRecord();
            StreamArtistDelegationCollectionHydration.importConsent(
                _policies, _recordDelegation, _saleRecords, _latestSaleConsents, q, p.typedState
            );
            return;
        }
        if (StreamArtistMultipleHydrationCodec.isState(p.typedState)) {
            if (p.nonces.length != 0) revert T.InvalidRecord();
            StreamArtistMultipleCollectionHydration.policies(_policies, p.typedState);
            return;
        }
        if (StreamArtistContentHydration.isState(p.typedState)) {
            if (p.nonces.length != 0) revert T.InvalidRecord();
            bytes memory inner = StreamArtistContentHydration.importState(
                _ratifications,
                _ratificationRecords,
                _contentConsents,
                _latestContentConsent,
                q,
                p.typedState
            );
            StreamArtistEconomicsHydration.importState(
                _policies, _economics, _associatedEconomicsRecords, _economicsAssociations, q, inner
            );
            return;
        }
        if (StreamArtistEconomicsHydration.isState(p.typedState)) {
            if (p.nonces.length != 0) revert T.InvalidRecord();
            StreamArtistEconomicsHydration.importState(
                _policies,
                _economics,
                _associatedEconomicsRecords,
                _economicsAssociations,
                q,
                p.typedState
            );
            return;
        }
        bytes32[] memory records = abi.decode(p.typedState, (bytes32[]));
        if (records.length != q.policies.length || p.nonces.length != 0) revert T.InvalidRecord();
        for (uint256 j; j < records.length; ++j) {
            bytes32 key = keccak256(
                abi.encode(q.collectionId, q.policies[j].phaseId, q.policies[j].policyHash)
            );
            if (_policies[key] != 0 || records[j] == 0) revert T.InvalidRecord();
            _policies[key] = records[j];
        }
    }
}

