pragma solidity ^0.8.19;
import "./StreamArtistDelegationHydrationSource.sol";
import "./StreamArtistDelegationState.sol";
import "./StreamArtistSaleHashes.sol";

/// @notice Original-domain history joins. Present grant liveness never reauthorizes a historical consent.
library StreamArtistDelegationHydrationFacts {
    function check(StreamArtistHydrationPrepared.Bundle memory h, AH.Request memory p) public view {
        AH.Binding memory binding =
            StreamArtistDelegationHydrationCodec.binding(h.data[0].typedState);
        DH.Identity memory identity =
            StreamArtistDelegationHydrationCodec.identity(h.data[2].typedState);
        AH.Identity memory original = abi.decode(identity.baseline, (AH.Identity));
        AH.Acceptance memory acceptance = abi.decode(h.data[3].typedState, (AH.Acceptance));
        DH.Consent memory consent =
            StreamArtistDelegationHydrationCodec.consent(h.data[6].typedState);
        if (
            binding.item.artistId != h.q.artistId || binding.item.bindingHash != h.q.bindingHash
                || binding.item.artistAddress != original.item.authorityAddress
                || binding.item.identityRecordHash != original.item.identityRecordHash
                || original.nextRegistrationNonce != 1 || original.item.authorityClass != 1
                || original.item.status != 1
                || acceptance.record
                    != IStreamArtistNativeReceipts(h.source.owners[3])
                    .artistNativeReceiptAt(0)
                    .recordHash || identity.epoch != 0
        ) revert T.InvalidRecord();
        StreamArtistHashes.Environment memory e = StreamArtistHashes.Environment(
            block.chainid, h.prior, h.source.core, h.source.mintManager
        );
        if (
            StreamArtistHashes.identity(
                    e, original.item.authorityAddress, original.item.identityRecordHash, 0
                ) != h.q.artistId
        ) revert T.InvalidRecord();
        _identity(h, identity, original, e);
        _consents(h, identity, original, consent, binding, e);
        _nonces(identity, p.expectedSource[2].nonceIndexCount, h.q.artistId);
    }

    function _identity(
        StreamArtistHydrationPrepared.Bundle memory h,
        DH.Identity memory b,
        AH.Identity memory original,
        StreamArtistHashes.Environment memory e
    ) private view {
        uint256 revisions;
        uint256 grants;
        uint256 revocations;
        bytes32 prior;
        bytes32 document = original.item.identityRecordHash;
        uint256 count = IStreamArtistNativeReceipts(h.source.owners[2]).artistNativeReceiptCount();
        for (uint256 i; i < count; ++i) {
            H.Receipt memory r =
                IStreamArtistNativeReceipts(h.source.owners[2]).artistNativeReceiptAt(i);
            if (r.operation == 25) {
                if (revisions >= b.revisions.length) revert T.InvalidRecord();
                DH.Revision memory row = b.revisions[revisions++];
                if (
                    row.item.recordHash != r.recordHash || row.item.artistId != h.q.artistId
                        || row.item.previousRevisionRecord != prior
                        || row.item.previousRecordHash != document
                        || row.item.revisedRecordHash == document
                        || row.item.signer != original.item.authorityAddress
                        || row.item.authorityClass != 1 || row.item.signedAt == 0
                        || row.document.length == 0
                        || keccak256(row.document) != row.item.revisedRecordHash
                        || bytes(row.item.displayName).length == 0
                        || keccak256(
                                abi.encode(
                                    bytes32(
                                        0x1b7518e9d16da358d15957ec43218eb0b017fbd017e60c75b3126110006034a4
                                    ),
                                    e.chainId,
                                    e.registry,
                                    h.q.artistId,
                                    document,
                                    row.item.revisedRecordHash,
                                    row.item.signer,
                                    uint8(1),
                                    row.item.nonce,
                                    row.item.signedAt
                                )
                            ) != r.recordHash
                ) revert T.InvalidRecord();
                prior = r.recordHash;
                document = row.item.revisedRecordHash;
            } else if (r.operation == 26) {
                if (grants >= b.grants.length) revert T.InvalidRecord();
                DH.Grant memory row = b.grants[grants++];
                D.Grant memory g = row.item.grant;
                if (
                    row.recordHash != r.recordHash
                        || row.item.grantor != original.item.authorityAddress
                        || g.artistId != h.q.artistId || g.delegate == address(0)
                        || g.delegate == row.item.grantor || g.capabilities == 0
                        || (g.capabilities & ~uint32(1143)) != 0 || g.expiresAt <= g.notBefore
                        || row.epoch != b.epoch || (g.maxUses != 0 && row.item.uses > g.maxUses)
                        || row.item.revoked != (row.item.revocationRecordHash != 0)
                        || keccak256(
                                abi.encode(
                                    keccak256("6529STREAM_ARTIST_DELEGATION_RECORD_V1"),
                                    e.chainId,
                                    e.registry,
                                    g.artistId,
                                    g.delegate,
                                    g.collectionId,
                                    g.capabilities,
                                    g.notBefore,
                                    g.expiresAt,
                                    g.maxUses,
                                    g.constraintsHash,
                                    row.item.nonce
                                )
                            ) != row.recordHash
                ) revert T.InvalidRecord();
                bytes32 latest = row.recordHash;
                for (uint256 j = grants; j < b.grants.length; ++j) {
                    if (b.grants[j].item.grant.delegate == g.delegate) {
                        latest = b.grants[j].recordHash;
                    }
                }
                if (row.current != latest) revert T.InvalidRecord();
            } else if (r.operation == 27) {
                uint256 matched;
                // A revocation must follow its actual grant in the original Identity journal.
                for (uint256 j; j < grants; ++j) {
                    if (b.grants[j].item.revocationRecordHash == r.recordHash) ++matched;
                }
                if (matched != 1) revert T.InvalidRecord();
                ++revocations;
            }
        }
        uint256 revoked;
        for (uint256 i; i < b.grants.length; ++i) {
            if (b.grants[i].item.revoked) ++revoked;
        }
        if (revisions != b.revisions.length || grants != b.grants.length || revocations != revoked) revert T.InvalidRecord();
    }

    function _consents(
        StreamArtistHydrationPrepared.Bundle memory h,
        DH.Identity memory identity,
        AH.Identity memory original,
        DH.Consent memory b,
        AH.Binding memory binding,
        StreamArtistHashes.Environment memory e
    ) private view {
        uint256 policies;
        uint256 sales;
        uint256[] memory uses = new uint256[](identity.grants.length);
        uint256 count = IStreamArtistNativeReceipts(h.source.owners[6]).artistNativeReceiptCount();
        if (b.policies.length != h.q.policies.length) revert T.InvalidRecord();
        for (uint256 i; i < count; ++i) {
            H.Receipt memory r =
                IStreamArtistNativeReceipts(h.source.owners[6]).artistNativeReceiptAt(i);
            if (r.operation == 14) {
                if (
                    policies >= b.policies.length || b.policies[policies].recordHash != r.recordHash
                ) revert T.InvalidRecord();
                bytes32 grant = b.policies[policies++].grant;
                if (grant != 0) {
                    ++uses[
                        _grant(
                            identity,
                            grant,
                            h.q.collectionId,
                            D.POLICY_CONSENT,
                            binding.item.consentMode
                        )
                    ];
                }
            } else {
                if (r.operation != 16 || sales >= b.sales.length) revert T.InvalidRecord();
                DH.Sale memory row = b.sales[sales++];
                Sale.Record memory item = row.item;
                if (
                    item.recordHash != r.recordHash || item.artistId != h.q.artistId
                        || item.terms.collectionId != h.q.collectionId
                        || item.terms.saleAdapter == address(0) || item.terms.saleId == 0
                        || item.terms.saleConfigHash == 0 || item.signedAt == 0
                        || item.bindingGeneration != 1 || item.bindingHash != h.q.bindingHash
                        || StreamArtistSaleHashes.record(
                                e,
                                item.terms,
                                item.artistId,
                                item.signer,
                                item.authorityClass,
                                item.nonce,
                                item.signedAt
                            ) != item.recordHash
                ) revert T.InvalidRecord();
                if (row.grant == 0) {
                    if (item.authorityClass != 1 || item.signer != original.item.authorityAddress) {
                        revert T.InvalidRecord();
                    }
                } else {
                    uint256 g = _grant(
                        identity,
                        row.grant,
                        h.q.collectionId,
                        D.SALE_CONSENT,
                        binding.item.consentMode
                    );
                    if (
                        item.authorityClass != 2
                            || item.signer != identity.grants[g].item.grant.delegate
                    ) revert T.InvalidRecord();
                    ++uses[g];
                }
                bytes32 lookup = StreamArtistSaleHashes.lookup(
                    item.terms.collectionId, item.terms.saleId, item.terms.saleConfigHash
                );
                bytes32 latest = item.recordHash;
                for (uint256 j = sales; j < b.sales.length; ++j) {
                    Sale.Record memory next = b.sales[j].item;
                    if (
                        StreamArtistSaleHashes.lookup(
                                next.terms.collectionId,
                                next.terms.saleId,
                                next.terms.saleConfigHash
                            ) == lookup
                    ) latest = next.recordHash;
                }
                if (row.current != latest) revert T.InvalidRecord();
            }
        }
        if (policies != b.policies.length || sales != b.sales.length) revert T.InvalidRecord();
        for (uint256 i; i < uses.length; ++i) {
            if (uses[i] != identity.grants[i].item.uses) revert T.UnsupportedProfile();
        }
    }

    function _grant(
        DH.Identity memory b,
        bytes32 hash,
        uint256 collectionId,
        uint32 capability,
        uint8 mode
    ) private pure returns (uint256) {
        if (mode != 2) revert T.UnsupportedProfile();
        for (uint256 i; i < b.grants.length; ++i) {
            if (b.grants[i].recordHash != hash) continue;
            D.Grant memory g = b.grants[i].item.grant;
            if (
                (g.collectionId != 0 && g.collectionId != collectionId)
                    || (g.capabilities & capability) == 0
            ) revert T.InvalidRecord();
            return i;
        }
        revert T.InvalidRecord();
    }

    function _nonces(DH.Identity memory b, uint256 count, bytes32 artistId) private pure {
        if (count != 1 + b.delegateNonces.length) revert T.InvalidRecord();
        uint256 unique;
        for (uint256 i; i < b.grants.length; ++i) {
            address delegate = b.grants[i].item.grant.delegate;
            uint256 uses;
            bool prior;
            for (uint256 j; j < b.grants.length; ++j) {
                if (b.grants[j].item.grant.delegate != delegate) continue;
                if (j < i) prior = true;
                uses += b.grants[j].item.uses;
            }
            if (prior || uses == 0) continue;
            ++unique;
            bytes32 key = keccak256(
                abi.encode(
                    keccak256("6529STREAM_ARTIST_DELEGATE_NONCE_LANE_V1"), artistId, delegate
                )
            );
            uint256 matches;
            for (uint256 j; j < b.delegateNonces.length; ++j) {
                if (b.delegateNonces[j].key == key) ++matches;
            }
            if (matches != 1) revert T.InvalidRecord();
        }
        if (unique != b.delegateNonces.length) revert T.InvalidRecord();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "./StreamArtistDelegationHydrationFacts.sol";

library StreamArtistDelegationHydrationOperations {
    function hydrate(D.CoordinatorContext memory x, address actor, AH.Request memory p)
        public
        returns (bytes32)
    {
        StreamArtistHydrationPrepared.Bundle memory h =
            StreamArtistDelegationHydrationSource.prepare(x, p);
        StreamArtistDelegationHydrationFacts.check(h, p);
        return StreamArtistHydrationCommit.execute(x, actor, p, h);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "./StreamArtistHydrationCommit.sol";
import "./StreamArtistDelegationHydrationCodec.sol";
import "../../interfaces/stream/artist/IStreamArtistDelegationAuthorityHydration.sol";

/// @notice Complete source collection; no mutation is reachable before all seven inventories pass.
library StreamArtistDelegationHydrationSource {
    function prepare(D.CoordinatorContext memory x, AH.Request memory p)
        public
        view
        returns (StreamArtistHydrationPrepared.Bundle memory h)
    {
        if (
            p.artistId == 0 || p.collectionId == 0 || p.bindingIndex != 0 || p.policies.length > 128
        ) revert T.UnsupportedProfile();
        IStreamArtistHistory history = IStreamArtistHistory(x.suite.owners[2]);
        if (history.importedHistoryBindingCount() != 1) revert T.InvalidBinding();
        (h.prior,,,) = history.importedHistoryBinding(0);
        (, bytes32 pin,) = history.artistHistoryPredecessorBinding(h.prior);
        StreamArtistHistoryProof.predecessor(
            x.suite.core,
            x.suite.registry,
            h.prior,
            pin,
            StreamArtistHistoryProof.cap(x.suite.registry)
        );
        (bool sealed_, address successor,) = IStreamArtistHistory(h.prior).artistRegistryCutover();
        if (
            !sealed_ || successor != x.suite.registry
                || IStreamArtistHistory(h.prior).importedHistoryBindingCount() != 0
        ) revert T.InvalidBinding();
        StreamArtistHydrationSourceGuards._lane(history, h.prior, 1, p.artistId);
        StreamArtistHydrationSourceGuards._lane(history, h.prior, 2, bytes32(p.collectionId));
        h.sourceCoordinator = IStreamArtistIngressBinding(h.prior).operationCoordinator();
        h.source = IStreamArtistAuthorityHydrationCoordinator(h.sourceCoordinator)
            .authorityHydrationSuite();
        StreamArtistHydrationSourceGuards._suite(x.suite, h.source, h.prior, h.sourceCoordinator);
        h.profile = DH.PROFILE;
        h.q = _inventory(x.suite, h, p);
        for (uint256 i; i < 7; ++i) {
            h.data[i] = _guards(h.source, h.sourceCoordinator, i, p);
            h.data[i].typedState = i == 0 || i == 2 || i == 6
                ? IStreamArtistDelegationHydrationOwner(h.source.owners[i])
                    .authorityDelegationHydrationState(h.q)
                : IStreamArtistAuthorityHydrationOwner(h.source.owners[i])
                    .authorityHydrationState(h.q);
        }
    }

    function _inventory(
        T.SuiteConfiguration memory next,
        StreamArtistHydrationPrepared.Bundle memory h,
        AH.Request memory p
    ) private view returns (AH.Query memory q) {
        q.artistId = p.artistId;
        q.collectionId = p.collectionId;
        q.policies = p.policies;
        uint256[7] memory counts;
        uint256 total;
        for (uint256 i; i < 7; ++i) {
            h.before_[i] = IStreamArtistOwner(next.owners[i]).ownerStateSnapshotV2();
            if (
                h.before_[i].revision != (i == 2 ? 3 : 0)
                    || IStreamArtistNativeReceipts(next.owners[i]).artistNativeReceiptCount() != 0
                    || IStreamArtistAuthorityHydrationOwner(next.owners[i])
                            .authorityHydrationCommitment() != 0
            ) revert T.InvalidRecord();
            StreamArtistHydrationSourceGuards._multipleHeader(
                h.source.owners[i], p.expectedSource[i]
            );
            counts[i] = IStreamArtistNativeReceipts(h.source.owners[i]).artistNativeReceiptCount();
            if (counts[i] > 128) revert T.UnsupportedProfile();
            if ((i == 0 || i == 3) && counts[i] != 1) revert T.UnsupportedProfile();
            if ((i == 1 || i == 4 || i == 5) && counts[i] != 0) revert T.UnsupportedProfile();
            if (i == 2 && counts[i] == 0) revert T.UnsupportedProfile();
            total += counts[i];
        }
        q.records = new bytes32[](total);
        uint256 index;
        uint256 policies;
        uint256 collectionCount;
        for (uint256 i; i < 7; ++i) {
            for (uint256 j; j < counts[i]; ++j) {
                H.Receipt memory r =
                    IStreamArtistNativeReceipts(h.source.owners[i]).artistNativeReceiptAt(j);
                bool allowed = i == 0
                    ? r.operation == 1
                    : i == 3
                        ? r.operation == 2
                        : i == 2
                            ? (j == 0
                                    ? r.operation == 1 && r.recordHash == q.artistId
                                    : r.operation == 25 || r.operation == 26 || r.operation == 27
                                        || r.operation == 54)
                            : i == 6 && (r.operation == 14 || r.operation == 16);
                if (
                    !allowed || r.artistId != q.artistId
                        || r.collectionId != (i == 2 ? 0 : q.collectionId) || r.recordHash == 0
                ) revert T.UnsupportedProfile();
                q.records[index++] = r.recordHash;
                if (i == 0) q.bindingHash = r.recordHash;
                if (i == 6 && r.operation == 14) ++policies;
                if (r.collectionId != 0) ++collectionCount;
            }
            uint256 revision = i == 0 || i == 4
                ? 2
                : i == 2 ? 2 + counts[2] + counts[6] : i == 3 ? 1 : i == 6 ? counts[6] : 0;
            if (p.expectedSource[i].ownerState.revision != revision) revert T.UnsupportedProfile();
        }
        if (policies != q.policies.length) revert T.InvalidRecord();
        for (uint256 i; i < policies; ++i) {
            if (q.policies[i].phaseId == 0 || q.policies[i].policyHash == 0) {
                revert T.InvalidRecord();
            }
            for (uint256 j; j < i; ++j) {
                if (
                    q.policies[i].phaseId == q.policies[j].phaseId
                        && q.policies[i].policyHash == q.policies[j].policyHash
                ) revert T.InvalidRecord();
            }
        }
        (, uint64 ac) = IStreamArtistHistory(h.prior).artistHistoryLane(1, q.artistId);
        (, uint64 cc) = IStreamArtistHistory(h.prior).artistHistoryLane(2, bytes32(q.collectionId));
        if (ac != total || cc != collectionCount) revert T.InvalidRecord();
    }

    function _guards(
        T.SuiteConfiguration memory s,
        address coordinator,
        uint256 i,
        AH.Request memory p
    ) private view returns (AH.OwnerData memory d) {
        CP.Checkpoint memory header = p.expectedSource[i];
        d.origins = p.replayOrigins[i];
        if (d.origins.length != header.replayCount) revert T.InvalidRecord();
        d.sourceKeys = new bytes32[](header.replayCount);
        d.cells = new T.ReplayCell[](header.replayCount);
        for (uint256 j; j < header.replayCount; ++j) {
            (bytes32 key, T.ReplayCell memory cell) = CP(s.owners[i]).authorityReplayAt(j);
            if (
                key
                        != keccak256(
                            abi.encode(
                                keccak256("6529STREAM_ARTIST_OWNER_REPLAY_KEY_V2"),
                                block.chainid,
                                s.registry,
                                coordinator,
                                s.archive,
                                s.owners[i],
                                header.ownerState.domainId,
                                d.origins[j].surface,
                                d.origins[j].scope
                            )
                        ) || cell.status == 0
                    || keccak256(abi.encode(cell))
                        != keccak256(abi.encode(IStreamArtistOwner(s.owners[i]).replayCell(key)))
            ) revert T.InvalidRecord();
            d.sourceKeys[j] = key;
            d.cells[j] = cell;
        }
        if (i != 2) {
            if (header.nonceIndexCount != 0) revert T.UnsupportedProfile();
            return d;
        }
        bool found;
        uint256 prefixes;
        for (uint256 j; j < header.nonceIndexCount; ++j) {
            CP.NonceIndex memory n = CP(s.owners[i]).authorityNonceIndexAt(j);
            prefixes += n.prefixCount;
            if ((n.kind != 1 && n.kind != 2) || n.prefixCount == 0 || prefixes > 256) {
                revert T.UnsupportedProfile();
            }
            if (n.kind == 2) continue;
            if (found || n.key != p.artistId) revert T.UnsupportedProfile();
            found = true;
            d.nonces = new AH.NonceWord[](n.prefixCount);
            for (uint256 k; k < n.prefixCount; ++k) {
                (d.nonces[k].prefix, d.nonces[k].words, d.nonces[k].exhausted) =
                    CP(s.owners[i]).authorityNonceWordAt(1, n.key, k);
            }
        }
        if (!found) revert T.InvalidRecord();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "./StreamArtistIdentityHydration.sol";
import "./StreamArtistMultipleIdentityHydration.sol";
import "./StreamArtistIdentityRevisionState.sol";
import "./StreamArtistDelegationHydrationCodec.sol";
import {
    IStreamArtistNativeReceipts,
    StreamArtistHistoryTypes as H
} from "../../interfaces/stream/artist/IStreamArtistHistory.sol";
import {
    IStreamArtistAuthorityCheckpoint as CP
} from "../../interfaces/stream/artist/IStreamArtistAuthorityCheckpoint.sol";

/// @notice Original typed Identity cells only; caller/snapshot/replay/commit remain in the owner.
library StreamArtistDelegationIdentityHydration {
    function exportEncoded(
        StreamArtistIdentityState.State storage identity,
        StreamArtistDelegationState.State storage grants,
        StreamArtistIdentityRevisionState.State storage revisions,
        StreamArtistEstateState.State storage estate,
        StreamArtistDormancyState.State storage dormancy,
        StreamArtistUnavailabilityState.State storage findings,
        bytes calldata encoded
    ) public view returns (bytes memory) {
        return exportState(
            identity, grants, revisions, estate, dormancy, findings, abi.decode(encoded, (AH.Query))
        );
    }

    function exportState(
        StreamArtistIdentityState.State storage identity,
        StreamArtistDelegationState.State storage grants,
        StreamArtistIdentityRevisionState.State storage revisions,
        StreamArtistEstateState.State storage estate,
        StreamArtistDormancyState.State storage dormancy,
        StreamArtistUnavailabilityState.State storage findings,
        AH.Query memory q
    ) public view returns (bytes memory) {
        DH.Identity memory b;
        b.baseline = StreamArtistMultipleIdentityHydration.exportState(
            identity, estate, dormancy, findings, q
        );
        b.epoch = estate.delegationEpoch[q.artistId];
        if (b.epoch != 0 || revisions.pendingRecord[q.artistId] != 0) {
            revert T.UnsupportedProfile();
        }
        uint256 count = IStreamArtistNativeReceipts(address(this)).artistNativeReceiptCount();
        if (count > 128) revert T.UnsupportedProfile();
        uint256 revisionCount;
        uint256 grantCount;
        for (uint256 i; i < count; ++i) {
            H.Receipt memory r = IStreamArtistNativeReceipts(address(this)).artistNativeReceiptAt(i);
            if (r.artistId != q.artistId) continue;
            if (r.operation == 25) ++revisionCount;
            if (r.operation == 26) ++grantCount;
        }
        b.revisions = new DH.Revision[](revisionCount);
        b.grants = new DH.Grant[](grantCount);
        revisionCount = 0;
        grantCount = 0;
        bytes32 latest;
        for (uint256 i; i < count; ++i) {
            H.Receipt memory r = IStreamArtistNativeReceipts(address(this)).artistNativeReceiptAt(i);
            if (r.artistId != q.artistId) continue;
            if (r.operation == 25) {
                R.ProvisionalAssociation memory a = revisions.associations[r.recordHash];
                R.ProvisionalAssociation memory empty;
                if (keccak256(abi.encode(a)) != keccak256(abi.encode(empty))) {
                    revert T.UnsupportedProfile();
                }
                DH.Revision memory row;
                row.item = revisions.records[r.recordHash];
                row.document = identity.documents[row.item.revisedRecordHash];
                b.revisions[revisionCount++] = row;
                latest = r.recordHash;
            }
            if (r.operation == 26) {
                D.Record memory item = grants.records[r.recordHash];
                b.grants[grantCount++] = DH.Grant(
                    r.recordHash,
                    item,
                    estate.grantEpoch[r.recordHash],
                    grants.current[keccak256(abi.encode(q.artistId, item.grant.delegate))]
                );
            }
        }
        if (revisions.latestRecord[q.artistId] != latest) revert T.InvalidRecord();
        uint256 n = CP(address(this)).authorityCheckpoint().nonceIndexCount;
        if (n == 0 || n > 128) revert T.UnsupportedProfile();
        uint256 lanes;
        for (uint256 i; i < n; ++i) {
            CP.NonceIndex memory index = CP(address(this)).authorityNonceIndexAt(i);
            if (index.kind == 2 && _belongs(b.grants, q.artistId, index.key)) ++lanes;
        }
        b.delegateNonces = new DH.NonceLane[](lanes);
        lanes = 0;
        for (uint256 i; i < n; ++i) {
            CP.NonceIndex memory index = CP(address(this)).authorityNonceIndexAt(i);
            if (index.kind != 2 || !_belongs(b.grants, q.artistId, index.key)) continue;
            if (index.prefixCount == 0 || index.prefixCount > 256) revert T.UnsupportedProfile();
            DH.NonceLane memory lane;
            lane.key = index.key;
            lane.hint = grants.hints[index.key];
            lane.words = new AH.NonceWord[](index.prefixCount);
            for (uint256 j; j < index.prefixCount; ++j) {
                (lane.words[j].prefix, lane.words[j].words, lane.words[j].exhausted) =
                    CP(address(this)).authorityNonceWordAt(2, index.key, j);
            }
            b.delegateNonces[lanes++] = lane;
        }
        return abi.encode(DH.IDENTITY, b);
    }

    function _belongs(DH.Grant[] memory rows, bytes32 artistId, bytes32 key)
        private
        pure
        returns (bool)
    {
        for (uint256 i; i < rows.length; ++i) {
            if (
                key
                    == keccak256(
                        abi.encode(
                            keccak256("6529STREAM_ARTIST_DELEGATE_NONCE_LANE_V1"),
                            artistId,
                            rows[i].item.grant.delegate
                        )
                    )
            ) return true;
        }
        return false;
    }

    function importEncoded(
        StreamArtistIdentityState.State storage identity,
        StreamArtistDelegationState.State storage grants,
        StreamArtistIdentityRevisionState.State storage revisions,
        StreamArtistEstateState.State storage estate,
        StreamArtistDormancyState.State storage dormancy,
        StreamArtistUnavailabilityState.State storage findings,
        bytes calldata encoded
    ) public {
        (, AH.Query memory q, AH.OwnerData memory data,) =
            abi.decode(encoded, (T.ActionContext, AH.Query, AH.OwnerData, bytes32));
        DH.Identity memory b = StreamArtistDelegationHydrationCodec.identity(data.typedState);
        data.typedState = b.baseline;
        StreamArtistIdentityHydration.importState(identity, estate, dormancy, findings, q, data);
        importAdditional(identity, grants, revisions, estate, q, b);
    }

    function importAdditional(
        StreamArtistIdentityState.State storage identity,
        StreamArtistDelegationState.State storage grants,
        StreamArtistIdentityRevisionState.State storage revisions,
        StreamArtistEstateState.State storage estate,
        AH.Query memory q,
        DH.Identity memory b
    ) internal {
        if (
            b.epoch != 0 || estate.delegationEpoch[q.artistId] != 0
                || revisions.latestRecord[q.artistId] != 0
                || revisions.pendingRecord[q.artistId] != 0
        ) revert T.InvalidRecord();
        for (uint256 i; i < b.revisions.length; ++i) {
            DH.Revision memory row = b.revisions[i];
            if (
                revisions.records[row.item.recordHash].recordHash != 0
                    || keccak256(row.document) != row.item.revisedRecordHash
            ) revert T.InvalidRecord();
            revisions.records[row.item.recordHash] = row.item;
            revisions.latestRecord[q.artistId] = row.item.recordHash;
            if (identity.documents[row.item.revisedRecordHash].length == 0) {
                identity.documents[row.item.revisedRecordHash] = row.document;
                StreamArtistPayloadStore.store(keccak256("ARTIST_IDENTITY_DOCUMENT"), row.document);
            }
        }
        for (uint256 i; i < b.grants.length; ++i) {
            DH.Grant memory row = b.grants[i];
            if (grants.records[row.recordHash].grantor != address(0) || row.epoch != b.epoch) {
                revert T.InvalidRecord();
            }
            grants.records[row.recordHash] = row.item;
            estate.grantEpoch[row.recordHash] = row.epoch;
            bytes32 scope = keccak256(abi.encode(q.artistId, row.item.grant.delegate));
            if (grants.current[scope] != 0 && grants.current[scope] != row.current) {
                revert T.InvalidRecord();
            }
            grants.current[scope] = row.current;
        }
        for (uint256 i; i < b.delegateNonces.length; ++i) {
            DH.NonceLane memory lane = b.delegateNonces[i];
            if (grants.hints[lane.key] != 0) revert T.InvalidRecord();
            for (uint256 j; j < lane.words.length; ++j) {
                AH.NonceWord memory word = lane.words[j];
                uint256 prefix = word.prefix;
                for (uint8 level; level < 32; ++level) {
                    uint256 old = grants.availability[lane.key].full[level][prefix];
                    if (old != 0 && old != word.words[level]) revert T.InvalidRecord();
                    grants.availability[lane.key].full[level][prefix] = word.words[level];
                    prefix >>= 8;
                }
                grants.availability[lane.key].exhausted = word.exhausted;
                StreamArtistAuthorityCheckpoint.noteNonce(
                    2, lane.key, word.prefix, keccak256(abi.encode(word))
                );
            }
            (, uint256 hint) =
                StreamArtistNonceAvailability.firstUnused(grants.availability[lane.key]);
            if (hint != lane.hint) revert T.InvalidRecord();
            grants.hints[lane.key] = lane.hint;
        }
    }
}

