        StreamArtistEstateState.State storage estate,
        StreamArtistDormancyState.State storage dormancy,
        StreamArtistSuccessionState.State storage succession,
        StreamArtistIdentityContestState.State storage contests,
        mapping(bytes32 => T.ReplayCell) storage replay,
        RecoveryState.PrepareInput memory i
    ) public returns (StreamArtistIdentityState.Mutation memory m, bytes32 associationHash) {
        if (!_firstAfterDormancy(s, dormancy, i.request.artistId)) {
            return RecoveryState.prepareWithEstate(
                s, identity, rotations, resolutions, estate, succession, contests, replay, i
            );
        }
        Recovery.Context memory c = context(
            s,
            identity,
            rotations,
            resolutions,
            estate,
            dormancy,
            succession,
            contests,
            i.owner,
            i.request,
            i.acceptance
        );
        (, R.GuardianRecord memory guardian) = _facts(
            s,
            dormancy,
            estate,
            rotations,
            resolutions,
            succession,
            contests,
            i.owner.environment,
            resolutions.causes[resolutions.currentCause[i.request.artistId]],
            i.request
        );
        return StreamArtistIdentityRecoveryMutation.prepareWithGuardian(
            s, rotations, replay, i, c, guardian
        );
    }

    // This only selects the reader. That reader authenticates the original living35 and43,
    // their exact epoch boundary and complete ancestry before admitting the new profile.
    function _firstAfterDormancy(
        RecoveryState.State storage s,
        StreamArtistDormancyState.State storage dormancy,
        bytes32 artistId
    ) private view returns (bool) {
        bytes32 activation = dormancy.activation[artistId];
        if (activation == 0) return false;
        bytes32 latest = s.latest[artistId];
        return latest == 0
            || (s.records[latest].fields.vestedAuthorityClass == 1
                && s.records[latest].delegationEpoch
                    < dormancy.terminals[activation].delegationEpoch);
    }

    function _facts(
        RecoveryState.State storage s,
        StreamArtistDormancyState.State storage dormancy,
        StreamArtistEstateState.State storage estate,
        StreamArtistRotationState.State storage rotations,
        StreamArtistIdentityResolutionState.State storage resolutions,
        StreamArtistSuccessionState.State storage succession,
        StreamArtistIdentityContestState.State storage contests,
        StreamArtistHashes.Environment memory e,
        Dismissal.Cause memory cause,
        Recovery.Request memory p
    ) private view returns (bytes32, R.GuardianRecord memory) {
        // Both context and preparation consume the same selected origin/terminal and guardian proof.
        // Original history joins the actual op33 evidence. Keep the caller's Appeal document
        // and supersession list unchanged for adjudication, registration and acceptance.
        Recovery.Request memory historical = p;
        if (cause.facts.kind == 1 && p.supersededRecordHashes.length != 0) {
            historical = Recovery.Request(
                p.artistId,
                p.newAddress,
                p.vestedAuthorityClass,
                p.expectedCauseHash,
                p.expectedResolutionHash,
                contests.records[cause.facts.referenceHash].terms.evidenceHash,
                p.reasonHash,
                new bytes32[](0)
            );
        }
        bool familyRequired = FamilyHistory.required(s, rotations, resolutions, e, cause);
        bytes32 historyProof;
        if (familyRequired) {
            bytes32 activation = dormancy.activation[p.artistId];
            historyProof = FamilyHistory.read(
                s,
                rotations,
                resolutions,
                e,
                cause,
                s.vestingHistory.snapshots[activation],
                dormancy.transitions[activation]
            );
        }
        if (rotations.latestExecution[p.artistId] != dormancy.activation[p.artistId]) {
            if (familyRequired) {
                return DormRotation.factsWithHistory(
                    s,
                    dormancy,
                    estate,
                    rotations,
                    resolutions,
                    succession,
                    contests,
                    e,
                    cause,
                    historical,
                    historyProof
                );
            }
            return DormRotation.facts(
                s,
                dormancy,
                estate,
                rotations,
                resolutions,
                succession,
                contests,
                e,
                cause,
                historical
            );
        }
        if (familyRequired) {
            return DormPredecessor.factsWithHistory(
                s,
                dormancy,
                estate,
                rotations,
                resolutions,
                succession,
                contests,
                e,
                cause,
                historical,
                historyProof
            );
        }
        return DormPredecessor.facts(
            s, dormancy, estate, rotations, resolutions, succession, contests, e, cause, historical
        );
    }

    function _context(
        RecoveryState.State storage s,
        StreamArtistIdentityState.State storage identity,
        StreamArtistRotationState.State storage rotations,
        StreamArtistIdentityResolutionState.State storage resolutions,
        StreamArtistEstateState.State storage estate,
        StreamArtistDormancyState.State storage dormancy,
        StreamArtistSuccessionState.State storage succession,
        StreamArtistIdentityContestState.State storage contests,
        StreamArtistIdentityState.OwnerContext memory o,
        Recovery.Request memory p,
        T.Authorization memory acceptance
    ) private view returns (Recovery.Context memory c) {
        Dismissal.Cause memory cause = resolutions.causes[resolutions.currentCause[p.artistId]];
        T.Identity storage principal = identity.identities[p.artistId];
        if (
            p.artistId == bytes32(0) || cause.causeHash == bytes32(0)
                || cause.causeHash != p.expectedCauseHash || cause.facts.artistId != p.artistId
                || (cause.facts.kind != 1 && cause.facts.kind != 2)
                || cause.facts.referenceHash == bytes32(0) || cause.facts.actor == address(0)
                || cause.facts.incumbent == address(0) || principal.status != 4
                || principal.authorityClass != cause.facts.authorityClass
                || principal.authorityAddress != cause.facts.incumbent
                || identity.activeIdentity[principal.authorityAddress] != p.artistId
                || resolutions.latestResolution[p.artistId] != p.expectedResolutionHash
                || cause.facts.previousResolutionHash != p.expectedResolutionHash
                || p.newAddress == address(0) || p.newAddress == principal.authorityAddress
                || p.evidenceHash == bytes32(0) || p.reasonHash == bytes32(0)
        ) revert Recovery.InvalidIdentityRecovery(p.artistId);
        if (
            p.vestedAuthorityClass != 3 || cause.facts.authorityClass != 3
                || cause.facts.priorStatus != 3 || rotations.pending[p.artistId] != bytes32(0)
        ) revert Recovery.UnsupportedIdentityRecoveryProfile(p.artistId);
        (bytes32 predecessor, R.GuardianRecord memory guardian) = _facts(
            s,
            dormancy,
            estate,
            rotations,
            resolutions,
            succession,
            contests,
            o.environment,
            cause,
            p
        );
        if (identity.activeIdentity[p.newAddress] != bytes32(0)) {
            revert T.AddressAlreadyRegistered(p.newAddress);
        }
        c.causeHash = cause.causeHash;
        c.incumbent = principal.authorityAddress;
        c.postContestSeconds = StreamArtistRotationState.rotationSeconds(rotations);
        bytes32 supersessionContext;
        if (p.supersededRecordHashes.length != 0) {
            (supersessionContext, c.postContestSeconds) = GuardianSupersession.contextAndWindow(
                s.guardianSupersession,
                s.guardianHistory,
                s.vestingHistory,
                rotations,
                o.environment,
                cause,
                p,
                s.guardianRecordsSeen[p.artistId],
                c.postContestSeconds
            );
        } else if (guardian.terms.minContestSeconds > c.postContestSeconds) {
            c.postContestSeconds = guardian.terms.minContestSeconds;
        }
        c.standingTailSeconds = StreamArtistRotationState.standingSeconds(rotations);
        c.timingRevision = rotations.timingRevision == 0 ? 1 : rotations.timingRevision;
        c.delegationEpoch = estate.delegationEpoch[p.artistId];
        c.scopeHash = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_IDENTITY_RECOVERY_SCOPE_V2"),
                o.environment.chainId,
                o.environment.registry,
                address(this),
                p.artistId
            )
        );
        c.oldValueHash = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_IDENTITY_RECOVERY_STATE_V2"),
                c.scopeHash,
                cause,
                principal,
                p.expectedResolutionHash,
                c.postContestSeconds,
                c.standingTailSeconds,
                c.timingRevision,
                c.delegationEpoch
            )
        );
        // Registration changes owner revision, but never these scheduled transition facts.
        if (guardian.recordHash != bytes32(0)) {
            c.oldValueHash = keccak256(
                abi.encode(
                    keccak256("6529STREAM_ARTIST_GUARDED_RECOVERY_STATE_V1"),
                    c.oldValueHash,
                    guardian,
                    s.guardianRecordsSeen[p.artistId]
                )
            );
        }
        if (guardian.recordHash != bytes32(0)) {
            GH.Head memory history = GuardianHistory.requireComplete(
                s.guardianHistory, p.artistId, s.guardianRecordsSeen[p.artistId]
            );
            c.oldValueHash = keccak256(
                abi.encode(
                    keccak256("6529STREAM_ARTIST_RECOVERY_GUARDIAN_HISTORY_CONTEXT_V1"),
                    c.oldValueHash,
                    history
                )
            );
        }
        c.oldValueHash = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_RECOVERY_FIRST_DORMANCY_CONTEXT_V1"),
                c.oldValueHash,
                predecessor
            )
        );
        if (p.supersededRecordHashes.length != 0) {
            c.oldValueHash = keccak256(abi.encode(c.oldValueHash, supersessionContext));
        }
        c.newValueHash = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_IDENTITY_RECOVERY_INTENT_V2"),
                c.scopeHash,
                c.oldValueHash,
                p,
                acceptance.nonce,
                acceptance.time
            )
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "../../interfaces/stream/artist/IStreamArtistDormancy.sol";
import {
    StreamArtistDormancyTypes as Dorm
} from "../../interfaces/stream/artist/IStreamArtistDormancy.sol";
import {
    StreamArtistIdentityDismissalTypes as Dismissal
} from "../../interfaces/stream/artist/StreamArtistIdentityDismissalTypes.sol";

/// @notice Exact fixed-Identity notice joins for original op33 and op58 contexts.
library StreamArtistDormancyResolutionReads {
    function pending(bytes32 artistId) internal view returns (bytes32 proof) {
        (bytes32 notice, uint8 phase, bytes32 terminal) =
            _read(abi.encodeCall(IStreamArtistDormancyOwner.dormancyNotice, (artistId)), artistId);
        if (notice == 0 || phase != 1 || terminal != 0) revert Dorm.InvalidDormancy(artistId);
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_DORMANCY_PENDING_CONTEXT_V1"), notice, phase, terminal
            )
        );
    }

    function resolution(Dismissal.Cause memory cause)
        internal
        view
        returns (bytes32 proof, uint8 restoredStatus)
    {
        restoredStatus = cause.facts.priorStatus;
        if (restoredStatus != 2) return (bytes32(0), restoredStatus);
        (bytes32 notice, uint8 phase, bytes32 terminal) = _read(
            abi.encodeCall(
                IStreamArtistDormancyOwner.dormancyResolutionState,
                (cause.facts.artistId, cause.causeHash)
            ),
            cause.facts.artistId
        );
        if (
            notice == 0 || (phase != 1 && phase != 2)
                || (phase == 1 ? terminal != 0 : terminal == 0)
        ) revert Dorm.InvalidDormancy(cause.facts.artistId);
        proof = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_DORMANCY_RESOLUTION_CONTEXT_V1"),
                cause.causeHash,
                notice,
                phase,
                terminal
            )
        );
        if (phase == 2) restoredStatus = 1;
    }

    function _read(bytes memory data, bytes32 id) private view returns (bytes32, uint8, bytes32) {
        bytes memory raw = new bytes(96);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(gas(), address(), add(data, 32), mload(data), add(raw, 32), 96)
            size := returndatasize()
        }
        if (!ok || size != 96) revert Dorm.InvalidDormancy(id);
        return abi.decode(raw, (bytes32, uint8, bytes32));
    }
}

