    IStreamArtistAuthorityCheckpoint as CP
} from "../../interfaces/stream/artist/IStreamArtistAuthorityCheckpoint.sol";

import "./StreamArtistHydrationPrepared.sol";
import "./StreamArtistHydrationSourceState.sol";
