            StreamArtistRecoveredIdentityTransport.importEncoded(
                _recoveredHydrationRoots(), msg.data[4:]
            );
            return;
        }
        _baselineTiming();
        StreamArtistAdditiveIdentityHydration.importEncoded(
            _identity,
            _delegations,
            _identityRevisions,
            _estate,
            _dormancy,
            _unavailability,
            msg.data[4:]
