            identity.identities[b.artistId].authorityClass,
            a.nonce,
            _now()
        );
        m = StreamArtistIdentityState.authorize(
            identity,
            replay,
            o,
            c,
            b.artistId,
            a,
            proof,
            StreamArtistSaleHashes.digest(o.environment, p, a),
