pragma solidity ^0.8.19;
import "./StreamArtistHistoryState.sol";
import "./StreamArtistIdentityState.sol";
import {
    StreamArtistHistoryTypes as H
} from "../../interfaces/stream/artist/IStreamArtistHistory.sol";

/// @notice Exact original55–57 mutations; host retains operation admission and its single commit.
library StreamArtistIdentityHistoryMutation {
    function cutoverEncoded(
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistIdentityState.OwnerContext memory o,
        address artistWindowAuthority,
        bytes calldata data
    ) public returns (StreamArtistIdentityState.Mutation memory) {
        T.ActionContext memory c = abi.decode(data[4:], (T.ActionContext));
        return applyArtistRegistryCutover(replay, o, artistWindowAuthority, c);
    }

    function syncEncoded(address core, address registry, bytes calldata data) public {
        (address source, uint256 first, H.Receipt[] memory rows) =
            abi.decode(data[4:], (address, uint256, H.Receipt[]));
        StreamArtistHistoryState.sync(
            core, registry, source, first, rows, StreamArtistHistoryProof.cap(registry)
        );
    }

    function importEncoded(
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistIdentityState.OwnerContext memory o,
        address artistWindowAuthority,
        bytes calldata data
    ) public returns (StreamArtistIdentityState.Mutation memory) {
        (T.ActionContext memory c, H.Binding memory p, bytes32 actionId) =
            abi.decode(data[4:], (T.ActionContext, H.Binding, bytes32));
        return applyArtistHistoryImport(replay, o, artistWindowAuthority, c, p, actionId);
    }

    function verifyEncoded(
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistIdentityState.OwnerContext memory o,
        address artistWindowAuthority,
        bytes calldata data
    ) public returns (StreamArtistIdentityState.Mutation memory) {
        (T.ActionContext memory c, uint256 index, H.Leaf memory p, bytes32[] memory proof) =
            abi.decode(data[4:], (T.ActionContext, uint256, H.Leaf, bytes32[]));
        return
            applyArtistHistoryLaneVerification(replay, o, artistWindowAuthority, c, index, p, proof);
    }

    function applyArtistHistoryImport(
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistIdentityState.OwnerContext memory o,
        address artistWindowAuthority,
        T.ActionContext memory c,
        H.Binding memory p,
        bytes32 actionId
    ) public returns (StreamArtistIdentityState.Mutation memory) {
        if (c.actor != artistWindowAuthority || actionId == 0) {
            revert T.Unauthorized(c.actor);
        }
        H.Context memory x = StreamArtistHistoryState.context(o.environment.registry, p);
        bytes memory raw = StreamArtistHistoryProof.fixedRead(
            artistWindowAuthority,
            abi.encodeWithSignature("currentAction()"),
            192,
            StreamArtistHistoryProof.cap(o.environment.registry)
        );
        (bool executing, bytes32 id, uint8 cls, bytes32 scope, bytes32 oldHash, bytes32 newHash) =
            abi.decode(raw, (bool, bytes32, uint8, bytes32, bytes32, bytes32));
        if (
            !executing || id != actionId || cls != 1 || scope != x.scopeHash
                || oldHash != x.oldValueHash || newHash != x.newValueHash
                || keccak256(raw)
                    != keccak256(abi.encode(executing, id, cls, scope, oldHash, newHash))
        ) revert T.InvalidRecord();
        bytes32 a = _consume(
            replay,
            o,
            keccak256("identity_authority.replay.governance_action"),
            keccak256(abi.encode(id, scope, oldHash, newHash)),
            p.importRoot
        );
        bytes32 b = _consume(
            replay,
            o,
            keccak256("identity_authority.replay.import_binding_key"),
            keccak256(abi.encode(p)),
            p.importRoot
        );
        StreamArtistHistoryState.commit(
            o.environment.core,
            o.environment.registry,
            p,
            actionId,
            StreamArtistHistoryProof.cap(o.environment.registry)
        );
        return StreamArtistIdentityState.Mutation(
            bytes32(0),
            keccak256(abi.encode(p, id)),
            StreamArtistHistoryState.commitment(),
            keccak256(abi.encode(a, b))
        );
    }

    function applyArtistHistoryLaneVerification(
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistIdentityState.OwnerContext memory o,
        address artistWindowAuthority,
        T.ActionContext memory c,
        uint256 index,
        H.Leaf memory p,
        bytes32[] memory proof
    ) public returns (StreamArtistIdentityState.Mutation memory) {
        H.Binding memory b = StreamArtistHistoryState.binding(index);
        bytes32 a = _consume(
            replay,
            o,
            keccak256("identity_authority.replay.verified_lane_key"),
            keccak256(abi.encode(p.laneKind, p.laneKey)),
            p.recordChainHash
        );
        bytes32 bound = _consume(
            replay,
            o,
            keccak256("identity_authority.replay.import_binding"),
            keccak256(abi.encode(index, p.laneKind, p.laneKey)),
            b.importRoot
        );
        StreamArtistHistoryState.verifyTip(
            o.environment.core,
            o.environment.registry,
            index,
            p,
            proof,
            StreamArtistHistoryProof.cap(o.environment.registry)
        );
        return StreamArtistIdentityState.Mutation(
            bytes32(0),
            keccak256(abi.encode(index, p, proof)),
            StreamArtistHistoryState.commitment(),
            keccak256(abi.encode(a, bound))
        );
    }

    function applyArtistRegistryCutover(
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistIdentityState.OwnerContext memory o,
        address artistWindowAuthority,
        T.ActionContext memory c
    ) public returns (StreamArtistIdentityState.Mutation memory) {
        bytes32 a = _consume(
            replay,
            o,
            keccak256("identity_authority.replay.one_way_cutover_latch"),
            bytes32(0),
            keccak256(abi.encode(block.number))
        );
        StreamArtistHistoryState.observe(
            o.environment.core,
            o.environment.registry,
            StreamArtistHistoryProof.cap(o.environment.registry)
        );
        return StreamArtistIdentityState.Mutation(
            bytes32(0),
            keccak256(abi.encode(c.actor, block.number)),
            StreamArtistHistoryState.commitment(),
            a
        );
    }

    function _consume(
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistIdentityState.OwnerContext memory o,
        bytes32 surface,
        bytes32 scope,
        bytes32 commitment
    ) private returns (bytes32 key) {
        key = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_OWNER_REPLAY_KEY_V2"),
                o.environment.chainId,
                o.environment.registry,
                o.coordinator,
                o.archive,
                address(this),
                o.domain,
                surface,
                scope
            )
        );
        if (replay[key].status != 0) revert T.Replay(key);
        replay[key] = T.ReplayCell(commitment, o.revision + 1, 1, 2);
        StreamArtistAuthorityCheckpoint.noteReplay(key, replay[key]);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "./StreamArtistIdentityState.sol";
import "./StreamArtistEstateState.sol";
import "./StreamArtistDormancyState.sol";
import "./StreamArtistUnavailabilityState.sol";
import "./StreamArtistEntropyFindingHydration.sol";
import {
    StreamArtistAuthorityHydrationTypes as AH
} from "../../interfaces/stream/artist/IStreamArtistAuthorityHydration.sol";

/// @notice Typed baseline export/import; advanced state never defaults to a living principal.
library StreamArtistIdentityHydration {
    function exportState(
        StreamArtistIdentityState.State storage s,
        StreamArtistEstateState.State storage estate,
        StreamArtistDormancyState.State storage dorm,
        StreamArtistUnavailabilityState.State storage finding,
        AH.Query memory q
    ) public view returns (bytes memory) {
        AH.Identity memory p;
        p.item = s.identities[q.artistId];
        if (
            p.item.authorityClass != 1 || p.item.status != 1 || s.nextRegistrationNonce != 1
                || s.activeIdentity[p.item.authorityAddress] != q.artistId
        ) revert T.UnsupportedProfile();
        p.document = s.documents[p.item.identityRecordHash];
        p.nextRegistrationNonce = s.nextRegistrationNonce;
        if (p.document.length == 0 || keccak256(p.document) != p.item.identityRecordHash) {
            revert T.InvalidRecord();
        }
        p.estateActivity = estate.livingActivity[q.artistId];
        p.dormancyActivity = dorm.activity[q.artistId];
        p.findingActivity = finding.activityEpoch[q.artistId];
        p.signatures = new bytes[](q.records.length);
        for (uint256 j; j < q.records.length; ++j) {
            p.signatures[j] = s.signatures[q.records[j]];
        }
        return abi.encode(p);
    }

    function importState(
        StreamArtistIdentityState.State storage s,
        StreamArtistEstateState.State storage estate,
        StreamArtistDormancyState.State storage dorm,
        StreamArtistUnavailabilityState.State storage finding,
        AH.Query memory q,
        AH.OwnerData memory data
    ) public {
        AH.Identity memory p = abi.decode(data.typedState, (AH.Identity));
        if (
            s.nextRegistrationNonce != 0 || s.identities[q.artistId].authorityAddress != address(0)
                || s.activeIdentity[p.item.authorityAddress] != 0 || p.item.authorityClass != 1
                || p.item.status != 1 || p.nextRegistrationNonce != 1
                || p.signatures.length != q.records.length
                || keccak256(p.document) != p.item.identityRecordHash
        ) revert T.InvalidRecord();
        s.identities[q.artistId] = p.item;
        s.activeIdentity[p.item.authorityAddress] = q.artistId;
        s.nextRegistrationNonce = p.nextRegistrationNonce;
        s.documents[p.item.identityRecordHash] = p.document;
        StreamArtistPayloadStore.store(keccak256("ARTIST_IDENTITY_DOCUMENT"), p.document);
        for (uint256 j; j < q.records.length; ++j) {
            s.signatures[q.records[j]] = p.signatures[j];
            StreamArtistPayloadStore.store(keccak256("ARTIST_SIGNATURE_BUNDLE"), p.signatures[j]);
        }
        estate.livingActivity[q.artistId] = p.estateActivity;
        dorm.activity[q.artistId] = p.dormancyActivity;
        finding.activityEpoch[q.artistId] = p.findingActivity;
        for (uint256 j; j < data.nonces.length; ++j) {
            AH.NonceWord memory n = data.nonces[j];
            uint256 prefix = n.prefix;
            for (uint8 level; level < 32; ++level) {
                uint256 old = s.nonceAvailability[q.artistId].full[level][prefix];
                if (old != 0 && old != n.words[level]) revert T.InvalidRecord();
                s.nonceAvailability[q.artistId].full[level][prefix] = n.words[level];
                prefix >>= 8;
            }
            s.nonceAvailability[q.artistId].exhausted = n.exhausted;
            StreamArtistAuthorityCheckpoint.noteNonce(
                1, q.artistId, n.prefix, keccak256(abi.encode(n))
            );
        }
        (bool available, uint256 hint) =
            StreamArtistNonceAvailability.firstUnused(s.nonceAvailability[q.artistId]);
        if (!available || hint != p.item.nonceHint) revert T.InvalidRecord();
    }

    /// @dev Decode original owner calldata in the fixed worker, avoiding owner-side nested re-encoding.
    function exportEncoded(
        StreamArtistIdentityState.State storage s,
        StreamArtistEstateState.State storage estate,
        StreamArtistDormancyState.State storage dorm,
        StreamArtistUnavailabilityState.State storage finding,
        bytes calldata encoded
    ) public view returns (bytes memory) {
        AH.Query memory q = abi.decode(encoded, (AH.Query));
        return exportState(s, estate, dorm, finding, q);
    }

    function exportFindingEncoded(
        StreamArtistIdentityState.State storage s,
        StreamArtistEstateState.State storage estate,
        StreamArtistDormancyState.State storage dorm,
        StreamArtistUnavailabilityState.State storage finding,
        bytes calldata encoded
    ) public view returns (bytes memory) {
        AH.Query memory q = abi.decode(encoded, (AH.Query));
        return StreamArtistEntropyFindingHydration.exportState(
            finding, q, exportState(s, estate, dorm, finding, q)
        );
    }

    function importEncoded(
        StreamArtistIdentityState.State storage s,
        StreamArtistEstateState.State storage estate,
        StreamArtistDormancyState.State storage dorm,
        StreamArtistUnavailabilityState.State storage finding,
        bytes calldata encoded
    ) public {
        (, AH.Query memory q, AH.OwnerData memory data,) =
            abi.decode(encoded, (T.ActionContext, AH.Query, AH.OwnerData, bytes32));
        if (StreamArtistEntropyFindingHydration.isState(data.typedState)) {
            FH.Bundle memory b = StreamArtistEntropyFindingHydration.decode(data.typedState);
            data.typedState = b.identityState;
            importState(s, estate, dorm, finding, q, data);
            StreamArtistEntropyFindingHydration.importState(finding, q, b);
        } else {
            importState(s, estate, dorm, finding, q, data);
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamArtistEconomicOperations.sol";
import "./StreamArtistAttestationOperations.sol";
import "./StreamArtistIdentityRevisionState.sol";
import "./StreamArtistRecordPublicationReads.sol";
import "../../interfaces/stream/artist/IStreamArtistCurrentBindingOwner.sol";

/// @notice Typed identity recipes in the guarded Coordinator's delegatecall context.
library StreamArtistIdentityOperations {
    function revise(
        D.CoordinatorContext memory x,
        address actor,
        StreamArtistIdentityRevisionTypes.Revision memory p,
        T.Authorization memory submitted,
        bytes memory document,
        string memory displayName
    ) public returns (bytes32 record) {
        T.Snapshot[7] memory before_ = _snapshots(x, 25);
        (address signer, uint8 class_, uint8 status,) =
            IStreamArtistIdentityOwner(x.suite.owners[2]).authorityState(p.artistId);
        if (!StreamArtistAuthorityPolicy.ordinary(class_, status, false)) {
            revert T.InvalidIdentity(p.artistId);
        }
        T.Authorization memory effective = _directTime(actor, signer, submitted);
        T.SignerApproval memory proof = _verify(
            x,
            actor,
            signer,
            StreamArtistIdentityRevisionState.digest(_environment(x), p, effective),
            effective.signature
        );
        record = IStreamArtistIdentityRevisionOwner(x.suite.owners[2])
            .recordIdentityRevision(
                T.ActionContext(25, actor, before_[2]), p, effective, proof, document, displayName
            );
        _archive(
            x,
            25,
            actor,
            record,
            before_,
            abi.encode(p, submitted, document, displayName, proof, effective)
        );
    }

    function validateProposalIdentity(
        address owner,
        T.BindingProposal memory p,
        bytes memory document,
        string memory displayName
    ) public view {
        IStreamArtistIdentityOwner identity = IStreamArtistIdentityOwner(owner);
        (address authority, uint8 class_, uint8 status,) = identity.authorityState(p.artistId);
        (bytes32 hash, string memory uri, string memory name) =
            IStreamArtistIdentityRevisionOwner(owner).operativeIdentityMetadata(p.artistId);
        if (
            !StreamArtistAuthorityPolicy.ordinary(class_, status, false)
                || authority != p.artistAddress || hash != p.identityRecordHash
                || identity.activeIdentity(p.artistAddress) != p.artistId
                || keccak256(document) != hash
                || keccak256(bytes(displayName)) != keccak256(bytes(name))
                || keccak256(bytes(p.identityRecordURI)) != keccak256(bytes(uri))
        ) {
            revert T.InvalidIdentity(p.artistId);
        }
    }

    function attest(
        D.CoordinatorContext memory x,
        address actor,
        T.Attestation memory p,
        T.Authorization memory submitted,
        bytes memory statement
    ) public returns (bytes32 record) {
        if (p.subjectKind >= 1 && p.subjectKind <= 6) {
            Attest.Subject memory subject;
            return StreamArtistAttestationOperations.attest(
                x, actor, p, subject, false, 0, submitted, statement
            );
        }
        if (p.subjectKind == 7 || p.subjectKind == 8) {
            return _publicationAttestation(x, actor, p, submitted, statement);
        }
        T.Snapshot[7] memory before_ = _snapshots(x, 24);
        T.Binding memory b = StreamArtistOnboardingReads(x.reads).acceptedBinding(p.collectionId);
        if (!IStreamCoreCollectionView(x.suite.core).collectionExists(p.collectionId)) {
            revert T.InvalidAttribution(p.collectionId);
        }
        R.AuthorityFact memory authority =
            StreamArtistCurrentAuthorityFacts.read(x.suite.owners[2], b.artistId, false);
        T.Authorization memory effective = _directTime(actor, authority.authorityAddress, submitted);
        T.SignerApproval memory proof = _verify(
            x,
            actor,
            authority.authorityAddress,
            StreamArtistHashes.attestationDigest(_environment(x), p, effective),
            effective.signature
        );
        bytes32 operative;
        if (p.subjectKind == 10) {
            operative = IStreamArtistIdentityRevisionReads(x.suite.owners[2])
                .operativeIdentityRecord(b.artistId);
        }
        record = IStreamArtistIdentityOwner(x.suite.owners[2])
            .consumeAttestation(T.ActionContext(24, actor, before_[2]), b, p, effective, proof);
        bytes32 actual = IStreamArtistCurrentAttributionOwner(x.suite.owners[4])
            .recordAttestationWithAuthority(
                T.ActionContext(24, actor, before_[4]),
                b,
                p,
                operative,
                authority,
                proof.signer,
                effective.nonce,
                effective.time,
                statement
            );
        if (actual != record) revert T.InvalidRecord();
        bytes memory payload = submitted.time == effective.time
            ? abi.encode(b, p, submitted, statement, proof)
            : abi.encode(b, p, submitted, statement, proof, effective);
        if (p.subjectKind == 10) payload = abi.encode(payload, operative);
        payload = abi.encode(payload, authority);
        _archive(x, 24, actor, record, before_, payload);
    }

    function _publicationAttestation(
        D.CoordinatorContext memory x,
        address actor,
        T.Attestation memory p,
        T.Authorization memory submitted,
        bytes memory statement
    ) private returns (bytes32 record) {
        T.Snapshot[7] memory before_ = _snapshots(x, 24);
        T.Binding memory b = StreamArtistRecordPublicationReads.binding(x.suite, p.collectionId);
        (P.Publication memory publication,) =
            StreamArtistRecordPublicationRules.decode(p, statement);
        R.AuthorityFact memory authority =
            StreamArtistCurrentAuthorityFacts.read(x.suite.owners[2], b.artistId, false);
        if (publication.recorder != authority.authorityAddress) revert T.InvalidRecord();
        bytes32 hostCodeHash = StreamArtistRecordPublicationReads.candidate(x.suite, publication);
        T.Authorization memory effective = _directTime(actor, authority.authorityAddress, submitted);
        T.SignerApproval memory proof = _verify(
            x,
            actor,
            authority.authorityAddress,
            StreamArtistHashes.attestationDigest(_environment(x), p, effective),
            effective.signature
        );
        record = IStreamArtistIdentityOwner(x.suite.owners[2])
            .consumeAttestation(T.ActionContext(24, actor, before_[2]), b, p, effective, proof);
        bytes32 actual = IStreamArtistRecordPublicationOwner(x.suite.owners[4])
            .recordPublicationAttestation(
                T.ActionContext(24, actor, before_[4]),
                b,
                p,
                authority,
                effective.nonce,
                effective.time,
                statement,
                hostCodeHash
            );
        if (actual != record) revert T.InvalidRecord();
        _archive(
            x,
            24,
            actor,
            record,
            before_,
            abi.encode(
                b, p, submitted, statement, proof, effective, authority, publication, hostCodeHash
            )
        );
    }

    function _directTime(address actor, address signer, T.Authorization memory submitted)
        private
        view
        returns (T.Authorization memory effective)
    {
        effective = T.Authorization(submitted.nonce, submitted.time, submitted.signature);
        if (
            actor == signer && actor != address(0) && submitted.signature.length == 0
                && submitted.time == 0
        ) {
            if (block.timestamp > type(uint64).max) revert T.InvalidRecord();
            effective.time = uint64(block.timestamp);
        }
    }

    function _verify(
        D.CoordinatorContext memory x,
        address actor,
        address signer,
        bytes32 digest,
        bytes memory signature
    ) private view returns (T.SignerApproval memory) {
        if (actor == address(0) || signer == address(0)) {
            revert T.InvalidSignature();
        }
        bool direct = actor == signer && signature.length == 0;
        if (!direct) {
            (uint256 cap,, uint8 failure, uint64 revision) = IStreamGasParameterHost(
                    x.suite.registry
                ).gasParameterInfo(keccak256("6529STREAM_GGP_ARTIST_ERC1271_VERIFY_GAS"));
            if (
                failure != 2 || revision == 0
                    || !StreamArtistRegistryValidatorBase(x.suite.validator)
                        .validateSignerProof(signer, digest, signature, cap)
            ) revert T.InvalidSignature();
        }
        return T.SignerApproval(signer, digest, direct);
    }

    function _environment(D.CoordinatorContext memory x)
        private
        view
        returns (StreamArtistHashes.Environment memory)
    {
        return StreamArtistHashes.Environment(
            block.chainid, x.suite.registry, x.suite.core, x.suite.mintManager
        );
    }

    function _snapshots(D.CoordinatorContext memory x, uint16 op)
        private
        view
        returns (T.Snapshot[7] memory result)
    {
        uint256 mask = op == 25 ? 0x04 : 0x17;
        for (uint256 i; i < 7; ++i) {
            if ((mask & (1 << i)) != 0) {
                result[i] = IStreamArtistOwner(x.suite.owners[i]).ownerStateSnapshotV2();
            }
        }
    }

    function _archive(
        D.CoordinatorContext memory x,
        uint16 op,
        address actor,
        bytes32 record,
        T.Snapshot[7] memory before_,
        bytes memory payload
    ) private {
        bytes32 id = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_ONBOARDING_OPERATION_EVIDENCE_V1"),
                block.chainid,
                x.suite.registry,
                address(this),
                op,
                actor,
                record
            )
        );
        bytes memory evidence = abi.encode(
            uint16(1), x.configurationHash, op, actor, record, before_, _snapshots(x, op), payload
        );
        (bytes32 hash,, bool appended) =
            IStreamArtistArchiveV2(x.suite.archive).appendArtistEvidenceV2(id, 1, evidence);
        if (!appended || hash != keccak256(evidence)) revert T.InvalidRecord();
    }
}

