        item.standingTailSeconds = c.standingTailSeconds;
        item.timingRevision = c.timingRevision;
        {
            bytes32 acceptanceDelta = StreamArtistRotationState.acceptIdentityRecovery(
                rotations,
                replay,
                i.owner,
                i.action,
                R.Rotation(
                    i.request.artistId,
                    c.incumbent,
                    i.request.newAddress,
                    i.request.reasonHash,
