/// @notice Constructor-fixed typed Identity writers, executed only in their bound owner.
/// @dev No fallback or routing table. Direct state reads/writes reject; immutable getters
///      expose only truthful construction pins. Every semantic commit remains the owner.
contract StreamArtistIdentityWriterExtension is
    StreamArtistOwner,
    StreamArtistIdentityData,
    IStreamArtistIdentityDismissalEvents,
    IStreamArtistEstateEvents,
    IStreamArtistUnavailabilityEvents
{
    error InvalidTimestamp(uint64 timestamp);
    error ExtensionWrongHost(address actual);
    error DelegationUnavailable(bytes32 recordHash);
    address private immutable _host;

    constructor(
        address host_,
        address registry_,
        address coordinator_,
        address archive_,
        address core_,
        address manager_
    )
        StreamArtistOwner(
            registry_,
            coordinator_,
            archive_,
            keccak256("domain:identity_authority"),
            core_,
            manager_
        )
    {
        if (host_ == address(0) || host_ == address(this)) revert T.InvalidBinding();
        _host = host_;
    }

    modifier onlyHost() {
        if (address(this) != _host) revert ExtensionWrongHost(address(this));
        _;
    }

    function registerIdentity(
        T.ActionContext calldata c,
        address artist,
        bytes32 documentHash,
        string calldata uri,
        bytes calldata document,
        string calldata displayName
    ) external onlyHost returns (bytes32) {
        _check(c, 1);
        StreamArtistIdentityState.Mutation memory m =
            StreamArtistIdentityWriterTransport.registerEncoded(
                _identity, _replay, _ownerContext(), msg.data
            );
        _commit(c, m.action, m.state, m.replay, m.record);
        _native(c.operationId, m.record, m.record, 0);
        return m.record;
    }

    function revokeDelegation(
        T.ActionContext calldata c,
        D.Revocation calldata p,
        T.Authorization calldata a,
        T.SignerApproval calldata proof
    ) external onlyHost returns (bytes32 record) {
        _check(c, 27);
        _deadline(a.time);
        StreamArtistIdentityState.Mutation memory m =
            StreamArtistIdentityWriterTransport.revokeGrantEncoded(
                _identity, _replay, _delegations, _ownerContext(), msg.data
            );
        _noteLiving(_ownerContext(), _replay, p.artistId, proof.signer, c.operationId, m);
        _commit(c, m.action, m.state, m.replay, m.record);
        _native(c.operationId, m.record, p.artistId, 0);
        return m.record;
    }

    function dismissIdentityContest(
        T.ActionContext calldata c,
        Dismissal.Request calldata p,
        Contest.GovernanceWitness calldata governance
    ) external onlyHost returns (bytes32) {
        _check(c, 58);
        address executor = IStreamArtistIdentityContestOwner(address(this)).artistWindowAuthority();
        StreamArtistIdentityState.Mutation memory m =
            StreamArtistIdentityWriterTransport.dismissEncoded(
                _resolutions,
                _identity,
                _rotations,
                _identityRevisions,
                _succession,
                _replay,
                _ownerContext(),
                executor,
                msg.data
            );
        _commit(c, m.action, m.state, m.replay, m.record);
        _native(c.operationId, m.record, p.artistId, 0);
        return m.record;
    }

    function grantDelegation(
        T.ActionContext calldata c,
        D.Grant calldata p,
        T.Authorization calldata a,
        T.SignerApproval calldata proof
    ) external onlyHost returns (bytes32 record) {
        _check(c, 26);
        StreamArtistSuccessionState.requireAllowed(
            _succession, _rotations, p.artistId, p.capabilities
        );
        if (a.time != 0) revert T.InvalidRecord();
        StreamArtistIdentityState.Mutation memory m =
            StreamArtistIdentityWriterTransport.grantEncoded(
                _identity, _replay, _delegations, _ownerContext(), msg.data
            );
        _estate.grantEpoch[m.record] = _estate.delegationEpoch[p.artistId];
        _noteLiving(_ownerContext(), _replay, p.artistId, proof.signer, c.operationId, m);
        _commit(c, m.action, m.state, m.replay, m.record);
        _native(c.operationId, m.record, p.artistId, 0);
        return m.record;
    }

    function recordSuccessorDesignation(
        T.ActionContext calldata c,
        Succ.Designation calldata p,
        T.Authorization calldata a,
        T.SignerApproval calldata proof
    ) external onlyHost returns (bytes32) {
        _check(c, 36);
        // A fresh original designation cannot reactivate a permanently superseded directive.
        if (_recoveryRewinds.statuses[p.directiveHash].recoveryRecordHash != 0) {
            revert Succ.InvalidDirective();
        }
        StreamArtistIdentityState.Mutation memory m =
            StreamArtistIdentityWriterTransport.designateEncoded(
                _succession, _identity, _rotations, _resolutions, _replay, _ownerContext(), msg.data
            );
        _noteLiving(_ownerContext(), _replay, p.artistId, proof.signer, c.operationId, m);
        _commit(c, m.action, m.state, m.replay, m.record);
        _native(c.operationId, m.record, p.artistId, 0);
        return m.record;
    }

    function recordEstateDirective(
        T.ActionContext calldata c,
        Succ.Directive calldata p,
        T.Authorization calldata a,
        T.SignerApproval calldata proof,
        Succ.PublicDocument calldata document
    ) external onlyHost returns (bytes32) {
        _check(c, 37);
        StreamArtistIdentityState.Mutation memory m =
            StreamArtistIdentityWriterTransport.directiveEncoded(
                _succession, _identity, _rotations, _resolutions, _replay, _ownerContext(), msg.data
            );
        _noteLiving(_ownerContext(), _replay, p.artistId, proof.signer, c.operationId, m);
        _commit(c, m.action, m.state, m.replay, m.record);
        _native(c.operationId, m.record, p.artistId, 0);
        return m.record;
    }

    function ownerStateSnapshotV2() public view override onlyHost returns (T.Snapshot memory) {
        return super.ownerStateSnapshotV2();
    }

    function replayCell(bytes32 key) public view override onlyHost returns (T.ReplayCell memory) {
        return _replay[key];
    }

    function recordIdentityRevision(
        T.ActionContext calldata c,
        StreamArtistIdentityRevisionTypes.Revision calldata p,
        T.Authorization calldata a,
        T.SignerApproval calldata proof,
        bytes calldata document,
        string calldata displayName
    ) external onlyHost returns (bytes32) {
        _check(c, 25);
        StreamArtistIdentityState.Mutation memory m =
            StreamArtistRecoveryRewindContinuationMutation.reviseEncoded(
                _recoveryRewinds,
                _identityRevisions,
                _identity,
                _rotations,
                _resolutions,
                _replay,
                _ownerContext(),
                msg.data
            );
        _noteLiving(_ownerContext(), _replay, p.artistId, proof.signer, c.operationId, m);
        _commit(c, m.action, m.state, m.replay, m.record);
        _native(c.operationId, m.record, p.artistId, 0);
        return m.record;
    }

    function revokeAuthorization(
        T.ActionContext calldata c,
        StreamArtistAuthorizationTypes.Revocation calldata p,
        T.Authorization calldata a,
        T.SignerApproval calldata proof
    ) external onlyHost returns (bytes32) {
        _check(c, 54);
        StreamArtistIdentityState.Mutation memory m =
            StreamArtistIdentityWriterTransport.revokeEncoded(
                _identity, _replay, _ownerContext(), msg.data
            );
        _noteLiving(_ownerContext(), _replay, p.artistId, proof.signer, c.operationId, m);
        _commit(c, m.action, m.state, m.replay, m.record);
        _native(c.operationId, m.record, p.artistId, 0);
        return m.record;
    }

    function _forwardEstateWriterCompatibility() private {
        address target =
            IStreamArtistIdentityEstateWriterHost(address(this)).identityEstateExtension();
        assembly ("memory-safe") {
            let pointer := mload(0x40)
            calldatacopy(pointer, 0, calldatasize())
            let success := delegatecall(gas(), target, pointer, calldatasize(), 0, 0)
            returndatacopy(pointer, 0, returndatasize())
            if iszero(success) { revert(pointer, returndatasize()) }
            return(pointer, returndatasize())
        }
    }

    function _ownerContext() private view returns (StreamArtistIdentityState.OwnerContext memory) {
        return StreamArtistIdentityState.OwnerContext(
            _environment(), operationCoordinator, archiveV2, domainId, _revision
        );
    }

    function registerCollaboratorIdentity(
        T.ActionContext calldata c,
        C.IdentityProposal calldata p,
        T.Authorization calldata a,
        T.SignerApproval calldata proof,
        bytes calldata document,
        string calldata displayName
    ) external onlyHost returns (bytes32) {
        _check(c, 6);
        _deadline(a.time);
        StreamArtistIdentityState.Mutation memory m =
            StreamArtistIdentityWriterTransport.collaboratorEncoded(
                _identity, _collaboratorAccounts, _replay, _ownerContext(), msg.data
            );
        _commit(c, m.action, m.state, m.replay, m.record);
        _native(c.operationId, m.record, m.record, 0);
        return m.record;
    }

    function consumeCollaboratorAcceptance(
        T.ActionContext calldata c,
        C.BindingAcceptance calldata p,
        bytes32 artistId,
        T.Authorization calldata a,
        T.SignerApproval calldata proof
    ) external onlyHost returns (bytes32 record) {
        _check(c, 7);
        _deadline(a.time);
        if (proof.signer != p.account) revert T.InvalidSignature();
        record = StreamArtistCollaboratorHashes.acceptanceRecordForAuthority(
            _environment(), p, _identity.identities[artistId].authorityClass, a.nonce, _now()
        );
        _authorize(
            c,
            artistId,
            a,
            proof,
            StreamArtistCollaboratorHashes.acceptanceDigest(_environment(), p, a),
            record
        );
    }

    function consumeDelegatedEconomics(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.EconomicsConsent calldata p,
        bytes32 designation,
        bytes32 grant,
        T.Authorization calldata a,
        T.SignerApproval calldata proof
    ) external onlyHost returns (bytes32 record) {
        _forwardEstateWriterCompatibility();
    }

    function consumeDelegatedRoyaltyFreeze(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.RoyaltyFreeze calldata p,
        bytes32 grant,
        T.Authorization calldata a,
        T.SignerApproval calldata proof
    ) external onlyHost returns (bytes32 record) {
        _forwardEstateWriterCompatibility();
    }

    function consumeAcceptance(
        T.ActionContext calldata c,
        uint256 collectionId,
        T.Binding calldata b,
        T.Authorization calldata a,
        T.SignerApproval calldata proof
    ) external onlyHost returns (bytes32 record) {
        _check(c, 2);
        return _consumeAndCommit(c, b.artistId, proof.signer);
    }

    function consumeRefusal(
        T.ActionContext calldata c,
        T.Binding calldata b,
        L.Termination calldata p,
        T.Authorization calldata a,
        T.SignerApproval calldata proof
    ) external onlyHost returns (bytes32 record) {
        _check(c, 3);
        return _consumeAndCommit(c, b.artistId, proof.signer);
    }

    function consumeSaleConsent(
        T.ActionContext calldata c,
        T.Binding calldata b,
        Sale.Consent calldata p,
        T.Authorization calldata a,
        T.SignerApproval calldata proof
    ) external onlyHost returns (bytes32 record) {
        _check(c, 16);
        return _consumeAndCommit(c, b.artistId, proof.signer);
    }

    function consumePolicy(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.PolicyConsent calldata p,
        T.Authorization calldata a,
        T.SignerApproval calldata proof
    ) external onlyHost returns (bytes32 record) {
        _check(c, 14);
        return _consumeAndCommit(c, b.artistId, proof.signer);
    }

    function consumeEconomics(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.EconomicsConsent calldata p,
        bytes32 designation,
        T.Authorization calldata a,
        T.SignerApproval calldata proof
    ) external onlyHost returns (bytes32 record) {
        _check(c, 15);
        return _consumeAndCommit(c, b.artistId, proof.signer);
    }

    function consumePayout(
        T.ActionContext calldata c,
        T.PayoutDesignation calldata p,
        T.Authorization calldata a,
        T.SignerApproval calldata proof
    ) external onlyHost returns (bytes32 record) {
        _check(c, 18);
        return _consumeAndCommit(c, p.artistId, proof.signer);
    }

    function consumeDelegatedAttestation(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.Attestation calldata p,
        bytes32 grant,
        T.Authorization calldata a,
        T.SignerApproval calldata proof
    ) external onlyHost returns (bytes32 record) {
        _forwardEstateWriterCompatibility();
    }

    function consumeAttestation(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.Attestation calldata p,
        T.Authorization calldata a,
        T.SignerApproval calldata proof
    ) external onlyHost returns (bytes32 record) {
        _check(c, 24);
        return _consumeAndCommit(c, b.artistId, proof.signer);
    }

    function consumeRatification(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.Ratification calldata p,
        T.Authorization calldata a,
        T.SignerApproval calldata proof
    ) external onlyHost returns (bytes32 record) {
        _check(c, 52);
        return _consumeAndCommit(c, b.artistId, proof.signer);
    }

    function consumeRoyaltyFreeze(
        T.ActionContext calldata c,
        T.Binding calldata b,
        T.RoyaltyFreeze calldata p,
        T.Authorization calldata a,
        T.SignerApproval calldata proof
    ) external onlyHost returns (bytes32 record) {
        _check(c, 20);
        return _consumeAndCommit(c, b.artistId, proof.signer);
    }

    function consumeContentConsent(
        T.ActionContext calldata c,
        T.Binding calldata b,
        Content.Consent calldata p,
        T.Authorization calldata a,
        T.SignerApproval calldata proof
    ) external onlyHost returns (bytes32 record) {
        _check(c, 17);
        return _consumeAndCommit(c, b.artistId, proof.signer);
    }

    function consumeContentFreeze(
        T.ActionContext calldata c,
        T.Binding calldata b,
        Content.Freeze calldata p,
        T.Authorization calldata a,
        T.SignerApproval calldata proof
    ) external onlyHost returns (bytes32 record) {
        _check(c, 21);
        return _consumeAndCommit(c, b.artistId, proof.signer);
    }

    function _authorize(
        T.ActionContext calldata c,
        bytes32 artistId,
        T.Authorization calldata a,
        T.SignerApproval calldata proof,
        bytes32 digest,
        bytes32 record
    ) private {
        StreamArtistIdentityState.Mutation memory m =
            StreamArtistIdentityState.authorize(
                _identity,
                _replay,
                _ownerContext(),
                c,
                artistId,
                a,
                proof,
                digest,
                record,
                _identity.identities[artistId].authorityAddress
            );
        _noteLiving(_ownerContext(), _replay, artistId, proof.signer, c.operationId, m);
        _commit(c, m.action, m.state, m.replay, m.record);
    }

    function _deadline(uint64 deadline) private view {
        if (block.timestamp > deadline) revert T.ExpiredAuthorization(deadline);
    }

    function _signedAt(uint64 time) private view {
        if (time == 0 || time > block.timestamp) revert T.InvalidTimestamp(time);
    }

    function consumeAttributionDispute(
        T.ActionContext calldata c,
        AD.Filing calldata p,
        T.Binding calldata b,
        AD.Standing calldata standing,
        T.Authorization calldata a,
        T.SignerApproval calldata proof
    ) external onlyHost returns (bytes32) {
        _check(c, p.disputeAction == 2 ? 61 : p.disputeAction == 1 ? 44 : 45);
        (StreamArtistIdentityState.Mutation memory m, bytes32 record) = StreamArtistIdentityWriterTransport.disputeEncoded(
            _identity,
            _replay,
            _estate,
            _succession,
            _rotations,
            _delegations,
            _unavailability,
            _dormancy,
            _ownerContext(),
            msg.data
        );
        if (standing.delegation == 0) {
            _noteLiving(_ownerContext(), _replay, standing.artistId, proof.signer, c.operationId, m);
        }
        _commit(c, m.action, m.state, m.replay, m.record);
        return record;
    }

    function consumeRepudiation(
        T.ActionContext calldata c,
        AD.Filing calldata p,
        RP.Admission calldata admission,
        T.Authorization calldata a,
        T.SignerApproval calldata proof
    ) external onlyHost returns (bytes32) {
        _check(c, 47);
        (StreamArtistIdentityState.Mutation memory m, bytes32 record) = StreamArtistRepudiationIdentityMutation.consume(
            _identity, _replay, _ownerContext(), msg.data[4:]
        );
        _noteLiving(_ownerContext(), _replay, admission.binding_.artistId, proof.signer, 47, m);
        _commit(c, m.action, m.state, m.replay, m.record);
        return record;
    }

    function contestRepudiation(T.ActionContext calldata c, RP.GuardianProof calldata proof)
        external
        onlyHost
        returns (bytes32)
    {
        _check(c, 48);
        (StreamArtistIdentityState.Mutation memory m, bytes32 artistId) = StreamArtistRepudiationIdentityMutation.contest(
            _identity,
            _rotations,
            _identityContests,
            _resolutions,
            _estate,
            _identityRecovery,
            _dormancy,
            _replay,
            _ownerContext(),
            msg.data[4:]
        );
        _commit(c, m.action, m.state, m.replay, m.record);
        _native(48, m.record, artistId, proof.collectionId);
        _native(48, _resolutions.currentCause[artistId], artistId, proof.collectionId);
        return m.record;
    }

    function noteRepudiationCancellation(T.ActionContext calldata c, RP.Record calldata record)
        external
        onlyHost
    {
        _check(c, 49);
        StreamArtistRepudiationAdmission.cancellation(
            StreamArtistRepudiationAdmission.suite(
                _environment().registry, _ownerContext().coordinator
            ),
            c,
            record
        );
        StreamArtistIdentityState.Mutation memory m;
        m.action = keccak256(abi.encode(c.actor, record.recordHash));
        m.state = keccak256(abi.encode(record.recordHash, uint8(3)));
        _noteLiving(_ownerContext(), _replay, record.artistId, c.actor, 49, m);
        _commit(c, m.action, m.state, m.replay, 0);
    }
    function _consumeAndCommit(T.ActionContext calldata c, bytes32 artistId, address signer)
        private returns (bytes32 record)
    {
        StreamArtistIdentityState.Mutation memory m;
        (m, record) = StreamArtistIdentityConsentMutation.consume(
            _identity, _replay, _ownerContext(), c.operationId, msg.data[4:]
        );
        _noteLiving(_ownerContext(), _replay, artistId, signer, c.operationId, m);
        _commit(c, m.action, m.state, m.replay, m.record);
    }
}

