            if (
                row.bindingHash == 0 || records[row.bindingHash] != 0 || row.state.record == 0
                    || row.state.acceptedAt == 0
            ) revert T.InvalidRecord();
            records[row.bindingHash] = row.state.record;
            times[row.bindingHash] = row.state.acceptedAt;
        }
    }

