pragma solidity ^0.8.19;
import {
    StreamArtistDelegationTypes as D
} from "../../interfaces/stream/artist/StreamArtistDelegationTypes.sol";
import {
    StreamArtistHistoryTypes as H
} from "../../interfaces/stream/artist/IStreamArtistHistory.sol";
import {
    StreamArtistMultipleHydrationTypes as MH
} from "../../interfaces/stream/artist/IStreamArtistMultipleAuthorityHydration.sol";
import "../../interfaces/stream/artist/IStreamArtistDelegationAuthorityHydration.sol";
import "./StreamArtistMultipleHydrationOperations.sol";
import "./StreamArtistMultipleDelegationCodec.sol";
import "./StreamArtistMultipleDelegationFacts.sol";
import "./StreamArtistHydrationPrepared.sol";
import "./StreamArtistHydrationSourceGuards.sol";

/// @notice A partition of the complete fixed source, never independent subject completeness claims.
library StreamArtistMultipleDelegationSource {
    function prepare(
        D.CoordinatorContext memory x,
        MH.Request memory p,
        T.SuiteConfiguration memory s,
        address prior,
        address coordinator
    ) public view returns (StreamArtistHydrationPrepared.Bundle memory h) {
        h.profile = MD.PROFILE;
        h.prior = prior;
        h.source = s;
        h.sourceCoordinator = coordinator;
        for (uint256 i; i < 7; ++i) {
            h.before_[i] = IStreamArtistOwner(x.suite.owners[i]).ownerStateSnapshotV2();
            if (
                h.before_[i].revision
                        != (i == 2 ? 1 + p.artistIds.length + p.collections.length : 0)
                    || IStreamArtistNativeReceipts(x.suite.owners[i]).artistNativeReceiptCount()
                        != 0
                    || IStreamArtistAuthorityHydrationOwner(x.suite.owners[i])
                            .authorityHydrationCommitment() != 0
            ) revert T.InvalidRecord();
            StreamArtistHydrationSourceGuards._multipleHeader(s.owners[i], p.expectedSource[i]);
        }
        MD.Inventory memory inv = _inventory(s, p);
        IStreamArtistHistory history = IStreamArtistHistory(x.suite.owners[2]);
        for (uint256 i; i < p.artistIds.length; ++i) {
            StreamArtistHydrationSourceGuards._lane(history, prior, 1, p.artistIds[i]);
            (, uint64 count) = IStreamArtistHistory(prior).artistHistoryLane(1, p.artistIds[i]);
            if (count != inv.artists[i].records.length) revert T.InvalidRecord();
        }
        uint256[] memory ids = new uint256[](p.collections.length);
        for (uint256 i; i < p.collections.length; ++i) {
            ids[i] = p.collections[i].collectionId;
            StreamArtistHydrationSourceGuards._lane(history, prior, 2, bytes32(ids[i]));
            (, uint64 count) = IStreamArtistHistory(prior).artistHistoryLane(2, bytes32(ids[i]));
            uint256 expected = 2;
            for (uint256 j; j < inv.receipts[6].length; ++j) {
                if (inv.receipts[6][j].collectionId == ids[i]) ++expected;
            }
            if (count != expected) revert T.InvalidRecord();
        }
        MD.Identities memory identities;
        identities.rows = new MD.IdentityRow[](p.artistIds.length);
        identities.collectionIds = ids;
        for (uint256 i; i < p.artistIds.length; ++i) {
            identities.rows[i].artistId = p.artistIds[i];
            identities.rows[i].records = inv.artists[i].records;
            identities.rows[i].state = IStreamArtistDelegationHydrationOwner(s.owners[2])
                .authorityDelegationHydrationState(inv.artists[i]);
        }
        _nonces(s.owners[2], p, identities);
        MD.Collections memory collections = _collections(s, inv);
        StreamArtistMultipleDelegationFacts.check(s, p, inv, identities, collections);
        for (uint256 i; i < 7; ++i) {
            h.data[i] = StreamArtistMultipleHydrationOperations._replay(s, coordinator, i, p);
            if (i != 2 && p.expectedSource[i].nonceIndexCount != 0) revert T.UnsupportedProfile();
        }
        h.data[0].typedState = abi.encode(MD.BINDING, collections.bindings);
        h.data[2].typedState = abi.encode(MD.IDENTITY, identities);
        h.data[3].typedState = abi.encode(MD.ACCEPTANCE, collections.acceptances);
        h.data[4].typedState = abi.encode(MD.ATTRIBUTION, collections.attributions);
        h.data[6].typedState = abi.encode(MD.CONSENT, collections.consents);
        h.q = inv.collections[0];
    }

    function _inventory(T.SuiteConfiguration memory s, MH.Request memory p)
        private
        view
        returns (MD.Inventory memory v)
    {
        v.artists = new AH.Query[](p.artistIds.length);
        v.collections = new AH.Query[](p.collections.length);
        uint256 policies;
        for (uint256 i; i < p.artistIds.length; ++i) {
            v.artists[i].artistId = p.artistIds[i];
        }
        for (uint256 i; i < p.collections.length; ++i) {
            v.collections[i].artistId = p.collections[i].artistId;
            v.collections[i].collectionId = p.collections[i].collectionId;
            v.collections[i].policies = p.collections[i].policies;
            policies += p.collections[i].policies.length;
        }
        if (policies > 128) revert T.UnsupportedProfile();
        uint256[] memory artistCounts = new uint256[](p.artistIds.length);
        bool[] memory registered = new bool[](p.artistIds.length);
        bool[] memory accepted = new bool[](p.collections.length);
        uint256[] memory policyCounts = new uint256[](p.collections.length);
        uint256 registrations;
        for (uint256 i; i < 7; ++i) {
            uint256 n = IStreamArtistNativeReceipts(s.owners[i]).artistNativeReceiptCount();
            if (n > 128) revert T.UnsupportedProfile();
            if ((i == 0 || i == 3) && n != p.collections.length) revert T.UnsupportedProfile();
            if ((i == 1 || i == 4 || i == 5) && n != 0) revert T.UnsupportedProfile();
            v.receipts[i] = new H.Receipt[](n);
            for (uint256 j; j < n; ++j) {
                H.Receipt memory r =
                    IStreamArtistNativeReceipts(s.owners[i]).artistNativeReceiptAt(j);
                v.receipts[i][j] = r;
                uint256 a = StreamArtistMultipleHydrationOperations._artist(p.artistIds, r.artistId);
                if (r.recordHash == 0) revert T.InvalidRecord();
                ++artistCounts[a];
                if (i == 2) {
                    if (r.collectionId != 0) revert T.UnsupportedProfile();
                    if (r.operation == 1) {
                        if (registered[a] || r.recordHash != r.artistId) revert T.InvalidRecord();
                        registered[a] = true;
                        ++registrations;
                    } else if (
                        !registered[a]
                            || (r.operation != 25
                                && r.operation != 26
                                && r.operation != 27
                                && r.operation != 54)
                    ) {
                        revert T.UnsupportedProfile();
                    }
                } else {
                    uint256 c = StreamArtistMultipleHydrationOperations._collection(
                        p.collections, r.collectionId
                    );
                    if (p.collections[c].artistId != r.artistId) revert T.InvalidRecord();
                    if (i == 0 && r.operation == 1) {
                        if (v.collections[c].bindingHash != 0) revert T.InvalidRecord();
                        v.collections[c].bindingHash = r.recordHash;
                    } else if (i == 3 && r.operation == 2) {
                        if (accepted[c]) revert T.InvalidRecord();
                        accepted[c] = true;
                    } else if (i == 6 && r.operation == 14) {
                        ++policyCounts[c];
                    } else if (i != 6 || r.operation != 16) {
                        revert T.UnsupportedProfile();
                    }
                }
            }
        }
        for (uint256 i; i < 7; ++i) {
            uint256 revision = i == 0 || i == 4
                ? 2 * p.collections.length
                : i == 2
                    ? v.receipts[2].length + p.collections.length + v.receipts[6].length + 1
                    : i == 3 ? p.collections.length : i == 6 ? v.receipts[6].length : 0;
            if (p.expectedSource[i].ownerState.revision != revision) revert T.UnsupportedProfile();
        }
        if (registrations != p.artistIds.length) revert T.UnsupportedProfile();
        for (uint256 a; a < p.artistIds.length; ++a) {
            if (!registered[a]) revert T.InvalidRecord();
            v.artists[a].records = new bytes32[](artistCounts[a]);
            uint256 k;
            for (uint256 i; i < 7; ++i) {
                for (uint256 j; j < v.receipts[i].length; ++j) {
                    if (v.receipts[i][j].artistId == p.artistIds[a]) {
                        v.artists[a].records[k++] = v.receipts[i][j].recordHash;
                    }
                }
            }
        }
        for (uint256 c; c < p.collections.length; ++c) {
            if (
                !accepted[c] || v.collections[c].bindingHash == 0
                    || policyCounts[c] != p.collections[c].policies.length
            ) revert T.InvalidRecord();
        }
    }

    function _nonces(address owner, MH.Request memory p, MD.Identities memory b) internal view {
        uint256 n = p.expectedSource[2].nonceIndexCount;
        bool[] memory seen = new bool[](p.artistIds.length);
        uint256 delegateCount;
        uint256 expectedDelegates;
        uint256 total;
        DH.Identity[] memory states = new DH.Identity[](b.rows.length);
        for (uint256 i; i < b.rows.length; ++i) {
            states[i] = StreamArtistDelegationHydrationCodec.identity(b.rows[i].state);
            expectedDelegates += states[i].delegateNonces.length;
        }
        if (n != p.artistIds.length + expectedDelegates) revert T.InvalidRecord();
        for (uint256 i; i < n; ++i) {
            CP.NonceIndex memory index = CP(owner).authorityNonceIndexAt(i);
            if ((index.kind != 1 && index.kind != 2) || index.prefixCount == 0) {
                revert T.UnsupportedProfile();
            }
            total += index.prefixCount;
            if (total > 256) revert T.UnsupportedProfile();
            if (index.kind == 2) {
                uint256 matches;
                for (uint256 a; a < b.rows.length; ++a) {
                    for (uint256 d; d < states[a].delegateNonces.length; ++d) {
                        DH.NonceLane memory lane = states[a].delegateNonces[d];
                        if (lane.key != index.key) continue;
                        ++matches;
                        if (lane.words.length != index.prefixCount) revert T.InvalidRecord();
                        for (uint256 k; k < index.prefixCount; ++k) {
                            (uint256 prefix, uint256[32] memory words, bool exhausted) =
                                CP(owner).authorityNonceWordAt(2, index.key, k);
                            if (
                                keccak256(abi.encode(prefix, words, exhausted))
                                    != keccak256(abi.encode(lane.words[k]))
                            ) revert T.InvalidRecord();
                        }
                    }
                }
                if (matches != 1) revert T.InvalidRecord();
                ++delegateCount;
            } else {
                uint256 a = StreamArtistMultipleHydrationOperations._artist(p.artistIds, index.key);
                if (seen[a]) revert T.InvalidRecord();
                seen[a] = true;
                b.rows[a].nonces = new AH.NonceWord[](index.prefixCount);
                for (uint256 k; k < index.prefixCount; ++k) {
                    (
                        b.rows[a].nonces[k].prefix,
                        b.rows[a].nonces[k].words,
                        b.rows[a].nonces[k].exhausted
                    ) = CP(owner).authorityNonceWordAt(1, index.key, k);
                }
            }
        }
        for (uint256 a; a < seen.length; ++a) {
            if (!seen[a]) revert T.InvalidRecord();
        }
        if (delegateCount != expectedDelegates) revert T.InvalidRecord();
    }

    function _collections(T.SuiteConfiguration memory s, MD.Inventory memory v)
        internal
        view
        returns (MD.Collections memory b)
    {
        uint256 n = v.collections.length;
        b.bindings = new MD.BindingRow[](n);
        b.acceptances = new MD.AcceptanceRow[](n);
        b.attributions = new MD.AttributionRow[](n);
        b.consents = new MD.ConsentRow[](n);
        for (uint256 c; c < n; ++c) {
            AH.Query memory q = v.collections[c];
            b.bindings[c] = MD.BindingRow(
                q.collectionId,
                StreamArtistDelegationHydrationCodec.binding(
                    IStreamArtistDelegationHydrationOwner(s.owners[0])
                        .authorityDelegationHydrationState(q)
                )
            );
            b.acceptances[c] = MD.AcceptanceRow(
                q.bindingHash,
                abi.decode(
                    IStreamArtistAuthorityHydrationOwner(s.owners[3]).authorityHydrationState(q),
                    (AH.Acceptance)
                )
            );
            (uint8 state, uint64 generation) = abi.decode(
                IStreamArtistAuthorityHydrationOwner(s.owners[4]).authorityHydrationState(q),
                (uint8, uint64)
            );
            b.attributions[c] = MD.AttributionRow(q.collectionId, state, generation);
            b.consents[c] = MD.ConsentRow(
                q.collectionId,
                q.policies,
                StreamArtistDelegationHydrationCodec.consent(
                    IStreamArtistDelegationHydrationOwner(s.owners[6])
                        .authorityDelegationHydrationState(q)
                )
            );
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "../../interfaces/stream/artist/IStreamArtistMultipleAuthorityHydration.sol";
import {
    StreamArtistMultipleHydrationTypes as MH
} from "../../interfaces/stream/artist/IStreamArtistMultipleAuthorityHydration.sol";
import {
    StreamArtistOnboardingTypes as T
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";

/// @notice Explicit typed envelope, never an arbitrary storage or call transport.
library StreamArtistMultipleHydrationCodec {
    function isState(bytes memory raw) internal pure returns (bool) {
        bytes32 tag;
        if (raw.length >= 32) assembly ("memory-safe") { tag := mload(add(raw, 32)) }
        return tag == MH.SCHEMA;
    }

    function decode(bytes memory raw) internal pure returns (MH.Bundle memory b) {
        bytes32 tag;
        (tag, b) = abi.decode(raw, (bytes32, MH.Bundle));
        if (
            tag != MH.SCHEMA || b.rows.length == 0 || b.rows.length > 128
                || keccak256(raw) != keccak256(abi.encode(tag, b))
        ) revert T.InvalidRecord();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "./StreamArtistHydrationCommit.sol";
import "./StreamArtistMultipleHydrationCodec.sol";
import "./StreamArtistMultipleDelegationSelection.sol";
import {
    StreamArtistMultipleHydrationTypes as MH
} from "../../interfaces/stream/artist/IStreamArtistMultipleAuthorityHydration.sol";

/// @notice Whole-source multiplicity profile. Every journal/index is visited before any owner write.
library StreamArtistMultipleHydrationOperations {
    struct Inventory {
        AH.Query[] artists;
        AH.Query[] collections;
        H.Receipt[][7] receipts;
        uint256 policies;
        uint256 revocations;
    }
    event MultipleArtistAuthorityHydrated(
        address indexed predecessor,
        bytes32 indexed commitment,
        bytes32[] artistIds,
        uint256[] collectionIds
    );

    function hydrate(D.CoordinatorContext memory x, address actor, MH.Request memory p)
        public
        returns (bytes32 value)
    {
        _selectors(p);
        IStreamArtistHistory history = IStreamArtistHistory(x.suite.owners[2]);
        if (history.importedHistoryBindingCount() != 1) revert T.InvalidBinding();
        (address prior,,,) = history.importedHistoryBinding(0);
        (, bytes32 pin,) = history.artistHistoryPredecessorBinding(prior);
        StreamArtistHistoryProof.predecessor(
            x.suite.core,
            x.suite.registry,
            prior,
            pin,
            StreamArtistHistoryProof.cap(x.suite.registry)
        );
        (bool sealed_, address successor,) = IStreamArtistHistory(prior).artistRegistryCutover();
        if (
            !sealed_ || successor != x.suite.registry
                || IStreamArtistHistory(prior).importedHistoryBindingCount() != 0
        ) revert T.InvalidBinding();
        address coordinator = IStreamArtistIngressBinding(prior).operationCoordinator();
        T.SuiteConfiguration memory source =
            IStreamArtistAuthorityHydrationCoordinator(coordinator).authorityHydrationSuite();
        StreamArtistHydrationSourceGuards._suite(x.suite, source, prior, coordinator);
        if (StreamArtistMultipleDelegationSelection.required(source)) {
            return StreamArtistMultipleDelegationSelection.hydrate(
                x, actor, p, source, prior, coordinator
            );
        }
        StreamArtistHydrationPrepared.Bundle memory h;
        h.profile = MH.PROFILE;
        h.prior = prior;
        h.sourceCoordinator = coordinator;
        h.source = source;
        for (uint256 i; i < 7; ++i) {
            h.before_[i] = IStreamArtistOwner(x.suite.owners[i]).ownerStateSnapshotV2();
            if (
                h.before_[i].revision
                        != (i == 2 ? 1 + p.artistIds.length + p.collections.length : 0)
                    || IStreamArtistNativeReceipts(x.suite.owners[i]).artistNativeReceiptCount()
                        != 0
                    || IStreamArtistAuthorityHydrationOwner(x.suite.owners[i])
                            .authorityHydrationCommitment() != 0
            ) {
                revert T.InvalidRecord();
            }
            StreamArtistHydrationSourceGuards._multipleHeader(source.owners[i], p.expectedSource[i]);
        }
        Inventory memory inv = _inventory(source, p);
        for (uint256 i; i < p.artistIds.length; ++i) {
            StreamArtistHydrationSourceGuards._lane(history, prior, 1, p.artistIds[i]);
            (, uint64 count) = IStreamArtistHistory(prior).artistHistoryLane(1, p.artistIds[i]);
            if (count != inv.artists[i].records.length) revert T.InvalidRecord();
        }
        uint256[] memory ids = new uint256[](p.collections.length);
        for (uint256 i; i < p.collections.length; ++i) {
            ids[i] = p.collections[i].collectionId;
            StreamArtistHydrationSourceGuards._lane(history, prior, 2, bytes32(ids[i]));
            (, uint64 count) = IStreamArtistHistory(prior).artistHistoryLane(2, bytes32(ids[i]));
            if (count != 2 + p.collections[i].policies.length) revert T.InvalidRecord();
        }
        h.data = _data(source, coordinator, p, inv, ids);
        h.q = inv.collections[0];
        AH.Request memory base;
        base.artistId = h.q.artistId;
        base.collectionId = h.q.collectionId;
        base.policies = h.q.policies;
        base.expectedSource = p.expectedSource;
        base.replayOrigins = p.replayOrigins;
        value = StreamArtistHydrationCommit.execute(x, actor, base, h);
        emit MultipleArtistAuthorityHydrated(prior, value, p.artistIds, ids);
    }

    function _selectors(MH.Request memory p) internal pure {
        if (
            p.bindingIndex != 0 || p.artistIds.length == 0 || p.artistIds.length > 128
                || p.collections.length == 0 || p.collections.length > 128
        ) revert T.UnsupportedProfile();
        for (uint256 i; i < p.artistIds.length; ++i) {
            if (p.artistIds[i] == 0 || (i != 0 && p.artistIds[i] <= p.artistIds[i - 1])) {
                revert T.InvalidRecord();
            }
            bool present;
            for (uint256 j; j < p.collections.length; ++j) {
                if (p.collections[j].artistId == p.artistIds[i]) present = true;
            }
            if (!present) revert T.InvalidRecord();
        }
        for (uint256 i; i < p.collections.length; ++i) {
            MH.Collection memory c = p.collections[i];
            if (
                c.collectionId == 0
                    || (i != 0 && c.collectionId <= p.collections[i - 1].collectionId)
                    || c.policies.length > 128
            ) revert T.InvalidRecord();
            _artist(p.artistIds, c.artistId);
            for (uint256 j; j < c.policies.length; ++j) {
                if (c.policies[j].phaseId == 0 || c.policies[j].policyHash == 0) {
                    revert T.InvalidRecord();
                }
                for (uint256 k; k < j; ++k) {
                    if (
                        c.policies[k].phaseId == c.policies[j].phaseId
                            && c.policies[k].policyHash == c.policies[j].policyHash
                    ) {
                        revert T.InvalidRecord();
                    }
                }
            }
        }
    }

    function _inventory(T.SuiteConfiguration memory s, MH.Request memory p)
        private
        view
        returns (Inventory memory v)
    {
        v.artists = new AH.Query[](p.artistIds.length);
        v.collections = new AH.Query[](p.collections.length);
        for (uint256 j; j < p.artistIds.length; ++j) {
            v.artists[j].artistId = p.artistIds[j];
        }
        for (uint256 j; j < p.collections.length; ++j) {
            v.collections[j].artistId = p.collections[j].artistId;
            v.collections[j].collectionId = p.collections[j].collectionId;
            v.collections[j].policies = p.collections[j].policies;
            v.policies += p.collections[j].policies.length;
        }
        if (v.policies > 128) revert T.UnsupportedProfile();
        uint256[] memory artistCounts = new uint256[](p.artistIds.length);
        bool[] memory registered = new bool[](p.artistIds.length);
        bool[] memory accepted = new bool[](p.collections.length);
        uint256[] memory policies = new uint256[](p.collections.length);
        uint256 registrations;
        for (uint256 i; i < 7; ++i) {
            uint256 n = IStreamArtistNativeReceipts(s.owners[i]).artistNativeReceiptCount();
            if (n > 128) revert T.UnsupportedProfile();
            v.receipts[i] = new H.Receipt[](n);
            if ((i == 0 || i == 3) && n != p.collections.length) revert T.UnsupportedProfile();
            if ((i == 1 || i == 4 || i == 5) && n != 0) revert T.UnsupportedProfile();
            if (i == 6 && n != v.policies) revert T.InvalidRecord();
            for (uint256 j; j < n; ++j) {
                H.Receipt memory r =
                    IStreamArtistNativeReceipts(s.owners[i]).artistNativeReceiptAt(j);
                v.receipts[i][j] = r;
                uint256 a = _artist(p.artistIds, r.artistId);
                if (r.recordHash == 0) revert T.InvalidRecord();
                ++artistCounts[a];
                if (i == 2) {
                    if (r.collectionId != 0) revert T.UnsupportedProfile();
                    if (r.operation == 1) {
                        if (registered[a] || r.recordHash != r.artistId) revert T.InvalidRecord();
                        registered[a] = true;
                        ++registrations;
                    } else if (r.operation == 54) {
                        ++v.revocations;
                    } else {
                        revert T.UnsupportedProfile();
                    }
                } else {
                    uint256 c = _collection(p.collections, r.collectionId);
                    if (p.collections[c].artistId != r.artistId) revert T.InvalidRecord();
                    if (i == 0 && r.operation == 1) {
                        if (v.collections[c].bindingHash != 0) revert T.InvalidRecord();
                        v.collections[c].bindingHash = r.recordHash;
                    } else if (i == 3 && r.operation == 2) {
                        if (accepted[c]) revert T.InvalidRecord();
                        accepted[c] = true;
                    } else if (i == 6 && r.operation == 14) {
                        ++policies[c];
                    } else {
                        revert T.UnsupportedProfile();
                    }
                }
            }
            uint256 revision = i == 0 || i == 4
                ? 2 * p.collections.length
                : i == 2
                    ? p.artistIds.length + p.collections.length + v.policies + v.revocations + 1
                    : i == 3 ? p.collections.length : i == 6 ? v.policies : 0;
            if (p.expectedSource[i].ownerState.revision != revision) revert T.UnsupportedProfile();
        }
        if (registrations != p.artistIds.length) revert T.UnsupportedProfile();
        for (uint256 a; a < p.artistIds.length; ++a) {
            if (!registered[a]) revert T.InvalidRecord();
            v.artists[a].records = new bytes32[](artistCounts[a]);
            uint256 k;
            for (uint256 i; i < 7; ++i) {
                for (uint256 j; j < v.receipts[i].length; ++j) {
                    if (v.receipts[i][j].artistId == p.artistIds[a]) {
                        v.artists[a].records[k++] = v.receipts[i][j].recordHash;
                    }
                }
            }
        }
        for (uint256 c; c < p.collections.length; ++c) {
            if (
                !accepted[c] || v.collections[c].bindingHash == 0
                    || policies[c] != p.collections[c].policies.length
            ) {
                revert T.InvalidRecord();
            }
        }
    }

    function _data(
        T.SuiteConfiguration memory s,
        address coordinator,
        MH.Request memory p,
        Inventory memory inv,
        uint256[] memory ids
    ) private view returns (AH.OwnerData[7] memory data) {
        MH.Bundle memory identities;
        identities.rows = new MH.Row[](p.artistIds.length);
        identities.artistIds = p.artistIds;
        identities.collectionIds = ids;
        identities.registrationCount = p.artistIds.length;
        for (uint256 j; j < identities.rows.length; ++j) {
            identities.rows[j].query = inv.artists[j];
            identities.rows[j].state = IStreamArtistMultipleHydrationIdentity(s.owners[2])
                .authorityLivingIdentityHydrationState(inv.artists[j]);
            AH.Identity memory identity = abi.decode(identities.rows[j].state, (AH.Identity));
            if (identity.nextRegistrationNonce != p.artistIds.length) {
                revert T.UnsupportedProfile();
            }
        }
        uint256 registration;
        for (uint256 j; j < inv.receipts[2].length; ++j) {
            H.Receipt memory r = inv.receipts[2][j];
            if (r.operation != 1) continue;
            AH.Identity memory a =
                abi.decode(identities.rows[_artist(p.artistIds, r.artistId)].state, (AH.Identity));
            if (
                StreamArtistHashes.identity(
                        StreamArtistHashes.Environment(
                            block.chainid, s.registry, s.core, s.mintManager
                        ),
                        a.item.authorityAddress,
                        a.item.identityRecordHash,
                        registration++
                    ) != r.artistId
            ) revert T.InvalidRecord();
        }
        _nonces(s.owners[2], p, identities);
        for (uint256 i; i < 7; ++i) {
            data[i] = _replay(s, coordinator, i, p);
            if (i == 2) {
                data[i].typedState = abi.encode(MH.SCHEMA, identities);
            } else if (i == 1 || i == 5) {
                if (p.expectedSource[i].nonceIndexCount != 0) revert T.UnsupportedProfile();
            } else {
                if (p.expectedSource[i].nonceIndexCount != 0) revert T.UnsupportedProfile();
                MH.Bundle memory b;
                b.rows = new MH.Row[](p.collections.length);
                for (uint256 c; c < p.collections.length; ++c) {
                    AH.Query memory q = inv.collections[c];
                    bytes memory raw = IStreamArtistAuthorityHydrationOwner(s.owners[i])
                        .authorityHydrationState(q);
                    _collectionFacts(i, c, q, raw, identities, p, inv);
                    // Only Consent consumes policy selectors. Keep the other typed rows minimal.
                    b.rows[c].query = AH.Query(
                        q.artistId,
                        q.collectionId,
                        q.bindingHash,
                        i == 6 ? q.policies : new AH.PolicyKey[](0),
                        new bytes32[](0)
                    );
                    b.rows[c].state = raw;
                }
                data[i].typedState = abi.encode(MH.SCHEMA, b);
            }
        }
    }

    function _collectionFacts(
        uint256 owner,
        uint256 c,
        AH.Query memory q,
        bytes memory raw,
        MH.Bundle memory identities,
        MH.Request memory p,
        Inventory memory inv
    ) private pure {
        if (owner == 0) {
            AH.Binding memory b = abi.decode(raw, (AH.Binding));
            AH.Identity memory a =
                abi.decode(identities.rows[_artist(p.artistIds, q.artistId)].state, (AH.Identity));
            if (
                b.item.artistId != q.artistId || b.item.bindingHash != q.bindingHash
                    || b.item.artistAddress != a.item.authorityAddress
                    || b.item.identityRecordHash != a.item.identityRecordHash
            ) {
                revert T.InvalidRecord();
            }
        } else if (owner == 3) {
            AH.Acceptance memory a = abi.decode(raw, (AH.Acceptance));
            bool found;
            for (uint256 j; j < inv.receipts[3].length; ++j) {
                if (
                    inv.receipts[3][j].collectionId == q.collectionId
                        && inv.receipts[3][j].recordHash == a.record
                ) found = true;
            }
            if (!found) revert T.InvalidRecord();
        } else if (owner == 6) {
            bytes32[] memory records = abi.decode(raw, (bytes32[]));
            if (records.length != p.collections[c].policies.length) revert T.InvalidRecord();
            uint256 k;
            for (uint256 j; j < inv.receipts[6].length; ++j) {
                H.Receipt memory r = inv.receipts[6][j];
                if (r.collectionId != q.collectionId) continue;
                if (k >= records.length || records[k++] != r.recordHash) revert T.InvalidRecord();
            }
            if (k != records.length) revert T.InvalidRecord();
        }
    }

    function _nonces(address owner, MH.Request memory p, MH.Bundle memory b) private view {
        if (p.expectedSource[2].nonceIndexCount != p.artistIds.length) {
            revert T.UnsupportedProfile();
        }
        bool[] memory seen = new bool[](p.artistIds.length);
        uint256 total;
        for (uint256 j; j < p.artistIds.length; ++j) {
            CP.NonceIndex memory n = CP(owner).authorityNonceIndexAt(j);
            uint256 a = _artist(p.artistIds, n.key);
            if (seen[a] || n.kind != 1 || n.prefixCount == 0) revert T.UnsupportedProfile();
            seen[a] = true;
            total += n.prefixCount;
            if (total > 256) revert T.UnsupportedProfile();
            b.rows[a].nonces = new AH.NonceWord[](n.prefixCount);
            for (uint256 k; k < n.prefixCount; ++k) {
                (
                    b.rows[a].nonces[k].prefix,
                    b.rows[a].nonces[k].words,
                    b.rows[a].nonces[k].exhausted
                ) = CP(owner).authorityNonceWordAt(1, n.key, k);
            }
        }
    }

    function _replay(
        T.SuiteConfiguration memory s,
        address coordinator,
        uint256 i,
        MH.Request memory p
    ) internal view returns (AH.OwnerData memory d) {
        CP.Checkpoint memory h = p.expectedSource[i];
        d.origins = p.replayOrigins[i];
        if (d.origins.length != h.replayCount) revert T.InvalidRecord();
        d.sourceKeys = new bytes32[](h.replayCount);
        d.cells = new T.ReplayCell[](h.replayCount);
        for (uint256 j; j < h.replayCount; ++j) {
            (bytes32 key, T.ReplayCell memory cell) = CP(s.owners[i]).authorityReplayAt(j);
            bytes32 expected = keccak256(
                abi.encode(
                    keccak256("6529STREAM_ARTIST_OWNER_REPLAY_KEY_V2"),
                    block.chainid,
                    s.registry,
                    coordinator,
                    s.archive,
                    s.owners[i],
                    h.ownerState.domainId,
                    d.origins[j].surface,
                    d.origins[j].scope
                )
            );
            if (
                key != expected || cell.status == 0
                    || keccak256(abi.encode(cell))
                        != keccak256(abi.encode(IStreamArtistOwner(s.owners[i]).replayCell(key)))
            ) revert T.InvalidRecord();
            d.sourceKeys[j] = key;
            d.cells[j] = cell;
        }
    }

    function _artist(bytes32[] memory ids, bytes32 id) internal pure returns (uint256) {
        for (uint256 i; i < ids.length; ++i) {
            if (ids[i] == id) return i;
        }
        revert T.InvalidRecord();
    }

    function _collection(MH.Collection[] memory rows, uint256 id) internal pure returns (uint256) {
        for (uint256 i; i < rows.length; ++i) {
            if (rows[i].collectionId == id) return i;
        }
        revert T.InvalidRecord();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "./StreamArtistIdentityHydration.sol";
import "./StreamArtistMultipleHydrationCodec.sol";
import "./StreamArtistHistoryState.sol";
import {
    StreamArtistMultipleHydrationTypes as MH
} from "../../interfaces/stream/artist/IStreamArtistMultipleAuthorityHydration.sol";

/// @notice Fixed typed multiplicity import; the original identity domain and per-identity nonce trees remain distinct.
library StreamArtistMultipleIdentityHydration {
    function exportEncoded(
        StreamArtistIdentityState.State storage s,
        StreamArtistEstateState.State storage estate,
        StreamArtistDormancyState.State storage dorm,
        StreamArtistUnavailabilityState.State storage finding,
        bytes calldata encoded
    ) public view returns (bytes memory) {
        return exportState(s, estate, dorm, finding, abi.decode(encoded, (AH.Query)));
    }

    function exportState(
        StreamArtistIdentityState.State storage s,
        StreamArtistEstateState.State storage estate,
        StreamArtistDormancyState.State storage dorm,
        StreamArtistUnavailabilityState.State storage finding,
        AH.Query memory q
    ) public view returns (bytes memory) {
        AH.Identity memory p;
        p.item = s.identities[q.artistId];
        if (
            p.item.authorityClass != 1 || p.item.status != 1
                || s.activeIdentity[p.item.authorityAddress] != q.artistId
        ) revert T.UnsupportedProfile();
        p.document = s.documents[p.item.identityRecordHash];
        p.nextRegistrationNonce = s.nextRegistrationNonce;
        if (p.document.length == 0 || keccak256(p.document) != p.item.identityRecordHash) {
            revert T.InvalidRecord();
        }
        p.estateActivity = estate.livingActivity[q.artistId];
        p.dormancyActivity = dorm.activity[q.artistId];
        p.findingActivity = finding.activityEpoch[q.artistId];
        p.signatures = new bytes[](q.records.length);
        for (uint256 j; j < q.records.length; ++j) {
            p.signatures[j] = s.signatures[q.records[j]];
        }
        return abi.encode(p);
    }

    function importEncoded(
        StreamArtistIdentityState.State storage s,
        StreamArtistEstateState.State storage estate,
        StreamArtistDormancyState.State storage dorm,
        StreamArtistUnavailabilityState.State storage finding,
        bytes calldata encoded
    ) public {
        (, AH.Query memory anchor, AH.OwnerData memory outer, bytes32 value) =
            abi.decode(encoded, (T.ActionContext, AH.Query, AH.OwnerData, bytes32));
        MH.Bundle memory b = StreamArtistMultipleHydrationCodec.decode(outer.typedState);
        if (
            s.nextRegistrationNonce != 0 || outer.nonces.length != 0
                || b.rows.length != b.artistIds.length || b.registrationCount != b.artistIds.length
                || b.collectionIds.length == 0 || anchor.collectionId != b.collectionIds[0]
        ) revert T.InvalidRecord();
        for (uint256 i; i < b.rows.length; ++i) {
            MH.Row memory row = b.rows[i];
            AH.Identity memory p = abi.decode(row.state, (AH.Identity));
            if (
                row.query.artistId != b.artistIds[i] || row.query.artistId == 0
                    || (i != 0 && b.artistIds[i] <= b.artistIds[i - 1])
                    || s.identities[row.query.artistId].authorityAddress != address(0)
                    || s.activeIdentity[p.item.authorityAddress] != 0
                    || p.item.authorityAddress == address(0) || p.item.authorityClass != 1
                    || p.item.status != 1 || p.nextRegistrationNonce != b.registrationCount
                    || row.nonces.length == 0 || p.signatures.length != row.query.records.length
                    || p.document.length == 0 || keccak256(p.document) != p.item.identityRecordHash
            ) {
                revert T.InvalidRecord();
            }
            _import(s, estate, dorm, finding, row.query, p, row.nonces);
        }
        s.nextRegistrationNonce = b.registrationCount;
        StreamArtistHistoryState.activateMultiple(b.artistIds, b.collectionIds, value);
    }

    function _import(
        StreamArtistIdentityState.State storage s,
        StreamArtistEstateState.State storage estate,
        StreamArtistDormancyState.State storage dorm,
        StreamArtistUnavailabilityState.State storage finding,
        AH.Query memory q,
        AH.Identity memory p,
        AH.NonceWord[] memory nonces
    ) internal {
        AH.OwnerData memory data;
        data.nonces = nonces;
        s.identities[q.artistId] = p.item;
        s.activeIdentity[p.item.authorityAddress] = q.artistId;
        s.documents[p.item.identityRecordHash] = p.document;
        StreamArtistPayloadStore.store(keccak256("ARTIST_IDENTITY_DOCUMENT"), p.document);
        for (uint256 j; j < q.records.length; ++j) {
            s.signatures[q.records[j]] = p.signatures[j];
            StreamArtistPayloadStore.store(keccak256("ARTIST_SIGNATURE_BUNDLE"), p.signatures[j]);
        }
        estate.livingActivity[q.artistId] = p.estateActivity;
        dorm.activity[q.artistId] = p.dormancyActivity;
        finding.activityEpoch[q.artistId] = p.findingActivity;
        for (uint256 j; j < data.nonces.length; ++j) {
            AH.NonceWord memory n = data.nonces[j];
            uint256 prefix = n.prefix;
            for (uint8 level; level < 32; ++level) {
                uint256 old = s.nonceAvailability[q.artistId].full[level][prefix];
                if (old != 0 && old != n.words[level]) revert T.InvalidRecord();
                s.nonceAvailability[q.artistId].full[level][prefix] = n.words[level];
                prefix >>= 8;
            }
            s.nonceAvailability[q.artistId].exhausted = n.exhausted;
            StreamArtistAuthorityCheckpoint.noteNonce(
                1, q.artistId, n.prefix, keccak256(abi.encode(n))
            );
        }
        (bool available, uint256 hint) =
            StreamArtistNonceAvailability.firstUnused(s.nonceAvailability[q.artistId]);
        if (!available || hint != p.item.nonceHint) revert T.InvalidRecord();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "./StreamArtistPublicationHydration.sol";
import "./StreamArtistMultipleDelegationCodec.sol";
import "./StreamArtistMultipleHydrationOperations.sol";
import "../../interfaces/stream/artist/IStreamArtistAttributionOwner.sol";
import {
    StreamArtistMultipleRecordsTypes as MR
} from "../../interfaces/stream/artist/IStreamArtistMultipleRecordsHydration.sol";

library StreamArtistMultipleRecordsAttestations {
    function collect(
        T.SuiteConfiguration memory s,
        MD.Inventory memory inv,
        MR.CollectionWitness[] memory inputs,
        MD.Identities memory identities
    ) public view returns (bytes memory) {
        MR.Attribution memory b;
        b.sourceRegistry = s.registry;
        b.collections = inv.collections;
        b.records = new PubH.Row[](inv.receipts[4].length);
        uint256[] memory used = new uint256[](inputs.length);
        StreamArtistHashes.Environment memory e =
            StreamArtistHashes.Environment(block.chainid, s.registry, s.core, s.mintManager);
        for (uint256 j; j < b.records.length; ++j) {
            H.Receipt memory n = inv.receipts[4][j];
            uint256 c = _collection(inv.collections, n.collectionId);
            if (used[c] >= inputs[c].attestations.length) revert T.InvalidRecord();
            PubH.Row memory row;
            row.attestation.input = inputs[c].attestations[used[c]++];
            row.attestation.record =
                IStreamArtistAttributionOwner(s.owners[4]).attestationRecord(n.recordHash);
            row.attestation.authorityClass = IStreamArtistReadinessAttributionOwner(s.owners[4])
                .attestationAuthorityClass(n.recordHash);
            row.attestation.association = IStreamArtistAuthenticatedAttestationOwner(s.owners[4])
                .attestationAssociation(n.recordHash);
            row.attestation.statement = IStreamArtistAttributionOwner(s.owners[4])
                .statementBytes(row.attestation.record.statementHash);
            row.publication = IStreamArtistRecordPublicationOwner(s.owners[4])
                .publicationAttestation(n.recordHash);
            StreamArtistPublicationHydration.validate(e, inv.collections[c], row);
            uint256 a;
            while (a < identities.rows.length && identities.rows[a].artistId != n.artistId) ++a;
            if (a == identities.rows.length) revert T.InvalidRecord();
            DH.Identity memory identity =
                StreamArtistDelegationHydrationCodec.identity(identities.rows[a].state);
            AH.Identity memory original = abi.decode(identity.baseline, (AH.Identity));
            if (
                row.attestation.record.recordHash != n.recordHash
                    || row.attestation.record.signer != original.item.authorityAddress
            ) revert T.InvalidRecord();
            b.records[j] = row;
        }
        for (uint256 c; c < inputs.length; ++c) {
            if (used[c] != inputs[c].attestations.length) revert T.InvalidRecord();
        }
        for (uint256 j; j < b.records.length; ++j) {
            RH.AttestationRow memory row = b.records[j].attestation;
            bool last = true;
            bytes32 key = _key(row.input.terms);
            for (uint256 k = j + 1; k < b.records.length; ++k) {
                if (_key(b.records[k].attestation.input.terms) == key) last = false;
            }
            if (
                last
                    && keccak256(abi.encode(row.record))
                        != keccak256(
                            abi.encode(
                                IStreamArtistAttributionOwner(s.owners[4])
                                    .attestation(
                                        row.input.terms.collectionId,
                                        row.input.terms.subjectKind,
                                        row.input.terms.subjectId
                                    )
                            )
                        )
            ) revert T.InvalidRecord();
        }
        _credentials(s.owners[4], b, identities);
        return abi.encode(MR.ATTRIBUTION, b);
    }

    function _credentials(address owner, MR.Attribution memory b, MD.Identities memory identities)
        private
        view
    {
        for (uint256 a; a < identities.rows.length; ++a) {
            bytes32 artist = identities.rows[a].artistId;
            C2PA.Head memory expected;
            for (uint256 j; j < b.records.length; ++j) {
                RH.AttestationRow memory row = b.records[j].attestation;
                T.Attestation memory p = row.input.terms;
                uint256 c = _collection(b.collections, p.collectionId);
                AH.Query memory q = b.collections[c];
                if (
                    q.artistId != artist || p.subjectKind != 10
                        || p.schemaId != StreamArtistC2PACredentials.SCHEMA
                ) continue;
                C2PA.Payload memory payload =
                    StreamArtistC2PACredentials.decode(row.statement, artist, p.subjectStateHash);
                if (payload.previousRecordHash != expected.recordHash) revert T.InvalidRecord();
                expected = C2PA.Head(
                    expected.revision + 1,
                    row.record.recordHash,
                    expected.recordHash,
                    artist,
                    p.collectionId,
                    q.bindingHash,
                    1,
                    p.subjectStateHash,
                    row.record.statementHash,
                    b.sourceRegistry
                );
                if (
                    keccak256(
                            abi.encode(
                                IStreamArtistC2PAReads(owner)
                                    .c2paCredentialRecord(expected.recordHash)
                            )
                        ) != keccak256(abi.encode(expected))
                ) revert T.InvalidRecord();
            }
            if (
                keccak256(abi.encode(IStreamArtistC2PAReads(owner).c2paCredentialHead(artist)))
                    != keccak256(abi.encode(expected))
            ) revert T.InvalidRecord();
        }
        for (uint256 c; c < b.collections.length; ++c) {
            AH.Query memory q = b.collections[c];
            T.AttestationRecord memory expected;
            for (uint256 j; j < b.records.length; ++j) {
                RH.AttestationRow memory row = b.records[j].attestation;
                T.Attestation memory p = row.input.terms;
                if (
                    p.collectionId == q.collectionId && p.subjectKind == 10
                        && StreamArtistC2PACredentials.isPersonhood(p.schemaId)
                ) expected = row.record;
            }
            if (
                keccak256(
                        abi.encode(
                            IStreamArtistC2PAReads(owner)
                                .personhoodAttestation(q.collectionId, q.artistId)
                        )
                    ) != keccak256(abi.encode(expected))
            ) revert T.InvalidRecord();
        }
    }

    function importState(
        AS.State storage s,
        StreamArtistHashes.Environment memory e,
        bytes memory raw
    ) public {
        (bytes32 tag, MR.Attribution memory b) = abi.decode(raw, (bytes32, MR.Attribution));
        if (
            tag != MR.ATTRIBUTION || b.sourceRegistry == address(0) || b.collections.length == 0
                || b.collections.length > 128 || b.records.length > 128
        ) revert T.InvalidRecord();
        e.registry = b.sourceRegistry;
        for (uint256 c; c < b.collections.length; ++c) {
            AH.Query memory q = b.collections[c];
            if (
                q.collectionId == 0
                    || (c != 0 && q.collectionId <= b.collections[c - 1].collectionId)
                    || s.attributions[q.collectionId].generation != 0
            ) revert T.InvalidRecord();
            s.attributions[q.collectionId] = AS.Attribution(2, 1);
        }
        for (uint256 j; j < b.records.length; ++j) {
            PubH.Row memory row = b.records[j];
            RH.AttestationRow memory r = row.attestation;
            AH.Query memory q =
                b.collections[_collection(b.collections, r.input.terms.collectionId)];
            StreamArtistPublicationHydration.validate(e, q, row);
            bytes32 record = r.record.recordHash;
            if (
                s.records[record].recordHash != 0
                    || s.publications[record].evidence.attestationRecordHash != 0
            ) revert T.InvalidRecord();
            s.records[record] = r.record;
            s.attestationClasses[record] = r.authorityClass;
            s.attestationAssociations[record] = r.association;
            s.attestations[_key(r.input.terms)] = r.record;
            if (r.input.terms.subjectKind == 7 || r.input.terms.subjectKind == 8) {
                s.publications[record] = row.publication;
            }
            if (s.statements[r.record.statementHash].length == 0) {
                s.statements[r.record.statementHash] = r.statement;
            }
            StreamArtistPayloadStore.store(keccak256("ARTIST_PUBLICATION_STATEMENT"), r.statement);
            StreamArtistC2PACredentials.note(
                b.sourceRegistry,
                q.artistId,
                q.bindingHash,
                r.input.terms,
                r.record,
                r.statement,
                false
            );
        }
    }

    function _collection(AH.Query[] memory rows, uint256 id) private pure returns (uint256) {
        for (uint256 c; c < rows.length; ++c) {
            if (rows[c].collectionId == id) return c;
        }
        revert T.InvalidRecord();
    }

    function _key(T.Attestation memory p) private pure returns (bytes32) {
        return keccak256(abi.encode(p.collectionId, p.subjectKind, p.subjectId));
    }
}

