pragma solidity ^0.8.19;

import {
    StreamArtistRecoveredHydrationTypes as RH
} from "../../interfaces/stream/artist/StreamArtistRecoveredHydrationTypes.sol";
import {
    StreamArtistAuthorityHydrationTypes as AH
} from "../../interfaces/stream/artist/IStreamArtistAuthorityHydration.sol";
import { StreamArtistAttributionStateTypes as AS } from "./StreamArtistAttributionStateTypes.sol";
import {
    StreamArtistRecoveredHydrationProvenance as Provenance
} from "./StreamArtistRecoveredHydrationProvenance.sol";
import {
    StreamArtistRecoveredHydrationOwnerPayload as Payload
} from "./StreamArtistRecoveredHydrationOwnerPayload.sol";

/// @notice Explicit base collection dependencies for recovered-authority graphs.
/// @dev One accepted attribution and complete direct policy14 history. Pending-generation
/// history has a distinct tag and complete Binding-owner join; generation-one bytes are unchanged.
/// Other collection histories require their typed extension; none is represented as empty here.
library StreamArtistRecoveredCollectionHydration {
    bytes32 internal constant ATTRIBUTION =
        keccak256("6529STREAM_ARTIST_RECOVERED_ATTRIBUTION_BASE_V1");
    bytes32 internal constant GENERATIONS_ATTRIBUTION =
        keccak256("6529STREAM_ARTIST_RECOVERED_ATTRIBUTION_GENERATIONS_V1");
    bytes32 internal constant POLICIES =
        keccak256("6529STREAM_ARTIST_RECOVERED_DIRECT_POLICIES_V1");
    bytes32 private constant POLICY_KEY = keccak256("consent_finality.replay.policy_consent_key");

    struct AttributionBundle {
        bytes32 provenance;
        bytes32 artistId;
        uint256 collectionId;
        bytes32 bindingHash;
        AS.Attribution item;
    }

    struct PolicyBundle {
        bytes32 provenance;
        bytes32 artistId;
        uint256 collectionId;
        AH.PolicyKey[] policies;
        bytes32[] records;
    }

    function exportAttribution(AS.State storage s, AH.Query memory q, RH.OwnerProvenance memory p)
        public
        view
        returns (bytes memory)
    {
        Provenance.validateOwnerSource(p, 4, address(this));
        AttributionBundle memory b = AttributionBundle(
            RH.ownerProvenanceHash(p, 4),
            q.artistId,
            q.collectionId,
            q.bindingHash,
            s.attributions[q.collectionId]
        );
        if (b.item.generation > 1) {
            validateGenerationsAttribution(b, q, p);
            return abi.encode(GENERATIONS_ATTRIBUTION, b);
        }
        validateAttribution(b, q, p);
        return abi.encode(ATTRIBUTION, b);
    }

    function importAttribution(AS.State storage s, AH.Query memory q, bytes memory raw) public {
        (RH.ExportHeader memory header, Payload.Payload memory payload) = Payload.decode(raw, 4);
        (bytes32 tag, AttributionBundle memory b) =
            abi.decode(payload.semanticState, (bytes32, AttributionBundle));
        if (
            keccak256(payload.semanticState) != keccak256(abi.encode(tag, b))
                || payload.nonces.length != 0
        ) revert RH.InvalidRecoveredHydrationProfile();
        if (tag == GENERATIONS_ATTRIBUTION) {
            if ((header.requiredFeatures & RH.BINDING_GENERATIONS) == 0) {
                revert RH.InvalidRecoveredHydrationProfile();
            }
            validateGenerationsAttribution(b, q, payload.provenance);
        } else {
            if (tag != ATTRIBUTION) revert RH.InvalidRecoveredHydrationProfile();
            validateAttribution(b, q, payload.provenance);
        }
        if (
            s.attributions[q.collectionId].state != 0
                || s.attributions[q.collectionId].generation != 0
        ) revert RH.InvalidRecoveredHydrationProfile();
        s.attributions[q.collectionId] = b.item;
    }

    function validateAttribution(
        AttributionBundle memory b,
        AH.Query memory q,
        RH.OwnerProvenance memory p
    ) public pure {
        _validateAttribution(b, q, p, 1);
    }

    /// @notice All pending generations terminate before the sole final acceptance.
    /// @dev Prepared joins the exact generation to the complete Binding-owner history.
    /// Each original proposal and termination/acceptance mutates Attribution exactly once.
    function validateGenerationsAttribution(
        AttributionBundle memory b,
        AH.Query memory q,
        RH.OwnerProvenance memory p
    ) public pure {
        if (b.item.generation < 2 || b.item.generation > 128) {
            revert RH.InvalidRecoveredHydrationProfile();
        }
        _validateAttribution(b, q, p, b.item.generation);
    }

    function _validateAttribution(
        AttributionBundle memory b,
        AH.Query memory q,
        RH.OwnerProvenance memory p,
        uint64 generation
    ) private pure {
        Provenance.validateOwner(p, 4);
        if (
            b.provenance != RH.ownerProvenanceHash(p, 4) || b.artistId == 0
                || b.artistId != q.artistId || b.collectionId == 0
                || b.collectionId != q.collectionId || b.bindingHash == 0
                || b.bindingHash != q.bindingHash || b.item.state != 2
                || b.item.generation != generation || p.journal.length != 0 || p.aliases.length != 0
        ) revert RH.InvalidRecoveredHydrationProfile();
        for (uint256 i; i < p.eras.length; ++i) {
            if (
                p.eras[i].checkpoint.ownerState.revision != (i == 0 ? 2 * generation : 1)
                    || p.eras[i].lowerRevision != (i == 0 ? 0 : 1) || p.eras[i].nativeCount != 0
                    || p.eras[i].checkpoint.replayCount != 0 || p.eras[i].checkpoint.replayRoot != 0
                    || p.eras[i].checkpoint.nonceIndexCount != 0
                    || p.eras[i].checkpoint.nonceRoot != 0
            ) {
                revert RH.InvalidRecoveredHydrationProfile();
            }
        }
    }

    function exportPolicies(
        mapping(bytes32 => bytes32) storage policies,
        mapping(bytes32 => bytes32) storage delegations,
        AH.Query memory q,
        RH.OwnerProvenance memory p
    ) public view returns (bytes memory) {
        Provenance.validateOwnerSource(p, 6, address(this));
        PolicyBundle memory b;
        b.provenance = RH.ownerProvenanceHash(p, 6);
        b.artistId = q.artistId;
        b.collectionId = q.collectionId;
        b.policies = q.policies;
        b.records = new bytes32[](q.policies.length);
        for (uint256 i; i < b.records.length; ++i) {
            b.records[i] = policies[_scope(q.collectionId, q.policies[i])];
            if (delegations[b.records[i]] != 0) revert RH.InvalidRecoveredHydrationProfile();
        }
        validatePolicies(b, q, p);
        return abi.encode(POLICIES, b);
    }

    function importPolicies(
        mapping(bytes32 => bytes32) storage policies,
        mapping(bytes32 => bytes32) storage delegations,
        AH.Query memory q,
        bytes memory raw
    ) public {
        (, Payload.Payload memory payload) = Payload.decode(raw, 6);
        (bytes32 tag, PolicyBundle memory b) =
            abi.decode(payload.semanticState, (bytes32, PolicyBundle));
        if (
            tag != POLICIES || keccak256(payload.semanticState) != keccak256(abi.encode(tag, b))
                || payload.nonces.length != 0
        ) revert RH.InvalidRecoveredHydrationProfile();
        validatePolicies(b, q, payload.provenance);
        for (uint256 i; i < b.records.length; ++i) {
            bytes32 scope = _scope(q.collectionId, b.policies[i]);
            if (policies[scope] != 0 || delegations[b.records[i]] != 0) {
                revert RH.InvalidRecoveredHydrationProfile();
            }
            policies[scope] = b.records[i];
        }
    }

    function validatePolicies(PolicyBundle memory b, AH.Query memory q, RH.OwnerProvenance memory p)
        public
        pure
    {
        Provenance.validateOwner(p, 6);
        if (
            b.provenance != RH.ownerProvenanceHash(p, 6) || b.artistId == 0
                || b.artistId != q.artistId || b.collectionId == 0
                || b.collectionId != q.collectionId || b.policies.length > 128
                || b.records.length != b.policies.length || b.records.length != p.journal.length
                || keccak256(abi.encode(b.policies)) != keccak256(abi.encode(q.policies))
        ) revert RH.InvalidRecoveredHydrationProfile();
        for (uint256 i; i < b.records.length; ++i) {
            if (b.records[i] == 0 || b.policies[i].phaseId == 0 || b.policies[i].policyHash == 0) {
                revert RH.InvalidRecoveredHydrationProfile();
            }
            for (uint256 j; j < i; ++j) {
                if (
                    b.records[j] == b.records[i]
                        || _scope(b.collectionId, b.policies[j])
                            == _scope(b.collectionId, b.policies[i])
                ) revert RH.InvalidRecoveredHydrationProfile();
            }
            uint256 matches;
            for (uint256 j; j < p.journal.length; ++j) {
                RH.JournalEntry memory row = p.journal[j];
                if (row.receipt.recordHash != b.records[i]) continue;
                if (
                    row.receipt.operation != 14 || row.receipt.artistId != b.artistId
                        || row.receipt.collectionId != b.collectionId
                ) revert RH.InvalidRecoveredHydrationProfile();
                ++matches;
            }
            if (matches != 1) revert RH.InvalidRecoveredHydrationProfile();
        }
        uint256 total;
        for (uint256 i; i < p.eras.length; ++i) {
            total += p.eras[i].nativeCount;
            if (
                p.eras[i].checkpoint.ownerState.revision
                        != p.eras[i].lowerRevision + p.eras[i].nativeCount
                    || p.eras[i].lowerRevision != (i == 0 ? 0 : 1)
                    || p.eras[i].checkpoint.nonceIndexCount != 0
                    || p.eras[i].checkpoint.nonceRoot != 0
                    || p.eras[i].checkpoint.replayCount != total
                    || (total == 0 && p.eras[i].checkpoint.replayRoot != 0)
            ) revert RH.InvalidRecoveredHydrationProfile();
        }
        for (uint256 i; i < p.aliases.length; ++i) {
            RH.ReplayAlias memory a = p.aliases[i];
            if (a.surface != POLICY_KEY || a.cell.kind != 1 || a.cell.status != 2) {
                revert RH.InvalidRecoveredHydrationProfile();
            }
            bool found;
            for (uint256 j; j < b.records.length; ++j) {
                if (
                    a.scope != _scope(b.collectionId, b.policies[j])
                        || a.cell.commitment != b.records[j]
                ) continue;
                for (uint256 k; k < p.journal.length; ++k) {
                    if (
                        p.journal[k].receipt.recordHash == b.records[j]
                            && keccak256(abi.encode(a.admittedAt))
                                == keccak256(abi.encode(p.journal[k].position.point))
                    ) found = true;
                }
            }
            if (!found) revert RH.InvalidRecoveredHydrationProfile();
        }
    }

    function _scope(uint256 collectionId, AH.PolicyKey memory key) private pure returns (bytes32) {
        return keccak256(abi.encode(collectionId, key.phaseId, key.policyHash));
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import {
    StreamArtistRecoveredHydrationTypes as RH
} from "../../interfaces/stream/artist/StreamArtistRecoveredHydrationTypes.sol";
import {
    StreamArtistRecoveredIdentityHydrationTypes as IH
} from "../../interfaces/stream/artist/StreamArtistRecoveredIdentityHydrationTypes.sol";
import {
    StreamArtistAuthorityHydrationTypes as AH
} from "../../interfaces/stream/artist/IStreamArtistAuthorityHydration.sol";
import {
    StreamArtistDelegationTypes as D
} from "../../interfaces/stream/artist/StreamArtistDelegationTypes.sol";
import {
    IStreamArtistContentRecordsOwner as ContentOwner
} from "../../interfaces/stream/artist/IStreamArtistContentOwner.sol";
import {
    StreamArtistContentTypes as Content
} from "../../interfaces/stream/artist/StreamArtistContentTypes.sol";
import {
    StreamArtistRecoveredContentConsentHydration as ContentH
} from "./StreamArtistRecoveredContentConsentHydration.sol";
import {
    StreamArtistRecoveredHydrationChronology as Chronology
} from "./StreamArtistRecoveredHydrationChronology.sol";

/// @notice Slim linked worker for original17/20/21 evidence and delegated20 use reconciliation.
/// @dev The facade supplies every field consumed by the original validator. Complete source
/// certificate and owner-map authentication remain prerequisites; no authority is reauthorized.
library StreamArtistRecoveredContentConsentFactRows {
    struct IdentityRows {
        bytes32 artistId;
        IH.SignatureRow[] signatures;
        IH.DelegationRow[] delegations;
    }

    struct ConsentRows {
        bytes32 artistId;
        uint256 collectionId;
        bytes32 bindingHash;
        ContentOwner.ConsentRecord[] consents;
        ContentH.Royalty[] royalties;
        Content.FreezeRecord[] freezes;
    }

    struct Scope {
        bytes32 artistId;
        uint256 collectionId;
        bytes32 bindingHash;
    }

    function validateRows(
        IdentityRows memory identity,
        ConsentRows memory consent,
        Scope memory q,
        RH.Provenance memory p
    ) public pure returns (uint256[] memory uses) {
        return _validateRows(identity, consent, q, p, 1);
    }

    function validateGenerationRows(
        IdentityRows memory identity,
        ConsentRows memory consent,
        Scope memory q,
        RH.Provenance memory p,
        uint64 generation
    ) public pure returns (uint256[] memory uses) {
        if (generation < 2 || generation > 128 || identity.delegations.length != 0) _invalid();
        return _validateRows(identity, consent, q, p, generation);
    }

    function _validateRows(
        IdentityRows memory identity,
        ConsentRows memory consent,
        Scope memory q,
        RH.Provenance memory p,
        uint64 generation
    ) private pure returns (uint256[] memory uses) {
        if (
            q.artistId == 0 || q.collectionId == 0 || q.bindingHash == 0
                || identity.artistId != q.artistId || consent.artistId != q.artistId
                || consent.collectionId != q.collectionId || consent.bindingHash != q.bindingHash
        ) _invalid();
        uses = new uint256[](identity.delegations.length);
        uint256 contents;
        uint256 royalties;
        uint256 freezes;
        for (uint256 i; i < p.journals[6].length; ++i) {
            RH.JournalEntry memory native_ = p.journals[6][i];
            uint16 op = native_.receipt.operation;
            if (op == 14 || op == 15 || op == 16) continue;
            if (op != 17 && op != 20 && op != 21) _invalid();
            if (
                native_.receipt.artistId != q.artistId
                    || native_.receipt.collectionId != q.collectionId
                    || native_.receipt.recordHash == 0 || native_.position.point.ownerIndex != 6
            ) _invalid();
            Chronology.validatePoint(p, native_.position.point);
            for (uint256 j; j < i; ++j) {
                if (p.journals[6][j].receipt.recordHash == native_.receipt.recordHash) _invalid();
            }
            _signature(identity, native_.receipt.recordHash);
            if (op == 17) {
                if (contents == consent.consents.length) _invalid();
                ContentOwner.ConsentRecord memory row = consent.consents[contents++];
                if (
                    row.recordHash != native_.receipt.recordHash || row.artistId != q.artistId
                        || row.bindingGeneration != generation
                        || row.terms.collectionId != q.collectionId
                        || (row.authorityClass != 1 && row.authorityClass != 3)
                ) _invalid();
            } else if (op == 21) {
                if (freezes == consent.freezes.length) _invalid();
                Content.FreezeRecord memory row = consent.freezes[freezes++];
                if (
                    row.recordHash != native_.receipt.recordHash || row.artistId != q.artistId
                        || row.bindingGeneration != generation
                        || (row.authorityClass != 1 && row.authorityClass != 3)
                ) _invalid();
            } else {
                if (royalties == consent.royalties.length) _invalid();
                ContentH.Royalty memory row = consent.royalties[royalties++];
                if (
                    row.item.recordHash != native_.receipt.recordHash
                        || row.item.artistId != q.artistId
                        || row.item.bindingGeneration != generation
                        || row.terms.collectionId != q.collectionId
                ) _invalid();
                if (row.grant != 0) {
                    ++uses[_grant(identity, p, q.collectionId, row.grant, native_.position.point)];
                }
            }
        }
        if (
            contents != consent.consents.length || royalties != consent.royalties.length
                || freezes != consent.freezes.length
        ) _invalid();
    }

    function _signature(IdentityRows memory identity, bytes32 record) private pure {
        bool found;
        for (uint256 i; i < identity.signatures.length; ++i) {
            if (identity.signatures[i].recordHash != record) continue;
            if (found || identity.signatures[i].signature.length > 4096) _invalid();
            found = true;
        }
        // Empty bytes are valid direct/Safe evidence. Exact source bytes and all nonce/replay
        // inventories are authenticated separately; there is no new ERC1271 check here.
        if (!found) _invalid();
    }

    function _grant(
        IdentityRows memory identity,
        RH.Provenance memory p,
        uint256 collectionId,
        bytes32 hash,
        RH.Point memory usePoint
    ) private pure returns (uint256 at) {
        uint256 useEra = _era(p, usePoint.environmentHash);
        for (uint256 i; i < identity.delegations.length; ++i) {
            IH.DelegationRow memory row = identity.delegations[i];
            if (row.recordHash != hash) continue;
            D.Grant memory grant = row.record.grant;
            if (
                grant.artistId != identity.artistId || grant.delegate == address(0)
                    || (grant.collectionId != 0 && grant.collectionId != collectionId)
                    || (grant.capabilities & D.ROYALTY_FREEZE) == 0
                    || row.position.point.ownerIndex != 2
                    || _era(p, row.position.point.environmentHash) > useEra
            ) _invalid();
            Chronology.validatePoint(p, row.position.point);
            if (
                row.record.revoked
                    && _revocationEra(p, identity.artistId, row.record.revocationRecordHash)
                        < useEra
            ) _invalid();
            for (uint256 j = i + 1; j < identity.delegations.length; ++j) {
                IH.DelegationRow memory next = identity.delegations[j];
                if (
                    next.record.grant.delegate == grant.delegate
                        && _era(p, next.position.point.environmentHash) < useEra
                ) _invalid();
            }
            // Within one era, Identity and Consent have independent revision counters. The
            // original writer authenticated order, live epoch, validity and grant consumption.
            // Only an earlier/later era supplies an additional cross-owner ordering fact.
            return i;
        }
        _invalid();
    }

    function _revocationEra(RH.Provenance memory p, bytes32 artist, bytes32 record)
        private
        pure
        returns (uint256 era)
    {
        bool found;
        if (record == 0) _invalid();
        for (uint256 i; i < p.journals[2].length; ++i) {
            RH.JournalEntry memory native_ = p.journals[2][i];
            if (native_.receipt.recordHash != record) continue;
            if (
                found || native_.receipt.operation != 27 || native_.receipt.artistId != artist
                    || native_.receipt.collectionId != 0 || native_.position.point.ownerIndex != 2
            ) _invalid();
            Chronology.validatePoint(p, native_.position.point);
            era = _era(p, native_.position.point.environmentHash);
            found = true;
        }
        if (!found) _invalid();
    }

    function _era(RH.Provenance memory p, bytes32 origin) private pure returns (uint256) {
        for (uint256 i; i < p.eras.length; ++i) {
            if (p.eras[i].originHash == origin) return i;
        }
        _invalid();
    }

    function _invalid() private pure {
        revert RH.InvalidRecoveredHydrationProfile();
    }
}

