                key
            );
            if (X.succession(r).payloads[key].length != 0) revert IH.InvalidRecoveredIdentity(key);
            X.succession(r).directives[key] = row.record;
            X.succession(r).payloads[key] = row.payload;
            X.rewinds(r).statuses[key] = row.status;
