                    if (cursor >= r.indices.length || r.indices[cursor++] != j + 1) {
                        revert IH.InvalidRecoveredIdentity(b.artistId);
                    }
                }
            }
            if (cursor != r.indices.length) revert IH.InvalidRecoveredIdentity(b.artistId);
