            }
        }
        for (uint256 i; i < b.directives.length; ++i) {
            _native(p, b.artistId, b.directives[i].position, 37, b.directives[i].record.recordHash);
            if (i != 0) {
                _ordered(p, b.directives[i - 1].position.point, b.directives[i].position.point);
            }
        }
