/// @notice Original environments and one owner-local clock for recovered Identity/Payout reads.
/// @dev A point proves provenance, never the semantic record body or its original authorization.
/// Fixed consumers build Context with load; caller-authored Context is not an authorization input.
library StreamArtistRecoveredRuntimeReads {
    struct Context {
        uint8 ownerIndex;
        address owner;
        RH.OriginEnvironment current;
        RH.OwnerProvenance imported;
        CP.Checkpoint checkpoint;
        bytes32 importCommitment;
        uint64 importedAtRevision;
        uint256 nativeCount;
    }

    struct OriginFact {
        RH.Point point;
        RH.OriginEnvironment environment;
    }

    struct ReceiptFact {
        RH.Position position;
        H.Receipt receipt;
        RH.OriginEnvironment environment;
        uint256 logicalIndex;
    }

    struct ReplayFact {
        bytes32 originalKey;
        T.ReplayCell cell;
        OriginFact admission;
    }

    function load(W.EnvironmentV3 memory e, uint8 ownerIndex)
        public
        view
        returns (Context memory c)
    {
        if (ownerIndex != 2 && ownerIndex != 5) _invalid();
        c.ownerIndex = ownerIndex;
        c.current = _current(e);
        c.owner = c.current.owners[ownerIndex];
        IStreamArtistOwner own = IStreamArtistOwner(c.owner);
        if (
            own.artistRegistry() != e.registry || own.operationCoordinator() != e.coordinator
                || own.archiveV2() != e.archive || own.core() != e.core
                || own.mintManager() != e.manager || own.deploymentChainId() != e.chainId
                || own.domainId() != RH.ownerDomain(ownerIndex)
        ) _invalid();
        c.checkpoint = CP(c.owner).authorityCheckpoint();
        if (
            c.checkpoint.schema != RH.CHECKPOINT
                || c.checkpoint.ownerState.domainId != RH.ownerDomain(ownerIndex)
                || c.checkpoint.ownerState.stateRoot == 0
                || c.checkpoint.ownerState.recordChainTip == 0
                || keccak256(abi.encode(c.checkpoint.ownerState))
                    != keccak256(abi.encode(own.ownerStateSnapshotV2()))
        ) _invalid();
        (c.imported, c.importCommitment, c.importedAtRevision) =
            Owner(c.owner).recoveredHydrationImportedPrefix();
        if (Original(c.owner).authorityHydrationCommitment() != c.importCommitment) _invalid();
        if (c.importCommitment == 0) {
            if (
                c.importedAtRevision != 0 || c.imported.origins.length != 0
                    || c.imported.eras.length != 0 || c.imported.journal.length != 0
                    || c.imported.aliases.length != 0
            ) _invalid();
        } else {
            Provenance.validateOwner(c.imported, ownerIndex);
            if (
                c.importedAtRevision == 0 || c.importedAtRevision > c.checkpoint.ownerState.revision
            ) _invalid();
            for (uint256 i; i < c.imported.origins.length; ++i) {
                RH.OriginEnvironment memory old = c.imported.origins[i];
                if (
                    old.chainId != e.chainId || old.core != e.core || old.manager != e.manager
                        || old.registry == e.registry || old.coordinator == e.coordinator
                        || old.owners[ownerIndex] == c.owner
                        || RH.originHash(old) == RH.originHash(c.current)
                ) _invalid();
            }
        }
        c.nativeCount = Native(c.owner).artistNativeReceiptCount();
    }

    function logicalCount(Context memory c) public pure returns (uint256) {
        return c.imported.journal.length + c.nativeCount;
    }

    function receiptAt(Context memory c, uint256 index) public view returns (ReceiptFact memory f) {
        _fresh(c);
        if (index >= logicalCount(c)) _invalid();
        f.logicalIndex = index;
        if (index < c.imported.journal.length) {
            RH.JournalEntry memory row = c.imported.journal[index];
            f.position = row.position;
            f.receipt = row.receipt;
        } else {
            uint256 nativeIndex = index - c.imported.journal.length;
            uint64 revision = NativeClock(c.owner).artistNativeReceiptRevisionAt(nativeIndex);
            if (revision <= c.importedAtRevision || revision > c.checkpoint.ownerState.revision) {
                _invalid();
            }
            f.position = RH.Position(
                RH.Point(RH.originHash(c.current), c.ownerIndex, revision), nativeIndex
            );
            f.receipt = Native(c.owner).artistNativeReceiptAt(nativeIndex);
        }
        if (
            f.receipt.operation == 0 || f.receipt.recordHash == 0
                || (f.receipt.operation > 59 && f.receipt.operation != 61)
                || (f.receipt.artistId == 0 && f.receipt.collectionId == 0)
        ) _invalid();
        _point(c, f.position.point);
        f.environment = environment(c, f.position.point.environmentHash);
    }

    function auxiliary(Context memory c, bytes32 kind, bytes32 key)
        public
        view
        returns (OriginFact memory f)
    {
        _fresh(c);
        if (kind == 0 || key == 0) _invalid();
        // Deliberately no catch, zero sentinel, or current-origin inference from missing metadata.
        f.point = Owner(c.owner).recoveredHydrationAuxiliaryPoint(kind, key);
        _point(c, f.point);
        f.environment = environment(c, f.point.environmentHash);
    }

    function replay(Context memory c, bytes32 keyEnvironment, bytes32 surface, bytes32 scope)
        public
        view
        returns (ReplayFact memory f)
    {
        _fresh(c);
        if (surface == 0) _invalid();
        RH.OriginEnvironment memory origin = environment(c, keyEnvironment);
        f.originalKey = Keys.replayKey(origin, c.ownerIndex, AH.Origin(surface, scope));
        if (keyEnvironment == RH.originHash(c.current)) {
            f.cell = IStreamArtistOwner(c.owner).replayCell(f.originalKey);
            f.admission.point = Owner(c.owner).recoveredHydrationReplayPoint(f.originalKey);
        } else {
            bool found;
            for (uint256 i; i < c.imported.aliases.length; ++i) {
                RH.ReplayAlias memory a = c.imported.aliases[i];
                if (a.originalKey != f.originalKey) continue;
                if (
                    found || a.originHash != keyEnvironment || a.ownerIndex != c.ownerIndex
                        || a.surface != surface || a.scope != scope
                ) _invalid();
                f.cell = a.cell;
                f.admission.point = a.admittedAt;
                found = true;
            }
            if (!found) _invalid();
        }
        if (
            f.cell.status == 0 || f.cell.kind == 0 || f.cell.touchedRevision == 0
                || f.cell.touchedRevision != f.admission.point.ownerRevision
        ) _invalid();
        _point(c, f.admission.point);
        f.admission.environment = environment(c, f.admission.point.environmentHash);
    }

    function before(Context memory c, RH.Point memory first, RH.Point memory second)
        public
        pure
        returns (bool)
    {
        return Chronology.beforeOwner(_clock(c), c.ownerIndex, first, second);
    }

    function environment(Context memory c, bytes32 hash)
        public
        pure
        returns (RH.OriginEnvironment memory)
    {
        if (hash == RH.originHash(c.current)) return c.current;
        for (uint256 i; i < c.imported.origins.length; ++i) {
            if (RH.originHash(c.imported.origins[i]) == hash) return c.imported.origins[i];
        }
        revert RH.InvalidRecoveredHydrationProvenance();
    }

    function rewindEnvironment(RH.OriginEnvironment memory o)
        public
        pure
        returns (W.EnvironmentV3 memory)
    {
        return W.EnvironmentV3(
            o.chainId,
            o.registry,
            o.owners[2],
            o.ownerCodeHashes[2],
            o.owners[5],
            o.ownerCodeHashes[5],
            o.coordinator,
            o.archive,
            o.core,
            o.manager
        );
    }

    function nativeKind(uint16 operationId) public pure returns (bytes32) {
        return keccak256(
            abi.encode(keccak256("6529STREAM_ARTIST_RECOVERED_NATIVE_RECORD_V1"), operationId)
        );
    }

    function _current(W.EnvironmentV3 memory e)
        private
        view
        returns (RH.OriginEnvironment memory o)
    {
        if (
            e.chainId != block.chainid || e.coordinator.code.length == 0 || e.registry == address(0)
                || e.archive == address(0) || e.core == address(0) || e.manager == address(0)
        ) _invalid();
        T.SuiteConfiguration memory s = Deployment(e.coordinator).suiteConfiguration();
        if (
            s.registry != e.registry || s.archive != e.archive || s.core != e.core
                || s.mintManager != e.manager || s.owners[2] != e.identityOwner
                || s.owners[5] != e.payoutOwner || e.identityOwner.codehash != e.identityCodeHash
                || e.payoutOwner.codehash != e.payoutCodeHash
                || Deployment(e.coordinator).deploymentChainId() != e.chainId
        ) _invalid();
        o = RH.OriginEnvironment(
            e.chainId,
            e.registry,
            e.coordinator,
            e.archive,
            s.owners,
            o.ownerCodeHashes,
            e.core,
            e.manager,
            keccak256(abi.encode(s))
        );
        for (uint256 i; i < 7; ++i) {
            if (s.owners[i].code.length == 0) _invalid();
            for (uint256 j; j < i; ++j) {
                if (s.owners[j] == s.owners[i]) _invalid();
            }
            o.ownerCodeHashes[i] = s.owners[i].codehash;
        }
    }

    function _point(Context memory c, RH.Point memory point) private pure {
        Chronology.validateOwnerPoint(_clock(c), c.ownerIndex, point);
    }

    /// @dev Clock view only: retained admitted prefix plus the actual current owner checkpoint.
    /// It can contain MAX_ERAS+1 and is never submitted as a transport/import certificate.
    function _clock(Context memory c) private pure returns (RH.OwnerProvenance memory clock) {
        uint256 n = c.imported.eras.length;
        clock.origins = new RH.OriginEnvironment[](n + 1);
        clock.eras = new RH.OwnerEra[](n + 1);
        for (uint256 i; i < n; ++i) {
            clock.origins[i] = c.imported.origins[i];
            clock.eras[i] = c.imported.eras[i];
        }
        clock.origins[n] = c.current;
        clock.eras[n] = RH.OwnerEra(
            RH.originHash(c.current),
            c.checkpoint,
            c.nativeCount,
            c.importedAtRevision,
            c.importCommitment
        );
    }

    function _fresh(Context memory c) private view {
        if (
            (c.ownerIndex != 2 && c.ownerIndex != 5) || c.owner != c.current.owners[c.ownerIndex]
                || c.owner.codehash != c.current.ownerCodeHashes[c.ownerIndex]
                || keccak256(abi.encode(CP(c.owner).authorityCheckpoint()))
                    != keccak256(abi.encode(c.checkpoint))
                || Native(c.owner).artistNativeReceiptCount() != c.nativeCount
        ) _invalid();
    }

    function _invalid() private pure {
        revert RH.InvalidRecoveredHydrationProvenance();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import {
    StreamArtistRecoveredSimpleHydrationTypes as S
} from "../../interfaces/stream/artist/StreamArtistRecoveredSimpleHydrationTypes.sol";
import {
    StreamArtistRecoveredHydrationTypes as RH
} from "../../interfaces/stream/artist/StreamArtistRecoveredHydrationTypes.sol";
import {
    StreamArtistAuthorityHydrationTypes as AH
} from "../../interfaces/stream/artist/IStreamArtistAuthorityHydration.sol";
import {
    StreamArtistOnboardingTypes as T
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";
import {
    StreamArtistCollaboratorTypes as C
} from "../../interfaces/stream/artist/StreamArtistCollaboratorTypes.sol";
import {
    StreamArtistBindingLifecycleTypes as L
} from "../../interfaces/stream/artist/StreamArtistBindingLifecycleTypes.sol";
import {
    StreamArtistRecoveredHydrationProvenance as Provenance
} from "./StreamArtistRecoveredHydrationProvenance.sol";
import {
    StreamArtistRecoveredHydrationOwnerPayload as Payload
} from "./StreamArtistRecoveredHydrationOwnerPayload.sol";
import { StreamArtistHashes as Hashes } from "./StreamArtistHashes.sol";
import {
    StreamArtistCollaboratorHashes as Collaborators
} from "./StreamArtistCollaboratorHashes.sol";

/// @notice Fixed storage adapters for the singleton accepted generation1, no-collaborator profile.
/// @dev Every original owner era is accounted for, including non-native acceptance and imports.
/// Unknown maps cannot be inferred empty from a zero native count. Source checks read only this
/// semantic owner plus immutable suite bindings. Destination decoding makes no source call.
library StreamArtistRecoveredSimpleHydration {
    function exportBinding(
        mapping(uint256 => T.Binding) storage bindings,
        mapping(uint256 => mapping(uint64 => T.Binding)) storage history,
        mapping(uint256 => mapping(uint64 => C.BindingTerms)) storage terms,
        mapping(uint256 => mapping(uint64 => L.Terminal)) storage terminals,
        AH.Query memory q,
        RH.OwnerProvenance memory local
    ) public view returns (bytes memory) {
        Provenance.validateOwnerSource(local, 0, address(this));
        S.Binding memory b;
        b.scope = scope(q);
        b.provenanceCommitment = RH.ownerProvenanceHash(local, 0);
        b.item = bindings[q.collectionId];
        b.history = history[q.collectionId][1];
        b.terms = terms[q.collectionId][1];
        b.terminal = terminals[q.collectionId][1];
        validateBinding(q, local, b);
        return abi.encode(S.BINDING, RH.VERSION, b);
    }

    function importBinding(
        mapping(uint256 => T.Binding) storage bindings,
        mapping(uint256 => mapping(uint64 => T.Binding)) storage history,
        mapping(uint256 => mapping(uint64 => C.BindingTerms)) storage terms,
        mapping(uint256 => mapping(uint64 => L.Terminal)) storage terminals,
        AH.Query memory q,
        bytes memory raw
    ) public {
        (RH.ExportHeader memory header, Payload.Payload memory p) = Payload.decode(raw, 0);
        S.Binding memory b = decodeBinding(q, p.provenance, p.semanticState);
        if (b.item.consentMode == 2 && (header.requiredFeatures & RH.DELEGATED_CONSENT) == 0) {
            revert RH.InvalidRecoveredHydrationProfile();
        }
        T.Binding memory emptyBinding;
        C.BindingTerms memory emptyTerms;
        L.Terminal memory emptyTerminal;
        if (
            keccak256(abi.encode(bindings[q.collectionId])) != keccak256(abi.encode(emptyBinding))
                || keccak256(abi.encode(history[q.collectionId][1]))
                    != keccak256(abi.encode(emptyBinding))
                || keccak256(abi.encode(terms[q.collectionId][1]))
                    != keccak256(abi.encode(emptyTerms))
                || keccak256(abi.encode(terminals[q.collectionId][1]))
                    != keccak256(abi.encode(emptyTerminal))
        ) revert T.InvalidRecord();
        bindings[q.collectionId] = b.item;
        history[q.collectionId][1] = b.history;
        terms[q.collectionId][1] = b.terms;
        terminals[q.collectionId][1] = b.terminal;
    }

    function exportAcceptance(
        mapping(bytes32 => bytes32) storage records,
        mapping(bytes32 => uint64) storage times,
        AH.Query memory q,
        RH.OwnerProvenance memory local
    ) public view returns (bytes memory) {
        Provenance.validateOwnerSource(local, 3, address(this));
        S.Acceptance memory a = S.Acceptance(
            scope(q), RH.ownerProvenanceHash(local, 3), records[q.bindingHash], times[q.bindingHash]
        );
        validateAcceptance(q, local, a);
        return abi.encode(S.ACCEPTANCE, RH.VERSION, a);
    }

    function importAcceptance(
        mapping(bytes32 => bytes32) storage records,
        mapping(bytes32 => uint64) storage times,
        AH.Query memory q,
        bytes memory raw
    ) public {
        (, Payload.Payload memory p) = Payload.decode(raw, 3);
        S.Acceptance memory a = decodeAcceptance(q, p.provenance, p.semanticState);
        if (records[q.bindingHash] != 0 || times[q.bindingHash] != 0) revert T.InvalidRecord();
        records[q.bindingHash] = a.record;
        times[q.bindingHash] = a.acceptedAt;
    }

    function exportCollaborator(AH.Query memory q, RH.OwnerProvenance memory local)
        public
        view
        returns (bytes memory)
    {
        Provenance.validateOwnerSource(local, 1, address(this));
        S.EmptyCollaborator memory c =
            S.EmptyCollaborator(scope(q), RH.ownerProvenanceHash(local, 1));
        validateCollaborator(q, local, c);
        return abi.encode(S.COLLABORATOR, RH.VERSION, c);
    }

    function importCollaborator(AH.Query memory q, bytes memory raw) public pure {
        (, Payload.Payload memory p) = Payload.decode(raw, 1);
        decodeCollaborator(q, p.provenance, p.semanticState);
        // The exact zero-history certificate has no semantic map entry to install.
    }

    function decodeBinding(AH.Query memory q, RH.OwnerProvenance memory local, bytes memory raw)
        public
        pure
        returns (S.Binding memory b)
    {
        bytes32 tag;
        uint16 version;
        (tag, version, b) = abi.decode(raw, (bytes32, uint16, S.Binding));
        _canonical(raw, tag, S.BINDING, version, abi.encode(tag, version, b));
        validateBinding(q, local, b);
    }

    function decodeAcceptance(AH.Query memory q, RH.OwnerProvenance memory local, bytes memory raw)
        public
        pure
        returns (S.Acceptance memory a)
    {
        bytes32 tag;
        uint16 version;
        (tag, version, a) = abi.decode(raw, (bytes32, uint16, S.Acceptance));
        _canonical(raw, tag, S.ACCEPTANCE, version, abi.encode(tag, version, a));
        validateAcceptance(q, local, a);
    }

    function decodeCollaborator(
        AH.Query memory q,
        RH.OwnerProvenance memory local,
        bytes memory raw
    ) public pure returns (S.EmptyCollaborator memory c) {
        bytes32 tag;
        uint16 version;
        (tag, version, c) = abi.decode(raw, (bytes32, uint16, S.EmptyCollaborator));
        _canonical(raw, tag, S.COLLABORATOR, version, abi.encode(tag, version, c));
        validateCollaborator(q, local, c);
    }

    function validateBinding(AH.Query memory q, RH.OwnerProvenance memory local, S.Binding memory b)
        public
        pure
    {
        _scope(q, b.scope);
        _history(local, 0, b.provenanceCommitment);
        RH.JournalEntry memory row = local.journal[0];
        L.Terminal memory emptyTerminal;
        if (
            b.item.artistId != q.artistId || b.item.bindingHash != q.bindingHash
                || b.item.artistAddress == address(0) || b.item.identityRecordHash == 0
                || b.item.proposer == address(0) || b.item.generation != 1 || !b.item.accepted
                || (b.item.consentMode != 1 && b.item.consentMode != 2)
                || b.item.saleConsentScope > 1 || b.item.registryImmutabilityElection > 1
                || keccak256(abi.encode(b.item)) != keccak256(abi.encode(b.history))
                || keccak256(abi.encode(b.terminal)) != keccak256(abi.encode(emptyTerminal))
                || b.terms.count != 0 || b.terms.mode != 0 || b.terms.threshold != 0
                || b.terms.collaboratorSetHash != Hashes.emptyCollaborators()
                || b.terms.capabilityPolicySetHash != Hashes.emptyCapabilities()
                || row.receipt.artistId != q.artistId || row.receipt.collectionId != q.collectionId
                || row.receipt.recordHash != q.bindingHash
        ) revert T.UnsupportedProfile();
        RH.OriginEnvironment memory origin = local.origins[0];
        if (
            Collaborators.binding(
                    Hashes.Environment(
                        origin.chainId, origin.registry, origin.core, origin.manager
                    ),
                    q.collectionId,
                    b.item,
                    new T.CollaboratorRecord[](0)
                ) != q.bindingHash
        ) revert T.InvalidRecord();
        _guards(
            local,
            0,
            keccak256("binding_lifecycle.replay.proposal_key"),
            keccak256(abi.encode(q.collectionId, uint64(1))),
            q.bindingHash
        );
    }

    function validateAcceptance(
        AH.Query memory q,
        RH.OwnerProvenance memory local,
        S.Acceptance memory a
    ) public pure {
        _scope(q, a.scope);
        _history(local, 3, a.provenanceCommitment);
        RH.JournalEntry memory row = local.journal[0];
        if (
            a.record == 0 || a.acceptedAt == 0 || row.receipt.artistId != q.artistId
                || row.receipt.collectionId != q.collectionId || row.receipt.recordHash != a.record
        ) revert T.UnsupportedProfile();
        // The original mapping stores record/time, not signer/nonce. The actual owner export
        // authenticates those unchanged fields; a guessed acceptance preimage is not substituted.
        _guards(local, 3, keccak256("acceptance_lifecycle.replay.record_uniqueness"), 0, a.record);
    }

    function validateCollaborator(
        AH.Query memory q,
        RH.OwnerProvenance memory local,
        S.EmptyCollaborator memory c
    ) public pure {
        _scope(q, c.scope);
        _history(local, 1, c.provenanceCommitment);
        if (local.aliases.length != 0) revert T.UnsupportedProfile();
        RH.OriginEnvironment memory origin = local.origins[0];
        T.Snapshot memory initial = local.eras[0].checkpoint.ownerState;
        if (
            initial.stateRoot
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_ARTIST_OWNER_STATE_GENESIS_V2"),
                            origin.chainId,
                            origin.registry,
                            origin.coordinator,
                            origin.archive,
                            origin.owners[1],
                            RH.ownerDomain(1)
                        )
                    )
                || initial.recordChainTip
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_ARTIST_OWNER_RECORD_GENESIS_V2"),
                            origin.chainId,
                            origin.registry,
                            origin.coordinator,
                            origin.archive,
                            origin.owners[1],
                            RH.ownerDomain(1)
                        )
                    )
        ) revert T.UnsupportedProfile();
    }

    function scope(AH.Query memory q) public pure returns (S.Scope memory result) {
        if (q.artistId == 0 || q.collectionId == 0 || q.bindingHash == 0) {
            revert T.UnsupportedProfile();
        }
        return S.Scope(q.artistId, q.collectionId, q.bindingHash);
    }

    function _scope(AH.Query memory q, S.Scope memory actual) private pure {
        if (keccak256(abi.encode(scope(q))) != keccak256(abi.encode(actual))) {
            revert T.InvalidRecord();
        }
    }

    function _history(RH.OwnerProvenance memory local, uint8 ownerIndex, bytes32 commitment)
        private
        pure
    {
        if (Provenance.validateOwner(local, ownerIndex) != commitment) {
            revert RH.InvalidRecoveredHydrationProvenance();
        }
        bool empty = ownerIndex == 1;
        if (local.journal.length != (empty ? 0 : 1)) revert T.UnsupportedProfile();
        for (uint256 i; i < local.eras.length; ++i) {
            RH.OwnerEra memory era = local.eras[i];
            uint256 nativeCount = i == 0 && !empty ? 1 : 0;
            uint64 expectedRevision = i == 0 ? (empty ? 0 : (ownerIndex == 0 ? 2 : 1)) : 1;
            if (
                era.nativeCount != nativeCount || era.lowerRevision != (i == 0 ? 0 : 1)
                    || era.checkpoint.ownerState.revision != expectedRevision
                    || era.checkpoint.nonceIndexCount != 0 || era.checkpoint.nonceRoot != 0
                    || era.checkpoint.replayCount != (empty ? 0 : 1)
                    || (empty && era.checkpoint.replayRoot != 0)
            ) revert T.UnsupportedProfile();
        }
        if (!empty) {
            RH.JournalEntry memory row = local.journal[0];
            if (
                row.position.point.environmentHash != local.eras[0].originHash
                    || row.position.point.ownerRevision != 1
                    || row.receipt.operation != (ownerIndex == 0 ? 1 : 2)
            ) revert T.UnsupportedProfile();
        }
    }

    function _guards(
        RH.OwnerProvenance memory local,
        uint8 ownerIndex,
        bytes32 surface,
        bytes32 exactScope,
        bytes32 record
    ) private pure {
        if (local.aliases.length != local.eras.length) {
            revert T.UnsupportedProfile();
        }
        for (uint256 i; i < local.aliases.length; ++i) {
            RH.ReplayAlias memory a = local.aliases[i];
            if (
                a.ownerIndex != ownerIndex || a.surface != surface || a.scope == 0
                    || (exactScope != 0 && a.scope != exactScope) || a.cell.commitment != record
                    || a.cell.kind != 1 || a.cell.status != 2
                    || keccak256(abi.encode(a.admittedAt))
                        != keccak256(abi.encode(local.journal[0].position.point))
            ) revert T.UnsupportedProfile();
        }
    }

    function _canonical(
        bytes memory raw,
        bytes32 actual,
        bytes32 expected,
        uint16 version,
        bytes memory canonical
    ) private pure {
        if (actual != expected || version != RH.VERSION || keccak256(raw) != keccak256(canonical)) {
            revert RH.InvalidRecoveredHydrationProfile();
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import {
    StreamArtistRecoveredTimingTypes as TM
} from "../../interfaces/stream/artist/StreamArtistRecoveredTimingTypes.sol";

/// @notice Complete observer over the five original validated timing writers.
/// @dev note is called after original validation/mutation and changes no original key, hash,
/// event, timing revision, liveness, native journal or semantic-owner mutation counter.
/// The fixed new host initializes this namespace; absence never means an empty history.
library StreamArtistRecoveredTimingInventory {
    bytes32 private constant SLOT = keccak256("6529STREAM_ARTIST_RECOVERED_TIMING_STORAGE_V1");

    struct State {
        bytes32 schema;
        bytes32 root;
        TM.Entry[] entries;
        uint64[5] changes;
        mapping(bytes32 => bool) seen;
    }

    function state() internal pure returns (State storage s) {
        bytes32 slot = SLOT;
        assembly ("memory-safe") { s.slot := slot }
    }

    function initialize() public {
        State storage s = state();
        if (s.schema != 0 || s.root != 0 || s.entries.length != 0) {
            revert TM.RecoveredTimingUnavailable();
        }
        s.schema = TM.SCHEMA;
    }

    function note(TM.Input memory change) public {
        State storage s = state();
        if (s.schema != TM.SCHEMA) revert TM.RecoveredTimingUnavailable();
        (, uint8 group, uint64 floor) = _parameter(change.parameter);
        if (
            change.oldRevision != s.changes[group] + 1
                || change.newRevision != change.oldRevision + 1 || change.floor != floor
                || change.actionId == 0 || change.oldValue == change.newValue
                || change.newValue < floor
                || change.actionKey
                    != keccak256(
                        abi.encode(
                            change.actionId, change.parameter, change.oldHash, change.newHash
                        )
                    )
                || change.oldHash
                    != _stateHash(
                        block.chainid,
                        address(this),
                        change.parameter,
                        change.oldValue,
                        floor,
                        change.oldRevision
                    )
                || change.newHash
                    != _stateHash(
                        block.chainid,
                        address(this),
                        change.parameter,
                        change.newValue,
                        floor,
                        change.newRevision
                    ) || s.seen[change.actionKey]
        ) revert TM.InvalidRecoveredTiming(change.actionKey);
        TM.Entry memory entry =
            TM.Entry(block.chainid, address(this), s.entries.length, change, s.root, bytes32(0));
        entry.commitment = _hash(entry);
        s.entries.push(entry);
        s.root = entry.commitment;
        ++s.changes[group];
        s.seen[change.actionKey] = true;
    }

    function collect(TM.Configuration memory configuration)
        public
        view
        returns (TM.Bundle memory b)
    {
        State storage s = state();
        if (s.schema != TM.SCHEMA || s.entries.length > TM.MAX_ENTRIES) {
            revert TM.RecoveredTimingUnavailable();
        }
        b.configuration = configuration;
        b.entries = s.entries;
        b.checkpoint = TM.Checkpoint(
            TM.SCHEMA, TM.VERSION, b.entries.length, s.root, keccak256(abi.encode(configuration))
        );
        validate(b);
    }

    function checkpoint(TM.Configuration memory configuration)
        public
        view
        returns (TM.Checkpoint memory)
    {
        State storage s = state();
        if (s.schema != TM.SCHEMA || s.entries.length > TM.MAX_ENTRIES) {
            revert TM.RecoveredTimingUnavailable();
        }
        return TM.Checkpoint(
            TM.SCHEMA, TM.VERSION, s.entries.length, s.root, keccak256(abi.encode(configuration))
        );
    }

    function entryAt(uint256 index) public view returns (TM.Entry memory) {
        if (state().schema != TM.SCHEMA) revert TM.RecoveredTimingUnavailable();
        return state().entries[index];
    }

    /// @dev Called by the authenticated fixed operation60 worker before any copied timing maps.
    function install(TM.Bundle memory b) public {
        validate(b);
        State storage s = state();
        if (s.schema != TM.SCHEMA) revert TM.RecoveredTimingUnavailable();
        if (s.entries.length == b.entries.length && s.root == b.checkpoint.root) return;
        if (s.entries.length != 0 || s.root != 0) revert TM.RecoveredTimingUnavailable();
        for (uint256 i; i < b.entries.length; ++i) {
            TM.Entry memory e = b.entries[i];
            (, uint8 group,) = _parameter(e.change.parameter);
            s.entries.push(e);
            ++s.changes[group];
            s.seen[e.change.actionKey] = true;
        }
        s.root = b.checkpoint.root;
    }

    function validate(TM.Bundle memory b) public pure returns (bytes32) {
        if (
            b.entries.length > TM.MAX_ENTRIES || b.checkpoint.schema != TM.SCHEMA
                || b.checkpoint.version != TM.VERSION || b.checkpoint.count != b.entries.length
                || b.checkpoint.configurationHash != keccak256(abi.encode(b.configuration))
        ) revert TM.RecoveredTimingUnavailable();
        uint64[7] memory values =
            [uint64(7 days), 90 days, 180 days, 730 days, 365 days, 90 days, 7 days];
        uint64[5] memory revisions = [uint64(1), 1, 1, 1, 1];
        bytes32 previous;
        for (uint256 i; i < b.entries.length; ++i) {
            TM.Entry memory e = b.entries[i];
            TM.Input memory c = e.change;
            (uint8 parameter, uint8 group, uint64 floor) = _parameter(c.parameter);
            if (
                e.chainId == 0 || e.owner == address(0) || e.index != i
                    || e.previousCommitment != previous || e.commitment != _hash(e)
                    || c.actionId == 0 || c.oldValue != values[parameter]
                    || c.oldRevision != revisions[group] || c.newRevision != c.oldRevision + 1
                    || c.newValue == c.oldValue || c.newValue < floor || c.floor != floor
                    || c.actionKey
                        != keccak256(abi.encode(c.actionId, c.parameter, c.oldHash, c.newHash))
                    || c.oldHash
                        != _stateHash(
                            e.chainId, e.owner, c.parameter, c.oldValue, floor, c.oldRevision
                        )
                    || c.newHash
                        != _stateHash(
                            e.chainId, e.owner, c.parameter, c.newValue, floor, c.newRevision
                        )
            ) revert TM.InvalidRecoveredTiming(c.actionKey);
            for (uint256 j; j < i; ++j) {
                if (b.entries[j].change.actionKey == c.actionKey) {
                    revert TM.InvalidRecoveredTiming(c.actionKey);
                }
            }
            values[parameter] = c.newValue;
            revisions[group] = c.newRevision;
            previous = e.commitment;
        }
        if (previous != b.checkpoint.root) revert TM.RecoveredTimingUnavailable();
        for (uint256 i; i < 7; ++i) {
            uint64 actual = b.configuration.values[i];
            // Original raw zero stores its immutable default, not a fabricated governed write.
            if (actual == 0) actual = _default(i);
            if (actual != values[i]) revert TM.RecoveredTimingUnavailable();
        }
        for (uint256 i; i < 5; ++i) {
            uint64 actual = b.configuration.revisions[i] == 0 ? 1 : b.configuration.revisions[i];
            if (actual != revisions[i]) revert TM.RecoveredTimingUnavailable();
        }
        return keccak256(abi.encode(TM.SCHEMA, TM.VERSION, b));
    }

    function parameter(bytes32 key) public pure returns (uint8 index, uint8 group, uint64 floor) {
        return _parameter(key);
    }

    function _parameter(bytes32 key) private pure returns (uint8, uint8, uint64) {
        if (key == keccak256("ARTIST_ROTATION_CONTEST_SECONDS")) return (0, 0, 72 hours);
        if (key == keccak256("ARTIST_PRIOR_ADDRESS_STANDING_TAIL_SECONDS")) return (1, 0, 30 days);
        if (key == keccak256("ARTIST_ESTATE_ACTIVATION_NOTICE_SECONDS")) return (2, 1, 90 days);
        if (key == keccak256("ARTIST_DORMANCY_MIN_INACTIVITY_SECONDS")) return (3, 2, 365 days);
        if (key == keccak256("ARTIST_DORMANCY_NOTICE_SECONDS")) return (4, 2, 180 days);
        if (key == keccak256("ARTIST_UNAVAILABILITY_RECOVERY_NOTICE_SECONDS")) {
            return (5, 3, 30 days);
        }
        if (key == keccak256("ARTIST_REPUDIATION_CONTEST_SECONDS")) return (6, 4, 3 days);
        revert TM.InvalidRecoveredTiming(key);
    }

    function _default(uint256 i) private pure returns (uint64) {
        if (i == 0 || i == 6) return 7 days;
        if (i == 1 || i == 5) return 90 days;
        if (i == 2) return 180 days;
        if (i == 3) return 730 days;
        return 365 days;
    }

    function _hash(TM.Entry memory e) private pure returns (bytes32) {
        e.commitment = 0;
        return keccak256(abi.encode(TM.SCHEMA, TM.VERSION, e));
    }

    function _stateHash(
        uint256 chainId,
        address owner,
        bytes32 parameter_,
        uint64 value,
        uint64 floor,
        uint64 revision
    ) private pure returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_WINDOW_STATE_V1"),
                chainId,
                owner,
                parameter_,
                value,
                floor,
                revision
            )
        );
    }
}

