pragma solidity ^0.8.19;
import {
    StreamArtistGuardianAppealTypes as Appeal
} from "../../interfaces/stream/artist/StreamArtistGuardianAppealTypes.sol";
import {
    IStreamArtistGuardianAppealOwner
} from "../../interfaces/stream/artist/IStreamArtistGuardianAppealEvidence.sol";
import { StreamArtistGuardianAppealReads } from "./StreamArtistGuardianAppealReads.sol";
import { StreamArtistHashes } from "./StreamArtistHashes.sol";
import {
    IStreamArtistGuardianSelectionOwner
} from "../../interfaces/stream/artist/IStreamArtistGuardianSelectionPreparation.sol";
import {
    StreamArtistGuardianSelectionTypes as Selection
} from "../../interfaces/stream/artist/StreamArtistGuardianSelectionTypes.sol";
import {
    StreamArtistRotationTypes as Rotation
} from "../../interfaces/stream/artist/StreamArtistRotationTypes.sol";
import {
    IStreamArtistGuardianHistory
} from "../../interfaces/stream/artist/IStreamArtistGuardianHistory.sol";
import {
    StreamArtistGuardianHistoryTypes as GH
} from "../../interfaces/stream/artist/StreamArtistGuardianHistoryTypes.sol";

import { StreamArtistRecoveryActionReads as Reads } from "./StreamArtistRecoveryActionReads.sol";
import {
    StreamArtistRecoveryActionTypes as A
} from "../../interfaces/stream/artist/StreamArtistRecoveryActionTypes.sol";
import {
    StreamArtistIdentityRecoveryOperationTypes as R
} from "../../interfaces/stream/artist/StreamArtistIdentityRecoveryOperationTypes.sol";
import {
    StreamArtistOnboardingTypes as T
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";
import {
    StreamArtistDelegationTypes as D
} from "../../interfaces/stream/artist/StreamArtistDelegationTypes.sol";
import {
    IStreamArtistRecoveryActionOwner
} from "../../interfaces/stream/artist/IStreamArtistRecoveryAction.sol";
import {
    IStreamArtistIdentityRecoveryOwner
} from "../../interfaces/stream/artist/IStreamArtistIdentityRecovery.sol";
import { IStreamArtistOwner } from "../../interfaces/stream/artist/IStreamArtistOwner.sol";
import { IStreamArtistArchiveV2 } from "../../interfaces/stream/artist/IStreamArtistArchiveV2.sol";
import { GovernanceCall } from "../../interfaces/stream/governance/StreamGovernanceTypes.sol";

/// @notice Explicit auxiliary and operation34 recipes, invoked inside the pinned Coordinator lock.
library StreamArtistRecoveryActionOperations {
    function prepare(
        D.CoordinatorContext memory x,
        address actor,
        bytes32 actionId,
        GovernanceCall[] memory calls,
        R.Request memory p,
        T.Authorization memory acceptance
    ) public returns (bytes32 association) {
        address identity = x.suite.owners[2];
        T.Snapshot[7] memory before_;
        before_[2] = IStreamArtistOwner(identity).ownerStateSnapshotV2();
        R.Context memory context =
            IStreamArtistIdentityRecoveryOwner(identity).identityRecoveryContext(p, acceptance);
        IStreamArtistRecoveryActionOwner owner = IStreamArtistRecoveryActionOwner(identity);
        (address executor, bytes32 codeHash) = owner.recoveryExecutorBinding();
        bool appeal = p.supersededRecordHashes.length != 0
            && IStreamArtistGuardianAppealOwner(identity)
                    .guardianRecoveryAuthorityRole(p.artistId, p.supersededRecordHashes)
                == Appeal.APPEAL;
        A.Witness memory w = appeal
            ? Reads.prepareAppeal(
                A.Environment(x.suite.registry, executor, codeHash, x.suite.roleRegistry),
                actionId,
                calls,
                p,
                acceptance,
                context
            )
            : Reads.prepare(
                A.Environment(x.suite.registry, executor, codeHash, x.suite.roleRegistry),
                actionId,
                calls,
                p,
                acceptance,
                context
            );
        (A.Association memory previous,,,) =
            owner.identityRecoveryActionState(p.artistId, bytes32(0));
        bool terminal = previous.associationHash == bytes32(0) || Reads.terminal(previous.action);
        association = owner.prepareIdentityRecoveryAction(
            T.ActionContext(A.PREPARE_OPERATION, actor, before_[2]),
            p,
            acceptance,
            w,
            previous.associationHash,
            terminal
        );
        (A.Association memory saved, A.Veto memory veto, bytes32 executed, uint64 count) =
            owner.identityRecoveryActionState(p.artistId, actionId);
        if (
            association == bytes32(0) || saved.associationHash != association
                || veto.vetoer != address(0) || executed != bytes32(0)
                || saved.action.actionId != actionId
        ) revert T.InvalidRecord();
        (GH.Head memory head,, GH.Snapshot memory history,) = IStreamArtistGuardianHistory(
                address(owner)
            ).guardianHistoryState(p.artistId, 0, address(0), actionId);
        if (
            history.associationHash != association || history.artistId != p.artistId
                || history.count != count || head.count != count
                || history.historyCommitment != head.commitment
        ) revert T.InvalidRecord();
        bytes memory payload =
            _preparationPayload(identity, p, acceptance, context, saved, count, history);
        if (appeal) {
            payload = abi.encode(
                payload,
                abi.encode(
                    StreamArtistGuardianAppealReads.read(
                        identity,
                        StreamArtistHashes.Environment(
                            block.chainid, x.suite.registry, x.suite.core, x.suite.mintManager
                        ),
                        p
                    )
                )
            );
        }
        _archive(x, actor, A.PREPARE_OPERATION, association, before_, payload);
    }

    function _preparationPayload(
        address identity,
        R.Request memory p,
        T.Authorization memory acceptance,
        R.Context memory context,
        A.Association memory saved,
        uint64 count,
        GH.Snapshot memory history
    ) private view returns (bytes memory) {
        if (p.supersededRecordHashes.length != 0) {
            (Selection.Result memory result, Rotation.GuardianRecord memory restored) = IStreamArtistGuardianSelectionOwner(
                    identity
                ).guardianRecoverySelection(saved.action.actionId);
            if (result.commitment != 0) {
                return abi.encode(p, acceptance, context, saved, count, history, result, restored);
            }
        }
        return abi.encode(p, acceptance, context, saved, count, history);
    }

    function veto(D.CoordinatorContext memory x, address actor, bytes32 artistId, bytes32 reason)
        public
    {
        address identity = x.suite.owners[2];
        T.Snapshot[7] memory before_;
        before_[2] = IStreamArtistOwner(identity).ownerStateSnapshotV2();
        IStreamArtistRecoveryActionOwner owner = IStreamArtistRecoveryActionOwner(identity);
        (A.Association memory a,,,) = owner.identityRecoveryActionState(artistId, bytes32(0));
        if (a.associationHash == bytes32(0)) revert A.InvalidRecoveryAction(bytes32(0));
        Reads.requireScheduled(a.action);
        owner.vetoPreparedIdentityRecovery(
            T.ActionContext(34, actor, before_[2]), artistId, a.action.actionId, reason, true
        );
        (, A.Veto memory v, bytes32 executed,) =
            owner.identityRecoveryActionState(artistId, a.action.actionId);
        if (v.vetoer != actor || v.reasonHash != reason || executed != bytes32(0)) {
            revert T.InvalidRecord();
        }
        bytes32 id = keccak256(abi.encode(a.associationHash, v));
        _archive(x, actor, 34, id, before_, abi.encode(a, v));
    }

    function requireExecution(address identity, bytes32 artistId, bytes32 actionId) public view {
        IStreamArtistRecoveryActionOwner owner = IStreamArtistRecoveryActionOwner(identity);
        (A.Association memory a,,,) = owner.identityRecoveryActionState(artistId, actionId);
        // The owner independently rejects an unprepared guarded context. The original unguarded profile stays exact.
        if (a.associationHash == bytes32(0)) return;
        (address executor, bytes32 codeHash) = owner.recoveryExecutorBinding();
        if (a.action.executor != executor || a.action.executorCodeHash != codeHash) {
            revert T.InvalidBinding();
        }
        Reads.requireExecuted(a.action);
    }

    function _archive(
        D.CoordinatorContext memory x,
        address actor,
        uint16 operation,
        bytes32 commitment,
        T.Snapshot[7] memory before_,
        bytes memory payload
    ) private {
        T.Snapshot[7] memory after_;
        after_[2] = IStreamArtistOwner(x.suite.owners[2]).ownerStateSnapshotV2();
        bytes32 id = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_ONBOARDING_OPERATION_EVIDENCE_V1"),
                block.chainid,
                x.suite.registry,
                address(this),
                operation,
                actor,
                commitment
            )
        );
        bytes memory evidence = abi.encode(
            uint16(1), x.configurationHash, operation, actor, bytes32(0), before_, after_, payload
        );
        (bytes32 hash,, bool appended) =
            IStreamArtistArchiveV2(x.suite.archive).appendArtistEvidenceV2(id, 1, evidence);
        if (!appended || hash != keccak256(evidence)) revert T.InvalidRecord();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import { StreamArtistGuardianAppealAuthority } from "./StreamArtistGuardianAppealAuthority.sol";

import {
    StreamArtistRecoveryActionTypes as A
} from "../../interfaces/stream/artist/StreamArtistRecoveryActionTypes.sol";
import {
    StreamArtistIdentityRecoveryOperationTypes as R
} from "../../interfaces/stream/artist/StreamArtistIdentityRecoveryOperationTypes.sol";
import {
    StreamArtistOnboardingTypes as T
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";
import {
    IStreamArtistIdentityRecovery
} from "../../interfaces/stream/artist/IStreamArtistIdentityRecovery.sol";
import {
    IStreamArtistIdentityRecoveryV2
} from "../../interfaces/stream/artist/IStreamArtistIdentityRecoveryV2.sol";
import {
    IStreamGovernanceActionFacts
} from "../../interfaces/stream/governance/IStreamGovernanceActionFacts.sol";
import {
    IStreamGovernanceReads
} from "../../interfaces/stream/governance/IStreamGovernanceReads.sol";
import { IStreamRoleRegistry } from "../../interfaces/stream/governance/IStreamRoleRegistry.sol";
import {
    GovernanceCall,
    GovernanceActionStatus
} from "../../interfaces/stream/governance/StreamGovernanceTypes.sol";

/// @notice Complete scheduled-batch authentication for Identity's auxiliary preparation.
/// @dev The Coordinator supplies its fixed suite and the Identity child's original Executor pin.
library StreamArtistRecoveryActionReads {
    bytes32 private constant CALLS =
        0x10f09566fb70f7947b61639c2a53b3aec872069a8b46edd08ba14eb2b5942b70;

    function prepare(
        A.Environment memory e,
        bytes32 actionId,
        GovernanceCall[] memory calls,
        R.Request memory request,
        T.Authorization memory acceptance,
        R.Context memory context
    ) public view returns (A.Witness memory w) {
        return _prepare(e, actionId, calls, request, acceptance, context, false, bytes32(0));
    }

    function prepareAppeal(
        A.Environment memory e,
        bytes32 actionId,
        GovernanceCall[] memory calls,
        R.Request memory request,
        T.Authorization memory acceptance,
        R.Context memory context
    ) public view returns (A.Witness memory w) {
        return _prepare(e, actionId, calls, request, acceptance, context, true, bytes32(0));
    }

    /// @notice Exact additive selector/calldata authentication; zero never selects V1 implicitly.
    function prepareV2(
        A.Environment memory e,
        bytes32 actionId,
        GovernanceCall[] memory calls,
        R.Request memory request,
        T.Authorization memory acceptance,
        R.Context memory context,
        bool appeal,
        bytes32 manifestHash
    ) public view returns (A.Witness memory w) {
        if (manifestHash == bytes32(0)) revert A.InvalidRecoveryAction(actionId);
        return _prepare(e, actionId, calls, request, acceptance, context, appeal, manifestHash);
    }

    function _prepare(
        A.Environment memory e,
        bytes32 actionId,
        GovernanceCall[] memory calls,
        R.Request memory request,
        T.Authorization memory acceptance,
        R.Context memory context,
        bool appeal,
        bytes32 manifestHash
    ) private view returns (A.Witness memory w) {
        _pin(e.executor, e.executorCodeHash);
        if (e.registry.code.length == 0 || e.roles.code.length == 0) {
            revert A.InvalidRecoveryAction(actionId);
        }
        bytes memory sealedState = _fixed(
            e.executor, abi.encodeCall(IStreamGovernanceReads.systemManifestBootstrapState, ()), 928
        );
        if (_word(sealedState, 0) != 1 || _word(sealedState, 1) != 1) {
            revert A.InvalidRecoveryAction(actionId);
        }
        IStreamGovernanceActionFacts.ActionFacts memory facts = _facts(e.executor, actionId);
        uint256 delay = _word(
            _fixed(e.executor, abi.encodeCall(IStreamGovernanceReads.minimumDelay, (uint8(2))), 32),
            0
        );
        if (
            facts.status != GovernanceActionStatus.SCHEDULED || facts.actionClass != 2
                || facts.notBefore > facts.expiresAfter || delay < 72 hours
                || delay > type(uint64).max || block.timestamp > type(uint64).max
                || block.timestamp + delay > facts.notBefore || acceptance.time < facts.notBefore
                || acceptance.signature.length > 4096 || request.supersededRecordHashes.length > 64
        ) revert A.InvalidRecoveryAction(actionId);
        w.actionId = actionId;
        w.callsHash = keccak256(abi.encode(CALLS, calls));
        if (w.callsHash != facts.callHash) revert A.InvalidRecoveryAction(actionId);
        bytes4 selector;
        if (manifestHash == bytes32(0)) {
            selector = IStreamArtistIdentityRecovery.recoverArtistIdentity.selector;
            w.callDataHash = keccak256(
                abi.encodeCall(
                    IStreamArtistIdentityRecovery.recoverArtistIdentity, (request, acceptance)
                )
            );
        } else {
            selector = IStreamArtistIdentityRecoveryV2.recoverArtistIdentityV2.selector;
            w.callDataHash = keccak256(
                abi.encodeCall(
                    IStreamArtistIdentityRecoveryV2.recoverArtistIdentityV2,
                    (request, acceptance, manifestHash)
                )
            );
        }
        uint256 matches;
        for (uint256 i; i < calls.length; ++i) {
            GovernanceCall memory call_ = calls[i];
            if (call_.selector != selector) continue;
            if (
                call_.target != e.registry || call_.value != 0
                    || call_.callDataHash != w.callDataHash || call_.scopeHash != context.scopeHash
                    || call_.oldValueHash != context.oldValueHash
                    || call_.newValueHash != context.newValueHash
            ) revert A.InvalidRecoveryAction(actionId);
            w.callIndex = i;
            ++matches;
        }
        if (matches != 1) revert A.InvalidRecoveryAction(actionId);
        w.executor = e.executor;
        w.executorCodeHash = e.executorCodeHash;
        w.notBefore = facts.notBefore;
        w.expiresAfter = facts.expiresAfter;
        w.minimumDelay = uint64(delay);
        _proposer(e, w, request.reasonHash, facts, appeal);
    }

    /// @notice An expired SCHEDULED action cannot execute, even before its status is materialized.
    function terminal(A.Witness memory w) public view returns (bool) {
        _pin(w.executor, w.executorCodeHash);
        IStreamGovernanceActionFacts.ActionFacts memory a = _facts(w.executor, w.actionId);
        _same(w, a);
        return a.status == GovernanceActionStatus.CANCELLED
            || a.status == GovernanceActionStatus.EXECUTED
            || a.status == GovernanceActionStatus.EXPIRED
            || a.status == GovernanceActionStatus.VETOED
            || (a.status == GovernanceActionStatus.SCHEDULED && block.timestamp > a.expiresAfter);
    }

    /// @notice Registered guardian standing lasts while the actual action remains SCHEDULED.
    function requireScheduled(A.Witness memory w) public view {
        _pin(w.executor, w.executorCodeHash);
        IStreamGovernanceActionFacts.ActionFacts memory a = _facts(w.executor, w.actionId);
        _same(w, a);
        if (a.status != GovernanceActionStatus.SCHEDULED) {
            revert A.InvalidRecoveryAction(w.actionId);
        }
    }

    function requireExecuted(A.Witness memory w) public view {
        _pin(w.executor, w.executorCodeHash);
        IStreamGovernanceActionFacts.ActionFacts memory a = _facts(w.executor, w.actionId);
        _same(w, a);
        if (
            a.status != GovernanceActionStatus.EXECUTED || block.timestamp < a.notBefore
                || block.timestamp > a.expiresAfter
        ) {
            revert A.InvalidRecoveryAction(w.actionId);
        }
    }

    function _same(A.Witness memory w, IStreamGovernanceActionFacts.ActionFacts memory a)
        private
        pure
    {
        if (
            a.actionClass != 2 || a.callHash != w.callsHash || a.notBefore != w.notBefore
                || a.expiresAfter != w.expiresAfter
        ) {
            revert A.InvalidRecoveryAction(w.actionId);
        }
    }

    function _proposer(
        A.Environment memory e,
        A.Witness memory w,
        bytes32 reason,
        IStreamGovernanceActionFacts.ActionFacts memory facts,
        bool appeal
    ) private view {
        (bytes memory h, uint256 size) = _read(
            e.executor, abi.encodeCall(IStreamGovernanceReads.governanceAction, (w.actionId)), 640
        );
        uint256 uriLength = _word(h, 19);
        if (
            _word(h, 0) != 32 || _word(h, 17) != 576 || uriLength > size - 640 || size % 32 != 0
                || size - 640 - uriLength > 31
                || _word(h, 1) != uint256(GovernanceActionStatus.SCHEDULED) || _word(h, 2) != 2
                || _word(h, 3) > type(uint160).max || _word(h, 5) << 32 != 0
                || bytes32(_word(h, 6)) != facts.callHash || _word(h, 10) != facts.notBefore
                || _word(h, 11) != facts.expiresAfter || _word(h, 12) > type(uint160).max
                || _word(h, 13) != 0 || _word(h, 14) != 0 || _word(h, 15) != 0 || reason == 0
                || bytes32(_word(h, 16)) != reason
        ) revert A.InvalidRecoveryAction(w.actionId);
        w.proposer = address(uint160(_word(h, 12)));
        w.manifestHash = bytes32(_word(h, 18));
        if (appeal) {
            (w.roleMutationHash, w.roleRevision) =
                StreamArtistGuardianAppealAuthority.requireProposer(e.executor, e.roles, w.proposer);
            return;
        }
        uint256 roles = _word(_fixed(e.executor, abi.encodeWithSignature("roleRegistry()"), 32), 0);
        bytes32 role = keccak256("ROLE_ATTRIBUTION_ARBITER");
        if (
            roles != uint256(uint160(e.roles)) || w.proposer == address(0)
                || _word(
                        _fixed(
                            e.roles,
                            abi.encodeCall(IStreamRoleRegistry.hasRole, (role, w.proposer)),
                            32
                        ),
                        0
                    ) != 1
        ) {
            revert A.InvalidRecoveryAction(w.actionId);
        }
        bytes memory mutation =
            _fixed(e.roles, abi.encodeCall(IStreamRoleRegistry.roleMutationState, (role)), 64);
        uint256 revision = _word(mutation, 1);
        w.roleMutationHash = bytes32(_word(mutation, 0));
        if (w.roleMutationHash == 0 || revision == 0 || revision > type(uint64).max) {
            revert A.InvalidRecoveryAction(w.actionId);
        }
        w.roleRevision = uint64(revision);
    }

    function _facts(address executor, bytes32 actionId)
        private
        view
        returns (IStreamGovernanceActionFacts.ActionFacts memory a)
    {
        if (actionId == 0) revert A.InvalidRecoveryAction(actionId);
        bytes memory data = _fixed(
            executor,
            abi.encodeCall(IStreamGovernanceActionFacts.governanceActionFacts, (actionId)),
            160
        );
        if (
            _word(data, 0) > uint256(GovernanceActionStatus.VETOED) || _word(data, 1) > 255
                || _word(data, 2) == 0 || _word(data, 3) > type(uint64).max
                || _word(data, 4) > type(uint64).max
        ) {
            revert A.InvalidRecoveryAction(actionId);
        }
        a = abi.decode(data, (IStreamGovernanceActionFacts.ActionFacts));
    }

    function _pin(address target, bytes32 expected) private view {
        if (target.code.length == 0 || target.codehash != expected) {
            revert A.RecoveryActionDependencyChanged(target);
        }
    }

    function _word(bytes memory data, uint256 index) private pure returns (uint256 word) {
        assembly ("memory-safe") { word := mload(add(add(data, 32), mul(index, 32))) }
    }

    function _fixed(address target, bytes memory data, uint256 length)
        private
        view
        returns (bytes memory result)
    {
        uint256 size;
        (result, size) = _read(target, data, length);
        if (size != length) revert A.RecoveryActionDependencyChanged(target);
    }

    /// @dev Fixed authenticated governance hosts; bounded output copy also covers dynamic reason URIs.
    function _read(address target, bytes memory data, uint256 length)
        private
        view
        returns (bytes memory result, uint256 size)
    {
        result = new bytes(length);
        if (gasleft() < 20_000) revert A.RecoveryActionDependencyChanged(target);
        bool ok;
        assembly ("memory-safe") {
            ok := staticcall(
                sub(gas(), 10000),
                target,
                add(data, 32),
                mload(data),
                add(result, 32),
                length
            )
            size := returndatasize()
        }
        if (!ok || size < length) revert A.RecoveryActionDependencyChanged(target);
    }
}

