    /// @dev The fixed caller supplies its complete authenticated current-cause/staging history.
    /// The original estate request, capabilities, vesting and guardian prefix remain local.
    function firstEstateWithHistory(
        RecoveryState.State storage recovery,
        EstateState.State storage estate,
        StreamArtistRotationState.State storage rotations,
        Resolution.State storage resolutions,
        StreamArtistSuccessionState.State storage succession,
        ContestState.State storage contests,
        StreamArtistHashes.Environment memory e,
        Dismissal.Cause memory cause,
        Recovery.Request memory p,
        bytes32 historyProof
    ) public view returns (bytes32) {
        if (historyProof == 0) {
            revert Recovery.UnsupportedIdentityRecoveryProfile(p.artistId);
        }
        return _firstEstate(
            recovery,
            estate,
            rotations,
            resolutions,
            succession,
            contests,
            e,
            cause,
            p,
            historyProof
        );
    }

    function _firstEstate(
        RecoveryState.State storage recovery,
        EstateState.State storage estate,
        StreamArtistRotationState.State storage rotations,
        Resolution.State storage resolutions,
        StreamArtistSuccessionState.State storage succession,
        ContestState.State storage contests,
        StreamArtistHashes.Environment memory e,
        Dismissal.Cause memory cause,
        Recovery.Request memory p,
        bytes32 historyProof
    ) private view returns (bytes32) {
        bytes32 head = estate.authorityActivation[p.artistId];
        Facts memory f;
        f.request = estate.requests[head];
        f.execution = estate.executions[head];
        f.transition = estate.transitions[head];
        f.vesting = recovery.vestingHistory.snapshots[head];
        if (
            head == 0 || f.request.recordHash != head || f.request.terms.artistId != p.artistId
                || f.request.incumbent == address(0)
                || f.request.incumbent == f.request.terms.successor
                || f.request.terms.successor != cause.facts.incumbent
                || f.request.terms.evidenceHash == 0 || f.request.terms.selectedCoverageHash == 0
                || f.request.envelopeHash == 0 || f.request.requestedAt == 0
                || f.request.noticeRevision == 0 || f.request.rotationTimingRevision == 0
                || uint256(f.request.noticeEndsAt)
                    != uint256(f.request.requestedAt) + f.request.noticeSeconds
                || f.request.postContestSeconds < 72 hours
                || f.request.standingTailSeconds < 30 days
                || StreamArtistEstateHashes.record(
                        _recordEnvironment(e, 38, p.artistId, head),
                        f.request.terms,
                        f.request.authorization.nonce,
                        f.request.requestedAt,
                        f.request.noticeEndsAt
                    ) != head || estate.phases[head] != 2 || estate.pending[p.artistId] != 0
                || rotations.pending[p.artistId] != 0
                || rotations.latestExecution[p.artistId] != head
                || rotations.retirement[p.artistId][f.request.incumbent] != head
                || cause.facts.executedTransitionHash != head
                || (historyProof == 0 && cause.facts.pendingTransitionHash != 0)
                || f.execution.activationRecordHash != head || f.execution.coverageRecordHash == 0
                || f.execution.executedAt < f.request.requestedAt
                || f.execution.delegationEpoch == 0 || f.transition.recordHash != head
                || f.transition.artistId != p.artistId || f.transition.phase != 2
                || f.transition.stagedAt != f.request.requestedAt
                || f.transition.contestEndsAt != f.request.noticeEndsAt
                || f.transition.executedAt != f.execution.executedAt
                || uint256(f.transition.postWindowEndsAt)
                    != uint256(f.execution.executedAt) + f.request.postContestSeconds
                || block.timestamp < cause.facts.enteredAt
        ) revert Recovery.UnsupportedIdentityRecoveryProfile(p.artistId);
        if (historyProof != 0) {
            bytes32 previousRecovery = recovery.latest[p.artistId];
            if (
                f.execution.delegationEpoch != estate.delegationEpoch[p.artistId]
                    || (previousRecovery != 0
                        && (recovery.records[previousRecovery].fields.vestedAuthorityClass != 1
                            || recovery.records[previousRecovery].delegationEpoch
                                >= f.execution.delegationEpoch))
            ) revert Recovery.UnsupportedIdentityRecoveryProfile(p.artistId);
        }
        // Original operation40 already authenticated and consumed the historical accelerator.
        // Preserve its exact timing/witness shape without reauthorizing old governance or coverage.
        if (f.execution.executedAt < f.request.noticeEndsAt) {
            if (f.execution.governanceActionId == 0 || f.execution.governanceWitnessHash == 0) {
                revert Recovery.UnsupportedIdentityRecoveryProfile(p.artistId);
            }
        } else if (f.execution.governanceActionId != 0 || f.execution.governanceWitnessHash != 0) {
            revert Recovery.UnsupportedIdentityRecoveryProfile(p.artistId);
        }
        bytes32 closureProof;
        bytes32 laterProof;
        if (historyProof == 0) {
            closureProof = _closure(rotations, resolutions, contests, e, cause, f.transition);
            laterProof = _lastVeto(rotations, resolutions, contests, e, cause, f.transition);
            if (laterProof != 0 && closureProof == 0) {
                revert Recovery.UnsupportedIdentityRecoveryProfile(p.artistId);
            }
        }
        if (
            recovery.vestingHistory.latest[p.artistId] != head || f.vesting.artistId != p.artistId
                || f.vesting.transitionRecordHash != head || f.vesting.operationId != 40
                || f.vesting.authorityClass != 3 || f.vesting.oldAddress != f.request.incumbent
                || f.vesting.newAddress != cause.facts.incumbent
                || f.vesting.executedAt != f.execution.executedAt || f.vesting.ownerRevision == 0
                || (Imported.commitment() == 0
                    && f.vesting.ownerRevision <= f.vesting.guardians.ownerRevision)
                || f.vesting.commitment == 0 || f.vesting.commitment != _vestingHash(e, f.vesting)
        ) revert Recovery.UnsupportedIdentityRecoveryProfile(p.artistId);
        bytes32 ancestry;
        if (historyProof == 0) {
            ancestry = EstateHistory.previous(recovery, rotations, e, f.request, f.vesting);
        }
        bool hasAncestry =
            historyProof == 0 ? ancestry != 0 : f.vesting.previousTransitionRecordHash != 0;
        f.guardians = EstateGuardians.prefix(
            recovery.guardianHistory,
            rotations,
            e,
            p.artistId,
            recovery.guardianRecordsSeen[p.artistId],
            f.vesting
        );
        if (cause.causeHash != _causeHash(e, cause)) {
            revert Recovery.UnsupportedIdentityRecoveryProfile(p.artistId);
        }
        f.contest = contests.records[cause.facts.referenceHash];
        if (historyProof == 0) _contest(e, cause, p, f.contest, head);
        f.designation = succession.designations[f.request.designationRecordHash];
        if (
            f.request.designationRecordHash == 0
                || f.request.terms.expectedDesignationRecordHash != f.request.designationRecordHash
                || StreamArtistSuccessionState.operativeDesignation(
                        succession, rotations, p.artistId
                    ) != f.request.designationRecordHash
                || StreamArtistSuccessionState.operativeDirective(succession, rotations, p.artistId)
                    != f.request.forbiddenDirectiveRecordHash
                || f.designation.recordHash != f.request.designationRecordHash
                || f.designation.terms.artistId != p.artistId
                || f.designation.terms.successor != f.request.terms.successor
                || f.designation.terms.directiveHash != f.request.pairedDirectiveRecordHash
                || f.designation.authorityClass != 1 || f.designation.signer == address(0)
                || (!hasAncestry && f.designation.signer != f.request.incumbent)
                || f.designation.signedAt > f.request.requestedAt
                || !_planAssociation(rotations, p.artistId, f.designation.provisional, hasAncestry)
                || StreamArtistSuccessionHashes.designationRecord(
                        _recordEnvironment(e, 36, p.artistId, f.designation.recordHash),
                        f.designation.terms,
                        T.Authorization(f.designation.nonce, f.designation.signedAt, bytes(""))
                    ) != f.designation.recordHash
        ) revert Recovery.UnsupportedIdentityRecoveryProfile(p.artistId);
        f.paired = succession.directives[f.request.pairedDirectiveRecordHash];
        f.forbidden = succession.directives[f.request.forbiddenDirectiveRecordHash];
        _directive(
            rotations, e, f.request, f.paired, f.request.pairedDirectiveRecordHash, hasAncestry
        );
        _directive(
            rotations,
            e,
            f.request,
            f.forbidden,
            f.request.forbiddenDirectiveRecordHash,
            hasAncestry
        );
        f.capabilities = EstateState.activationCapabilities(
            succession, f.request.designationRecordHash, f.request.forbiddenDirectiveRecordHash
        );
        if (
            f.capabilities != f.execution.effectiveCapabilities
                || f.capabilities & ~uint32(4095) != 0
        ) {
            revert Recovery.UnsupportedIdentityRecoveryProfile(p.artistId);
        }
        bytes32 factsHash = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_RECOVERY_FIRST_ESTATE_FACTS_V1"),
                e.chainId,
                e.registry,
                address(this),
                f
            )
        );
        if (closureProof != 0) {
            factsHash = keccak256(
                abi.encode(
                    keccak256("6529STREAM_ARTIST_RECOVERY_CLOSED_FIRST_ESTATE_FACTS_V1"),
                    factsHash,
                    closureProof
                )
            );
        }
        if (ancestry != 0 || laterProof != 0) {
            factsHash = keccak256(
                abi.encode(
                    keccak256("6529STREAM_ARTIST_RECOVERY_ESTATE_CONTINUATION_FACTS_V1"),
                    factsHash,
                    ancestry,
                    laterProof
                )
            );
        }
        if (historyProof == 0) return factsHash;
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_RECOVERY_FIRST_ESTATE_WITH_HISTORY_FACTS_V1"),
                factsHash,
                cause,
                historyProof
            )
        );
    }

    // Consume authenticated immutable owner records, not a fresh historical governance decision.
    // Original immutable causes distinguish compromise from a pending-rotation standing veto.
    function _closure(
        StreamArtistRotationState.State storage rotations,
        Resolution.State storage resolutions,
        ContestState.State storage contests,
        StreamArtistHashes.Environment memory e,
        Dismissal.Cause memory current,
        R.TransitionState memory t
    ) private view returns (bytes32) {
        Dismissal.Closure memory closed = resolutions.closures[t.recordHash];
        Dismissal.Closure memory empty;
        if (keccak256(abi.encode(closed)) == keccak256(abi.encode(empty))) {
            if (
                current.facts.enteredAt < t.postWindowEndsAt
                    || (t.contestedAt != 0 && t.contestedAt < t.postWindowEndsAt)
            ) {
                revert Recovery.UnsupportedIdentityRecoveryProfile(current.facts.artistId);
            }
            return 0;
        }
        bool abandoned = t.contestedAt != 0 && t.contestedAt < t.postWindowEndsAt;
        if (
            closed.artistId != current.facts.artistId || closed.transitionRecordHash != t.recordHash
                || closed.dismissalRecordHash == 0 || closed.windowEndsAt != t.postWindowEndsAt
                || closed.contestedAt != t.contestedAt
                || (closed.contestedAt != 0 && closed.contestedAt < t.executedAt)
                || closed.abandoned != abandoned || current.facts.previousResolutionHash == 0
        ) {
            revert Recovery.UnsupportedIdentityRecoveryProfile(current.facts.artistId);
        }
        Dismissal.Record memory original = resolutions.records[closed.dismissalRecordHash];
        bytes32 originalProof = _dismissed(
            rotations,
            resolutions,
            contests,
            e,
            current.facts,
            t,
            original,
            closed.dismissalRecordHash
        );
        Dismissal.Cause memory firstCause = resolutions.causes[original.terms.expectedCauseHash];
        if (
            (firstCause.facts.kind == 1
                        ? firstCause.facts.enteredAt != closed.contestedAt
                        : closed.contestedAt != 0 || abandoned
                        || firstCause.facts.enteredAt < t.postWindowEndsAt)
                || (!abandoned && original.dismissedAt < t.postWindowEndsAt)
        ) {
            revert Recovery.UnsupportedIdentityRecoveryProfile(current.facts.artistId);
        }
        // The closure never moves. Today's latest admitted dismissal may be a later episode.
        Dismissal.Record memory latest = resolutions.records[current.facts.previousResolutionHash];
        bytes32 latestProof = _dismissed(
            rotations,
            resolutions,
            contests,
            e,
            current.facts,
            t,
            latest,
            current.facts.previousResolutionHash
        );
        if (
            latest.dismissedAt < original.dismissedAt
                || current.facts.previousCauseHash != latest.terms.expectedCauseHash
        ) {
            revert Recovery.UnsupportedIdentityRecoveryProfile(current.facts.artistId);
        }
        return keccak256(abi.encode(closed, originalProof, latestProof));
    }

    function _dismissed(
        StreamArtistRotationState.State storage rotations,
        Resolution.State storage resolutions,
        ContestState.State storage contests,
        StreamArtistHashes.Environment memory e,
        Dismissal.CauseFacts memory current,
        R.TransitionState memory t,
        Dismissal.Record memory r,
        bytes32 expected
    ) private view returns (bytes32) {
        Dismissal.Cause memory cause = resolutions.causes[r.terms.expectedCauseHash];
        if (
            expected == 0 || r.recordHash != expected || r.terms.artistId != current.artistId
                || r.terms.evidenceHash == 0 || r.terms.reasonHash == 0 || r.executor == address(0)
                || r.proposer == address(0) || (r.actionClass != 1 && r.actionClass != 2)
                || r.actionId == 0 || r.incumbent != current.incumbent || r.authorityClass != 3
                || r.restoredStatus != 3 || r.dismissedAt == 0 || r.dismissedAt > current.enteredAt
                || r.cohortHash == 0 || r.governanceWitnessHash == 0
                || r.recordHash != _dismissalHash(e, r) || cause.causeHash == 0
                || cause.causeHash != r.terms.expectedCauseHash
                || cause.causeHash != _causeHash(e, cause)
                || cause.facts.artistId != current.artistId
                || cause.facts.executedTransitionHash != t.recordHash
                || cause.facts.incumbent != current.incumbent || cause.facts.actor == address(0)
                || cause.facts.referenceHash == 0 || cause.facts.enteredAt < t.executedAt
                || cause.facts.enteredAt > r.dismissedAt
                || cause.facts.previousResolutionHash != r.terms.expectedResolutionHash
        ) {
            revert Recovery.UnsupportedIdentityRecoveryProfile(current.artistId);
        }
        if (cause.facts.kind == 2) {
            return EstateHistory.standing(rotations, resolutions, e, cause, r, t);
        }
        if (
            cause.facts.pendingTransitionHash != 0 || cause.facts.evidenceHash == 0
                || cause.facts.reasonHash == 0
        ) {
            revert Recovery.UnsupportedIdentityRecoveryProfile(current.artistId);
        }
        Recovery.Request memory historical;
        historical.artistId = current.artistId;
        historical.evidenceHash = cause.facts.evidenceHash;
        historical.reasonHash = cause.facts.reasonHash;
        Contest.Record memory contest = contests.records[cause.facts.referenceHash];
        _contest(e, cause, historical, contest, t.recordHash);
        return keccak256(abi.encode(r, cause, contest));
    }

    function _lastVeto(
        StreamArtistRotationState.State storage rotations,
        Resolution.State storage resolutions,
        ContestState.State storage contests,
        StreamArtistHashes.Environment memory e,
        Dismissal.Cause memory current,
        R.TransitionState memory t
    ) private view returns (bytes32) {
        bytes32 latest = rotations.latestTransition[current.facts.artistId];
        if (latest == t.recordHash) return 0;
        Dismissal.Closure memory closed = resolutions.closures[latest];
        Dismissal.Record memory r = resolutions.records[closed.dismissalRecordHash];
        Dismissal.Cause memory cause = resolutions.causes[r.terms.expectedCauseHash];
        if (
            latest == 0 || closed.transitionRecordHash != latest || cause.facts.kind != 2
                || cause.facts.referenceHash != latest
                || r.dismissedAt
                    > resolutions.records[current.facts.previousResolutionHash].dismissedAt
        ) {
            revert Recovery.UnsupportedIdentityRecoveryProfile(current.facts.artistId);
        }
        return _dismissed(
            rotations, resolutions, contests, e, current.facts, t, r, closed.dismissalRecordHash
        );
    }

    function _dismissalHash(StreamArtistHashes.Environment memory e, Dismissal.Record memory r)
        private
        view
        returns (bytes32)
    {
        address originalOwner = address(this);
        if (Imported.commitment() != 0) {
            Runtime.Context memory clock = Recovered.load(address(this), e.registry, e.chainId);
            Runtime.ReceiptFact memory row =
                Recovered.nativeFact(clock, 58, r.terms.artistId, r.recordHash);
            Runtime.ReplayFact memory replay = Runtime.replay(
                clock,
                RH.originHash(clock.current),
                keccak256("identity_authority.replay.contest_resolution"),
                keccak256(abi.encode(r.terms.artistId, r.terms.expectedCauseHash))
            );
            if (
                replay.cell.kind != 1 || replay.cell.status != 2
                    || replay.cell.commitment != r.recordHash
                    || !Recovered.samePoint(replay.admission.point, row.position.point)
            ) {
                revert RH.InvalidRecoveredHydrationProvenance();
            }
            e = Recovered.hashes(row.environment);
            originalOwner = row.environment.owners[2];
        }
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_IDENTITY_DISMISSAL_RECORD_V1"),
                e.chainId,
                e.registry,
                originalOwner,
                r.terms,
                r.executor,
                r.proposer,
                r.actionClass,
                r.actionId,
                r.incumbent,
                r.authorityClass,
                r.restoredStatus,
                r.dismissedAt,
                r.cohortHash,
                r.governanceWitnessHash
            )
        );
    }

    function _contest(
        StreamArtistHashes.Environment memory e,
        Dismissal.Cause memory cause,
        Recovery.Request memory p,
        Contest.Record memory c,
        bytes32 head
    ) private view {
        e = _recordEnvironment(e, 33, c.terms.artistId, c.recordHash);
        if (
            cause.facts.kind != 1 || cause.facts.authorityClass != 3 || cause.facts.priorStatus != 3
                || c.recordHash == 0 || c.recordHash != cause.facts.referenceHash
                || c.terms.artistId != p.artistId || c.terms.subjectRecordHash != head
                || c.terms.evidenceHash != p.evidenceHash || c.terms.reasonHash != p.reasonHash
                || cause.facts.evidenceHash != p.evidenceHash
                || cause.facts.reasonHash != p.reasonHash || c.contester != cause.facts.actor
                || c.contestedAt != cause.facts.enteredAt || c.priorStatus != 3
                || c.pendingTransitionRecordHash != 0 || c.executedTransitionRecordHash != head
                || c.recordHash
                    != keccak256(
                        abi.encode(
                            bytes32(
                                0x26a4221cd1625ab88b1ac279e1708a73efa176e486242b26832cdc94fe25e6bb
                            ),
                            e.chainId,
                            e.registry,
                            p.artistId,
                            c.contester,
                            head,
                            p.evidenceHash,
                            p.reasonHash,
                            c.contestedAt
                        )
                    )
        ) revert Recovery.UnsupportedIdentityRecoveryProfile(p.artistId);
    }

    function _directive(
        StreamArtistRotationState.State storage rotations,
        StreamArtistHashes.Environment memory e,
        Estate.RequestRecord memory request,
        Succ.DirectiveRecord memory d,
        bytes32 hash,
        bool hasAncestry
    ) private view {
        if (hash == 0) {
            Succ.DirectiveRecord memory empty;
            if (keccak256(abi.encode(d)) != keccak256(abi.encode(empty))) {
                revert Recovery.UnsupportedIdentityRecoveryProfile(request.terms.artistId);
            }
            return;
        }
        if (
            d.recordHash != hash || d.terms.artistId != request.terms.artistId
                || d.authorityClass != 1 || d.signer == address(0)
                || (!hasAncestry && d.signer != request.incumbent)
                || d.signedAt > request.requestedAt
                || !_planAssociation(rotations, request.terms.artistId, d.provisional, hasAncestry)
                || StreamArtistSuccessionHashes.directiveRecord(
                        _recordEnvironment(e, 37, d.terms.artistId, d.recordHash),
                        d.terms,
                        T.Authorization(d.nonce, d.signedAt, bytes(""))
                    ) != hash
        ) revert Recovery.UnsupportedIdentityRecoveryProfile(request.terms.artistId);
    }

    function _planAssociation(
        StreamArtistRotationState.State storage rotations,
        bytes32 artistId,
        R.ProvisionalAssociation memory a,
        bool hasAncestry
    ) private view returns (bool) {
        if (!hasAncestry) {
            return a.transitionRecordHash == 0 && a.windowEndsAt == 0;
        }
        return StreamArtistRotationState.eligible(rotations, artistId, a);
    }

    function _vestingHash(StreamArtistHashes.Environment memory e, V.Snapshot memory v)
        private
        view
        returns (bytes32)
    {
        if (Imported.commitment() != 0) return Order.vesting(e, v);
        return keccak256(
            bytes.concat(
                abi.encode(
                    keccak256("6529STREAM_ARTIST_GUARDIAN_VESTING_V1"),
                    e.chainId,
                    e.registry,
                    address(this)
                ),
                abi.encode(
                    v.artistId,
                    v.transitionRecordHash,
                    v.operationId,
                    v.ownerRevision,
                    v.executedAt,
                    v.oldAddress,
                    v.newAddress,
                    v.authorityClass,
                    v.guardians,
                    v.previousTransitionRecordHash,
                    v.previousCommitment
                )
            )
        );
    }

    function _recordEnvironment(
        StreamArtistHashes.Environment memory e,
        uint16 operation,
        bytes32 artistId,
        bytes32 record
    ) private view returns (StreamArtistHashes.Environment memory) {
        return Imported.commitment() == 0
            ? e
            : Order.nativeEnvironment(e, operation, artistId, record);
    }

    function _causeHash(StreamArtistHashes.Environment memory e, Dismissal.Cause memory cause)
        private
        view
        returns (bytes32)
    {
        address originalOwner = address(this);
        if (Imported.commitment() != 0) {
            Runtime.ReceiptFact memory row = Recovered.nativeFact(
                Recovered.load(address(this), e.registry, e.chainId),
                cause.facts.kind == 1 ? 33 : 31,
                cause.facts.artistId,
                cause.causeHash
            );
            e = Recovered.hashes(row.environment);
            originalOwner = row.environment.owners[2];
        }
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_IDENTITY_CONTEST_CAUSE_V1"),
                e.chainId,
                e.registry,
                originalOwner,
                cause.facts
            )
        );
    }
}

