                e.chainId,
                e.registry,
                r.terms.artistId,
                r.terms.collectionId,
                r.terms.evidenceHash,
                r.terms.reasonHash,
                r.governanceActionId,
                r.noticeEndsAt,
                r.recordedAt
            )
        );
    }
}

