pragma solidity ^0.8.19;
import { StreamArtistGuardianAppealAuthority } from "./StreamArtistGuardianAppealAuthority.sol";

import {
    StreamArtistRecoveryActionTypes as A
} from "../../interfaces/stream/artist/StreamArtistRecoveryActionTypes.sol";
import {
    StreamArtistIdentityRecoveryOperationTypes as R
} from "../../interfaces/stream/artist/StreamArtistIdentityRecoveryOperationTypes.sol";
import {
    StreamArtistOnboardingTypes as T
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";
import {
    IStreamArtistIdentityRecovery
} from "../../interfaces/stream/artist/IStreamArtistIdentityRecovery.sol";
import {
    IStreamArtistIdentityRecoveryV3
} from "../../interfaces/stream/artist/IStreamArtistIdentityRecoveryV3.sol";
import {
    IStreamGovernanceActionFacts
} from "../../interfaces/stream/governance/IStreamGovernanceActionFacts.sol";
import {
    IStreamGovernanceReads
} from "../../interfaces/stream/governance/IStreamGovernanceReads.sol";
import { IStreamRoleRegistry } from "../../interfaces/stream/governance/IStreamRoleRegistry.sol";
import {
    GovernanceCall,
    GovernanceActionStatus
} from "../../interfaces/stream/governance/StreamGovernanceTypes.sol";

/// @notice Complete scheduled-batch authentication for Identity's auxiliary preparation.
/// @dev The Coordinator supplies its fixed suite and the Identity child's original Executor pin.
library StreamArtistRecoveryRewindActionReads {
    bytes32 private constant CALLS =
        0x10f09566fb70f7947b61639c2a53b3aec872069a8b46edd08ba14eb2b5942b70;

    /// @notice Exact additive selector/calldata authentication; zero never selects V1 implicitly.
    function prepare(
        A.Environment memory e,
        bytes32 actionId,
        GovernanceCall[] memory calls,
        R.Request memory request,
        T.Authorization memory acceptance,
        R.Context memory context,
        bool appeal,
        bytes32 manifestHash
    ) public view returns (A.Witness memory w) {
        if (manifestHash == bytes32(0)) revert A.InvalidRecoveryAction(actionId);
        return _prepare(e, actionId, calls, request, acceptance, context, appeal, manifestHash);
    }

    function _prepare(
        A.Environment memory e,
        bytes32 actionId,
        GovernanceCall[] memory calls,
        R.Request memory request,
        T.Authorization memory acceptance,
        R.Context memory context,
        bool appeal,
        bytes32 manifestHash
    ) private view returns (A.Witness memory w) {
        _pin(e.executor, e.executorCodeHash);
        if (e.registry.code.length == 0 || e.roles.code.length == 0) {
            revert A.InvalidRecoveryAction(actionId);
        }
        bytes memory sealedState = _fixed(
            e.executor, abi.encodeCall(IStreamGovernanceReads.systemManifestBootstrapState, ()), 928
        );
        if (_word(sealedState, 0) != 1 || _word(sealedState, 1) != 1) {
            revert A.InvalidRecoveryAction(actionId);
        }
        IStreamGovernanceActionFacts.ActionFacts memory facts = _facts(e.executor, actionId);
        uint256 delay = _word(
            _fixed(e.executor, abi.encodeCall(IStreamGovernanceReads.minimumDelay, (uint8(2))), 32),
            0
        );
        if (
            facts.status != GovernanceActionStatus.SCHEDULED || facts.actionClass != 2
                || facts.notBefore > facts.expiresAfter || delay < 72 hours
                || delay > type(uint64).max || block.timestamp > type(uint64).max
                || block.timestamp + delay > facts.notBefore || acceptance.time < facts.notBefore
                || acceptance.signature.length > 4096 || request.supersededRecordHashes.length > 64
        ) revert A.InvalidRecoveryAction(actionId);
        w.actionId = actionId;
        w.callsHash = keccak256(abi.encode(CALLS, calls));
        if (w.callsHash != facts.callHash) revert A.InvalidRecoveryAction(actionId);
        bytes4 selector = IStreamArtistIdentityRecoveryV3.recoverArtistIdentityV3.selector;
        w.callDataHash = keccak256(
            abi.encodeCall(
                IStreamArtistIdentityRecoveryV3.recoverArtistIdentityV3,
                (request, acceptance, manifestHash)
            )
        );
        uint256 matches;
        for (uint256 i; i < calls.length; ++i) {
            GovernanceCall memory call_ = calls[i];
            if (call_.selector != selector) continue;
            if (
                call_.target != e.registry || call_.value != 0
                    || call_.callDataHash != w.callDataHash || call_.scopeHash != context.scopeHash
                    || call_.oldValueHash != context.oldValueHash
                    || call_.newValueHash != context.newValueHash
            ) revert A.InvalidRecoveryAction(actionId);
            w.callIndex = i;
            ++matches;
        }
        if (matches != 1) revert A.InvalidRecoveryAction(actionId);
        w.executor = e.executor;
        w.executorCodeHash = e.executorCodeHash;
        w.notBefore = facts.notBefore;
        w.expiresAfter = facts.expiresAfter;
        w.minimumDelay = uint64(delay);
        _proposer(e, w, request.reasonHash, facts, appeal);
    }

    /// @notice An expired SCHEDULED action cannot execute, even before its status is materialized.
    function terminal(A.Witness memory w) public view returns (bool) {
        _pin(w.executor, w.executorCodeHash);
        IStreamGovernanceActionFacts.ActionFacts memory a = _facts(w.executor, w.actionId);
        _same(w, a);
        return a.status == GovernanceActionStatus.CANCELLED
            || a.status == GovernanceActionStatus.EXECUTED
            || a.status == GovernanceActionStatus.EXPIRED
            || a.status == GovernanceActionStatus.VETOED
            || (a.status == GovernanceActionStatus.SCHEDULED && block.timestamp > a.expiresAfter);
    }

    /// @notice Registered guardian standing lasts while the actual action remains SCHEDULED.
    function requireScheduled(A.Witness memory w) public view {
        _pin(w.executor, w.executorCodeHash);
        IStreamGovernanceActionFacts.ActionFacts memory a = _facts(w.executor, w.actionId);
        _same(w, a);
        if (a.status != GovernanceActionStatus.SCHEDULED) {
            revert A.InvalidRecoveryAction(w.actionId);
        }
    }

    function requireExecuted(A.Witness memory w) public view {
        _pin(w.executor, w.executorCodeHash);
        IStreamGovernanceActionFacts.ActionFacts memory a = _facts(w.executor, w.actionId);
        _same(w, a);
        if (
            a.status != GovernanceActionStatus.EXECUTED || block.timestamp < a.notBefore
                || block.timestamp > a.expiresAfter
        ) {
            revert A.InvalidRecoveryAction(w.actionId);
        }
    }

    function _same(A.Witness memory w, IStreamGovernanceActionFacts.ActionFacts memory a)
        private
        pure
    {
        if (
            a.actionClass != 2 || a.callHash != w.callsHash || a.notBefore != w.notBefore
                || a.expiresAfter != w.expiresAfter
        ) {
            revert A.InvalidRecoveryAction(w.actionId);
        }
    }

    function _proposer(
        A.Environment memory e,
        A.Witness memory w,
        bytes32 reason,
        IStreamGovernanceActionFacts.ActionFacts memory facts,
        bool appeal
    ) private view {
        (bytes memory h, uint256 size) = _read(
            e.executor, abi.encodeCall(IStreamGovernanceReads.governanceAction, (w.actionId)), 640
        );
        uint256 uriLength = _word(h, 19);
        if (
            _word(h, 0) != 32 || _word(h, 17) != 576 || uriLength > size - 640 || size % 32 != 0
                || size - 640 - uriLength > 31
                || _word(h, 1) != uint256(GovernanceActionStatus.SCHEDULED) || _word(h, 2) != 2
                || _word(h, 3) > type(uint160).max || _word(h, 5) << 32 != 0
                || bytes32(_word(h, 6)) != facts.callHash || _word(h, 10) != facts.notBefore
                || _word(h, 11) != facts.expiresAfter || _word(h, 12) > type(uint160).max
                || _word(h, 13) != 0 || _word(h, 14) != 0 || _word(h, 15) != 0 || reason == 0
                || bytes32(_word(h, 16)) != reason
        ) revert A.InvalidRecoveryAction(w.actionId);
        w.proposer = address(uint160(_word(h, 12)));
        w.manifestHash = bytes32(_word(h, 18));
        if (appeal) {
            (w.roleMutationHash, w.roleRevision) =
                StreamArtistGuardianAppealAuthority.requireProposer(e.executor, e.roles, w.proposer);
            return;
        }
        uint256 roles = _word(_fixed(e.executor, abi.encodeWithSignature("roleRegistry()"), 32), 0);
        bytes32 role = keccak256("ROLE_ATTRIBUTION_ARBITER");
        if (
            roles != uint256(uint160(e.roles)) || w.proposer == address(0)
                || _word(
                        _fixed(
                            e.roles,
                            abi.encodeCall(IStreamRoleRegistry.hasRole, (role, w.proposer)),
                            32
                        ),
                        0
                    ) != 1
        ) {
            revert A.InvalidRecoveryAction(w.actionId);
        }
        bytes memory mutation =
            _fixed(e.roles, abi.encodeCall(IStreamRoleRegistry.roleMutationState, (role)), 64);
        uint256 revision = _word(mutation, 1);
        w.roleMutationHash = bytes32(_word(mutation, 0));
        if (w.roleMutationHash == 0 || revision == 0 || revision > type(uint64).max) {
            revert A.InvalidRecoveryAction(w.actionId);
        }
        w.roleRevision = uint64(revision);
    }

    function _facts(address executor, bytes32 actionId)
        private
        view
        returns (IStreamGovernanceActionFacts.ActionFacts memory a)
    {
        if (actionId == 0) revert A.InvalidRecoveryAction(actionId);
        bytes memory data = _fixed(
            executor,
            abi.encodeCall(IStreamGovernanceActionFacts.governanceActionFacts, (actionId)),
            160
        );
        if (
            _word(data, 0) > uint256(GovernanceActionStatus.VETOED) || _word(data, 1) > 255
                || _word(data, 2) == 0 || _word(data, 3) > type(uint64).max
                || _word(data, 4) > type(uint64).max
        ) {
            revert A.InvalidRecoveryAction(actionId);
        }
        a = abi.decode(data, (IStreamGovernanceActionFacts.ActionFacts));
    }

    function _pin(address target, bytes32 expected) private view {
        if (target.code.length == 0 || target.codehash != expected) {
            revert A.RecoveryActionDependencyChanged(target);
        }
    }

    function _word(bytes memory data, uint256 index) private pure returns (uint256 word) {
        assembly ("memory-safe") { word := mload(add(add(data, 32), mul(index, 32))) }
    }

    function _fixed(address target, bytes memory data, uint256 length)
        private
        view
        returns (bytes memory result)
    {
        uint256 size;
        (result, size) = _read(target, data, length);
        if (size != length) revert A.RecoveryActionDependencyChanged(target);
    }

    /// @dev Fixed authenticated governance hosts; bounded output copy also covers dynamic reason URIs.
    function _read(address target, bytes memory data, uint256 length)
        private
        view
        returns (bytes memory result, uint256 size)
    {
        result = new bytes(length);
        if (gasleft() < 20_000) revert A.RecoveryActionDependencyChanged(target);
        bool ok;
        assembly ("memory-safe") {
            ok := staticcall(
                sub(gas(), 10000),
                target,
                add(data, 32),
                mload(data),
                add(result, 32),
                length
            )
            size := returndatasize()
        }
        if (!ok || size < length) revert A.RecoveryActionDependencyChanged(target);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import {
    StreamArtistRecoveryRewindTypes as W
} from "../../interfaces/stream/artist/StreamArtistRecoveryRewindTypes.sol";
import {
    StreamArtistOnboardingTypes as T
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";
import {
    StreamArtistRotationTypes as R
} from "../../interfaces/stream/artist/StreamArtistRotationTypes.sol";
import {
    StreamArtistIdentityDismissalTypes as D
} from "../../interfaces/stream/artist/StreamArtistIdentityDismissalTypes.sol";
import {
    StreamArtistGuardianVestingTypes as V
} from "../../interfaces/stream/artist/StreamArtistGuardianVestingTypes.sol";
import { IStreamArtistOwner } from "../../interfaces/stream/artist/IStreamArtistOwner.sol";
import {
    IStreamArtistRecoveryDeployment
} from "../../interfaces/stream/artist/IStreamArtistRecoveryDeployment.sol";
import {
    IStreamArtistRotationReads
} from "../../interfaces/stream/artist/IStreamArtistRotation.sol";
import {
    IStreamArtistIdentityDismissalOwner
} from "../../interfaces/stream/artist/IStreamArtistIdentityDismissal.sol";
import {
    IStreamArtistGuardianVestingHistory
} from "../../interfaces/stream/artist/IStreamArtistGuardianVestingHistory.sol";
import { StreamArtistHashes as H } from "./StreamArtistHashes.sol";
import {
    StreamArtistRecoveredIdentityRuntime as Recovered
} from "./StreamArtistRecoveredIdentityRuntime.sol";
import {
    StreamArtistRecoveredRuntimeReads as Runtime
} from "./StreamArtistRecoveredRuntimeReads.sol";
import {
    StreamArtistRecoveredHydrationTypes as RH
} from "../../interfaces/stream/artist/StreamArtistRecoveredHydrationTypes.sol";

/// @notice Fixed-owner admission and original association proofs shared by the V3 record reader.
/// @dev The selector proves complete receipt prefixes and currentness; this leaf never scans history.
library StreamArtistRecoveryRewindAdmission {
    error InvalidRewindRecord(bytes32 recordHash);
    error InvalidRewindEnvironment();

    /// @notice Original key-domain admission with its actual historical mutation point.
    function consumedAt(
        W.EnvironmentV3 memory e,
        bytes32 origin,
        bytes32 surface,
        bytes32 scope,
        bytes32 expected
    ) public view returns (Runtime.ReplayFact memory f) {
        Runtime.Context memory c = Runtime.load(e, 2);
        f = Runtime.replay(c, origin, surface, scope);
        if (
            expected == 0 || f.cell.commitment != expected || f.cell.kind != 1 || f.cell.status != 2
        ) revert InvalidRewindRecord(expected);
    }

    function nonceAt(
        W.EnvironmentV3 memory e,
        bytes32 origin,
        bytes32 artistId,
        uint256 value,
        bytes32 digest
    ) public view returns (Runtime.ReplayFact memory) {
        return consumedAt(
            e,
            origin,
            keccak256("identity_authority.replay.nonce_allocator"),
            keccak256(abi.encode(artistId, value)),
            digest
        );
    }

    function vestingAt(W.EnvironmentV3 memory e, bytes32 artistId, bytes32 record)
        public
        view
        returns (V.Snapshot memory v, R.TransitionState memory t, Runtime.OriginFact memory origin)
    {
        Runtime.Context memory c = Runtime.load(e, 2);
        v = IStreamArtistGuardianVestingHistory(e.identityOwner)
            .guardianVestingSnapshot(artistId, record);
        t = IStreamArtistRotationReads(e.identityOwner).artistTransitionState(record);
        origin = Recovered.vesting(c, v);
        if (
            record == 0 || v.artistId != artistId || v.transitionRecordHash != record
                || v.executedAt > block.timestamp || t.recordHash != record
                || t.artistId != artistId || t.phase != 2 || t.executedAt != v.executedAt
                || t.postWindowEndsAt <= t.executedAt
                || (t.contestedAt != 0
                    && (t.contestedAt < t.executedAt || t.contestedAt > block.timestamp))
                || (v.previousTransitionRecordHash == 0 && v.previousCommitment != 0)
        ) revert InvalidRewindRecord(record);
    }

    function associationAt(
        W.EnvironmentV3 memory e,
        bytes32 artistId,
        R.ProvisionalAssociation memory a,
        address signer,
        uint8 authorityClass,
        RH.Point memory admission
    ) public view returns (R.TransitionState memory t, bool eligible, bytes32 proof) {
        Runtime.Context memory c = Runtime.load(e, 2);
        if (a.transitionRecordHash == 0) {
            if (a.windowEndsAt != 0) revert InvalidRewindRecord(bytes32(0));
            // Validate the supplied point even when there is no provisional association.
            Runtime.environment(c, admission.environmentHash);
            Runtime.before(c, admission, admission);
            return (t, true, keccak256(abi.encode(a)));
        }
        (
            V.Snapshot memory v,
            R.TransitionState memory transition,
            Runtime.OriginFact memory origin
        ) = vestingAt(e, artistId, a.transitionRecordHash);
        t = transition;
        if (
            a.windowEndsAt != t.postWindowEndsAt || signer != v.newAddress
                || authorityClass != v.authorityClass || !Runtime.before(c, origin.point, admission)
        ) revert InvalidRewindRecord(a.transitionRecordHash);
        D.Closure memory closed = IStreamArtistIdentityDismissalOwner(e.identityOwner)
            .identityTransitionClosure(artistId, a.transitionRecordHash);
        bytes32 closureProof;
        if (closed.dismissalRecordHash != 0) {
            (D.Record memory d, Runtime.ReplayFact memory resolved) =
                dismissalAt(e, closed.dismissalRecordHash);
            if (
                closed.artistId != artistId || closed.transitionRecordHash != t.recordHash
                    || closed.windowEndsAt != t.postWindowEndsAt
                    || closed.contestedAt != t.contestedAt
                    || closed.abandoned
                        != (t.contestedAt != 0 && t.contestedAt < t.postWindowEndsAt)
                    || d.terms.artistId != artistId
                    || !Runtime.before(c, origin.point, resolved.admission.point)
            ) revert InvalidRewindRecord(t.recordHash);
            closureProof = keccak256(abi.encode(d, resolved));
        } else {
            D.Closure memory empty;
            if (keccak256(abi.encode(closed)) != keccak256(abi.encode(empty))) {
                revert InvalidRewindRecord(t.recordHash);
            }
        }
        eligible = R.eligible(artistId, a, t, block.timestamp);
        proof = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_RECOVERED_ASSOCIATION_V1"),
                a,
                v,
                t,
                closed,
                closureProof,
                origin,
                admission
            )
        );
    }

    function dismissalAt(W.EnvironmentV3 memory e, bytes32 record)
        public
        view
        returns (D.Record memory d, Runtime.ReplayFact memory admitted)
    {
        Runtime.Context memory c = Runtime.load(e, 2);
        d = IStreamArtistIdentityDismissalOwner(e.identityOwner)
            .identityContestDismissalRecord(record);
        Runtime.ReceiptFact memory original = Recovered.nativeFact(c, 58, d.terms.artistId, record);
        RH.OriginEnvironment memory origin = original.environment;
        if (
            record == 0 || d.recordHash != record || d.terms.artistId == 0
                || d.terms.expectedCauseHash == 0 || d.executor == address(0)
                || d.proposer == address(0) || d.incumbent == address(0) || d.actionClass != 1
                || d.actionId == 0 || d.dismissedAt == 0 || d.dismissedAt > block.timestamp
                || d.governanceWitnessHash == 0 || d.cohortHash == 0 || d.terms.evidenceHash == 0
                || d.terms.reasonHash == 0 || (d.authorityClass != 1 && d.authorityClass != 3)
                || (d.restoredStatus != d.authorityClass
                    && !(d.authorityClass == 1 && d.restoredStatus == 2))
                || record
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_ARTIST_IDENTITY_DISMISSAL_RECORD_V1"),
                            origin.chainId,
                            origin.registry,
                            origin.owners[2],
                            d.terms,
                            d.executor,
                            d.proposer,
                            d.actionClass,
                            d.actionId,
                            d.incumbent,
                            d.authorityClass,
                            d.restoredStatus,
                            d.dismissedAt,
                            d.cohortHash,
                            d.governanceWitnessHash
                        )
                    )
        ) revert InvalidRewindRecord(record);
        admitted = consumedAt(
            e,
            original.position.point.environmentHash,
            keccak256("identity_authority.replay.contest_resolution"),
            keccak256(abi.encode(d.terms.artistId, d.terms.expectedCauseHash)),
            record
        );
        if (!Recovered.samePoint(original.position.point, admitted.admission.point)) {
            revert InvalidRewindRecord(record);
        }
    }

    function environment(W.EnvironmentV3 memory e) public view {
        if (
            e.chainId != block.chainid || e.registry == address(0) || e.identityOwner == address(0)
                || e.payoutOwner == address(0) || e.identityOwner == e.payoutOwner
                || e.coordinator == address(0) || e.archive == address(0) || e.core == address(0)
                || e.manager == address(0) || e.identityCodeHash == 0 || e.payoutCodeHash == 0
                || e.identityOwner.code.length == 0 || e.payoutOwner.code.length == 0
                || e.identityOwner.codehash != e.identityCodeHash
                || e.payoutOwner.codehash != e.payoutCodeHash
        ) revert InvalidRewindEnvironment();
        T.SuiteConfiguration memory suite =
            IStreamArtistRecoveryDeployment(e.coordinator).suiteConfiguration();
        if (
            suite.owners[2] != e.identityOwner || suite.owners[5] != e.payoutOwner
                || suite.registry != e.registry || suite.archive != e.archive
                || suite.core != e.core || suite.mintManager != e.manager
                || IStreamArtistRecoveryDeployment(e.coordinator).deploymentChainId() != e.chainId
        ) revert InvalidRewindEnvironment();
        _owner(e, e.identityOwner, keccak256("domain:identity_authority"));
        _owner(e, e.payoutOwner, keccak256("domain:payout_lifecycle"));
    }

    function hashes(W.EnvironmentV3 memory e) internal pure returns (H.Environment memory) {
        return H.Environment(e.chainId, e.registry, e.core, e.manager);
    }

    function key(W.EnvironmentV3 memory e, bytes32 surface, bytes32 scope)
        internal
        pure
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_OWNER_REPLAY_KEY_V2"),
                e.chainId,
                e.registry,
                e.coordinator,
                e.archive,
                e.identityOwner,
                keccak256("domain:identity_authority"),
                surface,
                scope
            )
        );
    }

    function consumed(W.EnvironmentV3 memory e, bytes32 surface, bytes32 scope, bytes32 expected)
        public
        view
        returns (T.ReplayCell memory cell)
    {
        cell = IStreamArtistOwner(e.identityOwner).replayCell(key(e, surface, scope));
        if (
            expected == 0 || cell.commitment != expected || cell.status != 2 || cell.kind != 1
                || cell.touchedRevision == 0
                || cell.touchedRevision
                    > IStreamArtistOwner(e.identityOwner).ownerStateSnapshotV2().revision
        ) revert InvalidRewindRecord(expected);
    }

    function nonce(W.EnvironmentV3 memory e, bytes32 artistId, uint256 value, bytes32 digest)
        public
        view
        returns (T.ReplayCell memory)
    {
        return consumed(
            e,
            keccak256("identity_authority.replay.nonce_allocator"),
            keccak256(abi.encode(artistId, value)),
            digest
        );
    }

    function vesting(W.EnvironmentV3 memory e, bytes32 artistId, bytes32 record)
        public
        view
        returns (V.Snapshot memory v, R.TransitionState memory t)
    {
        v = IStreamArtistGuardianVestingHistory(e.identityOwner)
            .guardianVestingSnapshot(artistId, record);
        t = IStreamArtistRotationReads(e.identityOwner).artistTransitionState(record);
        if (
            record == 0 || v.artistId != artistId || v.transitionRecordHash != record
                || v.ownerRevision == 0 || v.ownerRevision <= v.guardians.ownerRevision
                || v.ownerRevision
                    > IStreamArtistOwner(e.identityOwner).ownerStateSnapshotV2().revision
                || v.executedAt == 0 || v.executedAt > block.timestamp || v.oldAddress == address(0)
                || v.newAddress == address(0) || v.oldAddress == v.newAddress
                || (v.authorityClass != 1 && v.authorityClass != 3)
                || (v.operationId != 32
                    && v.operationId != 35
                    && v.operationId != 40
                    && v.operationId != 43) || (v.operationId == 40 && v.authorityClass != 3)
                || v.commitment == 0 || v.commitment != _vestingHash(e, v) || t.recordHash != record
                || t.artistId != artistId || t.phase != 2 || t.executedAt != v.executedAt
                || t.postWindowEndsAt <= t.executedAt
                || (t.contestedAt != 0
                    && (t.contestedAt < t.executedAt || t.contestedAt > block.timestamp))
        ) revert InvalidRewindRecord(record);
        if (v.previousTransitionRecordHash == 0 && v.previousCommitment != 0) {
            revert InvalidRewindRecord(record);
        }
    }

    function association(
        W.EnvironmentV3 memory e,
        bytes32 artistId,
        R.ProvisionalAssociation memory a,
        address signer,
        uint8 authorityClass,
        uint64 admissionRevision
    ) public view returns (R.TransitionState memory t, bool eligible, bytes32 proof) {
        if (a.transitionRecordHash == 0) {
            if (a.windowEndsAt != 0) revert InvalidRewindRecord(bytes32(0));
            return (t, true, keccak256(abi.encode(a)));
        }
        V.Snapshot memory v;
        (v, t) = vesting(e, artistId, a.transitionRecordHash);
        if (
            a.windowEndsAt != t.postWindowEndsAt || signer != v.newAddress
                || authorityClass != v.authorityClass || admissionRevision <= v.ownerRevision
        ) revert InvalidRewindRecord(a.transitionRecordHash);
        D.Closure memory c = IStreamArtistIdentityDismissalOwner(e.identityOwner)
            .identityTransitionClosure(artistId, a.transitionRecordHash);
        bytes32 closureProof;
        if (c.dismissalRecordHash != 0) {
            (D.Record memory d, T.ReplayCell memory cell) = dismissal(e, c.dismissalRecordHash);
            if (
                c.artistId != artistId || c.transitionRecordHash != t.recordHash
                    || c.windowEndsAt != t.postWindowEndsAt || c.contestedAt != t.contestedAt
                    || c.abandoned != (t.contestedAt != 0 && t.contestedAt < t.postWindowEndsAt)
                    || d.terms.artistId != artistId || cell.touchedRevision <= v.ownerRevision
            ) revert InvalidRewindRecord(t.recordHash);
            closureProof = keccak256(abi.encode(d, cell));
        } else {
            D.Closure memory empty;
            if (keccak256(abi.encode(c)) != keccak256(abi.encode(empty))) {
                revert InvalidRewindRecord(t.recordHash);
            }
        }
        eligible = R.eligible(artistId, a, t, block.timestamp);
        proof = keccak256(abi.encode(a, v, t, c, closureProof));
    }

    function dismissal(W.EnvironmentV3 memory e, bytes32 record)
        public
        view
        returns (D.Record memory d, T.ReplayCell memory cell)
    {
        d = IStreamArtistIdentityDismissalOwner(e.identityOwner)
            .identityContestDismissalRecord(record);
        if (
            record == 0 || d.recordHash != record || d.terms.artistId == 0
                || d.terms.expectedCauseHash == 0 || d.executor == address(0)
                || d.proposer == address(0) || d.incumbent == address(0) || d.actionClass != 1
                || d.actionId == 0 || d.dismissedAt == 0 || d.dismissedAt > block.timestamp
                || d.governanceWitnessHash == 0 || d.cohortHash == 0 || d.terms.evidenceHash == 0
                || d.terms.reasonHash == 0 || (d.authorityClass != 1 && d.authorityClass != 3)
                || (d.restoredStatus != d.authorityClass
                    && !(d.authorityClass == 1 && d.restoredStatus == 2))
                || record
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_ARTIST_IDENTITY_DISMISSAL_RECORD_V1"),
                            e.chainId,
                            e.registry,
                            e.identityOwner,
                            d.terms,
                            d.executor,
                            d.proposer,
                            d.actionClass,
                            d.actionId,
                            d.incumbent,
                            d.authorityClass,
                            d.restoredStatus,
                            d.dismissedAt,
                            d.cohortHash,
                            d.governanceWitnessHash
                        )
                    )
        ) revert InvalidRewindRecord(record);
        cell = consumed(
            e,
            keccak256("identity_authority.replay.contest_resolution"),
            keccak256(abi.encode(d.terms.artistId, d.terms.expectedCauseHash)),
            record
        );
    }

    function _owner(W.EnvironmentV3 memory e, address target, bytes32 domain) private view {
        IStreamArtistOwner o = IStreamArtistOwner(target);
        if (
            o.deploymentChainId() != e.chainId || o.artistRegistry() != e.registry
                || o.operationCoordinator() != e.coordinator || o.archiveV2() != e.archive
                || o.core() != e.core || o.mintManager() != e.manager || o.domainId() != domain
                || o.ownerStateSnapshotV2().domainId != domain
        ) revert InvalidRewindEnvironment();
    }

    function _vestingHash(W.EnvironmentV3 memory e, V.Snapshot memory v)
        private
        pure
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_GUARDIAN_VESTING_V1"),
                e.chainId,
                e.registry,
                e.identityOwner,
                v.artistId,
                v.transitionRecordHash,
                v.operationId,
                v.ownerRevision,
                v.executedAt,
                v.oldAddress,
                v.newAddress,
                v.authorityClass,
                v.guardians,
                v.previousTransitionRecordHash,
                v.previousCommitment
            )
        );
    }
}

