    ) public view returns (bytes32 proof) {
        Runtime.Context memory clock = Runtime.load(e, 2);
        IStreamArtistIdentityRecoveryOwnerV3 owner =
            IStreamArtistIdentityRecoveryOwnerV3(e.identityOwner);
