                    || abandoned.artistId != r.artistId
                    || abandoned.previousRevisionRecord != c.stableRevisionRecordHash
                    || abandoned.previousRecordHash != c.stableDocumentHash
                    || association.transitionRecordHash == 0 || !closed.abandoned
