    {
        return StreamArtistContentHashes.consentDigest(_environment(), p, a);
    }

    function contentFreezeDigest(Content.Freeze calldata p, T.Authorization calldata a)
        external
        view
        onlyHost
        returns (bytes32)
    {
        return StreamArtistContentHashes.freezeDigest(_environment(), p, a);
    }

    function identityRecoveryContextV3(
        IdentityRecovery.Request calldata p,
        T.Authorization calldata a,
        bytes32 manifestHash
    ) external view onlyHost returns (IdentityRecovery.Context memory) {
        return StreamArtistRecoveryRewindOperations.context(_contentSuite(), p, a, manifestHash);
    }

    function identityRecoveryEvidenceStateV3(bytes32 artistId, bytes32 actionId)
        external
        view
        onlyHost
        returns (RewindTypes.EvidenceStateV3 memory)
    {
        return IStreamArtistIdentityRecoveryOwnerV3(_contentSuite().owners[2])
            .identityRecoveryEvidenceStateV3(artistId, actionId);
    }

    function identityRecoveryContextV2(
        IdentityRecovery.Request calldata p,
        T.Authorization calldata a,
        bytes32 manifestHash
    ) external view onlyHost returns (IdentityRecovery.Context memory) {
        return IStreamArtistIdentityRecoveryOwnerV2(_contentSuite().owners[2])
            .identityRecoveryContextV2(p, a, manifestHash);
    }

    function identityRecoveryEvidenceState(bytes32 artistId, bytes32 actionId)
        external
        view
        onlyHost
        returns (RecoveryEvidence.EvidenceStateV2 memory)
    {
        return IStreamArtistIdentityRecoveryOwnerV2(_contentSuite().owners[2])
            .identityRecoveryEvidenceState(artistId, actionId);
    }

    function identityRecoveryContext(
        IdentityRecovery.Request calldata p,
        T.Authorization calldata a
    ) external view onlyHost returns (IdentityRecovery.Context memory) {
        return
            IStreamArtistIdentityRecoveryOwner(_contentSuite().owners[2])
                .identityRecoveryContext(p, a);
    }

    function identityRecoveryRecord(bytes32 record)
        external
        view
        onlyHost
        returns (IdentityRecovery.Record memory)
    {
        return IStreamArtistIdentityRecoveryOwner(_contentSuite().owners[2])
            .identityRecoveryRecord(record);
    }

    function latestIdentityRecovery(bytes32 artistId) external view onlyHost returns (bytes32) {
        return IStreamArtistIdentityRecoveryOwner(_contentSuite().owners[2])
            .latestIdentityRecovery(artistId);
    }

    function collaboratorIdentityDigest(
        address account,
        bytes32 identityRecordHash,
        T.Authorization calldata a
    ) external view onlyHost returns (bytes32) {
        return StreamArtistCollaboratorHashes.identityDigest(
            _environment(), account, identityRecordHash, a
        );
    }

    function collaboratorAcceptanceDigest(
        C.BindingAcceptance calldata p,
        T.Authorization calldata a
    ) external view onlyHost returns (bytes32) {
        return StreamArtistCollaboratorHashes.acceptanceDigest(_environment(), p, a);
    }

    function guardianSet(bytes32 artistId)
        external
        view
        onlyHost
