pragma solidity ^0.8.19;
import "../../interfaces/stream/artist/IStreamArtistDelegatedConsentOwner.sol";
import "./StreamArtistAttributionPolicy.sol";

import "./StreamArtistContentOperations.sol";
import "./StreamArtistSaleHashes.sol";
import "../../interfaces/stream/artist/IStreamArtistSaleOwner.sol";
import "../../interfaces/stream/artist/IStreamArtistSaleFacts.sol";
import "../../interfaces/stream/modules/IStreamModule.sol";
import "../../interfaces/stream/modules/IStreamModuleRegistry.sol";
import "../../vendor/openzeppelin/IERC165.sol";

/// @notice Typed sale consent over registered immutable adapter facts and actual artist owners.
/// @dev Caller-sensitive validation receives the original adapter from the facade explicitly.
library StreamArtistSaleOperations {
    bytes32 private constant _READ_GAS = keccak256("6529STREAM_GGP_ARTIST_SALE_FACTS_READ_GAS");

    function record(
        StreamArtistDelegationTypes.CoordinatorContext memory x,
        address actor,
        Sale.Consent memory p,
        T.Authorization memory a
    ) public returns (bytes32 result) {
        T.Snapshot[7] memory prior = _snapshots(x.suite);
        T.Binding memory b = _binding(x.suite, p.collectionId, true);
        R.AuthorityFact memory authority =
            StreamArtistCurrentAuthorityFacts.read(x.suite.owners[2], b.artistId, false);
        bytes memory facts = _adapter(x.suite, p, 0);
        bytes32 digest = StreamArtistSaleHashes.digest(_environment(x.suite), p, a);
        bool direct = actor == authority.authorityAddress && a.signature.length == 0;
        if (actor == address(0)) revert T.InvalidSignature();
        if (!direct) {
            (uint256 cap,, uint8 failure, uint64 revision) = IStreamGasParameterHost(
                    x.suite.registry
                ).gasParameterInfo(keccak256("6529STREAM_GGP_ARTIST_ERC1271_VERIFY_GAS"));
            if (
                revision == 0 || failure != 2
                    || !StreamArtistRegistryValidatorBase(x.suite.validator)
                        .validateSignerProof(authority.authorityAddress, digest, a.signature, cap)
            ) {
                revert T.InvalidSignature();
            }
        }
        T.SignerApproval memory proof = T.SignerApproval(authority.authorityAddress, digest, direct);
        result = IStreamArtistSaleIdentityOwner(x.suite.owners[2])
            .consumeSaleConsent(T.ActionContext(16, actor, prior[2]), b, p, a, proof);
        bytes32 actual = IStreamArtistSaleConsentOwner(x.suite.owners[6])
            .recordSaleConsent(
                T.ActionContext(16, actor, prior[6]), b, p, proof.signer, a.nonce, authority
            );
        if (actual != result) revert T.InvalidRecord();
        bytes32 id = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_ONBOARDING_OPERATION_EVIDENCE_V1"),
                block.chainid,
                x.suite.registry,
                address(this),
                uint16(16),
                actor,
                result
            )
        );
        bytes memory evidence = abi.encode(
            uint16(1),
            x.configurationHash,
            uint16(16),
            actor,
            result,
            prior,
            _snapshots(x.suite),
            abi.encode(b, p, a, proof, authority, facts)
        );
        (bytes32 hash,, bool appended) =
            IStreamArtistArchiveV2(x.suite.archive).appendArtistEvidenceV2(id, 1, evidence);
        if (!appended || hash != keccak256(evidence)) revert T.InvalidRecord();
    }

    function delegatedBinding(T.SuiteConfiguration memory suite, uint256 collectionId)
        public
        view
        returns (T.Binding memory b)
    {
        b = _binding(suite, collectionId, true);
        if (b.consentMode != 2) revert T.UnsupportedProfile();
    }

    function saleFacts(T.SuiteConfiguration memory suite, Sale.Consent memory p)
        public
        view
        returns (bytes memory)
    {
        return _adapter(suite, p, 0);
    }

    function scope(T.SuiteConfiguration memory suite, uint256 collectionId)
        public
        view
        returns (uint8)
    {
        return _binding(suite, collectionId, false).saleConsentScope;
    }

    /// @notice Historical/latest evidence only; current applicability is checked by requireConsent.
    function isConsented(
        T.SuiteConfiguration memory suite,
        uint256 collectionId,
        bytes32 saleId,
        bytes32 config
    ) public view returns (bool, bytes32) {
        bytes32 hash = IStreamArtistSaleConsentOwner(suite.owners[6])
            .saleConsentAt(collectionId, saleId, config);
        return (hash != bytes32(0), hash);
    }

    function requireConsent(
        T.SuiteConfiguration memory suite,
        address adapter,
        uint256 collectionId,
        bytes32 saleId,
        bytes32 config
    ) public view {
        T.Binding memory b = _binding(suite, collectionId, false);
        if (b.saleConsentScope == 0) return;
        b = _binding(suite, collectionId, true);
        Sale.Consent memory p = Sale.Consent(collectionId, adapter, saleId, config);
        IStreamArtistSaleConsentOwner owner = IStreamArtistSaleConsentOwner(suite.owners[6]);
        Sale.Record memory item =
            owner.saleConsentRecord(owner.saleConsentAt(collectionId, saleId, config));
        if (
            item.recordHash == bytes32(0) || item.artistId != b.artistId || item.signedAt == 0
                || item.signedAt > block.timestamp
                || (item.authorityClass != 1
                    && item.authorityClass != 3
                    && !(item.authorityClass == 2
                        && b.consentMode == 2
                        && IStreamArtistDelegatedConsentOwner(suite.owners[6])
                                .recordDelegation(item.recordHash) != 0))
                || item.bindingGeneration != b.generation || item.bindingHash != b.bindingHash
                || keccak256(abi.encode(item.terms)) != keccak256(abi.encode(p))
        ) {
            revert Sale.SaleConsentUnavailable(collectionId, saleId, config);
        }
        // The stored timestamp is the consent writer's observed block time, not a supplied
        // signing time. New consent still uses ACTIVE-only admission through the zero mode.
        _adapter(suite, p, item.signedAt);
    }

    /// @notice Exact independent attribution and authority states, never inferred from missing acceptance.
    function attributionStateEncoded(T.SuiteConfiguration memory suite, uint256 collectionId)
        public
        view
        returns (bytes memory)
    {
        (uint8 state, uint64 generation, bytes32 artistId, uint8 status, bytes32 hash) =
            attributionState(suite, collectionId);
        return abi.encode(state, generation, artistId, status, hash);
    }

    function attributionState(T.SuiteConfiguration memory suite, uint256 collectionId)
        public
        view
        returns (
            uint8 state,
            uint64 generation,
            bytes32 artistId,
            uint8 authorityStatus,
            bytes32 bindingHash
        )
    {
        _selected(suite.core, keccak256("ARTIST_REGISTRY"), suite.registry, _cap(suite));
        _chain(suite);
        T.Binding memory b = IStreamArtistBindingOwner(suite.owners[0]).binding(collectionId);
        (state, generation) =
            IStreamArtistAttributionOwner(suite.owners[4]).attributionState(collectionId);
        if (generation != b.generation) revert T.InvalidAttribution(collectionId);
        artistId = b.artistId;
        bindingHash = b.bindingHash;
        if (artistId != bytes32(0)) {
            (,, authorityStatus,) =
                IStreamArtistIdentityOwner(suite.owners[2]).authorityState(artistId);
        }
    }

    function _binding(T.SuiteConfiguration memory suite, uint256 collectionId, bool accepted)
        private
        view
        returns (T.Binding memory b)
    {
        _chain(suite);
        _selected(suite.core, keccak256("ARTIST_REGISTRY"), suite.registry, _cap(suite));
        b = IStreamArtistBindingOwner(suite.owners[0]).binding(collectionId);
        if (collectionId == 0 || b.bindingHash == bytes32(0) || b.saleConsentScope > 1) {
            revert T.InvalidAttribution(collectionId);
        }
        if (!accepted) return b;
        (uint8 state, uint64 generation) =
            IStreamArtistAttributionOwner(suite.owners[4]).attributionState(collectionId);
        (address authority, uint8 class_, uint8 status,) =
            IStreamArtistIdentityOwner(suite.owners[2]).authorityState(b.artistId);
        if (
            !b.accepted || !StreamArtistAttributionPolicy.acceptedOrSanctioned(state)
                || generation != b.generation
                || !StreamArtistAuthorityPolicy.ordinary(class_, status, false)
                || authority == address(0) || (b.consentMode != 1 && b.consentMode != 2)
        ) revert T.InvalidAttribution(collectionId);
        C.BindingTerms memory terms = IStreamArtistCollaboratorBindingOwner(suite.owners[0])
            .bindingTerms(collectionId, generation);
        if (terms.mode != 0 || terms.threshold != 0 || terms.count > 32) {
            revert T.UnsupportedProfile();
        }
        if (
            IStreamArtistCollaboratorRecordsOwner(suite.owners[1]).acceptedCount(b.bindingHash)
                != terms.count
        ) {
            revert T.InvalidAttribution(collectionId);
        }
    }

    function _adapter(T.SuiteConfiguration memory suite, Sale.Consent memory p, uint64 consentAt)
        private
        view
        returns (bytes memory evidence)
    {
        address adapter = p.saleAdapter;
        if (adapter.code.length == 0 || p.saleId == bytes32(0) || p.saleConfigHash == bytes32(0)) {
            revert Sale.InvalidSaleAdapter(adapter);
        }
        uint256 cap = _cap(suite);
        address registry = _selected(suite.core, keccak256("MODULE_REGISTRY"), address(0), cap);
        bytes32 kind = abi.decode(
            _read(
                adapter, abi.encodeWithSelector(IStreamModule.streamModuleType.selector), 32, cap
            ),
            (bytes32)
        );
        bytes4 interfaceId = abi.decode(
            _read(
                adapter,
                abi.encodeWithSelector(IStreamModule.streamModuleInterfaceId.selector),
                32,
                cap
            ),
            (bytes4)
        );
        if (
            kind == bytes32(0) || interfaceId == bytes4(0) || interfaceId == bytes4(0xffffffff)
                || !(consentAt == 0
                        ? abi.decode(
                            _read(
                                registry,
                                abi.encodeCall(
                                    IStreamModuleRegistry.isModuleEligible,
                                    (adapter, kind, interfaceId)
                                ),
                                32,
                                cap
                            ),
                            (bool)
                        )
                        : _retainedAdapter(registry, adapter, kind, interfaceId, consentAt, cap))
                || !abi.decode(
                    _read(
                        adapter,
                        abi.encodeCall(
                            IERC165.supportsInterface, (type(IStreamArtistSaleFacts).interfaceId)
                        ),
                        32,
                        cap
                    ),
                    (bool)
                )
                || abi.decode(_read(adapter, abi.encodeWithSignature("core()"), 32, cap), (address))
                    != suite.core
        ) {
            revert Sale.InvalidSaleAdapter(adapter);
        }
        (uint256 collectionId, bytes32 config) = abi.decode(
            _read(
                adapter,
                abi.encodeCall(IStreamArtistSaleFacts.saleConsentFacts, (p.saleId)),
                64,
                cap
            ),
            (uint256, bytes32)
        );
        if (collectionId != p.collectionId || config != p.saleConfigHash) {
            revert Sale.InvalidSaleAdapter(adapter);
        }
        return abi.encode(
            registry, registry.codehash, adapter.codehash, kind, interfaceId, collectionId, config
        );
    }

    /// @dev Consent is only one retained prerequisite. The sale and payment boundaries still
    /// validate their original immutable creation timestamps and registry revisions separately.
    function _retainedAdapter(
        address registry,
        address adapter,
        bytes32 kind,
        bytes4 interfaceId,
        uint64 consentAt,
        uint256 cap
    ) private view returns (bool) {
        if (adapter.code.length == 23) {
            bytes3 prefix;
            assembly ("memory-safe") {
                extcodecopy(adapter, 0, 0, 3)
                prefix := mload(0)
            }
            if (prefix == 0xef0100) return false;
        }
        bytes memory input = abi.encodeCall(IStreamModuleRegistry.moduleRecord, (adapter));
        uint256[14] memory w;
        bool ok;
        uint256 size;
        _parentGas(cap);
        assembly ("memory-safe") {
            ok := staticcall(cap, registry, add(input, 32), mload(input), w, 448)
            size := returndatasize()
        }
        // Canonical single dynamic tuple: twelve-word head and a URI of at most 2048 bytes.
        // Copy only the fixed header; never allocate or bubble the registry's URI/revert tail.
        if (
            !ok || size < 448 || w[0] != 32 || w[9] != 384 || w[13] > 2048
                || size - 448 != ((w[13] + 31) / 32) * 32 || (w[1] != 1 && w[1] != 2)
                || bytes32(w[2]) != kind || w[3] == 0 || w[4] != uint256(uint32(interfaceId)) << 224
                || w[5] > type(uint32).max || bytes32(w[6]) != adapter.codehash || w[7] == 0
                || w[8] == 0 || w[10] == 0 || w[10] > type(uint64).max || w[10] > consentAt
                || w[11] < w[10] || w[11] > block.timestamp || w[11] > type(uint64).max
                || w[12] == 0 || w[12] > type(uint64).max
                || (w[1] == 2 && (consentAt >= w[11] || w[12] < 2))
        ) return false;
        return bytes32(w[3])
                == abi.decode(
                _read(adapter, abi.encodeCall(IStreamModule.streamModuleVersion, ()), 32, cap),
                (bytes32)
            ) && _retainedInterface(adapter, type(IERC165).interfaceId, cap) == 1
            && _retainedInterface(adapter, bytes4(0xffffffff), cap) == 0
            && _retainedInterface(adapter, interfaceId, cap) == 1;
    }

    function _retainedInterface(address adapter, bytes4 interfaceId, uint256 cap)
        private
        view
        returns (uint256)
    {
        return abi.decode(
            _read(adapter, abi.encodeCall(IERC165.supportsInterface, (interfaceId)), 32, cap),
            (uint256)
        );
    }

    function _cap(T.SuiteConfiguration memory suite) private view returns (uint256 cap) {
        uint8 failure;
        uint64 revision;
        (cap,, failure, revision) =
            IStreamGasParameterHost(suite.registry).gasParameterInfo(_READ_GAS);
        if (cap == 0 || failure != 2 || revision == 0) revert T.InvalidBinding();
    }

    function _selected(address core, bytes32 kind, address expected, uint256 cap)
        private
        view
        returns (address target)
    {
        bytes memory data = _read(
            core, abi.encodeCall(IStreamCorePointers.getSatellitePointer, (kind)), 320, cap
        );
        bytes32 word;
        bytes32 hash;
        assembly ("memory-safe") {
            word := mload(add(data, 32))
            hash := mload(add(data, 64))
        }
        target = address(uint160(uint256(word)));
        if (
            uint256(word) >> 160 != 0 || target.code.length == 0 || hash != target.codehash
                || (expected != address(0) && expected != target)
        ) revert T.ComponentChanged(target);
    }

    /// @dev Allocate only the expected fixed result; neither return nor revert data is copied unboundedly.
    function _read(address target, bytes memory callData, uint256 length, uint256 cap)
        private
        view
        returns (bytes memory result)
    {
        _parentGas(cap);
        result = new bytes(length);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(
                cap,
                target,
                add(callData, 32),
                mload(callData),
                add(result, 32),
                length
            )
            size := returndatasize()
        }
        if (!ok || size != length) revert Sale.SaleFactsReadFailed(target, bytes4(callData));
    }

    function _parentGas(uint256 cap) private view {
        uint256 available = gasleft();
        // Includes a cold account access, fixed buffer and instructions before STATICCALL.
        if (cap > (type(uint256).max - 10_000) / 64 * 63) {
            revert Sale.SaleFactsParentGas(available, cap);
        }
        uint256 required = cap + cap / 63 + 10_000;
        if (available < required) revert Sale.SaleFactsParentGas(available, required);
    }

    function _chain(T.SuiteConfiguration memory suite) private view {
        if (block.chainid != IStreamArtistOwner(suite.owners[2]).deploymentChainId()) {
            revert T.InvalidBinding();
        }
    }

    function _environment(T.SuiteConfiguration memory suite)
        private
        view
        returns (StreamArtistHashes.Environment memory)
    {
        return StreamArtistHashes.Environment(
            block.chainid, suite.registry, suite.core, suite.mintManager
        );
    }

    function _snapshots(T.SuiteConfiguration memory suite)
        private
        view
        returns (T.Snapshot[7] memory result)
    {
        for (uint256 i; i < 7; ++i) {
            if ((0x57 & (1 << i)) != 0) {
                result[i] = IStreamArtistOwner(suite.owners[i]).ownerStateSnapshotV2();
            }
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamArtistSanctionHashes.sol";
import "./StreamArtistSanctionCeremony.sol";
import "../finality/StreamFinalitySanctionReviewReads.sol";
import "../../interfaces/stream/finality/IStreamArtistSanctionReviewPreparation.sol";
import {
    StreamArtistSanctionRequestTypes as Q
} from "../../interfaces/stream/artist/StreamArtistSanctionRequestTypes.sol";
import "../../interfaces/stream/finality/IStreamArtistSanctionPreparation.sol";
import "../../interfaces/stream/finality/IStreamFinalitySanctionReview.sol";
import "../../interfaces/stream/finality/IStreamFinalityDeploymentBindings.sol";
import "../../interfaces/stream/finality/IStreamFinalityScopeEvidence.sol";
import "../../interfaces/stream/finality/IStreamFinalityEvidenceProvider.sol";
import "../../interfaces/stream/core/IStreamCorePointers.sol";

/// @notice Actual candidate joins before signing or nonce consumption; no caller-supplied review inventory.
library StreamArtistSanctionCandidate {
    struct Pins {
        address finalityRegistry;
        bytes32 finalityCodeHash;
        address provider;
        bytes32 providerCodeHash;
        uint256 readGas;
    }

    error SanctionReadFailed(address target);
    error SanctionParentGas(uint256 available, uint256 required);

    function prepare(StreamArtistHashes.Environment memory e, Pins memory pins, Q.Request memory q)
        public
        view
        returns (Q.Prepared memory result)
    {
        if (
            pins.finalityRegistry.code.length == 0
                || pins.finalityRegistry.codehash != pins.finalityCodeHash
                || pins.provider.code.length == 0 || pins.provider.codehash != pins.providerCodeHash
        ) revert T.InvalidBinding();
        _selected(e.core, keccak256("ARTIST_REGISTRY"), e.registry, pins.readGas);
        _selected(
            e.core, keccak256("ARTWORK_FINALITY_REGISTRY"), pins.finalityRegistry, pins.readGas
        );
        if (q.terms.scopeType > 4) revert S.InvalidSanction();
        StreamFinalityScope memory scope = StreamFinalityScope(
            StreamFinalityScopeType(q.terms.scopeType),
            q.terms.collectionId,
            q.terms.tokenId,
            q.terms.scopeId
        );
        StreamArtistSanctionPreparation memory actual;
        bytes memory raw;
        if (StreamFinalityBoundedReads.supportsOptional(
                pins.finalityRegistry,
                type(IStreamArtistSanctionReviewPreparation).interfaceId,
                pins.readGas
            )) {
            bytes memory combined = StreamFinalitySanctionReviewReads.read(
                pins.finalityRegistry,
                abi.encodeCall(
                    IStreamArtistSanctionReviewPreparation.prepareSanctionWithReview,
                    (scope, q.nonSanctionComponents, q.manifest)
                ),
                896,
                pins.readGas
            );
            IStreamFinalitySanctionReview.ReviewFacts memory review =
                StreamFinalitySanctionReviewReads.review(combined, 160);
            actual = abi.decode(combined, (StreamArtistSanctionPreparation));
            raw = abi.encode(review);
        } else {
            actual = abi.decode(
                _read(
                    pins.finalityRegistry,
                    abi.encodeCall(
                        IStreamArtistSanctionPreparation.prepareSanction,
                        (scope, q.nonSanctionComponents, q.manifest)
                    ),
                    128,
                    pins.readGas
                ),
                (StreamArtistSanctionPreparation)
            );
        }
        S.Subject memory p;
        p.domain = keccak256("6529STREAM_ARTIST_SANCTION_SUBJECT_V1");
        p.chainId = e.chainId;
        p.core = e.core;
        p.finalityRegistry = pins.finalityRegistry;
        p.scopeType = q.terms.scopeType;
        p.collectionId = q.terms.collectionId;
        p.tokenId = q.terms.tokenId;
        p.scopeId = q.terms.scopeId;
        p.coreFactsHash = actual.coreFactsHash;
        p.nonSanctionComponentsHash = actual.nonSanctionComponentsHash;
        p.manifestURIHash = q.manifest.uriHash;
        p.manifestContentHash = q.manifest.contentHash;
        p.manifestSchemaId = q.manifest.schemaId;
        p.manifestCanonicalizationHash = q.manifest.canonicalizationHash;
        if (
            actual.sanctionSubjectHash != StreamArtistSanctionHashes.subject(p)
                || actual.scopeInputsHash == 0
        ) revert S.InvalidSanction();
        if (raw.length == 0) {
            raw = _readReview(
                pins.provider,
                abi.encodeCall(
                    IStreamFinalitySanctionReview.requireSanctionReviewFacts,
                    (scope, q.manifest.contentHash)
                ),
                pins.readGas
            );
        }
        uint256 referenceCount = _word(raw, 224);
        uint256 profile = _word(raw, 64);
        // Two explicitly admitted native ONCHAIN profiles. Both retain every ordered original
        // reference artifact occurrence, including repeated bytes, and have no media objects.
        if (
            _word(raw, 0) != 32 || _word(raw, 32) != 1 || _word(raw, 96) == 0
                || _word(raw, 128) != 160 || _word(raw, 160) != 192 || _word(raw, 192) != 0
                || referenceCount == 0 || referenceCount > 16
                || raw.length != 256 + referenceCount * 32
                || !((profile == 1 && referenceCount == 1) || (profile == 2 && referenceCount >= 2))
        ) revert S.InvalidSanctionCeremony();
        for (uint256 i; i < referenceCount; ++i) {
            if (_word(raw, 256 + i * 32) == 0) revert S.InvalidSanctionCeremony();
        }
        IStreamFinalitySanctionReview.ReviewFacts memory reviewed =
            abi.decode(raw, (IStreamFinalitySanctionReview.ReviewFacts));
        S.Ceremony memory c = S.Ceremony(
            reviewed.contentRoot,
            reviewed.mediaContentHashes,
            reviewed.referenceRenderContentHashes,
            q.statement,
            q.signingToolName,
            q.signingToolVersion
        );
        result = Q.Prepared(
            p, StreamArtistSanctionCeremony.document(p, c), actual.scopeInputsHash, keccak256(raw)
        );
    }

    function _selected(address core, bytes32 key, address expected, uint256 cap) private view {
        bytes memory raw =
            _read(core, abi.encodeCall(IStreamCorePointers.getSatellitePointer, (key)), 320, cap);
        uint256 addressWord = _word(raw, 0);
        address actual = address(uint160(addressWord));
        if (
            addressWord >> 160 != 0 || actual != expected || actual.code.length == 0
                || actual.codehash != bytes32(_word(raw, 32))
        ) revert T.ComponentChanged(expected);
    }

    function _word(bytes memory value, uint256 offset) private pure returns (uint256 word) {
        assembly ("memory-safe") { word := mload(add(add(value, 32), offset)) }
    }

    // Match the shared finality reader: cap is an upper bound, measured after allocation.
    function _readReview(address target, bytes memory data, uint256 cap)
        private
        view
        returns (bytes memory raw)
    {
        if (cap == 0 || cap > type(uint256).max / 64) revert T.InvalidBinding();
        raw = new bytes(768);
        uint256 available = gasleft();
        if (available <= 100000) revert SanctionParentGas(available, 100000);
        uint256 forwarded = available - 100000;
        if (cap < forwarded) forwarded = cap;
        bool ok;
        uint256 returned;
        assembly ("memory-safe") {
            ok := staticcall(forwarded, target, add(data, 32), mload(data), add(raw, 32), 768)
            returned := returndatasize()
        }
        if (!ok || returned < 288 || returned > 768) revert SanctionReadFailed(target);
        assembly ("memory-safe") { mstore(raw, returned) }
    }

    function _read(address target, bytes memory data, uint256 size, uint256 cap)
        private
        view
        returns (bytes memory raw)
    {
        if (cap == 0 || cap > type(uint256).max / 64) revert T.InvalidBinding();
        raw = new bytes(size);
        uint256 available = gasleft();
        if (available <= 100000) revert SanctionParentGas(available, 100000);
        uint256 forwarded = available - 100000;
        if (cap < forwarded) forwarded = cap;
        bool ok;
        uint256 returned;
        assembly ("memory-safe") {
            ok := staticcall(forwarded, target, add(data, 32), mload(data), add(raw, 32), size)
            returned := returndatasize()
        }
        if (!ok || returned != size) revert SanctionReadFailed(target);
    }
}

