pragma solidity ^0.8.19;

import "./StreamArtistHashes.sol";
import "../../interfaces/stream/artist/IStreamArtistSuccessionRecords.sol";

/// @notice Frozen succession record preimages and a bounded canonical public directive schema.
library StreamArtistSuccessionHashes {
    function designationDigest(
        StreamArtistHashes.Environment memory e,
        Succ.Designation memory p,
        T.Authorization memory a
    ) public pure returns (bytes32) {
        return StreamArtistHashes.typed(
            e,
            keccak256(
                abi.encode(
                    bytes32(0x978b9dfcca0968239ea043e735357728a9489fe40067fea6673256206c83de15),
                    p.artistId,
                    p.successor,
                    p.successorKind,
                    p.grantedCapabilities,
                    p.conditionsHash,
                    p.directiveHash,
                    a.nonce,
                    a.time
                )
            )
        );
    }

    function directiveDigest(
        StreamArtistHashes.Environment memory e,
        Succ.Directive memory p,
        T.Authorization memory a
    ) public pure returns (bytes32) {
        return StreamArtistHashes.typed(
            e,
            keccak256(
                abi.encode(
                    bytes32(0xa1f146b360069294c6453e91242bb36bb0245545d57b3c89e1cc73c25e953d31),
                    p.artistId,
                    p.grantedCapabilities,
                    p.forbiddenCapabilities,
                    p.directivePayloadHash,
                    a.nonce,
                    a.time
                )
            )
        );
    }

    function designationRecord(
        StreamArtistHashes.Environment memory e,
        Succ.Designation memory p,
        T.Authorization memory a
    ) public pure returns (bytes32) {
        return keccak256(
            abi.encode(
                bytes32(0xe72b08eca38f3231b67e0fa8daba2f1d5daf1953d4b91f8c8e698d14f0ed2b0a),
                e.chainId,
                e.registry,
                p.artistId,
                p.successor,
                p.successorKind,
                p.grantedCapabilities,
                p.conditionsHash,
                p.directiveHash,
                a.nonce,
                a.time
            )
        );
    }

    function directiveRecord(
        StreamArtistHashes.Environment memory e,
        Succ.Directive memory p,
        T.Authorization memory a
    ) public pure returns (bytes32) {
        return keccak256(
            abi.encode(
                bytes32(0x993e7562ac3c0f8eddb70e4c49c42ef750a52133056061d419fdbe9ee7236f50),
                e.chainId,
                e.registry,
                p.artistId,
                p.grantedCapabilities,
                p.forbiddenCapabilities,
                p.directivePayloadHash,
                a.nonce,
                a.time
            )
        );
    }

    function publicPayload(uint32 granted, uint32 forbidden, Succ.PublicDocument memory document)
        public
        pure
        returns (bytes memory)
    {
        if ((granted | forbidden) & ~uint32(4095) != 0 || granted & forbidden != 0) {
            revert Succ.InvalidDirective();
        }
        return abi.encodePacked(
            '{"forbiddenCapabilities":',
            _decimal(forbidden),
            ',"grantedCapabilities":',
            _decimal(granted),
            ',"legalInstrumentHash":"',
            _hex(document.legalInstrumentHash),
            '","payoutRoutingIntentHash":"',
            _hex(document.payoutRoutingIntentHash),
            '","schema":"6529STREAM_ESTATE_DIRECTIVE_V1"}'
        );
    }

    function _decimal(uint32 value) private pure returns (bytes memory result) {
        uint32 copy = value;
        uint256 digits = 1;
        while (copy >= 10) {
            ++digits;
            copy /= 10;
        }
        result = new bytes(digits);
        while (digits != 0) {
            result[--digits] = bytes1(uint8(48 + value % 10));
            value /= 10;
        }
    }

    function _hex(bytes32 value) private pure returns (bytes memory result) {
        bytes16 alphabet = "0123456789abcdef";
        result = new bytes(66);
        result[0] = "0";
        result[1] = "x";
        for (uint256 i; i < 32; ++i) {
            result[2 + i * 2] = alphabet[uint8(value[i]) >> 4];
            result[3 + i * 2] = alphabet[uint8(value[i]) & 15];
        }
    }

    function isDesignatedAccount(address account) public view returns (bool) {
        if (account.code.length != 23) return false;
        bytes3 prefix;
        assembly {
            let p := mload(0x40)
            extcodecopy(account, p, 0, 3)
            prefix := mload(p)
        }
        return prefix == hex"ef0100";
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamArtistSuccessionHashes.sol";
import "./StreamArtistRegistryValidatorBase.sol";
import "../../interfaces/stream/artist/IStreamArtistIdentityOwner.sol";
import "../../interfaces/stream/artist/IStreamArtistArchiveV2.sol";
import {
    StreamArtistDelegationTypes as D
} from "../../interfaces/stream/artist/StreamArtistDelegationTypes.sol";
import "../../interfaces/stream/parameters/IStreamGasParameterHost.sol";

/// @notice Fixed typed succession recipes, executed in the authenticated locked Coordinator.
library StreamArtistSuccessionOperations {
    function designate(
        D.CoordinatorContext memory x,
        address actor,
        Succ.Designation memory p,
        T.Authorization memory submitted
    ) public returns (bytes32 record) {
        T.Snapshot[7] memory before_ = _snapshots(x);
        address signer = _authority(x, p.artistId);
        T.Authorization memory effective = _effective(actor, signer, submitted);
        T.SignerApproval memory proof = _verify(
            x,
            actor,
            signer,
            StreamArtistSuccessionHashes.designationDigest(_environment(x), p, effective),
            effective.signature
        );
        IStreamArtistSuccessionOwner owner = IStreamArtistSuccessionOwner(x.suite.owners[2]);
        record = owner.recordSuccessorDesignation(
            T.ActionContext(36, actor, before_[2]), p, effective, proof
        );
        _archive(
            x,
            36,
            actor,
            record,
            before_,
            abi.encode(p, submitted, effective, proof, owner.successorDesignationRecord(record))
        );
    }

    function directive(
        D.CoordinatorContext memory x,
        address actor,
        Succ.Directive memory p,
        T.Authorization memory submitted,
        Succ.PublicDocument memory document
    ) public returns (bytes32 record) {
        T.Snapshot[7] memory before_ = _snapshots(x);
        address signer = _authority(x, p.artistId);
        T.Authorization memory effective = _effective(actor, signer, submitted);
        T.SignerApproval memory proof = _verify(
            x,
            actor,
            signer,
            StreamArtistSuccessionHashes.directiveDigest(_environment(x), p, effective),
            effective.signature
        );
        IStreamArtistSuccessionOwner owner = IStreamArtistSuccessionOwner(x.suite.owners[2]);
        record = owner.recordEstateDirective(
            T.ActionContext(37, actor, before_[2]), p, effective, proof, document
        );
        _archive(
            x,
            37,
            actor,
            record,
            before_,
            abi.encode(
                p,
                submitted,
                effective,
                proof,
                document,
                owner.estateDirectiveRecord(record),
                owner.estateDirectivePayload(record)
            )
        );
    }

    function _authority(D.CoordinatorContext memory x, bytes32 artistId)
        private
        view
        returns (address signer)
    {
        uint8 class_;
        uint8 status;
        (signer, class_, status,) =
            IStreamArtistIdentityOwner(x.suite.owners[2]).authorityState(artistId);
        if (signer == address(0) || class_ != 1 || (status != 1 && status != 2)) {
            revert T.InvalidIdentity(artistId);
        }
    }

    function _effective(address actor, address signer, T.Authorization memory submitted)
        private
        view
        returns (T.Authorization memory effective)
    {
        effective = T.Authorization(submitted.nonce, submitted.time, submitted.signature);
        if (actor == signer && submitted.signature.length == 0 && submitted.time == 0) {
            if (block.timestamp > type(uint64).max) revert T.InvalidRecord();
            effective.time = uint64(block.timestamp);
        }
    }

    function _verify(
        D.CoordinatorContext memory x,
        address actor,
        address signer,
        bytes32 digest,
        bytes memory signature
    ) private view returns (T.SignerApproval memory) {
        if (actor == address(0) || signer == address(0)) {
            revert T.InvalidSignature();
        }
        bool direct = actor == signer && signature.length == 0;
        if (!direct) {
            (uint256 cap,, uint8 failureClass, uint64 revision) = IStreamGasParameterHost(
                    x.suite.registry
                ).gasParameterInfo(keccak256("6529STREAM_GGP_ARTIST_ERC1271_VERIFY_GAS"));
            if (
                revision == 0 || failureClass != 2
                    || !StreamArtistRegistryValidatorBase(x.suite.validator)
                        .validateSignerProof(signer, digest, signature, cap)
            ) {
                revert T.InvalidSignature();
            }
        }
        return T.SignerApproval(signer, digest, direct);
    }

    function _environment(D.CoordinatorContext memory x)
        private
        view
        returns (StreamArtistHashes.Environment memory)
    {
        return StreamArtistHashes.Environment(
            block.chainid, x.suite.registry, x.suite.core, x.suite.mintManager
        );
    }

    function _snapshots(D.CoordinatorContext memory x)
        private
        view
        returns (T.Snapshot[7] memory result)
    {
        result[2] = IStreamArtistOwner(x.suite.owners[2]).ownerStateSnapshotV2();
    }

    function _archive(
        D.CoordinatorContext memory x,
        uint16 op,
        address actor,
        bytes32 record,
        T.Snapshot[7] memory before_,
        bytes memory payload
    ) private {
        bytes32 id = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_ONBOARDING_OPERATION_EVIDENCE_V1"),
                block.chainid,
                x.suite.registry,
                address(this),
                op,
                actor,
                record
            )
        );
        bytes memory evidence = abi.encode(
            uint16(1), x.configurationHash, op, actor, record, before_, _snapshots(x), payload
        );
        (bytes32 hash,, bool appended) =
            IStreamArtistArchiveV2(x.suite.archive).appendArtistEvidenceV2(id, 1, evidence);
        if (!appended || hash != keccak256(evidence)) revert T.InvalidRecord();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "./StreamArtistAuthorityCheckpoint.sol";
import { StreamArtistPayloadStore } from "./StreamArtistPayloadStore.sol";

import "./StreamArtistIdentityState.sol";
import "./StreamArtistRotationState.sol";
import "./StreamArtistSuccessionHashes.sol";

/// @notice Identity-owned succession records; linked code owns no independent authority.
library StreamArtistSuccessionState {
    struct State {
        mapping(bytes32 => Succ.DesignationRecord) designations;
        mapping(bytes32 => Succ.DirectiveRecord) directives;
        mapping(bytes32 => bytes) payloads;
        mapping(bytes32 => bytes32) stableDesignation;
        mapping(bytes32 => bytes32) candidateDesignation;
        mapping(bytes32 => bytes32) stableDirective;
        mapping(bytes32 => bytes32) candidateDirective;
    }
    event ArtistSuccessorDesignated(
        uint16 schemaVersion,
        bytes32 indexed artistId,
        address indexed successor,
        uint8 successorKind,
        uint32 grantedCapabilities,
        bytes32 conditionsHash,
        bytes32 directiveHash,
        uint256 nonce,
        uint64 signedAt,
        bytes32 designationRecordHash
    );
    event ArtistEstateDirectiveRecorded(
        uint16 schemaVersion,
        bytes32 indexed artistId,
        uint32 grantedCapabilities,
        uint32 forbiddenCapabilities,
        bytes32 directivePayloadHash,
        uint256 nonce,
        uint64 signedAt,
        bytes32 directiveRecordHash
    );

    function operativeDesignation(
        State storage s,
        StreamArtistRotationState.State storage rotations,
        bytes32 artistId
    ) public view returns (bytes32) {
        bytes32 base = s.stableDesignation[artistId];
        bytes32 candidate = s.candidateDesignation[artistId];
        if (
            candidate != bytes32(0)
                && StreamArtistRotationState.eligible(
                    rotations, artistId, s.designations[candidate].provisional
                )
                && (base == bytes32(0)
                    || s.designations[candidate].nonce > s.designations[base].nonce)
        ) {
            return candidate;
        }
        return base;
    }

    function operativeDirective(
        State storage s,
        StreamArtistRotationState.State storage rotations,
        bytes32 artistId
    ) public view returns (bytes32) {
        bytes32 base = s.stableDirective[artistId];
        bytes32 candidate = s.candidateDirective[artistId];
        if (
            candidate != bytes32(0)
                && StreamArtistRotationState.eligible(
                    rotations, artistId, s.directives[candidate].provisional
                )
                && (base == bytes32(0) || s.directives[candidate].nonce > s.directives[base].nonce)
        ) {
            return candidate;
        }
        return base;
    }

    function successor(
        State storage s,
        StreamArtistRotationState.State storage rotations,
        bytes32 artistId
    ) public view returns (address account, bytes32 record) {
        record = operativeDesignation(s, rotations, artistId);
        account = s.designations[record].terms.successor;
    }

    function requireAllowed(
        State storage s,
        StreamArtistRotationState.State storage rotations,
        bytes32 artistId,
        uint32 capabilities
    ) public view {
        bytes32 record = operativeDirective(s, rotations, artistId);
        if (s.directives[record].terms.forbiddenCapabilities & capabilities != 0) {
            revert Succ.ForbiddenCapability(artistId, capabilities, record);
        }
    }

    function designate(
        State storage s,
        StreamArtistIdentityState.State storage identity,
        StreamArtistRotationState.State storage rotations,
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistIdentityState.OwnerContext memory o,
        T.ActionContext memory c,
        Succ.Designation memory p,
        T.Authorization memory a,
        T.SignerApproval memory proof
    ) public returns (StreamArtistIdentityState.Mutation memory m) {
        Dismissal.Closure memory empty;
        return _designate(s, identity, rotations, replay, o, c, p, a, proof, empty);
    }

    function designateWithResolution(
        State storage s,
        StreamArtistIdentityState.State storage identity,
        StreamArtistRotationState.State storage rotations,
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistIdentityState.OwnerContext memory o,
        T.ActionContext memory c,
        Succ.Designation memory p,
        T.Authorization memory a,
        T.SignerApproval memory proof,
        Dismissal.Closure memory closure
    ) public returns (StreamArtistIdentityState.Mutation memory m) {
        return _designate(s, identity, rotations, replay, o, c, p, a, proof, closure);
    }

    function _designate(
        State storage s,
        StreamArtistIdentityState.State storage identity,
        StreamArtistRotationState.State storage rotations,
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistIdentityState.OwnerContext memory o,
        T.ActionContext memory c,
        Succ.Designation memory p,
        T.Authorization memory a,
        T.SignerApproval memory proof,
        Dismissal.Closure memory closure
    ) private returns (StreamArtistIdentityState.Mutation memory m) {
        bool ownKey = p.successor.code.length == 0
            || StreamArtistSuccessionHashes.isDesignatedAccount(p.successor);
        if (
            p.successor == address(0) || (p.successorKind != 1 && p.successorKind != 2)
                || (p.successorKind == 1) != ownKey || p.grantedCapabilities & ~uint32(4095) != 0
        ) {
            revert Succ.InvalidSuccessor();
        }
        if (
            p.directiveHash != bytes32(0)
                && (s.directives[p.directiveHash].recordHash == bytes32(0)
                    || s.directives[p.directiveHash].terms.artistId != p.artistId)
        ) revert Succ.InvalidDirective();
        _time(a, proof);
        bytes32 record = StreamArtistSuccessionHashes.designationRecord(o.environment, p, a);
        if (s.designations[record].recordHash != bytes32(0)) revert T.InvalidRecord();
        m = StreamArtistIdentityState.authorize(
            identity,
            replay,
            o,
            c,
            p.artistId,
            a,
            proof,
            StreamArtistSuccessionHashes.designationDigest(o.environment, p, a),
            record,
            identity.identities[p.artistId].authorityAddress
        );
        bytes32 base = operativeDesignation(s, rotations, p.artistId);
        R.ProvisionalAssociation memory association_ =
            StreamArtistRotationState.associationWithResolution(rotations, p.artistId, closure);
        Succ.DesignationRecord memory item =
            Succ.DesignationRecord(record, p, proof.signer, 1, a.nonce, a.time, association_);
        s.designations[record] = item;
        if (association_.transitionRecordHash == bytes32(0)) {
            s.stableDesignation[p.artistId] =
                base == bytes32(0) || a.nonce > s.designations[base].nonce ? record : base;
            delete s.candidateDesignation[p.artistId];
        } else {
            s.stableDesignation[p.artistId] = base;
            bytes32 candidate = s.candidateDesignation[p.artistId];
            if (
                candidate == bytes32(0)
                    || s.designations[candidate].provisional.transitionRecordHash
                        != association_.transitionRecordHash
                    || a.nonce > s.designations[candidate].nonce
            ) s.candidateDesignation[p.artistId] = record;
        }
        bytes32 key =
            _consume(replay, o, keccak256("identity_authority.replay.succession_chain"), record);
        m.record = record;
        m.action = keccak256(abi.encode(p, a, proof));
        m.state = keccak256(
            abi.encode(
                m.state,
                base,
                item,
                s.stableDesignation[p.artistId],
                s.candidateDesignation[p.artistId]
            )
        );
        m.replay = keccak256(abi.encode(m.replay, key, record));
        emit ArtistSuccessorDesignated(
            1,
            p.artistId,
            p.successor,
            p.successorKind,
            p.grantedCapabilities,
            p.conditionsHash,
            p.directiveHash,
            a.nonce,
            a.time,
            record
        );

        if (closure.dismissalRecordHash != bytes32(0)) {
            m.state = keccak256(abi.encode(m.state, closure));
        }
    }

    function directive(
        State storage s,
        StreamArtistIdentityState.State storage identity,
        StreamArtistRotationState.State storage rotations,
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistIdentityState.OwnerContext memory o,
        T.ActionContext memory c,
        Succ.Directive memory p,
        T.Authorization memory a,
        T.SignerApproval memory proof,
        Succ.PublicDocument memory document
    ) public returns (StreamArtistIdentityState.Mutation memory m) {
        Dismissal.Closure memory empty;
        return _directive(s, identity, rotations, replay, o, c, p, a, proof, document, empty);
    }

    function directiveWithResolution(
        State storage s,
        StreamArtistIdentityState.State storage identity,
        StreamArtistRotationState.State storage rotations,
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistIdentityState.OwnerContext memory o,
        T.ActionContext memory c,
        Succ.Directive memory p,
        T.Authorization memory a,
        T.SignerApproval memory proof,
        Succ.PublicDocument memory document,
        Dismissal.Closure memory closure
    ) public returns (StreamArtistIdentityState.Mutation memory m) {
        return _directive(s, identity, rotations, replay, o, c, p, a, proof, document, closure);
    }

    function _directive(
        State storage s,
        StreamArtistIdentityState.State storage identity,
        StreamArtistRotationState.State storage rotations,
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistIdentityState.OwnerContext memory o,
        T.ActionContext memory c,
        Succ.Directive memory p,
        T.Authorization memory a,
        T.SignerApproval memory proof,
        Succ.PublicDocument memory document,
        Dismissal.Closure memory closure
    ) private returns (StreamArtistIdentityState.Mutation memory m) {
        _time(a, proof);
        bytes memory payload = StreamArtistSuccessionHashes.publicPayload(
            p.grantedCapabilities, p.forbiddenCapabilities, document
        );
        if (payload.length > 8192) revert T.BoundExceeded(payload.length, 8192);
        if (keccak256(payload) != p.directivePayloadHash) revert Succ.InvalidDirective();
        bytes32 record = StreamArtistSuccessionHashes.directiveRecord(o.environment, p, a);
        if (s.directives[record].recordHash != bytes32(0)) revert T.InvalidRecord();
        m = StreamArtistIdentityState.authorize(
            identity,
            replay,
            o,
            c,
            p.artistId,
            a,
            proof,
            StreamArtistSuccessionHashes.directiveDigest(o.environment, p, a),
            record,
            identity.identities[p.artistId].authorityAddress
        );
        bytes32 base = operativeDirective(s, rotations, p.artistId);
        R.ProvisionalAssociation memory association_ =
            StreamArtistRotationState.associationWithResolution(rotations, p.artistId, closure);
        Succ.DirectiveRecord memory item =
            Succ.DirectiveRecord(record, p, proof.signer, 1, a.nonce, a.time, association_);
        s.directives[record] = item;
        s.payloads[record] = payload;
        StreamArtistPayloadStore.store(keccak256("ARTIST_DIRECTIVE_PAYLOAD"), payload);
        if (association_.transitionRecordHash == bytes32(0)) {
            s.stableDirective[p.artistId] =
                base == bytes32(0) || a.nonce > s.directives[base].nonce ? record : base;
            delete s.candidateDirective[p.artistId];
        } else {
            s.stableDirective[p.artistId] = base;
            bytes32 candidate = s.candidateDirective[p.artistId];
            if (
                candidate == bytes32(0)
                    || s.directives[candidate].provisional.transitionRecordHash
                        != association_.transitionRecordHash
                    || a.nonce > s.directives[candidate].nonce
            ) s.candidateDirective[p.artistId] = record;
        }
        bytes32 key =
            _consume(replay, o, keccak256("identity_authority.replay.directive_chain"), record);
        m.record = record;
        m.action = keccak256(abi.encode(p, a, proof, document));
        m.state = keccak256(
            abi.encode(
                m.state,
                base,
                item,
                s.stableDirective[p.artistId],
                s.candidateDirective[p.artistId],
                keccak256(payload)
            )
        );
        m.replay = keccak256(abi.encode(m.replay, key, record));
        emit ArtistEstateDirectiveRecorded(
            1,
            p.artistId,
            p.grantedCapabilities,
            p.forbiddenCapabilities,
            p.directivePayloadHash,
            a.nonce,
            a.time,
            record
        );

        if (closure.dismissalRecordHash != bytes32(0)) {
            m.state = keccak256(abi.encode(m.state, closure));
        }
    }

    function _time(T.Authorization memory a, T.SignerApproval memory proof) private view {
        if (a.time == 0 || a.time > block.timestamp || (proof.direct && a.time != block.timestamp)) revert T.InvalidTimestamp(a.time);
    }

    function _consume(
        mapping(bytes32 => T.ReplayCell) storage replay,
        StreamArtistIdentityState.OwnerContext memory o,
        bytes32 surface,
        bytes32 record
    ) private returns (bytes32 key) {
        key = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_OWNER_REPLAY_KEY_V2"),
                o.environment.chainId,
                o.environment.registry,
                o.coordinator,
                o.archive,
                address(this),
                o.domain,
                surface,
                keccak256(abi.encode(record))
            )
        );
        if (replay[key].status != 0) revert T.Replay(key);
        replay[key] = T.ReplayCell(record, o.revision + 1, 1, 2);
        StreamArtistAuthorityCheckpoint.noteReplay(key, replay[key]);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import { StreamArtistDefaultTemplateReads } from "./StreamArtistDefaultTemplateReads.sol";
import { StreamArtistScopedTemplateReads } from "./StreamArtistScopedTemplateReads.sol";
import { StreamArtistDynamicTemplateReads } from "./StreamArtistDynamicTemplateReads.sol";
import "../../interfaces/stream/artist/IStreamArtistPrimaryTemplateFacts.sol";
import "../../interfaces/stream/artist/IStreamArtistPrimaryTemplateConsentFacts.sol";
import "../../interfaces/stream/artist/IStreamArtistEconomicsEvidence.sol";
import "../../interfaces/stream/revenue/IStreamRevenueResolver.sol";
import "../../vendor/openzeppelin/IERC165.sol";
import {
    StreamArtistOnboardingTypes as T
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";

/// @notice Fixed linked template facts and evidence reads for the Artist read host.
/// @dev The host first checks its suite, accepted binding and operative payout.
///      Delegatecall preserves that host as the caller of every original provider read.
library StreamArtistTemplateEconomicsReads {
    function prospective(T.EconomicsConsent memory p, bytes32 templateId)
        public
        view
        returns (bytes memory)
    {
        if (p.scope == 0) return StreamArtistDefaultTemplateReads.prospective(p, templateId);
        if (p.scope == 2) return StreamArtistScopedTemplateReads.prospective(p, templateId);
        if (StreamArtistDynamicTemplateReads.isDynamic(p.resolver, templateId)) {
            return StreamArtistDynamicTemplateReads.prospective(p, templateId);
        }
        address resolver = p.resolver;
        IStreamArtistPrimaryTemplateConsentFacts provider =
            IStreamArtistPrimaryTemplateConsentFacts(resolver);
        (bytes32 entriesHash, bytes32 metadataURIHash, uint32 share) =
            provider.primaryTemplateConsentFacts(templateId);
        T.AssignmentFact memory fact = provider.previewArtistPrimaryTemplateConsentAssignment(
            p.collectionId, templateId, bytes32(0), false
        );
        if (
            entriesHash == bytes32(0) || share == 0 || share > 1_000_000
                || fact.resolver != p.resolver || fact.revenueClass != p.revenueClass
                || fact.scope != p.scope || fact.scopeId != p.scopeId
                || fact.assignmentHash != p.assignmentHash
        ) revert T.InvalidRecord();
        return abi.encode(
            keccak256("6529STREAM_PROSPECTIVE_PRIMARY_TEMPLATE_ECONOMICS_EVIDENCE_V1"),
            templateId,
            entriesHash,
            metadataURIHash,
            share,
            fact
        );
    }

    function current(
        uint256 collectionId,
        address resolver,
        bytes32 primaryRevenueClass,
        address consentOwner,
        T.Binding memory binding_,
        IStreamRevenueResolver.ResolvedPrimaryAssignment memory current
    ) public view returns (bytes memory) {
        if (current.scope == 0) {
            return StreamArtistDefaultTemplateReads.current(
                collectionId, resolver, primaryRevenueClass, consentOwner, binding_, current
            );
        }
        if (current.scope == 2) {
            return StreamArtistScopedTemplateReads.current(
                collectionId, resolver, primaryRevenueClass, consentOwner, binding_, current
            );
        }
        if (StreamArtistDynamicTemplateReads.isDynamic(resolver, current.templateId)) {
            return StreamArtistDynamicTemplateReads.current(
                collectionId, resolver, primaryRevenueClass, consentOwner, binding_, current
            );
        }
        bytes32 entriesHash;
        bytes32 metadataURIHash;
        uint32 artistShare;
        T.AssignmentFact memory preview;
        if (_templateConsentCapability(resolver)) {
            IStreamArtistPrimaryTemplateConsentFacts provider =
                IStreamArtistPrimaryTemplateConsentFacts(resolver);
            (entriesHash, metadataURIHash, artistShare) =
                provider.primaryTemplateConsentFacts(current.templateId);
            preview = provider.previewArtistPrimaryTemplateConsentAssignment(
                collectionId, current.templateId, current.policyHash, current.frozen
            );
            if (artistShare < 500_000) {
                T.EconomicsConsent memory consent = T.EconomicsConsent(
                    collectionId,
                    resolver,
                    primaryRevenueClass,
                    1,
                    collectionId,
                    current.assignmentHash
                );
                if (
                    IStreamArtistEconomicsEvidence(consentOwner)
                            .economicsRecordForBinding(
                                consent,
                                binding_.artistId,
                                binding_.generation,
                                binding_.bindingHash
                            ) == bytes32(0)
                ) {
                    revert T.MissingMintPrerequisite(keccak256("economics"));
                }
            }
        } else {
            IStreamArtistPrimaryTemplateFacts provider = IStreamArtistPrimaryTemplateFacts(resolver);
            (entriesHash, metadataURIHash, artistShare) =
                provider.primaryTemplateEconomicsFacts(current.templateId);
            preview = provider.previewArtistPrimaryTemplateAssignment(
                collectionId, current.templateId, current.policyHash, current.frozen
            );
            if (artistShare < 500_000) revert T.InvalidRecord();
        }
        if (
            entriesHash == bytes32(0) || artistShare == 0 || artistShare > 1_000_000
                || preview.resolver != resolver || preview.revenueClass != primaryRevenueClass
                || preview.scope != 1 || preview.scopeId != collectionId
                || preview.assignmentHash != current.assignmentHash
        ) revert T.InvalidRecord();
        return abi.encode(
            keccak256("6529STREAM_CURRENT_PRIMARY_TEMPLATE_ECONOMICS_EVIDENCE_V1"),
            current.templateId,
            entriesHash,
            metadataURIHash,
            artistShare
        );
    }

    function _templateConsentCapability(address resolver) private view returns (bool) {
        return IERC165(resolver)
            .supportsInterface(type(IStreamArtistPrimaryTemplateConsentFacts).interfaceId);
    }
}

