pragma solidity ^0.8.19;

import { IStreamCore } from "../../interfaces/stream/core/IStreamCore.sol";
import {
    IStreamEntropyOriginRelay as R
} from "../../interfaces/stream/entropy/IStreamEntropyOriginRelay.sol";
import {
    IStreamEntropyPolicyContinuity as C
} from "../../interfaces/stream/entropy/IStreamEntropyPolicyContinuity.sol";
import { StreamEntropyIncidentParameters } from "./StreamEntropyIncidentParameters.sol";

/// @notice Permanent origin admissions and per-request relay evidence in the calling host.
library StreamEntropyRelayState {
    bytes32 private constant SLOT = keccak256("6529STREAM_ENTROPY_ORIGIN_RELAY_STORAGE_V1");
    bytes32 internal constant RELAY_DOMAIN = keccak256("6529STREAM_ENTROPY_RELAY_V1");
    bytes32 internal constant WITNESS_DOMAIN = keccak256("6529STREAM_ENTROPY_RELAY_WITNESS_V1");

    struct Admission {
        bytes32 successorCodeHash;
        bytes32 importHash;
        bytes32 policyHash;
        bytes32 exportHash;
        C.PolicyExport policy;
        C.RecoveryExport recovery;
    }

    /// @dev Parent host exposes witnessHash only after checking its actual request/snapshot/subject.
    struct LocalRoute {
        address origin;
        bytes32 originCodeHash;
        bytes32 importHash;
        bytes32 relayId;
        bytes32 witnessHash;
    }

    struct Store {
        mapping(uint256 => mapping(address => Admission)) admissions;
        mapping(bytes32 => bool) actions;
        mapping(bytes32 => R.RelayResult) results;
        mapping(bytes32 => bytes32) requestRelays;
        mapping(address => mapping(uint256 => bytes32)) providerRelays;
        mapping(bytes32 => LocalRoute) localRoutes;
    }

    function store() internal pure returns (Store storage s) {
        bytes32 slot = SLOT;
        assembly ("memory-safe") { s.slot := slot }
    }

    function context(IStreamCore core, R.RelayInput memory input)
        internal
        pure
        returns (bytes memory)
    {
        return abi.encode(
            uint16(input.scopeId == 0 ? 1 : 2),
            address(core),
            input.collectionId,
            input.tokenId,
            input.scopeId,
            input.policy.providerEpoch,
            input.policy.providerConfigHash,
            input.policy.requestAttempt,
            input.policy.inputsHash
        );
    }

    function requestKey(IStreamCore core, address successor, R.RelayInput memory input)
        internal
        view
        returns (bytes32)
    {
        if (input.scopeId == 0) {
            return keccak256(
                abi.encode(
                    keccak256("6529STREAM_ENTROPY_REQUEST_V1"),
                    block.chainid,
                    successor,
                    address(core),
                    input.collectionId,
                    input.tokenId,
                    input.policy.provider,
                    input.policy.providerEpoch,
                    input.policy.providerConfigHash,
                    input.policy.requestAttempt
                )
            );
        }
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_ENTROPY_SCOPE_REQUEST_V1"),
                block.chainid,
                successor,
                address(core),
                input.collectionId,
                input.scopeId,
                input.policy.provider,
                input.policy.providerEpoch,
                input.policy.providerConfigHash,
                input.policy.inputsHash,
                input.policy.requestAttempt
            )
        );
    }

    function relayId(IStreamCore core, address origin, address successor, R.RelayInput memory input)
        internal
        view
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                RELAY_DOMAIN,
                block.chainid,
                origin,
                successor,
                successor.codehash,
                input.importHash,
                input.collectionId,
                input.successorRequestKey,
                keccak256(context(core, input))
            )
        );
    }

    function witnessHash(
        IStreamCore core,
        address successor,
        address origin,
        bytes32 originCodeHash,
        R.RelayInput memory input
    ) internal view returns (bytes32) {
        return keccak256(
            abi.encode(
                WITNESS_DOMAIN,
                block.chainid,
                address(core),
                successor,
                successor.codehash,
                origin,
                originCodeHash,
                input
            )
        );
    }

    /// @notice Called only after the successor prewrites its complete actual request and snapshot.
    function prewriteLocal(
        IStreamCore core,
        address origin,
        bytes32 originCodeHash,
        R.RelayInput memory input
    ) internal returns (bytes32 id) {
        if (
            origin == address(this) || origin.code.length == 0 || origin.codehash != originCodeHash
                || originCodeHash == 0 || input.importHash == 0
                || input.successorRequestKey != requestKey(core, address(this), input)
                || store().localRoutes[input.successorRequestKey].origin != address(0)
        ) revert R.InvalidEntropyRelay();
        id = relayId(core, origin, address(this), input);
        store().localRoutes[input.successorRequestKey] = LocalRoute(
            origin,
            originCodeHash,
            input.importHash,
            id,
            witnessHash(core, address(this), origin, originCodeHash, input)
        );
    }

    /// @dev Ordinary and relayed provider-ID binding paths must both invoke this guard.
    function requireProviderIdUnused(address provider, uint256 id) internal view {
        if (store().providerRelays[provider][id] != 0) {
            revert R.EntropyRelayProviderIdCollision(provider, id);
        }
    }

    function requireRequestKeyUnused(bytes32 key) internal view {
        if (store().requestRelays[key] != 0) revert R.EntropyRelayRequestCollision(key);
    }
}

/// @notice Fixed-size/bounded authentication reads under a distinct full-cap relay envelope.
library StreamEntropyRelayReads {
    bytes32 internal constant AUTH_GAS =
        keccak256("6529STREAM_GGP_ENTROPY_RELAY_AUTH_READ_GAS_LIMIT");

    function read(address target, bytes memory data, uint256 size)
        internal
        view
        returns (bytes memory out)
    {
        out = bounded(target, data, size);
        if (out.length != size) revert R.EntropyRelayReadFailed(target);
    }

    function bounded(address target, bytes memory data, uint256 maximum)
        internal
        view
        returns (bytes memory out)
    {
        if (target.code.length == 0) revert R.EntropyRelayDependency(target);
        uint256 cap = StreamEntropyIncidentParameters.value(AUTH_GAS);
        out = new bytes(maximum);
        uint256 available = gasleft();
        if (available <= 15000 || (available - 15000) / 64 * 63 < cap) {
            revert R.EntropyRelayReadFailed(target);
        }
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(data, 32), mload(data), add(out, 32), maximum)
            size := returndatasize()
        }
        if (!ok || size > maximum) revert R.EntropyRelayReadFailed(target);
        assembly ("memory-safe") { mstore(out, size) }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import { IERC165 } from "../../vendor/openzeppelin/IERC165.sol";
import { IStreamCoreIdentity as Core } from "../../interfaces/stream/core/IStreamCoreIdentity.sol";
import {
    IStreamEntropyView as E,
    StreamEntropyStatus
} from "../../interfaces/stream/entropy/IStreamEntropyView.sol";
import {
    StreamEntropyPolicyConsumerTypes as P,
    IStreamEntropyPolicyConsumerRead as Read,
    IStreamEntropyPolicyStaticRead as StaticRead
} from "../../interfaces/stream/entropy/StreamEntropyPolicyConsumerTypes.sol";
import { StreamRendererCalls as Calls } from "../metadata/StreamRendererCalls.sol";

/// @notice Original-at-mint terminal facts. This is not evidence that an arbitrary program is entropy-independent.
/// @dev staticTerminal uses the direct producer profile. Ordinary terminal/policy reads retain
/// the original live getters, which may use linked read workers and are not STATIC conformance.
library StreamEntropyRenderPolicyReads {
    error InvalidTerminalEntropy(uint256 tokenId);

    function policy(address coordinator, address core, uint256 collectionId, uint256 cap)
        internal
        view
        returns (P.Policy memory p)
    {
        if (coordinator.code.length == 0 || core.code.length == 0) {
            revert InvalidTerminalEntropy(0);
        }
        if (
            !abi.decode(
                    Calls.read(
                        coordinator,
                        abi.encodeCall(IERC165.supportsInterface, (P.CAPABILITY)),
                        Calls.ReadOptions(32, true),
                        cap
                    ),
                    (bool)
                )
                || abi.decode(
                        Calls.read(
                            coordinator,
                            abi.encodeWithSignature("core()"),
                            Calls.ReadOptions(32, true),
                            cap
                        ),
                        (address)
                    ) != core
        ) {
            revert InvalidTerminalEntropy(0);
        }
        bytes memory raw = Calls.read(
            coordinator,
            abi.encodeCall(Read.collectionEntropyPolicy, (collectionId)),
            Calls.ReadOptions(384, true),
            cap
        );
        p = abi.decode(raw, (P.Policy));
        if (keccak256(raw) != keccak256(abi.encode(p))) revert InvalidTerminalEntropy(0);
        _policy(p);
    }

    function _policy(P.Policy memory p) private pure {
        if (
            !p.configured || !p.explicitPolicy || !p.frozen || p.mode > 2 || p.securityClass > 1
                || p.renderRequirement > 1 || p.revision == 0 || p.policyHash == 0
                || p.lastActionId == 0 || p.artistConsentRecord == 0
                || p.contentStateHash != keccak256(abi.encode(P.FAMILY, p.policyHash, p.frozen))
        ) {
            revert InvalidTerminalEntropy(0);
        }
    }

    /// @notice Separate storage-only producer profile for executable STATIC serving.
    /// The original tokenSeed getter derives finalized solely from status. The original tokenEntropy
    /// getter returns requestId/attempt zero whenever this same Subject.requestKey is zero.
    function staticTerminal(address core, uint256 tokenId, uint256 collectionId, uint256 cap)
        internal
        view
        returns (P.Terminal memory t)
    {
        (bool exists, uint256 actualCollection,,) = abi.decode(
            Calls.read(
                core,
                abi.encodeCall(Core.tokenCollectionIdentity, (tokenId)),
                Calls.ReadOptions(128, true),
                cap
            ),
            (bool, uint256, uint256, bool)
        );
        if (!exists || collectionId == 0 || actualCollection != collectionId) {
            revert InvalidTerminalEntropy(tokenId);
        }
        t.coordinator = abi.decode(
            Calls.read(
                core,
                abi.encodeCall(Core.coordinatorAtMint, (tokenId)),
                Calls.ReadOptions(32, true),
                cap
            ),
            (address)
        );
        t.coordinatorCodeHash = t.coordinator.codehash;
        if (
            t.coordinator.code.length == 0
                || !abi.decode(
                    Calls.read(
                        t.coordinator,
                        abi.encodeCall(IERC165.supportsInterface, (P.STATIC_CAPABILITY)),
                        Calls.ReadOptions(32, true),
                        cap
                    ),
                    (bool)
                )
                || abi.decode(
                        Calls.read(
                            t.coordinator,
                            abi.encodeWithSignature("core()"),
                            Calls.ReadOptions(32, true),
                            cap
                        ),
                        (address)
                    ) != core
        ) revert InvalidTerminalEntropy(tokenId);
        bytes memory raw = Calls.read(
            t.coordinator,
            abi.encodeCall(StaticRead.staticTerminalEntropyFacts, (tokenId)),
            Calls.ReadOptions(512, true),
            cap
        );
        uint256 retainedCollection;
        bytes32 seed;
        bytes32 request;
        (retainedCollection, t.policy, t.status, seed, request) =
            abi.decode(raw, (uint256, P.Policy, uint8, bytes32, bytes32));
        if (
            keccak256(raw)
                    != keccak256(abi.encode(retainedCollection, t.policy, t.status, seed, request))
                || retainedCollection != collectionId || seed != 0 || request != 0
                || t.policy.renderRequirement != 1
                || (t.status == 1 ? t.policy.mode != 0 : t.status != 2 || t.policy.mode != 2)
        ) revert InvalidTerminalEntropy(tokenId);
        _policy(t.policy);
    }

    function terminal(address core, uint256 tokenId, uint256 collectionId, uint256 cap)
        internal
        view
        returns (P.Terminal memory t)
    {
        (bool exists, uint256 actualCollection,,) = abi.decode(
            Calls.read(
                core,
                abi.encodeCall(Core.tokenCollectionIdentity, (tokenId)),
                Calls.ReadOptions(128, true),
                cap
            ),
            (bool, uint256, uint256, bool)
        );
        if (!exists || collectionId == 0 || actualCollection != collectionId) {
            revert InvalidTerminalEntropy(tokenId);
        }
        t.coordinator = abi.decode(
            Calls.read(
                core,
                abi.encodeCall(Core.coordinatorAtMint, (tokenId)),
                Calls.ReadOptions(32, true),
                cap
            ),
            (address)
        );
        t.coordinatorCodeHash = t.coordinator.codehash;
        t.policy = policy(t.coordinator, core, collectionId, cap);
        bytes memory raw = Calls.read(
            t.coordinator,
            abi.encodeCall(E.tokenEntropy, (tokenId)),
            Calls.ReadOptions(256, true),
            cap
        );
        (
            StreamEntropyStatus status,
            bytes32 seed,
            address provider,
            uint32 epoch,
            bytes32 configuration,
            bytes32 request,
            uint256 requestId,
            uint16 attempt
        ) = abi.decode(
            raw, (StreamEntropyStatus, bytes32, address, uint32, bytes32, bytes32, uint256, uint16)
        );
        if (
            keccak256(raw)
                != keccak256(
                    abi.encode(
                        status, seed, provider, epoch, configuration, request, requestId, attempt
                    )
                )
        ) revert InvalidTerminalEntropy(tokenId);
        t.status = uint8(status);
        if (
            t.policy.renderRequirement != 1
                || (t.status == 1 ? t.policy.mode != 0 : t.status != 2 || t.policy.mode != 2)
                || seed != 0 || request != 0 || requestId != 0 || attempt != 0
        ) revert InvalidTerminalEntropy(tokenId);
        (bytes32 savedSeed, bool finalized) = abi.decode(
            Calls.read(
                t.coordinator,
                abi.encodeCall(E.tokenSeed, (tokenId)),
                Calls.ReadOptions(64, true),
                cap
            ),
            (bytes32, bool)
        );
        if (
            savedSeed != 0 || finalized
                || abi.decode(
                        Calls.read(
                            t.coordinator,
                            abi.encodeCall(E.tokenEntropyStatus, (tokenId)),
                            Calls.ReadOptions(32, true),
                            cap
                        ),
                        (StreamEntropyStatus)
                    ) != status
        ) {
            revert InvalidTerminalEntropy(tokenId);
        }
        // Provider/epoch/configuration are retained only in the producer's policy. They are never
        // repurposed as a request or fabricated into a terminal seed/finality claim.
    }
}

