// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "../../vendor/openzeppelin/IERC165.sol";

/// @notice Exact-return static reads with a cap and retained caller gas.
/// @dev The configured cap is an upper bound. Allocate before measuring remaining gas.
library StreamFinalityBoundedReads {
    uint256 internal constant PARENT_RESERVE = 100000;
    error FinalityReadFailed(address target);
    error FinalityCapabilityMalformed(address target);

    function tryRead(address target, bytes memory input, uint256 size, uint256 cap)
        internal
        view
        returns (bool ok, uint256 actualSize, bytes memory result)
    {
        result = new bytes(size);
        uint256 available = gasleft();
        if (available <= PARENT_RESERVE) return (false, 0, result);
        uint256 forwarded = available - PARENT_RESERVE;
        if (cap < forwarded) forwarded = cap;
        assembly ("memory-safe") {
            ok := staticcall(forwarded, target, add(input, 32), mload(input), add(result, 32), size)
            actualSize := returndatasize()
            if iszero(eq(actualSize, size)) { ok := 0 }
        }
    }

    function read(address target, bytes memory input, uint256 size, uint256 cap)
        internal
        view
        returns (bytes memory result)
    {
        (bool ok,, bytes memory raw) = tryRead(target, input, size, cap);
        if (!ok) revert FinalityReadFailed(target);
        return raw;
    }

    function supportsOptional(address target, bytes4 id, uint256 cap) internal view returns (bool) {
        bytes memory input = abi.encodeCall(IERC165.supportsInterface, (id));
        uint256 budget = cap < 30000 ? cap : 30000;
        if (gasleft() <= budget + budget / 63 + PARENT_RESERVE) revert FinalityReadFailed(target);
        bytes memory result = new bytes(32);
        bool ok;
        uint256 size;
        uint256 supported;
        assembly ("memory-safe") {
            ok := staticcall(budget, target, add(input, 32), mload(input), add(result, 32), 32)
            size := returndatasize()
            supported := mload(add(result, 32))
        }
        // Older pinned implementations can have no capability method. Once advertised,
        // execution failure is terminal and cannot fall back to a different validation path.
        if (!ok || size == 0) return false;
        if (size != 32 || supported > 1) revert FinalityCapabilityMalformed(target);
        return supported == 1;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/finality/StreamFinalityConservationTypes.sol";
import "../../interfaces/stream/metadata/IStreamCollectionRecordReceipts.sol";
import "../metadata/StreamMetadataSubjects.sol";
import "../records/StreamConservationDefinitions.sol";
import "../records/StreamWorkRecordDefinitions.sol";

/// @notice Current conservation facts from a fixed original-record selector and receipt host.
/// @dev The consuming provider supplies constructor-fixed addresses/code pins, including a
/// predicted late selector if needed. Success proves current facts, not finality readiness:
/// sanction, lock/exception policy, scope membership and complete archives remain independent.
/// Historical finalized inputs must use their saved evidence, never this current eligibility API.
library StreamFinalityConservationReads {
    struct Dependencies {
        // Core, generic metadata, schemas, byte store, conservation selector.
        address[5] targets;
        bytes32[5] codeHashes;
        uint256 chainId;
        uint256 readGas;
        uint256 selectionGas;
    }

    error ConservationConfiguration();
    error ConservationDependency(address target);
    error ConservationRead(address target, bytes4 selector);
    error ConservationSelection(bytes32 recordHash);
    error ConservationReceipt(bytes32 recordHash);
    error ConservationLock(bytes32 recordHash);

    /// @notice Requires the current original ARTIST_INTENT lineage, without estate fallback.
    /// @dev An unlocked result is explicit. No zero-reference/non-artist default is returned.
    function requireCurrent(Dependencies memory d, StreamFinalityScope memory scope)
        public
        view
        returns (StreamFinalityConservationEvidence memory e)
    {
        _bindings(d);
        e.scopeSubject = StreamMetadataSubjects.scopeSubject(d.chainId, d.targets[0], scope);
        e.selected = _selected(d, scope.collectionId, e.scopeSubject);
        _original(d, scope.collectionId, e.selected.record, e.selected.association, false);
        if (e.selected.record.kind == IStreamConservationRecordSelection.RecordKind.INTENT) {
            e.intentRecordHash = e.selected.record.recordHash;
        } else if (
            e.selected.record.kind == IStreamConservationRecordSelection.RecordKind.INTENT_WAIVER
        ) {
            e.intentWaiverRecordHash = e.selected.record.recordHash;
        } else {
            revert ConservationSelection(e.selected.record.recordHash);
        }
        _interview(d, scope.collectionId, e.selected);
        e.intentLock = _lock(d, scope.collectionId, e.scopeSubject, e.selected);
        e.interviewEvidenceHash = _interviewCommitment(d, scope, e.scopeSubject, e.selected);
        e.archiveRequirement =
        StreamConservationArchiveRequirement.DUAL_FAMILY_REFERENCES_AND_SIGNATURE_BUNDLES;
    }

    /// @notice The narrower policy additionally requires the exact current artist intent lock.
    /// @dev A matching lock still does not prove sanction, archive coverage or complete finality.
    function requireLocked(Dependencies memory d, StreamFinalityScope memory scope)
        public
        view
        returns (StreamFinalityConservationEvidence memory e)
    {
        e = requireCurrent(d, scope);
        if (!e.intentLock.locked) revert ConservationLock(e.selected.record.recordHash);
    }

    function _selected(Dependencies memory d, uint256 cid, bytes32 subject)
        private
        view
        returns (IStreamConservationRecordSelection.Selection memory s)
    {
        bytes memory raw = _read(
            d.targets[4],
            abi.encodeCall(
                IStreamConservationRecordSelection.currentConservation,
                (cid, subject, StreamConservationRecordTypes.StatementOrigin.ARTIST_INTENT)
            ),
            1600,
            d.readGas
        );
        s = abi.decode(raw, (IStreamConservationRecordSelection.Selection));
        if (
            s.record.recordHash == 0 || s.record.payloadHash == 0 || s.revision == 0
                || s.origin != StreamConservationRecordTypes.StatementOrigin.ARTIST_INTENT
                || s.association.artistId == 0 || s.association.bindingHash == 0
                || s.association.generation == 0 || s.association.identityRecordHash == 0
                || s.submitter == address(0) || s.selectedAt == 0
                || s.selectedAt < s.record.recordedAt || s.selectedAt > block.timestamp
                || s.catalogsHash == 0 || keccak256(raw) != keccak256(abi.encode(s))
        ) revert ConservationSelection(s.record.recordHash);
        bytes32 retained = s.selectionHash;
        s.selectionHash = 0;
        bytes32 computed = keccak256(
            abi.encode(
                keccak256("6529STREAM_CONSERVATION_SELECTION_V1"),
                d.chainId,
                d.targets[4],
                d.targets[0],
                d.targets[1],
                d.targets[2],
                d.targets[3],
                cid,
                subject,
                s
            )
        );
        s.selectionHash = retained;
        if (retained != computed) revert ConservationSelection(s.record.recordHash);
        bytes memory current = _read(
            d.targets[4],
            abi.encodeCall(
                IStreamConservationRecordSelection.requireCurrent,
                (cid, subject, s.origin, s.record.recordHash, s.revision)
            ),
            1600,
            d.selectionGas
        );
        if (keccak256(current) != keccak256(raw)) {
            revert ConservationSelection(s.record.recordHash);
        }
        // That exact selector rechecks the full current graph, accepted/sanctioned association,
        // all nine fixed definition bytes and every complete selected catalog. Original signer
        // authority was proven on adoption and is not substituted with today's operative key.
    }

    function _interview(
        Dependencies memory d,
        uint256 cid,
        IStreamConservationRecordSelection.Selection memory s
    ) private view {
        if (s.interviewStatus == StreamConservationRecordTypes.InterviewStatus.PRESENT) {
            if (
                s.interview.kind != IStreamConservationRecordSelection.RecordKind.INTERVIEW
                    || s.interviewArchiveReferenceHash == 0
            ) revert ConservationSelection(s.record.recordHash);
            _original(d, cid, s.interview, s.association, true);
        } else {
            IStreamConservationRecordSelection.RecordEvidence memory empty;
            if (
                keccak256(abi.encode(s.interview)) != keccak256(abi.encode(empty))
                    || s.interviewArchiveReferenceHash != 0
                    || s.interviewPayloadCorrespondence
                        != IStreamConservationRecordSelection.PayloadCorrespondence
                            .UNVERIFIED_REFERENCE
            ) revert ConservationSelection(s.record.recordHash);
        }
    }

    function _original(
        Dependencies memory d,
        uint256 cid,
        IStreamConservationRecordSelection.RecordEvidence memory e,
        IStreamConservationRecordSelection.Association memory a,
        bool interview
    ) private view {
        StreamArtistRecordPublicationTypes.Evidence memory p = e.publication;
        if (
            e.recordHash == 0 || e.payloadHash == 0 || e.recorder == address(0) || e.recordedAt == 0
                || e.recordChainHash == 0 || e.receiptHash == 0 || e.publicationEvidenceHash == 0
                || p.attestationRecordHash == 0 || p.artistId != a.artistId
                || p.bindingHash != a.bindingHash || p.bindingGeneration != a.generation
                || p.signer != e.recorder
                || (interview
                        ? (p.authorityClass != 1 && p.authorityClass != 3)
                        : p.authorityClass != 1) || p.requiredCapability != (interview ? 1 : 64)
                || p.signedAt == 0 || p.signedAt > e.recordedAt || p.publicationHash == 0
        ) revert ConservationReceipt(e.recordHash);
        bytes memory raw = _read(
            d.targets[1],
            abi.encodeCall(IStreamCollectionRecordReceipts.collectionRecordReceipt, (e.recordHash)),
            288,
            d.readGas
        );
        IStreamCollectionMetadataV1.RecordReceipt memory r =
            abi.decode(raw, (IStreamCollectionMetadataV1.RecordReceipt));
        bytes32 schemaHash = interview
            ? StreamConservationDefinitions.INTERVIEW_SCHEMA_HASH
            : e.kind == IStreamConservationRecordSelection.RecordKind.INTENT
                ? StreamConservationDefinitions.INTENT_SCHEMA_HASH
                : StreamConservationDefinitions.WAIVER_SCHEMA_HASH;
        if (
            keccak256(raw) != keccak256(abi.encode(r)) || keccak256(raw) != e.receiptHash
                || r.collectionId != cid || r.recorder != e.recorder || r.authorizationClass != 1
                || r.recordedAt != e.recordedAt || r.recordIndex != e.recordIndex
                || r.recordChainHash != e.recordChainHash || r.schemaDefinitionHash != schemaHash
                || r.canonicalizationDefinitionHash != StreamWorkRecordDefinitions.CANON_HASH
                || r.artistAuthorization != p.attestationRecordHash
        ) revert ConservationReceipt(e.recordHash);
        bytes32 recordType = interview
            ? keccak256("ARTIST_STATEMENT")
            : e.kind == IStreamConservationRecordSelection.RecordKind.INTENT
                ? keccak256("ARTIST_INTENT")
                : keccak256("ARTIST_INTENT_WAIVER");
        _word(
            d,
            1,
            abi.encodeCall(
                IStreamCollectionMetadataV1.recordHashAt, (cid, recordType, r.recordIndex)
            ),
            e.recordHash
        );
        _word(
            d,
            1,
            abi.encodeWithSignature(
                "consumedArtistAuthorization(bytes32)", p.attestationRecordHash
            ),
            bytes32(uint256(1))
        );
    }

    function _lock(
        Dependencies memory d,
        uint256 cid,
        bytes32 subject,
        IStreamConservationRecordSelection.Selection memory s
    ) private view returns (IStreamConservationRecordSelection.IntentLock memory locked) {
        bytes memory raw = _read(
            d.targets[4],
            abi.encodeCall(IStreamConservationRecordSelection.intentLock, (cid, subject)),
            288,
            d.readGas
        );
        locked = abi.decode(raw, (IStreamConservationRecordSelection.IntentLock));
        if (keccak256(raw) != keccak256(abi.encode(locked))) {
            revert ConservationLock(s.record.recordHash);
        }
        if (locked.locked) {
            if (
                locked.locker == address(0) || locked.artistId != s.association.artistId
                    || locked.identityRecordHash != s.association.identityRecordHash
                    || locked.bindingHash != s.association.bindingHash
                    || locked.bindingGeneration != s.association.generation
                    || locked.recordHash != s.record.recordHash || locked.revision != s.revision
                    || locked.lockedAt < s.selectedAt || locked.lockedAt > block.timestamp
            ) revert ConservationLock(s.record.recordHash);
        } else {
            IStreamConservationRecordSelection.IntentLock memory empty;
            if (keccak256(raw) != keccak256(abi.encode(empty))) {
                revert ConservationLock(s.record.recordHash);
            }
        }
    }

    function _interviewCommitment(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 subject,
        IStreamConservationRecordSelection.Selection memory s
    ) private pure returns (bytes32) {
        // The exact parent payload commits the complete mandatory interview declaration. For
        // WAIVED there is no separately extracted Reference/subobject hash or interview record.
        bytes32 domain = s.interviewStatus == StreamConservationRecordTypes.InterviewStatus.PRESENT
            ? keccak256("6529STREAM_FINALITY_PRESENT_INTERVIEW_V1")
            : keccak256("6529STREAM_FINALITY_WAIVED_INTERVIEW_V1");
        return keccak256(
            abi.encode(
                domain,
                d.chainId,
                d.targets,
                scope,
                subject,
                s,
                StreamConservationDefinitions.INTERVIEW_SCHEMA_ID,
                StreamConservationDefinitions.INTERVIEW_PROFILE_HASH
            )
        );
    }

    function _bindings(Dependencies memory d) private view {
        if (
            block.chainid != d.chainId || d.readGas == 0 || d.selectionGas < d.readGas
                || d.selectionGas > type(uint256).max / 64
        ) revert ConservationConfiguration();
        for (uint256 i; i < 5; ++i) {
            if (d.targets[i].code.length == 0 || d.targets[i].codehash != d.codeHashes[i]) {
                revert ConservationDependency(d.targets[i]);
            }
        }
        bytes4[4] memory addressSelectors = [
            IStreamConservationRecordSelection.core.selector,
            IStreamConservationRecordSelection.metadata.selector,
            IStreamConservationRecordSelection.schemaRegistry.selector,
            IStreamConservationRecordSelection.chunkStore.selector
        ];
        bytes4[4] memory hashSelectors = [
            IStreamConservationRecordSelection.coreCodeHash.selector,
            IStreamConservationRecordSelection.metadataCodeHash.selector,
            IStreamConservationRecordSelection.schemaRegistryCodeHash.selector,
            IStreamConservationRecordSelection.chunkStoreCodeHash.selector
        ];
        for (uint256 i; i < 4; ++i) {
            _word(
                d,
                4,
                abi.encodeWithSelector(addressSelectors[i]),
                bytes32(uint256(uint160(d.targets[i])))
            );
            _word(d, 4, abi.encodeWithSelector(hashSelectors[i]), d.codeHashes[i]);
        }
        _word(
            d,
            4,
            abi.encodeCall(IStreamConservationRecordSelection.deploymentChainId, ()),
            bytes32(d.chainId)
        );
        _word(
            d,
            4,
            abi.encodeCall(
                IERC165.supportsInterface, (type(IStreamConservationRecordSelection).interfaceId)
            ),
            bytes32(uint256(1))
        );
    }

    function _word(Dependencies memory d, uint256 target, bytes memory input, bytes32 expected)
        private
        view
    {
        if (abi.decode(_read(d.targets[target], input, 32, d.readGas), (bytes32)) != expected) {
            revert ConservationDependency(d.targets[target]);
        }
    }

    function _read(address target, bytes memory input, uint256 size, uint256 cap)
        private
        view
        returns (bytes memory out)
    {
        out = new bytes(size);
        if (gasleft() <= cap + cap / 63 + 10000) revert ConservationRead(target, bytes4(input));
        bool ok;
        uint256 returned;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(input, 32), mload(input), add(out, 32), size)
            returned := returndatasize()
        }
        if (!ok || returned != size) revert ConservationRead(target, bytes4(input));
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/finality/IStreamFinalityCoordinatorInventory.sol";
import "../../interfaces/stream/finality/IStreamFinalityScopeMembership.sol";
import "../../interfaces/stream/core/IStreamCoreIdentity.sol";
import "../metadata/StreamMetadataSubjects.sol";

/// @notice Indexes every member's retained Core coordinator and first-occurrence source order.
/// @dev Permissionless transport of actual source facts; no caller token lists or readiness flags.
contract StreamFinalityCoordinatorInventory is IStreamFinalityCoordinatorInventory, IERC165 {
    address public immutable override core;
    address public immutable override scopeMembershipHost;
    bytes32 public immutable coreCodeHash;
    bytes32 public immutable scopeMembershipCodeHash;
    uint256 public immutable deploymentChainId;
    uint32 public immutable readGas;
    uint32 public immutable membershipGas;
    uint256 public constant MAX_BATCH = 256;

    struct State {
        StreamFinalityScope scope;
        StreamScopeMembershipFacts facts;
        Progress progress;
        Coordinator[] coordinators;
        mapping(address => uint256) positions;
    }
    mapping(bytes32 => State) private _plans;

    error InventoryConfiguration();
    error InventoryDependency(address target);
    error InventoryRead(address target, bytes4 selector);
    error InventoryParentGas(uint256 required);
    error InventoryUnknown(bytes32 planId);
    error InventoryStale(bytes32 planId);
    error InventoryIncomplete(bytes32 planId);
    error InventoryBatch(uint256 maximumTokens);
    error InventoryToken(uint256 tokenId);
    error InventoryIndex(uint256 index);

    constructor(address core_, address membership_, uint32 readGas_, uint32 membershipGas_) {
        if (
            core_.code.length == 0 || membership_.code.length == 0 || readGas_ < 50000
                || membershipGas_ < readGas_
        ) {
            revert InventoryConfiguration();
        }
        core = core_;
        scopeMembershipHost = membership_;
        coreCodeHash = core_.codehash;
        scopeMembershipCodeHash = membership_.codehash;
        deploymentChainId = block.chainid;
        readGas = readGas_;
        membershipGas = membershipGas_;
        if (
            abi.decode(
                    _read(
                        membership_,
                        abi.encodeCall(IStreamFinalityScopeMembership.core, ()),
                        32,
                        readGas_
                    ),
                    (address)
                ) != core_
        ) {
            revert InventoryConfiguration();
        }
        _supports(core_, 0x80ac58cd);
        _supports(membership_, type(IStreamFinalityScopeMembership).interfaceId);
    }

    function supportsInterface(bytes4 id) external pure override returns (bool) {
        return id == type(IERC165).interfaceId
            || id == type(IStreamFinalityCoordinatorInventory).interfaceId;
    }

    function beginInventory(StreamFinalityScope calldata scope)
        external
        override
        returns (bytes32 id)
    {
        _pins();
        StreamScopeMembershipFacts memory facts = _facts(scope);
        id = keccak256(
            abi.encode(
                keccak256("6529STREAM_COORDINATOR_INVENTORY_PLAN_V1"),
                deploymentChainId,
                address(this),
                core,
                coreCodeHash,
                scopeMembershipHost,
                scopeMembershipCodeHash,
                scope,
                facts
            )
        );
        State storage s = _plans[id];
        if (s.progress.exists) return id;
        s.scope = scope;
        s.facts = facts;
        s.progress.exists = true;
        s.progress.tokenCount = facts.tokenCount;
        s.progress.tokenChain =
            keccak256(abi.encode(keccak256("6529STREAM_COORDINATOR_TOKEN_CHAIN_V1"), id));
        s.progress.coordinatorChain =
            keccak256(abi.encode(keccak256("6529STREAM_COORDINATOR_SOURCE_CHAIN_V1"), id));
        emit CoordinatorInventoryBegun(id, facts.scopeSubject, facts.tokenCount);
        if (facts.tokenCount == 0) _complete(id, s);
    }

    function appendInventory(bytes32 id, uint256 maximumTokens) external override {
        _pins();
        State storage s = _known(id);
        if (maximumTokens == 0 || maximumTokens > MAX_BATCH || s.progress.complete) {
            revert InventoryBatch(maximumTokens);
        }
        _current(id, s);
        uint256 remaining = s.progress.tokenCount - s.progress.processedTokens;
        uint256 end =
            s.progress.processedTokens + (maximumTokens < remaining ? maximumTokens : remaining);
        for (uint256 i = s.progress.processedTokens; i < end; ++i) {
            _append(id, s, i);
        }
        s.progress.processedTokens = end;
        emit CoordinatorInventoryProgressed(id, end, s.coordinators.length);
        if (end == s.progress.tokenCount) _complete(id, s);
    }

    function inventoryProgress(bytes32 id) external view override returns (Progress memory) {
        return _plans[id].progress;
    }

    function inventoryScope(bytes32 id)
        external
        view
        override
        returns (StreamFinalityScope memory, StreamScopeMembershipFacts memory)
    {
        State storage s = _known(id);
        return (s.scope, s.facts);
    }

    function coordinatorAt(bytes32 id, uint256 index)
        public
        view
        override
        returns (Coordinator memory)
    {
        State storage s = _known(id);
        if (index >= s.coordinators.length) revert InventoryIndex(index);
        return s.coordinators[index];
    }

    function requireCompleteInventory(bytes32 id) external view override returns (Progress memory) {
        _pins();
        State storage s = _known(id);
        _current(id, s);
        if (
            !s.progress.complete || s.progress.processedTokens != s.facts.tokenCount
                || s.progress.commitment == 0
                || s.progress.coordinatorCount != s.coordinators.length
        ) revert InventoryIncomplete(id);
        return s.progress;
    }

    function requireCoordinator(bytes32 id, uint256 index)
        external
        view
        override
        returns (Coordinator memory c)
    {
        _pins();
        c = coordinatorAt(id, index);
        if (c.coordinator.code.length == 0 || c.coordinator.codehash != c.indexedCodeHash) {
            revert InventoryDependency(c.coordinator);
        }
    }

    function _append(bytes32 id, State storage s, uint256 index) private {
        uint256 tokenId = abi.decode(
            _read(
                scopeMembershipHost,
                abi.encodeCall(IStreamFinalityScopeMembership.scopeTokenAt, (s.scope, index)),
                32,
                membershipGas
            ),
            (uint256)
        );
        (uint256 exists, uint256 cid, uint256 serial, uint256 burned) = abi.decode(
            _read(
                core,
                abi.encodeCall(IStreamCoreIdentity.tokenCollectionIdentity, (tokenId)),
                128,
                readGas
            ),
            (uint256, uint256, uint256, uint256)
        );
        uint256 life = abi.decode(
            _read(core, abi.encodeCall(IStreamCoreIdentity.tokenLifecycle, (tokenId)), 32, readGas),
            (uint256)
        );
        if (
            tokenId == 0 || exists != 1 || cid != s.scope.collectionId || serial == 0
                || !((life == 2 && burned == 0) || (life == 3 && burned == 1))
        ) revert InventoryToken(tokenId);
        address original = abi.decode(
            _read(
                core, abi.encodeCall(IStreamCoreIdentity.coordinatorAtMint, (tokenId)), 32, readGas
            ),
            (address)
        );
        if (original.code.length == 0) revert InventoryDependency(original);
        uint256 position = s.positions[original];
        if (position == 0) {
            Coordinator memory c = Coordinator(original, original.codehash, index);
            position = s.coordinators.length + 1;
            s.positions[original] = position;
            s.coordinators.push(c);
            s.progress.coordinatorCount = position;
            s.progress.coordinatorChain = keccak256(
                abi.encode(
                    keccak256("6529STREAM_COORDINATOR_SOURCE_APPEND_V1"),
                    s.progress.coordinatorChain,
                    position - 1,
                    c
                )
            );
            emit OriginalCoordinatorIndexed(id, position - 1, original, c.indexedCodeHash, index);
        } else if (s.coordinators[position - 1].indexedCodeHash != original.codehash) {
            revert InventoryDependency(original);
        }
        s.progress.tokenChain = keccak256(
            abi.encode(
                keccak256("6529STREAM_COORDINATOR_TOKEN_APPEND_V1"),
                s.progress.tokenChain,
                index,
                tokenId,
                original,
                position - 1
            )
        );
    }

    function _complete(bytes32 id, State storage s) private {
        s.progress.complete = true;
        s.progress.commitment = keccak256(
            abi.encode(
                keccak256("6529STREAM_COORDINATOR_INVENTORY_COMPLETE_V1"),
                id,
                s.progress.tokenCount,
                s.coordinators.length,
                s.progress.tokenChain,
                s.progress.coordinatorChain
            )
        );
        emit CoordinatorInventoryCompleted(id, s.progress.commitment);
    }

    function _facts(StreamFinalityScope memory scope)
        private
        view
        returns (StreamScopeMembershipFacts memory facts)
    {
        bytes32 subject = StreamMetadataSubjects.scopeSubject(deploymentChainId, core, scope);
        bytes memory raw = _read(
            scopeMembershipHost,
            abi.encodeCall(IStreamFinalityScopeMembership.requireScopeMembership, (scope)),
            256,
            membershipGas
        );
        facts = abi.decode(raw, (StreamScopeMembershipFacts));
        if (
            facts.scopeSubject != subject || facts.membershipHash == 0
                || keccak256(raw) != keccak256(abi.encode(facts))
        ) {
            revert InventoryConfiguration();
        }
    }

    function _current(bytes32 id, State storage s) private view {
        if (keccak256(abi.encode(_facts(s.scope))) != keccak256(abi.encode(s.facts))) {
            revert InventoryStale(id);
        }
    }

    function _known(bytes32 id) private view returns (State storage s) {
        s = _plans[id];
        if (!s.progress.exists) revert InventoryUnknown(id);
    }

    function _pins() private view {
        if (block.chainid != deploymentChainId) revert InventoryConfiguration();
        if (core.code.length == 0 || core.codehash != coreCodeHash) {
            revert InventoryDependency(core);
        }
        if (
            scopeMembershipHost.code.length == 0
                || scopeMembershipHost.codehash != scopeMembershipCodeHash
        ) revert InventoryDependency(scopeMembershipHost);
    }

    function _supports(address target, bytes4 id) private view {
        if (
            abi.decode(
                        _read(target, abi.encodeCall(IERC165.supportsInterface, (id)), 32, readGas),
                        (uint256)
                    ) != 1
                || abi.decode(
                        _read(
                            target,
                            abi.encodeCall(IERC165.supportsInterface, (type(IERC165).interfaceId)),
                            32,
                            readGas
                        ),
                        (uint256)
                    ) != 1
                || abi.decode(
                        _read(
                            target,
                            abi.encodeCall(IERC165.supportsInterface, (bytes4(0xffffffff))),
                            32,
                            readGas
                        ),
                        (uint256)
                    ) != 0
        ) {
            revert InventoryDependency(target);
        }
    }

    function _read(address target, bytes memory input, uint256 size, uint256 cap)
        private
        view
        returns (bytes memory out)
    {
        out = new bytes(size);
        uint256 required = cap + cap / 63 + 10000;
        if (gasleft() <= required) revert InventoryParentGas(required);
        bool ok;
        uint256 returned;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(input, 32), mload(input), add(out, 32), size)
            returned := returndatasize()
        }
        if (!ok || returned != size) revert InventoryRead(target, bytes4(input));
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/finality/StreamFinalityCoordinatorPolicyTypes.sol";
import "../../interfaces/stream/finality/IStreamFinalityCoordinatorInventory.sol";
import "../../interfaces/stream/finality/IStreamFinalityScopeMembership.sol";
import "../../interfaces/stream/entropy/IStreamEntropyCoordinator.sol";
import "../../interfaces/stream/entropy/IStreamEntropyFinalityPolicy.sol";
import "../../interfaces/stream/modules/IStreamModule.sol";
import "./StreamFinalityRouterEvidence.sol";
import "../metadata/StreamMetadataSubjects.sol";

/// @notice Joins every original coordinator in the actual scope to its native policy.
/// @dev The consuming provider supplies constructor-fixed dependencies. No supplied source list,
/// current-pointer substitution, policy readiness cache or finality authority is introduced.
library StreamFinalityCoordinatorPolicyReads {
    struct Dependencies {
        // Core, generic Metadata, authoritative membership, original-coordinator inventory.
        address[4] targets;
        bytes32[4] codeHashes;
        uint256 chainId;
        uint32 readGas;
        uint32 inventoryGas;
    }

    error PolicyConfiguration();
    error PolicyDependency(address target);
    error PolicyRead(address target, bytes4 selector);
    error PolicyInventory(bytes32 planId);
    error PolicyUnavailable(address coordinator);

    /// @notice Validate a consuming host's fixed graph without requiring a particular scope.
    function validateDependencies(Dependencies memory d) public view {
        _bindings(d);
    }

    /// @notice Derive the exact current inventory plan from authoritative scope facts.
    function currentInventoryPlan(Dependencies memory d, StreamFinalityScope memory scope)
        public
        view
        returns (bytes32)
    {
        _bindings(d);
        bytes memory raw = _read(
            d.targets[2],
            abi.encodeCall(IStreamFinalityScopeMembership.requireScopeMembership, (scope)),
            256,
            d.inventoryGas
        );
        StreamScopeMembershipFacts memory f = abi.decode(raw, (StreamScopeMembershipFacts));
        if (
            keccak256(raw) != keccak256(abi.encode(f)) || f.membershipHash == 0
                || f.scopeSubject
                    != StreamMetadataSubjects.scopeSubject(d.chainId, d.targets[0], scope)
        ) {
            revert PolicyInventory(0);
        }
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_COORDINATOR_INVENTORY_PLAN_V1"),
                d.chainId,
                d.targets[3],
                d.targets[0],
                d.codeHashes[0],
                d.targets[2],
                d.codeHashes[2],
                scope,
                f
            )
        );
    }

    /// @notice Revalidate a native policy previously admitted into immutable host-owned evidence.
    /// @dev This does not admit the supplied source into an inventory. The consuming host must
    /// retain the complete scope/source association from requireCurrent; caller-supplied tuples
    /// alone convey no provenance or finality authority. Current membership is checked separately.
    function requireRetainedPolicy(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        IStreamFinalityCoordinatorInventory.Coordinator memory original
    ) public view returns (StreamFinalityCoordinatorPolicy memory) {
        _bindings(d);
        StreamMetadataSubjects.scopeSubject(d.chainId, d.targets[0], scope);
        return _policy(d, scope, original);
    }

    function requireCurrent(Dependencies memory d, StreamFinalityScope memory scope, bytes32 planId)
        public
        view
        returns (StreamFinalityCoordinatorPolicyEvidence memory e)
    {
        _bindings(d);
        IStreamFinalityCoordinatorInventory.Progress memory p = _inventory(d, scope, planId);
        e.planId = planId;
        e.inventoryHash = p.commitment;
        e.policyCount = p.coordinatorCount;
        e.allFrozen = p.coordinatorCount != 0;
        e.policies = new StreamFinalityCoordinatorPolicy[](p.coordinatorCount);
        e.policyChainHash = keccak256(
            abi.encode(
                keccak256("6529STREAM_ORIGINAL_COORDINATOR_POLICIES_V1"),
                d.chainId,
                d.targets,
                d.codeHashes,
                scope,
                planId,
                p.commitment,
                p.coordinatorCount
            )
        );
        bytes32 sources =
            keccak256(abi.encode(keccak256("6529STREAM_COORDINATOR_SOURCE_CHAIN_V1"), planId));
        for (uint256 i; i < p.coordinatorCount; ++i) {
            IStreamFinalityCoordinatorInventory.Coordinator memory original = abi.decode(
                _read(
                    d.targets[3],
                    abi.encodeCall(
                        IStreamFinalityCoordinatorInventory.requireCoordinator, (planId, i)
                    ),
                    96,
                    d.readGas
                ),
                (IStreamFinalityCoordinatorInventory.Coordinator)
            );
            if (
                original.firstTokenIndex >= p.tokenCount
                    || (i == 0
                            ? original.firstTokenIndex != 0
                            : original.firstTokenIndex <= e.policies[i - 1].firstTokenIndex)
            ) {
                revert PolicyInventory(planId);
            }
            sources = keccak256(
                abi.encode(
                    keccak256("6529STREAM_COORDINATOR_SOURCE_APPEND_V1"), sources, i, original
                )
            );
            StreamFinalityCoordinatorPolicy memory policy = _policy(d, scope, original);
            e.policies[i] = policy;
            e.allFrozen = e.allFrozen && policy.frozen;
            e.policyChainHash = keccak256(
                abi.encode(
                    keccak256("6529STREAM_ORIGINAL_COORDINATOR_POLICY_APPEND_V1"),
                    e.policyChainHash,
                    i,
                    policy
                )
            );
        }
        if (sources != p.coordinatorChain) revert PolicyInventory(planId);
    }

    function _inventory(Dependencies memory d, StreamFinalityScope memory scope, bytes32 id)
        private
        view
        returns (IStreamFinalityCoordinatorInventory.Progress memory p)
    {
        bytes memory raw = _read(
            d.targets[3],
            abi.encodeCall(IStreamFinalityCoordinatorInventory.requireCompleteInventory, (id)),
            256,
            d.inventoryGas
        );
        p = abi.decode(raw, (IStreamFinalityCoordinatorInventory.Progress));
        if (
            keccak256(raw) != keccak256(abi.encode(p)) || !p.exists || !p.complete
                || p.processedTokens != p.tokenCount || p.coordinatorCount > p.tokenCount
                || (p.tokenCount != 0 && p.coordinatorCount == 0)
        ) revert PolicyInventory(id);
        (StreamFinalityScope memory saved, StreamScopeMembershipFacts memory facts) = abi.decode(
            _read(
                d.targets[3],
                abi.encodeCall(IStreamFinalityCoordinatorInventory.inventoryScope, (id)),
                384,
                d.readGas
            ),
            (StreamFinalityScope, StreamScopeMembershipFacts)
        );
        if (
            keccak256(abi.encode(scope)) != keccak256(abi.encode(saved))
                || facts.scopeSubject
                    != StreamMetadataSubjects.scopeSubject(d.chainId, d.targets[0], scope)
                || facts.membershipHash == 0 || facts.tokenCount != p.tokenCount
                || id
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_COORDINATOR_INVENTORY_PLAN_V1"),
                            d.chainId,
                            d.targets[3],
                            d.targets[0],
                            d.codeHashes[0],
                            d.targets[2],
                            d.codeHashes[2],
                            scope,
                            facts
                        )
                    )
                || p.commitment
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_COORDINATOR_INVENTORY_COMPLETE_V1"),
                            id,
                            p.tokenCount,
                            p.coordinatorCount,
                            p.tokenChain,
                            p.coordinatorChain
                        )
                    )
        ) revert PolicyInventory(id);
        // The original inventory independently revalidates all eight current membership facts.
    }

    function _policy(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        IStreamFinalityCoordinatorInventory.Coordinator memory original
    ) private view returns (StreamFinalityCoordinatorPolicy memory e) {
        address target = original.coordinator;
        if (target.code.length == 0 || target.codehash != original.indexedCodeHash) {
            revert PolicyDependency(target);
        }
        _word(
            target,
            abi.encodeWithSignature("core()"),
            bytes32(uint256(uint160(d.targets[0]))),
            d.readGas
        );
        _supports(target, type(IStreamEntropyCoordinator).interfaceId, d.readGas);
        _supports(target, type(IStreamEntropyFinalityPolicy).interfaceId, d.readGas);
        _supports(target, type(IStreamModule).interfaceId, d.readGas);
        _word(
            target,
            abi.encodeCall(IStreamModule.streamModuleType, ()),
            keccak256("ENTROPY_COORDINATOR"),
            d.readGas
        );
        _word(
            target,
            abi.encodeCall(IStreamModule.streamModuleInterfaceId, ()),
            bytes32(type(IStreamEntropyCoordinator).interfaceId),
            d.readGas
        );
        _word(
            target,
            abi.encodeCall(IStreamModule.streamModuleCodeHash, ()),
            original.indexedCodeHash,
            d.readGas
        );
        e.coordinator = target;
        e.indexedCodeHash = original.indexedCodeHash;
        e.firstTokenIndex = original.firstTokenIndex;
        (e.moduleVersion, e.moduleManifestHash) =
            StreamFinalityRouterEvidence.moduleIdentity(target, d.readGas);
        e.moduleSchemaHash = abi.decode(
            _read(target, abi.encodeCall(IStreamModule.streamModuleSchemaHash, ()), 32, d.readGas),
            (bytes32)
        );
        e.deploymentManifestHash = abi.decode(
            _read(
                target,
                abi.encodeCall(IStreamModule.streamModuleDeploymentManifestHash, ()),
                32,
                d.readGas
            ),
            (bytes32)
        );
        bytes memory raw = _read(
            target,
            abi.encodeCall(IStreamEntropyFinalityPolicy.entropyPolicyFrozen, (scope.collectionId)),
            160,
            d.readGas
        );
        (e.frozen, e.policyHash, e.provider, e.epoch, e.salt) =
            abi.decode(raw, (bool, bytes32, address, uint32, bytes32));
        if (
            e.moduleSchemaHash == 0 || e.deploymentManifestHash == 0 || e.policyHash == 0
                || e.provider == address(0) || e.epoch == 0 || e.salt == 0
                || keccak256(raw)
                    != keccak256(abi.encode(e.frozen, e.policyHash, e.provider, e.epoch, e.salt))
        ) {
            revert PolicyUnavailable(target);
        }
        // Identical per-source preimage to the original single-coordinator evidence provider.
        e.componentDataHash = keccak256(
            abi.encode(
                keccak256("6529STREAM_ENTROPY_COMPONENT_EVIDENCE_V1"),
                d.chainId,
                d.targets[0],
                target,
                scope,
                e.policyHash,
                e.provider,
                e.epoch,
                e.salt
            )
        );
    }

    function _bindings(Dependencies memory d) private view {
        if (d.chainId != block.chainid || d.readGas < 50000 || d.inventoryGas < d.readGas) {
            revert PolicyConfiguration();
        }
        for (uint256 i; i < 4; ++i) {
            if (d.targets[i].code.length == 0 || d.targets[i].codehash != d.codeHashes[i]) {
                revert PolicyDependency(d.targets[i]);
            }
        }
        _supports(d.targets[0], 0x80ac58cd, d.readGas);
        _supports(d.targets[2], type(IStreamFinalityScopeMembership).interfaceId, d.readGas);
        _supports(d.targets[3], type(IStreamFinalityCoordinatorInventory).interfaceId, d.readGas);
        for (uint256 i = 1; i < 4; ++i) {
            _word(
                d.targets[i],
                abi.encodeWithSignature("core()"),
                bytes32(uint256(uint160(d.targets[0]))),
                d.readGas
            );
        }
        _word(
            d.targets[2],
            abi.encodeWithSignature("metadataHost()"),
            bytes32(uint256(uint160(d.targets[1]))),
            d.readGas
        );
        _word(
            d.targets[3],
            abi.encodeWithSignature("scopeMembershipHost()"),
            bytes32(uint256(uint160(d.targets[2]))),
            d.readGas
        );
        _word(
            d.targets[3],
            abi.encodeWithSignature("deploymentChainId()"),
            bytes32(d.chainId),
            d.readGas
        );
        _word(d.targets[3], abi.encodeWithSignature("coreCodeHash()"), d.codeHashes[0], d.readGas);
        _word(
            d.targets[3],
            abi.encodeWithSignature("scopeMembershipCodeHash()"),
            d.codeHashes[2],
            d.readGas
        );
    }

    function _supports(address target, bytes4 id, uint32 cap) private view {
        _word(target, abi.encodeCall(IERC165.supportsInterface, (id)), bytes32(uint256(1)), cap);
        _word(
            target,
            abi.encodeCall(IERC165.supportsInterface, (type(IERC165).interfaceId)),
            bytes32(uint256(1)),
            cap
        );
        _word(
            target, abi.encodeCall(IERC165.supportsInterface, (bytes4(0xffffffff))), bytes32(0), cap
        );
    }

    function _word(address target, bytes memory input, bytes32 expected, uint32 cap) private view {
        if (abi.decode(_read(target, input, 32, cap), (bytes32)) != expected) {
            revert PolicyDependency(target);
        }
    }

    function _read(address target, bytes memory input, uint256 size, uint32 cap)
        private
        view
        returns (bytes memory out)
    {
        out = new bytes(size);
        if (gasleft() <= uint256(cap) + uint256(cap) / 63 + 10000) {
            revert PolicyRead(target, bytes4(input));
        }
        bool ok;
        uint256 returned;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(input, 32), mload(input), add(out, 32), size)
            returned := returndatasize()
        }
        if (!ok || returned != size) revert PolicyRead(target, bytes4(input));
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/finality/StreamFinalityCoordinatorPolicyTypesV2.sol";
import "../../interfaces/stream/finality/IStreamFinalityCoordinatorInventory.sol";
import "../../interfaces/stream/finality/IStreamFinalityScopeMembership.sol";
import "../../interfaces/stream/entropy/IStreamEntropyCoordinator.sol";
import "../../interfaces/stream/entropy/IStreamEntropyFinalityPolicy.sol";
import "../../interfaces/stream/modules/IStreamModule.sol";
import "./StreamFinalityRouterEvidence.sol";
import {
    StreamEntropyRenderPolicyReads as Explicit
} from "../entropy/StreamEntropyRenderPolicyReads.sol";
import {
    StreamEntropyPolicyConsumerTypes as P,
    IStreamEntropyPolicyConsumerRead as ExplicitRead
} from "../../interfaces/stream/entropy/StreamEntropyPolicyConsumerTypes.sol";
import "../metadata/StreamMetadataSubjects.sol";

/// @notice Joins every original coordinator in the actual scope to its native policy.
/// @dev The consuming provider supplies constructor-fixed dependencies. No supplied source list,
/// current-pointer substitution, policy readiness cache or finality authority is introduced.
library StreamFinalityCoordinatorPolicyReadsV2 {
    struct Dependencies {
        // Core, generic Metadata, authoritative membership, original-coordinator inventory.
        address[4] targets;
        bytes32[4] codeHashes;
        uint256 chainId;
        uint32 readGas;
        uint32 inventoryGas;
    }

    error PolicyConfiguration();
    error PolicyDependency(address target);
    error PolicyRead(address target, bytes4 selector);
    error PolicyInventory(bytes32 planId);
    error PolicyUnavailable(address coordinator);

    /// @notice Validate a consuming host's fixed graph without requiring a particular scope.
    function validateDependencies(Dependencies memory d) public view {
        _bindings(d);
    }

    /// @notice Derive the exact current inventory plan from authoritative scope facts.
    function currentInventoryPlan(Dependencies memory d, StreamFinalityScope memory scope)
        public
        view
        returns (bytes32)
    {
        _bindings(d);
        bytes memory raw = _read(
            d.targets[2],
            abi.encodeCall(IStreamFinalityScopeMembership.requireScopeMembership, (scope)),
            256,
            d.inventoryGas
        );
        StreamScopeMembershipFacts memory f = abi.decode(raw, (StreamScopeMembershipFacts));
        if (
            keccak256(raw) != keccak256(abi.encode(f)) || f.membershipHash == 0
                || f.scopeSubject
                    != StreamMetadataSubjects.scopeSubject(d.chainId, d.targets[0], scope)
        ) {
            revert PolicyInventory(0);
        }
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_COORDINATOR_INVENTORY_PLAN_V1"),
                d.chainId,
                d.targets[3],
                d.targets[0],
                d.codeHashes[0],
                d.targets[2],
                d.codeHashes[2],
                scope,
                f
            )
        );
    }

    /// @notice Revalidate a native policy previously admitted into immutable host-owned evidence.
    /// @dev This does not admit the supplied source into an inventory. The consuming host must
    /// retain the complete scope/source association from requireCurrent; caller-supplied tuples
    /// alone convey no provenance or finality authority. Current membership is checked separately.
    function requireRetainedPolicy(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        IStreamFinalityCoordinatorInventory.Coordinator memory original
    ) public view returns (StreamFinalityCoordinatorPolicyV2 memory) {
        _bindings(d);
        StreamMetadataSubjects.scopeSubject(d.chainId, d.targets[0], scope);
        return _policy(d, scope, original);
    }

    function requireCurrent(Dependencies memory d, StreamFinalityScope memory scope, bytes32 planId)
        public
        view
        returns (StreamFinalityCoordinatorPolicyEvidenceV2 memory e)
    {
        _bindings(d);
        IStreamFinalityCoordinatorInventory.Progress memory p = _inventory(d, scope, planId);
        e.planId = planId;
        e.inventoryHash = p.commitment;
        e.policyCount = p.coordinatorCount;
        e.allFrozen = p.coordinatorCount != 0;
        e.policies = new StreamFinalityCoordinatorPolicyV2[](p.coordinatorCount);
        e.policyChainHash = keccak256(
            abi.encode(
                keccak256("6529STREAM_ORIGINAL_COORDINATOR_POLICIES_V2"),
                d.chainId,
                d.targets,
                d.codeHashes,
                scope,
                planId,
                p.commitment,
                p.coordinatorCount
            )
        );
        bytes32 sources =
            keccak256(abi.encode(keccak256("6529STREAM_COORDINATOR_SOURCE_CHAIN_V1"), planId));
        for (uint256 i; i < p.coordinatorCount; ++i) {
            IStreamFinalityCoordinatorInventory.Coordinator memory original = abi.decode(
                _read(
                    d.targets[3],
                    abi.encodeCall(
                        IStreamFinalityCoordinatorInventory.requireCoordinator, (planId, i)
                    ),
                    96,
                    d.readGas
                ),
                (IStreamFinalityCoordinatorInventory.Coordinator)
            );
            if (
                original.firstTokenIndex >= p.tokenCount
                    || (i == 0
                            ? original.firstTokenIndex != 0
                            : original.firstTokenIndex <= e.policies[i - 1].firstTokenIndex)
            ) {
                revert PolicyInventory(planId);
            }
            sources = keccak256(
                abi.encode(
                    keccak256("6529STREAM_COORDINATOR_SOURCE_APPEND_V1"), sources, i, original
                )
            );
            StreamFinalityCoordinatorPolicyV2 memory policy = _policy(d, scope, original);
            e.policies[i] = policy;
            e.allFrozen = e.allFrozen && policy.frozen;
            e.policyChainHash = keccak256(
                abi.encode(
                    keccak256("6529STREAM_ORIGINAL_COORDINATOR_POLICY_APPEND_V2"),
                    e.policyChainHash,
                    i,
                    policy
                )
            );
        }
        if (sources != p.coordinatorChain) revert PolicyInventory(planId);
    }

    function _inventory(Dependencies memory d, StreamFinalityScope memory scope, bytes32 id)
        private
        view
        returns (IStreamFinalityCoordinatorInventory.Progress memory p)
    {
        bytes memory raw = _read(
            d.targets[3],
            abi.encodeCall(IStreamFinalityCoordinatorInventory.requireCompleteInventory, (id)),
            256,
            d.inventoryGas
        );
        p = abi.decode(raw, (IStreamFinalityCoordinatorInventory.Progress));
        if (
            keccak256(raw) != keccak256(abi.encode(p)) || !p.exists || !p.complete
                || p.processedTokens != p.tokenCount || p.coordinatorCount > p.tokenCount
                || (p.tokenCount != 0 && p.coordinatorCount == 0)
        ) revert PolicyInventory(id);
        (StreamFinalityScope memory saved, StreamScopeMembershipFacts memory facts) = abi.decode(
            _read(
                d.targets[3],
                abi.encodeCall(IStreamFinalityCoordinatorInventory.inventoryScope, (id)),
                384,
                d.readGas
            ),
            (StreamFinalityScope, StreamScopeMembershipFacts)
        );
        if (
            keccak256(abi.encode(scope)) != keccak256(abi.encode(saved))
                || facts.scopeSubject
                    != StreamMetadataSubjects.scopeSubject(d.chainId, d.targets[0], scope)
                || facts.membershipHash == 0 || facts.tokenCount != p.tokenCount
                || id
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_COORDINATOR_INVENTORY_PLAN_V1"),
                            d.chainId,
                            d.targets[3],
                            d.targets[0],
                            d.codeHashes[0],
                            d.targets[2],
                            d.codeHashes[2],
                            scope,
                            facts
                        )
                    )
                || p.commitment
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_COORDINATOR_INVENTORY_COMPLETE_V1"),
                            id,
                            p.tokenCount,
                            p.coordinatorCount,
                            p.tokenChain,
                            p.coordinatorChain
                        )
                    )
        ) revert PolicyInventory(id);
        // The original inventory independently revalidates all eight current membership facts.
    }

    function _policy(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        IStreamFinalityCoordinatorInventory.Coordinator memory original
    ) private view returns (StreamFinalityCoordinatorPolicyV2 memory e) {
        address target = original.coordinator;
        if (target.code.length == 0 || target.codehash != original.indexedCodeHash) {
            revert PolicyDependency(target);
        }
        _word(
            target,
            abi.encodeWithSignature("core()"),
            bytes32(uint256(uint160(d.targets[0]))),
            d.readGas
        );
        _supports(target, type(IStreamEntropyCoordinator).interfaceId, d.readGas);
        _supports(target, type(IStreamEntropyFinalityPolicy).interfaceId, d.readGas);
        _supports(target, type(IStreamModule).interfaceId, d.readGas);
        _word(
            target,
            abi.encodeCall(IStreamModule.streamModuleType, ()),
            keccak256("ENTROPY_COORDINATOR"),
            d.readGas
        );
        _word(
            target,
            abi.encodeCall(IStreamModule.streamModuleInterfaceId, ()),
            bytes32(type(IStreamEntropyCoordinator).interfaceId),
            d.readGas
        );
        _word(
            target,
            abi.encodeCall(IStreamModule.streamModuleCodeHash, ()),
            original.indexedCodeHash,
            d.readGas
        );
        e.coordinator = target;
        e.indexedCodeHash = original.indexedCodeHash;
        e.firstTokenIndex = original.firstTokenIndex;
        (e.moduleVersion, e.moduleManifestHash) =
            StreamFinalityRouterEvidence.moduleIdentity(target, d.readGas);
        e.moduleSchemaHash = abi.decode(
            _read(target, abi.encodeCall(IStreamModule.streamModuleSchemaHash, ()), 32, d.readGas),
            (bytes32)
        );
        e.deploymentManifestHash = abi.decode(
            _read(
                target,
                abi.encodeCall(IStreamModule.streamModuleDeploymentManifestHash, ()),
                32,
                d.readGas
            ),
            (bytes32)
        );
        bool explicitCap = abi.decode(
            _read(target, abi.encodeCall(IERC165.supportsInterface, (P.CAPABILITY)), 32, d.readGas),
            (bool)
        );
        if (explicitCap) {
            bytes memory encoded = _read(
                target,
                abi.encodeCall(ExplicitRead.collectionEntropyPolicy, (scope.collectionId)),
                384,
                d.readGas
            );
            P.Policy memory policy = abi.decode(encoded, (P.Policy));
            if (keccak256(encoded) != keccak256(abi.encode(policy))) {
                revert PolicyUnavailable(target);
            }
            if (policy.explicitPolicy) {
                e.collectionPolicy =
                    Explicit.policy(target, d.targets[0], scope.collectionId, d.readGas);
                e.explicitPolicy = true;
                e.frozen = e.collectionPolicy.frozen;
                e.policyHash = e.collectionPolicy.policyHash;
                if (e.moduleSchemaHash == 0 || e.deploymentManifestHash == 0) {
                    revert PolicyUnavailable(target);
                }
                // Explicit V2 never borrows V1 provider/epoch/salt or its evidence identity.
                // The original five-word API must remain unavailable for this policy.
                bytes memory unavailable = _read(
                    target,
                    abi.encodeCall(
                        IStreamEntropyFinalityPolicy.entropyPolicyFrozen, (scope.collectionId)
                    ),
                    160,
                    d.readGas
                );
                if (keccak256(unavailable) != keccak256(new bytes(160))) {
                    revert PolicyUnavailable(target);
                }
                e.componentDataHash = keccak256(
                    abi.encode(
                        keccak256("6529STREAM_ENTROPY_COMPONENT_EVIDENCE_V2"),
                        d.chainId,
                        d.targets[0],
                        target,
                        scope,
                        e.collectionPolicy
                    )
                );
                return e;
            }
        }
        bytes memory raw = _read(
            target,
            abi.encodeCall(IStreamEntropyFinalityPolicy.entropyPolicyFrozen, (scope.collectionId)),
            160,
            d.readGas
        );
        (e.frozen, e.policyHash, e.provider, e.epoch, e.salt) =
            abi.decode(raw, (bool, bytes32, address, uint32, bytes32));
        if (
            e.moduleSchemaHash == 0 || e.deploymentManifestHash == 0 || e.policyHash == 0
                || e.provider == address(0) || e.epoch == 0 || e.salt == 0
                || keccak256(raw)
                    != keccak256(abi.encode(e.frozen, e.policyHash, e.provider, e.epoch, e.salt))
        ) {
            revert PolicyUnavailable(target);
        }
        // Identical per-source preimage to the original single-coordinator evidence provider.
        e.componentDataHash = keccak256(
            abi.encode(
                keccak256("6529STREAM_ENTROPY_COMPONENT_EVIDENCE_V1"),
                d.chainId,
                d.targets[0],
                target,
                scope,
                e.policyHash,
                e.provider,
                e.epoch,
                e.salt
            )
        );
    }

    function _bindings(Dependencies memory d) private view {
        if (d.chainId != block.chainid || d.readGas < 50000 || d.inventoryGas < d.readGas) {
            revert PolicyConfiguration();
        }
        for (uint256 i; i < 4; ++i) {
            if (d.targets[i].code.length == 0 || d.targets[i].codehash != d.codeHashes[i]) {
                revert PolicyDependency(d.targets[i]);
            }
        }
        _supports(d.targets[0], 0x80ac58cd, d.readGas);
        _supports(d.targets[2], type(IStreamFinalityScopeMembership).interfaceId, d.readGas);
        _supports(d.targets[3], type(IStreamFinalityCoordinatorInventory).interfaceId, d.readGas);
        for (uint256 i = 1; i < 4; ++i) {
            _word(
                d.targets[i],
                abi.encodeWithSignature("core()"),
                bytes32(uint256(uint160(d.targets[0]))),
                d.readGas
            );
        }
        _word(
            d.targets[2],
            abi.encodeWithSignature("metadataHost()"),
            bytes32(uint256(uint160(d.targets[1]))),
            d.readGas
        );
        _word(
            d.targets[3],
            abi.encodeWithSignature("scopeMembershipHost()"),
            bytes32(uint256(uint160(d.targets[2]))),
            d.readGas
        );
        _word(
            d.targets[3],
            abi.encodeWithSignature("deploymentChainId()"),
            bytes32(d.chainId),
            d.readGas
        );
        _word(d.targets[3], abi.encodeWithSignature("coreCodeHash()"), d.codeHashes[0], d.readGas);
        _word(
            d.targets[3],
            abi.encodeWithSignature("scopeMembershipCodeHash()"),
            d.codeHashes[2],
            d.readGas
        );
    }

    function _supports(address target, bytes4 id, uint32 cap) private view {
        _word(target, abi.encodeCall(IERC165.supportsInterface, (id)), bytes32(uint256(1)), cap);
        _word(
            target,
            abi.encodeCall(IERC165.supportsInterface, (type(IERC165).interfaceId)),
            bytes32(uint256(1)),
            cap
        );
        _word(
            target, abi.encodeCall(IERC165.supportsInterface, (bytes4(0xffffffff))), bytes32(0), cap
        );
    }

    function _word(address target, bytes memory input, bytes32 expected, uint32 cap) private view {
        if (abi.decode(_read(target, input, 32, cap), (bytes32)) != expected) {
            revert PolicyDependency(target);
        }
    }

    function _read(address target, bytes memory input, uint256 size, uint32 cap)
        private
        view
        returns (bytes memory out)
    {
        out = new bytes(size);
        if (gasleft() <= uint256(cap) + uint256(cap) / 63 + 10000) {
            revert PolicyRead(target, bytes4(input));
        }
        bool ok;
        uint256 returned;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(input, 32), mload(input), add(out, 32), size)
            returned := returndatasize()
        }
        if (!ok || returned != size) revert PolicyRead(target, bytes4(input));
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/finality/StreamFinalityDescriptionTypes.sol";
import "../../interfaces/stream/metadata/IStreamWorkRecordSelection.sol";
import "../../interfaces/stream/metadata/IStreamRightsRecordSelection.sol";
import "../../interfaces/stream/metadata/IStreamCollectionRecordReceipts.sol";
import "../metadata/StreamMetadataSubjects.sol";
import "../records/StreamWorkRecordDefinitions.sol";
import "../records/StreamRightsRecordDefinitions.sol";

/// @notice Joins current WORK and RIGHTS heads to their actual original metadata receipts.
/// @dev The consuming provider supplies constructor-fixed dependencies, including predicted late
///      selector addresses and exact expected runtime hashes. No caller-selected dependency graph,
///      mutable binding phase, collection-to-token inheritance or complete finality claim is added.
library StreamFinalityDescriptionReads {
    struct Dependencies {
        // Core, generic metadata, schemas, byte store, WORK selector, RIGHTS selector.
        address[6] targets;
        bytes32[6] codeHashes;
        uint256 chainId;
        uint256 readGas;
        uint256 selectionGas;
    }

    error DescriptionConfiguration();
    error DescriptionDependency(address target);
    error DescriptionRead(address target, bytes4 selector);
    error DescriptionSelection(address target, bytes32 recordHash);
    error DescriptionReceipt(bytes32 recordHash);

    function requireCurrent(Dependencies memory d, StreamFinalityScope memory scope)
        public
        view
        returns (StreamFinalityDescriptionEvidence memory e)
    {
        _bindings(d);
        e.scopeSubject = StreamMetadataSubjects.scopeSubject(d.chainId, d.targets[0], scope);
        IStreamWorkRecordSelection.Selection memory work =
            _work(d, scope.collectionId, e.scopeSubject);
        IStreamRightsRecordSelection.Selection memory rights =
            _rights(d, scope.collectionId, e.scopeSubject);
        e.workDescriptionRecordHash = work.recordHash;
        e.rightsStatementRecordHash = rights.recordHash;
        e.workPayloadHash = work.payloadHash;
        e.rightsPayloadHash = rights.payloadHash;
        e.workSelectionHash = work.selectionHash;
        e.rightsSelectionHash = rights.selectionHash;
        e.workRevision = work.revision;
        e.rightsRevision = rights.revision;
    }

    function _work(Dependencies memory d, uint256 cid, bytes32 subject)
        private
        view
        returns (IStreamWorkRecordSelection.Selection memory selected)
    {
        bytes memory raw = _read(
            d.targets[4],
            abi.encodeCall(IStreamWorkRecordSelection.currentWork, (cid, subject)),
            1056,
            d.readGas
        );
        selected = abi.decode(raw, (IStreamWorkRecordSelection.Selection));
        if (
            selected.recordHash == 0 || selected.payloadHash == 0 || selected.revision == 0
                || keccak256(raw) != keccak256(abi.encode(selected))
        ) revert DescriptionSelection(d.targets[4], selected.recordHash);
        bytes32 retained = selected.selectionHash;
        selected.selectionHash = 0;
        bytes32 computed = keccak256(
            abi.encode(
                keccak256("6529STREAM_WORK_SELECTION_V1"),
                d.chainId,
                d.targets[4],
                d.targets[0],
                d.targets[1],
                d.targets[2],
                d.targets[3],
                cid,
                subject,
                selected
            )
        );
        selected.selectionHash = retained;
        if (retained != computed) revert DescriptionSelection(d.targets[4], selected.recordHash);
        bytes memory current = _read(
            d.targets[4],
            abi.encodeCall(
                IStreamWorkRecordSelection.requireCurrent,
                (cid, subject, selected.recordHash, selected.revision)
            ),
            1056,
            d.selectionGas
        );
        if (keccak256(current) != keccak256(raw)) {
            revert DescriptionSelection(d.targets[4], selected.recordHash);
        }
        IStreamCollectionMetadataV1.RecordReceipt memory receipt = _receipt(d, selected.recordHash);
        if (
            receipt.collectionId != cid || receipt.recordIndex != selected.recordIndex
                || receipt.recorder != selected.recorder
                || receipt.authorizationClass != selected.recorderAuthorizationClass
                || receipt.recordChainHash != selected.recordChainHash
                || receipt.schemaDefinitionHash != StreamWorkRecordDefinitions.SCHEMA_HASH
                || receipt.canonicalizationDefinitionHash != StreamWorkRecordDefinitions.CANON_HASH
                || receipt.artistAuthorization != selected.artistPublication.attestationRecordHash
        ) revert DescriptionReceipt(selected.recordHash);
    }

    function _rights(Dependencies memory d, uint256 cid, bytes32 subject)
        private
        view
        returns (IStreamRightsRecordSelection.Selection memory selected)
    {
        bytes memory raw = _read(
            d.targets[5],
            abi.encodeCall(IStreamRightsRecordSelection.currentRights, (cid, subject)),
            448,
            d.readGas
        );
        selected = abi.decode(raw, (IStreamRightsRecordSelection.Selection));
        if (
            selected.recordHash == 0 || selected.payloadHash == 0 || selected.revision == 0
                || keccak256(raw) != keccak256(abi.encode(selected))
        ) revert DescriptionSelection(d.targets[5], selected.recordHash);
        bytes32 retained = selected.selectionHash;
        selected.selectionHash = 0;
        bytes32 computed = keccak256(
            abi.encode(
                keccak256("6529STREAM_RIGHTS_SELECTION_V1"),
                d.chainId,
                d.targets[5],
                d.targets[0],
                d.targets[1],
                d.targets[2],
                d.targets[3],
                cid,
                subject,
                selected
            )
        );
        selected.selectionHash = retained;
        if (retained != computed) revert DescriptionSelection(d.targets[5], selected.recordHash);
        bytes memory current = _read(
            d.targets[5],
            abi.encodeCall(
                IStreamRightsRecordSelection.requireCurrent,
                (cid, subject, selected.recordHash, selected.revision)
            ),
            448,
            d.selectionGas
        );
        if (keccak256(current) != keccak256(raw)) {
            revert DescriptionSelection(d.targets[5], selected.recordHash);
        }
        IStreamCollectionMetadataV1.RecordReceipt memory receipt = _receipt(d, selected.recordHash);
        if (
            receipt.collectionId != cid || receipt.recordIndex != selected.recordIndex
                || receipt.recorder != selected.recorder
                || receipt.authorizationClass != selected.recorderAuthorizationClass
                || receipt.schemaDefinitionHash != StreamRightsRecordDefinitions.SCHEMA_HASH
                || receipt.canonicalizationDefinitionHash
                    != StreamRightsRecordDefinitions.CANON_HASH
        ) revert DescriptionReceipt(selected.recordHash);
    }

    function _receipt(Dependencies memory d, bytes32 hash)
        private
        view
        returns (IStreamCollectionMetadataV1.RecordReceipt memory r)
    {
        bytes memory raw = _read(
            d.targets[1],
            abi.encodeCall(IStreamCollectionRecordReceipts.collectionRecordReceipt, (hash)),
            288,
            d.readGas
        );
        r = abi.decode(raw, (IStreamCollectionMetadataV1.RecordReceipt));
        if (keccak256(raw) != keccak256(abi.encode(r))) revert DescriptionReceipt(hash);
    }

    function _bindings(Dependencies memory d) private view {
        if (
            block.chainid != d.chainId || d.readGas == 0 || d.selectionGas < d.readGas
                || d.selectionGas > type(uint256).max / 64
        ) {
            revert DescriptionConfiguration();
        }
        for (uint256 i; i < 6; ++i) {
            if (d.targets[i].code.length == 0 || d.targets[i].codehash != d.codeHashes[i]) {
                revert DescriptionDependency(d.targets[i]);
            }
        }
        bytes4[4] memory addressSelectors = [
            IStreamWorkRecordSelection.core.selector,
            IStreamWorkRecordSelection.metadata.selector,
            IStreamWorkRecordSelection.schemaRegistry.selector,
            IStreamWorkRecordSelection.chunkStore.selector
        ];
        bytes4[4] memory hashSelectors = [
            IStreamWorkRecordSelection.coreCodeHash.selector,
            IStreamWorkRecordSelection.metadataCodeHash.selector,
            IStreamWorkRecordSelection.schemaRegistryCodeHash.selector,
            IStreamWorkRecordSelection.chunkStoreCodeHash.selector
        ];
        for (uint256 i = 4; i < 6; ++i) {
            for (uint256 j; j < 4; ++j) {
                _word(
                    d,
                    i,
                    abi.encodeWithSelector(addressSelectors[j]),
                    bytes32(uint256(uint160(d.targets[j])))
                );
                _word(d, i, abi.encodeWithSelector(hashSelectors[j]), d.codeHashes[j]);
            }
            _word(
                d,
                i,
                abi.encodeCall(IStreamWorkRecordSelection.deploymentChainId, ()),
                bytes32(d.chainId)
            );
            _word(
                d,
                i,
                abi.encodeCall(
                    IERC165.supportsInterface,
                    (i == 4
                            ? type(IStreamWorkRecordSelection).interfaceId
                            : type(IStreamRightsRecordSelection).interfaceId)
                ),
                bytes32(uint256(1))
            );
        }
        // requireCurrent on each original selector verifies its reciprocal metadata/artist graph,
        // selected Core host and complete active definition bytes. Do not replay the old grants.
    }

    function _word(Dependencies memory d, uint256 target, bytes memory input, bytes32 expected)
        private
        view
    {
        if (abi.decode(_read(d.targets[target], input, 32, d.readGas), (bytes32)) != expected) {
            revert DescriptionDependency(d.targets[target]);
        }
    }

    function _read(address target, bytes memory input, uint256 size, uint256 cap)
        private
        view
        returns (bytes memory out)
    {
        out = new bytes(size);
        if (gasleft() <= cap + cap / 63 + 10000) revert DescriptionRead(target, bytes4(input));
        bool ok;
        uint256 returned;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(input, 32), mload(input), add(out, 32), size)
            returned := returndatasize()
        }
        if (!ok || returned != size) revert DescriptionRead(target, bytes4(input));
    }
}

