        bytes32 coreFactsHash,
        bytes32 componentsHash,
        StreamFinalityManifestRef calldata manifest
    ) public view returns (bytes32) {
        if (scope.scopeType == StreamFinalityScopeType.COLLECTION) {
            return keccak256(
                bytes.concat(
                    abi.encode(
                        StreamFinalityDomains.STREAM_FINALITY_V1,
                        block.chainid,
                        core_,
                        scope.collectionId,
                        coreFactsHash
                    ),
                    abi.encode(
                        componentsHash,
                        manifest.uriHash,
                        manifest.contentHash,
                        manifest.schemaId,
                        manifest.canonicalizationHash
                    )
                )
            );
        }
        return keccak256(
            bytes.concat(
                abi.encode(
                    StreamFinalityDomains.STREAM_SCOPED_FINALITY_V1,
                    block.chainid,
                    core_,
                    uint8(scope.scopeType),
                    scope.collectionId,
                    scope.tokenId,
                    scope.scopeId
                ),
                abi.encode(
                    coreFactsHash,
                    componentsHash,
                    manifest.uriHash,
                    manifest.contentHash,
                    manifest.schemaId,
                    manifest.canonicalizationHash
                )
