pragma solidity ^0.8.19;

import "./StreamFinalityNativeProviderReads.sol";
import "./StreamFinalityNativeSanctionProfile.sol";
import "../../interfaces/stream/finality/IStreamFinalitySanctionReview.sol";
import "../../interfaces/stream/preservation/IStreamExternalArtifactCoverage.sol";
import "../../interfaces/stream/preservation/StreamExternalArtifactTypes.sol";
import "../records/StreamReferenceRenderDefinitions.sol";
import "../records/StreamReferenceModeDefinitions.sol";
import "../../interfaces/stream/preservation/IStreamReferenceModePublication.sol";

/// @notice Ordered original PNG content hashes for the admitted native finality statement.
/// @dev The provider first validates all current inputs and the exact registered manifest.
/// This projection is not a separate readiness gate and accepts no caller-selected object list.
library StreamFinalityNativeSanctionReview {
    error NativeReviewSource();
    error NativeReviewRead(address target);
    uint256 internal constant MAX_PUBLICATION_BYTES = 1048576;

    function review(
        StreamFinalityNativeProviderReads.Config memory c,
        StreamFinalityInputManifestTypes.Statement memory s
    ) public view returns (IStreamFinalitySanctionReview.ReviewFacts memory result) {
        if (
            c.chainId != block.chainid || s.scope.scopeType != StreamFinalityScopeType.COLLECTION
                || s.scope.collectionId == 0 || s.scope.tokenId != 0 || s.scope.scopeId != 0
                || s.contentRoot == 0 || s.inputs.referenceRenderRecordHash == 0
                || s.inputs.snapshotRecordHash == 0 || s.referenceRenderManifestHash == 0
        ) {
            revert NativeReviewSource();
        }
        _pin(c, 2);
        _pin(c, 9);
        _pin(c, 11);
        _pin(c, 21);
        bytes32 artistId = _artist(c, s.scope.collectionId);
        (StreamReferenceRenderTypes.Publication memory publication, bool exact) = _publication(c, s);
        uint256 count = publication.captures.length;
        if (count == 0 || count > 16) revert NativeReviewSource();
        if (count > 1) {
            StreamFinalityNativeSanctionProfile.requireCurrent(
                c.targets[4], c.codeHashes[4], c.targets[5], c.codeHashes[5], c.readGas
            );
        }
        result.schemaVersion = 1;
        result.profile = count == 1 ? 1 : 2;
        result.contentRoot = s.contentRoot;
        // This native ONCHAIN profile has no separate off-chain media object list.
        result.mediaContentHashes = new bytes32[](0);
        result.referenceRenderContentHashes = new bytes32[](count);
        for (uint256 i; i < count; ++i) {
            result.referenceRenderContentHashes[i] =
                _capture(c, artistId, publication.captures[i], exact);
        }
    }

    function _artist(StreamFinalityNativeProviderReads.Config memory c, uint256 cid)
        private
        view
        returns (bytes32)
    {
        bytes memory raw = StreamFinalityBoundedReads.read(
            c.targets[2],
            abi.encodeCall(IStreamMetadataServingFacts.artistPresentation, (cid)),
            384,
            c.readGas
        );
        IStreamMetadataServingFacts.ArtistPresentation memory p =
            abi.decode(raw, (IStreamMetadataServingFacts.ArtistPresentation));
        if (
            keccak256(raw) != keccak256(abi.encode(p)) || !p.locked || p.artistId == 0
                || p.registry != c.targets[11] || p.registryCodeHash != c.codeHashes[11]
                || p.bindingGeneration == 0 || p.bindingHash == 0 || p.identityRecordHash == 0
                || p.acceptanceRecordHash == 0 || p.snapshotHash == 0
        ) revert NativeReviewSource();
        return p.artistId;
    }

    function _publication(
        StreamFinalityNativeProviderReads.Config memory c,
        StreamFinalityInputManifestTypes.Statement memory s
    ) private view returns (StreamReferenceRenderTypes.Publication memory p, bool exact) {
        bytes memory raw = _dynamicRead(
            c.targets[9],
            abi.encodeCall(
                IStreamReferenceRenderPublication.referenceRecord,
                (s.inputs.referenceRenderRecordHash)
            ),
            c.sourceGas
        );
        StreamReferenceRenderTypes.Receipt memory receipt;
        (p, receipt) = abi.decode(
            raw, (StreamReferenceRenderTypes.Publication, StreamReferenceRenderTypes.Receipt)
        );
        if (
            keccak256(raw) != keccak256(abi.encode(p, receipt))
                || receipt.recordHash != s.inputs.referenceRenderRecordHash
                || receipt.collectionId != s.scope.collectionId
                || receipt.snapshotRecordHash != s.inputs.snapshotRecordHash
                || receipt.payloadHash != s.referenceRenderManifestHash || receipt.payloadBytes == 0
                || receipt.sourcesHash == 0 || receipt.snapshotRevision == 0
                || p.collectionId != receipt.collectionId || p.referenceId != receipt.referenceId
                || p.snapshotRecordHash != receipt.snapshotRecordHash
                || p.snapshotRevision != receipt.snapshotRevision
                || p.expectedSourcesHash != receipt.sourcesHash
        ) {
            revert NativeReviewSource();
        }
        exact = receipt.profileHash == StreamReferenceRenderDefinitions.PROFILE_HASH;
        if (!exact) {
            if (
                receipt.profileHash != StreamReferenceModeDefinitions.PROFILE_HASH
                    || receipt.schemaHash != StreamReferenceModeDefinitions.SCHEMA_HASH
                    || receipt.canonicalizationHash != StreamReferenceModeDefinitions.CANON_HASH
            ) revert NativeReviewSource();
            // Full mode validation is part of the provider's original current-input admission.
            bytes memory modeRaw = StreamFinalityBoundedReads.read(
                c.targets[9],
                abi.encodeCall(IStreamReferenceModePublication.referenceMode, (receipt.recordHash)),
                64,
                c.readGas
            );
            (StreamReferenceModeTypes.Mode mode, bytes32 evidenceHash) =
                abi.decode(modeRaw, (StreamReferenceModeTypes.Mode, bytes32));
            if (
                keccak256(modeRaw) != keccak256(abi.encode(mode, evidenceHash)) || evidenceHash == 0
                    || (mode != StreamReferenceModeTypes.Mode.PERCEPTUAL_TOLERANCE
                        && mode != StreamReferenceModeTypes.Mode.CURATED_EQUIVALENCE)
            ) revert NativeReviewSource();
        }
        raw = StreamFinalityBoundedReads.read(
            c.targets[9],
            abi.encodeCall(
                IStreamReferenceRenderPublication.currentReference, (s.scope.collectionId)
            ),
            640,
            c.readGas
        );
        if (keccak256(raw) != keccak256(abi.encode(receipt))) revert NativeReviewSource();
    }

    function _capture(
        StreamFinalityNativeProviderReads.Config memory c,
        bytes32 artistId,
        StreamReferenceRenderTypes.Capture memory capture,
        bool exact
    ) private view returns (bytes32) {
        bytes memory raw = StreamFinalityBoundedReads.read(
            c.targets[21],
            abi.encodeCall(IStreamExternalArtifactCoverage.objectIdentity, (capture.objectHash)),
            320,
            c.readGas
        );
        StreamExternalArtifactTypes.ObjectIdentity memory o =
            abi.decode(raw, (StreamExternalArtifactTypes.ObjectIdentity));
        if (
            keccak256(raw) != keccak256(abi.encode(o)) || o.artistId != artistId
                || o.contentHash == 0 || o.sha256Digest == 0 || capture.repeatCaptureSha256[0] == 0
                || capture.repeatCaptureSha256[1] == 0
                || (exact && capture.repeatCaptureSha256[0] != capture.repeatCaptureSha256[1])
                || o.sha256Digest != capture.repeatCaptureSha256[0] || o.arweaveDataRoot == 0
                || o.byteSize == 0 || capture.coverageHash == 0
                || o.canonicalizationId != keccak256("RAW_BYTES")
                || o.schemaId != StreamReferenceRenderDefinitions.PNG_SCHEMA_ID
                || o.formatId != keccak256("IANA:image/png")
                || o.formatCatalogId != StreamReferenceRenderDefinitions.FORMAT_CATALOG_ID
                || o.formatCatalogHash != StreamReferenceRenderDefinitions.FORMAT_CATALOG_HASH
                || capture.objectHash
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_EXTERNAL_OBJECT_V1"),
                            c.chainId,
                            c.targets[21],
                            c.targets[0],
                            o
                        )
                    )
        ) revert NativeReviewSource();
        return o.contentHash;
    }

    function _pin(StreamFinalityNativeProviderReads.Config memory c, uint256 index) private view {
        if (c.targets[index].code.length == 0 || c.targets[index].codehash != c.codeHashes[index]) {
            revert NativeReviewRead(c.targets[index]);
        }
    }

    function _dynamicRead(address target, bytes memory input, uint256 cap)
        private
        view
        returns (bytes memory result)
    {
        // Inspect bounded returndata before allocating/copying it. No unbounded return bomb.
        uint256 available = gasleft();
        if (available <= 100000 || cap == 0) revert NativeReviewRead(target);
        uint256 forwarded = available - 100000;
        if (cap < forwarded) forwarded = cap;
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(forwarded, target, add(input, 32), mload(input), 0, 0)
            size := returndatasize()
        }
        if (!ok || size == 0 || size > MAX_PUBLICATION_BYTES) revert NativeReviewRead(target);
        result = new bytes(size);
        assembly ("memory-safe") { returndatacopy(add(result, 32), 0, size) }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamFinalityPolicyInputManifestSchemasV2.sol";
import "./StreamFinalityRouterEvidence.sol";
import {
    StreamPolicySnapshotDefinitionsV2 as SnapshotDefinitions
} from "../records/StreamPolicySnapshotDefinitionsV2.sol";
import {
    StreamPolicyReferenceDefinitionsV2 as ReferenceDefinitions
} from "../records/StreamPolicyReferenceDefinitionsV2.sol";
import "../../interfaces/stream/finality/StreamFinalityPolicyInputManifestTypesV2.sol";
import "../../interfaces/stream/finality/IStreamArtworkFinalityRegistry.sol";
import "../../interfaces/stream/metadata/IStreamSchemaDocumentFacts.sol";
import "../metadata/StreamSchemaDocumentStore.sol";

/// @notice Exact registered interpretation and two-store admission of an independent manifest.
/// @dev The consuming provider supplies fixed dependencies and independently derived current
/// facts. No caller-selected input list, new latest pointer, publication authority or readiness
/// interface is introduced. This joins bytes; actual source/coverage/authority validation stays
/// mandatory in the provider, while sanction and manifest archival evidence are separate joins.
library StreamFinalityPolicyInputManifestReadsV2 {
    struct Dependencies {
        // Core, actual generic Metadata, schemas, schema Store, original Finality Registry.
        address[5] targets;
        bytes32[5] codeHashes;
        uint256 chainId;
        uint256 readGas;
    }
    error InvalidInputManifest();
    error InputManifestDependency(address target);
    error InputManifestDefinition(bytes32 id);
    error InputManifestBytes(bytes32 hash);

    function encode(
        Dependencies memory d,
        StreamFinalityPolicyInputManifestTypesV2.Statement memory s
    ) public pure returns (bytes memory payload) {
        _shape(s);
        if (
            d.chainId == 0 || d.targets[0] == address(0) || d.targets[1] == address(0)
                || d.targets[4] == address(0)
        ) revert InvalidInputManifest();
        payload = abi.encode(
            StreamFinalityPolicyInputManifestSchemasV2.SCHEMA_ID,
            StreamFinalityPolicyInputManifestSchemasV2.CANON_ID,
            d.chainId,
            d.targets[0],
            d.targets[1],
            d.targets[4],
            s
        );
        if (payload.length > 8192) revert InvalidInputManifest();
    }

    function scopeInputsHash(
        Dependencies memory d,
        StreamFinalityPolicyInputManifestTypesV2.Statement memory s
    ) public pure returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_FINALITY_SCOPE_INPUTS_V1"),
                d.chainId,
                d.targets[0],
                d.targets[1],
                s.scope,
                s.inputs
            )
        );
    }

    function requireCurrent(
        Dependencies memory d,
        StreamFinalityPolicyInputManifestTypesV2.Statement memory expected,
        bytes32 contentHash
    ) public view returns (bytes32 schemaId, bytes32 canonicalizationId) {
        _bindings(d);
        bytes memory payload = encode(d, expected);
        if (contentHash == 0 || keccak256(payload) != contentHash) {
            revert InputManifestBytes(contentHash);
        }
        schemaId = StreamFinalityPolicyInputManifestSchemasV2.SCHEMA_ID;
        canonicalizationId = StreamFinalityPolicyInputManifestSchemasV2.CANON_ID;
        _definition(d, schemaId, IStreamSchemaRegistry.DocumentKind.SCHEMA);
        _definition(d, canonicalizationId, IStreamSchemaRegistry.DocumentKind.CANONICALIZATION);
        _same(
            d.targets[3],
            abi.encodeCall(StreamSchemaDocumentStore.readChunk, (contentHash)),
            payload,
            contentHash,
            d.readGas
        );
        _same(
            d.targets[4],
            abi.encodeCall(IStreamArtworkFinalityRegistry.finalityManifestBytes, (contentHash)),
            payload,
            contentHash,
            d.readGas
        );
    }

    function _same(
        address target,
        bytes memory input,
        bytes memory expected,
        bytes32 hash,
        uint256 cap
    ) private view {
        bytes memory raw = StreamFinalityRouterEvidence.dynamicRead(target, input, 8256, cap);
        bytes memory actual = abi.decode(raw, (bytes));
        if (
            keccak256(raw) != keccak256(abi.encode(actual)) || actual.length != expected.length
                || keccak256(actual) != hash
        ) revert InputManifestBytes(hash);
        // Both whole-byte digests must match the independently encoded expected document.
        if (keccak256(expected) != hash) revert InputManifestBytes(hash);
    }

    function _bindings(Dependencies memory d) private view {
        if (d.chainId != block.chainid || d.readGas < 50000 || d.readGas > type(uint256).max / 64) {
            revert InvalidInputManifest();
        }
        for (uint256 i; i < 5; ++i) {
            if (d.targets[i].code.length == 0 || d.targets[i].codehash != d.codeHashes[i]) {
                revert InputManifestDependency(d.targets[i]);
            }
        }
        _address(d, 1, "core()", 0);
        _address(d, 1, "schemaRegistry()", 2);
        _address(d, 2, "chunkStore()", 3);
        _address(d, 4, "coreReads()", 0);
        _address(d, 4, "metadataReads()", 1);
    }

    function _address(Dependencies memory d, uint256 source, string memory signature, uint256 dest)
        private
        view
    {
        bytes memory raw = StreamFinalityRouterEvidence.read(
            d.targets[source], abi.encodeWithSignature(signature), 32, d.readGas
        );
        if (abi.decode(raw, (uint256)) != uint256(uint160(d.targets[dest]))) {
            revert InputManifestDependency(d.targets[source]);
        }
    }

    function _definition(Dependencies memory d, bytes32 id, IStreamSchemaRegistry.DocumentKind kind)
        private
        view
    {
        bytes memory expected = StreamFinalityPolicyInputManifestSchemasV2.document(id);
        bytes memory raw = StreamFinalityRouterEvidence.read(
            d.targets[2],
            abi.encodeCall(IStreamSchemaDocumentFacts.documentFacts, (id)),
            288,
            d.readGas
        );
        IStreamSchemaDocumentFacts.DocumentFacts memory f =
            abi.decode(raw, (IStreamSchemaDocumentFacts.DocumentFacts));
        if (
            keccak256(raw) != keccak256(abi.encode(f)) || !f.exists || f.kind != kind
                || f.status != IStreamSchemaRegistry.DocumentStatus.ACTIVE
                || f.contentHash != keccak256(expected) || f.totalBytes != expected.length
                || f.canonicalizationId != keccak256("RAW_BYTES") || f.chunkCount != 1
                || f.declarationHash == 0
        ) revert InputManifestDefinition(id);
        _same(
            d.targets[2],
            abi.encodeCall(IStreamSchemaRegistry.documentBytes, (id)),
            expected,
            keccak256(expected),
            d.readGas
        );
    }

    function _shape(StreamFinalityPolicyInputManifestTypesV2.Statement memory s) private pure {
        if (
            s.scope.scopeType != StreamFinalityScopeType.COLLECTION || s.scope.collectionId == 0
                || s.scope.tokenId != 0 || s.scope.scopeId != 0 || s.coreFactsHash == 0
                || s.contentRoot == 0 || s.leafCount == 0 || s.contentRootSchemaId == 0
                || s.snapshotManifestHash == 0 || s.referenceRenderManifestHash == 0
                || s.entropy.sourceSet == address(0) || s.entropy.sourceSetCodeHash == 0
                || s.entropy.sourceSetProfile
                    != keccak256("6529STREAM_ENTROPY_POLICY_SOURCE_SET_V2")
                || s.entropy.inventoryPlan == 0 || s.entropy.inventoryHash == 0
                || s.entropy.policyChainHash == 0 || s.entropy.policyCount == 0
                || s.entropy.snapshotProfileHash != SnapshotDefinitions.PROFILE_HASH
                || s.entropy.referenceProfileHash != ReferenceDefinitions.PROFILE_HASH
                || s.postFreezePolicy != 1 || s.sanctionPolicy != 1
                || s.nonSanctionComponents.length != 9
        ) revert InvalidInputManifest();
        StreamFinalityScopeInputs memory e = s.inputs;
        if (
            e.rootRecordHash == 0 || e.snapshotRecordHash == 0 || e.referenceRenderRecordHash == 0
                || e.interviewEvidenceHash == 0 || e.rightsStatementRecordHash == 0
                || e.workDescriptionRecordHash == 0 || e.renderCriticalEvidenceHash == 0
                || e.bundleCoverageHash == 0
                || ((e.intentRecordHash == 0) == (e.intentWaiverRecordHash == 0))
        ) {
            revert InvalidInputManifest();
        }
        uint256 seen;
        for (uint256 i; i < 9; ++i) {
            StreamFinalityComponentExpectation memory c = s.nonSanctionComponents[i];
            if (
                c.component == address(0) || c.codeHash == 0 || c.interfaceId == 0
                    || c.moduleVersion == 0 || c.manifestHash == 0 || c.dataHash == 0
                    || (i != 0 && c.componentType <= s.nonSanctionComponents[i - 1].componentType)
            ) {
                revert InvalidInputManifest();
            }
            uint256 bit = _familyBit(c.componentType);
            if ((seen & bit) != 0) revert InvalidInputManifest();
            seen |= bit;
        }
        if (seen != 511) revert InvalidInputManifest();
    }

    function _familyBit(bytes32 id) private pure returns (uint256) {
        if (id == StreamFinalityDomains.COMPONENT_METADATA_ROUTER) return 1;
        if (id == StreamFinalityDomains.COMPONENT_RENDERER) return 2;
        if (id == StreamFinalityDomains.COMPONENT_RENDER_CONTEXT) return 4;
        if (id == StreamFinalityDomains.COMPONENT_MEDIA_MANIFEST) return 8;
        if (id == StreamFinalityDomains.COMPONENT_SCRIPT_SOURCE) return 16;
        if (id == StreamFinalityDomains.COMPONENT_DEPENDENCY_SOURCE) return 32;
        if (id == StreamFinalityDomains.COMPONENT_COLLECTION_METADATA) return 64;
        if (id == StreamFinalityDomains.COMPONENT_ENTROPY_COORDINATOR) return 128;
        if (id == StreamFinalityDomains.COMPONENT_REFERENCE_RENDER) return 256;
        revert InvalidInputManifest();
    }
}

