pragma solidity ^0.8.19;
import {
    StreamScopedReferenceTypes as T
} from "../../interfaces/stream/preservation/StreamScopedReferenceTypes.sol";
import {
    StreamReferenceRenderTypes as R
} from "../../interfaces/stream/preservation/StreamReferenceRenderTypes.sol";
import {
    IStreamScopedReferencePublication as P
} from "../../interfaces/stream/preservation/IStreamScopedReferencePublication.sol";
import {
    StreamScopedReferenceDefinitions as D
} from "../records/StreamScopedReferenceDefinitions.sol";
import { StreamMetadataSubjects } from "../metadata/StreamMetadataSubjects.sol";
import { StreamFinalityRouterEvidence as Reads } from "./StreamFinalityRouterEvidence.sol";
import {
    StreamFinalityScope,
    StreamFinalityScopeType,
    StreamFinalityDomains,
    StreamFinalityComponentState,
    IStreamArtworkScopedFinalityComponent
} from "../../interfaces/stream/finality/IStreamArtworkFinalityComponents.sol";

/// @notice Exact scoped original reference records and current terminal lock for fixed providers.
/// @dev Caller supplies its constructor-pinned dependency configuration, never a per-request host.
/// These observations do not replace the complete scoped render-critical inventory or archive.
library StreamFinalityScopedReferenceReads {
    struct Dependencies {
        // Core, selected Metadata, Router, scoped snapshots, scoped reference publisher.
        address[5] targets;
        bytes32[5] codeHashes;
        uint256 chainId;
        uint256 readGas;
        uint256 sourceGas;
    }
    error InvalidScopedReferenceEvidence();
    error ScopedReferenceDependency(address source);

    function requireBindings(Dependencies memory d) public view {
        if (d.chainId != block.chainid || d.readGas < 50000 || d.sourceGas < d.readGas) {
            revert InvalidScopedReferenceEvidence();
        }
        for (uint256 i; i < 5; ++i) {
            if (d.targets[i].code.length == 0 || d.targets[i].codehash != d.codeHashes[i]) {
                revert ScopedReferenceDependency(d.targets[i]);
            }
        }
        bytes memory raw =
            Reads.read(d.targets[4], abi.encodeCall(P.dependencies, ()), 608, d.readGas);
        T.Dependencies memory source = abi.decode(raw, (T.Dependencies));
        _canonical(d.targets[4], raw, abi.encode(source));
        if (source.chainId != d.chainId) revert InvalidScopedReferenceEvidence();
        uint256[4] memory indexes = [uint256(0), 1, 4, 5];
        // Publisher runtime is already pinned above; its first four shared roles match exactly.
        for (uint256 i; i < 4; ++i) {
            if (
                source.targets[indexes[i]] != d.targets[i]
                    || source.codeHashes[indexes[i]] != d.codeHashes[i]
            ) {
                revert ScopedReferenceDependency(d.targets[4]);
            }
        }
    }

    function original(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 hash,
        uint64 revision
    ) public view returns (T.Publication memory p, T.Receipt memory receipt) {
        requireBindings(d);
        bytes32 subject = _subject(d, scope);
        bytes memory raw = Reads.dynamicRead(
            d.targets[4], abi.encodeCall(P.referenceRecord, (hash)), 524960, d.sourceGas
        );
        (p, receipt) = abi.decode(raw, (T.Publication, T.Receipt));
        _canonical(d.targets[4], raw, abi.encode(p, receipt));
        R.Receipt memory r = receipt.observation;
        R.Publication memory o = p.observation;
        if (
            hash == 0 || revision == 0 || receipt.scopeSubject != subject
                || keccak256(abi.encode(p.scope)) != keccak256(abi.encode(scope))
                || o.collectionId != scope.collectionId || r.collectionId != scope.collectionId
                || r.recordHash != hash || r.revision != revision || o.referenceId != r.referenceId
                || r.referenceId == 0 || o.expectedHead != r.predecessor
                || o.expectedRevision == type(uint64).max || o.expectedRevision + 1 != revision
                || o.expectedSourcesHash != r.sourcesHash || r.sourcesHash == 0
                || o.snapshotRecordHash != r.snapshotRecordHash || r.snapshotRecordHash == 0
                || o.snapshotRevision != r.snapshotRevision || r.snapshotRevision == 0
                || r.payloadHash == 0 || r.payloadBytes == 0 || r.payloadBytes > 524288
                || r.recordChainHash == 0 || r.recorder == address(0)
                || (r.authorizationClass != 3 && r.authorizationClass != 8) || r.grantRevision == 0
                || o.effectiveAt != r.effectiveAt || r.effectiveAt == 0
                || o.reasonHash != r.reasonHash || r.reasonHash == 0 || r.recordedAt == 0
                || r.effectiveAt > r.recordedAt || r.recordedAt > block.timestamp
                || r.schemaHash != D.SCHEMA_HASH || r.profileHash != D.PROFILE_HASH
                || r.canonicalizationHash != D.CANON_HASH
        ) revert InvalidScopedReferenceEvidence();
        // Original producer hashes the complete receipt before assigning these two final fields.
        T.Receipt memory fields = abi.decode(abi.encode(receipt), (T.Receipt));
        fields.observation.recordHash = 0;
        fields.observation.recordChainHash = 0;
        if (
            keccak256(
                    abi.encode(
                        keccak256("6529STREAM_SCOPED_REFERENCE_RECORD_V1"),
                        d.chainId,
                        d.targets[4],
                        d.targets[0],
                        d.targets[1],
                        p,
                        fields
                    )
                ) != hash
        ) {
            revert InvalidScopedReferenceEvidence();
        }
    }

    function requireCurrent(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 hash,
        uint64 revision
    ) public view returns (T.Receipt memory receipt) {
        (, receipt) = original(d, scope, hash, revision);
        bytes memory raw = Reads.read(
            d.targets[4],
            abi.encodeCall(P.requireCurrent, (scope, hash, revision)),
            672,
            d.sourceGas
        );
        T.Receipt memory current = abi.decode(raw, (T.Receipt));
        _canonical(d.targets[4], raw, abi.encode(current));
        if (keccak256(abi.encode(current)) != keccak256(abi.encode(receipt))) {
            revert InvalidScopedReferenceEvidence();
        }
    }

    function requireLocked(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 hash,
        uint64 revision
    ) public view returns (T.Receipt memory receipt, R.Lock memory locked) {
        receipt = requireCurrent(d, scope, hash, revision);
        bytes memory raw =
            Reads.read(d.targets[4], abi.encodeCall(P.referenceLock, (scope)), 128, d.readGas);
        locked = abi.decode(raw, (R.Lock));
        _canonical(d.targets[4], raw, abi.encode(locked));
        if (
            locked.actionId == 0 || locked.recordHash != hash || locked.revision != revision
                || locked.lockedAt < receipt.observation.recordedAt
                || locked.lockedAt > block.timestamp
        ) {
            revert InvalidScopedReferenceEvidence();
        }
    }

    function component(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 hash,
        uint64 revision
    ) public view returns (StreamFinalityComponentState memory state) {
        (T.Receipt memory receipt, R.Lock memory locked) = requireLocked(d, scope, hash, revision);
        bytes memory raw = Reads.read(
            d.targets[4],
            abi.encodeCall(IStreamArtworkScopedFinalityComponent.finalityStateForScope, (scope)),
            256,
            d.sourceGas
        );
        state = abi.decode(raw, (StreamFinalityComponentState));
        _canonical(d.targets[4], raw, abi.encode(state));
        if (
            !state.frozen || state.componentType != StreamFinalityDomains.COMPONENT_REFERENCE_RENDER
                || state.component != d.targets[4] || state.codeHash != d.codeHashes[4]
                || state.interfaceId != type(IStreamArtworkScopedFinalityComponent).interfaceId
                || state.moduleVersion
                    != keccak256("STREAM_SCOPED_REFERENCE_RENDER_IMPLEMENTATION_V1")
                || state.manifestHash != D.PROFILE_HASH
                || state.dataHash
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_LOCKED_SCOPED_REFERENCE_COMPONENT_V1"),
                            d.chainId,
                            d.targets[4],
                            d.targets[0],
                            scope,
                            receipt,
                            locked
                        )
                    )
        ) revert InvalidScopedReferenceEvidence();
    }

    function _subject(Dependencies memory d, StreamFinalityScope memory scope)
        private
        pure
        returns (bytes32)
    {
        if (
            scope.scopeType != StreamFinalityScopeType.TOKEN
                && scope.scopeType != StreamFinalityScopeType.RELEASE
                && scope.scopeType != StreamFinalityScopeType.SEASON
        ) revert InvalidScopedReferenceEvidence();
        return StreamMetadataSubjects.scopeSubject(d.chainId, d.targets[0], scope);
    }

    function _canonical(address source, bytes memory raw, bytes memory encoded) private pure {
        if (keccak256(raw) != keccak256(encoded)) revert ScopedReferenceDependency(source);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamFinalityScopedProviderReads.sol";
import "./StreamFinalityScopedReferenceReads.sol";
import "./StreamFinalityNativeSanctionProfile.sol";
import "../../interfaces/stream/finality/IStreamFinalitySanctionReview.sol";
import "../../interfaces/stream/preservation/IStreamExternalArtifactCoverage.sol";
import "../../interfaces/stream/preservation/StreamExternalArtifactTypes.sol";
import "../records/StreamReferenceRenderDefinitions.sol";
import "../records/StreamReferenceModeDefinitions.sol";
import "../../interfaces/stream/preservation/IStreamReferenceModePublication.sol";

/// @notice Ordered original PNG hashes for the independently admitted TOKEN/RELEASE/SEASON statement.
/// @dev The provider first validates all current inputs and the exact registered manifest.
/// This projection is not a separate readiness gate and accepts no caller-selected object list.
library StreamFinalityScopedSanctionReview {
    error NativeReviewSource();
    error NativeReviewRead(address target);
    uint256 internal constant MAX_PUBLICATION_BYTES = 1048576;

    function review(
        StreamFinalityScopedProviderReads.Config memory c,
        StreamScopedFinalityInputManifestTypes.Statement memory s
    ) public view returns (IStreamFinalitySanctionReview.ReviewFacts memory result) {
        if (
            c.chainId != block.chainid || s.scope.collectionId == 0
                || (s.scope.scopeType != StreamFinalityScopeType.TOKEN
                    && s.scope.scopeType != StreamFinalityScopeType.RELEASE
                    && s.scope.scopeType != StreamFinalityScopeType.SEASON) || s.contentRoot == 0
                || s.inputs.referenceRenderRecordHash == 0 || s.inputs.snapshotRecordHash == 0
                || s.referenceRenderManifestHash == 0
        ) {
            revert NativeReviewSource();
        }
        _pin(c, 2);
        _pin(c, 9);
        _pin(c, 11);
        _pin(c, 21);
        bytes32 artistId = _artist(c, s.scope.collectionId);
        (StreamReferenceRenderTypes.Publication memory publication, bool exact) = _publication(c, s);
        uint256 count = publication.captures.length;
        if (count == 0 || count > 16) revert NativeReviewSource();
        if (count > 1) {
            StreamFinalityNativeSanctionProfile.requireCurrent(
                c.targets[4], c.codeHashes[4], c.targets[5], c.codeHashes[5], c.readGas
            );
        }
        result.schemaVersion = 1;
        result.profile = count == 1 ? 1 : 2;
        result.contentRoot = s.contentRoot;
        // This scoped ONCHAIN profile has no separate off-chain media object list.
        result.mediaContentHashes = new bytes32[](0);
        result.referenceRenderContentHashes = new bytes32[](count);
        for (uint256 i; i < count; ++i) {
            result.referenceRenderContentHashes[i] =
                _capture(c, artistId, publication.captures[i], exact);
        }
    }

    function _artist(StreamFinalityScopedProviderReads.Config memory c, uint256 cid)
        private
        view
        returns (bytes32)
    {
        bytes memory raw = StreamFinalityBoundedReads.read(
            c.targets[2],
            abi.encodeCall(IStreamMetadataServingFacts.artistPresentation, (cid)),
            384,
            c.readGas
        );
        IStreamMetadataServingFacts.ArtistPresentation memory p =
            abi.decode(raw, (IStreamMetadataServingFacts.ArtistPresentation));
        if (
            keccak256(raw) != keccak256(abi.encode(p)) || !p.locked || p.artistId == 0
                || p.registry != c.targets[11] || p.registryCodeHash != c.codeHashes[11]
                || p.bindingGeneration == 0 || p.bindingHash == 0 || p.identityRecordHash == 0
                || p.acceptanceRecordHash == 0 || p.snapshotHash == 0
        ) revert NativeReviewSource();
        return p.artistId;
    }

    function _publication(
        StreamFinalityScopedProviderReads.Config memory c,
        StreamScopedFinalityInputManifestTypes.Statement memory s
    ) private view returns (StreamReferenceRenderTypes.Publication memory p, bool exact) {
        bytes memory raw = StreamFinalityBoundedReads.read(
            c.targets[9],
            abi.encodeCall(IStreamScopedReferencePublication.currentReference, (s.scope)),
            672,
            c.readGas
        );
        StreamScopedReferenceTypes.Receipt memory head =
            abi.decode(raw, (StreamScopedReferenceTypes.Receipt));
        if (
            keccak256(raw) != keccak256(abi.encode(head))
                || head.scopeSubject
                    != StreamMetadataSubjects.scopeSubject(c.chainId, c.targets[0], s.scope)
                || head.observation.recordHash != s.inputs.referenceRenderRecordHash
                || head.observation.payloadHash != s.referenceRenderManifestHash
                || head.observation.snapshotRecordHash != s.inputs.snapshotRecordHash
        ) revert NativeReviewSource();
        StreamFinalityScopedReferenceReads.Dependencies memory d;
        uint256[5] memory indexes = [uint256(0), 1, 2, 8, 9];
        for (uint256 i; i < 5; ++i) {
            d.targets[i] = c.targets[indexes[i]];
            d.codeHashes[i] = c.codeHashes[indexes[i]];
        }
        d.chainId = c.chainId;
        d.readGas = c.readGas;
        d.sourceGas = c.sourceGas;
        // Recompute the original full scoped record and its immutable receipt. The provider
        // already authenticated current inventory; this projection cannot select another host.
        (
            StreamScopedReferenceTypes.Publication memory saved,
            StreamScopedReferenceTypes.Receipt memory receipt
        ) = StreamFinalityScopedReferenceReads.original(
            d, s.scope, s.inputs.referenceRenderRecordHash, head.observation.revision
        );
        if (keccak256(abi.encode(receipt)) != keccak256(raw)) revert NativeReviewSource();
        p = saved.observation;
        exact = true; // This distinct current scoped reference profile explicitly requires repeat-byte equality.
    }

    function _capture(
        StreamFinalityScopedProviderReads.Config memory c,
        bytes32 artistId,
        StreamReferenceRenderTypes.Capture memory capture,
        bool exact
    ) private view returns (bytes32) {
        bytes memory raw = StreamFinalityBoundedReads.read(
            c.targets[21],
            abi.encodeCall(IStreamExternalArtifactCoverage.objectIdentity, (capture.objectHash)),
            320,
            c.readGas
        );
        StreamExternalArtifactTypes.ObjectIdentity memory o =
            abi.decode(raw, (StreamExternalArtifactTypes.ObjectIdentity));
        if (
            keccak256(raw) != keccak256(abi.encode(o)) || o.artistId != artistId
                || o.contentHash == 0 || o.sha256Digest == 0 || capture.repeatCaptureSha256[0] == 0
                || capture.repeatCaptureSha256[1] == 0
                || (exact && capture.repeatCaptureSha256[0] != capture.repeatCaptureSha256[1])
                || o.sha256Digest != capture.repeatCaptureSha256[0] || o.arweaveDataRoot == 0
                || o.byteSize == 0 || capture.coverageHash == 0
                || o.canonicalizationId != keccak256("RAW_BYTES")
                || o.schemaId != StreamReferenceRenderDefinitions.PNG_SCHEMA_ID
                || o.formatId != keccak256("IANA:image/png")
                || o.formatCatalogId != StreamReferenceRenderDefinitions.FORMAT_CATALOG_ID
                || o.formatCatalogHash != StreamReferenceRenderDefinitions.FORMAT_CATALOG_HASH
                || capture.objectHash
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_EXTERNAL_OBJECT_V1"),
                            c.chainId,
                            c.targets[21],
                            c.targets[0],
                            o
                        )
                    )
        ) revert NativeReviewSource();
        return o.contentHash;
    }

    function _pin(StreamFinalityScopedProviderReads.Config memory c, uint256 index) private view {
        if (c.targets[index].code.length == 0 || c.targets[index].codehash != c.codeHashes[index]) {
            revert NativeReviewRead(c.targets[index]);
        }
    }

    function _dynamicRead(address target, bytes memory input, uint256 cap)
        private
        view
        returns (bytes memory result)
    {
        // Inspect bounded returndata before allocating/copying it. No unbounded return bomb.
        uint256 available = gasleft();
        if (available <= 100000 || cap == 0) revert NativeReviewRead(target);
        uint256 forwarded = available - 100000;
        if (cap < forwarded) forwarded = cap;
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(forwarded, target, add(input, 32), mload(input), 0, 0)
            size := returndatasize()
        }
        if (!ok || size == 0 || size > MAX_PUBLICATION_BYTES) revert NativeReviewRead(target);
        result = new bytes(size);
        assembly ("memory-safe") { returndatacopy(add(result, 32), 0, size) }
    }
}

