// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/finality/StreamScopeMembershipTypes.sol";
import "../../interfaces/stream/finality/StreamArtworkFinalityTypes.sol";

/// @notice Canonical byte grammar and hashes; no publication or token authority is inferred.
library StreamScopeMembershipEncoding {
    bytes32 internal constant SCOPE_ID_DOMAIN = keccak256("6529STREAM_SCOPE_MEMBERSHIP_ID_V1");
    bytes32 internal constant MEMBERSHIP_DOMAIN = keccak256("6529STREAM_SCOPE_MEMBERSHIP_FACTS_V1");
    bytes32 internal constant SCHEMA_ID = keccak256("STREAM_SCOPE_MEMBERSHIP_V1");
    bytes32 internal constant CANONICALIZATION_ID = keccak256("STREAM_SCOPE_MEMBERSHIP_ABI_V1");
    uint256 internal constant CHUNK_BYTES = 8192;
    uint256 internal constant MAX_CHUNKS = 64;

    error InvalidScopeMembershipEncoding();

    function encode(StreamScopeMembershipManifest memory m) public pure returns (bytes memory raw) {
        _shape(m);
        raw = abi.encode(
            m.version,
            m.chainId,
            m.core,
            m.collectionId,
            m.scopeType,
            m.tokenCount,
            m.tokenListHash,
            m.chunkHashes
        );
    }

    function decode(bytes memory raw) public pure returns (StreamScopeMembershipManifest memory m) {
        if (raw.length < 288 || raw.length > 288 + 32 * MAX_CHUNKS) {
            revert InvalidScopeMembershipEncoding();
        }
        uint256 parts = _word(raw, 8);
        if (
            _word(raw, 0) != 1 || _word(raw, 2) >> 160 != 0 || _word(raw, 4) > type(uint8).max
                || _word(raw, 7) != 256 || parts > MAX_CHUNKS || raw.length != 288 + 32 * parts
        ) revert InvalidScopeMembershipEncoding();
        m.version = 1;
        m.chainId = _word(raw, 1);
        m.core = address(uint160(_word(raw, 2)));
        m.collectionId = _word(raw, 3);
        m.scopeType = uint8(_word(raw, 4));
        m.tokenCount = _word(raw, 5);
        m.tokenListHash = bytes32(_word(raw, 6));
        m.chunkHashes = new bytes32[](parts);
        for (uint256 i; i < parts; ++i) {
            m.chunkHashes[i] = bytes32(_word(raw, 9 + i));
        }
        _shape(m);
    }

    function scopeId(
        uint256 chainId,
        address core,
        uint256 collectionId,
        uint8 scopeType,
        bytes32 recordHash
    ) public pure returns (bytes32) {
        if (
            core == address(0) || collectionId == 0 || scopeType < 2 || scopeType > 4
                || recordHash == 0
        ) {
            revert InvalidScopeMembershipEncoding();
        }
        return keccak256(
            abi.encode(SCOPE_ID_DOMAIN, chainId, core, collectionId, scopeType, recordHash)
        );
    }

    function membershipHash(
        uint256 chainId,
        address core,
        address metadataHost,
        address inventory,
        StreamFinalityScope memory scope,
        StreamScopeMembershipFacts memory f
    ) public pure returns (bytes32) {
        return membershipHashStatic(chainId, core, metadataHost, inventory, scope, f);
    }

    /// @notice Exact original seven-fact commitment without a linked-library call.
    function membershipHashStatic(
        uint256 chainId,
        address core,
        address metadataHost,
        address inventory,
        StreamFinalityScope memory scope,
        StreamScopeMembershipFacts memory f
    ) internal pure returns (bytes32) {
        // The output hash field is intentionally excluded; all other seven fact words are bound.
        bytes32 factsHash = keccak256(
            abi.encode(
                f.scopeSubject,
                f.scopeManifestHash,
                f.sourceRecordHash,
                f.tokenCount,
                f.tokenListHash,
                f.inventoryCount,
                f.inventoryPrefixHash
            )
        );
        return keccak256(
            abi.encode(MEMBERSHIP_DOMAIN, chainId, core, metadataHost, inventory, scope, factsHash)
        );
    }

    function _shape(StreamScopeMembershipManifest memory m) private pure {
        if (
            m.version != 1 || m.core == address(0) || m.collectionId == 0 || m.scopeType < 2
                || m.scopeType > 4 || m.tokenCount > MAX_CHUNKS * CHUNK_BYTES / 32
                || m.chunkHashes.length != (m.tokenCount * 32 + CHUNK_BYTES - 1) / CHUNK_BYTES
                || m.tokenListHash == 0 || (m.tokenCount == 0 && m.tokenListHash != keccak256(""))
        ) revert InvalidScopeMembershipEncoding();
        for (uint256 i; i < m.chunkHashes.length; ++i) {
            if (m.chunkHashes[i] == 0) revert InvalidScopeMembershipEncoding();
        }
    }

    function _word(bytes memory raw, uint256 index) private pure returns (uint256 value) {
        assembly ("memory-safe") { value := mload(add(add(raw, 32), mul(index, 32))) }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamScopeMembershipEncoding.sol";
import "../../interfaces/stream/finality/IStreamFinalityScopeMembership.sol";
import "../../interfaces/stream/metadata/IStreamSchemaDocumentFacts.sol";
import "../metadata/StreamMetadataSubjects.sol";
import "../metadata/StreamSchemaDocumentStore.sol";
import "../records/StreamCollectionRecordHashes.sol";
import "../records/StreamRecordFamilies.sol";

/// @notice Bounded original publication and native-byte reads for the fixed membership host.
/// @dev The host supplies only constructor-derived targets. This library is not an authority route.
library StreamScopeMembershipReads {
    bytes32 internal constant RECORD_TYPE = keccak256("SCOPE_MEMBERSHIP");
    bytes32 internal constant SCHEMA_HASH =
        0x70c79fbabc4dc32259b4f3958da52f8c9d27814e9202e1ab2b1c0b75acd3d2cb;
    bytes32 internal constant CANON_HASH =
        0x3a8f6aa2c183ea43dff145064f8175f2a7c4bc7c2b65633d0fdfdc36fdeaab5e;

    struct Inputs {
        uint256 chainId;
        address core;
        address metadataHost;
        address schemaRegistry;
        address chunkStore;
        uint256 readGas;
    }

    function publication(Inputs memory b, bytes32 recordHash)
        public
        view
        returns (
            StreamScopeMembershipManifest memory m,
            IStreamFinalityScopeMembership.Publication memory p
        )
    {
        bytes memory raw = read(
            b.metadataHost,
            abi.encodeCall(IStreamCollectionMetadataV1.collectionRecord, (recordHash)),
            4096,
            b.readGas,
            false
        );
        (
            IStreamPreservationRecords.CollectionRecord memory record,
            IStreamCollectionMetadataV1.RecordReceipt memory receipt
        ) = abi.decode(
            raw,
            (IStreamPreservationRecords.CollectionRecord, IStreamCollectionMetadataV1.RecordReceipt)
        );
        if (
            keccak256(raw) != keccak256(abi.encode(record, receipt))
                || receipt.recorder == address(0)
                || (receipt.authorizationClass != 7 && receipt.authorizationClass != 8)
                || receipt.recordedAt == 0 || receipt.recordChainHash == 0
                || receipt.artistAuthorization != 0 || record.recordType != RECORD_TYPE
                || record.schemaId != StreamScopeMembershipEncoding.SCHEMA_ID
                || record.contentHash.algorithm != 1 || record.contentHash.digest.length != 32
                || record.contentHash.canonicalizationId
                    != StreamScopeMembershipEncoding.CANONICALIZATION_ID
                || record.signatureScheme != 0 || record.signatureHash.algorithm != 0
                || record.signatureHash.digest.length != 0
                || record.signatureHash.canonicalizationId != 0 || record.effectiveAt == 0
                || receipt.schemaDefinitionHash != SCHEMA_HASH
                || receipt.canonicalizationDefinitionHash != CANON_HASH
                || _recordHash(b, record, receipt) != recordHash
        ) revert IStreamFinalityScopeMembership.InvalidScopeMembershipRecord(recordHash);
        _policyAndIndex(b, receipt, recordHash);
        _definitions(b);
        raw = read(
            b.metadataHost,
            abi.encodeCall(IStreamCollectionMetadataV1.recordPayload, (recordHash)),
            8352,
            b.readGas,
            false
        );
        (address pointer, bytes memory payload) = abi.decode(raw, (address, bytes));
        bytes32 manifestHash = bytes32(record.contentHash.digest);
        if (
            keccak256(raw) != keccak256(abi.encode(pointer, payload))
                || keccak256(payload) != manifestHash
        ) {
            revert IStreamFinalityScopeMembership.InvalidScopeMembershipRecord(recordHash);
        }
        (address nativePointer, uint256 nativeLength) =
            chunkPointer(b.chunkStore, manifestHash, b.readGas);
        if (pointer != nativePointer || payload.length != nativeLength) {
            revert IStreamFinalityScopeMembership.InvalidScopeMembershipRecord(recordHash);
        }
        m = StreamScopeMembershipEncoding.decode(payload);
        if (
            m.chainId != b.chainId || m.core != b.core || m.collectionId != receipt.collectionId
                || record.subjectId
                    != StreamMetadataSubjects.scopeSubject(
                        b.chainId,
                        b.core,
                        StreamFinalityScope(
                            StreamFinalityScopeType.COLLECTION, m.collectionId, 0, 0
                        )
                    )
        ) revert IStreamFinalityScopeMembership.InvalidScopeMembershipRecord(recordHash);
        p = IStreamFinalityScopeMembership.Publication(
            recordHash,
            manifestHash,
            record.schemaId,
            record.contentHash.canonicalizationId,
            pointer,
            pointer.codehash,
            record.effectiveAt,
            receipt
        );
    }

    function _recordHash(
        Inputs memory b,
        IStreamPreservationRecords.CollectionRecord memory r,
        IStreamCollectionMetadataV1.RecordReceipt memory receipt
    ) private pure returns (bytes32) {
        StreamCollectionRecordHashes.Preimage memory p;
        p.domain = keccak256("6529stream.preservation-record.v2");
        p.chainId = b.chainId;
        p.host = b.metadataHost;
        p.core = b.core;
        p.recorder = receipt.recorder;
        p.collectionId = receipt.collectionId;
        p.recordType = r.recordType;
        p.subjectId = r.subjectId;
        p.contentHash = StreamCollectionRecordHashes.hashRef(
            r.contentHash.algorithm, r.contentHash.digest, r.contentHash.canonicalizationId
        );
        p.uriHash = keccak256(bytes(r.uri));
        p.schemaId = r.schemaId;
        p.signatureScheme = r.signatureScheme;
        p.signatureHash = StreamCollectionRecordHashes.hashRef(
            r.signatureHash.algorithm, r.signatureHash.digest, r.signatureHash.canonicalizationId
        );
        p.effectiveAt = r.effectiveAt;
        return keccak256(abi.encode(p));
    }

    function _policyAndIndex(
        Inputs memory b,
        IStreamCollectionMetadataV1.RecordReceipt memory receipt,
        bytes32 recordHash
    ) private view {
        IStreamCollectionMetadataV1.RecordPolicy memory
            policy =
            abi.decode(
                read(
                    b.metadataHost,
                    abi.encodeCall(IStreamCollectionMetadataV1.recordPolicy, (RECORD_TYPE)),
                    96,
                    b.readGas,
                    true
                ),
                (IStreamCollectionMetadataV1.RecordPolicy)
            );
        if (
            !policy.admitted || policy.family != StreamRecordFamilies.IDENTITY
                || (policy.authorizationMask & StreamRecordFamilies.bit(receipt.authorizationClass))
                    == 0
                || (policy.authorizationMask
                            & ~(StreamRecordFamilies.bit(7) | StreamRecordFamilies.bit(8))) != 0
                || abi.decode(
                        read(
                            b.metadataHost,
                            abi.encodeCall(
                                IStreamCollectionMetadataV1.recordHashAt,
                                (receipt.collectionId, RECORD_TYPE, uint256(receipt.recordIndex))
                            ),
                            32,
                            b.readGas,
                            true
                        ),
                        (bytes32)
                    ) != recordHash
        ) revert IStreamFinalityScopeMembership.InvalidScopeMembershipRecord(recordHash);
    }

    function _definitions(Inputs memory b) private view {
        _definition(
            b,
            StreamScopeMembershipEncoding.SCHEMA_ID,
            IStreamSchemaRegistry.DocumentKind.SCHEMA,
            SCHEMA_HASH,
            2047
        );
        _definition(
            b,
            StreamScopeMembershipEncoding.CANONICALIZATION_ID,
            IStreamSchemaRegistry.DocumentKind.CANONICALIZATION,
            CANON_HASH,
            1309
        );
    }

    function _definition(
        Inputs memory b,
        bytes32 id,
        IStreamSchemaRegistry.DocumentKind kind,
        bytes32 hash,
        uint32 size
    ) private view {
        IStreamSchemaDocumentFacts.DocumentFacts memory f =
            abi.decode(
                read(
                    b.schemaRegistry,
                    abi.encodeCall(IStreamSchemaDocumentFacts.documentFacts, (id)),
                    288,
                    b.readGas,
                    true
                ),
                (IStreamSchemaDocumentFacts.DocumentFacts)
            );
        if (
            !f.exists || f.kind != kind || f.contentHash != hash || f.totalBytes != size
                || f.canonicalizationId != keccak256("RAW_BYTES") || f.chunkCount != 1
                || f.declarationHash == 0
        ) revert IStreamFinalityScopeMembership.InvalidScopeMembershipRecord(id);
        bytes memory raw = read(
            b.schemaRegistry,
            abi.encodeCall(IStreamSchemaRegistry.documentBytes, (id)),
            64 + ((uint256(size) + 31) / 32) * 32,
            b.readGas,
            true
        );
        bytes memory payload = abi.decode(raw, (bytes));
        if (
            payload.length != size || keccak256(payload) != hash
                || keccak256(raw) != keccak256(abi.encode(payload))
        ) {
            revert IStreamFinalityScopeMembership.InvalidScopeMembershipRecord(id);
        }
        // Retirement changes new-writing policy, never the interpretation of an original record.
    }

    function chunkPointer(address store, bytes32 hash, uint256 cap)
        public
        view
        returns (address pointer, uint256 length)
    {
        (pointer, length) = abi.decode(
            read(store, abi.encodeWithSignature("chunk(bytes32)", hash), 64, cap, true),
            (address, uint256)
        );
        if (
            pointer == address(0) || length == 0 || length > 8192
                || pointer.code.length != length + 1
        ) {
            revert IStreamFinalityScopeMembership.ScopeMembershipDependencyChanged(pointer);
        }
    }

    function part(
        address store,
        bytes32 hash,
        address expectedPointer,
        bytes32 codeHash,
        uint256 length,
        uint256 cap
    ) public view returns (bytes memory payload) {
        (address pointer, uint256 actualLength) = chunkPointer(store, hash, cap);
        if (pointer != expectedPointer || pointer.codehash != codeHash || actualLength != length) {
            revert IStreamFinalityScopeMembership.ScopeMembershipDependencyChanged(pointer);
        }
        bytes memory raw = read(
            store,
            abi.encodeCall(StreamSchemaDocumentStore.readChunk, (hash)),
            64 + length,
            cap,
            true
        );
        payload = abi.decode(raw, (bytes));
        if (
            payload.length != length || keccak256(payload) != hash
                || keccak256(raw) != keccak256(abi.encode(payload))
        ) {
            revert IStreamFinalityScopeMembership.ScopeMembershipDependencyChanged(pointer);
        }
    }

    function read(address target, bytes memory input, uint256 maximum, uint256 cap, bool exact)
        public
        view
        returns (bytes memory output)
    {
        return readStatic(target, input, maximum, cap, exact);
    }

    /// @notice Exact original bounded read, inlined for transitive STATIC serving paths.
    /// @dev The public read ABI remains for original publication callers. No source, cap,
    /// malformed-return or parent-gas rule differs between the two entry paths.
    function readStatic(
        address target,
        bytes memory input,
        uint256 maximum,
        uint256 cap,
        bool exact
    ) internal view returns (bytes memory output) {
        output = new bytes(maximum);
        if (cap == 0 || cap > type(uint256).max / 64) {
            revert IStreamFinalityScopeMembership.InvalidScopeMembershipConfiguration();
        }
        uint256 required = cap + cap / 63 + 100000;
        if (gasleft() <= required) {
            revert IStreamFinalityScopeMembership.ScopeMembershipParentGas(gasleft(), required);
        }
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(input, 32), mload(input), add(output, 32), maximum)
            size := returndatasize()
        }
        if (!ok || size > maximum || (exact && size != maximum)) {
            revert IStreamFinalityScopeMembership.ScopeMembershipReadFailed(target, bytes4(input));
        }
        assembly ("memory-safe") { mstore(output, size) }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamScopedFinalityInputManifestSchemas.sol";
import "./StreamFinalityRouterEvidence.sol";
import "../../interfaces/stream/finality/StreamScopedFinalityInputManifestTypes.sol";
import "../../interfaces/stream/finality/IStreamArtworkFinalityRegistry.sol";
import "../../interfaces/stream/metadata/IStreamSchemaDocumentFacts.sol";
import "../metadata/StreamSchemaDocumentStore.sol";

/// @notice Exact registered interpretation and two-store admission of an independent manifest.
/// @dev The consuming provider supplies fixed dependencies and independently derived current
/// facts. No caller-selected input list, new latest pointer, publication authority or readiness
/// interface is introduced. This joins bytes; actual source/coverage/authority validation stays
/// mandatory in the provider, while sanction and manifest archival evidence are separate joins.
library StreamScopedFinalityInputManifestReads {
    struct Dependencies {
        // Core, actual generic Metadata, schemas, schema Store, original Finality Registry.
        address[5] targets;
        bytes32[5] codeHashes;
        uint256 chainId;
        uint256 readGas;
    }
    error InvalidInputManifest();
    error InputManifestDependency(address target);
    error InputManifestDefinition(bytes32 id);
    error InputManifestBytes(bytes32 hash);

    function encode(
        Dependencies memory d,
        StreamScopedFinalityInputManifestTypes.Statement memory s
    ) public pure returns (bytes memory payload) {
        _shape(s);
        if (
            d.chainId == 0 || d.targets[0] == address(0) || d.targets[1] == address(0)
                || d.targets[4] == address(0)
        ) revert InvalidInputManifest();
        payload = abi.encode(
            StreamScopedFinalityInputManifestSchemas.SCHEMA_ID,
            StreamScopedFinalityInputManifestSchemas.CANON_ID,
            d.chainId,
            d.targets[0],
            d.targets[1],
            d.targets[4],
            s
        );
        if (payload.length > 8192) revert InvalidInputManifest();
    }

    function scopeInputsHash(
        Dependencies memory d,
        StreamScopedFinalityInputManifestTypes.Statement memory s
    ) public pure returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_FINALITY_SCOPE_INPUTS_V1"),
                d.chainId,
                d.targets[0],
                d.targets[1],
                s.scope,
                s.inputs
            )
        );
    }

    function requireCurrent(
        Dependencies memory d,
        StreamScopedFinalityInputManifestTypes.Statement memory expected,
        bytes32 contentHash
    ) public view returns (bytes32 schemaId, bytes32 canonicalizationId) {
        _bindings(d);
        bytes memory payload = encode(d, expected);
        if (contentHash == 0 || keccak256(payload) != contentHash) {
            revert InputManifestBytes(contentHash);
        }
        schemaId = StreamScopedFinalityInputManifestSchemas.SCHEMA_ID;
        canonicalizationId = StreamScopedFinalityInputManifestSchemas.CANON_ID;
        _definition(d, schemaId, IStreamSchemaRegistry.DocumentKind.SCHEMA);
        _definition(d, canonicalizationId, IStreamSchemaRegistry.DocumentKind.CANONICALIZATION);
        _same(
            d.targets[3],
            abi.encodeCall(StreamSchemaDocumentStore.readChunk, (contentHash)),
            payload,
            contentHash,
            d.readGas
        );
        _same(
            d.targets[4],
            abi.encodeCall(IStreamArtworkFinalityRegistry.finalityManifestBytes, (contentHash)),
            payload,
            contentHash,
            d.readGas
        );
    }

    function _same(
        address target,
        bytes memory input,
        bytes memory expected,
        bytes32 hash,
        uint256 cap
    ) private view {
        bytes memory raw = StreamFinalityRouterEvidence.dynamicRead(target, input, 8256, cap);
        bytes memory actual = abi.decode(raw, (bytes));
        if (
            keccak256(raw) != keccak256(abi.encode(actual)) || actual.length != expected.length
                || keccak256(actual) != hash
        ) revert InputManifestBytes(hash);
        // Both whole-byte digests must match the independently encoded expected document.
        if (keccak256(expected) != hash) revert InputManifestBytes(hash);
    }

    function _bindings(Dependencies memory d) private view {
        if (d.chainId != block.chainid || d.readGas < 50000 || d.readGas > type(uint256).max / 64) {
            revert InvalidInputManifest();
        }
        for (uint256 i; i < 5; ++i) {
            if (d.targets[i].code.length == 0 || d.targets[i].codehash != d.codeHashes[i]) {
                revert InputManifestDependency(d.targets[i]);
            }
        }
        _address(d, 1, "core()", 0);
        _address(d, 1, "schemaRegistry()", 2);
        _address(d, 2, "chunkStore()", 3);
        _address(d, 4, "coreReads()", 0);
        _address(d, 4, "metadataReads()", 1);
    }

    function _address(Dependencies memory d, uint256 source, string memory signature, uint256 dest)
        private
        view
    {
        bytes memory raw = StreamFinalityRouterEvidence.read(
            d.targets[source], abi.encodeWithSignature(signature), 32, d.readGas
        );
        if (abi.decode(raw, (uint256)) != uint256(uint160(d.targets[dest]))) {
            revert InputManifestDependency(d.targets[source]);
        }
    }

    function _definition(Dependencies memory d, bytes32 id, IStreamSchemaRegistry.DocumentKind kind)
        private
        view
    {
        bytes memory expected = StreamScopedFinalityInputManifestSchemas.document(id);
        bytes memory raw = StreamFinalityRouterEvidence.read(
            d.targets[2],
            abi.encodeCall(IStreamSchemaDocumentFacts.documentFacts, (id)),
            288,
            d.readGas
        );
        IStreamSchemaDocumentFacts.DocumentFacts memory f =
            abi.decode(raw, (IStreamSchemaDocumentFacts.DocumentFacts));
        if (
            keccak256(raw) != keccak256(abi.encode(f)) || !f.exists || f.kind != kind
                || f.status != IStreamSchemaRegistry.DocumentStatus.ACTIVE
                || f.contentHash != keccak256(expected) || f.totalBytes != expected.length
                || f.canonicalizationId != keccak256("RAW_BYTES") || f.chunkCount != 1
                || f.declarationHash == 0
        ) revert InputManifestDefinition(id);
        _same(
            d.targets[2],
            abi.encodeCall(IStreamSchemaRegistry.documentBytes, (id)),
            expected,
            keccak256(expected),
            d.readGas
        );
    }

    function _shape(StreamScopedFinalityInputManifestTypes.Statement memory s) private pure {
        if (
            s.scope.collectionId == 0
                || (s.scope.scopeType == StreamFinalityScopeType.TOKEN
                        ? s.scope.tokenId == 0 || s.scope.scopeId != 0 || s.leafCount != 1
                        : (s.scope.scopeType != StreamFinalityScopeType.RELEASE
                            && s.scope.scopeType != StreamFinalityScopeType.SEASON)
                        || s.scope.tokenId != 0 || s.scope.scopeId == 0) || s.coreFactsHash == 0
                || s.contentRoot == 0 || s.leafCount == 0 || s.contentRootSchemaId == 0
                || s.snapshotManifestHash == 0 || s.referenceRenderManifestHash == 0
                || s.entropyPolicy != 1 || s.postFreezePolicy != 1 || s.sanctionPolicy != 1
                || s.nonSanctionComponents.length != 9
        ) revert InvalidInputManifest();
        StreamFinalityScopeInputs memory e = s.inputs;
        if (
            e.rootRecordHash == 0 || e.snapshotRecordHash == 0 || e.referenceRenderRecordHash == 0
                || e.interviewEvidenceHash == 0 || e.rightsStatementRecordHash == 0
                || e.workDescriptionRecordHash == 0 || e.renderCriticalEvidenceHash == 0
                || e.bundleCoverageHash == 0
                || ((e.intentRecordHash == 0) == (e.intentWaiverRecordHash == 0))
        ) {
            revert InvalidInputManifest();
        }
        uint256 seen;
        for (uint256 i; i < 9; ++i) {
            StreamFinalityComponentExpectation memory c = s.nonSanctionComponents[i];
            if (
                c.component == address(0) || c.codeHash == 0 || c.interfaceId == 0
                    || c.moduleVersion == 0 || c.manifestHash == 0 || c.dataHash == 0
                    || (i != 0 && c.componentType <= s.nonSanctionComponents[i - 1].componentType)
            ) {
                revert InvalidInputManifest();
            }
            uint256 bit = _familyBit(c.componentType);
            if ((seen & bit) != 0) revert InvalidInputManifest();
            seen |= bit;
        }
        if (seen != 511) revert InvalidInputManifest();
    }

    function _familyBit(bytes32 id) private pure returns (uint256) {
        if (id == StreamFinalityDomains.COMPONENT_METADATA_ROUTER) return 1;
        if (id == StreamFinalityDomains.COMPONENT_RENDERER) return 2;
        if (id == StreamFinalityDomains.COMPONENT_RENDER_CONTEXT) return 4;
        if (id == StreamFinalityDomains.COMPONENT_MEDIA_MANIFEST) return 8;
        if (id == StreamFinalityDomains.COMPONENT_SCRIPT_SOURCE) return 16;
        if (id == StreamFinalityDomains.COMPONENT_DEPENDENCY_SOURCE) return 32;
        if (id == StreamFinalityDomains.COMPONENT_COLLECTION_METADATA) return 64;
        if (id == StreamFinalityDomains.COMPONENT_ENTROPY_COORDINATOR) return 128;
        if (id == StreamFinalityDomains.COMPONENT_REFERENCE_RENDER) return 256;
        revert InvalidInputManifest();
    }
}

