pragma solidity ^0.8.19;

import "../../interfaces/stream/core/IStreamCoreCollectionView.sol";
import "../../interfaces/stream/artist/IStreamArtistAttribution.sol";
import "../../interfaces/stream/artist/IStreamArtistContentRatification.sol";
import "../../interfaces/stream/artist/IStreamArtistContentAuthority.sol";

/// @notice Fixed-library consent consumption and ratification continuity in Router storage.
library StreamMetadataContentAuthorization {
    struct Context {
        address core;
        address artist;
        uint256 collectionId;
        bytes32 currentState;
    }

    error ArtistContentEvolutionBroken(uint256 collectionId);
    error ArtistContentAuthorizationRequired(uint256 collectionId);
    error ArtistContentConsentConsumed(bytes32 recordHash);

    event ArtistContentConsentApplied(
        uint256 indexed collectionId,
        bytes32 indexed familyId,
        bytes32 indexed consentRecordHash,
        bytes32 resultingContentStateHash,
        uint16 schemaVersion
    );

    function authorize(
        mapping(bytes32 => bool) storage consumed,
        mapping(uint256 => bytes32) storage evolutionRatification,
        mapping(uint256 => bytes32) storage evolutionContent,
        Context memory ctx,
        bytes32 familyId,
        bytes32 newStateHash
    ) public returns (bytes32 consent, bytes32 ratification) {
        return _authorize(
            consumed, evolutionRatification, evolutionContent, ctx, familyId, newStateHash, false
        );
    }

    /// @notice Closed alternate-view profile requires original op17 consent even before mint.
    function authorizeRequired(
        mapping(bytes32 => bool) storage consumed,
        mapping(uint256 => bytes32) storage evolutionRatification,
        mapping(uint256 => bytes32) storage evolutionContent,
        Context memory ctx,
        bytes32 familyId,
        bytes32 newStateHash
    ) public returns (bytes32 consent, bytes32 ratification) {
        return _authorize(
            consumed, evolutionRatification, evolutionContent, ctx, familyId, newStateHash, true
        );
    }

    function _authorize(
        mapping(bytes32 => bool) storage consumed,
        mapping(uint256 => bytes32) storage evolutionRatification,
        mapping(uint256 => bytes32) storage evolutionContent,
        Context memory ctx,
        bytes32 familyId,
        bytes32 newStateHash,
        bool required
    ) private returns (bytes32 consent, bytes32 ratification) {
        (bool ratified, bytes32 ratifiedState, bytes32 record) =
            IStreamArtistContentRatification(ctx.artist).firstReleaseRatification(ctx.collectionId);
        if (!ratified) {
            if (
                !required
                    && (IStreamCoreCollectionView(ctx.core).collectionMintedEver(ctx.collectionId)
                            == 0
                        || IStreamArtistAttribution(ctx.artist)
                            .attribution(ctx.collectionId)
                            .nominatedArtist == address(0))
            ) return (0, 0);
        } else {
            if (
                record == bytes32(0)
                    || (ctx.currentState != ratifiedState
                        && (evolutionRatification[ctx.collectionId] != record
                            || evolutionContent[ctx.collectionId] != ctx.currentState))
            ) revert ArtistContentEvolutionBroken(ctx.collectionId);
            ratification = record;
        }
        try IStreamArtistContentAuthority(ctx.artist)
            .contentConsentEvidence(ctx.collectionId, familyId, newStateHash) returns (
            bytes32 evidence
        ) {
            consent = evidence;
        } catch {
            revert ArtistContentAuthorizationRequired(ctx.collectionId);
        }
        if (consent == bytes32(0)) revert ArtistContentAuthorizationRequired(ctx.collectionId);
        if (consumed[consent]) revert ArtistContentConsentConsumed(consent);
        consumed[consent] = true;
    }

    function recordApplication(
        mapping(uint256 => bytes32) storage evolutionRatification,
        mapping(uint256 => bytes32) storage evolutionContent,
        uint256 collectionId,
        bytes32 familyId,
        bytes32 consent,
        bytes32 ratification,
        bytes32 currentState
    ) public {
        if (consent == bytes32(0)) return;
        if (ratification != bytes32(0)) {
            evolutionRatification[collectionId] = ratification;
            evolutionContent[collectionId] = currentState;
        }
        emit ArtistContentConsentApplied(collectionId, familyId, consent, currentState, 1);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/artist/IStreamArtistContentAuthority.sol";

/// @notice Fixed-library application of exact artist freeze authorization in Router storage.
library StreamMetadataContentLocks {
    error InvalidArtistContentFreeze(bytes32 recordHash);
    event CollectionMetadataLocked(
        uint256 indexed collectionId,
        bytes32 indexed lockId,
        address actor,
        uint8 authorityClass,
        bytes32 freezeAuthorizationHash,
        uint16 schemaVersion
    );

    function applyFreeze(
        mapping(uint256 => mapping(bytes32 => bool)) storage locks,
        address artist,
        uint256 collectionId,
        bytes32 freezeRecordHash,
        bytes32 currentState
    ) public {
        IStreamArtistContentAuthority authority = IStreamArtistContentAuthority(artist);
        C.FreezeRecord memory record = authority.contentFreezeAuthorization(freezeRecordHash);
        if (
            freezeRecordHash == 0 || record.recordHash != freezeRecordHash || record.artistId == 0
                || record.metadataContract != address(this) || record.authorityClass == 0
                || record.lockClasses.length == 0 || record.lockClasses.length > 16
                || record.expectedStateHash != currentState
        ) revert InvalidArtistContentFreeze(freezeRecordHash);
        bytes32 previous;
        for (uint256 i; i < record.lockClasses.length; ++i) {
            bytes32 lockClass = record.lockClasses[i];
            if (
                lockClass <= previous
                    || (lockClass != keccak256("SCRIPT")
                        && lockClass != keccak256("MEDIA_MANIFEST")
                        && lockClass != keccak256("BASE_URI")
                        && lockClass != keccak256("DEPENDENCIES")
                        && lockClass != keccak256("RENDERER_CONFIG"))
            ) revert InvalidArtistContentFreeze(freezeRecordHash);
            (bool authorized, bytes32 operative) =
                authority.isContentFreezeAuthorized(collectionId, lockClass);
            if (!authorized || operative != freezeRecordHash) {
                revert InvalidArtistContentFreeze(freezeRecordHash);
            }
            previous = lockClass;
        }
        for (uint256 i; i < record.lockClasses.length; ++i) {
            bytes32 lockClass = record.lockClasses[i];
            if (locks[collectionId][lockClass]) continue;
            locks[collectionId][lockClass] = true;
            emit CollectionMetadataLocked(
                collectionId, lockClass, msg.sender, record.authorityClass, freezeRecordHash, 1
            );
        }
    }
}

