pragma solidity ^0.8.19;

import {
    IStreamContentRootPublication as R
} from "../../interfaces/stream/metadata/IStreamContentRootPublication.sol";
import "../../interfaces/stream/finality/IStreamContentRootEvidenceBinding.sol";
import "../../interfaces/stream/finality/IStreamFinalityDeploymentBindings.sol";
import "../../interfaces/stream/finality/IStreamFinalityEvidenceProvider.sol";
import "../../interfaces/stream/finality/IStreamContentLeafManifest.sol";
import "../../interfaces/stream/finality/IStreamOnchainContentCheckpoint.sol";
import "../../interfaces/stream/preservation/IStreamFinalityArtifactCoverage.sol";
import "../../interfaces/stream/core/IStreamCorePointers.sol";
import "../../interfaces/stream/core/IStreamCoreCollectionView.sol";
import "../../interfaces/stream/artist/IStreamArtistAttributionState.sol";
import "../../interfaces/stream/artist/IStreamArtistFinalityBinding.sol";
import "../../interfaces/stream/metadata/IStreamCollectionMetadataV1.sol";
import "../../interfaces/stream/parameters/IStreamGasParameterHost.sol";
import "../../interfaces/stream/metadata/IStreamSchemaRegistry.sol";
import "../records/StreamRecordFamilies.sol";
import "../finality/StreamContentRootSchemas.sol";
import "./StreamMetadataSubjects.sol";
import "./StreamMetadataRenderer.sol";
import {
    StreamPolicyContentRootStateV2 as PolicyRootState
} from "./StreamPolicyContentRootStateV2.sol";
import {
    StreamPolicyOutputSchemasV2 as PolicyOutputSchemas
} from "../finality/StreamPolicyOutputSchemasV2.sol";

/// @notice Authoritative root state in Router storage, using its fixed library and artist consent.
library StreamMetadataContentRoot {
    struct State {
        mapping(uint256 => bytes32) heads;
        mapping(bytes32 => R.Record) records;
    }

    struct Context {
        address core;
        address artist;
    }

    struct Route {
        address finality;
        address provider;
        address metadata;
        address schemas;
        address manifest;
        address artifacts;
        uint256 readGas;
        bytes32 hash;
    }

    event TokenContentRootPublished(
        uint16 schemaVersion,
        uint256 indexed collectionId,
        bytes32 indexed scopeSubject,
        bytes32 indexed recordHash,
        R.Record record
    );

    function familyState(State storage state, address core, uint256 collectionId)
        public
        view
        returns (bytes32)
    {
        bytes32 head = state.heads[collectionId];
        if (head != 0) return state.records[head].stateHash;
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_EMPTY_CONTENT_ROOT_STATE_V1"),
                block.chainid,
                address(this),
                core,
                collectionId
            )
        );
    }

    function prepare(
        State storage state,
        Context memory ctx,
        R.Publication memory p,
        address publisher
    ) public view returns (R.Record memory r) {
        if (p.collectionId == 0 || p.verifiedManifestRecordHash == 0 || publisher == address(0)) revert R.InvalidContentRootPublication();
        bytes32 previous = state.heads[p.collectionId];
        if (p.expectedPredecessor != previous) {
            revert R.ContentRootLineageChanged(p.expectedPredecessor, previous);
        }
        StreamMetadataRenderer.requireValidUtf8ContentUri(
            "contentRootManifestURI", p.manifestURI, 2048, false
        );
        Route memory route = _route(ctx);
        if (
            _word(
                        ctx.core,
                        abi.encodeCall(
                            IStreamCoreCollectionView.collectionExists, (p.collectionId)
                        ),
                        route.readGas
                    ) != 1
                || _word(
                        ctx.core,
                        abi.encodeCall(
                            IStreamCoreCollectionView.collectionFreezeStatus, (p.collectionId)
                        ),
                        route.readGas
                    ) != 0
        ) {
            revert R.InvalidContentRootPublication();
        }
        r.publication = p;
        r.publisher = publisher;
        (r.authorizationClass, r.grantRevision) = _authority(route, p.collectionId, publisher);
        (uint8 attribution, uint64 generation, bytes32 artistId,, bytes32 bindingHash) = abi.decode(
            _read(
                ctx.artist,
                abi.encodeCall(
                    IStreamArtistAttributionState.collectionArtistState, (p.collectionId)
                ),
                160,
                route.readGas
            ),
            (uint8, uint64, bytes32, uint8, bytes32)
        );
        if (
            (attribution != 2 && attribution != 3) || generation == 0 || artistId == 0
                || bindingHash == 0
        ) revert R.InvalidContentRootPublication();
        r.artistId = artistId;
        r.bindingGeneration = generation;
        r.bindingHash = bindingHash;
        IStreamContentLeafManifest.Manifest memory m = abi.decode(
            _read(
                route.manifest,
                abi.encodeCall(
                    IStreamContentLeafManifest.requireCurrentManifest,
                    (p.verifiedManifestRecordHash, artistId)
                ),
                288,
                route.readGas
            ),
            (IStreamContentLeafManifest.Manifest)
        );
        if (
            m.collectionId != p.collectionId || m.artistId != artistId || m.tokenCount == 0
                || m.contentRoot == 0 || m.manifestHash == 0
        ) revert R.InvalidContentRootPublication();
        r.contentRoot = m.contentRoot;
        r.leafCount = m.tokenCount;
        r.manifestHash = m.manifestHash;
        _schemas(route);
        r.routeHash = route.hash;
        r.stateHash = keccak256(
            abi.encode(
                keccak256("6529STREAM_CONTENT_ROOT_STATE_V1"), block.chainid, address(this), r
            )
        );
    }

    function publish(
        State storage state,
        Context memory ctx,
        R.Publication memory p,
        R.Record memory prepared,
        bytes32 artistConsent
    ) public returns (bytes32 hash) {
        if (artistConsent == 0 || block.timestamp > type(uint64).max) {
            revert R.InvalidContentRootPublication();
        }
        R.Record memory current = prepare(state, ctx, p, msg.sender);
        if (keccak256(abi.encode(current)) != keccak256(abi.encode(prepared))) {
            revert R.InvalidContentRootPublication();
        }
        current.artistConsent = artistConsent;
        current.publishedAt = uint64(block.timestamp);
        hash = keccak256(
            abi.encode(
                keccak256("6529STREAM_CONTENT_ROOT_RECORD_V1"),
                block.chainid,
                address(this),
                current
            )
        );
        if (state.records[hash].publisher != address(0)) revert R.InvalidContentRootPublication();
        state.records[hash] = current;
        state.heads[p.collectionId] = hash;
        emit TokenContentRootPublished(
            1, p.collectionId, _subject(ctx.core, p.collectionId), hash, current
        );
    }

    function readRoot(State storage state, address core, uint256 collectionId, bytes32 subject)
        public
        view
        returns (bytes32, uint64, bytes32)
    {
        if (subject != _subject(core, collectionId)) return (0, 0, 0);
        R.Record storage r = state.records[state.heads[collectionId]];
        return (
            r.contentRoot,
            r.leafCount,
            r.leafCount == 0
                ? bytes32(0)
                : PolicyRootState.state().bindings[state.heads[collectionId]].profileId == 0
                    ? StreamContentRootSchemas.LEAF_SCHEMA
                    : PolicyOutputSchemas.LEAF_SCHEMA
        );
    }

    function readRecord(State storage state, bytes32 hash) public view returns (R.Record memory) {
        if (hash == 0 || state.records[hash].publisher == address(0)) {
            revert R.ContentRootRecordUnknown(hash);
        }
        return state.records[hash];
    }

    function _route(Context memory ctx) private view returns (Route memory r) {
        r.finality = _selected(ctx.core, keccak256("ARTWORK_FINALITY_REGISTRY"), 100_000);
        if (
            _address(
                        ctx.artist,
                        abi.encodeCall(IStreamArtistFinalityBinding.finalityRegistry, ()),
                        100_000
                    ) != r.finality
                || bytes32(
                        _word(
                            ctx.artist,
                            abi.encodeCall(
                                IStreamArtistFinalityBinding.finalityRegistryCodeHash, ()
                            ),
                            100_000
                        )
                    ) != r.finality.codehash
        ) revert R.ContentRootComponentChanged(r.finality);
        r.readGas = _word(
            r.finality,
            abi.encodeCall(
                IStreamGasParameterHost.gasParameter,
                (keccak256("6529STREAM_GGP_FINALITY_COMPONENT_READ_GAS"))
            ),
            100_000
        );
        if (r.readGas < 50_000 || r.readGas > type(uint256).max / 64) {
            revert R.InvalidContentRootPublication();
        }
        if (
            _address(
                        r.finality,
                        abi.encodeCall(IStreamFinalityDeploymentBindings.coreReads, ()),
                        r.readGas
                    ) != ctx.core
                || _address(
                        r.finality,
                        abi.encodeCall(IStreamFinalityDeploymentBindings.sanctionReads, ()),
                        r.readGas
                    ) != ctx.artist
        ) revert R.InvalidContentRootPublication();
        r.provider = _address(
            r.finality,
            abi.encodeCall(IStreamFinalityDeploymentBindings.scopeEvidenceProvider, ()),
            r.readGas
        );
        _pin(
            r.provider,
            bytes32(
                _word(
                    r.finality,
                    abi.encodeCall(
                        IStreamFinalityDeploymentBindings.scopeEvidenceProviderCodeHash, ()
                    ),
                    r.readGas
                )
            )
        );
        r.metadata = _address(
            r.finality,
            abi.encodeCall(IStreamFinalityDeploymentBindings.metadataReads, ()),
            r.readGas
        );
        if (
            r.metadata != _selected(ctx.core, keccak256("COLLECTION_METADATA"), r.readGas)
                || _address(
                        r.provider,
                        abi.encodeCall(IStreamFinalityEvidenceProvider.metadataHost, ()),
                        r.readGas
                    ) != r.metadata
        ) revert R.ContentRootComponentChanged(r.metadata);
        _pin(
            r.metadata,
            bytes32(
                _word(
                    r.provider,
                    abi.encodeCall(IStreamContentRootEvidenceBinding.metadataHostCodeHash, ()),
                    r.readGas
                )
            )
        );
        r.schemas = _address(
            r.provider,
            abi.encodeCall(IStreamContentRootEvidenceBinding.schemaRegistry, ()),
            r.readGas
        );
        _pin(
            r.schemas,
            bytes32(
                _word(
                    r.provider,
                    abi.encodeCall(IStreamContentRootEvidenceBinding.schemaRegistryCodeHash, ()),
                    r.readGas
                )
            )
        );
        if (
            _address(r.metadata, abi.encodeCall(IStreamCollectionMetadataV1.core, ()), r.readGas)
                    != ctx.core
                || _address(
                        r.metadata,
                        abi.encodeCall(IStreamCollectionMetadataV1.schemaRegistry, ()),
                        r.readGas
                    ) != r.schemas
        ) revert R.InvalidContentRootPublication();
        r.manifest = _address(
            r.provider,
            abi.encodeCall(IStreamContentRootEvidenceBinding.contentLeafManifest, ()),
            r.readGas
        );
        _pin(
            r.manifest,
            bytes32(
                _word(
                    r.provider,
                    abi.encodeCall(
                        IStreamContentRootEvidenceBinding.contentLeafManifestCodeHash, ()
                    ),
                    r.readGas
                )
            )
        );
        address checkpoint = _address(
            r.manifest, abi.encodeCall(IStreamContentLeafManifest.contentCheckpoint, ()), r.readGas
        );
        if (
            _address(r.manifest, abi.encodeCall(IStreamContentLeafManifest.core, ()), r.readGas)
                    != ctx.core
                || _address(
                        checkpoint,
                        abi.encodeCall(IStreamOnchainContentCheckpoint.core, ()),
                        r.readGas
                    ) != ctx.core
                || _address(
                        checkpoint,
                        abi.encodeCall(IStreamOnchainContentCheckpoint.metadataRouter, ()),
                        r.readGas
                    ) != address(this)
                || _selected(ctx.core, keccak256("METADATA_ROUTER"), r.readGas) != address(this)
        ) revert R.InvalidContentRootPublication();
        r.artifacts = _address(
            r.finality,
            abi.encodeCall(IStreamFinalityDeploymentBindings.artifactCoverage, ()),
            r.readGas
        );
        if (
            _address(
                        r.manifest,
                        abi.encodeCall(IStreamContentLeafManifest.artifactCoverage, ()),
                        r.readGas
                    ) != r.artifacts
                || _address(
                        r.artifacts,
                        abi.encodeCall(IStreamFinalityArtifactCoverage.schemaRegistry, ()),
                        r.readGas
                    ) != r.schemas
        ) revert R.InvalidContentRootPublication();
        address[10] memory targets = [
            ctx.core,
            ctx.artist,
            address(this),
            r.finality,
            r.provider,
            r.metadata,
            r.schemas,
            r.manifest,
            checkpoint,
            r.artifacts
        ];
        bytes32[10] memory runtimeHashes;
        for (uint256 i; i < targets.length; ++i) {
            runtimeHashes[i] = targets[i].codehash;
        }
        r.hash = keccak256(
            abi.encode(
                keccak256("6529STREAM_CONTENT_ROOT_ROUTE_V1"),
                block.chainid,
                ctx,
                targets,
                runtimeHashes
            )
        );
    }

    function _authority(Route memory r, uint256 collectionId, address publisher)
        private
        view
        returns (uint8, uint64)
    {
        (bool enabled, uint64 revision) = abi.decode(
            _read(
                r.metadata,
                abi.encodeCall(
                    IStreamCollectionMetadataV1.familyWriter,
                    (collectionId, StreamRecordFamilies.SNAPSHOT, 7, publisher)
                ),
                64,
                r.readGas
            ),
            (bool, uint64)
        );
        if (enabled && revision != 0) return (7, revision);
        (enabled, revision) = abi.decode(
            _read(
                r.metadata,
                abi.encodeCall(
                    IStreamCollectionMetadataV1.familyWriter,
                    (0, StreamRecordFamilies.SNAPSHOT, 8, publisher)
                ),
                64,
                r.readGas
            ),
            (bool, uint64)
        );
        if (enabled && revision != 0) return (8, revision);
        revert R.ContentRootAuthorityRequired(publisher);
    }

    function _schemas(Route memory r) private view {
        bytes32[4] memory ids = [
            StreamContentRootSchemas.LEAF_SCHEMA,
            StreamContentRootSchemas.LEAF_CANON,
            StreamContentRootSchemas.ROOT_SCHEMA,
            StreamContentRootSchemas.ROOT_CANON
        ];
        for (uint256 i; i < ids.length; ++i) {
            bytes memory input = abi.encodeCall(IStreamSchemaRegistry.document, (ids[i]));
            bytes memory out = _readBounded(r.schemas, input, 8192, r.readGas);
            IStreamSchemaRegistry.DocumentView memory d =
                abi.decode(out, (IStreamSchemaRegistry.DocumentView));
            if (
                !d.exists || d.status != IStreamSchemaRegistry.DocumentStatus.ACTIVE
                    || uint8(d.specification.kind) != i % 2
                    || keccak256(bytes(d.specification.name)) != ids[i]
                    || d.specification.canonicalizationId != keccak256("RAW_BYTES")
                    || d.specification.contentHash
                        != StreamContentRootSchemas.definitionHash(ids[i])
            ) revert R.InvalidContentRootPublication();
        }
    }

    function _subject(address core, uint256 collectionId) private view returns (bytes32) {
        return StreamMetadataSubjects.scopeSubject(
            block.chainid,
            core,
            StreamFinalityScope(StreamFinalityScopeType.COLLECTION, collectionId, 0, 0)
        );
    }

    function _pin(address target, bytes32 hash) private view {
        if (target.code.length == 0 || target.codehash != hash) {
            revert R.ContentRootComponentChanged(target);
        }
    }

    function _selected(address core, bytes32 kind, uint256 gasCap)
        private
        view
        returns (address target)
    {
        bytes32 hash;
        (target, hash,,,,,,,,) = abi.decode(
            _read(
                core, abi.encodeCall(IStreamCorePointers.getSatellitePointer, (kind)), 320, gasCap
            ),
            (address, bytes32, bool, bytes32, bytes4, address, uint8, bytes32, bytes32, uint64)
        );
        _pin(target, hash);
    }

    function _address(address target, bytes memory input, uint256 gasCap)
        private
        view
        returns (address)
    {
        uint256 word = _word(target, input, gasCap);
        if (word == 0 || word > type(uint160).max) {
            revert R.ContentRootReadFailed(target, bytes4(input));
        }
        return address(uint160(word));
    }

    function _word(address target, bytes memory input, uint256 gasCap)
        private
        view
        returns (uint256)
    {
        return abi.decode(_read(target, input, 32, gasCap), (uint256));
    }

    function _read(address target, bytes memory input, uint256 size, uint256 gasCap)
        private
        view
        returns (bytes memory out)
    {
        out = _readBounded(target, input, size, gasCap);
        if (out.length != size) revert R.ContentRootReadFailed(target, bytes4(input));
    }

    function _readBounded(address target, bytes memory input, uint256 size, uint256 gasCap)
        private
        view
        returns (bytes memory out)
    {
        if (gasleft() <= gasCap + gasCap / 63 + 100_000) {
            revert R.ContentRootReadFailed(target, bytes4(input));
        }
        out = new bytes(size);
        bool ok;
        uint256 actual;
        assembly ("memory-safe") {
            ok := staticcall(gasCap, target, add(input, 32), mload(input), add(out, 32), size)
            actual := returndatasize()
        }
        if (!ok || actual > size) revert R.ContentRootReadFailed(target, bytes4(input));
        assembly ("memory-safe") { mstore(out, actual) }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import {
    IStreamGasParameterHost as G
} from "../../interfaces/stream/parameters/IStreamGasParameterHost.sol";
import {
    IStreamGovernedParameterAuthority as A
} from "../../interfaces/stream/parameters/IStreamGovernedParameterAuthority.sol";

/// @notice Router-owned display GGPs in appended namespaced storage; no provider parameter borrowing.
/// @dev Uses the original GGP V2 commitments and delayed, monotonic, at-most-2x transition.
library StreamMetadataDisplayParameters {
    bytes32 internal constant OUTER_GAS = keccak256("6529STREAM_GGP_ROUTER_LIVE_ATTRIBUTION_GAS");
    bytes32 internal constant READ_GAS =
        keccak256("6529STREAM_GGP_ROUTER_LIVE_ATTRIBUTION_READ_GAS");
    bytes32 internal constant MEMBERSHIP_GAS =
        keccak256("6529STREAM_GGP_ROUTER_LIVE_ATTRIBUTION_MEMBERSHIP_GAS");
    bytes32 internal constant RETURN_GAS =
        keccak256("6529STREAM_GGP_ROUTER_LIVE_ATTRIBUTION_RETURN_GAS");
    bytes32 internal constant BUNDLE_READ_GAS = keccak256("6529STREAM_GGP_ROUTER_BUNDLE_READ_GAS");
    bytes32 internal constant BUNDLE_RENDER_GAS =
        keccak256("6529STREAM_GGP_ROUTER_BUNDLE_RENDER_GAS");
    bytes32 internal constant FULL_VIEW_GAS = keccak256("6529STREAM_GGP_ROUTER_FULL_VIEW_GAS");
    bytes32 private constant SLOT =
        keccak256("6529STREAM_METADATA_ROUTER_DISPLAY_PARAMETERS_STORAGE_V1");
    bytes32 private constant SCOPE =
        0x9533611d402c2b44cf950a4a8900d25f6829bfac541dc4d5353094f966bb1a71;
    bytes32 private constant STATE =
        0x5059a253d3f7dd63b5d9fd1f0568caf72967f501a3db678b31cefe911334159c;

    struct Row {
        uint256 value;
        uint256 floor;
        uint8 failureClass;
        uint64 revision;
        bytes32 lastActionId;
    }

    struct Store {
        mapping(bytes32 => Row) rows;
        bytes32 authorityCodeHash;
    }
    event GasParameterRegistered(
        uint16 schemaVersion,
        bytes32 indexed parameterId,
        string name,
        uint256 genesisValue,
        uint256 floor,
        uint8 failureClass
    );
    event GasParameterUpdated(
        uint16 schemaVersion,
        bytes32 indexed parameterId,
        address indexed host,
        bytes32 indexed actionId,
        uint256 oldValue,
        uint256 newValue,
        uint256 floor
    );

    function _store() private pure returns (Store storage s) {
        bytes32 slot = SLOT;
        assembly ("memory-safe") { s.slot := slot }
    }

    function initialize(address authority) internal {
        Store storage s = _store();
        s.authorityCodeHash = authority.codehash;
        _register(s, OUTER_GAS, "ROUTER_LIVE_ATTRIBUTION_GAS", 8000000, 1);
        _register(s, READ_GAS, "ROUTER_LIVE_ATTRIBUTION_READ_GAS", 250000, 1);
        _register(s, MEMBERSHIP_GAS, "ROUTER_LIVE_ATTRIBUTION_MEMBERSHIP_GAS", 2000000, 1);
        _register(s, RETURN_GAS, "ROUTER_LIVE_ATTRIBUTION_RETURN_GAS", 2000000, 3);
        _register(s, BUNDLE_READ_GAS, "ROUTER_BUNDLE_READ_GAS", 2000000, 2);
        _register(s, BUNDLE_RENDER_GAS, "ROUTER_BUNDLE_RENDER_GAS", 8000000, 2);
        _register(s, FULL_VIEW_GAS, "ROUTER_FULL_VIEW_GAS", 60000000, 2);
    }

    function _register(
        Store storage s,
        bytes32 id,
        string memory name,
        uint256 amount,
        uint8 failureClass
    ) private {
        if (s.rows[id].revision != 0) revert G.GasParameterAlreadyRegistered(id);
        s.rows[id] = Row(amount, amount, failureClass, 1, 0);
        emit GasParameterRegistered(2, id, name, amount, amount, failureClass);
    }

    function ids() internal pure returns (bytes32[] memory result) {
        result = new bytes32[](7);
        result[0] = OUTER_GAS;
        result[1] = READ_GAS;
        result[2] = MEMBERSHIP_GAS;
        result[3] = RETURN_GAS;
        result[4] = BUNDLE_READ_GAS;
        result[5] = BUNDLE_RENDER_GAS;
        result[6] = FULL_VIEW_GAS;
    }

    function info(bytes32 id) internal view returns (uint256, uint256, uint8, uint64) {
        Row storage r = _store().rows[id];
        return (r.value, r.floor, r.failureClass, r.revision);
    }

    function value(bytes32 id) internal view returns (uint256) {
        Row storage r = _row(id);
        return r.value;
    }

    function _row(bytes32 id) private view returns (Row storage r) {
        r = _store().rows[id];
        if (r.revision == 0) revert G.GasParameterUnknown(id);
    }

    function transition(bytes32 id, uint256 next)
        public
        view
        returns (bytes32 scope, bytes32 oldHash, bytes32 newHash)
    {
        Row storage r = _row(id);
        if (next <= r.value) revert G.GasParameterNotARaise(id, r.value, next);
        if (next - r.value > r.value) revert G.GasParameterRaiseBoundExceeded(id, r.value, next);
        if (r.revision == type(uint64).max) revert G.GasParameterRevisionOverflow(id);
        scope = keccak256(abi.encode(SCOPE, block.chainid, address(this), id));
        oldHash = _state(scope, r, r.value, r.revision);
        newHash = _state(scope, r, next, r.revision + 1);
    }

    function _state(bytes32 scope, Row storage r, uint256 amount, uint64 revision)
        private
        view
        returns (bytes32)
    {
        return keccak256(abi.encode(STATE, scope, amount, r.floor, r.failureClass, revision));
    }

    function raise(address authority, bytes32 id, uint256 next) public {
        if (msg.sender != authority || authority == address(0)) {
            revert G.GasParameterNotAuthority(msg.sender);
        }
        if (authority.code.length == 0 || authority.codehash != _store().authorityCodeHash) {
            revert G.GasParameterInvalidAuthority(authority);
        }
        if (authority.code.length == 23) {
            bytes3 prefix;
            assembly ("memory-safe") {
                extcodecopy(authority, 0, 0, 3)
                prefix := mload(0)
            }
            if (prefix == 0xef0100) revert G.GasParameterInvalidAuthority(authority);
        }
        bytes memory marker =
            _read(authority, abi.encodeCall(A.isStreamGovernedParameterAuthority, ()), 32);
        if (abi.decode(marker, (uint256)) != 1) revert G.GasParameterInvalidAuthority(authority);
        (bytes32 scope, bytes32 oldHash, bytes32 newHash) = transition(id, next);
        bytes memory context = _read(authority, abi.encodeCall(A.currentAction, ()), 192);
        uint256 executingWord;
        uint256 classWord;
        assembly ("memory-safe") {
            executingWord := mload(add(context, 32))
            classWord := mload(add(context, 96))
        }
        if (executingWord > 1 || classWord > 255) revert G.GasParameterActionContextInvalid();
        (
            bool executing,
            bytes32 actionId,
            uint8 actionClass,
            bytes32 actualScope,
            bytes32 actualOld,
            bytes32 actualNew
        ) = abi.decode(context, (bool, bytes32, uint8, bytes32, bytes32, bytes32));
        if (!executing) revert G.GasParameterActionNotExecuting();
        if (actionId == 0) revert G.GasParameterActionIdZero();
        if (actionClass != 1) revert G.GasParameterActionClassMismatch(1, actionClass);
        if (actualScope != scope) revert G.GasParameterScopeHashMismatch(scope, actualScope);
        if (actualOld != oldHash) revert G.GasParameterOldStateHashMismatch(oldHash, actualOld);
        if (actualNew != newHash) revert G.GasParameterNewStateHashMismatch(newHash, actualNew);
        Row storage r = _row(id);
        if (r.lastActionId == actionId) revert G.GasParameterActionAlreadyApplied(id, actionId);
        uint256 old = r.value;
        r.value = next;
        ++r.revision;
        r.lastActionId = actionId;
        emit GasParameterUpdated(2, id, address(this), actionId, old, next, r.floor);
    }

    // The original canonical authority read uses gas() with fixed-size returndata copying.
    function _read(address target, bytes memory data, uint256 length)
        private
        view
        returns (bytes memory result)
    {
        result = new bytes(length);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(gas(), target, add(data, 32), mload(data), add(result, 32), length)
            size := returndatasize()
        }
        if (!ok || size != length) revert G.GasParameterActionContextInvalid();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import {
    IStreamScriptBundles as B,
    IStreamScriptBundleSelection
} from "../../interfaces/stream/metadata/IStreamScriptBundles.sol";
import {
    StreamMetadataDisplayParameters as BundleGas
} from "./StreamMetadataDisplayParameters.sol";
import { StreamMetadataBundleRenderer } from "./StreamMetadataBundleRenderer.sol";
import { StreamMetadataTokenRenderer } from "./StreamMetadataTokenRenderer.sol";

import "./StreamMetadataRecoveryRoutes.sol";
import "../finality/StreamFinalityEntropyServing.sol";
import "./StreamMetadataTokenReads.sol";
import "./StreamMetadataRenderPreparation.sol";
import "../../interfaces/stream/metadata/IStreamMetadataTokenRendering.sol";
import "../../interfaces/stream/metadata/IStreamMetadataRenderingProfile.sol";

/// @notice Nonrecursive serving of independently selected finality families.
/// @dev First profile is the existing stable presentation/linked renderer ABI. Unsupported
///      mixed context/dependency profiles fail closed. Raw source reads never call tokenURI.
library StreamMetadataFinalityServing {
    bytes32 private constant PROFILE = keccak256("6529STREAM_ROUTER_STABLE_PRESENTATION_V1");
    // Complete cold storage reads include up to 16 KiB token data and 14,592 bytes
    // of Router source fields. Do not rely on a provider incidentally warming them.
    uint256 private constant SOURCE_GAS = 2000000;
    uint256 private constant RENDER_GAS = 8000000;

    struct Sources {
        address display;
        address renderer;
        IStreamMetadataServingFacts.ServingSource metadata;
        bytes artist;
        B.Selection bundle;
    }
    error MetadataFrozenProfileUnsupported(address target);
    error MetadataFrozenBytesInvalid(address target);
    error InvalidToken(uint256 tokenId);
    error TokenEntropyNotFinalized(uint256 tokenId);

    function token(
        mapping(uint256 => IStreamMetadataServingFacts.ArtistPresentation) storage presentations,
        mapping(uint256 => StreamMetadataRecoveryRoutes.OriginalAnchor) storage anchors,
        StreamMetadataRecoveryRoutes.Environment memory e,
        StreamMetadataRecoveryRoutes.OriginalAnchor memory durable,
        uint256 id,
        bool allowBurned,
        bool asURI
    ) public view returns (bool frozen, string memory result) {
        (uint256 collection, uint256 serial) = _identity(e.core, id, allowBurned);
        (StreamMetadataRecoveryRoutes.Context memory c, bool active) = StreamMetadataRecoveryRoutes.context(
            e,
            presentations[collection].locked,
            anchors[collection],
            durable,
            StreamFinalityScope(StreamFinalityScopeType.TOKEN, collection, id, 0)
        );
        if (!active) return (false, "");
        Sources memory s = _sources(c, true);
        return (true, _render(c, serial, s, asURI ? 1 : 0));
    }

    function fullToken(
        mapping(uint256 => IStreamMetadataServingFacts.ArtistPresentation) storage presentations,
        mapping(uint256 => StreamMetadataRecoveryRoutes.OriginalAnchor) storage anchors,
        StreamMetadataRecoveryRoutes.Environment memory e,
        StreamMetadataRecoveryRoutes.OriginalAnchor memory durable,
        uint256 id,
        bool asHTML
    ) public view returns (bool frozen, string memory result) {
        (uint256 collection, uint256 serial) = _identity(e.core, id, true);
        (StreamMetadataRecoveryRoutes.Context memory c, bool active) = StreamMetadataRecoveryRoutes.context(
            e,
            presentations[collection].locked,
            anchors[collection],
            durable,
            StreamFinalityScope(StreamFinalityScopeType.TOKEN, collection, id, 0)
        );
        if (!active) return (false, "");
        return (true, _render(c, serial, _sources(c, true), asHTML ? 3 : 2));
    }

    function historicalFullToken(
        mapping(uint256 => IStreamMetadataServingFacts.ArtistPresentation) storage presentations,
        mapping(uint256 => StreamMetadataRecoveryRoutes.OriginalAnchor) storage anchors,
        StreamMetadataRecoveryRoutes.Environment memory e,
        StreamMetadataRecoveryRoutes.OriginalAnchor memory durable,
        uint256 id
    ) public view returns (bool frozen, string memory result) {
        (uint256 collection, uint256 serial) = _identity(e.core, id, true);
        (StreamMetadataRecoveryRoutes.Context memory c, bool active) = StreamMetadataRecoveryRoutes.context(
            e,
            presentations[collection].locked,
            anchors[collection],
            durable,
            StreamFinalityScope(StreamFinalityScopeType.TOKEN, collection, id, 0)
        );
        if (!active) return (false, "");
        return (true, _render(c, serial, _sources(c, true), 4));
    }

    function _render(
        StreamMetadataRecoveryRoutes.Context memory c,
        uint256 serial,
        Sources memory s,
        uint8 mode
    ) private view returns (string memory result) {
        uint256 id = c.scope.tokenId;
        (address entropy, address entropyAdapter) = StreamMetadataRecoveryRoutes.hostWithAdapter(
            c, StreamFinalityDomains.COMPONENT_ENTROPY_COORDINATOR
        );
        (bytes32 seed, bool finalized) =
            StreamFinalityEntropyServing.read(entropyAdapter, entropy, id);
        if (!finalized) revert TokenEntropyNotFinalized(id);
        bytes memory encodedData =
            _dynamic(c.core, abi.encodeCall(IStreamCoreMint.tokenData, (id)), 16448, SOURCE_GAS);
        bytes memory data = abi.decode(encodedData, (bytes));
        if (keccak256(encodedData) != keccak256(abi.encode(data))) {
            revert MetadataFrozenBytesInvalid(c.core);
        }
        StreamMetadataRenderTypes.Token memory input = StreamMetadataRenderTypes.Token(
            id, c.scope.collectionId, serial, seed, true, "final", data, true
        );
        if (mode == 2 || mode == 3) {
            (,,, bool burned) = abi.decode(
                StreamMetadataRecoveryRoutes.read(
                    c.core,
                    abi.encodeCall(IStreamCoreIdentity.tokenCollectionIdentity, (id)),
                    128,
                    150000
                ),
                (bool, uint256, uint256, bool)
            );
            if (burned) input.state = "burned";
        }
        // Keep the legacy default call and its exact bytes untouched. Full views and
        // bundle views use separate, explicit selectors and larger bounded output envelopes.
        bytes memory callData;
        if (s.bundle.bundleId != 0) {
            callData = abi.encodeWithSignature(
                "renderBundleForFinality(uint8,bytes)",
                mode == 4 ? 2 : mode,
                abi.encode(
                    input,
                    s.metadata,
                    s.artist,
                    s.bundle,
                    address(this),
                    block.chainid,
                    BundleGas.value(BundleGas.BUNDLE_READ_GAS)
                )
            );
        } else if (mode >= 2) {
            callData = abi.encodeWithSignature(
                "fullViewForFinality(bool,bytes)",
                mode == 3,
                abi.encode(input, s.metadata, s.artist)
            );
        } else {
            callData = abi.encodeCall(
                IStreamMetadataTokenRendering.renderForFinality,
                (mode == 1, abi.encode(input, s.metadata, s.artist))
            );
        }
        bytes memory raw = mode >= 2
            ? _fullDynamic(s.renderer, callData, BundleGas.value(BundleGas.FULL_VIEW_GAS))
            : _dynamic(
                s.renderer,
                callData,
                65536,
                s.bundle.bundleId != 0 ? BundleGas.value(BundleGas.BUNDLE_RENDER_GAS) : RENDER_GAS
            );
        result = abi.decode(raw, (string));
        if (keccak256(raw) != keccak256(abi.encode(result))) {
            revert MetadataFrozenBytesInvalid(s.renderer);
        }
        return result;
    }

    function collection(
        mapping(uint256 => IStreamMetadataServingFacts.ArtistPresentation) storage presentations,
        mapping(uint256 => StreamMetadataRecoveryRoutes.OriginalAnchor) storage anchors,
        StreamMetadataRecoveryRoutes.Environment memory e,
        StreamMetadataRecoveryRoutes.OriginalAnchor memory durable,
        uint256 id
    ) public view returns (bool frozen, string memory result) {
        (StreamMetadataRecoveryRoutes.Context memory c, bool active) = StreamMetadataRecoveryRoutes.context(
            e,
            presentations[id].locked,
            anchors[id],
            durable,
            StreamFinalityScope(StreamFinalityScopeType.COLLECTION, id, 0, 0)
        );
        if (!active) return (false, "");
        Sources memory s = _sources(c, false);
        result = StreamMetadataRenderPreparation.collectionURI(
            s.metadata.name, s.metadata.description, s.metadata.imageURI
        );
        return (true, result);
    }

    function _sources(StreamMetadataRecoveryRoutes.Context memory c, bool tokenView)
        private
        view
        returns (Sources memory s)
    {
        uint256 id = c.scope.collectionId;
        s.display =
            StreamMetadataRecoveryRoutes.host(c, StreamFinalityDomains.COMPONENT_METADATA_ROUTER);
        IStreamMetadataServingFacts.ServingFacts memory display = _facts(s.display, id);
        if (!display.displayMetadataLocked || !display.artistIdentityLocked) {
            revert MetadataFrozenProfileUnsupported(s.display);
        }
        IStreamMetadataServingFacts.ServingSource memory d = _source(s.display, id);
        address mediaHost =
            StreamMetadataRecoveryRoutes.host(c, StreamFinalityDomains.COMPONENT_MEDIA_MANIFEST);
        IStreamMetadataServingFacts.ServingFacts memory media = _facts(mediaHost, id);
        IStreamMetadataServingFacts.ServingSource memory m = _source(mediaHost, id);
        if (
            !media.mediaLocked || !media.baseURILocked
                || media.imageURIHash != keccak256(bytes(m.imageURI))
                || media.animationBaseURIHash != keccak256(bytes(m.animationBaseURI))
        ) {
            revert MetadataFrozenProfileUnsupported(mediaHost);
        }
        s.metadata = StreamMetadataRenderPreparation.prepareMetadata(
            d.name, d.description, m.imageURI, m.animationBaseURI
        );
        if (!tokenView) return s;
        s.renderer = _renderer(c, id);
        if (display.mode == keccak256("ONCHAIN")) {
            address scriptHost =
                StreamMetadataRecoveryRoutes.host(c, StreamFinalityDomains.COMPONENT_SCRIPT_SOURCE);
            if (_facts(scriptHost, id).presentationProfile == StreamMetadataBundleRenderer.PROFILE)
            {
                s.bundle = _bundle(c, id, scriptHost, s.renderer);
            } else {
                s.metadata.script = _script(c, id, s.renderer);
            }
        } else if (display.mode != keccak256("OFFCHAIN")) {
            revert MetadataFrozenProfileUnsupported(s.display);
        }
        IStreamMetadataServingFacts.ArtistPresentation memory a = abi.decode(
            StreamMetadataRecoveryRoutes.read(
                s.display,
                abi.encodeCall(IStreamMetadataServingFacts.artistPresentation, (id)),
                384,
                150000
            ),
            (IStreamMetadataServingFacts.ArtistPresentation)
        );
        if (
            !a.locked || a.registry == address(0) || a.registryCodeHash == 0 || a.artistId == 0
                || a.bindingGeneration == 0 || a.bindingHash == 0 || a.nominatedArtist == address(0)
                || a.identityRecordHash == 0 || a.acceptanceRecordHash == 0 || a.snapshotHash == 0
        ) {
            revert MetadataFrozenProfileUnsupported(s.display);
        }
        s.artist = StreamMetadataRenderPreparation.artistFields(
            a.nominatedArtist, a.identityRecordHash, a.acceptanceRecordHash
        );
    }

    function _renderer(StreamMetadataRecoveryRoutes.Context memory c, uint256 id)
        private
        view
        returns (address renderer)
    {
        address rendererHost =
            StreamMetadataRecoveryRoutes.host(c, StreamFinalityDomains.COMPONENT_RENDERER);
        IStreamMetadataServingFacts.ServingFacts memory rendering = _facts(rendererHost, id);
        renderer = rendering.renderer;
        if (renderer.code.length == 0 || rendering.rendererCodeHash != renderer.codehash) {
            revert MetadataFrozenProfileUnsupported(rendererHost);
        }
        if (rendering.presentationProfile == StreamMetadataBundleRenderer.PROFILE) {
            address context = StreamMetadataRecoveryRoutes.host(
                c, StreamFinalityDomains.COMPONENT_RENDER_CONTEXT
            );
            if (_facts(context, id).presentationProfile != StreamMetadataBundleRenderer.PROFILE) {
                revert MetadataFrozenProfileUnsupported(context);
            }
            bytes memory actual = StreamMetadataRecoveryRoutes.read(
                renderer, abi.encodeWithSignature("renderingProfile()"), 96, 150000
            );
            (bytes32 p, bytes32 h, bytes32 d) = StreamMetadataBundleRenderer.renderingProfile();
            if (keccak256(actual) != keccak256(abi.encode(p, h, d))) {
                revert MetadataFrozenProfileUnsupported(renderer);
            }
            return renderer;
        }
        (bytes32 contextHash,) = _profile(renderer);
        address contextHost =
            StreamMetadataRecoveryRoutes.host(c, StreamFinalityDomains.COMPONENT_RENDER_CONTEXT);
        (bytes32 selectedContext,) = _profile(contextHost);
        if (selectedContext != contextHash) revert MetadataFrozenProfileUnsupported(contextHost);
    }

    function _bundle(
        StreamMetadataRecoveryRoutes.Context memory c,
        uint256 id,
        address scriptHost,
        address renderer
    ) private view returns (B.Selection memory selection) {
        IStreamMetadataServingFacts.ServingFacts memory f = _facts(scriptHost, id);
        if (!f.scriptLocked || !f.dependenciesLocked) {
            revert MetadataFrozenProfileUnsupported(scriptHost);
        }
        selection = abi.decode(
            StreamMetadataRecoveryRoutes.read(
                scriptHost,
                abi.encodeCall(IStreamScriptBundleSelection.collectionScriptBundle, (id)),
                128,
                SOURCE_GAS
            ),
            (B.Selection)
        );
        B.Facts memory b = StreamMetadataBundleRenderer.facts(selection);
        if (b.payloadHash != f.scriptHash || b.totalBytes != f.scriptBytes) {
            revert MetadataFrozenBytesInvalid(scriptHost);
        }
        address dependencyHost =
            StreamMetadataRecoveryRoutes.host(c, StreamFinalityDomains.COMPONENT_DEPENDENCY_SOURCE);
        IStreamMetadataServingFacts.ServingFacts memory dependencies = _facts(dependencyHost, id);
        B.Selection memory dep = abi.decode(
            StreamMetadataRecoveryRoutes.read(
                dependencyHost,
                abi.encodeCall(IStreamScriptBundleSelection.collectionScriptBundle, (id)),
                128,
                SOURCE_GAS
            ),
            (B.Selection)
        );
        B.Facts memory df = StreamMetadataBundleRenderer.facts(dep);
        if (
            !dependencies.dependenciesLocked || dep.host != selection.host
                || dep.codeHash != selection.codeHash || df.libraryBundle != b.libraryBundle
        ) revert MetadataFrozenProfileUnsupported(dependencyHost);
        bytes memory actual = StreamMetadataRecoveryRoutes.read(
            renderer, abi.encodeWithSignature("renderingProfile()"), 96, 150000
        );
        (bytes32 p, bytes32 h, bytes32 d) = StreamMetadataBundleRenderer.renderingProfile();
        if (keccak256(actual) != keccak256(abi.encode(p, h, d))) {
            revert MetadataFrozenProfileUnsupported(renderer);
        }
    }

    function _script(StreamMetadataRecoveryRoutes.Context memory c, uint256 id, address renderer)
        private
        view
        returns (string memory)
    {
        address scriptHost =
            StreamMetadataRecoveryRoutes.host(c, StreamFinalityDomains.COMPONENT_SCRIPT_SOURCE);
        IStreamMetadataServingFacts.ServingFacts memory script = _facts(scriptHost, id);
        string memory rawScript = _source(scriptHost, id).script;
        if (
            !script.scriptLocked || script.scriptBytes != bytes(rawScript).length
                || bytes(rawScript).length == 0 || script.scriptHash != keccak256(bytes(rawScript))
        ) {
            revert MetadataFrozenProfileUnsupported(scriptHost);
        }
        address dependencyHost =
            StreamMetadataRecoveryRoutes.host(c, StreamFinalityDomains.COMPONENT_DEPENDENCY_SOURCE);
        IStreamMetadataServingFacts.ServingFacts memory dependencies = _facts(dependencyHost, id);
        (, bytes32 selectedDependencies) = _profile(dependencyHost);
        (, bytes32 dependencyHash) = _profile(renderer);
        if (!dependencies.dependenciesLocked || selectedDependencies != dependencyHash) {
            revert MetadataFrozenProfileUnsupported(dependencyHost);
        }
        return StreamMetadataRenderPreparation.prepareScript(rawScript);
    }

    function _profile(address target)
        private
        view
        returns (bytes32 contextHash, bytes32 dependencyHash)
    {
        bytes32 presentation;
        (presentation, contextHash, dependencyHash) = abi.decode(
            StreamMetadataRecoveryRoutes.read(
                target,
                abi.encodeCall(IStreamMetadataRenderingProfile.renderingProfile, ()),
                96,
                150000
            ),
            (bytes32, bytes32, bytes32)
        );
        if (presentation != PROFILE || contextHash == 0 || dependencyHash == 0) {
            revert MetadataFrozenProfileUnsupported(target);
        }
    }

    function _facts(address host, uint256 id)
        private
        view
        returns (IStreamMetadataServingFacts.ServingFacts memory f)
    {
        f = abi.decode(
            StreamMetadataRecoveryRoutes.read(
                host,
                abi.encodeCall(IStreamMetadataServingFacts.collectionServingFacts, (id)),
                512,
                SOURCE_GAS
            ),
            (IStreamMetadataServingFacts.ServingFacts)
        );
        if (
            (f.presentationProfile != PROFILE
                    && f.presentationProfile != StreamMetadataBundleRenderer.PROFILE)
                || !f.configured
        ) {
            revert MetadataFrozenProfileUnsupported(host);
        }
    }

    function _source(address host, uint256 id)
        private
        view
        returns (IStreamMetadataServingFacts.ServingSource memory s)
    {
        bytes memory raw = _dynamic(
            host,
            abi.encodeCall(IStreamMetadataServingFacts.collectionServingSource, (id)),
            14944,
            SOURCE_GAS
        );
        s = abi.decode(raw, (IStreamMetadataServingFacts.ServingSource));
        if (
            keccak256(raw) != keccak256(abi.encode(s)) || bytes(s.name).length > 256
                || bytes(s.description).length > 2048 || bytes(s.imageURI).length > 2048
                || bytes(s.animationBaseURI).length > 2048 || bytes(s.script).length > 8192
        ) {
            revert MetadataFrozenBytesInvalid(host);
        }
    }

    function _identity(address core, uint256 id, bool allowBurned)
        private
        view
        returns (uint256 cid, uint256 serial)
    {
        bool exists;
        bool burned;
        (exists, cid, serial, burned) = abi.decode(
            StreamMetadataRecoveryRoutes.read(
                core, abi.encodeCall(IStreamCoreIdentity.tokenCollectionIdentity, (id)), 128, 150000
            ),
            (bool, uint256, uint256, bool)
        );
        uint8 lifecycle = abi.decode(
            StreamMetadataRecoveryRoutes.read(
                core, abi.encodeCall(IStreamCoreIdentity.tokenLifecycle, (id)), 32, 150000
            ),
            (uint8)
        );
        if (
            !exists || cid == 0 || serial == 0 || (burned && !allowBurned)
                || (burned ? lifecycle != 3 : lifecycle != 2)
        ) revert InvalidToken(id);
    }

    function _fullDynamic(address target, bytes memory input, uint256 cap)
        private
        view
        returns (bytes memory output)
    {
        uint256 required = cap + cap / 63 + 1000000;
        if (gasleft() <= required) {
            revert StreamMetadataRecoveryRoutes.MetadataRecoveryParentGas(gasleft(), required);
        }
        bool ok;
        uint256 length;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(input, 32), mload(input), 0, 0)
            length := returndatasize()
        }
        // Do not allocate the maximum envelope for a small full view.
        if (!ok || length < 64 || length > 6000000) revert MetadataFrozenBytesInvalid(target);
        output = new bytes(length);
        assembly ("memory-safe") { returndatacopy(add(output, 32), 0, length) }
    }

    function _dynamic(address target, bytes memory input, uint256 limit, uint256 cap)
        private
        view
        returns (bytes memory output)
    {
        output = new bytes(limit);
        uint256 required = cap + cap / 63 + 100000;
        if (gasleft() <= required) {
            revert StreamMetadataRecoveryRoutes.MetadataRecoveryParentGas(gasleft(), required);
        }
        bool ok;
        uint256 returned;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(input, 32), mload(input), add(output, 32), limit)
            returned := returndatasize()
        }
        if (!ok || returned > limit || returned < 64) revert MetadataFrozenBytesInvalid(target);
        assembly ("memory-safe") { mstore(output, returned) }
    }
}

