        address original,
        address current,
        bytes calldata encodedSuite
    ) external view returns (address);
}

/// @notice Original Metadata ancestry through the actual complete recovered op60 prefix.
/// @dev The enclosing selector authenticates the original/current runtime, current suite,
/// Router and all seven matching completion markers. This adds no publication authority:
/// the original Metadata host still consumes original authorization IDs and record domains.
library StreamMetadataRecoveredArtistSelection {
    function requireAncestor(
        address core,
        address original,
        address current,
        T.SuiteConfiguration memory next,
        uint256 cap
    ) public view {
        _predecessor(current, original, cap);
        address coordinator = abi.decode(
            _read(
                original,
                abi.encodeCall(IStreamArtistIngressBinding.operationCoordinator, ()),
                32,
                cap
            ),
            (address)
        );
        T.SuiteConfiguration memory source =
            StreamMetadataArtistConfiguration.suite(coordinator, cap);
        if (
            source.registry != original || source.core != core || next.registry != current
                || source.mintManager != next.mintManager
                || source.roleRegistry != next.roleRegistry || source.metadata != next.metadata
                || source.primaryResolver != next.primaryResolver
                || source.royaltyResolver != next.royaltyResolver
                || source.primaryRevenueClass != next.primaryRevenueClass
                || source.validator != next.validator
        ) revert M.MetadataHostNotSelected();
        RH.OriginEnvironment memory origin;
        origin.chainId = block.chainid;
        origin.registry = original;
        origin.coordinator = coordinator;
        origin.archive = source.archive;
        origin.owners = source.owners;
        for (uint256 i; i < 7; ++i) {
            origin.ownerCodeHashes[i] = source.owners[i].codehash;
        }
        origin.core = core;
        origin.manager = source.mintManager;
        origin.suiteConfigurationHash = keccak256(abi.encode(source));
        bytes32 hash = RH.originHash(origin);
        bytes memory raw =
            _read(next.owners[2], abi.encodeCall(R.recoveredHydrationOrigin, (hash)), 672, cap);
        RH.OriginEnvironment memory saved = abi.decode(raw, (RH.OriginEnvironment));
        if (keccak256(raw) != keccak256(abi.encode(saved)) || RH.originHash(saved) != hash) {
            revert M.MetadataHostNotSelected();
        }
        // original != current, so the owner's local-origin branch cannot satisfy this query.
        // The only imported-origin producer is immutable installOwnerPrefix during complete
        // op60. Its source certificate joins the flattened original eras and all seven owners;
        // the enclosing selector checks every actual nonzero completion marker. No dynamic
        // journal or unbounded predecessor walk is read at publication time.
    }

    function repeatedAncestor(
        address core,
        address original,
        address current,
        bytes memory encodedSuite
    ) public view returns (address coordinator) {
        T.SuiteConfiguration memory next = abi.decode(encodedSuite, (T.SuiteConfiguration));
        _framePredecessor(current, original);
        coordinator = abi.decode(
            _frameRead(
                original, abi.encodeCall(IStreamArtistIngressBinding.operationCoordinator, ()), 32
            ),
            (address)
        );
        (T.SuiteConfiguration memory source, bytes32 suiteHash, bytes32[16] memory runtimeHashes) =
            _frameSuite(coordinator);
        if (
            source.registry != original || source.core != core || next.registry != current
                || source.mintManager != next.mintManager
                || source.roleRegistry != next.roleRegistry || source.metadata != next.metadata
                || source.primaryResolver != next.primaryResolver
                || source.royaltyResolver != next.royaltyResolver
                || source.primaryRevenueClass != next.primaryRevenueClass
                || source.validator != next.validator
        ) revert M.MetadataHostNotSelected();
        RH.OriginEnvironment memory origin;
        origin.chainId = block.chainid;
        origin.registry = original;
        origin.coordinator = coordinator;
        origin.archive = source.archive;
        origin.owners = source.owners;
        for (uint256 i; i < 7; ++i) {
            origin.ownerCodeHashes[i] = runtimeHashes[i];
        }
        origin.core = core;
        origin.manager = source.mintManager;
        origin.suiteConfigurationHash = suiteHash;
        bytes32 hash = RH.originHash(origin);
        bytes32 completion = currentCompletion(core, next.metadata, next.owners);
        (bytes32 actual, bytes32 committed, uint64 revision, uint8 index) = abi.decode(
            _frameRead(
                next.owners[2],
                abi.encodeCall(R.recoveredHydrationImportedOriginCertificate, (hash)),
                128
            ),
            (bytes32, bytes32, uint64, uint8)
        );
        if (
            actual != hash || committed == 0 || committed != completion || revision == 0
                || index != 2
        ) {
            revert M.MetadataHostNotSelected();
        }
        // This imported-only certificate has no local-origin branch.
        // The only imported-origin producer is immutable installOwnerPrefix during complete
        // op60. Its source certificate joins the flattened original eras and all seven owners;
        // the enclosing selector checks every actual nonzero completion marker. No dynamic
        // journal or unbounded predecessor walk is read at publication time.
    }

    /// @notice Fixed current Router/completion proof inside one governed dependency frame.
    /// @dev The enclosing Metadata selector STATICCALLs this fixed worker with the complete cap.
    /// Inner calls share that finite frame; any refusal, short return or exhausted frame rejects.
    function currentCompletion(address core, address expectedRouter, address[7] memory owners)
        private
        view
        returns (bytes32 completion)
    {
        (address router, bytes32 runtime,,,,,,,,) = abi.decode(
            _frameRead(
                core,
                abi.encodeCall(
                    IStreamCorePointers.getSatellitePointer, (keccak256("METADATA_ROUTER"))
                ),
                320
            ),
            (address, bytes32, bool, bytes32, bytes4, address, uint8, bytes32, bytes32, uint64)
        );
        if (router != expectedRouter) revert M.MetadataHostNotSelected();
        if (router.code.length == 0 || router.codehash != runtime) {
            revert M.MetadataDependencyChanged(router);
        }
        if (
            abi.decode(
                    _frameRead(router, abi.encodeCall(IStreamArtistOwner.core, ()), 32), (address)
                ) != core
        ) {
            revert M.MetadataHostNotSelected();
        }
        for (uint256 i; i < 7; ++i) {
            bytes32 actual = _frameWord(
                owners[i],
                IStreamArtistAuthorityHydrationOwner.authorityHydrationCommitment.selector
            );
            if (actual == 0 || (i != 0 && actual != completion)) {
                revert M.MetadataHostNotSelected();
            }
            completion = actual;
        }
    }

    /// @dev Closed zero-argument, full-word getters share the same finite outer frame.
    /// A bytes32/uint256 return has no narrower ABI canonicality condition. Scratch memory
    /// replaces only the previous temporary input/output byte arrays, not any validation.
    function _frameWord(address target, bytes4 selector) private view returns (bytes32 value) {
        if (target.code.length == 0) revert M.MetadataReadFailed(target);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            mstore(0, selector)
            ok := staticcall(gas(), target, 0, 4, 0, 32)
            size := returndatasize()
            value := mload(0)
        }
        if (!ok || size != 32) revert M.MetadataReadFailed(target);
    }

    function _frameRead(address target, bytes memory input, uint256 length)
        private
        view
        returns (bytes memory data)
    {
        if (target.code.length == 0) revert M.MetadataReadFailed(target);
        data = new bytes(length);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(gas(), target, add(input, 32), mload(input), add(data, 32), length)
            size := returndatasize()
        }
        if (!ok || size != length) revert M.MetadataReadFailed(target);
    }

    function _frameSuite(address coordinator)
        private
        view
        returns (
            T.SuiteConfiguration memory source,
            bytes32 suiteHash,
            bytes32[16] memory runtimeHashes
        )
    {
        bytes memory raw = _frameRead(
            coordinator,
            abi.encodeCall(IStreamMetadataArtistConfiguration.suiteConfiguration, ()),
            544
        );
        source = abi.decode(raw, (T.SuiteConfiguration));
        suiteHash = keccak256(abi.encode(source));
        if (keccak256(raw) != suiteHash) revert M.MetadataHostNotSelected();
        address finality = abi.decode(
            _frameRead(
                coordinator,
                abi.encodeCall(IStreamMetadataArtistConfiguration.finalityRegistry, ()),
                32
            ),
            (address)
        );
        address provider = abi.decode(
            _frameRead(
                coordinator,
                abi.encodeCall(IStreamMetadataArtistConfiguration.finalityEvidenceProvider, ()),
                32
            ),
            (address)
        );
        bytes32 actual = _frameWord(
            coordinator, IStreamMetadataArtistConfiguration.configurationHash.selector
        );
        if (finality.code.length == 0 || provider.code.length == 0) {
            revert M.MetadataHostNotSelected();
        }
        bytes32 expected;
        (expected, runtimeHashes) = StreamMetadataArtistConfiguration.hashAndRuntime(
            coordinator, source, finality, provider
        );
        if (actual != expected) revert M.MetadataHostNotSelected();
    }

    function _framePredecessor(address current, address original) private view {
        if (
            uint256(_frameWord(
                current, IStreamArtistHistory.importedHistoryBindingCount.selector
            )) != 1
        ) {
            revert M.MetadataHostNotSelected();
        }
        (address prior, uint64 snapshot, bytes32 root, bytes32 manifest) = abi.decode(
            _frameRead(
                current, abi.encodeCall(IStreamArtistHistory.importedHistoryBinding, (0)), 128
            ),
            (address, uint64, bytes32, bytes32)
        );
        if (
            prior == address(0) || prior == original || prior == current || prior.code.length == 0
                || snapshot == 0 || root == 0 || manifest == 0
        ) revert M.MetadataHostNotSelected();
        (bool bound, bytes32 runtime, uint256 count) = abi.decode(
            _frameRead(
                current,
                abi.encodeCall(IStreamArtistHistory.artistHistoryPredecessorBinding, (prior)),
                96
            ),
            (bool, bytes32, uint256)
        );
        if (!bound || count != 1 || prior.codehash != runtime) revert M.MetadataHostNotSelected();
        (bool sealed_, address successor, uint64 sealedAt) = abi.decode(
            _frameRead(prior, abi.encodeCall(IStreamArtistHistory.artistRegistryCutover, ()), 96),
            (bool, address, uint64)
        );
        if (!sealed_ || successor != current || sealedAt == 0 || snapshot > sealedAt) {
            revert M.MetadataHostNotSelected();
        }
    }

    function _predecessor(address current, address original, uint256 cap) private view {
        if (
            abi.decode(
                    _read(
                        current,
                        abi.encodeCall(IStreamArtistHistory.importedHistoryBindingCount, ()),
                        32,
                        cap
                    ),
                    (uint256)
                ) != 1
        ) {
            revert M.MetadataHostNotSelected();
        }
        (address prior, uint64 snapshot, bytes32 root, bytes32 manifest) = abi.decode(
            _read(
                current, abi.encodeCall(IStreamArtistHistory.importedHistoryBinding, (0)), 128, cap
            ),
            (address, uint64, bytes32, bytes32)
        );
        if (
            prior == address(0) || prior == original || prior == current || prior.code.length == 0
                || snapshot == 0 || root == 0 || manifest == 0
        ) revert M.MetadataHostNotSelected();
        (bool bound, bytes32 runtime, uint256 count) = abi.decode(
            _read(
                current,
                abi.encodeCall(IStreamArtistHistory.artistHistoryPredecessorBinding, (prior)),
                96,
                cap
            ),
            (bool, bytes32, uint256)
        );
        if (!bound || count != 1 || prior.codehash != runtime) revert M.MetadataHostNotSelected();
        (bool sealed_, address successor, uint64 sealedAt) = abi.decode(
            _read(prior, abi.encodeCall(IStreamArtistHistory.artistRegistryCutover, ()), 96, cap),
            (bool, address, uint64)
        );
        if (!sealed_ || successor != current || sealedAt == 0 || snapshot > sealedAt) {
            revert M.MetadataHostNotSelected();
        }
    }

    function _read(address target, bytes memory input, uint256 length, uint256 cap)
        private
        view
        returns (bytes memory data)
    {
        if (
            target.code.length == 0 || cap == 0 || cap == type(uint256).max
                || gasleft() <= cap + cap / 63 + 10000
        ) revert M.MetadataReadFailed(target);
        data = new bytes(length);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(input, 32), mload(input), add(data, 32), length)
            size := returndatasize()
        }
        if (!ok || size != length) revert M.MetadataReadFailed(target);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/core/IStreamCorePointers.sol";
import "../../interfaces/stream/modules/IStreamModule.sol";
import "../../interfaces/stream/modules/IStreamModuleRegistry.sol";
import "../../interfaces/stream/finality/IStreamArtworkFinalityRegistry.sol";
import "../../interfaces/stream/finality/IStreamArtworkFinalityRecovery.sol";
import "../../interfaces/stream/finality/IStreamFinalityHostAdapter.sol";
import "../../interfaces/stream/finality/IStreamFinalityDeploymentBindings.sol";
import "../../interfaces/stream/finality/IStreamFinalityRecoveryServingBindings.sol";
import "../../interfaces/stream/artist/IStreamArtistFinalityBinding.sol";

/// @notice Current recovery selection and immutable adapter-to-host joins for serving.
/// @dev Permanent registry reads only classify absence before companion installation. They
///      never select a serving route. All selected routes use both canonical companion reads.
library StreamMetadataRecoveryRoutes {
    uint256 internal constant READ_GAS = 150000;
    uint256 internal constant ROUTE_GAS = 2000000;
    bytes32 internal constant RECOVERY = keccak256("ARTWORK_FINALITY_RECOVERY");
    bytes32 internal constant ORIGINAL = keccak256("ARTWORK_FINALITY_REGISTRY");

    struct OriginalAnchor {
        address registry;
        bytes32 codeHash;
    }

    struct Environment {
        address core;
        address artist;
        bytes32 artistCodeHash;
    }

    struct Pointer {
        address target;
        bytes32 codeHash;
        bool frozen;
        bytes32 moduleType;
        bytes4 interfaceId;
        address registry;
        uint8 status;
        bytes32 moduleManifest;
        bytes32 deploymentManifest;
        uint64 revision;
    }

    struct Context {
        address core;
        address recovery;
        StreamFinalityScope scope;
    }

    struct Route {
        bool pinned;
        address module;
        bytes32 hash;
        bytes32 original;
        bytes32 recoveryId;
    }

    struct Status {
        bool pinned;
        bool current;
        bytes32 hash;
        bytes32 recoveryId;
    }

    error MetadataRecoveryBindingInvalid(address target);
    error MetadataRecoveryReadFailed(address target, bytes4 selector);
    error MetadataRecoveryParentGas(uint256 available, uint256 required);
    error MetadataFrozenRouteInvalid(bytes32 family);

    /// @notice The lock captures this binding from the fixed facade, never a caller target.
    function captureOriginal(Environment memory e) public view returns (OriginalAnchor memory a) {
        if (e.artist.code.length == 0 || e.artist.codehash != e.artistCodeHash) {
            revert MetadataRecoveryBindingInvalid(e.artist);
        }
        a.registry =
            _address(e.artist, abi.encodeCall(IStreamArtistFinalityBinding.finalityRegistry, ()));
        a.codeHash = abi.decode(
            read(
                e.artist,
                abi.encodeCall(IStreamArtistFinalityBinding.finalityRegistryCodeHash, ()),
                32,
                READ_GAS
            ),
            (bytes32)
        );
        if (_address(e.artist, abi.encodeWithSignature("core()")) != e.core) {
            revert MetadataRecoveryBindingInvalid(e.artist);
        }
        _original(e.core, a);
    }

    function _original(address core, OriginalAnchor memory a) private view {
        if (
            a.registry == address(0) || a.codeHash == 0 || a.registry.code.length == 0
                || a.registry.codehash != a.codeHash
                || _address(
                        a.registry, abi.encodeCall(IStreamFinalityDeploymentBindings.coreReads, ())
                    ) != core
        ) {
            revert MetadataRecoveryBindingInvalid(a.registry);
        }
    }

    /// @notice Absence/corruption never causes the saved original to be rediscovered.
    function servingOriginal(
        address core,
        bool locked,
        OriginalAnchor memory saved,
        OriginalAnchor memory durable
    ) public view returns (OriginalAnchor memory) {
        _original(core, durable);
        if (locked) {
            _original(core, saved);
            if (saved.registry != durable.registry || saved.codeHash != durable.codeHash) {
                revert MetadataRecoveryBindingInvalid(saved.registry);
            }
            return saved;
        }
        if (saved.registry != address(0) || saved.codeHash != 0) {
            revert MetadataRecoveryBindingInvalid(saved.registry);
        }
        return durable;
    }

    function context(
        Environment memory e,
        bool locked,
        OriginalAnchor memory saved,
        OriginalAnchor memory durable,
        StreamFinalityScope memory scope
    ) public view returns (Context memory c, bool frozen) {
        saved = servingOriginal(e.core, locked, saved, durable);
        address core = e.core;
        address original = saved.registry;
        c = Context(core, address(0), scope);
        // Immutable original counts classify absence only; they never select a serving route.
        uint256 count = abi.decode(
            read(
                original,
                abi.encodeCall(
                    IStreamArtworkFinalityRegistry.finalityComponentCountForScope, (scope)
                ),
                32,
                READ_GAS
            ),
            (uint256)
        );
        if (count == 0 && scope.scopeType == StreamFinalityScopeType.TOKEN) {
            count = abi.decode(
                read(
                    original,
                    abi.encodeCall(
                        IStreamArtworkFinalityRegistry.finalityComponentCount, (scope.collectionId)
                    ),
                    32,
                    READ_GAS
                ),
                (uint256)
            );
        }
        if (count == 0) return (c, false);
        Pointer memory recovery = _pointer(core, RECOVERY);
        _installed(
            core,
            recovery,
            keccak256("STREAM_ARTWORK_FINALITY_RECOVERY"),
            type(IStreamArtworkFinalityRecovery).interfaceId,
            true
        );
        c.recovery = recovery.target;
        address executor = _identityAddress(
            c.recovery,
            abi.encodeCall(IStreamFinalityRecoveryServingBindings.governanceAuthority, ())
        );
        address artist = _address(
            c.recovery, abi.encodeCall(IStreamFinalityRecoveryServingBindings.artistEvidence, ())
        );
        if (
            _address(c.recovery, abi.encodeCall(IStreamFinalityRecoveryServingBindings.core, ()))
                    != core
                || _address(
                        c.recovery,
                        abi.encodeCall(
                            IStreamFinalityRecoveryServingBindings.originalFinalityRegistry, ()
                        )
                    ) != original
                || _address(
                        original, abi.encodeCall(IStreamFinalityDeploymentBindings.coreReads, ())
                    ) != core
                || _address(
                        original,
                        abi.encodeCall(IStreamFinalityDeploymentBindings.sanctionReads, ())
                    ) != artist
                || _identityAddress(
                        original,
                        abi.encodeCall(
                            IStreamFinalityRecoveryServingBindings.governanceAuthority, ()
                        )
                    ) != executor
        ) revert MetadataRecoveryBindingInvalid(c.recovery);
        // OwnerRecords was authenticated at companion construction and recovery execution.
        // Historical serving uses the recorded evidence and canonical route/status reads.
        Route memory r = route(c, StreamFinalityDomains.COMPONENT_METADATA_ROUTER, true);
        frozen = r.pinned;
    }

    function route(Context memory c, bytes32 family, bool required)
        public
        view
        returns (Route memory r)
    {
        r = abi.decode(
            read(
                c.recovery,
                abi.encodeCall(
                    IStreamArtworkFinalityRecovery.resolvedFinalityRoute, (family, c.scope)
                ),
                160,
                ROUTE_GAS
            ),
            (Route)
        );
        Status memory s = abi.decode(
            read(
                c.recovery,
                abi.encodeCall(
                    IStreamArtworkFinalityRecovery.finalityRecoveryRouteStatus, (family, c.scope)
                ),
                128,
                ROUTE_GAS
            ),
            (Status)
        );
        if (
            r.pinned != s.pinned || r.hash != s.hash || r.recoveryId != s.recoveryId
                || (r.pinned
                    && (!s.current || r.module.code.length == 0 || r.hash == 0 || r.original == 0))
                || (!r.pinned
                    && (required
                        || s.current
                        || r.module != address(0)
                        || r.hash != 0
                        || r.original != 0
                        || r.recoveryId != 0))
        ) revert MetadataFrozenRouteInvalid(family);
    }

    function host(Context memory c, bytes32 family) public view returns (address target) {
        (target,) = hostWithAdapter(c, family);
    }

    /// @notice Return the exact selected adapter alongside its authenticated serving host.
    function hostWithAdapter(Context memory c, bytes32 family)
        public
        view
        returns (address target, address adapter)
    {
        Route memory r = route(c, family, true);
        adapter = r.module;
        _supports(r.module, type(IStreamFinalityHostAdapter).interfaceId);
        target = _address(r.module, abi.encodeCall(IStreamFinalityHostAdapter.host, ()));
        if (
            _address(r.module, abi.encodeCall(IStreamFinalityHostAdapter.core, ())) != c.core
                || abi.decode(
                        read(
                            r.module,
                            abi.encodeCall(IStreamFinalityHostAdapter.coreCodeHash, ()),
                            32,
                            READ_GAS
                        ),
                        (bytes32)
                    ) != c.core.codehash
                || abi.decode(
                        read(
                            r.module,
                            abi.encodeCall(IStreamFinalityHostAdapter.hostCodeHash, ()),
                            32,
                            READ_GAS
                        ),
                        (bytes32)
                    ) != target.codehash
                || abi.decode(
                        read(
                            r.module,
                            abi.encodeCall(IStreamFinalityHostAdapter.componentType, ()),
                            32,
                            READ_GAS
                        ),
                        (bytes32)
                    ) != family || _address(target, abi.encodeWithSignature("core()")) != c.core
        ) {
            revert MetadataRecoveryBindingInvalid(r.module);
        }
    }

    function _pointer(address core, bytes32 key) private view returns (Pointer memory p) {
        bytes memory raw = read(
            core, abi.encodeCall(IStreamCorePointers.getSatellitePointer, (key)), 320, READ_GAS
        );
        p = abi.decode(raw, (Pointer));
        if (p.target == address(0) && keccak256(raw) != keccak256(new bytes(320))) {
            revert MetadataRecoveryBindingInvalid(core);
        }
    }

    /// @notice Current discovery admission, separate from historical serving-host pins.
    function requireCurrentHost(
        address core,
        bytes32 key,
        address expected,
        bytes32 kind,
        bytes4 id
    ) public view {
        Pointer memory p = _pointer(core, key);
        if (p.target != expected) revert MetadataRecoveryBindingInvalid(p.target);
        _installed(core, p, kind, id, true);
    }

    function _installed(address core, Pointer memory p, bytes32 kind, bytes4 id, bool current)
        private
        view
    {
        if (
            p.target.code.length == 0 || p.codeHash != p.target.codehash || p.moduleType != kind
                || p.interfaceId != id || p.registry == address(0)
                || (p.status != 1 && p.status != 2) || p.moduleManifest == 0
                || p.deploymentManifest == 0 || p.revision == 0
        ) {
            revert MetadataRecoveryBindingInvalid(p.target);
        }
        _supports(p.target, id);
        if (
            abi.decode(
                        read(
                            p.target,
                            abi.encodeCall(IStreamModule.streamModuleType, ()),
                            32,
                            READ_GAS
                        ),
                        (bytes32)
                    ) != kind
                || abi.decode(
                        read(
                            p.target,
                            abi.encodeCall(IStreamModule.streamModuleInterfaceId, ()),
                            32,
                            READ_GAS
                        ),
                        (bytes4)
                    ) != id
        ) {
            revert MetadataRecoveryBindingInvalid(p.target);
        }
        if (current) {
            Pointer memory registry = _pointer(core, keccak256("MODULE_REGISTRY"));
            if (
                registry.target != p.registry || registry.target.code.length == 0
                    || registry.codeHash != registry.target.codehash
                    || !abi.decode(
                        read(
                            registry.target,
                            abi.encodeCall(
                                IStreamModuleRegistry.isModuleEligible, (p.target, kind, id)
                            ),
                            32,
                            READ_GAS
                        ),
                        (bool)
                    )
            ) {
                revert MetadataRecoveryBindingInvalid(p.target);
            }
        }
    }

    function _supports(address target, bytes4 id) private view {
        if (
            !abi.decode(
                    read(target, abi.encodeCall(IERC165.supportsInterface, (id)), 32, READ_GAS),
                    (bool)
                )
                || !abi.decode(
                    read(
                        target,
                        abi.encodeCall(IERC165.supportsInterface, (type(IERC165).interfaceId)),
                        32,
                        READ_GAS
                    ),
                    (bool)
                )
                || abi.decode(
                    read(
                        target,
                        abi.encodeCall(IERC165.supportsInterface, (bytes4(0xffffffff))),
                        32,
                        READ_GAS
                    ),
                    (bool)
                )
        ) {
            revert MetadataRecoveryBindingInvalid(target);
        }
    }

    function _address(address target, bytes memory input) private view returns (address value) {
        value = abi.decode(read(target, input, 32, READ_GAS), (address));
        if (value.code.length == 0) revert MetadataRecoveryBindingInvalid(value);
    }

    /// @dev Historical Executor identity is exact but its current runtime is not route evidence.
    function _identityAddress(address target, bytes memory input)
        private
        view
        returns (address value)
    {
        value = abi.decode(read(target, input, 32, READ_GAS), (address));
        if (value == address(0)) revert MetadataRecoveryBindingInvalid(value);
    }

    function read(address target, bytes memory input, uint256 length, uint256 cap)
        internal
        view
        returns (bytes memory output)
    {
        output = new bytes(length);
        uint256 required = cap + cap / 63 + 100000;
        if (gasleft() <= required) revert MetadataRecoveryParentGas(gasleft(), required);
        bool ok;
        uint256 returned;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(input, 32), mload(input), add(output, 32), length)
            returned := returndatasize()
        }
        if (!ok || returned != length) {
            bytes4 selector;
            assembly ("memory-safe") { selector := mload(add(input, 32)) }
            revert MetadataRecoveryReadFailed(target, selector);
        }
    }
}

