            i
                < registry.getDependencyScriptCountAtVersion(
                    dependencyNameAndVersion, dependencyVersion
                );
            i++
        ) {
            scriptText = string.concat(
                scriptText,
                registry.getDependencyScriptAtVersion(
                    dependencyNameAndVersion, dependencyVersion, i
                )
            );
        }
        return scriptText;
