pragma solidity ^0.8.19;

import "../../interfaces/stream/core/IStreamCore.sol";
import "../../interfaces/stream/entropy/IStreamEntropyView.sol";
import "../../interfaces/stream/artist/IStreamArtistAttribution.sol";
import "../../interfaces/stream/metadata/IStreamMetadataServingFacts.sol";
import "./StreamMetadataTokenRenderer.sol";

/// @notice Current or burned token identity with the original coordinator's canonical entropy.
library StreamMetadataTokenReads {
    struct TokenFacts {
        uint256 tokenId;
        uint256 collectionId;
        uint256 serial;
        bytes32 seed;
        bool finalized;
        string state;
    }

    error InvalidToken(uint256 tokenId);

    /// @notice Current-only state vocabulary; the original facts selector remains unchanged.
    function currentFacts(address coreAddress, uint256 tokenId, bool allowBurned)
        public
        view
        returns (TokenFacts memory value, bool terminal)
    {
        value = facts(coreAddress, tokenId, allowBurned);
        if (value.finalized) return (value, false);
        StreamEntropyStatus status = IStreamEntropyView(
                IStreamCore(coreAddress).coordinatorAtMint(tokenId)
            ).tokenEntropyStatus(tokenId);
        terminal =
            status == StreamEntropyStatus.DISABLED || status == StreamEntropyStatus.NOT_REQUIRED;
        if (terminal) {
            value.state = status == StreamEntropyStatus.DISABLED ? "disabled" : "not_required";
        }
    }

    function artistJSON(
        mapping(uint256 => IStreamMetadataServingFacts.ArtistPresentation) storage snapshots,
        address registry,
        uint256 collectionId
    ) public view returns (bytes memory) {
        IStreamMetadataServingFacts.ArtistPresentation storage snapshot = snapshots[collectionId];
        if (snapshot.locked) {
            return StreamMetadataTokenRenderer.artistFields(
                snapshot.nominatedArtist, snapshot.identityRecordHash, snapshot.acceptanceRecordHash
            );
        }
        IStreamCollectionArtistRegistry.Attribution memory record =
            IStreamArtistAttribution(registry).attribution(collectionId);
        if (record.artist == address(0)) return ',"artist_attribution":"unaccepted"';
        return StreamMetadataTokenRenderer.artistFields(
            record.artist, record.identityHash, record.acceptanceHash
        );
    }

    function facts(address coreAddress, uint256 tokenId, bool allowBurned)
        public
        view
        returns (TokenFacts memory)
    {
        IStreamCore core = IStreamCore(coreAddress);
        (bool exists, uint256 collectionId, uint256 serial, bool burned) =
            core.tokenCollectionIdentity(tokenId);
        if (!exists || (burned && !allowBurned)) revert InvalidToken(tokenId);
        uint8 lifecycle = core.tokenLifecycle(tokenId);
        if (burned
                ? lifecycle != uint8(StreamTokenLifecycle.BURNED)
                : lifecycle != uint8(StreamTokenLifecycle.MINTED)) {
            revert InvalidToken(tokenId);
        }
        address coordinator = core.coordinatorAtMint(tokenId);
        (bytes32 seed, bool finalized) = IStreamEntropyView(coordinator).tokenSeed(tokenId);
        StreamEntropyStatus entropyStatus =
            IStreamEntropyView(coordinator).tokenEntropyStatus(tokenId);
        string memory state = finalized
            ? "final"
            : entropyStatus == StreamEntropyStatus.STALE
                ? "stale"
                : entropyStatus == StreamEntropyStatus.FAILED ? "failed" : "pending";
        return TokenFacts(tokenId, collectionId, serial, seed, finalized, state);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/metadata/IStreamMetadataServingFacts.sol";
import "../../interfaces/stream/metadata/StreamMetadataRenderTypes.sol";
import "../../vendor/openzeppelin/Strings.sol";
import "../../vendor/openzeppelin/Base64.sol";
import "./StreamMetadataRenderer.sol";
import { StreamMetadataCitation as Citation } from "./StreamMetadataCitation.sol";

/// @notice Exact deterministic Stream JSON/HTML serialization, not RFC8785/JCS canonicalization.
/// @dev Prepared fields are escaped by the router's existing fixed helper. This pure linked helper
///      makes no provider or authority calls, and preserves full uint256 decimal token identities.
library StreamMetadataTokenRenderer {
    using Strings for uint256;

    /// @notice The render/renderURI selectors consume the fixed Token/ServingSource/artist tuple.
    /// @dev Their Base64/Strings implementation is embedded in the renderer runtime; these
    ///      two selectors perform no external reads. Preparation functions are a separate path.
    function renderingProfile() public pure returns (bytes32, bytes32, bytes32) {
        return StreamMetadataRenderTypes.profile();
    }

    /// @notice Stable library/contract-compatible static rendering entry for selected finality.
    error NoncanonicalFinalityRenderInput();

    function renderForFinality(bool asURI, bytes memory input) public pure returns (string memory) {
        (
            StreamMetadataRenderTypes.Token memory token,
            IStreamMetadataServingFacts.ServingSource memory metadata,
            bytes memory artist
        ) = abi.decode(
            input,
            (StreamMetadataRenderTypes.Token, IStreamMetadataServingFacts.ServingSource, bytes)
        );
        if (keccak256(input) != keccak256(abi.encode(token, metadata, artist))) {
            revert NoncanonicalFinalityRenderInput();
        }
        return asURI ? renderURI(token, metadata, artist) : render(token, metadata, artist);
    }

    function render(
        StreamMetadataRenderTypes.Token memory token,
        IStreamMetadataServingFacts.ServingSource memory metadata,
        bytes memory artist
    ) public pure returns (string memory) {
        bool onchain = token.finalized && bytes(metadata.script).length != 0;
        string memory animation = token.finalized ? _animation(metadata, token) : "";
        bytes memory animationField = bytes(animation).length == 0
            ? bytes("")
            : abi.encodePacked(',"animation_url":"', animation, '"');
        return string(
            abi.encodePacked(
                "{",
                _identity(metadata, token),
                _properties(token, onchain),
                artist,
                animationField,
                "}"
            )
        );
    }

    /// @notice Render and encode in one frame, without copying full JSON back through the router.
    function renderURI(
        StreamMetadataRenderTypes.Token memory token,
        IStreamMetadataServingFacts.ServingSource memory metadata,
        bytes memory artist
    ) public pure returns (string memory) {
        return dataURI(render(token, metadata, artist));
    }

    function dataURI(string memory json) public pure returns (string memory) {
        return string(abi.encodePacked("data:application/json;base64,", Base64.encode(bytes(json))));
    }

    /// @notice Current output carries the work's original identity explicitly.
    /// @dev Old finality selectors and their Token tuple remain unchanged.
    function renderCurrent(
        uint8 mode,
        StreamMetadataRenderTypes.Token memory token,
        IStreamMetadataServingFacts.ServingSource memory metadata,
        bytes memory artist,
        bool nestedArtist,
        uint256 originalChainId,
        address originalCore
    ) public pure returns (string memory) {
        assert(mode <= 3);
        if (mode == 3) return html(token, metadata);
        bytes memory json = bytes(render(token, metadata, nestedArtist ? bytes("") : artist));
        assembly ("memory-safe") { mstore(json, sub(mload(json), 1)) }
        bytes memory fullData = mode == 2 && token.finalized && bytes(metadata.script).length != 0
            ? abi.encodePacked(',"token_data_base64":"', Base64.encode(token.tokenData), '"')
            : bytes("");
        string memory result = string(
            bytes.concat(
                json,
                fullData,
                abi.encodePacked(
                    ',"properties":{"stream":{"render_state":"',
                    token.state,
                    '","citation":"',
                    Citation.work(originalChainId, originalCore, token.tokenId),
                    '"}',
                    nestedArtist
                        ? abi.encodePacked(',"provenance":{"attribution":', artist, "}")
                        : bytes(""),
                    "}}"
                )
            )
        );
        return mode == 1 ? dataURI(result) : result;
    }

    function artistFields(address artist, bytes32 identityHash, bytes32 acceptanceHash)
        public
        pure
        returns (bytes memory)
    {
        return abi.encodePacked(
            ',"artist":"',
            uint256(uint160(artist)).toHexString(20),
            '","artist_identity_hash":"',
            uint256(identityHash).toHexString(32),
            '","artist_acceptance_hash":"',
            uint256(acceptanceHash).toHexString(32),
            '"'
        );
    }

    function _identity(
        IStreamMetadataServingFacts.ServingSource memory metadata,
        StreamMetadataRenderTypes.Token memory token
    ) private pure returns (bytes memory) {
        string memory name = token.configured ? metadata.name : "6529 Stream";
        return abi.encodePacked(
            '"name":"',
            name,
            " #",
            token.serial.toString(),
            '","description":"',
            metadata.description,
            '","image":"',
            metadata.imageURI,
            '"'
        );
    }

    function _properties(StreamMetadataRenderTypes.Token memory token, bool onchain)
        private
        pure
        returns (bytes memory)
    {
        bytes memory tokenDataField = onchain
            ? bytes(',"token_data_location":"animation_url:tokenDataBase64"')
            : abi.encodePacked(',"token_data_base64":"', Base64.encode(token.tokenData), '"');
        return abi.encodePacked(
            ',"metadata_schema_version":"6529stream-v1","metadata_state":"',
            token.state,
            '","token_id":',
            token.tokenId.toString(),
            ',"collection_id":',
            token.collectionId.toString(),
            ',"collection_serial":',
            token.serial.toString(),
            ',"hash":"',
            uint256(token.seed).toHexString(32),
            '"',
            tokenDataField,
            ',"attributes":[]'
        );
    }

    function fullJSON(
        StreamMetadataRenderTypes.Token memory token,
        IStreamMetadataServingFacts.ServingSource memory metadata,
        bytes memory artist
    ) public pure returns (string memory) {
        bytes memory json = bytes(render(token, metadata, artist));
        assembly ("memory-safe") { mstore(json, sub(mload(json), 1)) }
        // The stable offchain branch already carries token_data_base64.
        bytes memory tokenDataField = token.finalized && bytes(metadata.script).length != 0
            ? abi.encodePacked(',"token_data_base64":"', Base64.encode(token.tokenData), '"')
            : bytes("");
        return string(
            bytes.concat(
                json,
                tokenDataField,
                abi.encodePacked(',"properties":{"stream":{"render_state":"', token.state, '"}}}')
            )
        );
    }

    function html(
        StreamMetadataRenderTypes.Token memory token,
        IStreamMetadataServingFacts.ServingSource memory metadata
    ) public pure returns (string memory) {
        if (!token.finalized || bytes(metadata.script).length == 0) {
            revert NoncanonicalFinalityRenderInput();
        }
        return string(
            abi.encodePacked(
                "<html data-stream-render-state=\"",
                token.state,
                "\"><head></head><body><script>",
                "const tokenId=",
                token.tokenId.toString(),
                ";const tokenHash='",
                uint256(token.seed).toHexString(32),
                "';const tokenDataBase64='",
                Base64.encode(token.tokenData),
                "';",
                metadata.script,
                "</script></body></html>"
            )
        );
    }

    function fullViewForFinality(bool asHTML, bytes memory input)
        public
        pure
        returns (string memory)
    {
        (
            StreamMetadataRenderTypes.Token memory token,
            IStreamMetadataServingFacts.ServingSource memory metadata,
            bytes memory artist
        ) = abi.decode(
            input,
            (StreamMetadataRenderTypes.Token, IStreamMetadataServingFacts.ServingSource, bytes)
        );
        if (keccak256(input) != keccak256(abi.encode(token, metadata, artist))) {
            revert NoncanonicalFinalityRenderInput();
        }
        return asHTML ? html(token, metadata) : fullJSON(token, metadata, artist);
    }

    function _animation(
        IStreamMetadataServingFacts.ServingSource memory metadata,
        StreamMetadataRenderTypes.Token memory token
    ) private pure returns (string memory) {
        if (bytes(metadata.script).length != 0) {
            string memory script = string(
                abi.encodePacked(
                    "const tokenId=",
                    token.tokenId.toString(),
                    ";const tokenHash='",
                    uint256(token.seed).toHexString(32),
                    "';const tokenDataBase64='",
                    Base64.encode(token.tokenData),
                    "';",
                    metadata.script
                )
            );
            return string(
                abi.encodePacked(
                    "data:text/html;base64,",
                    Base64.encode(
                        abi.encodePacked(
                            "<html><head></head><body><script>", script, "</script></body></html>"
                        )
                    )
                )
            );
        }
        if (bytes(metadata.animationBaseURI).length == 0) return "";
        return string(abi.encodePacked(metadata.animationBaseURI, token.tokenId.toString()));
    }
    error MetadataJSONLimitExceeded(uint256 bytes_, uint256 maximum);

    /// @notice Exact existing configuration escaping and aggregate bound, before storage writes.
    function prepareMetadata(
        string memory name,
        string memory description,
        string memory image,
        string memory animationBaseURI
    ) public pure returns (IStreamMetadataServingFacts.ServingSource memory) {
        name = StreamMetadataRenderer.escapeJsonString(name);
        description = StreamMetadataRenderer.escapeJsonString(description);
        image = StreamMetadataRenderer.escapeJsonString(image);
        uint256 identityBytes = bytes(name).length + bytes(description).length + bytes(image).length;
        if (identityBytes > 5120) revert MetadataJSONLimitExceeded(identityBytes, 5120);
        return IStreamMetadataServingFacts.ServingSource(
            name, description, image, StreamMetadataRenderer.escapeJsonString(animationBaseURI), ""
        );
    }

    /// @dev Escape the slash of every case-insensitive </script prefix. This preserves the
    /// JavaScript source while preventing an embedded string/comment from ending the HTML tag.
    /// Each disjoint eight-byte match adds one byte; resizing the allocation avoids a copy loop.
    function prepareScript(string memory raw) public pure returns (string memory result) {
        bytes memory source = bytes(raw);
        result = new string(source.length + source.length / 8);
        assembly ("memory-safe") {
            let cursor := add(source, 0x20)
            let end := add(cursor, mload(source))
            let output := add(result, 0x20)
            let start := output
            for { } lt(cursor, end) { cursor := add(cursor, 1) } {
                let character := byte(0, mload(cursor))
                if and(
                    iszero(gt(add(cursor, 8), end)),
                    eq(or(shr(192, mload(cursor)), 0x0000202020202020), 0x3c2f736372697074)
                ) {
                    mstore8(output, 0x3c)
                    mstore8(add(output, 1), 0x5c)
                    output := add(output, 2)
                    cursor := add(cursor, 1)
                    character := 0x2f
                }
                mstore8(output, character)
                output := add(output, 1)
            }
            mstore(result, sub(output, start))
        }
    }
}

