    function renderContextVersion() external pure override returns (bytes32) {
        return CONTEXT;
    }

    function rendererManifest() external view override returns (RendererManifest memory) {
        return _manifest;
    }

    function sourceBindings() external view returns (Sources memory, bytes32[6] memory) {
        return (_sources, _codeHashes);
    }

    function tokenURI(RenderRequest calldata r) external view override returns (string memory) {
        return _render(r, 1, false);
    }

    /// @param mode 0 compact JSON, 1 marketplace URI, 2 full JSON, 3 full executable HTML.
    function renderView(RenderRequest calldata r, uint8 mode)
        external
        view
        returns (string memory)
    {
        return _render(r, mode, false);
    }

    function _render(RenderRequest memory r, uint8 mode, bool current)
        private
        view
        returns (string memory)
    {
        if (mode > 3 || r.core != _sources.core || r.viewId != 0 || r.viewManifestHash != 0) {
            revert InvalidStaticRender();
        }
        Encoding.Prepared memory p = _prepare(r);
        if (mode == 1 && p.config.mode == MetadataMode.OFFCHAIN) {
            if (
                r.state == TokenRenderState.PENDING_RANDOMNESS
                    && bytes(p.config.pendingURI).length != 0
            ) return p.config.pendingURI;
            return string.concat(
                p.config.baseURI,
                (p.config.offchainURIIdMode == OffchainURIIdMode.TOKEN_ID
                        ? r.tokenId
                        : r.collectionSerial)
                .toString()
            );
        }
        if (mode == 3 && r.state == TokenRenderState.PENDING_RANDOMNESS) {
            revert InvalidStaticRender();
        }
        bool full = mode >= 2;
        string memory script = p.source.script;
        if (p.bundle != 0 && full) {
            script = string(_payload(p.bundle, p.bundleFacts));
            if (p.bundleFacts.libraryBundle != 0) {
                B.Facts memory libraryFacts = _bundleFacts(p.bundleFacts.libraryBundle);
                if (!libraryFacts.libraryOnly || libraryFacts.libraryBundle != 0) {
                    revert InvalidStaticRender();
                }
                p.facts.dependencyScript =
                    string(_payload(p.bundleFacts.libraryBundle, libraryFacts));
            }
        }
        _encodingPin();
        bytes memory input = abi.encodeWithSelector(
            current ? Encoding.renderCurrent.selector : Encoding.render.selector,
            r,
            p,
            script,
            _sources.router,
            mode
        );
        uint256 maximum = mode == 1 ? MAX_DEFAULT_URI_BYTES : mode == 0 ? 18000 : MAX_FULL_BYTES;
        bytes memory raw =
            Calls.fixedCode(address(Encoding), input, 64 + ((maximum + 31) / 32) * 32, gasleft());
        return Calls.stringResult(raw, maximum);
    }

    function _prepare(RenderRequest memory r) private view returns (Encoding.Prepared memory p) {
        _pin(0, _sources.core);
        _pin(1, _sources.router);
        bytes memory raw = _read(
            _sources.router,
            abi.encodeCall(S.staticRenderSourceForConfig, (r.collectionId, r.metadataSnapshotHash)),
            20736,
            false
        );
        (p.source, p.config) = abi.decode(raw, (S.RawSource, MetadataConfig));
        if (
            keccak256(raw) != keccak256(abi.encode(p.source, p.config)) || p.config.mode != r.mode
                || (r.metadataSnapshotHash != 0 && p.config.renderer != address(this))
        ) revert InvalidStaticRender();
        if (!p.source.configured && (r.metadataSnapshotHash != 0 || r.tokenId != 0)) {
            revert InvalidStaticRender();
        }
        p.facts.chainId = p.source.chainId;
        p.facts.viewName = "MARKETPLACE";
        if (r.tokenId != 0) {
            bytes memory tokenRaw =
                _read(_sources.core, abi.encodeCall(Mint.tokenData, (r.tokenId)), 16448, false);
            p.facts.tokenData = abi.decode(tokenRaw, (bytes));
            if (
                p.facts.tokenData.length > 16384
                    || keccak256(tokenRaw) != keccak256(abi.encode(p.facts.tokenData))
            ) revert InvalidStaticRender();
            _pin(3, _sources.entropy);
            (uint8 status,, address provider) = abi.decode(
                _read(
                    _sources.entropy,
                    abi.encodeCall(StaticEntropy.staticTokenRenderFacts, (r.tokenId)),
                    96,
                    true
                ),
                (uint8, bytes32, address)
            );
            if (status > 7) revert InvalidStaticRender();
            p.facts.entropyStatus = status;
            p.facts.entropyProvider = provider;
        }
        p.facts.scriptHash = keccak256(bytes(p.source.script));
        M.Selection memory selected = p.source.scriptManifest;
        if (selected.manifestHash != 0) {
            _manifestPin(selected);
            bytes memory manifestRaw = _read(
                selected.host,
                abi.encodeCall(Raw.staticScriptManifest, (selected.manifestHash)),
                9504,
                false
            );
            M.ScriptManifest memory m;
            uint256 collectionId;
            address router;
            (m, p.bundle, collectionId, router) =
                abi.decode(manifestRaw, (M.ScriptManifest, bytes32, uint256, address));
            if (
                keccak256(manifestRaw) != keccak256(abi.encode(m, p.bundle, collectionId, router))
                    || collectionId != r.collectionId || router != _sources.router
            ) revert InvalidStaticRender();
            if (
                !m.executable || keccak256(bytes(m.mimeType)) != keccak256("application/javascript")
            ) revert InvalidStaticRender();
            if (p.bundle != 0) {
                p.bundleFacts = _bundleFacts(p.bundle);
                if (
                    p.bundleFacts.libraryOnly || p.bundleFacts.payloadHash != m.scriptHash
                        || p.bundleFacts.chunkCount != m.chunkCount
                ) revert InvalidStaticRender();
                p.facts.scriptHash = p.bundleFacts.payloadHash;
                if (p.bundleFacts.libraryBundle != 0) {
                    B.Facts memory libraryFacts = _bundleFacts(p.bundleFacts.libraryBundle);
                    if (!libraryFacts.libraryOnly || libraryFacts.libraryBundle != 0) {
                        revert InvalidStaticRender();
                    }
                    p.facts.dependencyHash = libraryFacts.payloadHash;
                }
            } else if (
                m.scriptHash != p.facts.scriptHash || m.chunkCount != 1
                    || m.sourceType != M.PayloadSourceType.INLINE_CHUNKS
            ) {
                revert InvalidStaticRender();
            }
        }
        selected = p.source.mediaManifest;
        if (selected.manifestHash != 0) {
            _manifestPin(selected);
            p.facts.mediaManifestHash = selected.manifestHash;
        }
        if (c2paAttributionEnabled) {
            (p.artist, p.c2pa, p.c2paSubject, p.c2paUnavailable) =
                _attributionWithC2PA(r.collectionId, r.tokenId);
            if (c2paConflictsEnabled) {
                p.c2paConflictsEnabled = true;
                (p.c2paTokenConflict, p.c2paCollectionConflict, p.c2paConflictsUnavailable) =
                    _c2paConflicts(r.collectionId, r.tokenId);
            }
        } else {
            p.artist = _attribution(r.collectionId, r.tokenId);
        }
    }

    function _bundleFacts(bytes32 id) private view returns (B.Facts memory f) {
        _pin(2, _sources.metadata);
        (f,) = abi.decode(
            _read(_sources.metadata, abi.encodeCall(Raw.staticBundle, (id)), 384, true),
            (B.Facts, B.RegistrySource)
        );
        if (
            !f.finalized || f.chunkCount == 0 || f.chunkCount > 32 || f.totalBytes == 0
                || f.totalBytes > 786432 || f.payloadHash == 0
                || (f.sourceType != M.PayloadSourceType.INLINE_CHUNKS
                    && f.sourceType != M.PayloadSourceType.SSTORE2
                    && !(f.libraryOnly && f.sourceType == M.PayloadSourceType.DEPENDENCY_REGISTRY))
        ) revert InvalidStaticRender();
    }

    /// @notice Exact bounded reconstruction read; the same routine supplies assembled HTML/JSON.
    /// @dev bundleId is the immutable selected manifest's script or library bundle. A page proves
    /// its saved chunk hash; clients must still check the full ordered payload hash from facts.
    function scriptBundleChunk(bytes32 bundleId, uint256 index)
        external
        view
        returns (bytes memory)
    {
        B.Facts memory f = _bundleFacts(bundleId);
        if (index >= f.chunkCount) revert InvalidStaticRender();
        Raw.Chunk memory c = abi.decode(
            _read(
                _sources.metadata,
                abi.encodeCall(Raw.staticBundleChunk, (bundleId, index)),
                128,
                true
            ),
            (Raw.Chunk)
        );
        uint256 maximum = f.sourceType == M.PayloadSourceType.SSTORE2 ? 24576 : 8192;
        if (c.length == 0 || c.length > maximum || c.hash == 0) revert InvalidStaticRender();
        B.RegistrySource memory source;
        if (f.sourceType == M.PayloadSourceType.DEPENDENCY_REGISTRY) {
            (, source) = abi.decode(
                _read(_sources.metadata, abi.encodeCall(Raw.staticBundle, (bundleId)), 384, true),
                (B.Facts, B.RegistrySource)
            );
            if (source.registry != _sources.dependencyRegistry || source.codeHash != _codeHashes[4])
            {
                revert InvalidStaticRender();
            }
            _pin(4, source.registry);
            if (
                abi.decode(
                        _read(
                            source.registry,
                            abi.encodeWithSignature(
                                "getDependencyScriptContentHashAtVersion(bytes32,uint256)",
                                source.dependencyId,
                                source.version
                            ),
                            32,
                            true
                        ),
                        (bytes32)
                    ) != source.contentHash
            ) revert InvalidStaticRender();
        }
        bytes memory part = _chunkPayload(f, source, c, index);
        if (part.length != c.length || keccak256(part) != c.hash) revert InvalidStaticRender();
        return part;
    }

    function scriptBundleFacts(bytes32 bundleId) external view returns (B.Facts memory) {
        return _bundleFacts(bundleId);
    }

    function _chunkPayload(
        B.Facts memory f,
        B.RegistrySource memory source,
        Raw.Chunk memory c,
        uint256 index
    ) private view returns (bytes memory part) {
        if (f.sourceType == M.PayloadSourceType.DEPENDENCY_REGISTRY) {
            if (c.first != address(0) || c.tail != address(0)) revert InvalidStaticRender();
            bytes memory raw = _read(
                source.registry,
                abi.encodeWithSignature(
                    "getDependencyScriptAtVersion(bytes32,uint256,uint256)",
                    source.dependencyId,
                    source.version,
                    index
                ),
                8256,
                false
            );
            string memory value = abi.decode(raw, (string));
            if (keccak256(raw) != keccak256(abi.encode(value))) revert InvalidStaticRender();
            return bytes(value);
        }
        uint256 firstLength = c.length > 24575 ? 24575 : c.length;
        if (
            c.first.code.length != firstLength + 1
                || (c.length > 24575 ? c.tail.code.length != 2 : c.tail != address(0))
        ) revert InvalidStaticRender();
        part = new bytes(c.length);
        address first = c.first;
        address tail = c.tail;
        assembly ("memory-safe") { extcodecopy(first, add(part, 32), 1, firstLength) }
        if (tail != address(0)) {
            assembly ("memory-safe") { extcodecopy(tail, add(add(part, 32), firstLength), 1, 1) }
        }
    }

    function _payload(bytes32 id, B.Facts memory f) private view returns (bytes memory out) {
        B.RegistrySource memory source;
        if (f.sourceType == M.PayloadSourceType.DEPENDENCY_REGISTRY) {
            (, source) = abi.decode(
                _read(_sources.metadata, abi.encodeCall(Raw.staticBundle, (id)), 384, true),
                (B.Facts, B.RegistrySource)
            );
            if (source.registry != _sources.dependencyRegistry || source.codeHash != _codeHashes[4])
            {
                revert InvalidStaticRender();
            }
            _pin(4, source.registry);
        }
        out = new bytes(f.totalBytes);
        uint256 offset;
        bytes32 sequence;
        uint256 maximum = f.sourceType == M.PayloadSourceType.SSTORE2 ? 24576 : 8192;
        for (uint256 i; i < f.chunkCount; ++i) {
            Raw.Chunk memory c = abi.decode(
                _read(_sources.metadata, abi.encodeCall(Raw.staticBundleChunk, (id, i)), 128, true),
                (Raw.Chunk)
            );
            if (
                c.length == 0 || c.length > maximum || c.hash == 0 || c.length > out.length - offset
            ) {
                revert InvalidStaticRender();
            }
            bytes memory part = _chunkPayload(f, source, c, i);
            if (f.sourceType == M.PayloadSourceType.DEPENDENCY_REGISTRY) {
                bytes32 typed = keccak256(
                    abi.encode(
                        keccak256(
                            "6529StreamDependencyScriptChunk(uint256 index,bytes32 chunkHash,uint256 byteLength)"
                        ),
                        i,
                        c.hash,
                        uint256(c.length)
                    )
                );
                sequence = keccak256(abi.encode(sequence, typed));
            }
            if (part.length != c.length || keccak256(part) != c.hash) revert InvalidStaticRender();
            uint256 words = part.length & ~uint256(31);
            assembly ("memory-safe") {
                for { let j := 0 } lt(j, words) { j := add(j, 32) } {
                    mstore(add(add(out, 32), add(offset, j)), mload(add(add(part, 32), j)))
                }
            }
            for (uint256 j = words; j < part.length; ++j) {
                out[offset + j] = part[j];
            }
            offset += part.length;
        }
        if (source.registry != address(0)) {
            bytes32 content = keccak256(
                abi.encode(
                    keccak256(
                        "6529StreamDependencyScript(bytes32 dependencyNameAndVersion,uint256 chunkCount,bytes32 chunksHash)"
                    ),
                    source.dependencyId,
                    uint256(f.chunkCount),
                    sequence
                )
            );
            if (
                content != source.contentHash
                    || abi.decode(
                            _read(
                                source.registry,
                                abi.encodeWithSignature(
                                    "getDependencyScriptContentHashAtVersion(bytes32,uint256)",
                                    source.dependencyId,
                                    source.version
                                ),
                                32,
                                true
                            ),
                            (bytes32)
                        ) != content
            ) revert InvalidStaticRender();
        }
        if (
            offset != out.length || keccak256(out) != f.payloadHash
                || !Text.isValidUtf8(string(out))
        ) {
            revert InvalidStaticRender();
        }
    }

    function _c2paCapability(address target, bytes4 capability) private view returns (bool result) {
        bytes memory input = abi.encodeWithSignature("supportsInterface(bytes4)", capability);
        uint256 cap = _gasParameterValue(READ_GAS);
        if (gasleft() <= cap + cap / 63 + 10000) revert InvalidStaticRender();
        bool ok;
        uint256 size;
        uint256 value;
        assembly ("memory-safe") {
            let pointer := mload(0x40)
            ok := staticcall(cap, target, add(input, 32), mload(input), pointer, 32)
            size := returndatasize()
            value := mload(pointer)
        }
        if (!ok || size == 0) return false; // Original companion has no optional interface.
        if (size != 32 || value > 1) revert InvalidStaticRender();
        return value == 1;
    }

    function _c2paConflicts(uint256 id, uint256 token)
        private
        view
        returns (Conflicts.Standing memory t, Conflicts.Standing memory c, bool unavailable)
    {
        address a = _sources.attribution;
        uint256 cap = _gasParameterValue(ATTRIBUTION_GAS);
        if (
            a.codehash != _codeHashes[5] || a.code.length == 0
                || gasleft() <= cap + cap / 63 + 200000
        ) return (t, c, true);
        bytes memory input =
            abi.encodeCall(IStreamStaticC2PAConflicts.attributionC2PAConflicts, (id, token));
        bytes memory raw = new bytes(384);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(cap, a, add(input, 32), mload(input), add(raw, 32), 384)
            size := returndatasize()
        }
        if (!ok || size != 384) return (t, c, true);
        // Check narrow words before abi.decode so malformed optional data degrades, never reverts rendering.
        for (uint256 i; i < 2; ++i) {
            uint256 revision;
            uint256 count;
            assembly ("memory-safe") {
                revision := mload(add(add(raw, 160), mul(i, 192)))
                count := mload(add(add(raw, 192), mul(i, 192)))
            }
            if (revision > type(uint64).max || count > revision) return (t, c, true);
        }
        (Conflicts.Standing memory t_, Conflicts.Standing memory c_) =
            abi.decode(raw, (Conflicts.Standing, Conflicts.Standing));
        if (!_validConflict(t_) || !_validConflict(c_) || (token == 0 && t_.revision != 0)) {
            return (t, c, true);
        }
        return (t_, c_, false);
    }

    function _validConflict(Conflicts.Standing memory v) private pure returns (bool) {
        if ((v.revision == 0) != (v.chainHash == 0)) return false;
        if (v.unresolvedCount == 0) {
            return v.conflictId == 0 && v.recordHash == 0 && v.selectionHash == 0;
        }
        return v.conflictId != 0 && v.recordHash != 0 && v.selectionHash != 0;
    }

    function _attributionWithC2PA(uint256 id, uint256 token)
        private
        view
        returns (bytes memory value, C2PA.Display memory facts, bytes32 subject, bool unavailable)
    {
        value = '{"state":"attribution_unavailable"}';
        unavailable = true;
        address a = _sources.attribution;
        if (a.code.length == 0 || a.codehash != _codeHashes[5]) {
            return (value, facts, subject, unavailable);
        }
        uint256 cap = _gasParameterValue(ATTRIBUTION_GAS);
        if (gasleft() <= cap + cap / 63 + 200000) return (value, facts, subject, unavailable);
        bytes memory input = abi.encodeCall(C2PAAttribution.attributionWithC2PA, (id, token));
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(cap, a, add(input, 32), mload(input), 0, 0)
            size := returndatasize()
        }
        if (!ok || size < 288 || size > 33056) return (value, facts, subject, unavailable);
        bytes memory raw = new bytes(size);
        assembly ("memory-safe") { returndatacopy(add(raw, 32), 0, size) }
        uint256 offset;
        uint256 length;
        uint256 validation;
        uint256 authorship;
        uint256 current_;
        uint256 asserts_;
        assembly ("memory-safe") {
            offset := mload(add(raw, 32))
            validation := mload(add(raw, 128))
            authorship := mload(add(raw, 160))
            current_ := mload(add(raw, 192))
            asserts_ := mload(add(raw, 224))
            length := mload(add(raw, 288))
        }
        if (
            offset != 256 || length > 32768 || size != 288 + ((length + 31) / 32) * 32
                || validation > 2 || authorship > 2 || current_ > 1 || asserts_ > 1
        ) {
            return (value, facts, subject, unavailable);
        }
        (bytes memory candidate, C2PA.Display memory display_, bytes32 subject_) =
            abi.decode(raw, (bytes, C2PA.Display, bytes32));
        if (keccak256(raw) != keccak256(abi.encode(candidate, display_, subject_))) {
            return (value, facts, subject, unavailable);
        }
        if (
            (!display_.current
                    && (display_.validation != C2PA.ValidationStatus.UNEVALUATED
                        || display_.authorship != C2PA.AuthorshipStatus.UNEVALUATED))
                || ((display_.validation != C2PA.ValidationStatus.VALID
                        || !display_.assertsAuthorship)
                    && display_.authorship != C2PA.AuthorshipStatus.UNEVALUATED)
                || (display_.recordHash == 0
                    && (display_.selectionHash != 0
                        || display_.current
                        || display_.assertsAuthorship))
                || (display_.recordHash != 0 && (display_.selectionHash == 0 || subject_ == 0))
        ) return (value, facts, subject, unavailable);
        return (candidate, display_, subject_, false);
    }

    function _attribution(uint256 id, uint256 token) private view returns (bytes memory value) {
        address a = _sources.attribution;
        if (a.code.length == 0 || a.codehash != _codeHashes[5]) {
            return '{"state":"attribution_unavailable"}';
        }
        uint256 cap = _gasParameterValue(ATTRIBUTION_GAS);
        uint256 available = gasleft();
        if (available <= cap + cap / 63 + 200000) return '{"state":"attribution_unavailable"}';
        bytes memory input = abi.encodeCall(Attribution.attribution, (id, token));
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(cap, a, add(input, 32), mload(input), 0, 0)
            size := returndatasize()
        }
        if (!ok || size < 64 || size > 32832) return '{"state":"attribution_unavailable"}';
        bytes memory raw = new bytes(size);
        assembly ("memory-safe") { returndatacopy(add(raw, 32), 0, size) }
        uint256 start;
        uint256 length;
        assembly ("memory-safe") {
            start := mload(add(raw, 32))
            length := mload(add(raw, 64))
        }
        if (start != 32 || length > 32768 || size != 64 + ((length + 31) / 32) * 32) {
            return '{"state":"attribution_unavailable"}';
        }
        value = abi.decode(raw, (bytes));
        if (keccak256(raw) != keccak256(abi.encode(value))) {
            return '{"state":"attribution_unavailable"}';
        }
    }

    function _manifestPin(M.Selection memory s) private view {
        if (s.host != _sources.metadata || s.codeHash != _codeHashes[2]) {
            revert InvalidStaticRender();
        }
        _pin(2, s.host);
    }

    function _pin(uint256 i, address a) private view {
        if (a.code.length == 0 || a.codehash != _codeHashes[i]) revert InvalidStaticRender();
    }

    function _read(address a, bytes memory input, uint256 maximum, bool exact)
        private
        view
        returns (bytes memory)
    {
        return Calls.read(a, input, Calls.ReadOptions(maximum, exact), _gasParameterValue(READ_GAS));
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/metadata/IStreamRightsRecordSelection.sol";
import "../../interfaces/stream/metadata/IStreamRightsRecordWitnessSelection.sol";
import "../records/StreamRightsRecordReads.sol";
import "../records/StreamRecordArtistIdentityReads.sol";
import {
    IStreamRecordSelectionLock
} from "../../interfaces/stream/metadata/IStreamRecordSelectionLock.sol";
import { StreamRecordSelectionLocks as SelectionLocks } from "./StreamRecordSelectionLocks.sol";

/// @notice Explicit current rights statements selected by the existing RIGHTS authority.
/// @dev Fixed auxiliary for the typed provider; no new Core role, grant store or mutable binder.
contract StreamRightsRecordSelection is
    IStreamRightsRecordSelection,
    IStreamRightsRecordWitnessSelection,
    IStreamRecordSelectionLock
{
    address public immutable override core;
    address public immutable override metadata;
    address public immutable override schemaRegistry;
    address public immutable override chunkStore;
    uint256 public immutable override deploymentChainId;
    bytes32 public immutable coreCodeHash;
    bytes32 public immutable metadataCodeHash;
    bytes32 public immutable schemaRegistryCodeHash;
    bytes32 public immutable chunkStoreCodeHash;
    StreamRecordArtistIdentityReads.Pins private _artistPins;
    mapping(bytes32 => Selection[]) private _history;
    mapping(bytes32 => SelectionLock) private _selectionLocks;

    struct SelectionRequest {
        uint256 collectionId;
        bytes32 subjectId;
        bytes32 recordHash;
        bytes32 expectedHead;
        uint64 expectedRevision;
    }

    constructor(address core_, address metadata_, address schemas_) {
        if (
            core_.code.length == 0 || metadata_.code.length == 0 || schemas_.code.length == 0
                || !IERC165(metadata_)
                    .supportsInterface(type(IStreamCollectionRecordReceipts).interfaceId)
                || !IERC165(schemas_)
                    .supportsInterface(type(IStreamSchemaDocumentFacts).interfaceId)
        ) {
            revert InvalidRightsConfiguration();
        }
        core = core_;
        metadata = metadata_;
        schemaRegistry = schemas_;
        chunkStore = IStreamSchemaRegistry(schemas_).chunkStore();
        if (chunkStore.code.length == 0) revert InvalidRightsConfiguration();
        deploymentChainId = block.chainid;
        coreCodeHash = core_.codehash;
        metadataCodeHash = metadata_.codehash;
        schemaRegistryCodeHash = schemas_.codehash;
        chunkStoreCodeHash = chunkStore.codehash;
        // Complete definitions may be registered later by normal governance.
        StreamRightsRecordReads.Dependencies memory d = _baseContext();
        _artistPins =
            StreamRecordArtistIdentityReads.resolveCurrent(metadata, core, deploymentChainId, d.readGas);
    }

    function supportsInterface(bytes4 id) external pure override returns (bool) {
        return id == type(IStreamRightsRecordSelection).interfaceId
            || id == type(IStreamRightsRecordWitnessSelection).interfaceId
            || id == type(IStreamRecordSelectionLock).interfaceId || id == 0x01ffc9a7;
    }

    function selectCurrent(
        uint256 collectionId,
        bytes32 subjectId,
        bytes32 recordHash,
        bytes32 expectedHead,
        uint64 expectedRevision,
        StreamRightsRecordTypes.Statement calldata witness
    ) external override returns (Selection memory selected) {
        IStreamPreservationRecords.CollectionRecord memory unused;
        return _select(
            SelectionRequest(collectionId, subjectId, recordHash, expectedHead, expectedRevision),
            witness,
            unused,
            false
        );
    }

    function selectCurrentWithRecord(
        uint256 collectionId,
        bytes32 subjectId,
        bytes32 recordHash,
        bytes32 expectedHead,
        uint64 expectedRevision,
        Witness calldata witness
    ) external override returns (Selection memory) {
        return _select(
            SelectionRequest(collectionId, subjectId, recordHash, expectedHead, expectedRevision),
            witness.statement,
            witness.original,
            true
        );
    }

    function _select(
        SelectionRequest memory request,
        StreamRightsRecordTypes.Statement calldata witness,
        IStreamPreservationRecords.CollectionRecord memory original,
        bool supplied
    ) private returns (Selection memory selected) {
        if (_selectionLocks[_key(request.collectionId, request.subjectId)].locked) {
            revert RecordSelectionLocked(request.collectionId, request.subjectId);
        }
        Selection memory previous = currentRights(request.collectionId, request.subjectId);
        if (
            previous.recordHash != request.expectedHead
                || previous.revision != request.expectedRevision
                || witness.predecessor != request.expectedHead
                || request.expectedRevision == type(uint64).max
                || block.timestamp > type(uint64).max
        ) revert RightsSelectionConflict();
        StreamRightsRecordReads.Dependencies memory d = _context();
        (selected.authorizationClass, selected.grantScope, selected.grantRevision) =
            StreamRightsRecordReads.authority(d, request.collectionId, msg.sender);
        StreamRightsRecordReads.definitions(d);
        IStreamCollectionMetadataV1.RecordReceipt memory receipt;
        if (supplied) {
            (selected.payloadHash, receipt) = StreamRightsRecordReads.recordedWithWitness(
                d, request.collectionId, request.subjectId, request.recordHash, witness, original
            );
        } else {
            (selected.payloadHash, receipt) = StreamRightsRecordReads.recorded(
                d, request.collectionId, request.subjectId, request.recordHash, witness
            );
        }
        selected.recordIndex = receipt.recordIndex;
        selected.recorder = receipt.recorder;
        selected.recorderAuthorizationClass = receipt.authorizationClass;
        if (witness.licensor.kind == StreamRightsRecordTypes.LicensorKind.ARTIST) {
            selected.artistIdentityRecordHash = StreamRecordArtistIdentityReads.knownCurrentIdentity(
                metadata, core, deploymentChainId, _artistPins, witness.licensor.artistId, d.readGas
            );
        }
        if (request.expectedHead != 0 && selected.recordIndex <= previous.recordIndex) {
            revert RightsSelectionConflict();
        }
        selected.recordHash = request.recordHash;
        selected.predecessor = request.expectedHead;
        selected.selector = msg.sender;
        selected.revision = request.expectedRevision + 1;
        selected.selectedAt = uint64(block.timestamp);
        selected.selectionHash = _selectionHash(request.collectionId, request.subjectId, selected);
        _history[_key(request.collectionId, request.subjectId)].push(selected);
        emit RightsRecordSelected(
            request.collectionId, request.subjectId, request.recordHash, selected
        );
    }

    function _selectionHash(uint256 collectionId, bytes32 subjectId, Selection memory selected)
        private
        view
        returns (bytes32)
    {
        // The selectionHash field is zero while computing this explicit preimage.
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_RIGHTS_SELECTION_V1"),
                deploymentChainId,
                address(this),
                core,
                metadata,
                schemaRegistry,
                chunkStore,
                collectionId,
                subjectId,
                selected
            )
        );
    }

    function currentRights(uint256 collectionId, bytes32 subjectId)
        public
        view
        override
        returns (Selection memory)
    {
        Selection[] storage rows = _history[_key(collectionId, subjectId)];
        if (rows.length == 0) {
            Selection memory empty;
            return empty;
        }
        return rows[rows.length - 1];
    }

    function rightsSelectionAt(uint256 collectionId, bytes32 subjectId, uint64 revision)
        external
        view
        override
        returns (Selection memory)
    {
        if (revision == 0) revert RightsSelectionConflict();
        return _history[_key(collectionId, subjectId)][revision - 1];
    }

    function requireCurrent(
        uint256 collectionId,
        bytes32 subjectId,
        bytes32 expectedRecord,
        uint64 expectedRevision
    ) external view override returns (Selection memory selected) {
        selected = currentRights(collectionId, subjectId);
        if (
            selected.recordHash == 0 || selected.recordHash != expectedRecord
                || selected.revision != expectedRevision
        ) revert RightsSelectionConflict();
        StreamRightsRecordReads.definitions(_context());
    }

    function selectionLockTransition(
        uint256 collectionId,
        bytes32 subjectId,
        bytes32 expectedRecord,
        uint64 expectedRevision
    )
        external
        view
        override
        returns (bytes32 scopeHash, bytes32 oldValueHash, bytes32 newValueHash)
    {
        (SelectionLocks.Environment memory e, SelectionLocks.Head memory h) =
            _lockData(collectionId, subjectId, expectedRecord, expectedRevision);
        SelectionLock memory item = SelectionLocks.context(e, h);
        return (item.scopeHash, item.oldValueHash, item.newValueHash);
    }

    function lockSelection(
        uint256 collectionId,
        bytes32 subjectId,
        bytes32 expectedRecord,
        uint64 expectedRevision
    ) external override {
        (SelectionLocks.Environment memory e, SelectionLocks.Head memory h) =
            _lockData(collectionId, subjectId, expectedRecord, expectedRevision);
        SelectionLocks.lock(_selectionLocks, e, h);
    }

    function selectionLock(uint256 collectionId, bytes32 subjectId)
        external
        view
        override
        returns (SelectionLock memory)
    {
        return _selectionLocks[_key(collectionId, subjectId)];
    }

    function _lockData(
        uint256 collectionId,
        bytes32 subjectId,
        bytes32 expectedRecord,
        uint64 expectedRevision
    ) private view returns (SelectionLocks.Environment memory e, SelectionLocks.Head memory h) {
        if (_selectionLocks[_key(collectionId, subjectId)].locked) {
            revert RecordSelectionLocked(collectionId, subjectId);
        }
        Selection memory selected = currentRights(collectionId, subjectId);
        if (
            selected.recordHash == 0 || selected.recordHash != expectedRecord
                || selected.revision != expectedRevision
        ) {
            revert RecordSelectionLockConflict(collectionId, subjectId);
        }
        StreamRightsRecordReads.Dependencies memory d = _context();
        StreamRightsRecordReads.definitions(d);
        e = SelectionLocks.Environment(
            core,
            metadata,
            coreCodeHash,
            metadataCodeHash,
            deploymentChainId,
            d.readGas,
            keccak256("RIGHTS_STATEMENT")
        );
        h = SelectionLocks.Head(
            collectionId, subjectId, selected.recordHash, selected.revision, selected.selectionHash
        );
    }

    function _context() private view returns (StreamRightsRecordReads.Dependencies memory d) {
        d = _baseContext();
        for (uint256 i; i < 3; ++i) {
            if (
                _artistPins.targets[i].code.length == 0
                    || _artistPins.targets[i].codehash != _artistPins.codeHashes[i]
            ) {
                revert RightsDependencyChanged(_artistPins.targets[i]);
            }
        }
        StreamRecordArtistIdentityReads.Pins memory current =
            StreamRecordArtistIdentityReads.resolveCurrent(metadata, core, deploymentChainId, d.readGas);
        for (uint256 i; i < 3; ++i) {
            if (
                current.targets[i] != _artistPins.targets[i]
                    || current.codeHashes[i] != _artistPins.codeHashes[i]
            ) {
                revert RightsDependencyChanged(current.targets[i]);
            }
        }
    }

    function _baseContext() private view returns (StreamRightsRecordReads.Dependencies memory d) {
        d.targets = [core, metadata, schemaRegistry, chunkStore];
        d.codeHashes = [coreCodeHash, metadataCodeHash, schemaRegistryCodeHash, chunkStoreCodeHash];
        d.chainId = deploymentChainId;
        return StreamRightsRecordReads.currentContext(d);
    }

    function _key(uint256 collectionId, bytes32 subjectId) private pure returns (bytes32) {
        return keccak256(abi.encode(collectionId, subjectId));
    }
}

