import { IERC165 } from "../../vendor/openzeppelin/IERC165.sol";
import {
    IStreamGasParameterHost
} from "../../interfaces/stream/parameters/IStreamGasParameterHost.sol";
import {
    IStreamGovernedParameterAuthority
} from "../../interfaces/stream/parameters/IStreamGovernedParameterAuthority.sol";

import {
    IStreamScopedPolicySnapshotPublicationV2 as I
} from "../../interfaces/stream/metadata/IStreamScopedPolicySnapshotPublicationV2.sol";
import {
    StreamScopedPolicySnapshotTypesV2 as S
} from "../../interfaces/stream/metadata/StreamScopedPolicySnapshotTypesV2.sol";
import {
    StreamFinalityScope
} from "../../interfaces/stream/finality/StreamArtworkFinalityTypes.sol";
import {
    IStreamCollectionMetadataV1 as Metadata
} from "../../interfaces/stream/metadata/IStreamCollectionMetadataV1.sol";
import {
    IStreamSchemaRegistry as Schema
} from "../../interfaces/stream/metadata/IStreamSchemaRegistry.sol";
import {
    StreamScopedPolicySnapshotSourceReadsV2 as Sources
} from "../records/StreamScopedPolicySnapshotSourceReadsV2.sol";
import {
    StreamScopedPolicySnapshotDefinitionsV2 as Definitions
} from "../records/StreamScopedPolicySnapshotDefinitionsV2.sol";
import { StreamSnapshotManifestBytes as Bytes } from "../records/StreamSnapshotManifestBytes.sol";
import { StreamWorkRecordContext as Documents } from "../records/StreamWorkRecordContext.sol";
import { StreamRecordFamilies as Families } from "../records/StreamRecordFamilies.sol";
import {
    StreamFinalityRouterEvidence as Reads
} from "../finality/StreamFinalityRouterEvidence.sol";
import { StreamMetadataRenderer } from "./StreamMetadataRenderer.sol";
import { StreamGasParameterHost } from "../parameters/StreamGasParameterHost.sol";

/// @notice Exact full-policy scope-bound source publication, preceding separate scoped root adoption.
/// @dev Source snapshots are separate from Artist CONTENT_ROOT authority, complete output bytes,
/// reference-mode evidence and finality. VIEW requires its own actual presentation adoption profile.
contract StreamScopedPolicySnapshotPublicationV2 is I, StreamGasParameterHost {
    bytes32 public constant READ_GAS = keccak256("6529STREAM_GGP_SCOPED_POLICY_SNAPSHOT_READ_GAS");
    bytes32 public constant SOURCE_GAS =
        keccak256("6529STREAM_GGP_SCOPED_POLICY_SNAPSHOT_SOURCE_GAS");
    bytes32 public constant INVENTORY_GAS =
        keccak256("6529STREAM_GGP_SCOPED_POLICY_SNAPSHOT_INVENTORY_GAS");
    address public immutable override core;
    address public immutable override metadataHost;
    bytes32 public immutable authorityCodeHash;
    S.Dependencies private _fixed;
    mapping(bytes32 => S.Publication) private _publications;
    mapping(bytes32 => S.Receipt) private _receipts;
    mapping(bytes32 => Bytes.Manifest) private _payloads;
    mapping(bytes32 => bytes32[]) private _history;
    mapping(bytes32 => mapping(bytes32 => bytes32)) private _ids;
    mapping(bytes32 => S.Lock) private _locks;
    bool private _entered;

    constructor(S.Dependencies memory d, address executor, GasParameterConfig[3] memory configs)
        StreamGasParameterHost(executor)
    {
        if (
            _registerGasParameter(configs[0]) != READ_GAS
                || _registerGasParameter(configs[1]) != SOURCE_GAS
                || _registerGasParameter(configs[2]) != INVENTORY_GAS
        ) revert S.InvalidScopedPolicySnapshot();
        for (uint256 i; i < 3; ++i) {
            if (configs[i].failureClass != FAILURE_CLASS_FAIL_CLOSED_PRECHECK) {
                revert S.InvalidScopedPolicySnapshot();
            }
        }
        _fixed = d;
        core = d.targets[0];
        metadataHost = d.targets[1];
        Sources.bindings(dependencies());
        authorityCodeHash = abi.decode(
            Reads.read(
                metadataHost,
                abi.encodeWithSignature("executorCodeHash()"),
                32,
                configs[0].genesisValue
            ),
            (bytes32)
        );
        if (
            executor.code.length == 0 || executor.codehash != authorityCodeHash
                || abi.decode(
                        Reads.read(
                            metadataHost,
                            abi.encodeWithSignature("governanceAuthority()"),
                            32,
                            configs[0].genesisValue
                        ),
                        (address)
                    ) != executor
        ) revert S.InvalidScopedPolicySnapshot();
    }

    modifier guarded() {
        if (_entered) revert S.InvalidScopedPolicySnapshot();
        _entered = true;
        _;
        _entered = false;
    }

    function scopedPolicySnapshotProfile() external pure override returns (bytes32) {
        return keccak256("6529STREAM_SCOPED_POLICY_SNAPSHOT_V2");
    }

    function supportsInterface(bytes4 id) external pure override returns (bool) {
        return id == type(IERC165).interfaceId || id == type(I).interfaceId
            || id == type(IStreamGasParameterHost).interfaceId;
    }

    function dependencies() public view override returns (S.Dependencies memory d) {
        d = _fixed;
        d.readGas = gasParameter(READ_GAS);
        d.sourceGas = gasParameter(SOURCE_GAS);
        d.inventoryGas = gasParameter(INVENTORY_GAS);
    }

    function previewSnapshot(S.Publication calldata p, address publisher)
        external
        view
        override
        returns (bytes32 sourceHash, bytes memory canonical)
    {
        _candidate(p);
        S.Receipt memory r = _receipt(p, publisher);
        return _assemble(p, r);
    }

    function publishSnapshot(S.Publication calldata p)
        external
        override
        guarded
        returns (bytes32 hash)
    {
        _candidate(p);
        S.Receipt memory r = _receipt(p, msg.sender);
        bytes memory canonical;
        (r.sourceHash, canonical) = _assemble(p, r);
        if (p.expectedSourceHash == 0 || p.expectedSourceHash != r.sourceHash) {
            revert S.InvalidScopedPolicySnapshot();
        }
        r.manifestHash = keccak256(canonical);
        r.manifestBytes = uint32(canonical.length);
        r.recordedAt = uint64(block.timestamp);
        hash = keccak256(
            abi.encode(
                keccak256("6529STREAM_SCOPED_POLICY_SNAPSHOT_RECORD_V2"),
                _fixed.chainId,
                address(this),
                core,
                metadataHost,
                p,
                r
            )
        );
        r.recordHash = hash;
        r.chainHash = keccak256(
            abi.encode(
                keccak256("6529STREAM_SCOPED_POLICY_SNAPSHOT_CHAIN_V2"),
                _fixed.chainId,
                address(this),
                core,
                p.scope,
                _receipts[p.expectedHead].chainHash,
                r.revision,
                hash
            )
        );
        // The fixed Store cannot call back into the writer. Its immutable bytes grant no authority.
        Bytes.retain(_payloads[hash], _fixed.targets[3], canonical);
        _publications[hash] = p;
        _receipts[hash] = r;
        _ids[r.scopeSubject][p.snapshotId] = hash;
        _history[r.scopeSubject].push(hash);
        emit ScopedPolicySnapshotPublished(2, r.scopeSubject, p.snapshotId, hash, p, r);
    }

    function currentSnapshot(StreamFinalityScope calldata scope)
        public
        view
        override
        returns (S.Receipt memory)
    {
        S.Receipt memory r = _receipts[_head(Sources.scopeSubject(_fixed, scope))];
        if (r.recordHash != 0) _requireExactScope(r.recordHash, scope);
        return r;
    }

    function snapshotRecord(bytes32 hash)
        external
        view
        override
        returns (S.Publication memory, S.Receipt memory)
    {
        return (_publications[hash], _known(hash));
    }

    function snapshotPayload(bytes32 hash) external view override returns (bytes memory) {
        _known(hash);
        return Bytes.read(_payloads[hash]);
    }

    function requireCurrent(StreamFinalityScope calldata scope, bytes32 hash, uint64 revision)
        public
        view
        override
        returns (S.Receipt memory r)
    {
        r = _known(hash);
        _requireExactScope(hash, scope);
        bytes32 subject = Sources.scopeSubject(_fixed, scope);
        if (r.scopeSubject != subject || _head(subject) != hash || r.revision != revision) {
            revert S.ScopedPolicySnapshotLineage(hash, _head(subject));
        }
        S.Receipt memory fields = abi.decode(abi.encode(r), (S.Receipt));
        fields.recordHash = 0;
        fields.chainHash = 0;
        fields.manifestHash = 0;
        fields.manifestBytes = 0;
        fields.recordedAt = 0;
        (bytes32 sourceHash, bytes memory canonical) = _assemble(_publications[hash], fields);
        if (
            sourceHash != r.sourceHash || keccak256(canonical) != r.manifestHash
                || canonical.length != r.manifestBytes
                || Bytes.requireIntact(_payloads[hash]) != r.manifestHash
        ) revert S.InvalidScopedPolicySnapshot();
    }

    function lockTransition(StreamFinalityScope calldata scope)
        public
        view
        override
        returns (bytes32 actionScope, bytes32 oldState, bytes32 newState)
    {
        S.Receipt memory r = currentSnapshot(scope);
        if (r.recordHash == 0) revert S.ScopedPolicySnapshotUnknown(0);
        if (_locks[r.scopeSubject].actionId != 0) {
            revert S.ScopedPolicySnapshotLocked(r.scopeSubject);
        }
        actionScope = keccak256(
            abi.encode(
                keccak256("6529STREAM_SCOPED_POLICY_SNAPSHOT_LOCK_V2"),
                _fixed.chainId,
                address(this),
                core,
                scope
            )
        );
        oldState = keccak256(abi.encode(actionScope, r.recordHash, r.revision, false));
        newState = keccak256(abi.encode(actionScope, r.recordHash, r.revision, true));
    }

    function lockSnapshot(StreamFinalityScope calldata scope) external override guarded {
        if (msg.sender != governanceAuthority || governanceAuthority.codehash != authorityCodeHash)
        {
            revert S.ScopedPolicySnapshotAuthority(msg.sender);
        }
        (bytes32 actionScope, bytes32 oldState, bytes32 newState) = lockTransition(scope);
        (
            bool executing,
            bytes32 action,
            uint8 cls,
            bytes32 suppliedScope,
            bytes32 oldHash,
            bytes32 newHash
        ) = abi.decode(
            Reads.read(
                governanceAuthority,
                abi.encodeCall(IStreamGovernedParameterAuthority.currentAction, ()),
                192,
                gasParameter(READ_GAS)
            ),
            (bool, bytes32, uint8, bytes32, bytes32, bytes32)
        );
        if (
            !executing || action == 0 || cls != 2 || suppliedScope != actionScope
                || oldHash != oldState || newHash != newState
        ) revert S.ScopedPolicySnapshotAuthority(msg.sender);
        S.Receipt memory r = currentSnapshot(scope);
        requireCurrent(scope, r.recordHash, r.revision);
        if (block.timestamp == 0 || block.timestamp > type(uint64).max) {
            revert S.InvalidScopedPolicySnapshot();
        }
        _locks[r.scopeSubject] = S.Lock(r.recordHash, r.revision, action, uint64(block.timestamp));
        emit ScopedPolicySnapshotLocked(2, r.scopeSubject, _locks[r.scopeSubject]);
    }

    function snapshotLock(StreamFinalityScope calldata scope)
        external
        view
        override
        returns (S.Lock memory)
    {
        return _locks[Sources.scopeSubject(_fixed, scope)];
    }

    function snapshotCount(StreamFinalityScope calldata scope)
        external
        view
        override
        returns (uint256)
    {
        return _history[Sources.scopeSubject(_fixed, scope)].length;
    }

    function snapshotAt(StreamFinalityScope calldata scope, uint256 index)
        external
        view
        override
        returns (bytes32)
    {
        return _history[Sources.scopeSubject(_fixed, scope)][index];
    }

    function _candidate(S.Publication memory p) private view {
        bytes32 subject = Sources.scopeSubject(_fixed, p.scope);
        if (_locks[subject].actionId != 0) revert S.ScopedPolicySnapshotLocked(subject);
        if (
            p.snapshotId == 0 || p.reasonHash == 0 || p.effectiveAt == 0
                || p.effectiveAt > block.timestamp || block.timestamp > type(uint64).max
                || p.expectedRevision == type(uint64).max || _ids[subject][p.snapshotId] != 0
        ) revert S.InvalidScopedPolicySnapshot();
        if (_head(subject) != p.expectedHead || _history[subject].length != p.expectedRevision) {
            revert S.ScopedPolicySnapshotLineage(p.expectedHead, _head(subject));
        }
        StreamMetadataRenderer.requireValidUtf8ContentUri(
            "snapshotManifestURI", p.manifestURI, 2048, true
        );
    }

    function _receipt(S.Publication memory p, address publisher)
        private
        view
        returns (S.Receipt memory r)
    {
        r.scopeSubject = Sources.scopeSubject(_fixed, p.scope);
        r.predecessor = p.expectedHead;
        r.revision = p.expectedRevision + 1;
        r.publisher = publisher;
        (r.authorizationClass, r.grantRevision) =
            _authority(p.scope.collectionId, Families.SNAPSHOT, publisher);
        (r.displayAuthorizationClass, r.displayGrantRevision) =
            _authority(p.scope.collectionId, Families.IDENTITY, publisher);
        r.schemaHash = Definitions.SCHEMA_HASH;
        r.profileHash = Definitions.PROFILE_HASH;
        r.canonicalizationHash = Definitions.CANON_HASH;
    }

    function _authority(uint256 cid, bytes32 family, address actor)
        private
        view
        returns (uint8, uint64)
    {
        if (actor == address(0)) revert S.ScopedPolicySnapshotAuthority(actor);
        for (uint8 i; i < 2; ++i) {
            uint8 cls = i == 0 ? 7 : 8;
            bytes memory raw = Reads.read(
                metadataHost,
                abi.encodeCall(Metadata.familyWriter, (i == 0 ? cid : 0, family, cls, actor)),
                64,
                gasParameter(READ_GAS)
            );
            (bool enabled, uint64 rev) = abi.decode(raw, (bool, uint64));
            if (keccak256(raw) != keccak256(abi.encode(enabled, rev))) {
                revert S.InvalidScopedPolicySnapshot();
            }
            if (enabled && rev != 0) return (cls, rev);
        }
        revert S.ScopedPolicySnapshotAuthority(actor);
    }

    function _assemble(S.Publication memory p, S.Receipt memory r)
        private
        view
        returns (bytes32 hash, bytes memory canonical)
    {
        S.Dependencies memory d = dependencies();
        _definitions(d);
        S.Source memory f = Sources.current(d, p);
        hash = Sources.sourceHash(d, f);
        r.sourceHash = hash;
        p.expectedSourceHash = 0; // The actual hash is present in receipt/source; no preview circularity.
        canonical = abi.encode(
            keccak256("6529STREAM_SCOPED_POLICY_SNAPSHOT_PAYLOAD_V2"),
            d.chainId,
            address(this),
            d.targets,
            d.codeHashes,
            p,
            r,
            f
        );
        if (canonical.length > 524288) revert S.InvalidScopedPolicySnapshot();
    }

    function _definitions(S.Dependencies memory d) private view {
        Documents.Dependencies memory known;
        for (uint256 i; i < 4; ++i) {
            known.targets[i] = d.targets[i];
            known.codeHashes[i] = d.codeHashes[i];
        }
        known.chainId = d.chainId;
        known.readGas = d.readGas;
        Documents.definition(
            known,
            Definitions.SCHEMA_ID,
            Schema.DocumentKind.SCHEMA,
            Definitions.SCHEMA_HASH,
            Definitions.SCHEMA_BYTES,
            keccak256("RAW_BYTES"),
            true
        );
        Documents.definition(
            known,
            Definitions.PROFILE_ID,
            Schema.DocumentKind.CATALOG,
            Definitions.PROFILE_HASH,
            Definitions.PROFILE_BYTES,
            keccak256("RAW_BYTES"),
            true
        );
        Documents.definition(
            known,
            Definitions.CANON_ID,
            Schema.DocumentKind.CANONICALIZATION,
            Definitions.CANON_HASH,
            Definitions.CANON_BYTES,
            keccak256("RAW_BYTES"),
            true
        );
    }

    function _head(bytes32 subject) private view returns (bytes32) {
        uint256 n = _history[subject].length;
        return n == 0 ? bytes32(0) : _history[subject][n - 1];
    }

    /// @dev TOKEN subjects identify a global tokenId and do not encode collectionId. Scope-bound
    /// currentness and lock actions additionally authenticate the complete recorded scope tuple.
    function _requireExactScope(bytes32 hash, StreamFinalityScope memory scope) private view {
        if (keccak256(abi.encode(_publications[hash].scope)) != keccak256(abi.encode(scope))) {
            revert S.InvalidScopedPolicySnapshot();
        }
    }

    function _known(bytes32 hash) private view returns (S.Receipt memory r) {
        r = _receipts[hash];
        if (hash == 0 || r.recordHash != hash) revert S.ScopedPolicySnapshotUnknown(hash);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import {
    IStreamScriptBundles as B
} from "../../interfaces/stream/metadata/IStreamScriptBundles.sol";
import {
    StreamCollectionManifestTypes as M
} from "../../interfaces/stream/metadata/StreamCollectionManifestTypes.sol";
import {
    IStreamGasParameterHost as BundleGasHost
} from "../../interfaces/stream/parameters/IStreamGasParameterHost.sol";
import { Strings } from "../../vendor/openzeppelin/Strings.sol";
import { SSTORE2 } from "../../libraries/SSTORE2.sol";
import { StreamMetadataRenderer } from "./StreamMetadataRenderer.sol";

/// @notice Write-once logical chunks; a full 24,576-byte chunk uses two physical STOP blobs.
library StreamScriptBundles {
    bytes32 public constant PROFILE = keccak256("6529STREAM_ROUTER_CHUNKED_PRESENTATION_V1");

    struct Chunk {
        bytes32 hash;
        uint32 length;
        address first;
        address tail;
    }

    struct Bundle {
        B.Facts facts;
        Chunk[] chunks;
        uint8 nextChunk;
        uint8 utf8Remaining;
        uint8 utf8Min;
        uint8 utf8Max;
    }

    struct State {
        mapping(bytes32 => Bundle) bundles;
        mapping(bytes32 => bytes32) manifests;
        mapping(bytes32 => B.RegistrySource) registrySources;
    }
    event ScriptBundleBegun(
        uint16 schemaVersion,
        bytes32 indexed bundleId,
        bytes32 payloadHash,
        bytes32 libraryBundle,
        uint32 totalBytes,
        uint8 chunks,
        bool libraryOnly
    );
    event ScriptBundleChunkStored(
        uint16 schemaVersion,
        bytes32 indexed bundleId,
        uint256 indexed index,
        bytes32 payloadHash,
        address first,
        address tail
    );
    event ScriptBundleFinalized(
        uint16 schemaVersion, bytes32 indexed bundleId, bytes32 payloadHash
    );

    function write(State storage s, bytes calldata data) public returns (bytes memory) {
        bytes4 selector = bytes4(data);
        if (selector == B.beginScriptBundle.selector) {
            return abi.encode(begin(s, abi.decode(data[4:], (B.Plan))));
        }
        if (selector == B.beginRegistryLibrary.selector) {
            (B.Plan memory p, B.RegistrySource memory source) =
                abi.decode(data[4:], (B.Plan, B.RegistrySource));
            return abi.encode(beginRegistry(s, p, source));
        }
        if (selector == B.appendScriptBundle.selector) {
            (bytes32 id, uint256 index, bytes memory payload) =
                abi.decode(data[4:], (bytes32, uint256, bytes));
            append(s, id, index, payload);
            return "";
        }
        if (selector == B.finalizeScriptBundle.selector) {
            finish(s, abi.decode(data[4:], (bytes32)));
            return "";
        }
        revert B.InvalidScriptBundle(0);
    }

    function read(State storage s, bytes calldata data) public view returns (bytes memory) {
        bytes4 selector = bytes4(data);
        if (selector == B.scriptBundle.selector) {
            return abi.encode(facts(s, abi.decode(data[4:], (bytes32))));
        }
        if (selector == B.dependencyManifest.selector) {
            return abi.encode(dependencyManifest(s, abi.decode(data[4:], (bytes32))));
        }
        if (selector == B.scriptBundleRegistry.selector) {
            return abi.encode(registry(s, abi.decode(data[4:], (bytes32))));
        }
        if (selector == B.recordedScriptBundle.selector) {
            return abi.encode(s.manifests[abi.decode(data[4:], (bytes32))]);
        }
        if (selector == B.scriptBundleChunk.selector || selector == B.dependencyChunk.selector) {
            (bytes32 id, uint256 index) = abi.decode(data[4:], (bytes32, uint256));
            return abi.encode(
                selector == B.dependencyChunk.selector
                    ? dependency(s, id, index)
                    : chunk(s, id, index)
            );
        }
        if (selector == B.scriptBundleChunks.selector) {
            (bytes32 id, uint256 start, uint256 count) =
                abi.decode(data[4:], (bytes32, uint256, uint256));
            return abi.encode(page(s, id, start, count));
        }
        revert B.InvalidScriptBundle(0);
    }

    function begin(State storage s, B.Plan memory p) public returns (bytes32) {
        if (p.sourceType == M.PayloadSourceType.DEPENDENCY_REGISTRY) {
            revert B.InvalidScriptBundle(0);
        }
        return _begin(s, p, 0);
    }

    function _begin(State storage s, B.Plan memory p, bytes32 sourceHash)
        private
        returns (bytes32 id)
    {
        uint256 count = p.chunkHashes.length;
        if (
            count == 0 || count > 32 || p.chunkLengths.length != count || p.payloadHash == 0
                || (p.sourceType != M.PayloadSourceType.INLINE_CHUNKS
                    && p.sourceType != M.PayloadSourceType.SSTORE2
                    && !(p.libraryOnly && p.sourceType == M.PayloadSourceType.DEPENDENCY_REGISTRY))
                || (p.libraryOnly && p.libraryBundle != 0)
        ) revert B.InvalidScriptBundle(0);
        if (p.libraryBundle != 0) {
            B.Facts memory lib = facts(s, p.libraryBundle);
            if (!lib.finalized || !lib.libraryOnly) revert B.InvalidScriptBundle(p.libraryBundle);
        }
        uint32 total;
        uint256 cap = p.sourceType == M.PayloadSourceType.SSTORE2 ? 24576 : 8192;
        for (uint256 i; i < count; ++i) {
            if (p.chunkLengths[i] == 0 || p.chunkLengths[i] > cap || p.chunkHashes[i] == 0) {
                revert B.InvalidScriptBundle(0);
            }
            total += p.chunkLengths[i];
        }
        id = keccak256(
            abi.encode(
                keccak256("6529STREAM_IMMUTABLE_SCRIPT_BUNDLE_V1"),
                block.chainid,
                address(this),
                p,
                sourceHash
            )
        );
        Bundle storage b = s.bundles[id];
        if (b.facts.chunkCount != 0) return id;
        b.facts = B.Facts(
            p.payloadHash, p.libraryBundle, total, uint8(count), p.sourceType, p.libraryOnly, false
        );
        for (uint256 i; i < count; ++i) {
            b.chunks.push(Chunk(p.chunkHashes[i], p.chunkLengths[i], address(0), address(0)));
        }
        emit ScriptBundleBegun(
            1, id, p.payloadHash, p.libraryBundle, total, uint8(count), p.libraryOnly
        );
    }

    function beginRegistry(State storage s, B.Plan memory p, B.RegistrySource memory source)
        public
        returns (bytes32 id)
    {
        if (
            !p.libraryOnly || p.libraryBundle != 0
                || p.sourceType != M.PayloadSourceType.DEPENDENCY_REGISTRY
                || source.registry.code.length == 0 || source.registry.codehash != source.codeHash
                || source.version == 0 || source.dependencyId == 0
        ) revert B.InvalidScriptBundle(0);
        uint256 count = abi.decode(
            _registryRead(
                source,
                abi.encodeWithSignature(
                    "getDependencyScriptCountAtVersion(bytes32,uint256)",
                    source.dependencyId,
                    source.version
                ),
                32
            ),
            (uint256)
        );
        if (
            count == 0 || count > 32 || count != p.chunkHashes.length
                || count != p.chunkLengths.length
        ) {
            revert B.InvalidScriptBundle(0);
        }
        bytes32[] memory typedHashes = new bytes32[](count);
        for (uint256 i; i < count; ++i) {
            typedHashes[i] = keccak256(
                abi.encode(
                    keccak256(
                        "6529StreamDependencyScriptChunk(uint256 index,bytes32 chunkHash,uint256 byteLength)"
                    ),
                    i,
                    p.chunkHashes[i],
                    uint256(p.chunkLengths[i])
                )
            );
            if (
                abi.decode(
                        _registryRead(
                            source,
                            abi.encodeWithSignature(
                                "getDependencyScriptChunkHashAtVersion(bytes32,uint256,uint256)",
                                source.dependencyId,
                                source.version,
                                i
                            ),
                            32
                        ),
                        (bytes32)
                    ) != typedHashes[i]
            ) revert B.InvalidScriptBundle(0);
        }
        bytes32 sequence;
        for (uint256 i; i < count; ++i) {
            sequence = keccak256(abi.encode(sequence, typedHashes[i]));
        }
        bytes32 content = keccak256(
            abi.encode(
                keccak256(
                    "6529StreamDependencyScript(bytes32 dependencyNameAndVersion,uint256 chunkCount,bytes32 chunksHash)"
                ),
                source.dependencyId,
                count,
                sequence
            )
        );
        if (
            content != source.contentHash
                || abi.decode(
                        _registryRead(
                            source,
                            abi.encodeWithSignature(
                                "getDependencyScriptContentHashAtVersion(bytes32,uint256)",
                                source.dependencyId,
                                source.version
                            ),
                            32
                        ),
                        (bytes32)
                    ) != content
        ) revert B.InvalidScriptBundle(0);
        id = _begin(s, p, keccak256(abi.encode(source)));
        s.registrySources[id] = source;
    }

    function registry(State storage s, bytes32 id) public view returns (B.RegistrySource memory) {
        facts(s, id);
        return s.registrySources[id];
    }

    function dependencyManifest(State storage s, bytes32 id)
        public
        view
        returns (M.DependencyManifest memory m)
    {
        B.Facts memory f = facts(s, id);
        if (!f.finalized || !f.libraryOnly) revert B.InvalidScriptBundle(id);
        B.RegistrySource memory source = s.registrySources[id];
        m.dependencyId = id;
        m.dependencyHash = f.payloadHash;
        m.sourceType = f.sourceType;
        m.sourcePointer = Strings.toHexString(uint256(id), 32);
        m.mimeType = "application/javascript";
        if (source.registry != address(0)) {
            m.version = Strings.toString(source.version);
            m.useDependencyRegistry = true;
        }
    }

    function dependency(State storage s, bytes32 id, uint256 index)
        public
        view
        returns (bytes memory)
    {
        B.Facts memory f = facts(s, id);
        if (!f.finalized || !f.libraryOnly) revert B.InvalidScriptBundle(id);
        return chunk(s, id, index);
    }

    function _registryRead(B.RegistrySource memory source, bytes memory data, uint256 max)
        private
        view
        returns (bytes memory raw)
    {
        if (source.registry.codehash != source.codeHash || source.registry.code.length == 0) {
            revert B.InvalidScriptBundle(0);
        }
        bool ok;
        uint256 size;
        address target = source.registry;
        uint256 cap = BundleGasHost(address(this))
            .gasParameter(keccak256("6529STREAM_GGP_METADATA_DEPENDENCY_READ_GAS"));
        if (gasleft() <= cap + cap / 63 + 100000) revert B.InvalidScriptBundle(0);
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(data, 32), mload(data), 0, 0)
            size := returndatasize()
        }
        if (!ok || size > max || size < 32) revert B.InvalidScriptBundle(0);
        raw = new bytes(size);
        assembly ("memory-safe") { returndatacopy(add(raw, 32), 0, size) }
    }

    function append(State storage s, bytes32 id, uint256 index, bytes memory payload) public {
        Bundle storage b = s.bundles[id];
        if (index >= b.chunks.length) revert B.InvalidScriptBundle(id);
        Chunk storage c = b.chunks[index];
        if (payload.length != c.length || keccak256(payload) != c.hash) {
            revert B.InvalidScriptBundle(id);
        }
        if (index < b.nextChunk) {
            chunk(s, id, index);
            return;
        }
        if (b.facts.finalized || index != b.nextChunk) revert B.InvalidScriptBundle(id);
        _utf8(b, payload, id);
        ++b.nextChunk;
        if (b.facts.sourceType == M.PayloadSourceType.DEPENDENCY_REGISTRY) {
            // Pin reads to the originally authenticated version; no latest-version lookup.
            if (keccak256(chunk(s, id, index)) != c.hash) revert B.InvalidScriptBundle(id);
            emit ScriptBundleChunkStored(1, id, index, c.hash, address(0), address(0));
            return;
        }
        if (payload.length <= 24575) {
            c.first = SSTORE2.write(payload);
        } else {
            bytes memory first = new bytes(24575);
            _copy(payload, first, 0, 24575);
            c.first = SSTORE2.write(first);
            bytes memory tail = new bytes(1);
            tail[0] = payload[24575];
            c.tail = SSTORE2.write(tail);
        }
        emit ScriptBundleChunkStored(1, id, index, c.hash, c.first, c.tail);
    }

    function finish(State storage s, bytes32 id) public {
        B.Facts memory f = facts(s, id);
        Bundle storage b = s.bundles[id];
        if (b.nextChunk != f.chunkCount || b.utf8Remaining != 0) revert B.InvalidScriptBundle(id);
        bytes memory payload = assembled(s, id);
        if (keccak256(payload) != f.payloadHash) revert B.InvalidScriptBundle(id);
        if (f.finalized) return;
        s.bundles[id].facts.finalized = true;
        emit ScriptBundleFinalized(1, id, f.payloadHash);
    }

    /// @dev Streaming canonical UTF-8, including a code point crossing logical chunk boundaries.
    /// Validation work is bounded per append; finalize only reconstructs and hashes once.
    function _utf8(Bundle storage b, bytes memory raw, bytes32 id) private {
        uint8 remaining = b.utf8Remaining;
        uint8 lo = b.utf8Min;
        uint8 hi = b.utf8Max;
        for (uint256 i; i < raw.length; ++i) {
            uint8 c = uint8(raw[i]);
            if (remaining != 0) {
                if (c < lo || c > hi) revert B.InvalidScriptBundle(id);
                --remaining;
                lo = 0x80;
                hi = 0xbf;
                continue;
            }
            if (c < 0x80) continue;
            lo = 0x80;
            hi = 0xbf;
            if (c >= 0xc2 && c <= 0xdf) {
                remaining = 1;
            } else if (c >= 0xe0 && c <= 0xef) {
                remaining = 2;
                if (c == 0xe0) lo = 0xa0;
                else if (c == 0xed) hi = 0x9f;
            } else if (c >= 0xf0 && c <= 0xf4) {
                remaining = 3;
                if (c == 0xf0) lo = 0x90;
                else if (c == 0xf4) hi = 0x8f;
            } else {
                revert B.InvalidScriptBundle(id);
            }
        }
        b.utf8Remaining = remaining;
        b.utf8Min = lo;
        b.utf8Max = hi;
    }

    function facts(State storage s, bytes32 id) public view returns (B.Facts memory f) {
        f = s.bundles[id].facts;
        if (f.chunkCount == 0) revert B.InvalidScriptBundle(id);
    }

    function chunk(State storage s, bytes32 id, uint256 index)
        public
        view
        returns (bytes memory payload)
    {
        Bundle storage b = s.bundles[id];
        if (index >= b.chunks.length) revert B.InvalidScriptBundle(id);
        Chunk storage c = b.chunks[index];
        if (b.facts.sourceType == M.PayloadSourceType.DEPENDENCY_REGISTRY) {
            B.RegistrySource memory source = s.registrySources[id];
            bytes memory raw = _registryRead(
                source,
                abi.encodeWithSignature(
                    "getDependencyScriptAtVersion(bytes32,uint256,uint256)",
                    source.dependencyId,
                    source.version,
                    index
                ),
                8256
            );
            string memory text = abi.decode(raw, (string));
            payload = bytes(text);
            if (
                keccak256(raw) != keccak256(abi.encode(text)) || payload.length != c.length
                    || keccak256(payload) != c.hash
            ) revert B.InvalidScriptBundle(id);
            return payload;
        }
        if (
            c.first.code.length != (c.length > 24575 ? 24576 : uint256(c.length) + 1)
                || (c.length > 24575 ? c.tail.code.length != 2 : c.tail != address(0))
        ) revert B.InvalidScriptBundle(id);
        payload = SSTORE2.read(c.first);
        if (c.tail != address(0)) payload = bytes.concat(payload, SSTORE2.read(c.tail));
        if (payload.length != c.length || keccak256(payload) != c.hash) {
            revert B.InvalidScriptBundle(id);
        }
    }

    function page(State storage s, bytes32 id, uint256 start, uint256 count)
        public
        view
        returns (bytes[] memory result)
    {
        uint256 total = facts(s, id).chunkCount;
        // At most four logical chunks per page; callers can reconstruct all 32 in bounded reads.
        if (count > 4 || start > total || count > total - start) revert B.InvalidScriptBundle(id);
        result = new bytes[](count);
        for (uint256 i; i < count; ++i) {
            result[i] = chunk(s, id, start + i);
        }
    }

    function assembled(State storage s, bytes32 id) public view returns (bytes memory payload) {
        B.Facts memory f = facts(s, id);
        payload = new bytes(f.totalBytes);
        uint256 offset;
        for (uint256 i; i < f.chunkCount; ++i) {
            bytes memory part = chunk(s, id, i);
            _copy(part, payload, offset, part.length);
            offset += part.length;
        }
    }

    function _copy(bytes memory src, bytes memory dst, uint256 offset, uint256 length)
        private
        pure
    {
        // Byte tail avoids clobbering a following part or writing past the allocated buffer.
        uint256 n = length & ~uint256(31);
        assembly ("memory-safe") {
            let out := add(add(dst, 32), offset)
            let input := add(src, 32)
            for { let i := 0 } lt(i, n) { i := add(i, 32) } {
                mstore(add(out, i), mload(add(input, i)))
            }
        }
        for (uint256 i = n; i < length; ++i) {
            dst[offset + i] = src[i];
        }
    }

    function pointer(string memory text) public pure returns (bytes32 id) {
        bytes memory raw = bytes(text);
        if (raw.length != 66 || raw[0] != "0" || raw[1] != "x") revert B.InvalidScriptBundle(0);
        uint256 value;
        for (uint256 i = 2; i < 66; ++i) {
            uint8 c = uint8(raw[i]);
            uint8 v;
            if (c >= 48 && c <= 57) v = c - 48;
            else if (c >= 97 && c <= 102) v = c - 87;
            else revert B.InvalidScriptBundle(0);
            value = (value << 4) | v;
        }
        id = bytes32(value);
    }

    function manifest(
        State storage s,
        address core,
        address router,
        uint256 collectionId,
        M.ScriptManifest memory m
    ) public view returns (bytes32 hash, bytes32 id) {
        id = pointer(m.sourcePointer);
        B.Facts memory f = facts(s, id);
        if (
            !f.finalized || f.libraryOnly || !m.executable || m.rendererCompatibility != PROFILE
                || m.scriptHash != f.payloadHash || m.chunkCount != f.chunkCount
                || m.sourceType != f.sourceType
                || keccak256(bytes(m.mimeType)) != keccak256("application/javascript")
        ) revert B.InvalidScriptBundle(id);
        StreamMetadataRenderer.requireValidUtf8ContentUri("scriptURI", m.scriptURI, 2048, true);
        StreamMetadataRenderer.requireValidUtf8ContentUri("libraryURI", m.libraryURI, 2048, true);
        if (f.libraryBundle == 0 && bytes(m.libraryURI).length != 0) {
            revert B.InvalidScriptBundle(id);
        }
        hash = keccak256(
            abi.encode(
                keccak256("6529STREAM_CHUNKED_SCRIPT_MANIFEST_V1"),
                block.chainid,
                core,
                address(this),
                router,
                router.codehash,
                collectionId,
                id,
                f,
                m
            )
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "../../interfaces/stream/metadata/StreamArtistDisplayTypes.sol";
import "../../vendor/openzeppelin/Strings.sol";
import { StreamStaticText } from "./StreamStaticText.sol";

/// @notice Exact nested AA-DISPLAY serialization, separate from the historical renderer profile.
library StreamStaticArtistJSON {
    using Strings for uint256;

    function unavailable() internal pure returns (bytes memory) {
        return '{"state":"attribution_unavailable"}';
    }

    function nested(bytes memory object) internal pure returns (bytes memory) {
        return abi.encodePacked(',"properties":{"provenance":{"attribution":', object, "}}");
    }

    function render(StreamArtistDisplayTypes.Facts memory f)
        internal
        pure
        returns (bytes memory out)
    {
        if (
            f.state < 1 || f.state > 5 || f.collaborators.length > 32
                || (f.claimCount == 0) != (f.latestClaim == 0)
                || (f.contested && (!f.hasPlatformHistory || f.contestRecord == 0))
        ) revert StreamArtistDisplayTypes.DisplayFactsUnavailable();
        out = abi.encodePacked(
            '{"state":"',
            stateName(f.state),
            '","works_class":"',
            f.platform ? "platform_works" : "artist_bound",
            '","consent_mode":"',
            modeName(f.consentMode),
            '"'
        );
        if (!f.platform) {
            if (
                f.artistId == 0 || f.artist == address(0) || f.identityRecord == 0
                    || f.generation == 0 || f.consentMode == 3
            ) revert StreamArtistDisplayTypes.DisplayFactsUnavailable();
            out = abi.encodePacked(
                out,
                ',"artist_id":"',
                hex32(f.artistId),
                '","artist_address":"',
                uint256(uint160(f.artist)).toHexString(20),
                '","artist_display_name":"',
                name(f.name),
                '","identity_record_hash":"',
                hex32(f.identityRecord),
                '","binding_generation":',
                uint256(f.generation).toString(),
                ',"corrected_attribution":',
                boolean(f.corrected)
            );
            if (f.deploymentRecord != 0) {
                out = abi.encodePacked(
                    out, ',"deployment_attestation":"', hex32(f.deploymentRecord), '"'
                );
            }
            out = abi.encodePacked(
                out, ',"attestation_status":"', attestationName(f.attestationStatus), '"'
            );
            if (f.attestationRecord != 0) {
                if (f.attestationStatus == 0) {
                    revert StreamArtistDisplayTypes.DisplayFactsUnavailable();
                }
                out = abi.encodePacked(
                    out,
                    ',"attestation_record":"',
                    hex32(f.attestationRecord),
                    '","attestation_authority_class":"',
                    authority(f.attestationClass),
                    '","attested_state_hash":"',
                    hex32(f.attestedHash),
                    '"'
                );
            } else if (f.attestationStatus != 0 || f.attestedHash != 0 || f.attestationClass != 0) {
                revert StreamArtistDisplayTypes.DisplayFactsUnavailable();
            }
        } else if (f.consentMode != 3 || f.artistId != 0 || f.artist != address(0)) {
            revert StreamArtistDisplayTypes.DisplayFactsUnavailable();
        }
        if (f.collaborators.length != 0) {
            out = abi.encodePacked(out, ',"collaborators":[');
            for (uint256 i; i < f.collaborators.length; ++i) {
                StreamArtistDisplayTypes.Collaborator memory c = f.collaborators[i];
                if (c.account == address(0) || c.artistId == 0 || c.identityRecord == 0) {
                    revert StreamArtistDisplayTypes.DisplayFactsUnavailable();
                }
                out = abi.encodePacked(
                    out,
                    i == 0 ? "" : ",",
                    '{"artist_id":"',
                    hex32(c.artistId),
                    '","account":"',
                    uint256(uint160(c.account)).toHexString(20),
                    '","role":"',
                    hex32(c.role),
                    '","verification_state":"artist_accepted","artist_display_name":"',
                    name(c.name),
                    '","identity_record_hash":"',
                    hex32(c.identityRecord),
                    '"}'
                );
            }
            out = abi.encodePacked(out, "]");
        }
        if (f.sanctionRecord != 0) {
            out = abi.encodePacked(
                out,
                ',"sanction_record":"',
                hex32(f.sanctionRecord),
                '","sanction_authority_class":"',
                authority(f.sanctionClass),
                '"'
            );
        } else if (f.sanctionClass != 0) {
            revert StreamArtistDisplayTypes.DisplayFactsUnavailable();
        }
        if (f.platform || f.corrected) {
            out = abi.encodePacked(out, ',"contested":', boolean(f.contested));
            if (f.contested) {
                out = abi.encodePacked(out, ',"contest_record":"', hex32(f.contestRecord), '"');
            }
        }
        out = abi.encodePacked(out, ',"claim_count":', f.claimCount.toString());
        if (f.claimCount != 0) {
            out = abi.encodePacked(out, ',"latest_claim_record":"', hex32(f.latestClaim), '"');
        }
        return abi.encodePacked(out, "}");
    }

    function name(string memory value) private pure returns (string memory) {
        if (
            bytes(value).length == 0 || bytes(value).length > 256
                || !StreamStaticText.isValidUtf8(value)
        ) revert StreamArtistDisplayTypes.DisplayFactsUnavailable();
        return StreamStaticText.escapeJsonString(value);
    }

    function boolean(bool value) private pure returns (string memory) {
        return value ? "true" : "false";
    }

    function hex32(bytes32 value) private pure returns (string memory) {
        return uint256(value).toHexString(32);
    }

    function stateName(uint8 value) private pure returns (string memory) {
        if (value == 1) return "claimed";
        if (value == 2) return "artist_accepted";
        if (value == 3) return "artist_sanctioned";
        if (value == 4) return "disputed";
        if (value == 5) return "revoked";
        revert StreamArtistDisplayTypes.DisplayFactsUnavailable();
    }

    function modeName(uint8 value) private pure returns (string memory) {
        if (value == 1) return "artist_signed_policy";
        if (value == 2) return "artist_delegated";
        if (value == 3) return "platform_works";
        revert StreamArtistDisplayTypes.DisplayFactsUnavailable();
    }

    function authority(uint8 value) private pure returns (string memory) {
        if (value == 1) return "artist";
        if (value == 2) return "delegate";
        if (value == 3) return "successor";
        if (value == 4) return "steward";
        revert StreamArtistDisplayTypes.DisplayFactsUnavailable();
    }

    function attestationName(uint8 value) private pure returns (string memory) {
        if (value == 0) return "none";
        if (value == 1) return "attested_current";
        if (value == 2) return "attested_stale";
        if (value == 3) return "disputed";
        revert StreamArtistDisplayTypes.DisplayFactsUnavailable();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import {
    IStreamStaticArtistSource
} from "../../interfaces/stream/metadata/IStreamStaticArtistSource.sol";
import "./StreamStaticArtistJSON.sol";
import { StreamMetadataDisplayParameters } from "./StreamMetadataDisplayParameters.sol";
import {
    StreamFinalityNativeProviderReads
} from "../finality/StreamFinalityNativeProviderReads.sol";
import {
    IStreamFinalityDiscoverySources
} from "../../interfaces/stream/finality/IStreamFinalityDiscoverySources.sol";
import "./StreamStaticScopeSource.sol";
import "../../interfaces/stream/artist/IStreamArtistDisplayFacts.sol";
import "../../interfaces/stream/artist/IStreamArtistAttributionState.sol";
import "../../interfaces/stream/artist/IStreamArtistAttribution.sol";
import "../../interfaces/stream/artist/IStreamArtistIdentityRevision.sol";
import "../../interfaces/stream/artist/IStreamArtistCollaboratorLifecycle.sol";
import "../../interfaces/stream/artist/IStreamArtistPlatformWorks.sol";
import "../../interfaces/stream/artist/IStreamArtistSanction.sol";
import "../../interfaces/stream/metadata/IStreamCollectionSnapshots.sol";
import "../../interfaces/stream/finality/IStreamFinalityTokenScopeInventory.sol";

/// @notice Bounded live facts only. The caller catches this whole frame for AA-DISPLAY fallback.
library StreamStaticArtistReads {
    uint256 internal constant MAX_SCOPES = 64;

    struct State {
        uint8 attribution;
        uint64 generation;
        bytes32 artistId;
        uint8 authorityStatus;
        bytes32 bindingHash;
    }

    struct Attestation {
        uint8 status;
        bytes32 recordHash;
        bytes32 attestedHash;
        uint8 authorityClass;
        uint64 signedAt;
    }

    function object(
        address router,
        uint256 chainId,
        address core,
        address artist,
        bytes32 artistCodeHash,
        address original,
        bytes32 originalCodeHash,
        uint256 collection,
        uint256 token
    ) internal view returns (bytes memory) {
        _pin(artist, artistCodeHash);
        StreamMetadataRecoveryRoutes.Pointer memory p = abi.decode(
            _read(
                core,
                abi.encodeCall(
                    IStreamCorePointers.getSatellitePointer, (keccak256("ARTIST_REGISTRY"))
                ),
                320
            ),
            (StreamMetadataRecoveryRoutes.Pointer)
        );
        if (
            p.target != artist || p.codeHash != artistCodeHash || p.status != 1 || p.revision == 0
                || _address(artist, abi.encodeWithSignature("core()")) != core
        ) _fail();
        bytes memory stateRaw = _read(
            artist,
            abi.encodeCall(IStreamArtistAttributionState.collectionArtistState, (collection)),
            160
        );
        State memory s = abi.decode(stateRaw, (State));
        T.Binding memory b = abi.decode(
            _read(
                artist, abi.encodeCall(IStreamArtistDisplayFacts.displayBinding, (collection)), 320
            ),
            (T.Binding)
        );
        PW.State memory platform = abi.decode(
            _read(
                artist,
                abi.encodeCall(IStreamArtistPlatformWorks.platformWorksState, (collection)),
                640
            ),
            (PW.State)
        );
        StreamArtistDisplayTypes.Facts memory f;
        if (
            s.attribution > 5 || s.generation != b.generation || s.artistId != b.artistId
                || s.bindingHash != b.bindingHash || platform.contestState > 3
        ) _fail();
        f.platform = platform.declaration.recordHash != 0 && !platform.correction.accepted;
        f.hasPlatformHistory = platform.declaration.recordHash != 0;
        f.corrected = platform.correction.accepted;
        f.contested = platform.contestState == 1 || platform.contestState == 3;
        f.contestRecord = platform.contestRecord;
        if (f.platform) {
            f.state = f.contested ? 4 : 1;
            f.consentMode = 3;
            f.claimCount = platform.claimCount;
            f.latestClaim = platform.latestClaim;
        } else {
            if (
                b.artistId == 0 || b.generation == 0 || b.bindingHash == 0 || s.attribution == 0
                    || (s.attribution >= 2 && s.attribution <= 3 && !b.accepted)
            ) _fail();
            f.state = s.attribution;
            // Sanction is resolved below for this exact token/scope, never globally inferred.
            if (f.state == 3) f.state = 2;
            f.consentMode = b.consentMode;
            f.artistId = b.artistId;
            f.generation = b.generation;
            IStreamCollectionArtistRegistry.Attribution memory a = abi.decode(
                _read(
                    artist, abi.encodeCall(IStreamArtistAttribution.attribution, (collection)), 224
                ),
                (IStreamCollectionArtistRegistry.Attribution)
            );
            if (
                a.nominationHash != b.bindingHash || a.nominationRevision != b.generation
                    || a.nominatedArtist != b.artistAddress
            ) _fail();
            f.artist = b.accepted ? a.artist : b.artistAddress;
            (f.name, f.identityRecord) = _name(artist, b.artistId);
            (f.claimCount, f.latestClaim) = abi.decode(
                _read(
                    artist,
                    abi.encodeCall(IStreamArtistDisplayFacts.attributionClaims, (collection)),
                    64
                ),
                (uint256, bytes32)
            );
            (f.deploymentRecord,,) = abi.decode(
                _read(
                    artist,
                    abi.encodeCall(IStreamArtistDisplayFacts.deploymentAttestation, (collection)),
                    96
                ),
                (bytes32, uint8, uint64)
            );
            f.collaborators = _collaborators(artist, collection, b.generation);
            _attestation(router, chainId, core, artist, original, originalCodeHash, collection, f);
            if (f.state == 2) {
                _sanctions(
                    router, core, artist, original, originalCodeHash, collection, token, b, f
                );
            }
        }
        // Keep the complete raw binding and state stable across the selected source reads.
        if (
            keccak256(stateRaw)
                    != keccak256(
                        _read(
                            artist,
                            abi.encodeCall(
                                IStreamArtistAttributionState.collectionArtistState, (collection)
                            ),
                            160
                        )
                    )
                || keccak256(abi.encode(b))
                    != keccak256(
                        _read(
                            artist,
                            abi.encodeCall(IStreamArtistDisplayFacts.displayBinding, (collection)),
                            320
                        )
                    )
        ) _fail();
        return StreamStaticArtistJSON.render(f);
    }

    function _name(address artist, bytes32 id)
        private
        view
        returns (string memory value, bytes32 record)
    {
        bytes memory raw = _bounded(
            artist,
            abi.encodeCall(IStreamArtistIdentityRevisionReads.artistDisplayName, (id)),
            352,
            StreamMetadataDisplayParameters.value(StreamMetadataDisplayParameters.READ_GAS)
        );
        (value, record) = abi.decode(raw, (string, bytes32));
        if (
            keccak256(raw) != keccak256(abi.encode(value, record)) || record == 0
                || record
                    != abi.decode(
                        _read(
                            artist,
                            abi.encodeCall(
                                IStreamArtistIdentityRevisionReads.operativeIdentityRecord, (id)
                            ),
                            32
                        ),
                        (bytes32)
                    )
        ) _fail();
    }

    function _collaborators(address artist, uint256 collection, uint64 generation)
        private
        view
        returns (StreamArtistDisplayTypes.Collaborator[] memory out)
    {
        uint256 n = abi.decode(
            _read(
                artist,
                abi.encodeCall(
                    IStreamArtistCollaboratorLifecycle.collaboratorCount, (collection, generation)
                ),
                32
            ),
            (uint256)
        );
        if (n > 32) _fail();
        out = new StreamArtistDisplayTypes.Collaborator[](n);
        uint256 count;
        for (uint256 i; i < n; ++i) {
            C.Row memory row = abi.decode(
                _read(
                    artist,
                    abi.encodeCall(
                        IStreamArtistCollaboratorLifecycle.collaboratorAt,
                        (collection, generation, i)
                    ),
                    192
                ),
                (C.Row)
            );
            if (!row.accepted) continue;
            if (
                row.account == address(0) || row.collaboratorArtistId == 0
                    || row.acceptanceRecordHash == 0
            ) _fail();
            (string memory label, bytes32 record) = _name(artist, row.collaboratorArtistId);
            out[count++] = StreamArtistDisplayTypes.Collaborator(
                row.account, row.collaboratorArtistId, row.role, label, record
            );
        }
        assembly ("memory-safe") { mstore(out, count) }
    }

    function _attestation(
        address router,
        uint256 chainId,
        address core,
        address artist,
        address original,
        bytes32 originalHash,
        uint256 collection,
        StreamArtistDisplayTypes.Facts memory f
    ) private view {
        _pin(original, originalHash);
        if (
            _address(original, abi.encodeCall(IStreamFinalityDeploymentBindings.coreReads, ()))
                != core
        ) _fail();
        address provider = _address(
            original, abi.encodeCall(IStreamFinalityDeploymentBindings.scopeEvidenceProvider, ())
        );
        _pin(
            provider,
            abi.decode(
                _read(
                    original,
                    abi.encodeCall(
                        IStreamFinalityDeploymentBindings.scopeEvidenceProviderCodeHash, ()
                    ),
                    32
                ),
                (bytes32)
            )
        );
        StreamFinalityNativeProviderReads.Config memory c = abi.decode(
            _read(provider, abi.encodeWithSignature("nativeConfiguration()"), 1568),
            (StreamFinalityNativeProviderReads.Config)
        );
        address source =
            _address(provider, abi.encodeCall(IStreamFinalityDiscoverySources.snapshotHost, ()));
        if (
            c.chainId != chainId || c.targets[0] != core || c.targets[2] != router
                || c.targets[8] != source || c.targets[12] != original
                || c.codeHashes[12] != originalHash
        ) _fail();
        _pin(core, c.codeHashes[0]);
        _pin(router, c.codeHashes[2]);
        _pin(source, c.codeHashes[8]);
        _pin(c.targets[1], c.codeHashes[1]);
        if (
            _address(original, abi.encodeCall(IStreamFinalityDeploymentBindings.metadataReads, ()))
                    != c.targets[1] || _address(provider, abi.encodeWithSignature("core()")) != core
                || _address(
                        provider,
                        abi.encodeCall(IStreamFinalityRouterEvidenceBinding.metadataRouter, ())
                    ) != router
                || _address(source, abi.encodeCall(IStreamCollectionSnapshots.core, ())) != core
                || _address(source, abi.encodeCall(IStreamCollectionSnapshots.metadataRouter, ()))
                    != router
                || _address(source, abi.encodeCall(IStreamCollectionSnapshots.metadataHost, ()))
                    != c.targets[1]
        ) _fail();
        StreamSnapshotTypes.Receipt memory receipt = abi.decode(
            _read(
                source,
                abi.encodeCall(IStreamCollectionSnapshots.currentSnapshot, (collection)),
                672
            ),
            (StreamSnapshotTypes.Receipt)
        );
        bytes32 manifest = abi.decode(
            _read(
                source,
                abi.encodeCall(IStreamCollectionSnapshots.latestSnapshotHash, (collection)),
                32
            ),
            (bytes32)
        );
        if (receipt.recordHash == 0) {
            StreamSnapshotTypes.Receipt memory empty;
            if (manifest != 0 || keccak256(abi.encode(receipt)) != keccak256(abi.encode(empty))) {
                _fail();
            }
            return;
        }
        if (
            receipt.collectionId != collection || receipt.snapshotId == 0 || manifest == 0
                || manifest != receipt.manifestHash
                || manifest
                    != abi.decode(
                        _read(
                            source,
                            abi.encodeCall(
                                IStreamCollectionSnapshots.snapshotHash,
                                (collection, receipt.snapshotId)
                            ),
                            32
                        ),
                        (bytes32)
                    )
        ) _fail();
        Attestation memory a = abi.decode(
            _read(
                artist,
                abi.encodeCall(
                    IStreamArtistDisplayFacts.artistAttestationStatus,
                    (collection, uint8(1), receipt.snapshotId, manifest)
                ),
                160
            ),
            (Attestation)
        );
        f.attestationStatus = a.status;
        f.attestationRecord = a.recordHash;
        f.attestedHash = a.attestedHash;
        f.attestationClass = a.authorityClass;
    }

    function _sanctions(
        address router,
        address core,
        address artist,
        address original,
        bytes32 originalHash,
        uint256 collection,
        uint256 token,
        T.Binding memory b,
        StreamArtistDisplayTypes.Facts memory f
    ) private view {
        // Collection scope always covers its current tokens. Token scope is exact.
        _sanction(
            artist, StreamFinalityScope(StreamFinalityScopeType.COLLECTION, collection, 0, 0), b, f
        );
        if (token == 0) return;
        _sanction(
            artist, StreamFinalityScope(StreamFinalityScopeType.TOKEN, collection, token, 0), b, f
        );
        address membership = StreamStaticScopeSource.host(
            core, router, StreamMetadataRecoveryRoutes.OriginalAnchor(original, originalHash)
        );
        uint256 n = abi.decode(
            _read(
                membership,
                abi.encodeCall(IStreamFinalityTokenScopeInventory.tokenScopeCount, (token)),
                32
            ),
            (uint256)
        );
        if (n > MAX_SCOPES) _fail();
        for (uint256 i; i < n; ++i) {
            (StreamFinalityScope memory scope, bool complete) = abi.decode(
                _bounded(
                    membership,
                    abi.encodeCall(IStreamFinalityTokenScopeInventory.tokenScopeAt, (token, i)),
                    160,
                    StreamMetadataDisplayParameters.value(
                        StreamMetadataDisplayParameters.MEMBERSHIP_GAS
                    )
                ),
                (StreamFinalityScope, bool)
            );
            if (!complete) continue;
            if (
                scope.collectionId != collection || uint8(scope.scopeType) < 2 || scope.tokenId != 0
                    || scope.scopeId == 0
                    || abi.decode(
                            _bounded(
                                membership,
                                abi.encodeCall(
                                    IStreamFinalityScopeMembership.scopeCoversToken, (scope, token)
                                ),
                                32,
                                StreamMetadataDisplayParameters.value(
                                    StreamMetadataDisplayParameters.MEMBERSHIP_GAS
                                )
                            ),
                            (uint256)
                        ) != 1
            ) _fail();
            _sanction(artist, scope, b, f);
        }
    }

    function _sanction(
        address artist,
        StreamFinalityScope memory scope,
        T.Binding memory b,
        StreamArtistDisplayTypes.Facts memory f
    ) private view {
        S.Record memory r = abi.decode(
            _read(artist, abi.encodeCall(IStreamArtistDisplayFacts.displaySanction, (scope)), 512),
            (S.Record)
        );
        if (r.recordHash == 0) {
            S.Record memory empty;
            if (keccak256(abi.encode(r)) != keccak256(abi.encode(empty))) _fail();
            return;
        }
        if (
            r.artistId != b.artistId || r.bindingGeneration != b.generation
                || r.bindingHash != b.bindingHash || r.signer == address(0)
                || r.terms.scopeType != uint8(scope.scopeType)
                || r.terms.collectionId != scope.collectionId || r.terms.tokenId != scope.tokenId
                || r.terms.scopeId != scope.scopeId
        ) _fail();
        (bool valid, bytes32 hash, address signer, uint8 authorityClass) = abi.decode(
            _read(
                artist,
                abi.encodeCall(
                    IStreamFinalitySanctionReads.verifySanctionForSubject,
                    (
                        r.terms.scopeType,
                        scope.collectionId,
                        scope.tokenId,
                        scope.scopeId,
                        r.terms.sanctionSubjectHash
                    )
                ),
                128
            ),
            (bool, bytes32, address, uint8)
        );
        if (
            !valid || hash != r.recordHash || signer != r.signer
                || authorityClass != r.authorityClass || authorityClass == 0 || authorityClass > 4
        ) _fail();
        f.state = 3;
        // All covering scopes are inspected. First deterministic scope supplies the linked record.
        if (f.sanctionRecord == 0) {
            f.sanctionRecord = hash;
            f.sanctionClass = authorityClass;
        }
    }

    function _pin(address target, bytes32 hash) private view {
        if (target.code.length == 0 || hash == 0 || target.codehash != hash) _fail();
    }

    function _address(address target, bytes memory input) private view returns (address) {
        return abi.decode(_read(target, input, 32), (address));
    }

    function _read(address target, bytes memory input, uint256 length)
        private
        view
        returns (bytes memory raw)
    {
        raw = _bounded(
            target,
            input,
            length,
            StreamMetadataDisplayParameters.value(StreamMetadataDisplayParameters.READ_GAS)
        );
        if (raw.length != length) _fail();
    }

    function _bounded(address target, bytes memory input, uint256 maximum, uint256 cap)
        private
        view
        returns (bytes memory raw)
    {
        bool wrapped = _artistSelector(bytes4(input));
        if (wrapped) input = abi.encodeCall(IStreamStaticArtistSource.staticDisplayRead, (input));
        uint256 outerMaximum = wrapped ? 64 + ((maximum + 31) / 32) * 32 : maximum;
        uint256 available = gasleft();
        if (target.code.length == 0 || available <= 10000) _fail();
        available -= 10000;
        if (cap > available || available - cap < cap / 63) _fail();
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(input, 32), mload(input), 0, 0)
            size := returndatasize()
        }
        if (!ok || size > outerMaximum) _fail();
        raw = new bytes(size);
        assembly ("memory-safe") { returndatacopy(add(raw, 32), 0, size) }
        if (wrapped) {
            bytes memory value = abi.decode(raw, (bytes));
            if (value.length > maximum || keccak256(raw) != keccak256(abi.encode(value))) _fail();
            raw = value;
        }
    }

    function _artistSelector(bytes4 s) private pure returns (bool) {
        return s == IStreamArtistAttributionState.collectionArtistState.selector
            || s == IStreamArtistDisplayFacts.displayBinding.selector
            || s == IStreamArtistPlatformWorks.platformWorksState.selector
            || s == IStreamArtistAttribution.attribution.selector
            || s == IStreamArtistDisplayFacts.attributionClaims.selector
            || s == IStreamArtistDisplayFacts.deploymentAttestation.selector
            || s == IStreamArtistIdentityRevisionReads.artistDisplayName.selector
            || s == IStreamArtistIdentityRevisionReads.operativeIdentityRecord.selector
            || s == IStreamArtistCollaboratorLifecycle.collaboratorCount.selector
            || s == IStreamArtistCollaboratorLifecycle.collaboratorAt.selector
            || s == IStreamArtistDisplayFacts.artistAttestationStatus.selector
            || s == IStreamArtistDisplayFacts.displaySanction.selector
            || s == IStreamFinalitySanctionReads.verifySanctionForSubject.selector;
    }

    function _fail() private pure {
        revert StreamArtistDisplayTypes.DisplayFactsUnavailable();
    }
}

