pragma solidity ^0.8.19;

import {
    StreamRenderCriticalSourceTypes as S
} from "../../interfaces/stream/preservation/StreamRenderCriticalSourceTypes.sol";
import {
    StreamPreservationInventoryTypes as V
} from "../../interfaces/stream/preservation/StreamPreservationInventoryTypes.sol";
import { StreamPreservationInventoryIO as IO } from "./StreamPreservationInventoryIO.sol";
import { StreamPreservationInventoryItems as Items } from "./StreamPreservationInventoryItems.sol";
import {
    StreamArtistOnboardingTypes as A
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";
import {
    StreamArtistRecordPublicationTypes as P
} from "../../interfaces/stream/artist/StreamArtistRecordPublicationTypes.sol";
import {
    StreamArtistRotationTypes as R
} from "../../interfaces/stream/artist/StreamArtistRotationTypes.sol";
import "../../interfaces/stream/artist/IStreamArtistArchiveV2.sol";
import "../../interfaces/stream/artist/IStreamArtistRecordPublicationOwner.sol";
import "../records/StreamRecordArtistIdentityReads.sol";
import "../artist/StreamArtistHashes.sol";
import "../artist/StreamArtistContentHashes.sol";
import "../../interfaces/stream/artist/IStreamArtistContentOwner.sol";
import "../../interfaces/stream/artist/StreamArtistContentTypes.sol";
import "../../interfaces/stream/metadata/IStreamContentRootPublication.sol";

/// @notice Exact state-retained op24 original signed payload and signature correspondence.
/// @dev Actor is an untrusted archive locator, distinct from the original signer. No current
/// key, grant, ERC1271 owner set, consumed nonce or deadline is re-applied to historical proof.
library StreamPreservationArtistBundleReads {
    struct Envelope {
        uint16 version;
        bytes32 configurationHash;
        uint16 operationId;
        address actor;
        bytes32 record;
        A.Snapshot[7] before_;
        A.Snapshot[7] after_;
        bytes payload;
    }

    struct Payload {
        A.Binding binding;
        A.Attestation attestation;
        A.Authorization submitted;
        bytes statement;
        A.SignerApproval approval;
        A.Authorization effective;
        R.AuthorityFact authority;
        P.Publication publication;
        bytes32 metadataCodeHash;
    }

    struct Loaded {
        A.SuiteConfiguration suite;
        address coordinator;
        bytes32 id;
        bytes evidence;
    }

    struct ContentPayload {
        A.Binding binding;
        StreamArtistContentTypes.Consent terms;
        A.Authorization authorization;
        A.SignerApproval approval;
        bytes32 priorState;
    }

    function item(
        S.Dependencies memory d,
        P.Evidence memory expected,
        bytes32 originalRecord,
        address actor
    ) public view returns (V.Item memory result) {
        if (actor == address(0) || expected.attestationRecordHash == 0 || originalRecord == 0) revert V.InvalidInventoryItem();
        Loaded memory loaded = _load(d, expected.attestationRecordHash, actor, 24);
        bool direct = _decode(d, expected, originalRecord, actor, loaded);
        bytes32 retentionHash =
            _retained(loaded.suite.archive, loaded.id, loaded.evidence, d.readGas);
        result = Items.bytesItem(
            V.Kind.STATE_BUNDLE,
            keccak256("ORIGINAL_ARTIST_PUBLICATION_AUTHORIZATION"),
            loaded.suite.archive,
            loaded.id,
            1,
            loaded.evidence
        );
        result.provenanceHash = keccak256(
            abi.encode(
                originalRecord,
                expected,
                actor,
                d.artistTargets,
                d.artistCodeHashes,
                retentionHash,
                direct
            )
        );
    }

    function contentItem(
        S.Dependencies memory d,
        S.Context memory c,
        address actor,
        uint64 originalObservedAt
    ) public view returns (V.Item memory result) {
        bytes memory raw = IO.read(
            d.targets[4],
            abi.encodeCall(IStreamContentRootPublication.contentRootRecord, (c.rootRecordHash)),
            8192,
            d.sourceGas
        );
        IStreamContentRootPublication.Record memory root =
            abi.decode(raw, (IStreamContentRootPublication.Record));
        IO.canonical(d.targets[4], raw, abi.encode(root));
        if (
            keccak256(
                        abi.encode(
                            keccak256("6529STREAM_CONTENT_ROOT_RECORD_V1"),
                            d.chainId,
                            d.targets[4],
                            root
                        )
                    ) != c.rootRecordHash || root.artistId != c.artistId
                || root.publication.collectionId != c.collectionId || root.artistConsent == 0
                || actor == address(0)
        ) revert V.InvalidInventoryItem();
        Loaded memory loaded = _load(d, root.artistConsent, actor, 17);
        _contentOriginal(d, root, actor, originalObservedAt, loaded);
        bytes32 retained = _retained(loaded.suite.archive, loaded.id, loaded.evidence, d.readGas);
        result = Items.bytesItem(
            V.Kind.STATE_BUNDLE,
            keccak256("ORIGINAL_CONTENT_ROOT_AUTHORIZATION"),
            loaded.suite.archive,
            loaded.id,
            1,
            loaded.evidence
        );
        result.provenanceHash =
            _contentProvenance(d, c.rootRecordHash, actor, originalObservedAt, retained);
    }

    function _contentProvenance(
        S.Dependencies memory d,
        bytes32 rootRecord,
        address actor,
        uint64 observedAt,
        bytes32 retained
    ) private pure returns (bytes32) {
        return keccak256(
            abi.encode(rootRecord, actor, observedAt, retained, keccak256(abi.encode(d)))
        );
    }

    function _contentOriginal(
        S.Dependencies memory d,
        IStreamContentRootPublication.Record memory root,
        address actor,
        uint64 observedAt,
        Loaded memory loaded
    ) private view {
        IO.pin(d.artistContentOwner, d.artistContentOwnerCodeHash);
        if (loaded.suite.owners[6] != d.artistContentOwner) revert V.InvalidInventoryItem();
        ContentPayload memory p = _decodeContent(d, root.artistConsent, actor, loaded);
        uint8 class_ = _contentSaved(d, root, p);
        if (
            observedAt == 0 || observedAt > root.publishedAt || p.authorization.time < observedAt
                || (p.approval.direct
                        ? (actor != p.approval.signer || p.authorization.signature.length != 0)
                        : p.authorization.signature.length == 0)
        ) revert V.InvalidInventoryItem();
        StreamArtistHashes.Environment memory e = StreamArtistHashes.Environment(
            d.chainId, loaded.suite.registry, d.targets[0], loaded.suite.mintManager
        );
        if (
            p.approval.digest
                    != StreamArtistContentHashes.consentDigest(e, p.terms, p.authorization)
                || StreamArtistContentHashes.consentRecord(
                        e,
                        p.terms,
                        root.artistId,
                        p.approval.signer,
                        class_,
                        p.authorization.nonce,
                        observedAt
                    ) != root.artistConsent
        ) revert V.InvalidInventoryItem();
    }

    function _decodeContent(
        S.Dependencies memory d,
        bytes32 record,
        address actor,
        Loaded memory loaded
    ) private view returns (ContentPayload memory p) {
        bytes memory wrapped = bytes.concat(bytes32(uint256(32)), loaded.evidence);
        Envelope memory envelope = abi.decode(wrapped, (Envelope));
        IO.canonical(loaded.suite.archive, wrapped, abi.encode(envelope));
        if (
            envelope.version != 1 || envelope.operationId != 17 || envelope.actor != actor
                || envelope.record != record
                || envelope.configurationHash
                    != IO.word(
                        loaded.coordinator,
                        abi.encodeWithSignature("configurationHash()"),
                        d.readGas
                    )
        ) revert V.InvalidInventoryItem();
        wrapped = bytes.concat(bytes32(uint256(32)), envelope.payload);
        p = abi.decode(wrapped, (ContentPayload));
        IO.canonical(loaded.suite.archive, wrapped, abi.encode(p));
    }

    function _contentSaved(
        S.Dependencies memory d,
        IStreamContentRootPublication.Record memory root,
        ContentPayload memory p
    ) private view returns (uint8) {
        bytes memory raw = IO.fixedRead(
            d.artistContentOwner,
            abi.encodeCall(
                IStreamArtistContentRecordsOwner.contentConsentRecord, (root.artistConsent)
            ),
            256,
            d.readGas
        );
        IStreamArtistContentRecordsOwner.ConsentRecord memory saved =
            abi.decode(raw, (IStreamArtistContentRecordsOwner.ConsentRecord));
        IO.canonical(d.artistContentOwner, raw, abi.encode(saved));
        if (
            saved.recordHash != root.artistConsent || saved.artistId != root.artistId
                || saved.bindingGeneration != root.bindingGeneration
                || (saved.authorityClass != 1 && saved.authorityClass != 3)
                || keccak256(abi.encode(saved.terms)) != keccak256(abi.encode(p.terms))
                || p.terms.collectionId != root.publication.collectionId
                || p.terms.metadataContract != d.targets[4]
                || p.terms.familyId != keccak256("CONTENT_ROOT")
                || p.terms.newStateHash != root.stateHash || p.binding.artistId != root.artistId
                || p.binding.bindingHash != root.bindingHash
                || p.binding.generation != root.bindingGeneration || !p.binding.accepted
                || p.approval.signer == address(0) || p.priorState == 0
                || p.priorState == root.stateHash
        ) revert V.InvalidInventoryItem();
        return saved.authorityClass;
    }

    function _load(S.Dependencies memory d, bytes32 record, address actor, uint16 op)
        private
        view
        returns (Loaded memory loaded)
    {
        StreamRecordArtistIdentityReads.Pins memory pins =
            StreamRecordArtistIdentityReads.resolve(
                d.targets[1], d.targets[0], d.chainId, d.readGas
            );
        for (uint256 i; i < 5; ++i) {
            IO.pin(d.artistTargets[i], d.artistCodeHashes[i]);
        }
        for (uint256 i; i < 3; ++i) {
            if (
                pins.targets[i] != d.artistTargets[i] || pins.codeHashes[i] != d.artistCodeHashes[i]
            ) {
                revert V.InvalidInventoryItem();
            }
        }
        bytes memory raw = IO.fixedRead(
            pins.targets[1],
            abi.encodeCall(IStreamArtistSuiteReads.suiteConfiguration, ()),
            544,
            d.readGas
        );
        A.SuiteConfiguration memory suite = abi.decode(raw, (A.SuiteConfiguration));
        IO.canonical(pins.targets[1], raw, abi.encode(suite));
        if (
            suite.registry != pins.targets[0] || suite.core != d.targets[0]
                || suite.metadata != d.targets[4] || suite.owners[2] != pins.targets[2]
                || suite.owners[4] != d.artistTargets[3] || suite.archive != d.artistTargets[4]
        ) revert V.InvalidInventoryItem();
        if (
            IO.word(
                        suite.archive,
                        abi.encodeCall(IStreamArtistArchiveV2.artistRegistry, ()),
                        d.readGas
                    ) != bytes32(uint256(uint160(suite.registry)))
                || IO.word(
                        suite.archive,
                        abi.encodeCall(IStreamArtistArchiveV2.operationCoordinator, ()),
                        d.readGas
                    ) != bytes32(uint256(uint160(pins.targets[1])))
        ) revert V.InvalidInventoryItem();
        loaded.suite = suite;
        loaded.coordinator = pins.targets[1];
        loaded.id = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_ONBOARDING_OPERATION_EVIDENCE_V1"),
                d.chainId,
                suite.registry,
                pins.targets[1],
                op,
                actor,
                record
            )
        );
        raw = IO.read(
            suite.archive,
            abi.encodeCall(IStreamArtistArchiveV2.artistEvidenceBytesV2, (loaded.id, 1)),
            65600,
            d.sourceGas
        );
        loaded.evidence = abi.decode(raw, (bytes));
        IO.canonical(suite.archive, raw, abi.encode(loaded.evidence));
    }

    function _decode(
        S.Dependencies memory d,
        P.Evidence memory expected,
        bytes32 originalRecord,
        address actor,
        Loaded memory loaded
    ) private view returns (bool) {
        bytes memory wrapped = bytes.concat(bytes32(uint256(32)), loaded.evidence);
        Envelope memory envelope = abi.decode(wrapped, (Envelope));
        IO.canonical(loaded.suite.archive, wrapped, abi.encode(envelope));
        if (
            envelope.version != 1 || envelope.operationId != 24 || envelope.actor != actor
                || envelope.record != expected.attestationRecordHash
                || envelope.configurationHash
                    != IO.word(
                        loaded.coordinator,
                        abi.encodeWithSignature("configurationHash()"),
                        d.readGas
                    )
        ) revert V.InvalidInventoryItem();
        wrapped = bytes.concat(bytes32(uint256(32)), envelope.payload);
        Payload memory p = abi.decode(wrapped, (Payload));
        IO.canonical(loaded.suite.archive, wrapped, abi.encode(p));
        _original(d, expected, originalRecord, actor, loaded.suite, p);
        return p.approval.direct;
    }

    function _retained(address archive, bytes32 id, bytes memory evidence, uint256 readGas)
        private
        view
        returns (bytes32)
    {
        bytes memory raw = IO.fixedRead(
            archive,
            abi.encodeCall(IStreamArtistArchiveV2.artistEvidenceMetadataV2, (id, 1)),
            128,
            readGas
        );
        (bytes32 hash, address pointer, uint32 size, uint64 appendedAt) =
            abi.decode(raw, (bytes32, address, uint32, uint64));
        IO.canonical(archive, raw, abi.encode(hash, pointer, size, appendedAt));
        if (
            hash != keccak256(evidence) || size != evidence.length || appendedAt == 0
                || pointer.code.length != size + 1
        ) {
            revert V.InvalidInventoryItem();
        }
        bytes memory retained = new bytes(size + 1);
        assembly ("memory-safe") { extcodecopy(pointer, add(retained, 32), 0, add(size, 1)) }
        if (retained[0] != 0 || keccak256(retained) != keccak256(bytes.concat(hex"00", evidence))) {
            revert V.InvalidInventoryItem();
        }
        return keccak256(abi.encode(id, hash, pointer, pointer.codehash, size, appendedAt));
    }

    function _original(
        S.Dependencies memory d,
        P.Evidence memory expected,
        bytes32 record,
        address actor,
        A.SuiteConfiguration memory suite,
        Payload memory p
    ) private view {
        bytes memory raw = IO.fixedRead(
            suite.owners[4],
            abi.encodeCall(
                IStreamArtistRecordPublicationOwner.publicationAttestation,
                (expected.attestationRecordHash)
            ),
            704,
            d.readGas
        );
        IStreamArtistRecordPublicationOwner.Record memory saved =
            abi.decode(raw, (IStreamArtistRecordPublicationOwner.Record));
        IO.canonical(suite.owners[4], raw, abi.encode(saved));
        if (
            keccak256(abi.encode(saved.evidence)) != keccak256(abi.encode(expected))
                || keccak256(abi.encode(saved.publication)) != keccak256(abi.encode(p.publication))
                || saved.metadataHostCodeHash != d.codeHashes[1]
                || p.metadataCodeHash != d.codeHashes[1]
                || p.publication.metadataHost != d.targets[1]
                || p.publication.candidateRecordHash != record
                || p.publication.recorder != expected.signer
                || keccak256(abi.encode(p.publication)) != expected.publicationHash
                || p.binding.artistId != expected.artistId
                || p.binding.bindingHash != expected.bindingHash
                || p.binding.generation != expected.bindingGeneration || !p.binding.accepted
                || p.authority.artistId != expected.artistId
                || p.authority.authorityAddress != expected.signer
                || p.authority.authorityClass != expected.authorityClass
                || p.approval.signer != expected.signer || p.effective.time != expected.signedAt
                || p.effective.nonce != p.submitted.nonce
                || keccak256(p.effective.signature) != keccak256(p.submitted.signature)
                || p.attestation.collectionId != p.publication.collectionId
                || p.attestation.subjectId != p.publication.subjectId
                || p.attestation.schemaId != keccak256("6529STREAM_ARTIST_RECORD_PUBLICATION_V1")
                || p.attestation.statementHash != keccak256(p.statement)
                || keccak256(p.statement) != keccak256(abi.encode(uint16(1), p.publication))
                || (p.attestation.subjectKind == 7
                        ? p.attestation.subjectStateHash != record
                        : p.attestation.subjectKind != 8 || p.attestation.subjectStateHash != 0)
        ) revert V.InvalidInventoryItem();
        if (p.approval.direct) {
            if (
                actor != expected.signer || p.effective.signature.length != 0
                    || (p.submitted.time != 0 && p.submitted.time != p.effective.time)
            ) revert V.InvalidInventoryItem();
        } else if (p.effective.signature.length == 0 || p.submitted.time != p.effective.time) {
            revert V.InvalidInventoryItem();
        }
        bytes32 digest = StreamArtistHashes.attestationDigest(
            StreamArtistHashes.Environment(
                d.chainId, suite.registry, d.targets[0], suite.mintManager
            ),
            p.attestation,
            p.effective
        );
        if (p.approval.digest != digest) revert V.InvalidInventoryItem();
        bytes32 originalHash = StreamArtistHashes.attestationRecordForAuthority(
            StreamArtistHashes.Environment(
                d.chainId, suite.registry, d.targets[0], suite.mintManager
            ),
            p.attestation,
            p.binding.artistId,
            p.authority.authorityAddress,
            p.authority.authorityClass,
            p.effective.nonce,
            p.effective.time
        );
        if (originalHash != expected.attestationRecordHash) revert V.InvalidInventoryItem();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import {
    StreamRenderCriticalSourceTypes as S
} from "../../interfaces/stream/preservation/StreamRenderCriticalSourceTypes.sol";
import {
    StreamPreservationInventoryTypes as T
} from "../../interfaces/stream/preservation/StreamPreservationInventoryTypes.sol";
import { StreamPreservationInventoryIO as IO } from "./StreamPreservationInventoryIO.sol";
import { StreamPreservationInventoryItems as Items } from "./StreamPreservationInventoryItems.sol";
import "../../interfaces/stream/metadata/IStreamSchemaDocumentFacts.sol";
import "../metadata/StreamSchemaDocumentStore.sol";
import { StreamWorkRecordDefinitions as W } from "../records/StreamWorkRecordDefinitions.sol";
import { StreamRightsRecordDefinitions as R } from "../records/StreamRightsRecordDefinitions.sol";
import { StreamConservationDefinitions as C } from "../records/StreamConservationDefinitions.sol";
import { StreamSnapshotDefinitions as Snap } from "../records/StreamSnapshotDefinitions.sol";
import {
    StreamReferenceRenderDefinitions as Ref
} from "../records/StreamReferenceRenderDefinitions.sol";
import "../finality/StreamContentRootSchemas.sol";

/// @notice Complete ordered registered interpretation bytes, including repeated chunks.
library StreamPreservationDocumentReads {
    uint64 internal constant FIXED_COUNT = 30;

    function fixedHash(uint64 index) public pure returns (bytes32) {
        if (index >= FIXED_COUNT) revert T.InvalidInventoryItem();
        if (index >= 26) return StreamContentRootSchemas.definitionHash(fixedId(index));
        if (index == 25) {
            return keccak256(
                bytes(
                    '{"name":"RAW_BYTES","rule":"Do not transform the supplied bytes.","version":1}'
                )
            );
        }
        bytes32[25] memory hashes = [
            W.SCHEMA_HASH,
            W.PROFILE_HASH,
            W.CATALOG_SCHEMA_HASH,
            W.CATALOG_PROFILE_HASH,
            R.SCHEMA_HASH,
            R.PROFILE_HASH,
            C.INTENT_SCHEMA_HASH,
            C.INTENT_PROFILE_HASH,
            C.WAIVER_SCHEMA_HASH,
            C.WAIVER_PROFILE_HASH,
            C.INTERVIEW_SCHEMA_HASH,
            C.INTERVIEW_PROFILE_HASH,
            C.CATALOG_SCHEMA_HASH,
            C.CATALOG_PROFILE_HASH,
            Snap.SCHEMA_HASH,
            Snap.PROFILE_HASH,
            Ref.RENDERER_SCHEMA_HASH,
            Ref.RENDERER_PROFILE_HASH,
            Ref.SCHEMA_HASH,
            Ref.PROFILE_HASH,
            Ref.ENVIRONMENT_SCHEMA_HASH,
            Ref.PNG_SCHEMA_HASH,
            Ref.ZIP_SCHEMA_HASH,
            Ref.FORMAT_CATALOG_HASH,
            Snap.CANON_HASH
        ];
        return hashes[index];
    }

    function currentFactsHash(S.Dependencies memory d, bytes32 id) public view returns (bytes32) {
        IO.pin(d.targets[2], d.codeHashes[2]);
        IO.pin(d.targets[3], d.codeHashes[3]);
        bytes memory raw = IO.fixedRead(
            d.targets[2],
            abi.encodeCall(IStreamSchemaDocumentFacts.documentFacts, (id)),
            288,
            d.readGas
        );
        IStreamSchemaDocumentFacts.DocumentFacts memory facts =
            abi.decode(raw, (IStreamSchemaDocumentFacts.DocumentFacts));
        IO.canonical(d.targets[2], raw, abi.encode(facts));
        if (!facts.exists || facts.status != IStreamSchemaRegistry.DocumentStatus.ACTIVE) {
            revert T.InvalidInventoryItem();
        }
        return keccak256(raw);
    }

    function fixedId(uint64 index) public pure returns (bytes32) {
        if (index >= FIXED_COUNT) revert T.InvalidInventoryItem();
        string[30] memory names = [
            "STREAM_WORK_DESCRIPTION_V1",
            "STREAM_WORK_DESCRIPTION_JSON_PROFILE_V1",
            "STREAM_WORK_FORMAT_CATALOG_V1",
            "STREAM_WORK_FORMAT_CATALOG_JSON_PROFILE_V1",
            "STREAM_RIGHTS_V1",
            "STREAM_RIGHTS_JSON_PROFILE_V1",
            "STREAM_ARTIST_INTENT_V1",
            "STREAM_ARTIST_INTENT_JSON_PROFILE_V1",
            "STREAM_ARTIST_INTENT_WAIVER_V1",
            "STREAM_ARTIST_INTENT_WAIVER_JSON_PROFILE_V1",
            "STREAM_ARTIST_INTERVIEW_V1",
            "STREAM_ARTIST_INTERVIEW_JSON_PROFILE_V1",
            "STREAM_CONSERVATION_FORMAT_CATALOG_V1",
            "STREAM_CONSERVATION_FORMAT_CATALOG_JSON_PROFILE_V1",
            "STREAM_NATIVE_ONCHAIN_SNAPSHOT_V1",
            "STREAM_NATIVE_ONCHAIN_SNAPSHOT_JSON_PROFILE_V1",
            "STREAM_RENDERER_CLASS_DECLARATION_V1",
            "STREAM_RENDERER_CLASS_DECLARATION_JSON_PROFILE_V1",
            "STREAM_NATIVE_REFERENCE_RENDER_V1",
            "STREAM_NATIVE_REFERENCE_RENDER_JSON_PROFILE_V1",
            "STREAM_REFERENCE_NATIVE_ENVIRONMENT_V1",
            "STREAM_REFERENCE_PNG_OBJECT_V1",
            "STREAM_REFERENCE_RUNTIME_ZIP_OBJECT_V1",
            "STREAM_REFERENCE_NATIVE_FORMATS_V1",
            "RFC8785_JCS",
            "RAW_BYTES",
            "STREAM_TOKEN_CONTENT_LEAF_MANIFEST_V1",
            "STREAM_ABI_TOKEN_CONTENT_LEAF_MANIFEST_V1",
            "STREAM_TOKEN_CONTENT_ROOT_RECORD_V1",
            "STREAM_ABI_TOKEN_CONTENT_ROOT_RECORD_V1"
        ];
        return keccak256(bytes(names[index]));
    }

    function item(S.Dependencies memory d, bytes32 id, bytes32 expectedHash)
        public
        view
        returns (T.Item memory result)
    {
        IO.pin(d.targets[2], d.codeHashes[2]);
        IO.pin(d.targets[3], d.codeHashes[3]);
        bytes memory raw = IO.fixedRead(
            d.targets[2],
            abi.encodeCall(IStreamSchemaDocumentFacts.documentFacts, (id)),
            288,
            d.readGas
        );
        IStreamSchemaDocumentFacts.DocumentFacts memory facts =
            abi.decode(raw, (IStreamSchemaDocumentFacts.DocumentFacts));
        IO.canonical(d.targets[2], raw, abi.encode(facts));
        if (
            !facts.exists || facts.status != IStreamSchemaRegistry.DocumentStatus.ACTIVE
                || facts.contentHash == 0 || facts.totalBytes == 0 || facts.chunkCount == 0
                || facts.chunkCount > 64 || (expectedHash != 0 && facts.contentHash != expectedHash)
        ) revert T.InvalidInventoryItem();
        bytes memory complete;
        for (uint256 i; i < facts.chunkCount; ++i) {
            bytes32 hash = IO.word(
                d.targets[2],
                abi.encodeCall(IStreamSchemaDocumentFacts.documentChunkHashAt, (id, i)),
                d.readGas
            );
            raw = IO.read(
                d.targets[3],
                abi.encodeCall(StreamSchemaDocumentStore.readChunk, (hash)),
                8352,
                d.readGas
            );
            bytes memory chunk = abi.decode(raw, (bytes));
            IO.canonical(d.targets[3], raw, abi.encode(chunk));
            if (
                chunk.length == 0 || chunk.length > 8192 || keccak256(chunk) != hash
                    || complete.length + chunk.length > facts.totalBytes
            ) revert T.InvalidInventoryItem();
            complete = bytes.concat(complete, chunk);
        }
        if (complete.length != facts.totalBytes || keccak256(complete) != facts.contentHash) {
            revert T.InvalidInventoryItem();
        }
        result = Items.bytesItem(
            T.Kind.REGISTERED_DOCUMENT,
            keccak256("REGISTERED_INTERPRETATION_DOCUMENT"),
            d.targets[2],
            id,
            0,
            complete
        );
        // The archive object contains these exact bytes; interpreting them is already bound by
        // the original fixed producer. The declaration preimage omits registration URI/name here.
        result.catalogId = id;
        result.catalogHash = facts.contentHash;
        result.provenanceHash = keccak256(abi.encode(facts));
    }

    function authenticateCatalogs(S.Dependencies memory d, T.Item[] memory items) public view {
        for (uint256 i; i < items.length; ++i) {
            if (items[i].kind != T.Kind.REGISTERED_DOCUMENT) continue;
            T.Item memory actual = item(d, items[i].catalogId, items[i].catalogHash);
            if (
                actual.byteSize != items[i].byteSize
                    || keccak256(actual.digest) != keccak256(items[i].digest)
            ) {
                revert T.InvalidInventoryItem();
            }
        }
    }
}

