pragma solidity ^0.8.19;
import {
    StreamRenderCriticalSourceTypes as S
} from "../../interfaces/stream/preservation/StreamRenderCriticalSourceTypes.sol";
import {
    StreamScopedPolicyRenderCriticalTypesV2 as Scoped
} from "../../interfaces/stream/preservation/StreamScopedPolicyRenderCriticalTypesV2.sol";
import {
    StreamPreservationInventoryTypes as T
} from "../../interfaces/stream/preservation/StreamPreservationInventoryTypes.sol";
import {
    IStreamRendererRegistry as V
} from "../../interfaces/stream/metadata/IStreamRendererRegistry.sol";
import { IStreamRenderer as R } from "../../interfaces/stream/metadata/IStreamRenderer.sol";
import {
    IStreamStaticMetadataRouter as Router
} from "../../interfaces/stream/metadata/IStreamStaticMetadataRouter.sol";
import {
    StreamScopedPolicyRenderCriticalTokenReadsV2 as Tokens
} from "./StreamScopedPolicyRenderCriticalTokenReadsV2.sol";
import { StreamPreservationInventoryIO as IO } from "./StreamPreservationInventoryIO.sol";
import { StreamPreservationInventoryItems as Items } from "./StreamPreservationInventoryItems.sol";
import {
    StreamPreservationDocumentReads as Documents
} from "./StreamPreservationDocumentReads.sol";

/// @notice Original retained renderer declaration, complete named target roster and five documents.
/// @dev This worker does not claim transitive opcode conformance. A separately admitted current
/// output profile also requires its own declaration/analysis/goldens/read-set inventory.
library StreamScopedPolicyRenderCriticalRendererReadsV2 {
    struct Original {
        Router.Selection selected;
        V.Version version;
        V.Registration registration;
        V.Read[] reads;
        V.Target[] targets;
        bytes bindings;
        address encoding;
        bytes32 encodingHash;
    }

    function item(S.Dependencies memory d, Scoped.Context memory c, uint64 ordinal, uint64 index)
        public
        view
        returns (T.Item memory row, uint64 count)
    {
        (uint256 token, Tokens.Original memory source) = Tokens.sourceAt(d, c, ordinal);
        Original memory o = _load(d, source.selection.selection, source.selection.sources[3]);
        count = uint64(13 + o.targets.length);
        if (index >= count) revert T.InvalidInventoryItem();
        address registry = o.selected.registry;
        bytes32 key = o.selected.versionKey;
        if (index == 0) {
            return (
                _bytes("RENDERER_RETAINED_VERSION", registry, key, token, abi.encode(o.version)),
                count
            );
        }
        if (index == 1) {
            return (
                _bytes("RENDERER_REGISTRATION", registry, key, token, abi.encode(o.registration)),
                count
            );
        }
        if (index == 2) {
            return
                (
                    _bytes("RENDERER_DECLARED_READS", registry, key, token, abi.encode(o.reads)),
                    count
                );
        }
        if (index == 3) {
            return (
                _bytes("RENDERER_COMPLETE_TARGETS", registry, key, token, abi.encode(o.targets)),
                count
            );
        }
        if (index == 4) {
            return
                (Items.runtime(keccak256("RENDERER_REGISTRY_RUNTIME"), registry, key, token), count);
        }
        if (index == 5) {
            return (
                Items.runtime(
                    keccak256("SELECTED_RENDERER_RUNTIME"), o.selected.renderer, key, token
                ),
                count
            );
        }
        if (index == 6) {
            return (
                _bytes("RENDERER_SOURCE_BINDINGS", o.selected.renderer, key, token, o.bindings),
                count
            );
        }
        if (index == 7) {
            return (
                Items.runtime(keccak256("RENDERER_ENCODING_RUNTIME"), o.encoding, key, token), count
            );
        }
        if (index < 13) {
            bytes32[5] memory ids = [
                o.registration.schemaDocument,
                o.registration.contextDocument,
                o.registration.manifestDocument,
                o.registration.analysisDocument,
                o.registration.goldenDocument
            ];
            bytes32[5] memory hashes = [
                o.registration.manifest.schemaHash,
                bytes32(0),
                o.registration.manifest.manifestHash,
                o.version.analysisHash,
                o.version.goldenHash
            ];
            row = Documents.item(d, ids[index - 8], hashes[index - 8]);
            return (row, count);
        }
        V.Target memory target = o.targets[index - 13];
        row = Items.runtime(target.role, target.target, key, index - 13);
        row.provenanceHash = keccak256(abi.encode(registry, key, target));
    }

    function _load(S.Dependencies memory d, Router.Selection memory selected, address coordinator)
        private
        view
        returns (Original memory o)
    {
        o.selected = selected;
        address registry = selected.registry;
        IO.pin(registry, selected.registryCodeHash);
        IO.pin(selected.renderer, selected.rendererCodeHash);
        if (
            IO.addressWord(registry, abi.encodeWithSignature("schemaRegistry()"), d.readGas)
                    != d.targets[2]
                || IO.word(registry, abi.encodeWithSignature("schemaRegistryCodeHash()"), d.readGas)
                    != d.codeHashes[2]
                || uint256(
                        IO.word(registry, abi.encodeWithSignature("deploymentChainId()"), d.readGas)
                    ) != d.chainId
        ) {
            revert T.InventorySourceChanged();
        }
        bytes memory raw = IO.fixedRead(
            registry, abi.encodeCall(V.version, (selected.versionKey)), 288, d.readGas
        );
        o.version = abi.decode(raw, (V.Version));
        IO.canonical(registry, raw, abi.encode(o.version));
        if (
            !o.version.exists || o.version.renderer != selected.renderer
                || o.version.runtimeHash != selected.rendererCodeHash
                || o.version.registrationHash != selected.registrationHash
                || o.version.readSetHash != selected.readSetHash
        ) {
            revert T.InventorySourceChanged();
        }
        // Deprecated immutable versions remain retained; ordinary new-assignment policy is separate.
        raw = IO.fixedRead(
            registry, abi.encodeCall(V.requireRetained, (selected.versionKey)), 64, d.sourceGas
        );
        (address retained, bytes32 retainedHash) = abi.decode(raw, (address, bytes32));
        IO.canonical(registry, raw, abi.encode(retained, retainedHash));
        if (retained != selected.renderer || retainedHash != selected.rendererCodeHash) {
            revert T.InventorySourceChanged();
        }
        raw = IO.read(
            registry, abi.encodeCall(V.registration, (selected.versionKey)), 8192, d.readGas
        );
        o.registration = abi.decode(raw, (V.Registration));
        IO.canonical(registry, raw, abi.encode(o.registration));
        R.RendererManifest memory m = o.registration.manifest;
        if (
            o.registration.renderer != selected.renderer || m.rendererId != selected.rendererId
                || m.rendererVersion != selected.rendererVersion
                || m.contextVersion != selected.contextVersion
                || m.schemaHash != selected.schemaHash || m.rendererClass != keccak256("STATIC")
                || selected.versionKey
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_RENDERER_VERSION_V1"),
                            m.rendererId,
                            m.rendererVersion
                        )
                    )
        ) {
            revert T.InventorySourceChanged();
        }
        raw = IO.read(selected.renderer, abi.encodeCall(R.rendererManifest, ()), 8192, d.readGas);
        IO.canonical(selected.renderer, raw, abi.encode(m));
        raw = IO.read(registry, abi.encodeCall(V.reads, (selected.versionKey)), 16448, d.readGas);
        o.reads = abi.decode(raw, (V.Read[]));
        IO.canonical(registry, raw, abi.encode(o.reads));
        uint256 n = uint256(IO.word(registry, abi.encodeCall(V.targetCount, ()), d.readGas));
        if (n == 0 || n > 64 || o.reads.length > 128) revert T.InvalidInventoryItem();
        o.targets = new V.Target[](n);
        for (uint256 i; i < n; ++i) {
            raw = IO.fixedRead(registry, abi.encodeCall(V.targetAt, (i)), 96, d.readGas);
            o.targets[i] = abi.decode(raw, (V.Target));
            IO.canonical(registry, raw, abi.encode(o.targets[i]));
            if (i != 0 && o.targets[i].target <= o.targets[i - 1].target) {
                revert T.InvalidInventoryItem();
            }
            IO.pin(o.targets[i].target, o.targets[i].codeHash);
        }
        bytes32 targetsHash = keccak256(abi.encode(o.targets));
        if (
            targetsHash != IO.word(registry, abi.encodeWithSignature("targetSetHash()"), d.readGas)
                || keccak256(
                        abi.encode(
                            keccak256("6529STREAM_RENDERER_READ_SET_V1"), targetsHash, o.reads
                        )
                    ) != selected.readSetHash
                || keccak256(
                        abi.encode(
                            keccak256("6529STREAM_RENDERER_REGISTRATION_V1"),
                            d.chainId,
                            registry,
                            d.targets[2],
                            d.codeHashes[2],
                            targetsHash,
                            o.registration,
                            o.reads
                        )
                    ) != selected.registrationHash
        ) {
            revert T.InventorySourceChanged();
        }
        uint256 previous;
        for (uint256 i; i < o.reads.length; ++i) {
            V.Read memory declared = o.reads[i];
            uint256 order = (uint256(declared.targetIndex) << 32) | uint32(declared.selector);
            if (
                declared.targetIndex >= n || declared.selector == 0 || (i != 0 && order <= previous)
                    || declared.maxReturnBytes == 0 || declared.maxReturnBytes > 16777216
                    || (declared.exact && declared.maxReturnBytes % 32 != 0)
            ) revert T.InvalidInventoryItem();
            previous = order;
        }
        o.bindings = IO.fixedRead(
            selected.renderer, abi.encodeWithSignature("sourceBindings()"), 384, d.readGas
        );
        (address[6] memory sources, bytes32[6] memory pins) =
            abi.decode(o.bindings, (address[6], bytes32[6]));
        IO.canonical(selected.renderer, o.bindings, abi.encode(sources, pins));
        if (
            sources[0] != d.targets[0] || sources[1] != d.targets[4] || sources[2] != d.targets[1]
                || sources[3] != coordinator
        ) revert T.InventorySourceChanged();
        for (uint256 i; i < 6; ++i) {
            if (i == 4 && sources[i] == address(0)) continue;
            IO.pin(sources[i], pins[i]);
        }
        raw = IO.fixedRead(
            selected.renderer, abi.encodeWithSignature("encodingBinding()"), 64, d.readGas
        );
        (o.encoding, o.encodingHash) = abi.decode(raw, (address, bytes32));
        IO.canonical(selected.renderer, raw, abi.encode(o.encoding, o.encodingHash));
        IO.pin(o.encoding, o.encodingHash);
    }

    function _bytes(
        string memory role,
        address host,
        bytes32 record,
        uint256 token,
        bytes memory value
    ) private pure returns (T.Item memory) {
        return Items.bytesItem(
            T.Kind.NATIVE_BYTES, keccak256(bytes(role)), host, record, token, value
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import {
    StreamRenderCriticalSourceTypes as S
} from "../../interfaces/stream/preservation/StreamRenderCriticalSourceTypes.sol";
import {
    StreamPreservationInventoryTypes as V
} from "../../interfaces/stream/preservation/StreamPreservationInventoryTypes.sol";
import { StreamPreservationInventoryIO as IO } from "./StreamPreservationInventoryIO.sol";
import { StreamPreservationInventoryItems as Items } from "./StreamPreservationInventoryItems.sol";
import {
    StreamArtistOnboardingTypes as A
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";
import {
    StreamArtistRecordPublicationTypes as P
} from "../../interfaces/stream/artist/StreamArtistRecordPublicationTypes.sol";
import {
    StreamArtistRotationTypes as R
} from "../../interfaces/stream/artist/StreamArtistRotationTypes.sol";
import "../../interfaces/stream/artist/IStreamArtistArchiveV2.sol";
import "../../interfaces/stream/artist/IStreamArtistRecordPublicationOwner.sol";
import "../records/StreamRecordArtistIdentityReads.sol";
import "../artist/StreamArtistHashes.sol";
import "../artist/StreamArtistContentHashes.sol";
import "../../interfaces/stream/artist/IStreamArtistContentOwner.sol";
import "../../interfaces/stream/artist/StreamArtistContentTypes.sol";
import "../../interfaces/stream/metadata/IStreamScopedContentRootPublication.sol";
import {
    IStreamScopedPolicyContentRootPublicationV2 as RootV2
} from "../../interfaces/stream/metadata/IStreamScopedPolicyContentRootPublicationV2.sol";
import {
    StreamScopedPolicyContentRootSchemasV2 as RootSchemas
} from "../finality/StreamScopedPolicyContentRootSchemasV2.sol";

import {
    StreamScopedPolicyRenderCriticalTypesV2 as Scoped
} from "../../interfaces/stream/preservation/StreamScopedPolicyRenderCriticalTypesV2.sol";
import {
    StreamScopedPolicyRenderCriticalStateV2 as State
} from "./StreamScopedPolicyRenderCriticalStateV2.sol";

/// @notice Original op17 Archive proof for a current scoped root; no re-signing or live nonce use.
/// @dev Historical aggregate/legacy hashes are untrusted preimage witnesses. Exact original
/// record and signed family hashes authenticate them; present aggregate is never substituted.
library StreamScopedPolicyRenderCriticalRootAuthorizationV2 {
    struct Envelope {
        uint16 version;
        bytes32 configurationHash;
        uint16 operationId;
        address actor;
        bytes32 record;
        A.Snapshot[7] before_;
        A.Snapshot[7] after_;
        bytes payload;
    }

    struct Loaded {
        A.SuiteConfiguration suite;
        address coordinator;
        bytes32 id;
        bytes evidence;
    }

    struct ContentPayload {
        A.Binding binding;
        StreamArtistContentTypes.Consent terms;
        A.Authorization authorization;
        A.SignerApproval approval;
        bytes32 priorState;
    }

    function appendRootAuthorization(
        State.State storage state,
        bytes32 id,
        address actor,
        uint64 originalObservedAt,
        IStreamScopedContentRootPublication.Aggregate memory originalAggregate,
        bytes32 originalLegacyFamilyHash
    ) public {
        State.stage(state, id, 6);
        V.Item[] memory rows = new V.Item[](1);
        rows[0] = contentItem(
            state.dependencies,
            state.contexts[id],
            actor,
            originalObservedAt,
            originalAggregate,
            originalLegacyFamilyHash
        );
        State.append(state, id, rows, state.contexts[id].rootRecordHash);
        state.plans[id].progress.completedStages = 7;
    }

    function contentItem(
        S.Dependencies memory d,
        Scoped.Context memory c,
        address actor,
        uint64 originalObservedAt,
        IStreamScopedContentRootPublication.Aggregate memory originalAggregate,
        bytes32 originalLegacyFamilyHash
    ) public view returns (V.Item memory result) {
        bytes memory raw = IO.read(
            d.targets[4],
            abi.encodeCall(
                IStreamScopedContentRootPublication.scopedContentRootRecord, (c.rootRecordHash)
            ),
            16384,
            d.sourceGas
        );
        IStreamScopedContentRootPublication.Record memory record =
            abi.decode(raw, (IStreamScopedContentRootPublication.Record));
        IO.canonical(d.targets[4], raw, abi.encode(record));
        raw = IO.fixedRead(
            d.targets[4],
            abi.encodeCall(RootV2.scopedPolicyContentRootBinding, (c.rootRecordHash)),
            736,
            d.readGas
        );
        RootV2.Binding memory binding = abi.decode(raw, (RootV2.Binding));
        IO.canonical(d.targets[4], raw, abi.encode(binding));
        if (
            originalAggregate.revision == 0 || originalAggregate.transitionChain == 0
                || binding.profileId != RootSchemas.PROFILE || originalLegacyFamilyHash == 0
                || actor == address(0) || record.artistConsent == 0 || record.artistId != c.artistId
                || keccak256(abi.encode(record.publication.scope)) != keccak256(abi.encode(c.scope))
                || record.snapshotHost != d.targets[5] || record.snapshotCodeHash != d.codeHashes[5]
                || record.publication.snapshotRecordHash != c.snapshot.recordHash
                || record.publication.snapshotRevision != c.snapshot.revision
                || keccak256(
                        abi.encode(
                            keccak256("6529STREAM_SCOPED_POLICY_CONTENT_ROOT_RECORD_V2"),
                            d.chainId,
                            d.targets[4],
                            d.targets[0],
                            record,
                            binding,
                            originalAggregate
                        )
                    ) != c.rootRecordHash
        ) {
            revert V.InvalidInventoryItem();
        }
        bytes32 signedFamily = keccak256(
            abi.encode(
                keccak256("6529STREAM_CONTENT_ROOT_FAMILY_WITH_SCOPES_V1"),
                d.chainId,
                d.targets[4],
                d.targets[0],
                c.scope.collectionId,
                originalLegacyFamilyHash,
                originalAggregate
            )
        );
        Loaded memory loaded = _load(d, record.artistConsent, actor, 17);
        _contentOriginal(d, record, signedFamily, actor, originalObservedAt, loaded);
        bytes32 retained = _retained(loaded.suite.archive, loaded.id, loaded.evidence, d.readGas);
        result = Items.bytesItem(
            V.Kind.STATE_BUNDLE,
            keccak256("ORIGINAL_SCOPED_POLICY_CONTENT_ROOT_AUTHORIZATION_V2"),
            loaded.suite.archive,
            loaded.id,
            1,
            loaded.evidence
        );
        result.provenanceHash = keccak256(
            abi.encode(
                c.rootRecordHash,
                binding,
                originalAggregate,
                originalLegacyFamilyHash,
                signedFamily,
                actor,
                originalObservedAt,
                retained,
                keccak256(abi.encode(d))
            )
        );
    }

    function _contentOriginal(
        S.Dependencies memory d,
        IStreamScopedContentRootPublication.Record memory root,
        bytes32 signedFamily,
        address actor,
        uint64 observedAt,
        Loaded memory loaded
    ) private view {
        IO.pin(d.artistContentOwner, d.artistContentOwnerCodeHash);
        if (loaded.suite.owners[6] != d.artistContentOwner) revert V.InvalidInventoryItem();
        ContentPayload memory p = _decodeContent(d, root.artistConsent, actor, loaded);
        uint8 class_ = _contentSaved(d, root, signedFamily, p);
        if (
            observedAt == 0 || observedAt > root.publishedAt || p.authorization.time < observedAt
                || (p.approval.direct
                        ? (actor != p.approval.signer || p.authorization.signature.length != 0)
                        : p.authorization.signature.length == 0)
        ) revert V.InvalidInventoryItem();
        StreamArtistHashes.Environment memory e = StreamArtistHashes.Environment(
            d.chainId, loaded.suite.registry, d.targets[0], loaded.suite.mintManager
        );
        if (
            p.approval.digest
                    != StreamArtistContentHashes.consentDigest(e, p.terms, p.authorization)
                || StreamArtistContentHashes.consentRecord(
                        e,
                        p.terms,
                        root.artistId,
                        p.approval.signer,
                        class_,
                        p.authorization.nonce,
                        observedAt
                    ) != root.artistConsent
        ) revert V.InvalidInventoryItem();
    }

    function _decodeContent(
        S.Dependencies memory d,
        bytes32 record,
        address actor,
        Loaded memory loaded
    ) private view returns (ContentPayload memory p) {
        bytes memory wrapped = bytes.concat(bytes32(uint256(32)), loaded.evidence);
        Envelope memory envelope = abi.decode(wrapped, (Envelope));
        IO.canonical(loaded.suite.archive, wrapped, abi.encode(envelope));
        if (
            envelope.version != 1 || envelope.operationId != 17 || envelope.actor != actor
                || envelope.record != record
                || envelope.configurationHash
                    != IO.word(
                        loaded.coordinator,
                        abi.encodeWithSignature("configurationHash()"),
                        d.readGas
                    )
        ) revert V.InvalidInventoryItem();
        wrapped = bytes.concat(bytes32(uint256(32)), envelope.payload);
        p = abi.decode(wrapped, (ContentPayload));
        IO.canonical(loaded.suite.archive, wrapped, abi.encode(p));
    }

    function _contentSaved(
        S.Dependencies memory d,
        IStreamScopedContentRootPublication.Record memory root,
        bytes32 signedFamily,
        ContentPayload memory p
    ) private view returns (uint8) {
        bytes memory raw = IO.fixedRead(
            d.artistContentOwner,
            abi.encodeCall(
                IStreamArtistContentRecordsOwner.contentConsentRecord, (root.artistConsent)
            ),
            256,
            d.readGas
        );
        IStreamArtistContentRecordsOwner.ConsentRecord memory saved =
            abi.decode(raw, (IStreamArtistContentRecordsOwner.ConsentRecord));
        IO.canonical(d.artistContentOwner, raw, abi.encode(saved));
        if (
            saved.recordHash != root.artistConsent || saved.artistId != root.artistId
                || saved.bindingGeneration != root.bindingGeneration
                || (saved.authorityClass != 1 && saved.authorityClass != 3)
                || keccak256(abi.encode(saved.terms)) != keccak256(abi.encode(p.terms))
                || p.terms.collectionId != root.publication.scope.collectionId
                || p.terms.metadataContract != d.targets[4]
                || p.terms.familyId != keccak256("CONTENT_ROOT")
                || p.terms.newStateHash != signedFamily || p.binding.artistId != root.artistId
                || p.binding.bindingHash != root.bindingHash
                || p.binding.generation != root.bindingGeneration || !p.binding.accepted
                || p.approval.signer == address(0) || p.priorState == 0
                || p.priorState == signedFamily
        ) revert V.InvalidInventoryItem();
        return saved.authorityClass;
    }

    function _load(S.Dependencies memory d, bytes32 record, address actor, uint16 op)
        private
        view
        returns (Loaded memory loaded)
    {
        StreamRecordArtistIdentityReads.Pins memory pins =
            StreamRecordArtistIdentityReads.resolve(
                d.targets[1], d.targets[0], d.chainId, d.readGas
            );
        for (uint256 i; i < 5; ++i) {
            IO.pin(d.artistTargets[i], d.artistCodeHashes[i]);
        }
        for (uint256 i; i < 3; ++i) {
            if (
                pins.targets[i] != d.artistTargets[i] || pins.codeHashes[i] != d.artistCodeHashes[i]
            ) {
                revert V.InvalidInventoryItem();
            }
        }
        bytes memory raw = IO.fixedRead(
            pins.targets[1],
            abi.encodeCall(IStreamArtistSuiteReads.suiteConfiguration, ()),
            544,
            d.readGas
        );
        A.SuiteConfiguration memory suite = abi.decode(raw, (A.SuiteConfiguration));
        IO.canonical(pins.targets[1], raw, abi.encode(suite));
        if (
            suite.registry != pins.targets[0] || suite.core != d.targets[0]
                || suite.metadata != d.targets[4] || suite.owners[2] != pins.targets[2]
                || suite.owners[4] != d.artistTargets[3] || suite.archive != d.artistTargets[4]
        ) revert V.InvalidInventoryItem();
        if (
            IO.word(
                        suite.archive,
                        abi.encodeCall(IStreamArtistArchiveV2.artistRegistry, ()),
                        d.readGas
                    ) != bytes32(uint256(uint160(suite.registry)))
                || IO.word(
                        suite.archive,
                        abi.encodeCall(IStreamArtistArchiveV2.operationCoordinator, ()),
                        d.readGas
                    ) != bytes32(uint256(uint160(pins.targets[1])))
        ) revert V.InvalidInventoryItem();
        loaded.suite = suite;
        loaded.coordinator = pins.targets[1];
        loaded.id = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_ONBOARDING_OPERATION_EVIDENCE_V1"),
                d.chainId,
                suite.registry,
                pins.targets[1],
                op,
                actor,
                record
            )
        );
        raw = IO.read(
            suite.archive,
            abi.encodeCall(IStreamArtistArchiveV2.artistEvidenceBytesV2, (loaded.id, 1)),
            65600,
            d.sourceGas
        );
        loaded.evidence = abi.decode(raw, (bytes));
        IO.canonical(suite.archive, raw, abi.encode(loaded.evidence));
    }

    function _retained(address archive, bytes32 id, bytes memory evidence, uint256 readGas)
        private
        view
        returns (bytes32)
    {
        bytes memory raw = IO.fixedRead(
            archive,
            abi.encodeCall(IStreamArtistArchiveV2.artistEvidenceMetadataV2, (id, 1)),
            128,
            readGas
        );
        (bytes32 hash, address pointer, uint32 size, uint64 appendedAt) =
            abi.decode(raw, (bytes32, address, uint32, uint64));
        IO.canonical(archive, raw, abi.encode(hash, pointer, size, appendedAt));
        if (
            hash != keccak256(evidence) || size != evidence.length || appendedAt == 0
                || pointer.code.length != size + 1
        ) {
            revert V.InvalidInventoryItem();
        }
        bytes memory retained = new bytes(size + 1);
        assembly ("memory-safe") { extcodecopy(pointer, add(retained, 32), 0, add(size, 1)) }
        if (retained[0] != 0 || keccak256(retained) != keccak256(bytes.concat(hex"00", evidence))) {
            revert V.InvalidInventoryItem();
        }
        return keccak256(abi.encode(id, hash, pointer, pointer.codehash, size, appendedAt));
    }
}

