// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamConservationRecordFields.sol";

/// @notice Exact format declarations and complete supported catalog reconstruction.
/// @dev Actual consumers authenticate registered schema/profile/content. No format detection.
library StreamConservationFormatJson {
    error InvalidConservationFormat();

    function serialize(StreamConservationRecordTypes.Format memory f)
        public
        pure
        returns (string memory)
    {
        if (f.kind == StreamConservationRecordTypes.FormatKind.PRONOM) {
            if (
                bytes(f.catalog.name).length != 0 || f.catalog.entries.length != 0
                    || f.catalog.selectedEntryId != 0
            ) revert InvalidConservationFormat();
            _puid(f.puid);
            if (f.formatId != keccak256(bytes(string.concat("PRONOM:", f.puid)))) {
                revert InvalidConservationFormat();
            }
            return string.concat(
                '{"formatId":',
                StreamRecordJson.hexValue(f.formatId),
                ',"kind":"pronom","puid":',
                StreamRecordJson.quote(f.puid, 32, false),
                "}"
            );
        }
        if (bytes(f.puid).length != 0 || f.formatId != f.catalog.selectedEntryId) {
            revert InvalidConservationFormat();
        }
        bytes memory document = catalogDocument(f.catalog);
        string memory selected;
        for (uint256 i; i < f.catalog.entries.length; ++i) {
            if (f.catalog.entries[i].entryId == f.formatId) {
                selected = _mapping(f.catalog.entries[i]);
            }
        }
        return string.concat(
            '{"catalog":{"documentHash":',
            StreamRecordJson.hexValue(keccak256(document)),
            ',"documentId":',
            StreamRecordJson.hexValue(keccak256(bytes(f.catalog.name))),
            ',"name":',
            StreamRecordJson.quote(f.catalog.name, 128, false),
            '},"formatId":',
            StreamRecordJson.hexValue(f.formatId),
            ',"kind":"catalog","mapping":',
            selected,
            "}"
        );
    }

    /// @notice All entries are checked, ordered and committed, including unselected entries.
    function catalogDocument(StreamConservationRecordTypes.Catalog memory c)
        public
        pure
        returns (bytes memory)
    {
        bytes memory name = bytes(c.name);
        if (
            name.length == 0 || name.length > 128 || c.entries.length == 0 || c.selectedEntryId == 0
        ) {
            revert InvalidConservationFormat();
        }
        for (uint256 i; i < name.length; ++i) {
            bytes1 b = name[i];
            if (!((b >= "A" && b <= "Z") || (b >= "a" && b <= "z") || (b >= "0" && b <= "9")
                        || b == "_" || b == "." || b == "-")) revert InvalidConservationFormat();
        }
        bytes[] memory rows = new bytes[](c.entries.length);
        bytes32[] memory ids = new bytes32[](c.entries.length);
        bool found;
        for (uint256 i; i < c.entries.length; ++i) {
            bytes32 id = c.entries[i].entryId;
            if (id == 0) revert InvalidConservationFormat();
            ids[i] = id;
            if (id == c.selectedEntryId) found = true;
            rows[i] = bytes(
                string.concat(
                    '{"entryId":',
                    StreamRecordJson.hexValue(id),
                    ',"mapping":',
                    _mapping(c.entries[i]),
                    "}"
                )
            );
        }
        if (!found) revert InvalidConservationFormat();
        _unique(ids);
        return StreamConservationRecordFields.requirePayloadSize(
            bytes(
                string.concat(
                    '{"entries":', StreamConservationRecordFields.arrayJSON(rows), ',"version":1}'
                )
            )
        );
    }

    function _mapping(StreamConservationRecordTypes.CatalogEntry memory e)
        private
        pure
        returns (string memory)
    {
        if (e.kind == StreamConservationRecordTypes.MappingKind.PRONOM) {
            StreamConservationRecordFields.requireEmptyReference(e.specification);
            _puid(e.puid);
            return string.concat(
                '{"kind":"pronom","puid":', StreamRecordJson.quote(e.puid, 32, false), "}"
            );
        }
        if (bytes(e.puid).length != 0) revert InvalidConservationFormat();
        return string.concat(
            '{"kind":"specification","specification":',
            StreamConservationRecordFields.referenceJSON(e.specification),
            "}"
        );
    }

    function _puid(string memory value) private pure {
        bytes memory b = bytes(value);
        uint256 first;
        if (b.length >= 5 && b[0] == "f" && b[1] == "m" && b[2] == "t" && b[3] == "/") {
            first = 4;
        } else if (
            b.length >= 7 && b[0] == "x" && b[1] == "-" && b[2] == "f" && b[3] == "m" && b[4] == "t"
                && b[5] == "/"
        ) {
            first = 6;
        } else {
            revert InvalidConservationFormat();
        }
        if (b.length > 32 || b[first] < "1" || b[first] > "9") revert InvalidConservationFormat();
        for (uint256 i = first + 1; i < b.length; ++i) {
            if (b[i] < "0" || b[i] > "9") revert InvalidConservationFormat();
        }
    }

    function _unique(bytes32[] memory a) private pure {
        for (uint256 i = a.length / 2; i != 0;) {
            --i;
            _sift(a, i, a.length);
        }
        for (uint256 end = a.length; end > 1;) {
            --end;
            (a[0], a[end]) = (a[end], a[0]);
            _sift(a, 0, end);
        }
        for (uint256 i = 1; i < a.length; ++i) {
            if (a[i] == a[i - 1]) revert InvalidConservationFormat();
        }
    }

    function _sift(bytes32[] memory a, uint256 root, uint256 n) private pure {
        while (root < n / 2) {
            uint256 child = root * 2 + 1;
            if (child + 1 < n && a[child] < a[child + 1]) ++child;
            if (a[root] >= a[child]) return;
            (a[root], a[child]) = (a[child], a[root]);
            root = child;
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @notice RFC5646 syntax plus case-insensitive variant/singleton uniqueness.
/// @dev This does not prove dated IANA subtag registration or extension-specific semantics.
/// Original tag bytes are never rewritten; lowercase bytes exist only for parsing/comparison.
library StreamConservationLanguage {
    error InvalidConservationLanguage();

    /// @notice Validate ordered tags in one linked call and emit their exact ASCII JSON array.
    /// @dev Accepted tag bytes contain only ALNUM/hyphen, so none need JSON escaping.
    function arrayJSON(string[] memory values) public pure returns (string memory) {
        if (values.length == 0) revert InvalidConservationLanguage();
        uint256 size = 2;
        for (uint256 i; i < values.length; ++i) {
            size += bytes(values[i]).length + 2 + (i == 0 ? 0 : 1);
            if (size > 8192) revert InvalidConservationLanguage();
            requireWellFormed(values[i]);
        }
        bytes memory out = new bytes(size);
        out[0] = "[";
        uint256 at = 1;
        for (uint256 i; i < values.length; ++i) {
            if (i != 0) out[at++] = ",";
            out[at++] = '"';
            bytes memory value = bytes(values[i]);
            for (uint256 j; j < value.length; ++j) {
                out[at++] = value[j];
            }
            out[at++] = '"';
        }
        out[at] = "]";
        return string(out);
    }

    function requireWellFormed(string memory value) public pure {
        (bytes memory b, uint256[] memory parts) = _parts(value);
        // A single2..8ASCII-alpha primary already satisfies the complete original grammar.
        // Grandfathered tags are all multipart; preserve their existing path and exact bytes.
        if (parts.length == 1 && _size(parts[0]) >= 2 && _alpha(b, parts[0])) return;
        if (_grandfathered(keccak256(b))) return;
        uint256 n = parts.length;
        if (_size(parts[0]) == 1 && b[0] == "x") {
            if (n == 1) revert InvalidConservationLanguage();
            return;
        }
        uint256 languageLength = _size(parts[0]);
        if (languageLength < 2 || !_alpha(b, parts[0])) revert InvalidConservationLanguage();
        uint256 i = 1;
        if (languageLength <= 3) {
            uint256 count;
            while (i < n && count < 3 && _size(parts[i]) == 3 && _alpha(b, parts[i])) {
                ++i;
                ++count;
            }
        }
        if (i < n && _size(parts[i]) == 4 && _alpha(b, parts[i])) ++i;
        if (
            i < n
                && ((_size(parts[i]) == 2 && _alpha(b, parts[i]))
                    || (_size(parts[i]) == 3 && _digits(b, parts[i])))
        ) ++i;

        bytes32[] memory variants = new bytes32[](n);
        uint256 variantCount;
        while (i < n && _variant(b, parts[i])) {
            variants[variantCount++] = _hashPart(b, parts[i]);
            ++i;
        }
        _unique(variants, variantCount);

        uint256 singletons;
        while (i < n && _size(parts[i]) == 1 && b[parts[i] >> 8] != "x") {
            uint256 bit = uint256(1) << uint8(b[parts[i] >> 8]);
            if (singletons & bit != 0) revert InvalidConservationLanguage();
            singletons |= bit;
            ++i;
            uint256 start = i;
            while (i < n && _size(parts[i]) >= 2) ++i;
            if (i == start) revert InvalidConservationLanguage();
        }
        if (i < n && _size(parts[i]) == 1 && b[parts[i] >> 8] == "x") {
            ++i;
            if (i == n) revert InvalidConservationLanguage();
            // Every remaining part already satisfies private-use's1..8ALNUM production.
            i = n;
        }
        if (i != n) revert InvalidConservationLanguage();
    }

    function _parts(string memory value)
        private
        pure
        returns (bytes memory b, uint256[] memory parts)
    {
        bytes memory original = bytes(value);
        uint256 length = original.length;
        if (length == 0 || length > 8192 || original[0] == "-" || original[length - 1] == "-") {
            revert InvalidConservationLanguage();
        }
        b = new bytes(length);
        uint256 count = 1;
        for (uint256 i; i < length; ++i) {
            uint8 c = uint8(original[i]);
            if (c >= 65 && c <= 90) c += 32;
            if (c == 45) {
                if (i != 0 && original[i - 1] == "-") revert InvalidConservationLanguage();
                ++count;
            } else if (!((c >= 97 && c <= 122) || (c >= 48 && c <= 57))) {
                revert InvalidConservationLanguage();
            }
            b[i] = bytes1(c);
        }
        parts = new uint256[](count);
        uint256 start;
        uint256 index;
        for (uint256 i; i <= length; ++i) {
            if (i == length || b[i] == "-") {
                uint256 size = i - start;
                if (size == 0 || size > 8) revert InvalidConservationLanguage();
                parts[index++] = start << 8 | size;
                start = i + 1;
            }
        }
    }

    function _size(uint256 part) private pure returns (uint256) {
        return part & 255;
    }

    function _alpha(bytes memory b, uint256 part) private pure returns (bool) {
        uint256 start = part >> 8;
        uint256 end = start + _size(part);
        for (uint256 i = start; i < end; ++i) {
            if (b[i] < "a" || b[i] > "z") return false;
        }
        return true;
    }

    function _digits(bytes memory b, uint256 part) private pure returns (bool) {
        uint256 start = part >> 8;
        uint256 end = start + _size(part);
        for (uint256 i = start; i < end; ++i) {
            if (b[i] < "0" || b[i] > "9") return false;
        }
        return true;
    }

    function _variant(bytes memory b, uint256 part) private pure returns (bool) {
        uint256 size = _size(part);
        return size >= 5 || (size == 4 && b[part >> 8] >= "0" && b[part >> 8] <= "9");
    }

    function _hashPart(bytes memory b, uint256 part) private pure returns (bytes32) {
        bytes memory out = new bytes(_size(part));
        for (uint256 i; i < out.length; ++i) {
            out[i] = b[(part >> 8) + i];
        }
        return keccak256(out);
    }

    function _unique(bytes32[] memory hashes, uint256 n) private pure {
        for (uint256 i = n / 2; i != 0;) {
            --i;
            _sift(hashes, i, n);
        }
        for (uint256 end = n; end > 1;) {
            --end;
            (hashes[0], hashes[end]) = (hashes[end], hashes[0]);
            _sift(hashes, 0, end);
        }
        for (uint256 i = 1; i < n; ++i) {
            if (hashes[i - 1] == hashes[i]) revert InvalidConservationLanguage();
        }
    }

    function _sift(bytes32[] memory hashes, uint256 root, uint256 n) private pure {
        while (root < n / 2) {
            uint256 child = root * 2 + 1;
            if (child + 1 < n && hashes[child] < hashes[child + 1]) ++child;
            if (hashes[root] >= hashes[child]) return;
            (hashes[root], hashes[child]) = (hashes[child], hashes[root]);
            root = child;
        }
    }

    /// @dev The complete permanent26-tag regular/irregular set in RFC5646 section2.1.
    function _grandfathered(bytes32 h) private pure returns (bool) {
        return h == keccak256("en-gb-oed") || h == keccak256("i-ami") || h == keccak256("i-bnn")
            || h == keccak256("i-default") || h == keccak256("i-enochian")
            || h == keccak256("i-hak") || h == keccak256("i-klingon") || h == keccak256("i-lux")
            || h == keccak256("i-mingo") || h == keccak256("i-navajo") || h == keccak256("i-pwn")
            || h == keccak256("i-tao") || h == keccak256("i-tay") || h == keccak256("i-tsu")
            || h == keccak256("sgn-be-fr") || h == keccak256("sgn-be-nl")
            || h == keccak256("sgn-ch-de") || h == keccak256("art-lojban")
            || h == keccak256("cel-gaulish") || h == keccak256("no-bok") || h == keccak256("no-nyn")
            || h == keccak256("zh-guoyu") || h == keccak256("zh-hakka") || h == keccak256("zh-min")
            || h == keccak256("zh-min-nan") || h == keccak256("zh-xiang");
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamConservationRecordContext.sol";
import "./StreamCollectionRecordHashes.sol";
import "./StreamRecordFamilies.sol";
import "./StreamRecordArtistIdentityReads.sol";
import "../../interfaces/stream/metadata/IStreamConservationRecordSelection.sol";
import "../../interfaces/stream/metadata/IStreamCollectionMetadataV1.sol";
import "../../interfaces/stream/metadata/IStreamCollectionRecordReceipts.sol";
import "../../interfaces/stream/metadata/IStreamSchemaRegistry.sol";
import "../../interfaces/stream/parameters/IStreamGasParameterHost.sol";
import "../../interfaces/stream/artist/IStreamArtistBindingOwner.sol";
import "../../interfaces/stream/artist/IStreamArtistAttributionOwner.sol";
import "../../interfaces/stream/artist/IStreamArtistRecordPublicationOwner.sol";
import "../metadata/StreamSchemaDocumentStore.sol";

/// @notice Complete original conservation receipt, lane and historical op24 publication joins.
/// @dev No current signer is substituted for the stored original author/class. The fixed consumer
/// supplies its immutable dependency graph; all caller record fields remain untrusted witnesses.
library StreamConservationPublicationReads {
    bytes32 internal constant INTENT_TYPE = keccak256("ARTIST_INTENT");
    bytes32 internal constant WAIVER_TYPE = keccak256("ARTIST_INTENT_WAIVER");
    bytes32 internal constant INTERVIEW_TYPE = keccak256("ARTIST_STATEMENT");
    bytes32 private constant PUBLICATION_SCHEMA =
        keccak256("6529STREAM_ARTIST_RECORD_PUBLICATION_V1");

    function recorded(
        StreamConservationRecordContext.Dependencies memory d,
        uint256 collectionId,
        bytes32 subjectId,
        bytes32 recordHash,
        IStreamPreservationRecords.CollectionRecord memory record,
        IStreamConservationRecordSelection.RecordKind kind
    ) public view returns (IStreamConservationRecordSelection.RecordEvidence memory e) {
        (bytes32 recordType, bytes32 schemaId, bytes32 schemaHash) = definition(kind);
        IStreamCollectionMetadataV1.RecordReceipt memory receipt = _receipt(d, recordHash);
        IStreamCollectionMetadataV1.RecordPolicy memory policy = _policy(d, recordType);
        if (
            collectionId == 0 || subjectId == 0 || recordHash == 0
                || receipt.collectionId != collectionId || receipt.recorder == address(0)
                || receipt.authorizationClass != 1
                || (policy.authorizationMask & StreamRecordFamilies.bit(1)) == 0
                || receipt.recordedAt == 0 || receipt.schemaDefinitionHash != schemaHash
                || receipt.canonicalizationDefinitionHash != StreamWorkRecordDefinitions.CANON_HASH
                || record.recordType != recordType || record.subjectId != subjectId
                || record.schemaId != schemaId || record.contentHash.algorithm != 1
                || record.contentHash.digest.length != 32
                || record.contentHash.canonicalizationId != StreamWorkRecordDefinitions.CANON_ID
                || record.signatureScheme != 0 || record.signatureHash.algorithm != 0
                || record.signatureHash.digest.length != 0
                || record.signatureHash.canonicalizationId != 0 || record.effectiveAt == 0
                || _recordHash(d, collectionId, receipt.recorder, record) != recordHash
        ) revert IStreamConservationRecordSelection.InvalidConservationRecord(recordHash);
        _history(d, recordHash, receipt, recordType);
        e.recordHash = recordHash;
        e.kind = kind;
        e.payloadHash = bytes32(record.contentHash.digest);
        e.recorder = receipt.recorder;
        e.recordedAt = receipt.recordedAt;
        e.recordIndex = receipt.recordIndex;
        e.recordChainHash = receipt.recordChainHash;
        e.receiptHash = keccak256(abi.encode(receipt));
        (e.publication, e.publicationEvidenceHash) =
            _artistPublication(d, receipt, record, recordHash);
    }

    function definition(IStreamConservationRecordSelection.RecordKind kind)
        public
        pure
        returns (bytes32 recordType, bytes32 schemaId, bytes32 schemaHash)
    {
        if (kind == IStreamConservationRecordSelection.RecordKind.INTENT) {
            return (
                INTENT_TYPE,
                StreamConservationDefinitions.INTENT_SCHEMA_ID,
                StreamConservationDefinitions.INTENT_SCHEMA_HASH
            );
        }
        if (kind == IStreamConservationRecordSelection.RecordKind.INTENT_WAIVER) {
            return (
                WAIVER_TYPE,
                StreamConservationDefinitions.WAIVER_SCHEMA_ID,
                StreamConservationDefinitions.WAIVER_SCHEMA_HASH
            );
        }
        return (
            INTERVIEW_TYPE,
            StreamConservationDefinitions.INTERVIEW_SCHEMA_ID,
            StreamConservationDefinitions.INTERVIEW_SCHEMA_HASH
        );
    }

    function _artistPublication(
        StreamConservationRecordContext.Dependencies memory d,
        IStreamCollectionMetadataV1.RecordReceipt memory receipt,
        IStreamPreservationRecords.CollectionRecord memory record,
        bytes32 recordHash
    ) private view returns (P.Evidence memory evidence, bytes32 evidenceHash) {
        if (receipt.artistAuthorization == 0) {
            revert IStreamConservationRecordSelection.InvalidConservationRecord(recordHash);
        }
        bytes memory raw = _fixed(
            d,
            d.targets[1],
            abi.encodeWithSignature(
                "consumedArtistAuthorization(bytes32)", receipt.artistAuthorization
            ),
            32
        );
        if (_word(raw, 0) != bytes32(uint256(1))) {
            revert IStreamConservationRecordSelection.InvalidConservationRecord(recordHash);
        }
        raw = _fixed(
            d,
            d.artists[4],
            abi.encodeCall(
                IStreamArtistRecordPublicationOwner.publicationAttestation,
                (receipt.artistAuthorization)
            ),
            704
        );
        IStreamArtistRecordPublicationOwner.Record memory saved =
            abi.decode(raw, (IStreamArtistRecordPublicationOwner.Record));
        _canonical(d.artists[4], raw, abi.encode(saved));
        evidence = saved.evidence;
        P.Publication memory p = P.Publication(
            d.targets[1],
            receipt.recorder,
            receipt.collectionId,
            record.subjectId,
            record.recordType,
            record.schemaId,
            record.contentHash.canonicalizationId,
            1,
            bytes32(record.contentHash.digest),
            keccak256(bytes(record.uri)),
            record.effectiveAt,
            recordHash
        );
        if (
            saved.metadataHostCodeHash != d.codeHashes[1]
                || keccak256(abi.encode(saved.publication)) != keccak256(abi.encode(p))
                || evidence.attestationRecordHash != receipt.artistAuthorization
                || evidence.artistId == 0 || evidence.bindingHash == 0
                || evidence.bindingGeneration == 0 || evidence.signer != receipt.recorder
                || (evidence.authorityClass != 1 && evidence.authorityClass != 3)
                || evidence.requiredCapability != (record.recordType == INTERVIEW_TYPE ? 1 : 64)
                || evidence.signedAt == 0 || evidence.signedAt > receipt.recordedAt
                || evidence.publicationHash != keccak256(abi.encode(p))
        ) revert IStreamConservationRecordSelection.InvalidConservationRecord(recordHash);
        _attestation(d, evidence, p, recordHash);
        return (evidence, keccak256(abi.encode(saved)));
    }

    function _attestation(
        StreamConservationRecordContext.Dependencies memory d,
        P.Evidence memory evidence,
        P.Publication memory p,
        bytes32 recordHash
    ) private view {
        bytes memory raw = _fixed(
            d,
            d.artists[4],
            abi.encodeCall(
                IStreamArtistAttributionOwner.attestationRecord, (evidence.attestationRecordHash)
            ),
            224
        );
        T.AttestationRecord memory record = abi.decode(raw, (T.AttestationRecord));
        _canonical(d.artists[4], raw, abi.encode(record));
        bytes memory statement = abi.encode(uint16(1), p);
        if (
            record.recordHash != evidence.attestationRecordHash
                || record.subjectStateHash
                    != (p.recordType == INTERVIEW_TYPE ? bytes32(0) : recordHash)
                || record.schemaId != PUBLICATION_SCHEMA
                || record.statementHash != keccak256(statement)
                || record.generation != evidence.bindingGeneration
                || record.signedAt != evidence.signedAt || record.signer != evidence.signer
        ) revert IStreamConservationRecordSelection.InvalidConservationRecord(recordHash);
        raw = _read(
            d,
            d.artists[4],
            abi.encodeCall(IStreamArtistAttributionOwner.statementBytes, (record.statementHash)),
            480
        );
        bytes memory saved = abi.decode(raw, (bytes));
        _canonical(d.artists[4], raw, abi.encode(saved));
        if (saved.length != 416 || keccak256(saved) != keccak256(statement)) {
            revert IStreamConservationRecordSelection.InvalidConservationRecord(recordHash);
        }
    }

    function _policy(StreamConservationRecordContext.Dependencies memory d, bytes32 recordType)
        private
        view
        returns (IStreamCollectionMetadataV1.RecordPolicy memory policy)
    {
        bytes memory raw = _fixed(
            d,
            d.targets[1],
            abi.encodeCall(IStreamCollectionMetadataV1.recordPolicy, (recordType)),
            96
        );
        policy = abi.decode(raw, (IStreamCollectionMetadataV1.RecordPolicy));
        _canonical(d.targets[1], raw, abi.encode(policy));
        if (!policy.admitted || policy.family != StreamRecordFamilies.ARTIST) {
            revert IStreamConservationRecordSelection.ConservationSelectionAuthorityRequired();
        }
    }

    function _receipt(StreamConservationRecordContext.Dependencies memory d, bytes32 hash)
        private
        view
        returns (IStreamCollectionMetadataV1.RecordReceipt memory receipt)
    {
        bytes memory raw = _fixed(
            d,
            d.targets[1],
            abi.encodeCall(IStreamCollectionRecordReceipts.collectionRecordReceipt, (hash)),
            288
        );
        receipt = abi.decode(raw, (IStreamCollectionMetadataV1.RecordReceipt));
        _canonical(d.targets[1], raw, abi.encode(receipt));
    }

    function _history(
        StreamConservationRecordContext.Dependencies memory d,
        bytes32 recordHash,
        IStreamCollectionMetadataV1.RecordReceipt memory receipt,
        bytes32 recordType
    ) private view {
        bytes memory raw = _fixed(
            d,
            d.targets[1],
            abi.encodeCall(
                IStreamCollectionMetadataV1.recordHashAt,
                (receipt.collectionId, recordType, receipt.recordIndex)
            ),
            32
        );
        if (_word(raw, 0) != recordHash) {
            revert IStreamConservationRecordSelection.InvalidConservationRecord(recordHash);
        }
        bytes32 previous;
        if (receipt.recordIndex != 0) {
            raw = _fixed(
                d,
                d.targets[1],
                abi.encodeCall(
                    IStreamCollectionMetadataV1.recordHashAt,
                    (receipt.collectionId, recordType, receipt.recordIndex - 1)
                ),
                32
            );
            IStreamCollectionMetadataV1.RecordReceipt memory prior = _receipt(d, _word(raw, 0));
            if (
                prior.collectionId != receipt.collectionId
                    || prior.recordIndex + 1 != receipt.recordIndex
            ) revert IStreamConservationRecordSelection.InvalidConservationRecord(recordHash);
            previous = prior.recordChainHash;
        }
        bytes32 expected = keccak256(
            abi.encode(
                StreamCollectionRecordHashes.CHAIN_DOMAIN,
                d.chainId,
                d.targets[1],
                receipt.collectionId,
                recordType,
                previous,
                recordHash,
                receipt.recordIndex
            )
        );
        if (receipt.recordChainHash != expected) {
            revert IStreamConservationRecordSelection.InvalidConservationRecord(recordHash);
        }
    }

    function payload(
        StreamConservationRecordContext.Dependencies memory d,
        bytes32 recordHash,
        bytes32 payloadHash
    ) public view returns (bytes memory original) {
        bytes memory raw = _fixed(
            d, d.targets[3], abi.encodeWithSignature("chunk(bytes32)", payloadHash), 64
        );
        (address ptr, uint32 size) = abi.decode(raw, (address, uint32));
        _canonical(d.targets[3], raw, abi.encode(ptr, size));
        original = _chunk(d, payloadHash);
        if (
            ptr == address(0) || original.length != size || original.length == 0
                || keccak256(original) != payloadHash
        ) revert IStreamConservationRecordSelection.InvalidConservationRecord(recordHash);
    }

    function _recordHash(
        StreamConservationRecordContext.Dependencies memory d,
        uint256 collectionId,
        address recorder,
        IStreamPreservationRecords.CollectionRecord memory record
    ) private pure returns (bytes32) {
        StreamCollectionRecordHashes.Preimage memory p;
        p.domain = keccak256("6529stream.preservation-record.v2");
        p.chainId = d.chainId;
        p.host = d.targets[1];
        p.core = d.targets[0];
        p.recorder = recorder;
        p.collectionId = collectionId;
        p.recordType = record.recordType;
        p.subjectId = record.subjectId;
        p.contentHash = StreamCollectionRecordHashes.hashRef(
            record.contentHash.algorithm,
            record.contentHash.digest,
            record.contentHash.canonicalizationId
        );
        p.uriHash = keccak256(bytes(record.uri));
        p.schemaId = record.schemaId;
        p.signatureScheme = record.signatureScheme;
        p.signatureHash = StreamCollectionRecordHashes.hashRef(
            record.signatureHash.algorithm,
            record.signatureHash.digest,
            record.signatureHash.canonicalizationId
        );
        p.effectiveAt = record.effectiveAt;
        return keccak256(abi.encode(p));
    }

    function _chunk(StreamConservationRecordContext.Dependencies memory d, bytes32 hash)
        private
        view
        returns (bytes memory chunk)
    {
        bytes memory raw = _read(
            d, d.targets[3], abi.encodeCall(StreamSchemaDocumentStore.readChunk, (hash)), 8256
        );
        chunk = abi.decode(raw, (bytes));
        _canonical(d.targets[3], raw, abi.encode(chunk));
        if (keccak256(chunk) != hash) {
            revert IStreamConservationRecordSelection.ConservationDependencyReadFailed(d.targets[3]);
        }
    }

    function _word(bytes memory raw, uint256 index) private pure returns (bytes32 word) {
        assembly ("memory-safe") { word := mload(add(add(raw, 32), mul(index, 32))) }
    }

    function _canonical(address target, bytes memory raw, bytes memory encoded) private pure {
        if (raw.length != encoded.length || keccak256(raw) != keccak256(encoded)) {
            revert IStreamConservationRecordSelection.ConservationDependencyReadFailed(target);
        }
    }

    function _fixed(
        StreamConservationRecordContext.Dependencies memory d,
        address target,
        bytes memory input,
        uint256 size
    ) private view returns (bytes memory raw) {
        raw = _read(d, target, input, size);
        if (raw.length != size) {
            revert IStreamConservationRecordSelection.ConservationDependencyReadFailed(target);
        }
    }

    function _read(
        StreamConservationRecordContext.Dependencies memory d,
        address target,
        bytes memory input,
        uint256 maximum
    ) private view returns (bytes memory raw) {
        uint256 cap = d.readGas;
        raw = new bytes(maximum);
        if (cap == 0 || cap > type(uint64).max || gasleft() <= cap + cap / 63 + 10000) {
            revert IStreamConservationRecordSelection.ConservationDependencyReadFailed(target);
        }
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(input, 32), mload(input), add(raw, 32), maximum)
            size := returndatasize()
        }
        if (!ok || size > maximum) {
            revert IStreamConservationRecordSelection.ConservationDependencyReadFailed(target);
        }
        assembly ("memory-safe") { mstore(raw, size) }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamConservationDefinitions.sol";
import "./StreamWorkRecordDefinitions.sol";
import "./StreamCollectionRecordHashes.sol";
import "./StreamRecordFamilies.sol";
import "./StreamRecordArtistIdentityReads.sol";
import "../../interfaces/stream/metadata/IStreamConservationRecordSelection.sol";
import "../../interfaces/stream/metadata/IStreamCollectionMetadataV1.sol";
import "../../interfaces/stream/metadata/IStreamSchemaRegistry.sol";
import "../../interfaces/stream/metadata/IStreamSchemaDocumentFacts.sol";
import "../../interfaces/stream/metadata/IStreamCollectionRecordReceipts.sol";
import "../../interfaces/stream/parameters/IStreamGasParameterHost.sol";
import "../../interfaces/stream/artist/IStreamArtistBindingOwner.sol";
import "../../interfaces/stream/artist/IStreamArtistAttributionOwner.sol";
import "../../interfaces/stream/artist/IStreamArtistRecordPublicationOwner.sol";
import "../metadata/StreamSchemaDocumentStore.sol";

/// @notice Fixed conservation dependency graph and complete registered interpretation bytes.
/// @dev Stateless bounded reads; constructor selection and current use are separate caller decisions.
library StreamConservationRecordContext {
    bytes32 private constant RAW_BYTES = keccak256("RAW_BYTES");
    bytes32 private constant READ_GAS = keccak256("6529STREAM_GGP_METADATA_DEPENDENCY_READ_GAS");

    struct Dependencies {
        // Core, metadata host, schema registry, byte store.
        address[4] targets;
        bytes32[4] codeHashes;
        // Facade, Coordinator, Identity, Binding, Attribution owners.
        address[5] artists;
        bytes32[5] artistCodeHashes;
        uint256 chainId;
        uint256 readGas;
    }

    function currentContext(Dependencies memory d) public view returns (Dependencies memory) {
        if (block.chainid != d.chainId) {
            revert IStreamConservationRecordSelection.ConservationDependencyChanged(d.targets[0]);
        }
        for (uint256 i; i < 4; ++i) {
            _code(d.targets[i], d.codeHashes[i]);
        }
        // The immutable pinned host's getter has no external calls.
        d.readGas = IStreamGasParameterHost(d.targets[1]).gasParameter(READ_GAS);
        if (d.readGas == 0 || d.readGas > type(uint64).max) {
            revert IStreamConservationRecordSelection.InvalidConservationConfiguration();
        }
        if (
            _word(
                        _fixed(
                            d,
                            d.targets[1],
                            abi.encodeCall(
                                IERC165.supportsInterface,
                                (type(IStreamCollectionRecordReceipts).interfaceId)
                            ),
                            32
                        ),
                        0
                    ) != bytes32(uint256(1))
                || _word(
                        _fixed(
                            d,
                            d.targets[2],
                            abi.encodeCall(
                                IERC165.supportsInterface,
                                (type(IStreamSchemaDocumentFacts).interfaceId)
                            ),
                            32
                        ),
                        0
                    ) != bytes32(uint256(1))
        ) revert IStreamConservationRecordSelection.InvalidConservationConfiguration();
        if (
            _hash(d, d.targets[1], "coreCodeHash()") != d.codeHashes[0]
                || _hash(d, d.targets[1], "schemaRegistryCodeHash()") != d.codeHashes[2]
                || _hash(d, d.targets[1], "chunkStoreCodeHash()") != d.codeHashes[3]
                || _address(d, d.targets[1], "core()") != d.targets[0]
                || _address(d, d.targets[1], "schemaRegistry()") != d.targets[2]
                || _address(d, d.targets[1], "chunkStore()") != d.targets[3]
                || _address(d, d.targets[2], "chunkStore()") != d.targets[3]
        ) revert IStreamConservationRecordSelection.InvalidConservationConfiguration();
        _selected(d, keccak256("COLLECTION_METADATA"), d.targets[1], d.codeHashes[1]);
        if (d.artists[0] != address(0)) {
            for (uint256 i; i < 5; ++i) {
                _code(d.artists[i], d.artistCodeHashes[i]);
            }
            bytes32 expectedArtists = keccak256(abi.encode(d.artists, d.artistCodeHashes));
            Dependencies memory fresh = pinArtists(d);
            if (keccak256(abi.encode(fresh.artists, fresh.artistCodeHashes)) != expectedArtists) {
                revert IStreamConservationRecordSelection.ConservationAssociationChanged();
            }
        }
        return d;
    }

    function pinArtists(Dependencies memory d) public view returns (Dependencies memory) {
        StreamRecordArtistIdentityReads.Pins memory known = StreamRecordArtistIdentityReads.resolveCurrent(
            d.targets[1], d.targets[0], d.chainId, d.readGas
        );
        for (uint256 i; i < 3; ++i) {
            d.artists[i] = known.targets[i];
            d.artistCodeHashes[i] = known.codeHashes[i];
        }
        bytes memory suite =
            _fixed(d, d.artists[1], abi.encodeWithSignature("suiteConfiguration()"), 544);
        for (uint256 i; i < 17; ++i) {
            if (i != 15 && uint256(_word(suite, i)) > type(uint160).max) {
                revert IStreamConservationRecordSelection.ConservationDependencyReadFailed(d.artists[
                        1
                    ]);
            }
        }
        if (
            _word(suite, 0) != bytes32(uint256(uint160(d.artists[0])))
                || _word(suite, 9) != bytes32(uint256(uint160(d.targets[0])))
        ) revert IStreamConservationRecordSelection.InvalidConservationConfiguration();
        d.artists[3] = address(uint160(uint256(_word(suite, 2))));
        d.artists[4] = address(uint160(uint256(_word(suite, 6))));
        for (uint256 i = 3; i < 5; ++i) {
            if (d.artists[i].code.length == 0) {
                revert IStreamConservationRecordSelection.ConservationDependencyChanged(d.artists[
                        i
                    ]);
            }
            d.artistCodeHashes[i] = d.artists[i].codehash;
            if (
                _address(d, d.artists[i], "core()") != d.targets[0]
                    || _address(d, d.artists[i], "artistRegistry()") != d.artists[0]
                    || _address(d, d.artists[i], "operationCoordinator()") != d.artists[1]
                    || _hash(d, d.artists[i], "deploymentChainId()") != bytes32(d.chainId)
            ) revert IStreamConservationRecordSelection.InvalidConservationConfiguration();
        }
        _selected(d, keccak256("ARTIST_REGISTRY"), d.artists[0], d.artistCodeHashes[0]);
        return d;
    }

    function association(
        StreamConservationRecordContext.Dependencies memory d,
        uint256 collectionId
    ) public view returns (IStreamConservationRecordSelection.Association memory a) {
        bytes memory raw = _fixed(
            d, d.artists[3], abi.encodeCall(IStreamArtistBindingOwner.binding, (collectionId)), 320
        );
        T.Binding memory b = abi.decode(raw, (T.Binding));
        _canonical(d.artists[3], raw, abi.encode(b));
        if (b.artistId == 0) {
            T.Binding memory empty;
            if (keccak256(raw) != keccak256(abi.encode(empty))) {
                revert IStreamConservationRecordSelection.ConservationAssociationChanged();
            }
            return a;
        }
        raw = _fixed(
            d,
            d.artists[4],
            abi.encodeCall(IStreamArtistAttributionOwner.attributionState, (collectionId)),
            64
        );
        (uint8 status, uint64 generation) = abi.decode(raw, (uint8, uint64));
        _canonical(d.artists[4], raw, abi.encode(status, generation));
        if (
            !b.accepted || (status != 2 && status != 3) || b.bindingHash == 0 || b.generation == 0
                || b.generation != generation || b.identityRecordHash == 0
                || b.artistAddress == address(0)
        ) revert IStreamConservationRecordSelection.ConservationAssociationChanged();
        StreamRecordArtistIdentityReads.Pins memory pins;
        for (uint256 i; i < 3; ++i) {
            pins.targets[i] = d.artists[i];
            pins.codeHashes[i] = d.artistCodeHashes[i];
        }
        bytes32 identity = StreamRecordArtistIdentityReads.knownCurrentIdentity(
            d.targets[1], d.targets[0], d.chainId, pins, b.artistId, d.readGas
        );
        if (identity != b.identityRecordHash) {
            revert IStreamConservationRecordSelection.ConservationAssociationChanged();
        }
        return IStreamConservationRecordSelection.Association(
            b.artistId, b.bindingHash, b.generation, identity
        );
    }

    /// @notice Fresh direct principal authorization only for the explicit one-way local lock.
    /// @dev Historical record materialization never calls this current-authority predicate.
    function requireLocker(
        Dependencies memory d,
        bytes32 artistId,
        bytes32 identityRecordHash,
        address caller
    ) public view {
        bytes memory raw = _fixed(
            d,
            d.artists[2],
            abi.encodeCall(IStreamArtistIdentityOwner.authorityState, (artistId)),
            128
        );
        (address authority, uint8 authorityClass, uint8 status, bytes32 identity) =
            abi.decode(raw, (address, uint8, uint8, bytes32));
        _canonical(d.artists[2], raw, abi.encode(authority, authorityClass, status, identity));
        if (
            authority == address(0) || authority != caller || authorityClass != 1 || status != 1
                || identity != identityRecordHash || identity == 0
        ) {
            revert IStreamConservationRecordSelection.ConservationSelectionAuthorityRequired();
        }
    }

    function definitions(Dependencies memory d) public view {
        definition(
            d,
            StreamConservationDefinitions.INTENT_SCHEMA_ID,
            IStreamSchemaRegistry.DocumentKind.SCHEMA,
            StreamConservationDefinitions.INTENT_SCHEMA_HASH,
            StreamConservationDefinitions.INTENT_SCHEMA_BYTES,
            RAW_BYTES,
            true
        );
        definition(
            d,
            StreamConservationDefinitions.INTENT_PROFILE_ID,
            IStreamSchemaRegistry.DocumentKind.CATALOG,
            StreamConservationDefinitions.INTENT_PROFILE_HASH,
            StreamConservationDefinitions.INTENT_PROFILE_BYTES,
            RAW_BYTES,
            true
        );
        definition(
            d,
            StreamConservationDefinitions.WAIVER_SCHEMA_ID,
            IStreamSchemaRegistry.DocumentKind.SCHEMA,
            StreamConservationDefinitions.WAIVER_SCHEMA_HASH,
            StreamConservationDefinitions.WAIVER_SCHEMA_BYTES,
            RAW_BYTES,
            true
        );
        definition(
            d,
            StreamConservationDefinitions.WAIVER_PROFILE_ID,
            IStreamSchemaRegistry.DocumentKind.CATALOG,
            StreamConservationDefinitions.WAIVER_PROFILE_HASH,
            StreamConservationDefinitions.WAIVER_PROFILE_BYTES,
            RAW_BYTES,
            true
        );
        interviewDefinitions(d);
    }

    function interviewDefinitions(Dependencies memory d) public view {
        definition(
            d,
            StreamConservationDefinitions.INTERVIEW_SCHEMA_ID,
            IStreamSchemaRegistry.DocumentKind.SCHEMA,
            StreamConservationDefinitions.INTERVIEW_SCHEMA_HASH,
            StreamConservationDefinitions.INTERVIEW_SCHEMA_BYTES,
            RAW_BYTES,
            true
        );
        definition(
            d,
            StreamConservationDefinitions.INTERVIEW_PROFILE_ID,
            IStreamSchemaRegistry.DocumentKind.CATALOG,
            StreamConservationDefinitions.INTERVIEW_PROFILE_HASH,
            StreamConservationDefinitions.INTERVIEW_PROFILE_BYTES,
            RAW_BYTES,
            true
        );
        definition(
            d,
            StreamConservationDefinitions.CATALOG_SCHEMA_ID,
            IStreamSchemaRegistry.DocumentKind.SCHEMA,
            StreamConservationDefinitions.CATALOG_SCHEMA_HASH,
            StreamConservationDefinitions.CATALOG_SCHEMA_BYTES,
            RAW_BYTES,
            true
        );
        definition(
            d,
            StreamConservationDefinitions.CATALOG_PROFILE_ID,
            IStreamSchemaRegistry.DocumentKind.CATALOG,
            StreamConservationDefinitions.CATALOG_PROFILE_HASH,
            StreamConservationDefinitions.CATALOG_PROFILE_BYTES,
            RAW_BYTES,
            true
        );
        definition(
            d,
            StreamWorkRecordDefinitions.CANON_ID,
            IStreamSchemaRegistry.DocumentKind.CANONICALIZATION,
            StreamWorkRecordDefinitions.CANON_HASH,
            StreamWorkRecordDefinitions.CANON_BYTES,
            RAW_BYTES,
            true
        );
    }

    function document(Dependencies memory d, bytes32 id)
        public
        view
        returns (IStreamSchemaDocumentFacts.DocumentFacts memory row)
    {
        bytes memory raw = _fixed(
            d, d.targets[2], abi.encodeCall(IStreamSchemaDocumentFacts.documentFacts, (id)), 288
        );
        row = abi.decode(raw, (IStreamSchemaDocumentFacts.DocumentFacts));
        _canonical(d.targets[2], raw, abi.encode(row));
    }

    function definition(
        Dependencies memory d,
        bytes32 id,
        IStreamSchemaRegistry.DocumentKind kind,
        bytes32 hash,
        uint256 length,
        bytes32 canon,
        bool firstVersion
    ) public view returns (bytes memory payload) {
        IStreamSchemaDocumentFacts.DocumentFacts memory row = document(d, id);
        // The pinned Registry derives each immutable ID from its exact registered name.
        // URI is registration metadata; do not claim to re-create its declaration preimage.
        if (
            !row.exists || row.status != IStreamSchemaRegistry.DocumentStatus.ACTIVE
                || row.kind != kind || row.canonicalizationId != canon
                || (firstVersion && row.supersedesId != 0) || row.totalBytes != length
                || row.contentHash != hash || row.declarationHash == 0 || row.chunkCount == 0
                || row.chunkCount > 64 || length > 524288
        ) revert IStreamConservationRecordSelection.ConservationDefinitionUnavailable(id);
        for (uint256 i; i < row.chunkCount; ++i) {
            bytes32 chunkHash = _word(
                _fixed(
                    d,
                    d.targets[2],
                    abi.encodeCall(IStreamSchemaDocumentFacts.documentChunkHashAt, (id, i)),
                    32
                ),
                0
            );
            bytes memory chunk = _chunk(d, chunkHash);
            if (
                chunk.length == 0 || chunk.length > 8192
                    || (i + 1 < row.chunkCount && chunk.length != 8192)
                    || payload.length + chunk.length > length
            ) revert IStreamConservationRecordSelection.ConservationDefinitionUnavailable(id);
            payload = bytes.concat(payload, chunk);
        }
        if (payload.length != length || keccak256(payload) != hash) {
            revert IStreamConservationRecordSelection.ConservationDefinitionUnavailable(id);
        }
    }

    function _selected(Dependencies memory d, bytes32 kind, address target, bytes32 codeHash)
        private
        view
    {
        bytes memory raw = _fixed(
            d, d.targets[0], abi.encodeWithSignature("getSatellitePointer(bytes32)", kind), 320
        );
        if (
            uint256(_word(raw, 0)) > type(uint160).max || uint256(_word(raw, 2)) > 1
                || uint256(_word(raw, 4)) & type(uint224).max != 0
                || uint256(_word(raw, 5)) > type(uint160).max
                || uint256(_word(raw, 6)) > type(uint8).max
                || uint256(_word(raw, 9)) > type(uint64).max
        ) revert IStreamConservationRecordSelection.ConservationDependencyReadFailed(d.targets[0]);
        if (
            _word(raw, 0) != bytes32(uint256(uint160(target))) || _word(raw, 1) != codeHash
                || _word(raw, 3) != kind || _word(raw, 6) != bytes32(uint256(1))
        ) revert IStreamConservationRecordSelection.ConservationHostNotSelected();
    }

    function _code(address target, bytes32 hash) private view {
        if (target.code.length == 0 || target.codehash != hash) {
            revert IStreamConservationRecordSelection.ConservationDependencyChanged(target);
        }
    }

    function _address(Dependencies memory d, address target, string memory signature)
        private
        view
        returns (address)
    {
        uint256 word = uint256(_hash(d, target, signature));
        if (word > type(uint160).max) {
            revert IStreamConservationRecordSelection.ConservationDependencyReadFailed(target);
        }
        return address(uint160(word));
    }

    function _hash(Dependencies memory d, address target, string memory signature)
        private
        view
        returns (bytes32)
    {
        return _word(_fixed(d, target, abi.encodeWithSignature(signature), 32), 0);
    }

    function _chunk(Dependencies memory d, bytes32 hash) private view returns (bytes memory chunk) {
        bytes memory raw = _read(
            d, d.targets[3], abi.encodeCall(StreamSchemaDocumentStore.readChunk, (hash)), 8256
        );
        chunk = abi.decode(raw, (bytes));
        _canonical(d.targets[3], raw, abi.encode(chunk));
        if (keccak256(chunk) != hash) {
            revert IStreamConservationRecordSelection.ConservationDependencyReadFailed(d.targets[3]);
        }
    }

    function _word(bytes memory raw, uint256 index) private pure returns (bytes32 word) {
        assembly ("memory-safe") { word := mload(add(add(raw, 32), mul(index, 32))) }
    }

    function _canonical(address target, bytes memory raw, bytes memory encoded) private pure {
        if (raw.length != encoded.length || keccak256(raw) != keccak256(encoded)) {
            revert IStreamConservationRecordSelection.ConservationDependencyReadFailed(target);
        }
    }

    function _fixed(Dependencies memory d, address target, bytes memory input, uint256 size)
        private
        view
        returns (bytes memory raw)
    {
        raw = _read(d, target, input, size);
        if (raw.length != size) {
            revert IStreamConservationRecordSelection.ConservationDependencyReadFailed(target);
        }
    }

    function _read(Dependencies memory d, address target, bytes memory input, uint256 maximum)
        private
        view
        returns (bytes memory raw)
    {
        uint256 cap = d.readGas;
        raw = new bytes(maximum);
        if (cap == 0 || cap > type(uint64).max || gasleft() <= cap + cap / 63 + 10000) {
            revert IStreamConservationRecordSelection.ConservationDependencyReadFailed(target);
        }
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(input, 32), mload(input), add(raw, 32), maximum)
            size := returndatasize()
        }
        if (!ok || size > maximum) {
            revert IStreamConservationRecordSelection.ConservationDependencyReadFailed(target);
        }
        assembly ("memory-safe") { mstore(raw, size) }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamRecordJson.sol";
import "./StreamConservationDefinitions.sol";
import "../../interfaces/stream/metadata/StreamConservationRecordTypes.sol";

/// @notice Closed conservation fields; references are commitments, never verified external facts.
library StreamConservationRecordFields {
    error InvalidConservationWitness();

    function referenceJSON(StreamConservationRecordTypes.Reference memory r)
        public
        pure
        returns (string memory)
    {
        if (r.canonicalizationId == 0 || r.algorithm == 0 || r.algorithm > 6) {
            revert InvalidConservationWitness();
        }
        if (r.algorithm == 4 || r.algorithm == 5) {
            if (r.digest.length == 0 || r.digest.length > 128) revert InvalidConservationWitness();
        } else if (r.digest.length != 32) {
            revert InvalidConservationWitness();
        }
        StreamMetadataRenderer.requireValidUtf8ContentUri(
            "CONSERVATION_REFERENCE", r.uri, 2048, false
        );
        return string.concat(
            '{"hash":{"algorithm":',
            string(abi.encodePacked(bytes1(uint8(48 + r.algorithm)))),
            ',"canonicalizationId":',
            StreamRecordJson.hexValue(r.canonicalizationId),
            ',"digest":',
            _hexBytes(r.digest),
            '},"uri":',
            StreamRecordJson.quote(r.uri, 2048, false),
            "}"
        );
    }

    function requireEmptyReference(StreamConservationRecordTypes.Reference memory r) public pure {
        if (
            r.algorithm != 0 || r.canonicalizationId != 0 || r.digest.length != 0
                || bytes(r.uri).length != 0
        ) {
            revert InvalidConservationWitness();
        }
    }

    function requireHeader(bytes32 subjectId, bytes32 profileHash, bytes32 expectedProfile)
        public
        pure
    {
        if (subjectId == 0 || profileHash != expectedProfile) {
            revert InvalidConservationWitness();
        }
    }

    function artistJSON(StreamConservationRecordTypes.ArtistClaim memory a)
        public
        pure
        returns (string memory)
    {
        if (a.artistId == 0 || a.bindingGeneration == 0 || a.bindingHash == 0) {
            revert InvalidConservationWitness();
        }
        return string.concat(
            '{"artistId":',
            StreamRecordJson.hexValue(a.artistId),
            ',"bindingGeneration":',
            StreamRecordJson.unsigned(a.bindingGeneration),
            ',"bindingHash":',
            StreamRecordJson.hexValue(a.bindingHash),
            ',"statementOrigin":',
            a.origin == StreamConservationRecordTypes.StatementOrigin.ARTIST_INTENT
                ? '"artist_intent"'
                : '"estate_statement"',
            "}"
        );
    }

    function interviewJSON(StreamConservationRecordTypes.InterviewEntry memory e)
        public
        pure
        returns (string memory)
    {
        StreamConservationRecordTypes.InterviewRecord memory r = e.record;
        if (e.status == StreamConservationRecordTypes.InterviewStatus.PRESENT) {
            requireEmptyReference(e.waiverStatement);
            if (
                r.chainId == 0 || r.core == address(0) || r.host == address(0) || r.recordHash == 0
                    || r.schemaId != StreamConservationDefinitions.INTERVIEW_SCHEMA_ID
                    || r.profileHash != StreamConservationDefinitions.INTERVIEW_PROFILE_HASH
            ) revert InvalidConservationWitness();
            string memory locator = string.concat(
                '{"chainId":',
                StreamRecordJson.unsigned(r.chainId),
                ',"core":',
                StreamRecordJson.account(r.core),
                ',"host":',
                StreamRecordJson.account(r.host),
                ',"profileHash":',
                StreamRecordJson.hexValue(r.profileHash),
                ',"recordHash":',
                StreamRecordJson.hexValue(r.recordHash),
                ',"schemaId":',
                StreamRecordJson.hexValue(r.schemaId),
                "}"
            );
            return string.concat(
                '{"kind":"present","payload":', referenceJSON(r.payload), ',"record":', locator, "}"
            );
        }
        if (
            r.chainId != 0 || r.core != address(0) || r.host != address(0) || r.recordHash != 0
                || r.schemaId != 0 || r.profileHash != 0
        ) revert InvalidConservationWitness();
        requireEmptyReference(r.payload);
        return string.concat(
            '{"kind":"interview_waived","statement":', referenceJSON(e.waiverStatement), "}"
        );
    }

    /// @notice Preserve every row and its order with one bounded output allocation.
    function arrayJSON(bytes[] memory rows) public pure returns (string memory) {
        uint256 size = 2;
        for (uint256 i; i < rows.length; ++i) {
            size += rows[i].length + (i == 0 ? 0 : 1);
            if (size > 8192) revert InvalidConservationWitness();
        }
        bytes memory out = new bytes(size);
        out[0] = "[";
        uint256 offset = 1;
        for (uint256 i; i < rows.length; ++i) {
            if (i != 0) out[offset++] = ",";
            _copyRow(rows[i], out, offset);
            offset += rows[i].length;
        }
        out[offset] = "]";
        return string(out);
    }

    function requirePayloadSize(bytes memory value) public pure returns (bytes memory) {
        if (value.length == 0 || value.length > 8192) revert InvalidConservationWitness();
        return value;
    }

    function _hexBytes(bytes memory input) private pure returns (string memory) {
        bytes memory alphabet = "0123456789abcdef";
        bytes memory out = new bytes(4 + input.length * 2);
        out[0] = '"';
        out[1] = "0";
        out[2] = "x";
        out[out.length - 1] = '"';
        for (uint256 i; i < input.length; ++i) {
            out[3 + i * 2] = alphabet[uint8(input[i]) >> 4];
            out[4 + i * 2] = alphabet[uint8(input[i]) & 15];
        }
        return string(out);
    }

    function _copyRow(bytes memory row, bytes memory out, uint256 offset) private pure {
        assembly ("memory-safe") {
            let size := mload(row)
            let source := add(row, 32)
            let target := add(add(out, 32), offset)
            let cursor := 0
            for { } iszero(gt(add(cursor, 32), size)) { cursor := add(cursor, 32) } {
                mstore(add(target, cursor), mload(add(source, cursor)))
            }
            if lt(cursor, size) {
                let tail := mload(add(source, cursor))
                let index := 0
                for { } lt(cursor, size) {
                    cursor := add(cursor, 1)
                    index := add(index, 1)
                } { mstore8(add(target, cursor), byte(index, tail)) }
            }
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamConservationPublicationReads.sol";
import "./StreamArtistIntentJson.sol";
import "./StreamArtistIntentWaiverJson.sol";
import "./StreamArtistInterviewJson.sol";

/// @notice Complete typed conservation meaning over authenticated original records.
/// @dev External source statements remain attributed claims; original op24 evidence is retained.
library StreamConservationRecordReads {
    struct Prepared {
        IStreamConservationRecordSelection.Selection selection;
        IStreamConservationRecordSelection.CatalogPin[] catalogs;
    }

    function intent(
        StreamConservationRecordContext.Dependencies memory d,
        uint256 collectionId,
        bytes32 subjectId,
        bytes32 recordHash,
        IStreamConservationRecordSelection.IntentWitness calldata witness,
        IStreamConservationRecordSelection.PreparedInterview memory prepared
    ) public view returns (Prepared memory p) {
        p.selection.record = StreamConservationPublicationReads.recorded(
            d,
            collectionId,
            subjectId,
            recordHash,
            witness.original,
            IStreamConservationRecordSelection.RecordKind.INTENT
        );
        StreamArtistIntentJson.requireExact(
            witness.intent,
            StreamConservationPublicationReads.payload(
                d, recordHash, p.selection.record.payloadHash
            )
        );
        if (witness.intent.subjectId != subjectId) {
            revert IStreamConservationRecordSelection.InvalidConservationRecord(recordHash);
        }
        p.selection.predecessor = witness.intent.predecessor;
        p.selection.association = StreamConservationRecordContext.association(d, collectionId);
        _artist(p.selection, witness.intent.artist);
        (p.selection.interview, p.catalogs, p.selection.interviewPayloadCorrespondence) = _interview(
            d,
            collectionId,
            subjectId,
            p.selection.association,
            witness.intent.interview,
            witness.interview,
            prepared
        );
        p.selection.interviewStatus = witness.intent.interview.status;
        if (
            witness.intent.interview.status == StreamConservationRecordTypes.InterviewStatus.PRESENT
        ) {
            p.selection.interviewArchiveReferenceHash =
                keccak256(abi.encode(witness.intent.interview.record.payload));
        }
        p.selection.catalogsHash = keccak256(abi.encode(p.catalogs));
    }

    function waiver(
        StreamConservationRecordContext.Dependencies memory d,
        uint256 collectionId,
        bytes32 subjectId,
        bytes32 recordHash,
        IStreamConservationRecordSelection.WaiverWitness calldata witness,
        IStreamConservationRecordSelection.PreparedInterview memory prepared
    ) public view returns (Prepared memory p) {
        p.selection.record = StreamConservationPublicationReads.recorded(
            d,
            collectionId,
            subjectId,
            recordHash,
            witness.original,
            IStreamConservationRecordSelection.RecordKind.INTENT_WAIVER
        );
        StreamArtistIntentWaiverJson.requireExact(
            witness.waiver,
            StreamConservationPublicationReads.payload(
                d, recordHash, p.selection.record.payloadHash
            )
        );
        if (witness.waiver.subjectId != subjectId) {
            revert IStreamConservationRecordSelection.InvalidConservationRecord(recordHash);
        }
        p.selection.predecessor = witness.waiver.predecessor;
        p.selection.association = StreamConservationRecordContext.association(d, collectionId);
        _artist(p.selection, witness.waiver.artist);
        (p.selection.interview, p.catalogs, p.selection.interviewPayloadCorrespondence) = _interview(
            d,
            collectionId,
            subjectId,
            p.selection.association,
            witness.waiver.interview,
            witness.interview,
            prepared
        );
        p.selection.interviewStatus = witness.waiver.interview.status;
        if (
            witness.waiver.interview.status == StreamConservationRecordTypes.InterviewStatus.PRESENT
        ) {
            p.selection.interviewArchiveReferenceHash =
                keccak256(abi.encode(witness.waiver.interview.record.payload));
        }
        p.selection.catalogsHash = keccak256(abi.encode(p.catalogs));
    }

    function requireSelected(
        StreamConservationRecordContext.Dependencies memory d,
        uint256 collectionId,
        IStreamConservationRecordSelection.Selection memory selected,
        IStreamConservationRecordSelection.CatalogPin[] memory catalogs
    ) public view {
        IStreamConservationRecordSelection.Association memory current =
            StreamConservationRecordContext.association(d, collectionId);
        if (keccak256(abi.encode(current)) != keccak256(abi.encode(selected.association))) {
            revert IStreamConservationRecordSelection.ConservationAssociationChanged();
        }
        if (keccak256(abi.encode(catalogs)) != selected.catalogsHash) {
            revert IStreamConservationRecordSelection.ConservationSelectionConflict();
        }
        for (uint256 i; i < catalogs.length; ++i) {
            StreamConservationRecordContext.definition(
                d,
                catalogs[i].documentId,
                IStreamSchemaRegistry.DocumentKind.CATALOG,
                catalogs[i].contentHash,
                catalogs[i].totalBytes,
                StreamWorkRecordDefinitions.CANON_ID,
                false
            );
        }
    }

    function _artist(
        IStreamConservationRecordSelection.Selection memory selected,
        StreamConservationRecordTypes.ArtistClaim memory claim
    ) private pure {
        _sameAssociation(selected.association, selected.record);
        if (
            claim.artistId != selected.association.artistId
                || claim.bindingHash != selected.association.bindingHash
                || claim.bindingGeneration != selected.association.generation
                || (claim.origin == StreamConservationRecordTypes.StatementOrigin.ARTIST_INTENT
                        ? selected.record.publication.authorityClass != 1
                        : selected.record.publication.authorityClass != 3)
        ) {
            revert IStreamConservationRecordSelection.ConservationAssociationChanged();
        }
        selected.origin = claim.origin;
    }

    function _sameAssociation(
        IStreamConservationRecordSelection.Association memory a,
        IStreamConservationRecordSelection.RecordEvidence memory e
    ) private pure {
        if (
            a.artistId == 0 || e.publication.artistId != a.artistId
                || e.publication.bindingHash != a.bindingHash
                || e.publication.bindingGeneration != a.generation
        ) {
            revert IStreamConservationRecordSelection.ConservationAssociationChanged();
        }
    }

    function _interview(
        StreamConservationRecordContext.Dependencies memory d,
        uint256 collectionId,
        bytes32 subjectId,
        IStreamConservationRecordSelection.Association memory a,
        StreamConservationRecordTypes.InterviewEntry memory entry,
        IStreamConservationRecordSelection.InterviewWitness calldata witness,
        IStreamConservationRecordSelection.PreparedInterview memory prepared
    )
        private
        view
        returns (
            IStreamConservationRecordSelection.RecordEvidence memory e,
            IStreamConservationRecordSelection.CatalogPin[] memory catalogs,
            IStreamConservationRecordSelection.PayloadCorrespondence correspondence
        )
    {
        if (entry.status == StreamConservationRecordTypes.InterviewStatus.WAIVED) {
            IStreamConservationRecordSelection.InterviewWitness memory empty;
            if (
                prepared.preparationHash != 0
                    || keccak256(abi.encode(witness)) != keccak256(abi.encode(empty))
            ) {
                revert IStreamConservationRecordSelection.InvalidConservationRecord(0);
            }
            return (e, new IStreamConservationRecordSelection.CatalogPin[](0), correspondence);
        }
        StreamConservationRecordTypes.InterviewRecord memory locator = entry.record;
        if (
            locator.chainId != d.chainId || locator.core != d.targets[0]
                || locator.host != d.targets[1]
                || locator.schemaId != StreamConservationDefinitions.INTERVIEW_SCHEMA_ID
                || locator.profileHash != StreamConservationDefinitions.INTERVIEW_PROFILE_HASH
        ) {
            revert IStreamConservationRecordSelection.InvalidConservationRecord(locator.recordHash);
        }
        if (prepared.preparationHash == 0) {
            prepared = prepareInterview(d, collectionId, subjectId, locator.recordHash, witness);
        } else {
            IStreamConservationRecordSelection.InterviewWitness memory empty;
            if (
                keccak256(abi.encode(witness)) != keccak256(abi.encode(empty))
                    || prepared.collectionId != collectionId || prepared.subjectId != subjectId
                    || prepared.record.recordHash != locator.recordHash
                    || prepared.record.kind
                        != IStreamConservationRecordSelection.RecordKind.INTERVIEW
            ) {
                revert IStreamConservationRecordSelection.InvalidConservationRecord(locator.recordHash);
            }
            for (uint256 i; i < prepared.catalogs.length; ++i) {
                IStreamConservationRecordSelection.CatalogPin memory pin = prepared.catalogs[i];
                StreamConservationRecordContext.definition(
                    d,
                    pin.documentId,
                    IStreamSchemaRegistry.DocumentKind.CATALOG,
                    pin.contentHash,
                    pin.totalBytes,
                    StreamWorkRecordDefinitions.CANON_ID,
                    false
                );
            }
        }
        if (keccak256(abi.encode(a)) != keccak256(abi.encode(prepared.association))) {
            revert IStreamConservationRecordSelection.ConservationAssociationChanged();
        }
        e = prepared.record;
        catalogs = prepared.catalogs;
        _sameAssociation(a, e);
        bytes memory payload =
            StreamConservationPublicationReads.payload(d, e.recordHash, e.payloadHash);
        // Known JCS digest algorithms have an actual local correspondence check. All other
        // algorithms/canonicalizations remain attributed claims for a later archival verifier.
        // No digest match establishes retrieval, URI availability or archive delivery.
        if (
            locator.payload.canonicalizationId == StreamWorkRecordDefinitions.CANON_ID
                && (locator.payload.algorithm == 1 || locator.payload.algorithm == 2)
        ) {
            bytes32 digest = locator.payload.algorithm == 1 ? keccak256(payload) : sha256(payload);
            if (locator.payload.digest.length != 32 || bytes32(locator.payload.digest) != digest) {
                revert IStreamConservationRecordSelection.InvalidConservationRecord(locator.recordHash);
            }
            correspondence = locator.payload.algorithm == 1
                ? IStreamConservationRecordSelection.PayloadCorrespondence.EXACT_JCS_KECCAK256
                : IStreamConservationRecordSelection.PayloadCorrespondence.EXACT_JCS_SHA256;
        }
    }

    function prepareInterview(
        StreamConservationRecordContext.Dependencies memory d,
        uint256 collectionId,
        bytes32 subjectId,
        bytes32 recordHash,
        IStreamConservationRecordSelection.InterviewWitness calldata witness
    ) public view returns (IStreamConservationRecordSelection.PreparedInterview memory p) {
        if (witness.interview.subjectId != subjectId) {
            revert IStreamConservationRecordSelection.InvalidConservationRecord(recordHash);
        }
        p.collectionId = collectionId;
        p.subjectId = subjectId;
        p.record = StreamConservationPublicationReads.recorded(
            d,
            collectionId,
            subjectId,
            recordHash,
            witness.original,
            IStreamConservationRecordSelection.RecordKind.INTERVIEW
        );
        bytes memory payload =
            StreamConservationPublicationReads.payload(d, recordHash, p.record.payloadHash);
        StreamArtistInterviewJson.requireExact(witness.interview, payload);
        p.association = StreamConservationRecordContext.association(d, collectionId);
        _sameAssociation(p.association, p.record);
        uint256 count = witness.interview.transcript.format.kind
            == StreamConservationRecordTypes.FormatKind.CATALOG
            ? 1
            : 0;
        for (uint256 i; i < witness.interview.captures.length; ++i) {
            if (
                witness.interview.captures[i].payload.format.kind
                    == StreamConservationRecordTypes.FormatKind.CATALOG
            ) ++count;
        }
        p.catalogs = new IStreamConservationRecordSelection.CatalogPin[](count);
        uint256 cursor;
        if (
            witness.interview.transcript.format.kind
                == StreamConservationRecordTypes.FormatKind.CATALOG
        ) {
            p.catalogs[cursor++] = _catalog(d, witness.interview.transcript.format.catalog);
        }
        for (uint256 i; i < witness.interview.captures.length; ++i) {
            StreamConservationRecordTypes.Format memory format =
            witness.interview.captures[i].payload.format;
            if (format.kind == StreamConservationRecordTypes.FormatKind.CATALOG) {
                p.catalogs[cursor++] = _catalog(d, format.catalog);
            }
        }
    }

    function _catalog(
        StreamConservationRecordContext.Dependencies memory d,
        StreamConservationRecordTypes.Catalog memory catalog
    ) private view returns (IStreamConservationRecordSelection.CatalogPin memory pin) {
        bytes memory bytes_ = StreamConservationFormatJson.catalogDocument(catalog);
        pin.documentId = keccak256(bytes(catalog.name));
        pin.contentHash = keccak256(bytes_);
        pin.totalBytes = bytes_.length;
        bytes memory original = StreamConservationRecordContext.definition(
            d,
            pin.documentId,
            IStreamSchemaRegistry.DocumentKind.CATALOG,
            pin.contentHash,
            pin.totalBytes,
            StreamWorkRecordDefinitions.CANON_ID,
            false
        );
        StreamRecordJson.requirePayload(bytes_, original);
    }
}

