// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/artist/IStreamArtistSuiteReads.sol";
import "../../interfaces/stream/artist/IStreamArtistOwner.sol";
import "../../interfaces/stream/artist/IStreamArtistIngressBinding.sol";
import "../../interfaces/stream/artist/IStreamArtistIdentityOwner.sol";
import {
    StreamMetadataArtistSelection as ArtistSelection
} from "../metadata/StreamMetadataArtistSelection.sol";

/// @notice Resolves the actual Identity owner behind the metadata host's artist facade.
/// @dev The authenticated consumer supplies immutable metadata/Core/chain and its governed
///      metadata dependency-read gas cap. No witness chooses an Identity owner or signer.
library StreamRecordArtistIdentityReads {
    error InvalidArtistIdentityContext();
    error ArtistIdentityReadFailed(address target);
    error ArtistIdentityDependencyChanged(address target);
    error UnknownRecordArtist(bytes32 artistId);

    struct Pins {
        // In order: onboarding facade, operation Coordinator, Identity owner.
        address[3] targets;
        bytes32[3] codeHashes;
    }

    function resolve(address metadata, address core, uint256 chainId, uint256 readGas)
        public
        view
        returns (Pins memory pins)
    {
        if (
            core == address(0) || block.chainid != chainId || readGas == 0
                || readGas > type(uint64).max
        ) revert InvalidArtistIdentityContext();
        // The same artistRegistry() ABI selector is present on metadata and the owner.
        // This does not assert that metadata implements the owner interface.
        pins.targets[0] = _address(metadata, IStreamArtistOwner.artistRegistry.selector, readGas);
        pins.codeHashes[0] = _code(pins.targets[0]);
        // Metadata binds this facade runtime immutably at deployment. Initial resolution
        // cannot adopt a coherently substituted graph merely because its current getters agree.
        bytes32 originalFacadeCodeHash = _word(
            _read(metadata, abi.encodeWithSignature("artistRegistryCodeHash()"), 32, readGas), 0
        );
        if (pins.codeHashes[0] != originalFacadeCodeHash) {
            revert ArtistIdentityDependencyChanged(pins.targets[0]);
        }
        return _identityPins(pins, core, chainId, readGas);
    }

    /// @notice Resolve the currently selected Artist only after the original Metadata succession proof.
    /// @dev Original immutable Metadata bindings remain the ancestry anchor. Existing op60,
    /// predecessor and all-owner completion checks choose the current facade; no witness does.
    function resolveCurrent(address metadata, address core, uint256 chainId, uint256 readGas)
        public
        view
        returns (Pins memory pins)
    {
        if (
            core == address(0) || block.chainid != chainId || readGas == 0
                || readGas > type(uint64).max
        ) revert InvalidArtistIdentityContext();
        address original = _address(metadata, IStreamArtistOwner.artistRegistry.selector, readGas);
        bytes32 originalHash = _word(
            _read(metadata, abi.encodeWithSignature("artistRegistryCodeHash()"), 32, readGas), 0
        );
        ArtistSelection.Selected memory selected = ArtistSelection.selected(
            ArtistSelection.Context(core, _code(core), original, originalHash, readGas)
        );
        pins.targets[0] = selected.registry;
        pins.codeHashes[0] = selected.runtimeHash;
        return _identityPins(pins, core, chainId, readGas);
    }

    function _identityPins(Pins memory pins, address core, uint256 chainId, uint256 readGas)
        private
        view
        returns (Pins memory)
    {
        if (_address(pins.targets[0], IStreamArtistOwner.core.selector, readGas) != core) {
            revert InvalidArtistIdentityContext();
        }
        pins.targets[1] = _address(
            pins.targets[0], IStreamArtistIngressBinding.operationCoordinator.selector, readGas
        );
        pins.codeHashes[1] = _code(pins.targets[1]);
        if (
            _word(
                    _read(
                        pins.targets[1],
                        abi.encodeWithSelector(IStreamArtistSuiteReads.deploymentChainId.selector),
                        32,
                        readGas
                    ),
                    0
                ) != bytes32(chainId)
        ) {
            revert InvalidArtistIdentityContext();
        }
        bytes memory suite = _read(
            pins.targets[1],
            abi.encodeWithSelector(IStreamArtistSuiteReads.suiteConfiguration.selector),
            544,
            readGas
        );
        // SuiteConfiguration has17 fixed words. Every word except primaryRevenueClass15
        // is an address. Validate even unused words; no aliasing/trailing/dynamic decoding.
        for (uint256 i; i < 17; ++i) {
            if (i != 15 && uint256(_word(suite, i)) > type(uint160).max) {
                revert ArtistIdentityReadFailed(pins.targets[1]);
            }
        }
        if (
            _word(suite, 0) != bytes32(uint256(uint160(pins.targets[0])))
                || _word(suite, 9) != bytes32(uint256(uint160(core)))
        ) revert InvalidArtistIdentityContext();
        pins.targets[2] = address(uint160(uint256(_word(suite, 4)))); // owners[2]
        pins.codeHashes[2] = _code(pins.targets[2]);
        if (
            _address(pins.targets[2], IStreamArtistOwner.core.selector, readGas) != core
                || _address(pins.targets[2], IStreamArtistOwner.artistRegistry.selector, readGas)
                    != pins.targets[0]
                || _address(
                        pins.targets[2], IStreamArtistOwner.operationCoordinator.selector, readGas
                    ) != pins.targets[1]
                || _word(
                        _read(
                            pins.targets[2],
                            abi.encodeWithSelector(IStreamArtistOwner.deploymentChainId.selector),
                            32,
                            readGas
                        ),
                        0
                    ) != bytes32(chainId)
        ) {
            revert InvalidArtistIdentityContext();
        }
        return pins;
    }

    /// @notice Immutable registration identity only; operative authority fields are not returned.
    /// @dev No active/class/signer/collection-association requirement. Caller may retain this hash
    ///      as historical evidence while separately checking current deployment pins.
    function knownIdentity(
        address metadata,
        address core,
        uint256 chainId,
        Pins memory expected,
        bytes32 artistId,
        uint256 readGas
    ) public view returns (bytes32 identityRecordHash) {
        if (artistId == 0) revert UnknownRecordArtist(artistId);
        Pins memory current = resolve(metadata, core, chainId, readGas);
        return _knownIdentity(current, expected, artistId, readGas);
    }

    /// @notice Read immutable registration identity through the authenticated current graph.
    /// @dev Re-resolves current succession on each use and refuses previously pinned graphs.
    function knownCurrentIdentity(
        address metadata,
        address core,
        uint256 chainId,
        Pins memory expected,
        bytes32 artistId,
        uint256 readGas
    ) public view returns (bytes32 identityRecordHash) {
        if (artistId == 0) revert UnknownRecordArtist(artistId);
        Pins memory current = resolveCurrent(metadata, core, chainId, readGas);
        return _knownIdentity(current, expected, artistId, readGas);
    }

    function _knownIdentity(
        Pins memory current,
        Pins memory expected,
        bytes32 artistId,
        uint256 readGas
    ) private view returns (bytes32 identityRecordHash) {
        for (uint256 i; i < 3; ++i) {
            if (
                current.targets[i] != expected.targets[i]
                    || current.codeHashes[i] != expected.codeHashes[i]
            ) {
                revert ArtistIdentityDependencyChanged(current.targets[i]);
            }
        }
        bytes memory facts = _read(
            current.targets[2],
            abi.encodeCall(IStreamArtistIdentityOwner.authorityState, (artistId)),
            128,
            readGas
        );
        if (
            uint256(_word(facts, 0)) > type(uint160).max
                || uint256(_word(facts, 1)) > type(uint8).max
                || uint256(_word(facts, 2)) > type(uint8).max
        ) revert ArtistIdentityReadFailed(current.targets[2]);
        identityRecordHash = _word(facts, 3);
        if (identityRecordHash == 0) revert UnknownRecordArtist(artistId);
    }

    function _code(address target) private view returns (bytes32) {
        if (target.code.length == 0) revert ArtistIdentityDependencyChanged(target);
        return target.codehash;
    }

    function _address(address target, bytes4 selector, uint256 cap) private view returns (address) {
        uint256 value = uint256(_word(_read(target, abi.encodeWithSelector(selector), 32, cap), 0));
        if (value > type(uint160).max) revert ArtistIdentityReadFailed(target);
        return address(uint160(value));
    }

    function _word(bytes memory data, uint256 index) private pure returns (bytes32 value) {
        assembly ("memory-safe") { value := mload(add(add(data, 32), mul(index, 32))) }
    }

    function _read(address target, bytes memory input, uint256 size, uint256 cap)
        private
        view
        returns (bytes memory data)
    {
        if (target.code.length == 0) revert ArtistIdentityReadFailed(target);
        data = new bytes(size);
        // Allocation/calldata construction precede admission. Leave EIP150 and local
        // bookkeeping headroom immediately before the fixed-cap, fixed-copy call.
        if (gasleft() <= cap + cap / 63 + 10000) revert ArtistIdentityReadFailed(target);
        bool ok;
        uint256 returned;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(input, 32), mload(input), add(data, 32), size)
            returned := returndatasize()
        }
        if (!ok || returned != size) revert ArtistIdentityReadFailed(target);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/metadata/IStreamSchemaRegistry.sol";
import "../../interfaces/stream/metadata/IStreamSchemaDocumentFacts.sol";
import "../../interfaces/stream/metadata/IStreamCollectionMetadataV1.sol";
import "../metadata/StreamSchemaDocumentStore.sol";

/// @notice Bounded interpretation and payload reads shared by record hosts.
/// @dev Static document facts avoid registration URI/chunk-array costs under the governed cap.
library StreamRecordDocumentReads {
    function activeSchema(address registry, bytes32 schemaId, bytes32 canonId, uint256 gasCap)
        public
        view
        returns (bytes32, bytes32)
    {
        IStreamSchemaDocumentFacts.DocumentFacts memory schema = _facts(registry, schemaId, gasCap);
        IStreamSchemaDocumentFacts.DocumentFacts memory canon = _facts(registry, canonId, gasCap);
        if (
            !schema.exists || schema.status != IStreamSchemaRegistry.DocumentStatus.ACTIVE
                || schema.kind != IStreamSchemaRegistry.DocumentKind.SCHEMA
        ) revert IStreamCollectionMetadataV1.MetadataSchemaUnavailable(schemaId);
        if (
            !canon.exists || canon.status != IStreamSchemaRegistry.DocumentStatus.ACTIVE
                || canon.kind != IStreamSchemaRegistry.DocumentKind.CANONICALIZATION
        ) revert IStreamCollectionMetadataV1.MetadataSchemaUnavailable(canonId);
        return (schema.contentHash, canon.contentHash);
    }

    function _facts(address registry, bytes32 id, uint256 cap)
        private
        view
        returns (IStreamSchemaDocumentFacts.DocumentFacts memory)
    {
        bytes memory output = _read(
            registry, abi.encodeCall(IStreamSchemaDocumentFacts.documentFacts, (id)), 288, cap
        );
        if (output.length != 288) revert IStreamCollectionMetadataV1.MetadataReadFailed(registry);
        return abi.decode(output, (IStreamSchemaDocumentFacts.DocumentFacts));
    }

    function chunk(address store, bytes32 hash, uint256 gasCap) public view returns (bytes memory) {
        return abi.decode(
            _read(store, abi.encodeCall(StreamSchemaDocumentStore.readChunk, (hash)), 8352, gasCap),
            (bytes)
        );
    }

    function _read(address target, bytes memory input, uint256 maximum, uint256 cap)
        private
        view
        returns (bytes memory data)
    {
        if (gasleft() <= cap + cap / 63 + 10000) {
            revert IStreamCollectionMetadataV1.MetadataReadFailed(target);
        }
        data = new bytes(maximum);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(input, 32), mload(input), add(data, 32), maximum)
            size := returndatasize()
        }
        if (!ok || size > maximum) revert IStreamCollectionMetadataV1.MetadataReadFailed(target);
        assembly ("memory-safe") { mstore(data, size) }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @notice Existing family identifiers and numeric authorization-class masks from CMC-AUTHZ.
library StreamRecordFamilies {
    bytes32 internal constant ARTIST = keccak256("6529STREAM_RECORD_FAMILY_ARTIST_V1");
    bytes32 internal constant OWNER = keccak256("6529STREAM_RECORD_FAMILY_OWNER_V1");
    bytes32 internal constant INDEPENDENT = keccak256("6529STREAM_RECORD_FAMILY_INDEPENDENT_V1");
    bytes32 internal constant CURATOR = keccak256("6529STREAM_RECORD_FAMILY_CURATOR_V1");
    bytes32 internal constant INSTITUTION = keccak256("6529STREAM_RECORD_FAMILY_INSTITUTION_V1");
    bytes32 internal constant RIGHTS = keccak256("6529STREAM_RECORD_FAMILY_RIGHTS_V1");
    bytes32 internal constant ARCHIVE = keccak256("6529STREAM_RECORD_FAMILY_ARCHIVE_V1");
    bytes32 internal constant FIXITY = keccak256("6529STREAM_RECORD_FAMILY_FIXITY_V1");
    bytes32 internal constant C2PA = keccak256("6529STREAM_RECORD_FAMILY_C2PA_V1");
    bytes32 internal constant IIIF = keccak256("6529STREAM_RECORD_FAMILY_IIIF_V1");
    bytes32 internal constant MEDIA = keccak256("6529STREAM_RECORD_FAMILY_MEDIA_RELATIONSHIP_V1");
    bytes32 internal constant IDENTITY = keccak256("6529STREAM_RECORD_FAMILY_IDENTITY_DISPLAY_V1");
    bytes32 internal constant SNAPSHOT = keccak256("6529STREAM_RECORD_FAMILY_SNAPSHOT_V1");
    bytes32 internal constant AGENT = keccak256("6529STREAM_RECORD_FAMILY_AGENT_V1");
    bytes32 internal constant CONSERVATION = keccak256("6529STREAM_RECORD_FAMILY_CONSERVATION_V1");

    function bit(uint8 authorizationClass) internal pure returns (uint16) {
        return uint16(1) << authorizationClass;
    }

    function allowed(bytes32 family) internal pure returns (uint16) {
        if (family == ARTIST) return bit(1);
        if (family == OWNER) return bit(2);
        if (family == INDEPENDENT) return bit(5);
        if (family == CURATOR) return bit(3) | bit(8);
        if (family == INSTITUTION) return bit(4);
        if (
            family == RIGHTS || family == IDENTITY || family == SNAPSHOT || family == AGENT
                || family == CONSERVATION
        ) {
            return bit(7) | bit(8);
        }
        if (family == ARCHIVE) return bit(6) | bit(8);
        if (family == FIXITY || family == C2PA) return bit(4) | bit(6) | bit(8);
        if (family == IIIF) return bit(6) | bit(7) | bit(8);
        if (family == MEDIA) return bit(6) | bit(7);
        return 0;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../metadata/StreamMetadataRenderer.sol";

/// @notice Exact primitives for closed, fixed-key JSON record profiles.
/// @dev No generic JSON parsing, Unicode normalization, floating point, or authority decision.
library StreamRecordJson {
    error InvalidJsonWitness();
    error RecordPayloadMismatch();

    function quote(string memory value, uint256 maximum, bool allowEmpty)
        public
        pure
        returns (string memory)
    {
        if (
            (!allowEmpty && bytes(value).length == 0) || bytes(value).length > maximum
                || !StreamMetadataRenderer.isValidUtf8(value)
        ) revert InvalidJsonWitness();
        return string.concat('"', StreamMetadataRenderer.escapeJsonString(value), '"');
    }

    function hexValue(bytes32 value) public pure returns (string memory) {
        return _hex(abi.encodePacked(value));
    }

    function account(address value) public pure returns (string memory) {
        if (value == address(0)) revert InvalidJsonWitness();
        return _hex(abi.encodePacked(value));
    }

    function _hex(bytes memory input) private pure returns (string memory) {
        bytes memory alphabet = "0123456789abcdef";
        bytes memory output = new bytes(4 + input.length * 2);
        output[0] = '"';
        output[1] = "0";
        output[2] = "x";
        for (uint256 i; i < input.length; ++i) {
            output[3 + i * 2] = alphabet[uint8(input[i]) >> 4];
            output[4 + i * 2] = alphabet[uint8(input[i]) & 15];
        }
        output[output.length - 1] = '"';
        return string(output);
    }

    /// @notice Canonical decimal string, preserving the complete uint256 range.
    function unsigned(uint256 value) public pure returns (string memory) {
        uint256 digits = 1;
        for (uint256 remaining = value; remaining >= 10; remaining /= 10) {
            ++digits;
        }
        bytes memory output = new bytes(digits + 2);
        output[0] = '"';
        output[digits + 1] = '"';
        do {
            output[digits--] = bytes1(uint8(48 + value % 10));
            value /= 10;
        } while (value != 0);
        return string(output);
    }

    /// @notice Exact proleptic Gregorian YYYY-MM-DD, years 0001..9999, no inferred timezone.
    function date(uint32 value) public pure returns (string memory) {
        uint256 year = value / 10000;
        uint256 month = value / 100 % 100;
        uint256 day = value % 100;
        if (year == 0 || year > 9999 || month == 0 || month > 12 || day == 0) {
            revert InvalidJsonWitness();
        }
        uint256 maximum = month == 2
            ? (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0) ? 29 : 28)
            : (month == 4 || month == 6 || month == 9 || month == 11 ? 30 : 31);
        if (day > maximum) revert InvalidJsonWitness();
        bytes memory output = bytes('"0000-00-00"');
        output[1] = bytes1(uint8(48 + year / 1000));
        output[2] = bytes1(uint8(48 + year / 100 % 10));
        output[3] = bytes1(uint8(48 + year / 10 % 10));
        output[4] = bytes1(uint8(48 + year % 10));
        output[6] = bytes1(uint8(48 + month / 10));
        output[7] = bytes1(uint8(48 + month % 10));
        output[9] = bytes1(uint8(48 + day / 10));
        output[10] = bytes1(uint8(48 + day % 10));
        return string(output);
    }

    function requirePayload(bytes memory serialized, bytes memory stored)
        public
        pure
        returns (bytes32 hash)
    {
        if (
            serialized.length == 0 || serialized.length > 8192 || serialized.length != stored.length
        ) revert RecordPayloadMismatch();
        hash = keccak256(serialized);
        if (hash != keccak256(stored)) revert RecordPayloadMismatch();
        // Do not accept a witness that describes only a projection of the recorded object.
        for (uint256 i; i < stored.length; ++i) {
            if (serialized[i] != stored[i]) revert RecordPayloadMismatch();
        }
    }
}

