pragma solidity ^0.8.19;

/// @notice Exact additive scoped-policy reference definitions; original profiles remain unchanged.
library StreamScopedPolicyReferenceDefinitionsV2 {
    bytes32 internal constant SCHEMA_ID = keccak256("STREAM_SCOPED_POLICY_REFERENCE_ABI_V2");
    bytes32 internal constant SCHEMA_HASH =
        0x66d9b03f9b6c4aa37c55df3f47a5d21a964a419bd93a83130bbf0487a0a26715;
    uint32 internal constant SCHEMA_BYTES = 26018;
    bytes32 internal constant PROFILE_ID = keccak256("STREAM_SCOPED_POLICY_REFERENCE_PROFILE_V2");
    bytes32 internal constant PROFILE_HASH =
        0x4351690bd9597070d7de6a17071c7103d46a52efc757954a567fe542ecb64a47;
    uint32 internal constant PROFILE_BYTES = 2114;
    bytes32 internal constant CANON_ID = keccak256("STREAM_ABI_SCOPED_POLICY_REFERENCE_V2");
    bytes32 internal constant CANON_HASH =
        0xfd2a277aa777a57d09d19665f0c73a2a9ace95f4fa3c3b9b8340917e53c79028;
    uint32 internal constant CANON_BYTES = 1412;
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @notice Distinct scoped full-policy definitions; original profile documents are unchanged.
library StreamScopedPolicySnapshotDefinitionsV2 {
    bytes32 internal constant SCHEMA_ID = keccak256("STREAM_SCOPED_POLICY_SNAPSHOT_ABI_V2");
    string internal constant SCHEMA_DOCUMENT =
        "{\"name\":\"STREAM_SCOPED_POLICY_SNAPSHOT_ABI_V2\",\"version\":2,\"format\":\"Solidity ABI\",\"scope\":\"Canonical TOKEN, RELEASE or SEASON only; COLLECTION and VIEW are excluded\",\"dependencies\":[\"Core\",\"Metadata\",\"schemas\",\"Store\",\"Router\",\"scope membership\",\"STATIC selection checkpoint\",\"scoped-policy content checkpoint\",\"scoped-policy output manifest\",\"artifact coverage\",\"immutable full-policy source set\"],\"publication\":[\"StreamFinalityScope scope\",\"bytes32 snapshotId\",\"bytes32 expectedHead\",\"uint64 expectedRevision\",\"bytes32 outputManifestRecord\",\"bytes32 coordinatorInventoryPlan\",\"bytes32 expectedSourceHash\",\"string manifestURI\",\"uint64 effectiveAt\",\"bytes32 reasonHash\"],\"receipt\":[\"bytes32 recordHash\",\"bytes32 scopeSubject\",\"bytes32 predecessor\",\"uint64 revision\",\"bytes32 chainHash\",\"bytes32 manifestHash\",\"uint32 manifestBytes\",\"bytes32 sourceHash\",\"address publisher\",\"uint8 authorizationClass\",\"uint64 grantRevision\",\"uint8 displayAuthorizationClass\",\"uint64 displayGrantRevision\",\"uint64 recordedAt\",\"bytes32 schemaHash\",\"bytes32 profileHash\",\"bytes32 canonicalizationHash\"],\"source\":[\"StreamFinalityScope scope\",\"StreamScopeMembershipFacts membership\",\"IStreamMetadataServingFacts.ArtistPresentation artist\",\"IStreamStaticSelectionCheckpoint.Plan selection\",\"IStreamScopedPolicyContentCheckpointV2.Plan content\",\"IStreamScopedPolicyOutputManifestV2.Manifest outputs\",\"address sourceFactory\",\"bytes32 sourceFactoryCodeHash\",\"bytes32 factoryDependenciesHash\",\"StreamFinalityCoordinatorPolicyEvidenceV2 entropy\"],\"scopeTuple\":\"uint8 scopeType,uint256 collectionId,uint256 tokenId,bytes32 scopeId\",\"membership\":\"bytes32 scopeSubject,bytes32 scopeManifestHash,bytes32 sourceRecordHash,uint256 tokenCount,bytes32 tokenListHash,bytes32 membershipHash,uint256 inventoryCount,bytes32 inventoryPrefixHash\",\"artist\":\"bool locked,address registry,bytes32 registryCodeHash,bytes32 artistId,uint64 bindingGeneration,bytes32 bindingHash,address nominatedArtist,bytes32 identityRecordHash,bytes32 acceptanceRecordHash,uint64 acceptedAt,uint64 lockedAt,bytes32 snapshotHash\",\"selection\":\"StreamFinalityScope scope,bytes32 membershipHash,bytes32 collectionStateHash,uint64 tokenCount,uint64 nextIndex,bytes32 selectionRoot\",\"content\":\"bytes32 selectionId,bytes32 selectionHash,bytes32 inventoryHash,bytes32 policyChainHash,StreamFinalityScope scope,uint64 tokenCount,uint64 nextIndex,bytes32 leafChainHash,bytes32 contentRoot,bytes32 outputRoot\",\"outputs\":\"bytes32 checkpointHash,bytes32 checkpointStateHash,address entropySourceSet,bytes32 inventoryHash,bytes32 policyChainHash,bytes32 artifactHash,bytes32 coverageHash,bytes32 artistId,bytes32 contentRoot,bytes32 outputRoot,bytes32 manifestHash,StreamFinalityScope scope,uint64 tokenCount,uint64 byteLength\",\"entropy\":\"bytes32 planId,bytes32 inventoryHash,bytes32 policyChainHash,uint256 policyCount,bool allFrozen,StreamFinalityCoordinatorPolicyV2[] policies\",\"policyRow\":\"address coordinator,bytes32 indexedCodeHash,uint256 firstTokenIndex,bool frozen,bytes32 moduleVersion,bytes32 moduleManifestHash,bytes32 moduleSchemaHash,bytes32 deploymentManifestHash,bytes32 policyHash,address provider,uint32 epoch,bytes32 salt,bytes32 componentDataHash,bool explicitPolicy,Policy collectionPolicy\",\"collectionPolicy\":\"bool configured,bool explicitPolicy,bool frozen,uint8 mode,uint8 securityClass,uint8 renderRequirement,uint64 revision,uint32 providerEpoch,bytes32 policyHash,bytes32 contentStateHash,bytes32 lastActionId,bytes32 artistConsentRecord\",\"root\":\"No root record or authority appears in this source payload; separate scoped CONTENT_ROOT adoption follows publication\"}";
    bytes32 internal constant SCHEMA_HASH = keccak256(bytes(SCHEMA_DOCUMENT));
    uint256 internal constant SCHEMA_BYTES = 3617;

    bytes32 internal constant PROFILE_ID = keccak256("STREAM_SCOPED_POLICY_SNAPSHOT_PROFILE_V2");
    string internal constant PROFILE_DOCUMENT =
        "{\"name\":\"STREAM_SCOPED_POLICY_SNAPSHOT_PROFILE_V2\",\"version\":2,\"capability\":\"6529STREAM_SCOPED_POLICY_SNAPSHOT_V2\",\"scope\":\"Complete positive canonical TOKEN, RELEASE or SEASON membership; no COLLECTION or VIEW reinterpretation\",\"sources\":\"Exact fixed dependencies and scoped-policy checkpoint/output profiles; actual factory runtime, canonical dependencies and current route authenticate the original complete inventory and every frozen policy\",\"entropy\":\"Original status1/2 terminal evidence remains distinct from actual status5 finalized seed; independent terminal program admission is retained by the complete output record\",\"authority\":\"SNAPSHOT and IDENTITY families each require original Metadata class7 collection or class8 global writer; neither grants Artist CONTENT_ROOT authority\",\"lineage\":\"Exact scope subject, next revision, predecessor and unique snapshotId; current reads reconstruct exact payload and revalidate the complete output/policy sources\",\"lock\":\"Exact governance class2 action and current head; immutable historical receipts/payload remain readable after source drift\",\"preservation\":\"Exact snapshot bytes are retained in the original Store; output manifest covers commitments rather than full rendered bytes\",\"bound\":\"Complete canonical payload at most524288 bytes; policyCount positive and at most630 before allocation\"}";
    bytes32 internal constant PROFILE_HASH = keccak256(bytes(PROFILE_DOCUMENT));
    uint256 internal constant PROFILE_BYTES = 1350;

    bytes32 internal constant CANON_ID = keccak256("STREAM_ABI_SCOPED_POLICY_SNAPSHOT_V2");
    string internal constant CANON_DOCUMENT =
        "{\"name\":\"STREAM_ABI_SCOPED_POLICY_SNAPSHOT_V2\",\"version\":2,\"encoding\":\"abi.encode(bytes32 domain,uint256 chainId,address snapshotHost,address[11] targets,bytes32[11] codeHashes,Publication publication,Receipt receipt,Source source)\",\"domain\":\"keccak256(6529STREAM_SCOPED_POLICY_SNAPSHOT_PAYLOAD_V2)\",\"normalization\":\"publication.expectedSourceHash=0; receipt.recordHash,chainHash,manifestHash,manifestBytes,recordedAt=0; receipt.sourceHash is the actual complete source hash; other fields retained exactly\",\"sourceHash\":\"keccak256(abi.encode(keccak256(6529STREAM_SCOPED_POLICY_SNAPSHOT_SOURCES_V2),chainId,snapshotHost,targets,codeHashes,source))\",\"bytes\":\"Canonical Solidity0.8.19 ABI; exact tuple re-encoding, array order and complete bytes; no alternate offsets or trailing bytes\",\"hash\":\"Keccak-256 of exact retained payload, not JSON canonicalization\",\"chunks\":\"Contiguous original8192-byte Store segments, final segment exact residual length; at most524288 bytes\"}";
    bytes32 internal constant CANON_HASH = keccak256(bytes(CANON_DOCUMENT));
    uint256 internal constant CANON_BYTES = 970;

    function document(bytes32 id) internal pure returns (bytes memory) {
        if (id == SCHEMA_ID) return bytes(SCHEMA_DOCUMENT);
        if (id == PROFILE_ID) return bytes(PROFILE_DOCUMENT);
        if (id == CANON_ID) return bytes(CANON_DOCUMENT);
        revert("unknown scoped policy snapshot document");
    }
}

