// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../metadata/StreamSchemaDocumentStore.sol";

/// @notice Exact immutable snapshot bytes in the existing permissionless chunk store.
/// @dev Uploading bytes confers no snapshot authority. The fixed host supplies its assembled
///      canonical payload; the caller cannot choose a different chunk inventory.
library StreamSnapshotManifestBytes {
    uint256 internal constant SEGMENT_BYTES = 8192;
    uint256 internal constant MAX_MANIFEST_BYTES = 524288;

    struct Manifest {
        bytes32 contentHash;
        uint32 byteLength;
        address[] pointers;
        bytes32[] chunkHashes;
    }

    error InvalidSnapshotManifest();
    error SnapshotChunkUnavailable(bytes32 chunkHash);
    error SnapshotChunkChanged(address pointer);

    function retain(Manifest storage saved, address store, bytes memory canonical)
        public
        returns (bytes32 hash)
    {
        return retainBounded(saved, store, canonical, MAX_MANIFEST_BYTES);
    }

    function retainBounded(
        Manifest storage saved,
        address store,
        bytes memory canonical,
        uint256 maximum
    ) public returns (bytes32 hash) {
        uint256 length = canonical.length;
        if (saved.byteLength != 0 || maximum > 3000000 || length == 0 || length > maximum) {
            revert InvalidSnapshotManifest();
        }
        hash = keccak256(canonical);
        for (uint256 offset; offset < length; offset += SEGMENT_BYTES) {
            uint256 size = length - offset;
            if (size > SEGMENT_BYTES) size = SEGMENT_BYTES;
            bytes32 chunkHash;
            assembly ("memory-safe") {
                chunkHash := keccak256(add(add(canonical, 32), offset), size)
            }
            (address pointer, uint32 storedLength) =
                StreamSchemaDocumentStore(store).chunk(chunkHash);
            if (pointer == address(0) || storedLength != size) {
                revert SnapshotChunkUnavailable(chunkHash);
            }
            _chunk(pointer, chunkHash, size);
            saved.pointers.push(pointer);
            saved.chunkHashes.push(chunkHash);
        }
        saved.contentHash = hash;
        saved.byteLength = uint32(length);
    }

    function read(Manifest storage saved) public view returns (bytes memory payload) {
        return readBounded(saved, MAX_MANIFEST_BYTES);
    }

    function readBounded(Manifest storage saved, uint256 maximum)
        public
        view
        returns (bytes memory payload)
    {
        uint256 length = saved.byteLength;
        uint256 count = saved.pointers.length;
        if (
            maximum > 3000000 || length == 0 || length > maximum || count != (length + 8191) / 8192
                || saved.chunkHashes.length != count
        ) revert InvalidSnapshotManifest();
        payload = new bytes(length);
        for (uint256 i; i < count; ++i) {
            uint256 offset = i * SEGMENT_BYTES;
            uint256 size = length - offset;
            if (size > SEGMENT_BYTES) size = SEGMENT_BYTES;
            address pointer = saved.pointers[i];
            _chunk(pointer, saved.chunkHashes[i], size);
            assembly ("memory-safe") {
                extcodecopy(pointer, add(add(payload, 32), offset), 1, size)
            }
        }
        if (keccak256(payload) != saved.contentHash) revert InvalidSnapshotManifest();
    }

    function requireIntact(Manifest storage saved) public view returns (bytes32) {
        return keccak256(read(saved));
    }

    function requireIntactBounded(Manifest storage saved, uint256 maximum)
        public
        view
        returns (bytes32)
    {
        return keccak256(readBounded(saved, maximum));
    }

    function _chunk(address pointer, bytes32 hash, uint256 length) private view {
        if (pointer.code.length != length + 1) revert SnapshotChunkChanged(pointer);
        bytes memory raw = new bytes(length + 1);
        assembly ("memory-safe") { extcodecopy(pointer, add(raw, 32), 0, add(length, 1)) }
        bytes32 actual;
        assembly ("memory-safe") { actual := keccak256(add(raw, 33), length) }
        if (raw[0] != 0 || actual != hash) revert SnapshotChunkChanged(pointer);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/metadata/StreamSnapshotTypes.sol";
import "../../interfaces/stream/finality/StreamFinalityCoordinatorPolicyTypes.sol";
import "./StreamRecordJson.sol";
import "./StreamSnapshotDefinitions.sol";

/// @notice Complete fixed-key canonical JSON for the native assembled source profile.
/// @dev Inputs are populated exclusively by the fixed host's actual source/policy readers.
///      Decimal strings preserve every uint256 value; source text is never normalized.
library StreamSnapshotManifestJson {
    function manifest(
        StreamSnapshotTypes.Dependencies memory d,
        StreamSnapshotTypes.NativeFacts memory n,
        StreamFinalityCoordinatorPolicyEvidence memory entropy,
        StreamSnapshotTypes.Publication memory p,
        StreamSnapshotTypes.Receipt memory r
    ) public pure returns (bytes memory raw) {
        string memory out = string.concat(
            '{"chainId":',
            StreamRecordJson.unsigned(d.chainId),
            ',"collectionId":',
            StreamRecordJson.unsigned(n.collectionId),
            ',"contentRoot":',
            _root(n),
            ',"dependencyReadProfile":',
            _hash(n.dependencyProfile),
            ',"entropy":',
            _entropy(entropy)
        );
        out = string.concat(
            out,
            ',"metadata":',
            _metadata(n),
            ',"profileHash":',
            _hash(StreamSnapshotDefinitions.PROFILE_HASH),
            ',"publication":',
            _publication(p, r),
            ',"renderer":',
            _renderer(n)
        );
        out = string.concat(
            out,
            ',"schemaHash":',
            _hash(StreamSnapshotDefinitions.SCHEMA_HASH),
            ',"schemaId":',
            _hash(StreamSnapshotDefinitions.SCHEMA_ID),
            ',"script":',
            _script(n)
        );
        out = string.concat(
            out, ',"sources":', _sources(d), ',"subject":', _hash(n.subject), ',"version":1}'
        );
        raw = bytes(out);
        if (raw.length == 0 || raw.length > 524288) revert StreamSnapshotTypes.SnapshotSource();
    }

    function _publication(
        StreamSnapshotTypes.Publication memory p,
        StreamSnapshotTypes.Receipt memory r
    ) internal pure returns (string memory) {
        string memory out = string.concat(
            '{"authorizationClass":',
            StreamRecordJson.unsigned(r.authorizationClass),
            ',"displayAuthorizationClass":',
            StreamRecordJson.unsigned(r.displayAuthorizationClass),
            ',"displayGrantRevision":',
            StreamRecordJson.unsigned(r.displayGrantRevision),
            ',"effectiveAt":',
            StreamRecordJson.unsigned(p.effectiveAt)
        );
        out = string.concat(
            out,
            ',"grantRevision":',
            StreamRecordJson.unsigned(r.grantRevision),
            ',"manifestURI":',
            StreamRecordJson.quote(p.manifestURI, 2048, true),
            ',"predecessor":',
            _hash(p.expectedHead),
            ',"publisher":',
            _account(r.publisher)
        );
        out = string.concat(
            out,
            ',"reasonHash":',
            _hash(p.reasonHash),
            ',"revision":',
            StreamRecordJson.unsigned(r.revision),
            ',"snapshotId":',
            _hash(p.snapshotId),
            "}"
        );
        return out;
    }

    function _metadata(StreamSnapshotTypes.NativeFacts memory n)
        internal
        pure
        returns (string memory)
    {
        return string.concat(
            '{"animationBaseURI":',
            StreamRecordJson.quote(n.source.animationBaseURI, 2048, true),
            ',"artist":',
            _artist(n.artist),
            ',"description":',
            StreamRecordJson.quote(n.source.description, 2048, true),
            ',"imageURI":',
            StreamRecordJson.quote(n.source.imageURI, 2048, true),
            ',"locks":{"artistIdentity":true,"baseURI":true,"dependencies":true,"displayMetadata":true,"media":true,"script":true}',
            ',"name":',
            StreamRecordJson.quote(n.source.name, 256, true),
            "}"
        );
    }

    function _artist(IStreamMetadataServingFacts.ArtistPresentation memory p)
        private
        pure
        returns (string memory)
    {
        string memory out = string.concat(
            '{"acceptanceRecordHash":',
            _hash(p.acceptanceRecordHash),
            ',"acceptedAt":',
            StreamRecordJson.unsigned(p.acceptedAt),
            ',"artistId":',
            _hash(p.artistId),
            ',"bindingGeneration":',
            StreamRecordJson.unsigned(p.bindingGeneration)
        );
        out = string.concat(
            out,
            ',"bindingHash":',
            _hash(p.bindingHash),
            ',"identityRecordHash":',
            _hash(p.identityRecordHash),
            ',"lockedAt":',
            StreamRecordJson.unsigned(p.lockedAt),
            ',"nominatedArtist":',
            _account(p.nominatedArtist)
        );
        out = string.concat(
            out,
            ',"registry":',
            _account(p.registry),
            ',"registryCodeHash":',
            _hash(p.registryCodeHash),
            ',"snapshotHash":',
            _hash(p.snapshotHash),
            "}"
        );
        return out;
    }

    function _script(StreamSnapshotTypes.NativeFacts memory n)
        private
        pure
        returns (string memory)
    {
        return string.concat(
            '{"byteLength":',
            StreamRecordJson.unsigned(bytes(n.source.script).length),
            ',"content":',
            StreamRecordJson.quote(n.source.script, 8192, false),
            ',"contentHash":',
            _hash(n.serving.scriptHash),
            ',"mode":"ONCHAIN"}'
        );
    }

    function _renderer(StreamSnapshotTypes.NativeFacts memory n)
        internal
        pure
        returns (string memory)
    {
        string memory out = string.concat(
            '{"address":',
            _account(n.serving.renderer),
            ',"context":',
            _hash(n.rendererContext),
            ',"presentationProfile":',
            _hash(n.presentationProfile),
            ',"routerManifestHash":',
            _hash(n.routerManifestHash)
        );
        out = string.concat(
            out,
            ',"routerVersion":',
            _hash(n.routerVersion),
            ',"runtimeHash":',
            _hash(n.serving.rendererCodeHash),
            "}"
        );
        return out;
    }

    function _root(StreamSnapshotTypes.NativeFacts memory n) internal pure returns (string memory) {
        IStreamContentRootPublication.Record memory r = n.contentRoot;
        string memory out = string.concat(
            '{"artistConsent":',
            _hash(r.artistConsent),
            ',"authorizationClass":',
            StreamRecordJson.unsigned(r.authorizationClass),
            ',"checkpoint":',
            _checkpoint(n),
            ',"contentRoot":',
            _hash(r.contentRoot)
        );
        out = string.concat(
            out,
            ',"grantRevision":',
            StreamRecordJson.unsigned(r.grantRevision),
            ',"leafCount":',
            StreamRecordJson.unsigned(r.leafCount),
            ',"leafManifest":',
            _leaves(n),
            ',"manifestHash":',
            _hash(r.manifestHash)
        );
        out = string.concat(
            out,
            ',"manifestURI":',
            StreamRecordJson.quote(r.publication.manifestURI, 2048, true),
            ',"predecessor":',
            _hash(r.publication.expectedPredecessor),
            ',"publishedAt":',
            StreamRecordJson.unsigned(r.publishedAt),
            ',"publisher":',
            _account(r.publisher)
        );
        out = string.concat(
            out,
            ',"recordHash":',
            _hash(n.contentRootRecordHash),
            ',"routeHash":',
            _hash(r.routeHash),
            ',"stateHash":',
            _hash(r.stateHash),
            "}"
        );
        return out;
    }

    function _checkpoint(StreamSnapshotTypes.NativeFacts memory n)
        private
        pure
        returns (string memory)
    {
        string memory out = string.concat(
            '{"contentRoot":',
            _hash(n.checkpoint.contentRoot),
            ',"inventoryHash":',
            _hash(n.checkpoint.inventoryHash),
            ',"leafChainHash":',
            _hash(n.checkpoint.leafChainHash),
            ',"planHash":',
            _hash(n.leafManifest.checkpointHash)
        );
        out = string.concat(
            out,
            ',"servingStateHash":',
            _hash(n.checkpoint.servingStateHash),
            ',"tokenCount":',
            StreamRecordJson.unsigned(n.checkpoint.tokenCount),
            "}"
        );
        return out;
    }

    function _leaves(StreamSnapshotTypes.NativeFacts memory n)
        private
        pure
        returns (string memory)
    {
        return string.concat(
            '{"artifactHash":',
            _hash(n.leafManifest.artifactHash),
            ',"byteLength":',
            StreamRecordJson.unsigned(n.leafManifest.byteLength),
            ',"coverageHash":',
            _hash(n.leafManifest.coverageHash),
            ',"recordHash":',
            _hash(n.contentRoot.publication.verifiedManifestRecordHash),
            "}"
        );
    }

    function _sources(StreamSnapshotTypes.Dependencies memory d)
        internal
        pure
        returns (string memory out)
    {
        out = "[";
        for (uint256 i; i < d.targets.length; ++i) {
            out = string.concat(
                out,
                i == 0 ? "" : ",",
                '{"address":',
                _account(d.targets[i]),
                ',"role":',
                StreamRecordJson.unsigned(i),
                ',"runtimeHash":',
                _hash(d.codeHashes[i]),
                "}"
            );
        }
        return string.concat(out, "]");
    }

    function _entropy(StreamFinalityCoordinatorPolicyEvidence memory e)
        internal
        pure
        returns (string memory)
    {
        if (!e.allFrozen || e.policyCount == 0 || e.policies.length != e.policyCount) {
            revert StreamSnapshotTypes.SnapshotSource();
        }
        string memory policies = "[";
        for (uint256 i; i < e.policies.length; ++i) {
            policies = string.concat(policies, i == 0 ? "" : ",", _policy(e.policies[i]));
            if (bytes(policies).length > 524288) revert StreamSnapshotTypes.SnapshotSource();
        }
        return string.concat(
            '{"allFrozen":true,"inventoryHash":',
            _hash(e.inventoryHash),
            ',"planId":',
            _hash(e.planId),
            ',"policies":',
            policies,
            '],"policyChainHash":',
            _hash(e.policyChainHash),
            ',"policyCount":',
            StreamRecordJson.unsigned(e.policyCount),
            "}"
        );
    }

    function _policy(StreamFinalityCoordinatorPolicy memory p)
        private
        pure
        returns (string memory)
    {
        if (!p.frozen) revert StreamSnapshotTypes.SnapshotSource();
        string memory out = string.concat(
            '{"componentDataHash":',
            _hash(p.componentDataHash),
            ',"coordinator":',
            _account(p.coordinator),
            ',"deploymentManifestHash":',
            _hash(p.deploymentManifestHash),
            ',"epoch":',
            StreamRecordJson.unsigned(p.epoch)
        );
        out = string.concat(
            out,
            ',"firstTokenIndex":',
            StreamRecordJson.unsigned(p.firstTokenIndex),
            ',"frozen":true',
            ',"indexedCodeHash":',
            _hash(p.indexedCodeHash),
            ',"moduleManifestHash":',
            _hash(p.moduleManifestHash),
            ',"moduleSchemaHash":'
        );
        out = string.concat(
            out,
            _hash(p.moduleSchemaHash),
            ',"moduleVersion":',
            _hash(p.moduleVersion),
            ',"policyHash":',
            _hash(p.policyHash),
            ',"provider":',
            _account(p.provider),
            ',"salt":'
        );
        out = string.concat(out, _hash(p.salt), "}");
        return out;
    }

    /// @dev Fixed widths are proven by the types, so no dynamic-byte hex indexing is needed.
    function hashJSON(bytes32 value) public pure returns (string memory) {
        return _hash(value);
    }

    function accountJSON(address value) public pure returns (string memory) {
        return _account(value);
    }

    function _hash(bytes32 value) internal pure returns (string memory) {
        return _quotedHex(value, 32);
    }

    function _account(address value) internal pure returns (string memory) {
        if (value == address(0)) revert StreamRecordJson.InvalidJsonWitness();
        return _quotedHex(bytes32(uint256(uint160(value)) << 96), 20);
    }

    function _quotedHex(bytes32 value, uint256 size) private pure returns (string memory result) {
        result = new string(size * 2 + 4);
        assembly ("memory-safe") {
            let start := add(result, 32)
            mstore8(start, 0x22)
            mstore8(add(start, 1), 0x30)
            mstore8(add(start, 2), 0x78)
            let alphabet := 0x3031323334353637383961626364656600000000000000000000000000000000
            let cursor := add(start, 3)
            let end := add(cursor, mul(size, 2))
            for { } lt(cursor, end) { cursor := add(cursor, 1) } {
                mstore8(cursor, byte(shr(252, value), alphabet))
                value := shl(4, value)
            }
            mstore8(end, 0x22)
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/metadata/StreamSnapshotTypes.sol";
import "../../interfaces/stream/metadata/IStreamCollectionMetadataV1.sol";
import "../../interfaces/stream/metadata/IStreamMetadataRouter.sol";
import "../../interfaces/stream/metadata/IStreamMetadataRouterBinding.sol";
import "../../interfaces/stream/metadata/IStreamMetadataRenderingProfile.sol";
import "../../interfaces/stream/core/IStreamCoreCollectionView.sol";
import "../metadata/StreamMetadataRecoveryRoutes.sol";
import "../metadata/StreamMetadataSubjects.sol";
import "../finality/StreamFinalityRouterEvidence.sol";
import "../finality/StreamContentRootSchemas.sol";

import { StreamChunkedContentEvidence } from "../finality/StreamChunkedContentEvidence.sol";
import {
    IStreamChunkedContentCheckpoint
} from "../../interfaces/stream/finality/IStreamChunkedContentCheckpoint.sol";

/// @notice Reconstructs the native source side of an assembled snapshot from fixed actual hosts.
/// @dev Exact configured script bytes are retained. The renderer's contract read-set profile
///      is not proof that arbitrary JavaScript has no web or execution-environment dependencies.
library StreamSnapshotSourceReads {
    bytes32 private constant PRESENTATION = keccak256("6529STREAM_ROUTER_STABLE_PRESENTATION_V1");

    function requireCurrent(StreamSnapshotTypes.Dependencies memory d, uint256 collectionId)
        public
        view
        returns (StreamSnapshotTypes.NativeFacts memory f)
    {
        return _current(d, collectionId, false);
    }

    function requireCurrentChunked(StreamSnapshotTypes.Dependencies memory d, uint256 collectionId)
        public
        view
        returns (StreamSnapshotTypes.NativeFacts memory f)
    {
        return _current(d, collectionId, true);
    }

    function _current(StreamSnapshotTypes.Dependencies memory d, uint256 collectionId, bool chunked)
        private
        view
        returns (StreamSnapshotTypes.NativeFacts memory f)
    {
        bindings(d);
        if (
            collectionId == 0
                || _word(
                        d,
                        d.targets[0],
                        abi.encodeCall(IStreamCoreCollectionView.collectionExists, (collectionId))
                    ) != bytes32(uint256(1))
        ) {
            revert StreamSnapshotTypes.SnapshotSource();
        }
        f.collectionId = collectionId;
        f.subject = StreamMetadataSubjects.scopeSubject(
            d.chainId,
            d.targets[0],
            StreamFinalityScope(StreamFinalityScopeType.COLLECTION, collectionId, 0, 0)
        );
        bytes memory raw = StreamFinalityRouterEvidence.dynamicRead(
            d.targets[4],
            abi.encodeCall(IStreamMetadataServingFacts.collectionServingSource, (collectionId)),
            14976,
            d.sourceGas
        );
        f.source = abi.decode(raw, (IStreamMetadataServingFacts.ServingSource));
        _canonical(d.targets[4], raw, abi.encode(f.source));
        if (
            bytes(f.source.name).length > 256 || bytes(f.source.description).length > 2048
                || bytes(f.source.imageURI).length > 2048
                || bytes(f.source.animationBaseURI).length > 2048
                || (chunked
                        ? bytes(f.source.script).length != 0
                        : (bytes(f.source.script).length == 0
                            || bytes(f.source.script).length > 8192))
        ) {
            revert StreamSnapshotTypes.SnapshotSource();
        }
        raw = _read(
            d.targets[4],
            abi.encodeCall(IStreamMetadataServingFacts.collectionServingFacts, (collectionId)),
            512,
            d.sourceGas
        );
        f.serving = abi.decode(raw, (IStreamMetadataServingFacts.ServingFacts));
        _canonical(d.targets[4], raw, abi.encode(f.serving));
        if (
            !f.serving.configured
                || f.serving.presentationProfile
                    != (chunked ? StreamChunkedContentEvidence.PROFILE : PRESENTATION)
                || f.serving.mode != keccak256("ONCHAIN") || !f.serving.scriptLocked
                || !f.serving.mediaLocked || !f.serving.baseURILocked
                || !f.serving.dependenciesLocked || !f.serving.artistIdentityLocked
                || !f.serving.displayMetadataLocked
                || (!chunked
                    && (f.serving.scriptHash != keccak256(bytes(f.source.script))
                        || f.serving.scriptBytes != bytes(f.source.script).length))
                || f.serving.imageURIHash != keccak256(bytes(f.source.imageURI))
                || f.serving.animationBaseURIHash != keccak256(bytes(f.source.animationBaseURI))
        ) {
            revert StreamSnapshotTypes.SnapshotSource();
        }
        _pin(f.serving.renderer, f.serving.rendererCodeHash);
        f.serving.coreFrozen = false;
        raw = _read(
            d.targets[4],
            abi.encodeCall(IStreamMetadataServingFacts.artistPresentation, (collectionId)),
            384,
            d.readGas
        );
        f.artist = abi.decode(raw, (IStreamMetadataServingFacts.ArtistPresentation));
        _canonical(d.targets[4], raw, abi.encode(f.artist));
        if (
            !f.artist.locked || f.artist.registry == address(0) || f.artist.registryCodeHash == 0
                || f.artist.artistId == 0 || f.artist.bindingGeneration == 0
                || f.artist.bindingHash == 0 || f.artist.nominatedArtist == address(0)
                || f.artist.identityRecordHash == 0 || f.artist.acceptanceRecordHash == 0
                || f.artist.acceptedAt == 0 || f.artist.lockedAt == 0 || f.artist.snapshotHash == 0
        ) {
            revert StreamSnapshotTypes.SnapshotSource();
        }
        if (chunked) {
            StreamChunkedContentEvidence.Evidence memory e = StreamChunkedContentEvidence.source(
                d.targets[0], d.targets[4], d.chainId, collectionId, f.serving, d.sourceGas, true
            );
            if (e.selection.host != d.targets[1] || e.selection.codeHash != d.codeHashes[1]) {
                revert StreamSnapshotTypes.SnapshotSource();
            }
            f.presentationProfile = StreamChunkedContentEvidence.PROFILE;
            (f.rendererContext, f.dependencyProfile) =
                StreamChunkedContentEvidence.renderer(f.serving, d.readGas);
        } else {
            (f.presentationProfile, f.rendererContext, f.dependencyProfile) = abi.decode(
                _read(
                    d.targets[4],
                    abi.encodeCall(IStreamMetadataRenderingProfile.renderingProfile, ()),
                    96,
                    d.readGas
                ),
                (bytes32, bytes32, bytes32)
            );
            if (
                f.presentationProfile != PRESENTATION
                    || f.rendererContext != keccak256("6529STREAM_METADATA_TOKEN_RENDER_CONTEXT_V1")
                    || f.dependencyProfile
                        != keccak256("6529STREAM_METADATA_RENDER_NO_EXTERNAL_READS_V1")
            ) {
                revert StreamSnapshotTypes.SnapshotSource();
            }
        }
        (f.routerVersion, f.routerManifestHash) =
            StreamFinalityRouterEvidence.moduleIdentity(d.targets[4], d.sourceGas);
        _content(d, f);
        if (
            chunked
                && _word(
                        d,
                        d.targets[6],
                        abi.encodeCall(
                            IStreamChunkedContentCheckpoint.checkpointProfile,
                            (f.leafManifest.checkpointHash)
                        )
                    ) != keccak256("6529STREAM_CONTENT_CHUNKED_ONCHAIN_V1")
        ) revert StreamSnapshotTypes.SnapshotSource();
    }

    function bindings(StreamSnapshotTypes.Dependencies memory d) public view {
        if (
            d.chainId != block.chainid || d.readGas < 50000 || d.sourceGas < d.readGas
                || d.evidenceGas < d.readGas || d.inventoryGas < d.readGas
        ) {
            revert StreamSnapshotTypes.SnapshotConfiguration();
        }
        for (uint256 i; i < d.targets.length; ++i) {
            _pin(d.targets[i], d.codeHashes[i]);
        }
        StreamMetadataRecoveryRoutes.requireCurrentHost(
            d.targets[0],
            keccak256("COLLECTION_METADATA"),
            d.targets[1],
            keccak256("COLLECTION_METADATA"),
            type(IStreamCollectionMetadataV1).interfaceId
        );
        StreamMetadataRecoveryRoutes.requireCurrentHost(
            d.targets[0],
            keccak256("METADATA_ROUTER"),
            d.targets[4],
            keccak256("METADATA_ROUTER"),
            type(IStreamMetadataRouter).interfaceId
        );
        _address(d, d.targets[1], "core()", d.targets[0]);
        _address(d, d.targets[1], "schemaRegistry()", d.targets[2]);
        _address(d, d.targets[1], "chunkStore()", d.targets[3]);
        _address(d, d.targets[2], "chunkStore()", d.targets[3]);
        _address(d, d.targets[4], "core()", d.targets[0]);
        _address(d, d.targets[5], "core()", d.targets[0]);
        _address(d, d.targets[5], "contentCheckpoint()", d.targets[6]);
        _address(d, d.targets[6], "core()", d.targets[0]);
        _address(d, d.targets[6], "metadataRouter()", d.targets[4]);
        if (
            _word(d, d.targets[1], abi.encodeWithSignature("coreCodeHash()")) != d.codeHashes[0]
                || _word(d, d.targets[1], abi.encodeWithSignature("schemaRegistryCodeHash()"))
                    != d.codeHashes[2]
                || _word(d, d.targets[1], abi.encodeWithSignature("chunkStoreCodeHash()"))
                    != d.codeHashes[3]
        ) {
            revert StreamSnapshotTypes.SnapshotConfiguration();
        }
    }

    function _content(
        StreamSnapshotTypes.Dependencies memory d,
        StreamSnapshotTypes.NativeFacts memory f
    ) private view {
        f.contentRootRecordHash = _word(
            d,
            d.targets[4],
            abi.encodeCall(
                IStreamContentRootPublication.collectionContentRootHead, (f.collectionId)
            )
        );
        if (f.contentRootRecordHash == 0) revert StreamSnapshotTypes.SnapshotSource();
        bytes memory raw = StreamFinalityRouterEvidence.dynamicRead(
            d.targets[4],
            abi.encodeCall(
                IStreamContentRootPublication.contentRootRecord, (f.contentRootRecordHash)
            ),
            4096,
            d.evidenceGas
        );
        f.contentRoot = abi.decode(raw, (IStreamContentRootPublication.Record));
        _canonical(d.targets[4], raw, abi.encode(f.contentRoot));
        if (
            f.contentRoot.publication.collectionId != f.collectionId
                || f.contentRoot.artistId != f.artist.artistId
                || f.contentRoot.bindingGeneration != f.artist.bindingGeneration
                || f.contentRoot.bindingHash != f.artist.bindingHash
                || f.contentRoot.artistConsent == 0 || f.contentRoot.publisher == address(0)
                || f.contentRoot.grantRevision == 0
                || (f.contentRoot.authorizationClass != 7 && f.contentRoot.authorizationClass != 8)
                || f.contentRoot.publishedAt == 0 || f.contentRoot.stateHash == 0
                || f.contentRoot.routeHash == 0 || f.contentRoot.contentRoot == 0
                || f.contentRoot.leafCount == 0 || f.contentRoot.manifestHash == 0
                || bytes(f.contentRoot.publication.manifestURI).length > 2048
                || keccak256(
                        abi.encode(
                            keccak256("6529STREAM_CONTENT_ROOT_RECORD_V1"),
                            d.chainId,
                            d.targets[4],
                            f.contentRoot
                        )
                    ) != f.contentRootRecordHash
        ) {
            revert StreamSnapshotTypes.SnapshotSource();
        }
        raw = _read(
            d.targets[5],
            abi.encodeCall(
                IStreamContentLeafManifest.requireCurrentManifest,
                (f.contentRoot.publication.verifiedManifestRecordHash, f.artist.artistId)
            ),
            288,
            d.evidenceGas
        );
        f.leafManifest = abi.decode(raw, (IStreamContentLeafManifest.Manifest));
        _canonical(d.targets[5], raw, abi.encode(f.leafManifest));
        if (
            f.leafManifest.collectionId != f.collectionId
                || f.leafManifest.artistId != f.artist.artistId
                || f.leafManifest.contentRoot != f.contentRoot.contentRoot
                || f.leafManifest.tokenCount != f.contentRoot.leafCount
                || f.leafManifest.manifestHash != f.contentRoot.manifestHash
                || f.leafManifest.artifactHash == 0 || f.leafManifest.coverageHash == 0
                || f.leafManifest.byteLength == 0 || f.leafManifest.checkpointHash == 0
        ) {
            revert StreamSnapshotTypes.SnapshotSource();
        }
        bytes32 coverageWord = _word(d, d.targets[5], abi.encodeWithSignature("artifactCoverage()"));
        if (uint256(coverageWord) > type(uint160).max || coverageWord == 0) {
            revert StreamSnapshotTypes.SnapshotSource();
        }
        address coverage = address(uint160(uint256(coverageWord)));
        _pin(coverage, _word(d, d.targets[5], abi.encodeWithSignature("coverageCodeHash()")));
        bytes32 leafPlan = keccak256(
            abi.encode(
                keccak256("6529STREAM_CONTENT_LEAF_MANIFEST_PLAN_V1"),
                d.chainId,
                d.targets[5],
                d.targets[0],
                d.targets[6],
                coverage,
                f.leafManifest
            )
        );
        if (
            keccak256(
                    abi.encode(keccak256("6529STREAM_CONTENT_LEAF_MANIFEST_VERIFIED_V1"), leafPlan)
                ) != f.contentRoot.publication.verifiedManifestRecordHash
        ) {
            revert StreamSnapshotTypes.SnapshotSource();
        }
        raw = _read(
            d.targets[6],
            abi.encodeCall(
                IStreamOnchainContentCheckpoint.requireCurrentCheckpoint,
                (f.leafManifest.checkpointHash)
            ),
            224,
            d.evidenceGas
        );
        f.checkpoint = abi.decode(raw, (IStreamOnchainContentCheckpoint.Plan));
        _canonical(d.targets[6], raw, abi.encode(f.checkpoint));
        if (
            f.checkpoint.collectionId != f.collectionId
                || f.checkpoint.tokenCount != f.leafManifest.tokenCount
                || f.checkpoint.nextIndex != f.checkpoint.tokenCount
                || f.checkpoint.inventoryHash == 0 || f.checkpoint.servingStateHash == 0
                || f.checkpoint.leafChainHash == 0
                || f.checkpoint.contentRoot != f.contentRoot.contentRoot
        ) {
            revert StreamSnapshotTypes.SnapshotSource();
        }
    }

    function _pin(address target, bytes32 hash) private view {
        if (target.code.length == 0 || hash == 0 || target.codehash != hash) {
            revert StreamSnapshotTypes.SnapshotDependency(target);
        }
    }

    function _address(
        StreamSnapshotTypes.Dependencies memory d,
        address target,
        string memory getter,
        address expected
    ) private view {
        if (
            _word(d, target, abi.encodeWithSignature(getter)) != bytes32(uint256(uint160(expected)))
        ) {
            revert StreamSnapshotTypes.SnapshotDependency(target);
        }
    }

    function _word(StreamSnapshotTypes.Dependencies memory d, address target, bytes memory input)
        private
        view
        returns (bytes32)
    {
        return abi.decode(_read(target, input, 32, d.readGas), (bytes32));
    }

    function _read(address target, bytes memory input, uint256 length, uint256 cap)
        private
        view
        returns (bytes memory)
    {
        return StreamFinalityRouterEvidence.read(target, input, length, cap);
    }

    function _canonical(address target, bytes memory raw, bytes memory encoded) private pure {
        if (keccak256(raw) != keccak256(encoded)) {
            revert StreamSnapshotTypes.SnapshotDependency(target);
        }
    }
}

