// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamArtworkFinalityTypes.sol";

/// @notice Preparation read implemented by the actual selected recovery companion.
/// @dev This is a caller subset, not a replacement for the companion's primary module interface.
interface IStreamArtistRecoveryIntent {
    struct Facts {
        bytes32 scopeHash;
        bytes32 oldValueHash;
        bytes32 newValueHash;
        bytes32 requestHash;
    }

    function core() external view returns (address);
    function originalFinalityRegistry() external view returns (address);

    /// @notice Validate actual staged canonical intent, original finality and current route lineage.
    /// @dev All four results are derived from that exact stored request, never caller assertions.
    ///      The returned request commitment excludes artist/owner evidence heads, avoiding a cycle
    ///      with approval or finding records subsequently created for this exact recovery action.
    ///      Reverts for missing bytes, malformed/unsupported scope, drift or any mismatched hash.
    function requireArtistRecoveryIntent(
        StreamFinalityScope calldata scope,
        bytes32 originalFinalityRecordHash,
        bytes32 recoveryManifestHash
    ) external view returns (Facts memory);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @notice Exact immutable byte identity produced from a recorded sanction and its retained evidence.
interface IStreamArtistSanctionArchiveFacts {
    struct Facts {
        bytes32 sanctionRecordHash;
        bytes32 artistId;
        bytes32 schemaId;
        bytes32 canonicalizationId;
        bytes32 contentHash;
        uint64 byteLength;
    }

    /// @dev This historical read does not grant current authority or assert present archival health.
    ///      Unknown records revert. Finality separately verifies the saved sanction for its current subject.
    function sanctionArchiveFacts(bytes32 sanctionRecordHash) external view returns (Facts memory);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamArtworkFinalityTypes.sol";
import "./StreamArtistSanctionPreparationTypes.sol";

/// @notice Validates the exact non-sanction candidate before an artist signature exists.
interface IStreamArtistSanctionPreparation {
    /// @notice Validates the actual scope, current pins, mandatory frozen non-sanction components,
    ///         authoritative discovery, complete scope evidence and independent stored manifest.
    /// @dev Callable outside an executing governance action. The ordered input excludes every
    ///      ARTIST_SANCTION entry and PLATFORM_WORKS_DECLARATION: this is an artist-bound profile.
    ///      No placeholder sanction record or caller-selected readiness value is admitted.
    ///      Finalization revalidates these facts and the actual separately recorded sanction.
    function prepareSanction(
        StreamFinalityScope calldata scope,
        StreamFinalityComponentExpectation[] calldata nonSanctionComponents,
        StreamFinalityManifestRef calldata manifest
    ) external view returns (StreamArtistSanctionPreparation memory);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "./IStreamArtistSanctionPreparation.sol";
import "./IStreamFinalitySanctionReview.sol";

/// @notice Complete current artist candidate and its original image facts in one preparation.
/// @dev Same scope, component, manifest and current-source gates as prepareSanction.
/// Finalization still independently revalidates its own current inputs and original sanction.
interface IStreamArtistSanctionReviewPreparation {
    function prepareSanctionWithReview(
        StreamFinalityScope calldata scope,
        StreamFinalityComponentExpectation[] calldata nonSanctionComponents,
        StreamFinalityManifestRef calldata manifest
    )
        external
        view
        returns (
            StreamArtistSanctionPreparation memory prepared,
            IStreamFinalitySanctionReview.ReviewFacts memory review
        );
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamArtworkFinalityTypes.sol";

/// @notice Finality read surface every participating satellite exposes ([LTA-FINALITY]).
/// @dev Interface names carry the `Artwork` infix so this wave never collides with sibling
///      worktrees; function selectors follow the spec code blocks exactly.
interface IStreamArtworkFinalityComponent {
    /// @notice Reports the component's collection-scope finality state.
    function finalityState(uint256 collectionId)
        external
        view
        returns (StreamFinalityComponentState memory);
}

/// @notice Scoped finality read surface (Scoped Finality For Open Series).
interface IStreamArtworkScopedFinalityComponent {
    /// @notice Reports the component's finality state for one scope.
    function finalityStateForScope(StreamFinalityScope calldata scope)
        external
        view
        returns (StreamFinalityComponentState memory);
}

/// @notice Collection-scope component discovery, implemented by the metadata router
///         ([LTA-FINALITY] component discovery path).
interface IStreamArtworkFinalityDiscovery {
    function finalityComponentCount(uint256 collectionId) external view returns (uint256);

    function finalityComponentAt(uint256 collectionId, uint256 index)
        external
        view
        returns (StreamFinalityComponentExpectation memory);

    function finalityDiscoveryHash(uint256 collectionId) external view returns (bytes32);
}

/// @notice Scoped component discovery (Scoped Finality For Open Series).
interface IStreamArtworkScopedFinalityDiscovery {
    function finalityComponentCountForScope(StreamFinalityScope calldata scope)
        external
        view
        returns (uint256);

    function finalityComponentAtForScope(StreamFinalityScope calldata scope, uint256 index)
        external
        view
        returns (StreamFinalityComponentExpectation memory);

    function finalityDiscoveryHashForScope(StreamFinalityScope calldata scope)
        external
        view
        returns (bytes32);
}

/// @notice Frozen-route compatibility read keyed by full scope identity
///         (Scoped Finality For Open Series, scope rule 5).
interface IStreamArtworkScopedFrozenRouteRegistry {
    /// @notice Returns the module pinned for `routeType` by the scope's executed finality.
    /// @dev `routeHash` is `keccak256(abi.encode(expectation))` over the stored
    ///      `StreamFinalityComponentExpectation` — a registry-local convention until the
    ///      event catalog pins a route preimage.
    function frozenRouteForScope(bytes32 routeType, StreamFinalityScope calldata scope)
        external
        view
        returns (bool pinned, address module, bytes32 routeHash, bytes32 finalityRecordHash);
}

