struct StreamFinalityRecoveryEvidenceSnapshot {
    StreamFinalityRecoveryArtistEvidenceKind artistEvidenceKind;
    bytes32 artistEvidenceHash;
    address artistSigner;
    bytes32 artistId;
    uint8 artistAuthorityClass;
    uint64 artistNoticeEndsAt;
    bytes32 ownerEvidenceHash;
    uint64 ownerEvidenceRevision;
    uint64 ownerNoticeEndsAt;
    uint32 ownerAcknowledgementCount;
    uint32 ownerObjectionCount;
}

/// @notice Immutable facts of one executed canonical Governance action.
struct StreamFinalityRecoveryRecord {
    bool executed;
    bytes32 recoveryId;
    StreamFinalityScope scope;
    bytes32 originalFinalityRecordHash;
    bytes32 predecessorRecoveryId;
    uint64 generation;
    bytes32 oldRouteHash;
    bytes32 recoveryRouteHash;
    bool artworkBytesChanged;
    StreamFinalityComponentExpectation replacementRoute;
    StreamFinalityManifestRef recoveryManifest;
    StreamFinalityRecoveryEvidenceSnapshot evidence;
    bytes32 reasonHash;
    string reasonURI;
    uint64 executedAt;
}

struct StreamFinalityRecoveryRefreshPlan {
    bool exists;
    bool complete;
    bool superseded;
    bytes32 manifestContentHash;
    bytes32 supersededByRecoveryId;
    uint256 lastAllocatedTokenIdAtExecution;
    uint256 rangeStart;
    uint256 rangeEnd;
    uint256 processedThrough;
    uint256 chunksEmitted;
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @notice Original observed-reference evidence and separate current local lock status.
/// @dev Exact full original payload/coverage validation belongs to the pinned publication host.
///      A passing read does not prove arbitrary JavaScript classification or archive cadence.
struct StreamFinalityReferenceEvidence {
    bytes32 inputHash;
    bytes32 recordHash;
    bytes32 payloadHash;
    bytes32 sourcesHash;
    bytes32 snapshotRecordHash;
    uint64 snapshotRevision;
    uint64 revision;
    uint32 payloadBytes;
    address recorder;
    uint8 authorizationClass;
    uint64 grantRevision;
    uint64 recordedAt;
    bytes32 schemaHash;
    bytes32 profileHash;
    bytes32 canonicalizationHash;
    bool locked;
    bytes32 lockHash;
    bytes32 componentDataHash;
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @notice Exact immutable archival evidence selected by a canonical finality action.
/// @dev Completion identifies original whole-artifact coverage. Execution separately validates
///      current coverage; no mutable newest-proof or validation-cache head selects the action.
struct StreamFinalitySanctionArchiveProof {
    bytes32 sanctionRecordHash;
    bytes32 artifactHash;
    bytes32 completionHash;
}

/// @notice Executed proof selection, separate from permanent signed finality record preimages.
struct StreamFinalitySanctionArchiveWitness {
    bytes32 evidenceHash;
    StreamFinalitySanctionArchiveProof proof;
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

struct StreamFinalitySnapshotEvidence {
    bytes32 inputHash;
    bytes32 recordHash;
    bytes32 manifestHash;
    bytes32 sourceHash;
    bytes32 inventoryPlan;
    bytes32 schemaHash;
    bytes32 profileHash;
    bytes32 canonicalizationHash;
    uint64 revision;
    uint32 manifestBytes;
    address publisher;
    uint8 snapshotAuthorizationClass;
    uint64 snapshotGrantRevision;
    uint8 displayAuthorizationClass;
    uint64 displayGrantRevision;
    bool locked;
    bytes32 lockEvidenceHash;
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @notice Exact fields of the versioned, flat ABI scope-membership manifest.
/// @dev scopeId is derived from the authenticated Metadata record hash after publication.
struct StreamScopeMembershipManifest {
    uint16 version;
    uint256 chainId;
    address core;
    uint256 collectionId;
    uint8 scopeType;
    uint256 tokenCount;
    bytes32 tokenListHash;
    bytes32[] chunkHashes;
}

/// @notice Eight static words shared by authoritative scope consumers.
/// @dev COLLECTION uses the current complete inventory prefix and zero record/manifest/list
///      hashes. TOKEN has one member and no manifest/record/inventory-prefix fields. Scoped
///      published subsets keep zero inventory-prefix fields so later parent mints cannot
///      change their immutable membership commitment. These facts are not finality readiness.
struct StreamScopeMembershipFacts {
    bytes32 scopeSubject;
    bytes32 scopeManifestHash;
    bytes32 sourceRecordHash;
    uint256 tokenCount;
    bytes32 tokenListHash;
    bytes32 membershipHash;
    uint256 inventoryCount;
    bytes32 inventoryPrefixHash;
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamArtworkFinalityTypes.sol";
import "./StreamFinalityEvidenceTypes.sol";

/// @notice Exact TOKEN/RELEASE/SEASON finality manifest with full original scoped identities.
/// @dev The provider derives every value from its fixed live graph. Supplying this tuple is
/// not authority or readiness. The original sanction and this document's own hash are excluded.
library StreamScopedFinalityInputManifestTypes {
    struct Statement {
        StreamFinalityScope scope;
        bytes32 coreFactsHash;
        bytes32 contentRoot;
        uint64 leafCount;
        bytes32 contentRootSchemaId;
        bytes32 snapshotManifestHash;
        bytes32 referenceRenderManifestHash;
        StreamFinalityScopeInputs inputs;
        StreamFinalityComponentExpectation[] nonSanctionComponents;
        // This native artist-bound scoped profile admits only each named policy.
        uint8 entropyPolicy; // 1 = every member terminal; no deferred entropy exception.
        uint8 postFreezePolicy; // 1 = no artwork-byte mutation exception.
        uint8 sanctionPolicy; // 1 = actual artist sanction and archive checked separately.
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import { StreamFinalityScope } from "./StreamArtworkFinalityTypes.sol";
import {
    StreamRenderCriticalSourceTypes as Inventory
} from "../preservation/StreamRenderCriticalSourceTypes.sol";
import { IStreamGasParameterHost as Gas } from "../parameters/IStreamGasParameterHost.sol";

/// @notice Constructor-fixed deployment recipe; no caller-selected evidence hosts.
library StreamScopedPolicyPublicationGraphTypesV2 {
    bytes32 internal constant PROFILE =
        keccak256("6529STREAM_SCOPED_POLICY_PUBLICATION_FACTORY_V2");

    struct Recipe {
        // Original twelve-role roster. Slots 5 and 6 and their hashes MUST be zero;
        // the factory fills them with its genuine snapshot and reference children.
        Inventory.Dependencies inventory;
        // Membership, STATIC selection, scoped policy source factory, Governance executor.
        address[4] targets;
        bytes32[4] codeHashes;
        uint32 readinessReadGas;
        uint32 readinessSourceGas;
        uint256 factorySourceGas;
        uint256 bundleReadGas;
        uint256 bundleArchiveGas;
        Gas.GasParameterConfig[2] checkpointGas;
        Gas.GasParameterConfig outputGas;
        Gas.GasParameterConfig[3] snapshotGas;
        Gas.GasParameterConfig[4] referenceGas;
    }

    struct Graph {
        StreamFinalityScope scope;
        bytes32 inventoryPlan;
        address sourceSet;
        bytes32 sourceSetCodeHash;
        bytes32 graphId;
        // Readiness, checkpoint, output, snapshot, reference, inventory, bundle.
        address[7] children;
        bytes32[7] codeHashes;
        uint8 preparedChildren;
    }
    error PublicationRecipeInvalid();
    error PublicationGraphDependency(address target);
    error PublicationGraphIncomplete(bytes32 graphId);
    error PublicationGraphChanged(bytes32 graphId);
}

